begin;
    with j as (select * from jsonb_to_recordset($law7v024$[{"code_id":"NK_RF","article_number":"7","version_date":"2000-07-31","article_text":"Лицом, имеющим фактическое право на доходы, в целях настоящего Кодекса также признается лицо (иностранная структура без образования юридического лица), в интересах которого иное лицо (иная иностранная структура без образования юридического лица) правомочно распоряжаться доходом, полученным организацией (иностранной структурой без образования юридического лица), указанной в абзаце первом настоящего пункта, или непосредственно таким иным лицом (иной иностранной структурой без образования юридического лица).\n\nПри определении лица, имеющего фактическое право на доходы, учитываются функции, выполняемые лицами, указанными в настоящем пункте (иностранными структурами без образования юридического лица), а также принимаемые ими риски. При этом наличие фактического права на доходы определяется применительно к каждой отдельной выплате дохода в виде дивидендов и (или) к группе выплат дохода в рамках одного договора. (В редакции Федерального закона от 27.11.2018 № 424-ФЗ)\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n1) в случае, если лицо, имеющее фактическое право на выплачиваемые доходы (их часть), признается в соответствии с настоящим Кодексом налоговым резидентом Российской Федерации, налогообложение выплачиваемого дохода (его части) производится в соответствии с положениями соответствующих глав части второй настоящего Кодекса для налогоплательщиков, являющихся налоговыми резидентами Российской Федерации, без удержания соответствующего налога в отношении выплачиваемых доходов (их части) у источника выплаты при условии информирования налогового органа по месту постановки на учет организации - источника выплаты доходов в порядке, устанавливаемом федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов;\n\n2) в случае, если лицо, имеющее фактическое право на выплачиваемые доходы (их часть), является иностранным лицом, на которое распространяется действие международного договора Российской Федерации по вопросам налогообложения, положения указанного международного договора Российской Федерации применяются в отношении лица, которое имеет фактическое право на выплачиваемые доходы (их часть) в соответствии с порядком, предусмотренным ме\n\nждународным договором Российской Федерации;\n\n3) в случае, если лицо, имеющее фактическое право на выплачиваемые доходы (их часть), является иностранным лицом, на которое не распространяется действие международного договора Российской Федерации по вопросам налогообложения, налогообложение выплачиваемого дохода (его части) производится в соответствии с положениями соответствующих глав части второй настоящего Кодекса. (Дополнение подпунктом - Федеральный закон от 27.11.2018 № 424-ФЗ)\n\n(Статья в редакции Федерального закона от 24.11.2014 № 376-ФЗ)","article_title":"Статья 7. Международные договоры по вопросам налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"92df1683b8801e8137502358c56e3422ad815515295bfffbfedb81d172953e55"},{"code_id":"NK_RF","article_number":"70","version_date":"2000-07-31","article_text":"(Статья в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)","article_title":"Статья 70. Сроки направления требования об уплате задолженности","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"72d589278950508aa45731c7f3970dd158a1f96440114ce1054aa0314e45ba54"},{"code_id":"NK_RF","article_number":"71","version_date":"2000-07-31","article_text":"(Статья утратила силу  - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\n(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)","article_title":"Статья 71. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5fcb4ee6466ef86651b2fcc6c26fb3453d0d9a72209cc78b369c7ab236db31ee"},{"code_id":"NK_RF","article_number":"72","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nАбзац. (Утратил силу - Таможенный кодекс Российской Федерации от 28.05.2003 № 61-ФЗ)\n\nСведения, предусмотренные настоящим пунктом, размещаются в течение трех дней со дня принятия соответствующего решения налогового органа, но не ранее вступления в силу решения о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения, исполнение которого обеспечено запретом на отчуждение (передачу в залог) имущества налогоплательщика без согласия налогового органа в соответствии с пунктом 10 статьи 101 настоящего Кодекса.\n\nСостав размещаемых сведений и порядок их размещения утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)","article_title":"Статья 72. Способы обеспечения исполнения обязанности по уплате налогов, сборов, страховых взносов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4d01417a99542b0bf0e116e3f8fd17503816034176faff79a015bfcc97b1a78b"},{"code_id":"NK_RF","article_number":"73","version_date":"2000-07-31","article_text":"При оформлении договора залога залогодателем может быть как сам налогоплательщик, плательщик сбора или плательщик страховых взносов, так и третье лицо.\n\nФорма договора залога утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Пункт в редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nого обеспечено запретом на отчуждение (передачу в залог) имущества налогоплательщика (плательщика сбора, плательщика страховых взносов, налогового агента) без согласия налогового органа, имущество, в отношении которого применен указанный в настоящем пункте способ обеспечения исполнения обязанности по уплате налогов (сборов, страховых взносов) или принята обеспечительная мера, признается находящимся в залоге у налогового органа на основании закона. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nЗалог, возникающий в соответствии с настоящим пунктом в отношении имущества, находящегося в залоге у третьих лиц, признается последующим залогом.\n\nЗалог в соответствии с настоящим пунктом не возникает в отношении имущества, находящегося к моменту наступления указанных в настоящем Кодексе обстоятельств, влекущих возникновение залога, в залоге у третьих лиц, если по правилам гражданского законодательства Российской Федерации передача такого имущества в последующий залог не допускается.\n\nВ случае возникновения залога у налогового органа на основании закона предусмотренные гражданским законодательством Российской Федерации последствия залога не распространяются на денежные средства на счетах, вкладах (депозитах), предназначенные для удовлетворения требований в соответствии с гражданским законодательством Российской Федерации, которые предшествуют исполнению обязанности по уплате налогов (сборов, страховых взносов).\n\nЗалог, возникающий в соответствии с настоящим пунктом, подлежит государственной регистрации и учету в соответствии с правилами, предусмотренными гражданским законодательством Российской Федерации.\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nПредметом залога по договору между налоговым органом и залогодателем не может быть предмет залога по другому договору.","article_title":"Статья 73. Залог имущества","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2d5e82eb30d08e388443d88236d16bb1dccbeea23c1072ed8ba608a547ce4568"},{"code_id":"NK_RF","article_number":"74","version_date":"2000-07-31","article_text":"Поручительство оформляется в соответствии с гражданским законодательством Российской Федерации договором между налоговым органом и поручителем по форме, утверждаемой федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\nВ случае неуплаты или неполной уплаты в установленный срок налога, обязанность по уплате которого обеспечена поручительством, налоговый орган в течение тридцати дней со дня возникновения задолженности в связи с неисполнением такой обязанности направляет поручителю требование об уплате денежной суммы по договору поручительства. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nНалоговый орган применяет меры по взысканию с поручителя сумм, обязанность по уплате которых обеспечена поручительством, в порядке и сроки, которые предусмотрены статьями 46 - 48 настоящего Кодекса, в случае неисполнения им в установленный срок требования об уплате денежной суммы по договору поручительства.\n\n(Пункт в редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\n(Пункт 6 исключен  - Федеральный закон от 09.07.1999 № 154-ФЗ)","article_title":"Статья 74. Поручительство","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"30eb7519c2b80b30707c5c230f6b4c19d306af2e75c1fe4deba56685a604452d"},{"code_id":"NK_RF","article_number":"74.1","version_date":"2000-07-31","article_text":"Банковская гарантия, представляемая в налоговый орган гарантом, подписывается усиленной квалифицированной электронной подписью лица, обладающего таким правом, и направляется в налоговый орган в электронной форме по телекоммуникационным каналам связи. Формат и порядок направления банковской гарантии в налоговый орган в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по согласованию с Центральным банком Российской Федерации. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nВ случаях, предусмотренных настоящим Кодексом, налоговый орган уведомляет выдавшего банковскую гарантию гаранта в электронной форме по телекоммуникационным каналам связи о его освобождении от обязательств по этой банковской гарантии. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nПри этом налогоплательщика, в отношении которого выдана такая банковская гарантия, налоговый орган уведомляет в электронной форме по телекоммуникационным каналам связи об освобождении гаранта от обязательств по этой банковской гарантии в случае поступления от указанного налогоплательщика в налоговый орган в электронной форме по телекоммуникационным каналам связи соответствующего заявления. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nНалоговый орган возвращает по письменному заявлению налогоплательщика представленную им на бумажном носителе банковскую гарантию в срок не позднее трех дней со дня получения такого заявления. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nВ целях статьи 64 настоящего Кодекса банковская гарантия может быть представлена в налоговый орган налогоплательщиком на бумажном носителе. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n1) наличие лицензии на осуществление банковских операций, выданной Центральным банком Российской Федерации, и осуществление банковской деятельности в течение не менее пяти лет;\n\n2) наличие собственных средств (капитала) банка в размере не менее 1 миллиарда рублей;\n\n3) соблюдение обязательных нормативов, предусмотренных Федеральным законом от 10 июля 2002 года № 86-ФЗ \"О Центральном банке Российской Федерации (Банке России)\", на все отчетные даты в течение последних шести месяцев;\n\n4) отсутствие требования Центрального банка Российской Федерации об осуществлении мер по финансовому оздоровлению банка на основании параграфа 41 главы IX Федерального закона от 26 октября 2002 года № 127-ФЗ \"О несостоятельности (банкротстве)\". Настоящий подпункт не применяется к банкам, в отношении которых реализуются меры по предупреждению банкротства, осуществляемые с участием Центрального банка Российской Федерации или государственной корпорации \"Агентство по страхованию вкладов\". (В редакции федеральных законов от 29.12.2014 № 462-ФЗ, от 27.12.2019 № 470-ФЗ)\n\nМаксимальная сумма одной банковской гарантии и максимальная сумма всех одновременно действующих банковских гарантий, выданных государственной корпорацией развития \"ВЭБ.РФ\", для принятия указанных гарантий налоговыми органами устанавливаются Правительством Российской Федерации. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.12.2017 № 466-ФЗ)\n\nВ течение срока реализации плана по предупреждению банкротства банка, включенного в перечень на дату утверждения Советом директоров Центрального банка Российской Федерации плана по предупреждению банкротства банка, этот банк не исключается из перечня при условии принятия Советом директоров Центрального банка Российской Федерации решения о гарантировании непрерывности деятельности этого банка.\n\nВ случае, если банк, включенный в перечень на дату утверждения в отношении этого банка плана по предупреждению банкротства банка, исключен из перечня до дня принятия Советом директоров Центрального банка Российской Федерации решения о гарантировании непрерывности деятельности этого банка в течение срока реализации плана по предупреждению банкротства банка, этот банк включается Министерством финансов Российской Федерации в перечень не позднее чем в течение пяти дней со дня получения от Центрального банка Российской Федерации сведений, указанных в абзаце первом настоящего пункта.\n\n(Дополнение пунктом - Федеральный закон от 27.12.2019 № 470-ФЗ)\n\n1) банковская гарантия должна быть безотзывной и непередаваемой;\n\n2) банковская гарантия не может содержать указание на представление налоговым органом гаранту документов, которые не предусмотрены настоящей статьей;\n\n3) срок действия банковской гарантии должен истекать не ранее чем через шесть месяцев со дня истечения установленного срока исполнения налогоплательщиком обязанности по уплате налога, обеспеченной банковской гарантией, если иное не предусмотрено настоящим Кодексом;\n\n4) сумма, на которую выдана банковская гарантия, должна обеспечивать исполнение гарантом в полном объеме обязанности налогоплательщика по уплате налога и уплате пеней, если иное не предусмотрено настоящим Кодексом; (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n5) банковская гарантия должна предусматривать применение налоговым органом мер по взысканию с гаранта сумм, обязанность по уплате которых обеспечена банковской гарантией, в порядке и сроки, которые предусмотрены статьями 46 и 47 настоящего Кодекса, в случае неисполнения им в установленный срок требования об уплате денежной суммы по банковской гарантии, направленного до окончания срока действия банковской гарантии.\n\nВ случае неисполнения гарантом в установленный срок требования об уплате денежной суммы по банковской гарантии налоговый орган реализует право бесспорного списания суммы, указанной в данном требовании. (Дополнение абзацем - Федеральный закон от 14.07.2022 № 263-ФЗ) (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nМаксимальная сумма одной банковской гарантии и максимальная сумма всех одновременно действующих банковских гарантий, выданных включенным в перечень банком, в отношении которого Советом директоров Центрального банка Российской Федерации утвержден план по предупреждению банкротства банка и принято решение о гарантировании непрерывности его деятельности в течение срока реализации плана по предупреждению банкротства банка, для принятия указанных гарантий налоговыми органами в течение срока реализации плана по предупреждению банкротства банка устанавливаются в соответствии с абзацем первым настоящего пункта на последнюю квартальную отчетную дату, предшествующую дате утверждения Советом директоров Центрального банка Российской Федерации плана по предупреждению банкротства этого банка. (Дополнение абзацем - Федеральный закон от 27.12.2019 № 470-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 05.04.2016 № 101-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 23.07.2013 № 248-ФЗ)","article_title":"Статья 74.1. Банковская гарантия","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f60aa7d816c842932d47d1eae15f80ebe394ce4010f09dab038b8811078bc338"},{"code_id":"NK_RF","article_number":"75","version_date":"2000-07-31","article_text":"1. Пеней признается установленная настоящей статьей денежная сумма, которую налогоплательщик должен уплатить в бюджетную систему Российской Федерации в случае неисполнения обязанности по уплате причитающихся сумм налогов в установленные законодательством о налогах и сборах сроки.\n\n2. Сумма соответствующих пеней уплачивается дополнительно к причитающимся к уплате суммам налога независимо от применения других мер обеспечения исполнения обязанности по уплате налога, а также мер ответственности за нарушение законодательства о налогах и сборах.\n\n3. Пеня начисляется\n\nза каждый календарный день просрочки исполнения обязанности по уплате налогов начиная со дня возникновения недоимки по день (включительно) исполнения совокупной обязанности по уплате налогов.\n\nНе начисляются пени на сумму недоимки, которую налогоплательщик не мог погасить в силу того, что по решению налогового органа был наложен арест на имущество налогоплательщика или по решению суда были приняты обеспечительные меры в виде приостановления операций по счетам налогоплательщика в банке, наложения ареста на денежные средства или на имущество налогоплательщика. В этом случае пени не начисляются за весь период действия указанных обстоятельств. Подача заявления о предоставлении отсрочки или рассрочки либо заявления о предоставлении инвестиционного налогового кредита не приостанавливает начисления пеней на сумму налога, подлежащую уплате.\n\nНе начисляются пени на сумму недоимки в размере, не превышающем размера положительного сальдо единого налогового счета налогоплательщика в соответствующий календарный день просрочки исполнения обязанности по уплате налогов, увеличенного на сумму денежных средств, зачтенную в счет исполнения предстоящей обязанности этого налогоплательщика по уплате конкретного налога. (Дополнение абзацем - Федеральный закон от 29.10.2024 № 362-ФЗ)\n\n1) для физических лиц, включая индивидуальных предпринимателей, - одной трехсотой действующей в это время ключевой ставки Центрального банка Российской Федерации;\n\n2) для организаций:\n\nв отношении суммы отрицательного сальдо единого налогового счета, сформированного в связи с неисполненной обязанностью по уплате налогов, непрерывно существующей до 30 календарных дней (включительно), - одной трехсотой действующей в это время ключевой ставки Центрального банка Российской Федерации;\n\nв отношении суммы недоимки, не указанной в абзаце втором настоящего подпункта, - одной стопятидесятой ключевой ставки Центрального банка Российской Федерации.\n\n1) в течение первых 30 календарных дней (включительно) просрочки исполнения обязанности по уплате налогов - одной трехсотой ключевой ставки Центрального банка Российской Федерации, действующей в указанный период;\n\n2) начиная с 31-го дня просрочки исполнения обязанности по уплате налогов по 90-й день (включительно) - одной стопятидесятой ключевой ставки Центрального банка Российской Федерации, действующей в указанный период;\n\n3) начиная с 91-го дня просрочки исполнения обязанности по уплате налогов - одной трехсотой ключевой ставки Центрального банка Российской Федерации, действующей в указанный период.\n\n(Дополнение пунктом - Федеральный закон от 29.10.2024 № 362-ФЗ)\n\nВ случае увеличения совокупной обязанности отражение на едином налоговом счете начисления пеней на сумму недоимки осуществляется с даты учета увеличения соответствующей обязанности в соответствии с пунктом 5 статьи 113 настоящего Кодекса.\n\n1) возникшей в результате произведенной налогоплательщиком в соответствии с пунктом 6 статьи 1053 настоящего Кодекса самостоятельной корректировки налоговой базы и суммы налога (убытков), - со дня возникновения недоимки до установленного срока уплаты налога на прибыль организаций (налога на доходы физических лиц) за соответствующий налоговый период;\n\n2) возникшей в результате произведенной налогоплательщиком в соответствии с пунктом 12 статьи 10518 настоящего Кодекса обратной корректировки налоговой базы и суммы налога (убытков);\n\n3) образовавшейся у налогоплательщика в результате выполнения им письменных разъяснений о порядке исчисления и уплаты налога или по иным вопросам применения законодательства о налогах и сборах, данных ему либо неопределенному кругу лиц финансовым, налоговым или другим уполномоченным органом государственной власти (уполномоченным должностным лицом этого органа) в пределах его компетенции (указанные обстоятельства устанавливаются при наличии соответствующего документа этого органа, по смыслу и содержанию относящегося к налоговым (отчетным, расчетным) периодам, по которым образовалась недоимка, независимо от даты издания такого документа), и (или) в результате выполнения налогоплательщиком мотивированного мнения налогового органа, направленного ему в ходе проведения налогового мониторинга;\n\n4) в отношении которой принято решение о предоставлении отсрочки, рассрочки, - со дня, следующего за днем принятия указанного решения. В случае невступления решения о предоставлении отсрочки, рассрочки в силу в соответствии с пунктом 10 статьи 64 настоящего Кодекса начисление пеней возобновляется со дня, следующего за днем принятия решения о предоставлении отсрочки, рассрочки. (Дополнение подпунктом - Федеральный закон от 28.12.2022 № 565-ФЗ)\n\n(Статья в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)","article_title":"Статья 75. Пеня","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9f0a78a2ba2d81f510332d94d7519b9287935b276536076654b147e055196b63"},{"code_id":"NK_RF","article_number":"76","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 27.06.2011 № 162-ФЗ, от 19.12.2023 № 610-ФЗ)\n\nПриостановление операций по счету означает прекращение банком, а в отношении приостановления операций по счету цифрового рубля оператором платформы цифрового рубля всех расходных операций по данному счету, счету цифрового рубля, если иное не предусмотрено пунктом 2 настоящей статьи. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nПриостановление операций по счету, по счету цифрового рубля не распространяется на платежи, очередность исполнения которых в соответствии с гражданским законодательством Российской Федерации предшествует исполнению обязанности по уплате налогов, сборов, страховых взносов, а также на операции по списанию денежных средств в счет уплаты налогов (авансовых платежей), сборов, страховых взносов, соответствующих пеней и штрафов и по их перечислению в бюджетную систему Российской Федерации. (В редакции  федеральных законов от 26.11.2008 № 224-ФЗ, от 03.07.2016 № 243-ФЗ, от 19.12.2023 № 610-ФЗ)\n\nПриостановление переводов электронных денежных средств означает прекращение банком всех операций, влекущих уменьшение остатка электронных денежных средств, если иное не предусмотрено пунктом 2 настоящей статьи. (Дополнение абзацем - Федеральный закон от 27.06.2011 № 162-ФЗ)\n\nНе подлежат приостановлению операции по специальным избирательным счетам, специальным счетам фондов референдума и иным счетам в части сумм денежных средств, право собственности на которые не принадлежит владельцу соответствующего счета и на которые в соответствии с законодательством Российской Федерации не может быть обращено взыскание по обязательствам владельца этого счета. (Дополнение абзацем - Федеральный закон от 26.04.2016 № 110-ФЗ) (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\nПриостановление операций по счетам налогоплательщика-организации в банке, приостановление операций по счету цифрового рубля в случае, предусмотренном настоящим пунктом, означают прекращение банком, оператором платформы цифрового рубля расходных операций по счету (счетам), счету цифрового рубля этого налогоплательщика-организации в размере отрицательного сальдо его единого налогового счета, определяемом соответственно банком, оператором платформы цифрового рубля ежедневно на основании информации, содержащейся в реестре решений о взыскании задолженности, до момента формирования положительного либо нулевого сальдо его единого налогового счета, если иное не предусмотрено абзацем третьим пункта 1 настоящей статьи. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nПриостановление переводов электронных денежных средств налогоплательщика-организации в случае, предусмотренном настоящим пунктом, означает прекращение банком операций, влекущих уменьшение остатка электронных денежных средств, в размере отрицательного сальдо единого налогового счета этого налогоплательщика-организации до момента формирования положительного либо нулевого сальдо его единого налогового счета, определяемом банком ежедневно на основании информации, содержащейся в реестре решений о взыскании задолженности.\n\nПриостановление операций налогоплательщика-организации по его валютному счету, счету в драгоценных металлах в банке либо переводов электронных денежных средств налогоплательщика-организации в иностранной валюте в случае, предусмотренном настоящим пунктом, означает прекращение банком расходных операций или операций, влекущих уменьшение остатка электронных денежных средств в иностранной валюте, в размере отрицательного сальдо единого налогового счета этого налогоплательщика-организации в рублях по курсу Центрального банка Российской Федерации или стоимости драгоценных металлов, определенной исходя из учетной цены на драгоценные металлы, установленных Центральным банком Российской Федерации на дату начала действия такого приостановления, до момента формирования положительного либо нулевого сальдо его единого налогового счета, определяемых банком на основании информации, содержащейся в реестре решений о взыскании задолженности.\n\n(Пункт в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n1) в случае непредставления этим налогоплательщиком-организацией налоговой декларации в налоговый орган в течение 20 дней по истечении установленного срока представления такой декларации - в течение трех лет со дня истечения срока, установленного настоящим подпунктом; (В редакции Федерального закона от 09.11.2020 № 368-ФЗ)\n\n11) в случае неисполнения налогоплательщиком-организацией установленной пунктом 51 статьи 23 настоящего Кодекса обязанности по обеспечению получения от налогового органа по месту нахождения организации (по месту учета организации в качестве крупнейшего налогоплательщика) документов в электронной форме по телекоммуникационным каналам связи через оператора электронного документооборота - в течение 10 дней со дня установления налоговым органом факта неисполнения налогоплательщиком-организацией такой обязанности; (Дополнение подпунктом - Федеральный закон от 01.05.2016 № 130-ФЗ)\n\n2) (Подпункт утратил силу - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n(Пункт в редакции Федерального закона от 28.06.2013 № 134-ФЗ)\n\n1) при принятии решения на основании подпункта 1 пункта 3 настоящей статьи - не позднее одного дня, следующего за днем представления налогоплательщиком-организацией налоговой декларации;\n\n11) при принятии решения на основании подпункта 11 пункта 3 настоящей статьи - не позднее одного дня, следующего за днем исполнения налогоплательщиком-организацией обязанности по обеспечению получения от налогового органа по месту нахождения организации (по месту учета организации в качестве крупнейшего налогоплательщика) документов в электронной форме по телекоммуникационным каналам связи через оператора электронного документооборота, установленной пунктом 51 статьи 23 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 01.05.2016 № 130-ФЗ)\n\n2) (Подпункт утратил силу - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 28.06.2013 № 134-ФЗ)\n\nВ этом случае решение налогового органа о приостановлении операций налогового агента (плательщика страховых взносов) по его счетам в банке, по его счету цифрового рубля и переводов его электронных денежных средств отменяется решением этого налогового органа не позднее одного дня, следующего за днем представления указанным налоговым агентом (плательщиком страховых взносов) расчета сумм налога на доходы физических лиц, исчисленных и удержанных налоговым агентом (расчета по страховым взносам, расчета сумм выплаченных иностранным организациям доходов и удержанных налогов). (В редакции  федеральных законов от 31.07.2023 № 389-ФЗ, от 19.12.2023 № 610-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 02.05.2015 № 113-ФЗ) (В редакции Федерального закона от 29.07.2018 № 232-ФЗ)\n\nРешение об отмене приостановления операций по счетам налогоплательщика-организации в банке, по его счету цифрового рубля и переводов его электронных денежных средств направляется соответственно в банк, оператору платформы цифрового рубля в электронной форме не позднее дня, следующего за днем принятия такого решения.\n\nПорядок направления в банк, оператору платформы цифрового рубля в электронной форме решения налогового органа о приостановлении операций по счетам в банке, по счету цифрового рубля налогоплательщика-организации и переводов его электронных денежных средств или решения об отмене приостановления операций по счетам в банке, по счету цифрового рубля налогоплательщика-организации и переводов его электронных денежных средств устанавливается Центральным банком Российской Федерации по согласованию с федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nФормы решения налогового органа о приостановлении операций по счетам налогоплательщика-организации в банке, по его счету цифрового рубля и переводов его электронных денежных средств и решения об отмене приостановления операций по счетам налогоплательщика-организации в банке, по его счету цифрового рубля и переводов его электронных денежных средств утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. Форматы указанных решений утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по согласованию с Центральным банком Российской Федерации.\n\nКопия решения о приостановлении операций по счетам налогоплательщика-организации в банке, по его счету цифрового рубля и переводов его электронных денежных средств или решения об отмене приостановления операций по счетам налогоплательщика-организации в банке, по его счету цифрового рубля и переводов его электронных денежных средств передается налогоплательщику-организации под расписку или иным способом, свидетельствующим о дате получения налогоплательщиком-организацией копии соответствующего решения, в срок не позднее дня, следующего за днем принятия такого решения.\n\n(Пункт в редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nнежных средств, перевод которых приостановлен, в течение одного дня, следующего за днем приостановления операций по счетам налогоплательщика-организации в банке. Оператор платформы цифрового рубля обязан сообщить в налоговый орган в электронной форме сведения об остатках цифровых рублей на счете цифрового рубля, операции по которому приостановлены, в течение одного дня, следующего за днем приостановления операций по счету цифрового рубля налогоплательщика-организации. Форматы сообщения банком, оператором платформы цифрового рубля сведений об остатках денежных средств (драгоценных металлов) на счетах налогоплательщика-организации в банке, остатках цифровых рублей на счете цифрового рубля и об остатках электронных денежных средств и порядок направления банком, оператором платформы цифрового рубля указанного сообщения в электронной форме утверждаются Центральным банком Российской Федерации по согласованию с федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nБанк обязан не позднее дня, следующего за днем, по состоянию на конец которого произошло изменение остатка денежных средств (драгоценных металлов) налогоплательщика-организации на счетах в банке, операции по которым приостановлены, а также остатка электронных денежных средств, перевод которых приостановлен, сообщать в налоговый орган в электронной форме сведения об остатках денежных средств (драгоценных металлов) и об остатках электронных денежных средств по состоянию на конец соответствующего операционного дня. Оператор платформы цифрового рубля обязан не позднее дня, следующего за днем, по состоянию на конец которого произошло изменение остатка цифровых рублей налогоплательщика-организации на счете цифрового рубля, сообщить в налоговый орган в электронной форме сведения об остатке цифровых рублей на счете цифрового рубля по состоянию на конец соответствующего операционного дня. (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n(Пункт в редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nПри направлении в банк решения о приостановлении операций по счетам налогоплательщика-организации в банке и переводов его электронных денежных средств, оператору платформы цифрового рубля решения о приостановлении операций налогоплательщика-организации по счету цифрового рубля в электронной форме дата и время получения этих решений банком, оператором платформы цифрового рубля определяются в порядке, устанавливаемом Центральным банком Российской Федерации по согласованию с федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nВ случае, если после приостановления операций по счетам налогоплательщика-организации в банке изменились наименование налогоплательщика-организации и (или) реквизиты счета налогоплательщика-организации в банке, операции по которому приостановлены налоговым органом, приостановление операций по счетам в банке применяется также в отношении налогоплательщика-организации, изменившей свое наименование, и операций по счету, имеющему измененные реквизиты. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 229-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nВ случае, если после приостановления переводов электронных денежных средств налогоплательщика-организации в банке изменились наименование налогоплательщика-организации и (или) реквизиты корпоративного электронного средства платежа налогоплательщика-организации, переводы электронных денежных средств с использованием которого приостановлены налоговым органом, приостановление переводов электронных денежных средств применяется также в отношении налогоплательщика-организации, изменившей свое наименование, и электронных денежных средств с использованием корпоративного электронного средства платежа, имеющего измененные реквизиты. (Дополнение абзацем - Федеральный закон от 27.06.2011 № 162-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nВ случае, если после приостановления операций по счету цифрового рубля налогоплательщика-организации изменились наименование налогоплательщика-организации и (или) реквизиты счета цифрового рубля налогоплательщика-организации, операции по которому приостановлены налоговым органом, приостановление операций по счету цифрового рубля применяется также в отношении налогоплательщика-организации, изменившей свое наименование, и операций по счету цифрового рубля, имеющему измененные реквизиты. (Дополнение абзацем - Федеральный закон от 19.12.2023 № 610-ФЗ)\n\nВ случае, если отмена приостановления операций по счетам налогоплательщика-организации в банке осуществляется по основаниям, предусмотренным иными федеральными законами, принятие налоговым органом решения об отмене приостановления таких операций не требуется.\n\n(Дополнение пунктом - Федеральный закон от 26.11.2008 № 224-ФЗ) (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nВ случае неправомерного вынесения налоговым органом решения о приостановлении операций по счетам налогоплательщика-организации в банке на сумму денежных средств, в отношении которой действовало указанное решение (на драгоценные металлы, в отношении которых действовало указанное решение) налогового органа, начисляются проценты, подлежащие уплате указанному налогоплательщику-организации за каждый календарный день, начиная со дня получения банком решения о приостановлении операций по счетам налогоплательщика до дня получения банком решения об отмене приостановления операций по счетам налогоплательщика-организации. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 229-ФЗ) (В редакции Федерального закона от 27.11.2017 № 343-ФЗ)\n\nПроцентная ставка принимается равной ставке рефинансирования Центрального банка Российской Федерации, действовавшей в дни неправомерного приостановления операций по счетам налогоплательщика-организации, нарушения налоговым органом срока отмены решения о приостановлении операций по счетам налогоплательщика-организации в банке или срока направления в банк решения об отмене приостановления операций по счетам налогоплательщика-организации в банке. При этом стоимость драгоценных металлов определяется исходя из учетной цены на драгоценные металлы, установленной Центральным банком Российской Федерации на дату неправомерного приостановления операций по счетам налогоплательщика-организации, нарушения налоговым органом срока отмены решения о приостановлении операций по счетам налогоплательщика-организации в банке или срока направления в банк решения об отмене приостановления операций по счетам налогоплательщика-организации в банке. (В редакции федеральных законов от 27.07.2010 № 229-ФЗ; от 29.06.2012 № 97-ФЗ; от 27.11.2017 № 343-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 26.11.2008 № 224-ФЗ)\n\n1) организаций - налоговых агентов, плательщиков сборов, плательщиков страховых взносов; (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n2) индивидуальных предпринимателей - налогоплательщиков, налоговых агентов, плательщиков сборов, плательщиков страховых взносов, не утративших статус индивидуального предпринимателя на дату принятия решения о взыскании (далее в настоящей статье - индивидуальный предприниматель);  (В редакции  федеральных законов от 03.07.2016 № 243-ФЗ, от 14.07.2022 № 263-ФЗ)\n\n3) организаций и индивидуальных предпринимателей, не являющихся налогоплательщиками (налоговыми агентами, плательщиками страховых взносов), которые при этом обязаны представлять налоговые декларации (расчеты по страховым взносам) в соответствии с частью второй настоящего Кодекса; (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n4) нотариусов, занимающихся частной практикой, адвокатов, учредивших адвокатские кабинеты, - налогоплательщиков, налоговых агентов, плательщиков страховых взносов. (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n(Пункт в редакции Федерального закона от 28.06.2013 № 134-ФЗ)\n\n12. В случае приостановления операций по счетам налогоплательщика-организации и переводов его электронных денежных средств в банке, приостановления операций по его счету цифрового рубля, а также по счетам лиц, указанных в пункте 11 настоящей статьи, их счетам цифрового рубля и открытия соответственно банком, оператором платформы цифрового рубля этой организации и этим лицам счета, счета цифрового рубля и (или) предоставления банком этой организации права использовать новые корпоративные электронные средства платежа (персонифицированные электронные средства платежа) для переводов электронных денежных средств все расходные операции по вновь открытым счетам, счету цифрового рубля и (или) по переводу электронных денежных средств этой организации и этих лиц прекращаются банком, а в отношении цифровых рублей оператором платформы цифрового рубля со дня открытия соответствующего счета, счета цифрового рубля и (или) предоставления права использовать корпоративные электронные средства платежа (персонифицированные электронные средства платежа) до прекращения действия приостановления операций по счетам, по счету цифрового рубля и (или) переводов электронных денежных средств этой организации и этих лиц либо до отмены налоговым органом приостановления операций по счетам, счету цифрового рубля и (или) переводов электронных денежных средств этой организации и этих лиц в соответствии с пунктами 91 и 93 настоящей статьи.\n\nПорядок информирования банков о приостановлении операций по счетам в банке налогоплательщика-организации, лиц, указанных в пункте 11 настоящей статьи, и переводов их электронных денежных средств, информирования оператора платформы цифрового рубля о приостановлении операций по счетам цифрового рубля налогоплательщика-организации, лиц, указанных в пункте 11 настоящей статьи, устанавливается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по согласованию с Центральным банком Российской Федерации.\n\nНе подлежат приостановлению в соответствии с настоящим пунктом операции по специальным избирательным счетам, специальным счетам фондов референдума и иным счетам в части сумм денежных средств, право собственности на которые не принадлежит владельцу соответствующего счета и на которые в соответствии с законодательством Российской Федерации не может быть обращено взыскание по обязательствам владельца этого счета.\n\nПриостановление операций по счету в соответствии с настоящим пунктом не распространяется на платежи, очередность исполнения которых в соответствии с гражданским законодательством предшествует исполнению обязанности по уплате налогов, сборов, страховых взносов, а также на операции по списанию денежных средств в счет уплаты налогов (авансовых платежей), сборов, страховых взносов, соответствующих пеней и штрафов и по их перечислению в бюджетную систему Российской Федерации.\n\n(Пункт в редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 76. Приостановление операций по счетам в банках, по счетам цифрового рубля, а также переводов электронных денежных средств организаций и индивидуальных предпринимателей","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bec87037ae57dcd934a74028df4811fb424da018d32c90bb3080062b9d44b741"},{"code_id":"NK_RF","article_number":"77","version_date":"2000-07-31","article_text":"Арест имущества производится в случае неисполнения налогоплательщиком-организацией в установленные сроки обязанности по уплате налога, пеней и штрафов и при наличии у налоговых или таможенных органов достаточных оснований полагать, что указанное лицо предпримет меры, чтобы скрыться либо скрыть свое имущество. (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 27.07.2006 № 137-ФЗ)\n\nПолным арестом имущества признается такое ограничение прав налогоплательщика-организации в отношении его имущества, при котором он не вправе распоряжаться арестованным имуществом, а владение и пользование этим имуществом осуществляются с разрешения и под контролем налогового или таможенного органа. (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\nЧастичным арестом признается такое ограничение прав налогоплательщика-организации в отношении его имущества, при котором владение, пользование и распоряжение этим имуществом осуществляются с разрешения и под контролем налогового или таможенного органа. (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\nРешение о наложении ареста может быть принято в отношении общего имущества товарищей, а при отсутствии или недостаточности такого имущества в отношении имущества всех управляющих товарищей (при этом в первую очередь такое решение принимается в отношении имущества управляющего товарища, ответственного за ведение налогового учета).\n\nРешение о наложении ареста на общее имущество товарищей принимается руководителем (заместителем руководителя) уполномоченного налогового органа. (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\nРешение о наложении ареста на общее имущество товарищей и имущество управляющих товарищей может быть принято не ранее принятия решения о взыскании задолженности в соответствии со статьей 46 настоящего Кодекса и при недостаточности или отсутствии денежных средств на счетах инвестиционного товарищества, лиц, являющихся управляющими товарищами, либо при отсутствии информации о счетах указанных лиц.  (В редакции  федеральных законов от 23.07.2013 № 248-ФЗ, от 14.07.2022 № 263-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 28.11.2011 № 336-ФЗ)\n\nАрест на объект недвижимого имущества иностранной организации, не осуществляющей деятельность в Российской Федерации через постоянное представительство, при превышении стоимости указанного объекта недвижимого имущества над суммой взыскиваемой задолженности в отношении этого объекта налагается в случае отсутствия у иностранной организации иного имущества на территории Российской Федерации, на которое может быть обращено взыскание. (Дополнение абзацем - Федеральный закон от 04.11.2\n\n014 № 347-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nЛицам, участвующим в производстве ареста имущества в качестве понятых, специалистов, а также налогоплательщику-организации (его представителю) разъясняются их права и обязанности. (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n10. При производстве ареста составляется протокол об аресте имущества. В этом протоколе либо в прилагаемой к нему описи перечисляется и описывается имущество, подлежащее аресту, с точным указанием наименования, количества и индивидуальных признаков предметов, а при возможности - их стоимости.\n\nВсе предметы, подлежащие аресту, предъявляются понятым и налогоплательщику-организации (его представителю). (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n11. Руководитель (его заместитель) налогового или таможенного органа, вынесший постановление о наложении ареста на имущество, определяет место, где должно находиться имущество, на которое наложен арест.\n\n1) банковскую гарантию, отвечающую требованиям, установленным статьей 741 настоящего Кодекса и подтверждающую, что гарант обязывается перед налоговыми органами уплатить в соответствии с условиями даваемого гарантом обязательства сумму задолженности налогоплательщика-организации в случае неуплаты этой суммы принципалом в установленный срок по представленному налоговым органом гаранту в письменной форме или электронной форме по телекоммуникационным каналам связи требованию об уплате этой суммы; (В редакции  федеральных законов от 14.07.2022 № 263-ФЗ, от 31.07.2023 № 389-ФЗ)\n\n2) залог имущества налогоплательщика-организации, оформленный в соответствии с пунктом 2 статьи 73 настоящего Кодекса;\n\n3) поручительство третьего лица, оформленное в порядке, предусмотренном статьей 74 настоящего Кодекса.\n\nВ целях настоящего подпункта поручитель должен соответствовать требованиям, установленным пунктом 21 статьи 1761 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 23.07.2013 № 248-ФЗ) (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nРешение об аресте имущества действует с момента наложения ареста до отмены этого решения налоговым или таможенным органом, вынесшим это решение, либо до отмены этого решения вышестоящим налоговым или таможенным органом или судом. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nНалоговый (таможенный) орган уведомляет налогоплательщика об отмене решения об аресте имущества в течение пяти дней после дня принятия данного решения. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 229-ФЗ)\n\nС момента признания имущества находящимся в залоге у налогового органа ранее наложенный на это имущество арест прекращается. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n(Наименование в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)","article_title":"Статья 77. Арест имущества","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"363be3353449fe6330ee236efe007cfa4e803cb7992b5a5a805141a66c80f559"},{"code_id":"NK_RF","article_number":"78","version_date":"2000-07-31","article_text":"1. Налогоплательщик, плательщик сбора, плательщик страховых взносов и (или) налоговый агент вправе распорядиться суммой денежных средств, формирующих положительное сальдо его единого налогового счета, путем зачета в порядке, предусмотренном настоящей статьей:\n\nв счет исполнения обязанности другого лица по уплате налогов, сборов, страховых взносов, пеней, штрафов и (или) процентов;\n\nв счет исполнения предстоящей обязанности по уплате конкретного налога (сбора, страхового взноса);\n\nв счет исполнения решений налоговых органов, указанных в подпунктах 9 и 10 пункта 5 и подпункте 3 пункта 7 статьи 113 настоящего Кодекса, либо погашения задолженности, не учитываемой в совокупной обязанности в соответствии с подпунктом 2 пункта 7 статьи 113 настоящего Кодекса. (В редакции  Федерального закона от 28.12.2022 № 565-ФЗ)\n\nВ случае отсутствия положительного сальдо на едином налоговом счете для исполнения заявления о распоряжении путем зачета налогоплательщику, плательщику сбора, плательщику страховых взносов и (или) налоговому агенту направляется сообщение об отказе в исполнении заявления о распоряжении путем зачета.\n\nВ случае недостаточности положительного сальдо на едином налоговом счете для исполнения заявления о распоряжении путем зачета в полном объеме зачет осуществляется частично.\n\nВ заявлении о распоряжении путем зачета в счет исполнения предстоящей обязанности по уплате конкретного налога (сбора, страхового взноса) указываются принадлежность денежных средств к источнику доходов бюджетов бюджетной системы Российской Федерации, срок уплаты и иные реквизиты, необходимые для определения соответствующей обязанности.\n\nЗаявление о распоряжении путем зачета в счет исполнения решений налоговых органов, указанных в подпунктах 9 и 10 пункта 5 и подпункте 3 пункта 7 статьи 113 настоящего Кодекса, либо погашения задолженности, не учитываемой в совокупной обязанности в соответствии с подпунктом 2 пункта 7 статьи 113 настоящего Кодекса, может быть подано не позднее дня, предшествующего дню вступления в силу судебного акта о взыскании задолженности, с указанием соответствующего решения налогового органа. Зачет осуществляется последовательно начиная с задолженности с наиболее ранними сроками уплаты. (В редакции  Федерального закона от 28.12.2022 № 565-ФЗ)\n\nФорма и формат заявления о распоряжении путем зачета утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nИндивидуальными предпринимателями заявление о распоряжении путем зачета в счет исполнения предстоящей обязанности по уплате конкретного налога (сбора, страхового взноса) может быть представлено в налоговый орган через личный кабинет налогоплательщика в виде документа, подписанного усиленной неквалифицированной электронной подписью, сформированной в порядке, установленном федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, в соответствии с требованиями Федерального закона от 6 апреля 2011 года № 63-ФЗ \"Об электронной подписи\". (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nВ случае, если на момент проведения указанного в абзаце первом настоящего пункта зачета суммы, формирующей положительное сальдо единого налогового счета налогоплательщика, недостаточно для исполнения в полном объеме обязанностей такого налогоплательщика по уплате налогов, подлежащих уплате на основании направленного ему налогового уведомления, такой зачет осуществляется пропорционально суммам таких обязанностей.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nВ случае одновременного поступления уведомления, указанного в пункте 7 настоящей статьи, и уведомления, указанного в абзаце первом настоящего пункта, зачет, предусмотренный абзацем первым настоящего пункта, осуществляется после зачета, предусмотренного пунктом 7 настоящей статьи.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Статья в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)","article_title":"Статья 78. Зачет сумм денежных средств, формирующих положительное сальдо единого налогового счета","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5adf94c53adcd7f9e13bc19754ea7a3bb4c4cb22aa4fbd39847f0382547bd0e6"},{"code_id":"NK_RF","article_number":"79","version_date":"2000-07-31","article_text":"1. Налогоплательщик, плательщик сбора, плательщик страховых взносов и (или) налоговый агент вправе распорядиться суммой денежных средств, формирующих положительное сальдо его единого налогового счета, путем возврата этой суммы на открытый ему счет в банке в порядке, предусмотренном настоящей статьей.\n\nРаспоряжение денежными средствами в размере сумм, формирующих положительное сальдо единого налогового счета налогоплательщика, плательщика сбора, плательщика страховых взносов и (или) налогового агента, осуществляется на основании:\n\nзаявления о распоряжении путем возврата сумм денежных средств, формирующих положительное сальдо единого налогового счета такого лица (далее - заявление о распоряжении путем возврата), представленного в налоговый орган по месту учета такого лица по установленной форме на бумажном носителе или по установленному формату в электронной форме с усиленной квалифицированной электронной подписью по телекоммуникационным каналам связи или представленного через личный кабинет налогоплательщика, а также в составе налоговой декларации в соответствии со статьей 229 настоящего Кодекса;\n\nзаявления о возврате излишне уплаченных сумм налога на доходы физических лиц, уплачиваемого в соответствии со статьей 2271 настоящего Кодекса, налога на профессиональный доход и сборов за пользование объектами животного мира и за пользование объектами водных биологических ресурсов, налога на сверхприбыль,  представленного в налоговый орган; (В редакции  федеральных законов от 28.12.2022 № 565-ФЗ, от 04.08.2023 № 415-ФЗ, от 12.07.2024 № 176-ФЗ, от 29.10.2024 № 362-ФЗ)\n\nзаявления о возврате излишне уплаченных сумм страховых взносов на дополнительное социальное обеспечение членов летных экипажей воздушных судов гражданской авиации, а также отдельных категорий работников организаций угольной промышленности, представленного в налоговый орган плательщиком страховых взносов, включенным в порядке, предусмотренном Федеральным законом от 27 ноября 2001 года № 155-ФЗ \"О дополнительном социальном обеспечении членов летных экипажей воздушных судов гражданской авиации\" и Федеральным законом от 10 мая 2010 года № 84-ФЗ \"О дополнительном социальном обеспечении отдельных категорий работников организаций угольной промышленности\", в соответствующие перечни; (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nпринятого налоговым органом решения о возмещении (полностью или частично) суммы налога на добавленную стоимость или суммы акциза в соответствии со статьей 1761 или 2031 настоящего Кодекса;\n\nпринятого налоговым органом решения о возмещении (полностью или частично) суммы налога на добавленную стоимость или суммы акциза в соответствии со статьей 176 или 203 либо решения о предоставлении налогового вычета в соответствии со статьей 2211 настоящего Кодекса.\n\nФорма заявления о распоряжении путем возврата и формат указанного заявления в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n2. В случае отсутствия положительного сальдо на едином налоговом счете налогоплательщику, плательщику сбора, плательщику страховых взносов и (или) налоговому агенту направляется сообщение об отказе в возврате.\n\nВ случае недостаточности положительного сальдо на едином налоговом счете для осуществления предусмотренного настоящей статьей возврата сумм денежных средств налогоплательщику, плательщику сбора, плательщику страховых взносов и (или) налоговому агенту возврат осуществляется частично.\n\n3. Поручение о возврате суммы денежных средств, формирующих положительное сальдо единого налогового счета лица - налогоплательщика, плательщика сбора, плательщика страховых взносов и (или) налогового агента, направляется налоговым органом в территориальный орган Федерального казначейства не позднее следующего дня после наступления одного из следующих событий:\n\nполучение заявления о распоряжении путем возврата, но не ранее принятия решений о возмещении (полностью или частично) суммы налога, заявленной к возмещению, в соответствии со статьями 176 и 203 настоящего Кодекса, решения о предоставлении налогового вычета в соответствии со статьей 2211 настоящего Кодекса, если иное не предусмотрено настоящим пунктом; (В редакции  Федерального закона от 28.12.2022 № 565-ФЗ)\n\nпризнание в соответствии с подпунктом 5 пункта 1 статьи 113 настоящего Кодекса единым налоговым платежом излишне уплаченных сумм налога на доходы физических лиц, уплачиваемого в порядке, установленном статьей 2271 настоящего Кодекса, налога на профессиональный доход, сборов за пользование объектами животного мира и за пользование объектами водных биологических ресурсов, налога на сверхприбыль,  страховых взносов на дополнительное социальное обеспечение членов летных экипажей воздушных судов гражданской авиации, а также отдельных категорий работников организаций угольной промышленности после получения заявления о возврате сумм соответствующих излишне уплаченных налогов, сборов или страховых взносов; (В редакции  федеральных законов от 04.08.2023 № 415-ФЗ, от 08.08.2024 № 259-ФЗ, от 29.10.2024 № 362-ФЗ)\n\nпринятие налоговым органом решения о возмещении (полностью или частично) суммы налога на добавленную стоимость или суммы акциза в соответствии со статьей 1761 или 2031 настоящего Кодекса;\n\nполучение заявления о распоряжении путем возврата суммы денежных средств, формирующих положительное сальдо единого налогового счета, представленного в соответствии со статьей 229 настоящего Кодекса одновременно с налоговой декларацией по налогу на доходы физических лиц, но не ранее дня\n\nвступления в силу решения налогового органа по результатам камеральной налоговой проверки на основе указанной налоговой декларации либо истечения 10 дней после дня окончания установленного статьей 88 настоящего Кодекса срока проведения камеральной налоговой проверки указанной налоговой декларации. В случае, если при проведении камеральной налоговой проверки указанной налоговой декларации не были выявлены нарушения законодательства о налогах и сборах, указанное в абзаце первом настоящего пункта поручение о возврате суммы денежных средств может быть направлено налоговым органом в территориальный орган Федерального казначейства раньше дня окончания установленного статьей 88 настоящего Кодекса срока проведения камеральной налоговой проверки указанной налоговой декларации. (Дополнение абзацем - Федеральный закон от 28.12.2022 № 565-ФЗ)\n\n4. В случае, если установлен факт излишнего взыскания денежных средств, возврат излишне взысканных средств осуществляется налоговым органом самостоятельно в пределах сумм, формирующих положительное сальдо единого налогового счета.\n\nВозврат излишне взысканных денежных средств осуществляется на открытый счет организации, индивидуального предпринимателя, физического лица, не являющегося индивидуальным предпринимателем, в банке, информация о котором имеется у налоговых органов.\n\nПроценты на сумму излишне взысканных денежных средств начисляются со дня, следующего за днем взыскания, по день фактического возврата излишне взысканных сумм либо учета излишне взысканных сумм в счет исполнения совокупной обязанности налогоплательщика, плательщика сбора, плательщика страховых взносов и (или) налогового агента.\n\nПроцентная ставка принимается равной действовавшей в эти дни ключевой ставке Центрального банка Российской Федерации.\n\n5. Возврат сумм денежных средств, формирующих положительное сальдо единого налогового счета лица - налогоплательщика, плательщика сбора, плательщика страховых взносов и (или) налогового агента, осуществляется в валюте Российской Федерации посредством перечисления суммы денежных средств в размере, не превышающем положительное сальдо единого налогового счета такого лица по состоянию на дату формирования поручения о возврате денежных средств, на указанный в соответствующем заявлении счет в банке, информация о котором имеется у налоговых органов и который открыт такому лицу либо иностранному номинальному держателю (иностранному уполномоченному держателю, лицу, которому открыт счет депозитарных программ), в случае, если через такое лицо налогоплательщику осуществлялась выплата дохода, особенности исчисления и уплаты налога с которого установлены статьей 3101 настоящего Кодекса.\n\nполучения заявления лица о распоряжении путем возврата, но не ранее принятия налоговым органом решения о возмещении (полностью или частично) суммы налога на добавленную стоимость или акциза в соответствии со статьей 176 или 203 настоящего Кодекса либо решения о предоставлении налогового вычета в соответствии со статьей 2211 настоящего Кодекса;\n\nпризнания в соответствии с подпунктом 5 пункта 1 статьи 113 настоящего Кодекса единым налоговым платежом излишне уплаченных сумм налога на доходы физических лиц, уплачиваемого в порядке, установленном статьей 2271 настоящего Кодекса, налога на профессиональный доход, сборов за пользование объектами животного мира и за пользование объектами водных биологических ресурсов, налога на сверхприбыль,  страховых взносов на дополнительное социальное обеспечение членов летных экипажей воздушных судов гражданской авиации, а также отдельных категорий работников организаций угольной промышленности после получения заявления о возврате сумм соответствующих излишне уплаченных налогов, сборов или страховых взносов; (В редакции  федеральных законов от 04.08.2023 № 415-ФЗ, от 08.08.2024 № 259-ФЗ, от 29.10.2024 № 362-ФЗ)\n\nпринятия налоговым органом решения о возмещении (полностью или частично) суммы налога на добавленную стоимость или суммы акциза в соответствии со статьей 1761 или 2031 настоящего Кодекса.\n\nПроцентная ставка принимается равной ключевой ставке Центрального банка Российской Федерации, действовавшей в дни нарушения срока перечисления указанных сумм денежных средств.\n\n(Статья в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n(Наименование в редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n(Наименование в редакции Федерального закона от 09.07.1999 № 154-ФЗ)","article_title":"Статья 79. Возврат денежных средств, формирующих положительное сальдо единого налогового счета","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ef87020d43f6244676a7012bbc0355b146e502263ffab0a694b15e0617b35d4d"},{"code_id":"NK_RF","article_number":"8","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n1. Под налогом понимается обязательный, индивидуально безвозмездный платеж, взимаемый с организаций и физических лиц в форме отчуждения принадлежащих им на праве собственности, хозяйственного ведения или оперативного управления денежных средств в целях финансового обеспечения деятельности государства и (или) муниципальных образований.\n\nДля целей настоящего Кодекса страховыми взносами также признаются взносы, взимаемые с организаций в целях дополнительного социального обеспечения отдельных категорий физических лиц.\n\n(Дополнение пунктом - Федеральный закон от 03.07.2016 № 243-ФЗ)","article_title":"Статья 8. Понятие налога, сбора, страховых взносов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4471cb6a43e860b5c91058be95389aa56d47260f4b7f21e90aad3c8486c30624"},{"code_id":"NK_RF","article_number":"80","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nНалоговая декларация представляется каждым налогоплательщиком по каждому налогу, подлежащему уплате этим налогоплательщиком, если иное не предусмотрено законодательством о налогах и сборах.\n\nРасчет авансового платежа представляет собой письменное заявление или заявление налогоплательщика, составленное в электронной форме и переданное по телекоммуникационным каналам связи с применением усиленной квалифицированной электронной подписи или через личный кабинет налогоплательщика, о базе исчисления, об используемых льготах, исчисленной сумме авансового платежа и (или) о других данных, служащих основанием для исчисления и уплаты авансового платежа. Расчет авансового платежа представляется в случаях, предусмотренных настоящим Кодексом применительно к конкретному налогу. (В редакции федеральных законов от 27.07.2010 № 229-ФЗ; от 29.06.2012 № 97-ФЗ; от 04.11.2014 № 347-ФЗ)\n\nРасчет сбора представляет собой письменное заявление или заявление плательщика сбора, составленное в электронной форме и переданное по телекоммуникационным каналам связи с применением усиленной квалифицированной электронной подписи или через личный кабинет налогоплательщика, об объектах обложения, облагаемой базе, используемых льготах, исчисленной сумме сбора и (или) о других данных, служащих основанием для исчисления и уплаты сбора, если иное не предусмотрено настоящим Кодексом. Расчет сбора представляется в случаях, предусмотренных частью второй настоящего Кодекса применительно к каждому сбору. (В редакции федеральных законов от 27.07.2010 № 229-ФЗ; от 29.06.2012 № 97-ФЗ; от 04.11.2014 № 347-ФЗ)\n\nНалоговый агент представляет в налоговые органы расчеты, предусмотренные частью второй настоящего Кодекса. Указанные расчеты представляются в порядке, установленном частью второй настоящего Кодекса применительно к конкретному налогу.\n\nРасчет сумм налога на доходы физических лиц, исчисленных и удержанных налоговым агентом, представляет собой документ, содержащий обобщенную налоговым агентом информацию в целом по всем физическим лицам, получившим доходы от налогового агента (обособленного подразделения налогового агента), о суммах начисленных и выплаченных им доходов, предоставленных налоговых вычетах, об исчисленных и удержанных суммах налога, а также других данных, служащих основанием для исчисления налога. (Дополнение абзацем - Федеральный закон от 02.05.2015 № 113-ФЗ)\n\nРасчет по страховым взносам представляет собой письменное заявление или заявление плательщика страховых взносов, составленное в электронной форме и переданное по телекоммуникационным каналам связи с применением усиленной квалифицированной электронной подписи или через личный кабинет налогоплательщика, об объекте обложения страховыми взносами, о базе для исчисления страховых взносов, об исчисленной сумме страховых взносов и о других данных, служащих основанием для исчисления и уплаты страховых взносов, если иное не предусмотрено настоящим Кодексом. Расчет по страховым взносам представляется в случаях, предусмотренных главой 34 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 243-ФЗ)\n\nЛицо, признаваемое налогоплательщиком по одному или нескольким налогам, не осуществляющее операций, в результате которых происходит движение денежных средств на его счетах в банках (в кассе организации), и не имеющее по этим налогам объектов налогообложения, представляет по данным налогам единую (упрощенную) налоговую декларацию.\n\nФорма единой (упрощенной) налоговой декларации и порядок ее заполнения утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по согласованию с Министерством финансов Российской Федерации. (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nЕдиная (упрощенная) налоговая декларация представляется в налоговый орган по месту нахождения организации или месту жительства физического лица в следующие сроки: (В редакции Федерального закона от 08.08.2024 № 259-ФЗ)\n\nпо налогу на прибыль организаций - не позднее 20-го числа первого месяца второго квартала, следующего за налоговым периодом, в котором последний раз осуществлялись операции, в результате которых происходило движение денежных средств на счетах в банках (в кассе организации) этого лица, и (или) в котором последний раз были объекты налогообложения по налогу на прибыль организаций; (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nпо остальным налогам - не позднее 20-го числа первого месяца второго налогового периода, следующего за налоговым периодом, в котором последний раз осуществлялись операции, в результате которых происходило движение денежных средств на счетах в банках (в кассе организации) этого лица, и (или) в котором последний раз были объекты налогообложения по налогам, по которым представляется единая (упрощенная) налоговая декларация; (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nдля вновь созданных организаций, вновь зарегистрированных индивидуальных предпринимателей - не позднее 20-го числа месяца, следующего за истекшим кварталом, в котором была создана организация, был зарегистрирован индивидуальный предприниматель. (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n(Пункт в редакции Федерального закона от 30.12.2006 № 268-ФЗ)\n\nНалоговые декларации (расчеты) представляются в налоговый орган по месту учета налогоплательщика (плательщика сбора, плательщика страховых взносов, налогового агента) по установленным форматам в электронной форме по телекоммуникационным каналам связи через оператора электронного документооборота, являющегося российской организацией и соответствующего требованиям, утверждаемым федеральным органом исполнительной власти, уполномоченным осуществлять функции по контролю и надзору в сфере налогов и сборов, если иной порядок представления информации, отнесенной к государственной тайне, не предусмотрен законодательством Российской Федерации, следующими категориями налогоплательщиков (плательщиков страховых взносов): (В редакции федеральных законов от 28.06.2013 № 134-ФЗ; от 03.07.2016 № 243-ФЗ)\n\nналогоплательщиками (плательщиками страховых взносов), среднесписочная численность работников которых за предшествующий календарный год превышает 100 человек; (Дополнение абзацем - Федеральный закон от 28.06.2013 № 134-ФЗ) (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nвновь созданными (в том числе при реорганизации) организациями, численность работников которых превышает 100 человек; (Дополнение абзацем - Федеральный закон от 28.06.2013 № 134-ФЗ)\n\nналогоплательщиками (плательщиками страховых взносов), не указанными в абзацах третьем и четвертом настоящего пункта, для которых такая обязанность предусмотрена частью второй настоящего Кодекса применительно к конкретному налогу (страховым взносам). (Дополнение абзацем - Федеральный закон от 28.06.2013 № 134-ФЗ) (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nСведения о среднесписочной численности работников представляются в налоговые органы плательщиками страховых взносов, производящими выплаты и иные вознаграждения физическим лицам, в составе расчета по страховым взносам. (В редакции Федерального закона от 28.01.2020 № 5-ФЗ)\n\nНалогоплательщики, в соответствии со статьей 83 настоящего Кодекса отнесенные к категории крупнейших, представляют все налоговые декларации (расчеты), которые они обязаны представлять в соответствии с настоящим Кодексом, в налоговый орган по месту учета в качестве крупнейших налогоплательщиков по установленным форматам в электронной форме, если иной порядок представления информации, отнесенной к государственной тайне, не предусмотрен законодательством Российской Федерации. (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\nБланки налоговых деклараций (расчетов) предоставляются налоговыми органами бесплатно.\n\n(Пункт в редакции Федерального закона от 30.12.2006 № 268-ФЗ)\n\nНалоговый орган не вправе отказать в принятии налоговой декларации (расчета), представленной налогоплательщиком (плательщиком сборов, плательщиком страховых взносов, налоговым агентом) по установленной форме (установленному формату), если иное не предусмотрено настоящим Кодексом, и обязан проставить по просьбе налогоплательщика (плательщика сбора, плательщика страховых взносов, налогового агента) на копии налоговой декларации (копии расчета) отметку о принятии и дату ее получения при получении налоговой декларации (расчета) на бумажном носителе (в том числе через многофункциональный центр предоставления государственных и муниципальных услуг) либо передать налогоплательщику (плательщику сбора, плательщику страховых взносов, налоговому агенту) квитанцию о приеме в электронной форме - при получении налоговой декларации (расчета) по телекоммуникационным каналам связи или через личный кабинет налогоплательщика. (В редакции федеральных законов от 30.12.2006 № 268-ФЗ, от 29.06.2012 № 97-ФЗ, от 04.11.2014 № 347-ФЗ, от 03.07.2016 № 243-ФЗ, от 29.09.2019 № 325-ФЗ)\n\nПри отправке налоговой декларации (расчета) по почте днем ее представления считается дата отправки почтового отправления с описью вложения, если иное не предусмотрено настоящим Кодексом. При передаче налоговой декларации (расчета) по телекоммуникационным каналам связи или через личный кабинет налогоплательщика днем ее представления считается дата ее отправки, если иное не предусмотрено настоящим Кодексом. (В редакции федеральных законов от 04.11.2014 № 347-ФЗ, от 23.11.2020 № 374-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 27.07.2010 № 229-ФЗ)\n\nНалоговая декларация по налогу на доходы физических лиц на бумажном носителе также может быть представлена физическим лицом в налоговый орган через многофункциональный центр предоставления государственных и муниципальных услуг, который при принятии налоговой декларации обязан проставить по просьбе налогоплательщика на копии налоговой декларации отметку о принятии и дату ее приема. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nДнем представления налоговой декларации по налогу на доходы физических лиц в налоговый орган через многофункциональный центр предоставления государственных и муниципальных услуг считается день ее приема многофункциональным центром предоставления государственных и муниципальных услуг, если иное не предусмотрено настоящим Кодексом. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ) (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\n1) в ходе проведения мероприятий налогового контроля установлен факт подписания налоговой декларации (расчета) неуполномоченным лицом;\n\n2) физическое лицо, имеющее право без доверенности действовать от имени налогоплательщика (плательщика сбора, плательщика страховых взносов, налогового агента) и подписавшее налоговую декларацию (расчет), дисквалифицировано на основании вступившего в силу постановления о дисквалификации по делу об административном правонарушении и срок, на который установлена дисквалификация, не исте\n\nк ранее даты представления в налоговый орган такой налоговой декларации (расчета);\n\n3) в Едином государственном реестре записей актов гражданского состояния содержатся сведения о дате смерти физического лица, наступившей ранее даты подписания налоговой декларации (расчета) усиленной квалифицированной электронной подписью этого физического лица;\n\n4) в отношении лица, имеющего право без доверенности действовать от имени налогоплательщика (плательщика сбора, плательщика страховых взносов, налогового агента) и подписавшего налоговую декларацию (расчет), в Единый государственный реестр юридических лиц внесена запись о недостоверности сведений об указанном лице ранее даты представления в налоговый орган такой налоговой декларации (расчета);\n\n5) в отношении налогоплательщика (плательщика сбора, плательщика страховых взносов, налогового агента) - организации в Единый государственный реестр юридических лиц внесена запись о прекращении юридического лица (путем реорганизации, ликвидации или исключения из Единого государственного реестра юридических лиц по решению регистрирующего органа) ранее даты представления таким лицом в налоговый орган налоговой декларации (расчета);\n\n6) обстоятельства, предусмотренные пунктом 53 статьи 174 либо пунктом 7 статьи 431 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nФорма и формат уведомления о признании налоговой декларации (расчета) непредставленной утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение пунктом - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nНалогоплательщик (плательщик сбора, плательщика страховых взносов, налоговый агент) или его представитель подписывает налоговую декларацию (расчет), подтверждая достоверность и полноту сведений, указанных в налоговой декларации (расчете). (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nЕсли достоверность и полноту сведений, указанных в налоговой декларации (расчете), в том числе с применением усиленной квалифицированной электронной подписи при представлении налоговой декларации (расчета) в электронной форме, подтверждает уполномоченный представитель налогоплательщика (плательщика сбора, плательщика страховых взносов, налогового агента), в налоговой декларации (расчете) указывается основание представительства (наименование документа, подтверждающего наличие полномочий на подписание налоговой декларации (расчета). При этом к налоговой декларации (расчету) прилагается копия документа, подтверждающего полномочия представителя на подписание налоговой декларации (расчета). (В редакции  федеральных законов от 27.07.2010 № 229-ФЗ, от 29.06.2012 № 97-ФЗ, от 03.07.2016 № 243-ФЗ, от 23.11.2020 № 374-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 229-ФЗ) (Утратил силу  - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 30.12.2006 № 268-ФЗ) (Утратил силу - Федеральный закон от 27.07.2010 № 229-ФЗ)\n\nФедеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов, сборов, страховых взносов, не вправе включать в форму налоговой декларации (расчета), а налоговые органы не вправе требовать от налогоплательщиков (плательщиков сборов, плательщиков страховых взносов, налоговых агентов) включения в налоговую декларацию (расчет) сведений, не связанных с исчислением и (или) уплатой налогов, сборов, страховых взносов, за исключением: (В редакции федеральных законов от 27.07.2010 № 229-ФЗ; от 03.07.2016 № 243-ФЗ)\n\n1) вида документа: первичный (корректирующий);\n\n2) наименования налогового органа;\n\n3) места нахождения организации (ее обособленного подразделения) или места жительства физического лица;\n\n4) фамилии, имени, отчества физического лица или полного наименования организации (ее обособленного подразделения);\n\n5) номера контактного телефона налогоплательщика, плательщика страховых взносов; (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n6) сведений, подлежащих включению в налоговую декларацию в соответствии с главами 21, 23, 30 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 28.06.2013 № 134-ФЗ) (В редакции федеральных законов от 29.09.2019 № 325-ФЗ, от 23.11.2020 № 374-ФЗ)\n\n7) сведений о среднесписочной численности работников, подлежащих включению в расчет по страховым взносам. (Дополнение подпунктом - Федеральный закон от 28.01.2020 № 5-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 80. Налоговая декларация, расчеты","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e0a900994fa7e126f58af0e94644e1ef42dc1d3335e06be7849dad7f85ac0c68"},{"code_id":"NK_RF","article_number":"81","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n1. При обнаружении налогоплательщиком в поданной им в налоговый орган налоговой декларации факта неотражения или неполноты отражения сведений, а также ошибок, приводящих к занижению суммы налога, подлежащей уплате, налогоплательщик обязан внести необходимые изменения в налоговую декларацию и представить в налоговый орган уточненную налоговую декларацию в порядке, установленном настоящей статьей.\n\nПри обнаружении налогоплательщиком в поданной им в налоговый орган налоговой декларации недостоверных сведений, а также ошибок, не приводящих к занижению суммы налога, подлежащей уплате, налогоплательщик вправе внести необходимые изменения в налоговую декларацию и представить в налоговый орган уточненную налоговую декларацию в порядке, установленном настоящей статьей. При этом уточненная налоговая декларация, представленная после истечения установленного срока подачи декларации, не считается представленной с нарушением срока.\n\nАбзац. (Дополнение абзацем - Федеральный закон от 01.05.2022 № 120-ФЗ) (Утратил силу  - Федеральный закон от 28.12.2022 № 565-ФЗ)\n\n2. Если уточненная налоговая декларация представляется в налоговый орган до истечения срока подачи налоговой декларации, она считается поданной в день подачи уточненной налоговой декларации.\n\n3. Если уточненная налоговая декларация представляется в налоговый орган после истечения срока подачи налоговой декларации, но до истечения срока уплаты налога, то налогоплательщик освобождается от ответственности, если уточненная налоговая декларация была представлена до момента, когда налогоплательщик узнал об обнаружении налоговым органом факта неотражения или неполноты отражения сведений в налоговой декларации, а также ошибок, приводящих к занижению подлежащей уплате суммы налога, либо о назначении выездной налоговой проверки.\n\n4. Если уточненная налоговая декларация представляется в налоговый орган после истечения срока подачи налоговой декларации и срока уплаты налога, то налогоплательщик освобождается от ответственности в случаях:\n\n1) представления уточненной налоговой декларации до момента, когда налогоплательщик узнал об обнаружении налоговым органом неотражения или неполноты отражения сведений в налоговой декларации, а также ошибок, приводящих к занижению подлежащей уплате суммы налога, либо о назначении выездной налоговой проверки по данному налогу за данный период, при условии, что на момент представления уточненной налоговой декларации имеется положительное сальдо единого налогового счета в размере, соответствующем недостающей сумме налога и соответствующих ей пеней; (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n2) представления уточненной налоговой декларации после проведения выездной налоговой проверки за соответствующий налоговый период, по результатам которой не были обнаружены неотражение или неполнота отражения сведений в налоговой декларации, а также ошибки, приводящие к занижению подлежащей уплате суммы налога.\n\n5. Уточненная налоговая декларация представляется налогоплательщиком в налоговый орган по месту учета.\n\nУточненная налоговая декларация (расчет) представляется в налоговый орган по форме, действовавшей в налоговый период, за который вносятся соответствующие изменения.\n\n6. При обнаружении налоговым агентом в поданном им в налоговый орган расчете факта неотражения или неполноты отражения сведений, а также ошибок, приводящих к занижению или завышению суммы налога, подлежащей перечислению, налоговый агент обязан внести в указанный расчет необходимые изменения и представить в налоговый орган уточненный расчет в порядке, установленном настоящей статьей.\n\nУточненный расчет, представляемый налоговым агентом в налоговый орган, за исключением расчета сумм выплаченных иностранным организациям доходов и удержанных налогов за прошедший отчетный (налоговый) период, должен содержать данные в отношении только тех налогоплательщиков, в отношении которых обнаружены факты неотражения или неполноты отражения сведений, а также ошибки, приводящие к занижению или завышению суммы налога.\n\nУточненный расчет сумм выплаченных иностранным организациям доходов и удержанных налогов за прошедший отчетный (налоговый) период должен содержать данные в отношении всех налогоплательщиков, указанных в ранее представленном в налоговый орган расчете.\n\nПоложения, предусмотренные пунктами 3 и 4 настоящей статьи, касающиеся освобождения от ответственности, применяются также в отношении налоговых агентов при представлении ими уточненных расчетов.\n\n(Пункт в редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n61. В случае, если участник договора инвестиционного товарищества - управляющий товарищ, ответственный за ведение налогового учета (далее в настоящей статье - управляющий товарищ, ответственный за ведение налогового учета), предоставил участникам договора инвестиционного товарищества копию уточненного расчета финансового результата инвестиционного товарищества, налогоплательщики, уплачивающие налог на прибыль организаций, налог на доходы физических лиц в связи с их участием в договоре инвестиционного товарищества, обязаны подавать уточненную налоговую декларацию (расчет).\n\nУточненная налоговая декларация (расчет) должна быть представлена в налоговый орган по месту учета участника договора инвестиционного товарищества не позднее пятнадцати дней со дня, когда ему была передана копия уточненного расчета финансового результата инвестиционного товарищества.\n\nПри этом, если уточненная налоговая декларация (расчет) представляется в налоговый орган в сроки, указанные в абзаце втором настоящего пункта, участник договора инвестиционного товарищества, не являющийся управляющим товарищем, ответственным за ведение налогового учета, освобождается от ответственности.\n\nЕсли участник договора инвестиционного товарищества обжалует акты или решения налогового органа, которыми были изменены финансовые результаты инвестиционного товарищества, он обязан представить уточненную налоговую декларацию (расчет) не позднее пятнадцати дней со дня, когда вышестоящим налоговым органом было принято решение по результатам рассмотрения его жалобы.\n\n(Дополнение пунктом - Федеральный закон от 28.11.2011 № 336-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 81. Внесение изменений в налоговую декларацию, расчеты","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b428fa77b406da5c9f01a34a1059559b7af40d1470f00c1f76dbb45eb0e58796"},{"code_id":"NK_RF","article_number":"82","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\nНалоговый контроль проводится должностными лицами налоговых органов в пределах своей компетенции посредством налоговых проверок, получения объяснений налогоплательщиков, налоговых агентов и плательщиков сбора, плательщиков страховых взносов, проверки данных учета и отчетности, осмотра помещений и территорий, используемых для извлечения дохода (прибыли), а также в других формах, предусмотренных настоящим Кодексом. (В редакции федеральных законов от 27.07.2006 № 137-ФЗ; от 03.07.2016 № 243-ФЗ)\n\nОсобенности осуществления налогового контроля при выполнении соглашений о разделе продукции определяются главой 264 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 06.06.2003 № 65-ФЗ)\n\nОсобенности осуществления налогового контроля в форме налогового мониторинга устанавливаются разделом V2 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 04.11.2014 № 348-ФЗ)\n\n(Пункт в редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\nВ целях налогового контроля допускаются сбор, хранение и использование полученных от аудиторских организаций (индивидуальных аудиторов) документов (информации) в случаях, предусмотренных статьей 932 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 29.07.2018 № 231-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 09.07.1999 № 154-ФЗ)\n\nВ случае принятия налоговым органом решения о проведении налоговой проверки, налогового мониторинга с участием компетентного органа иностранного государства (территории) такому компетентному органу федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, сообщает в порядке, им определяемом, информацию о проведении налоговой проверки, налогового мониторинга, включая информацию о налоговом органе, которым принято решение о проведении налоговой проверки, налогового мониторинга, времени и месте проведения налоговой проверки, налогового мониторинга, а также об установленных настоящим Кодексом порядке и условиях проведения налоговой проверки, налогового мониторинга.\n\nПорядок организации работы по обеспечению участия и условия участия компетентного органа иностранного государства (территории) в налоговой проверке, налоговом мониторинге утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2017 № 340-ФЗ)","article_title":"Статья 82. Общие положения о налоговом контроле","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8b5370d5c7cd2516026f5379aa03a24d4ba6f3088af913b00bf65013315378f2"},{"code_id":"NK_RF","article_number":"83","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 23.12.2003 № 185-ФЗ)\n\nОрганизации, в состав которых входят обособленные подразделения, расположенные на территории Российской Федерации, подлежат постановке на учет в налоговых органах по месту нахождения каждого своего обособленного подразделения. (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nФедеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, вправе определять особенности учета в налоговых органах иностранных организаций, ино\n\nстранных граждан и лиц без гражданства, налогоплательщиков, указанных в пункте 1 статьи 2752 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 09.07.1999 № 154-ФЗ) (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 09.07.1999 № 154-ФЗ) (Утратил силу - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nОсобенности учета налогоплательщиков при выполнении соглашений о разделе продукции определяются главой 264 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 06.06.2003 № 65-ФЗ)\n\nФедеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, вправе определять особенности учета в налоговых органах крупнейших налогоплательщиков, в том числе в части установления критериев отнесения лиц к категории крупнейших налогоплательщиков. (Дополнение абзацем - Федеральный закон от 27.11.2018 № 424-ФЗ) (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nДля осуществления деятельности международной компании по месту нахождения ее обособленных подразделений (за исключением филиала, представительства), через которые иностранная организация, получившая статус международной компании, на момент принятия решения об изменении своего личного закона в порядке редомициляции осуществляла деятельность на территории Российской Федерации, такая международная компания представляет (направляет) сообщение, указанное в абзаце первом настоящего пункта, в налоговый орган не позднее 30 календарных дней со дня ее государственной регистрации в соответствии с Федеральным законом от 3 августа 2018 года № 290-ФЗ \"О международных компаниях и международных фондах\". (Дополнение абзацем - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\nПостановка на учет (снятие с учета) в налоговых органах иностранной организации по месту осуществления ею деятельности на территории Российской Федерации: (В редакции Федерального закона от 04.11.2014 № 347-ФЗ)\n\nчерез аккредитованные филиал, представительство осуществляется на основании сведений, содержащихся в государственном реестре аккредитованных филиалов, представительств иностранных юридических лиц; (Дополнение абзацем - Федеральный закон от 04.11.2014 № 347-ФЗ)\n\nчерез отделение иностранной некоммерческой неправительственной организации осуществляется на основании сведений, содержащихся в Едином государственном реестре юридических лиц; (Дополнение абзацем - Федеральный закон от 29.07.2018 № 230-ФЗ)\n\nчерез филиал или представительство международной организации, иностранной некоммерческой неправительственной организации осуществляется на основании сведений, содержащихся в реестре филиалов и представительств международных организаций и иностранных некоммерческих неправительственных организаций, сообщаемых органом, указанным в пункте 9 статьи 85 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 29.07.2018 № 230-ФЗ)\n\nчерез представительство иностранной религиозной организации осуществляется на основании сведений, содержащихся в реестре представительств иностранных религиозных организаций, открытых в Российской Федерации, сообщаемых органом, указанным в пункте 9 статьи 85 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 29.07.2018 № 230-ФЗ)\n\nчерез иные обособленные подразделения осуществляется на основании заявления о постановке на учет (снятии с учета) иностранной организации. Заявление о постановке на учет подается иностранной организацией в налоговый орган не позднее 30 календарных дней со дня начала осуществления ею деятельности на территории Российской Федерации. Заявление о снятии с учета подается иностранной организацией не позднее 15 календарных дней со дня прекращения ею деятельности на территории Российской Федерации. При подаче заявления о постановке на учет (снятии с учета) иностранная организация одновременно с указанным заявлением представляет в налоговый орган документы, которые необходимы для ее постановки на учет (снятия с учета) в налоговом органе и перечень которых утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 04.11.2014 № 347-ФЗ) (В редакции  федеральных законов от 29.07.2018 № 230-ФЗ, от 08.08.2024 № 259-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 04.11.2014 № 347-ФЗ) (Утратил силу - Федеральный закон от 29.07.2018 № 230-ФЗ)\n\nВ случае, если несколько обособленных подразделений организации находятся в одном муниципальном образовании, городах федерального значения Москве, Санкт-Петербурге и Севастополе на территориях, подведомственных разным налоговым органам, постановка организации на учет может быть осуществлена налоговым органом по месту нахождения одного из ее обособленных подразделений, определяемого этой организацией самостоятельно. Сведения о выборе налогового органа организация указывает в уведомлении, представляемом (направляемом) российской организацией в налоговый орган по месту ее нахождения, иностранной организацией - в выбранный ею налоговый орган. (В редакции Федерального закона от 29.11.2014 № 379-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 09.07.1999 № 154-ФЗ) (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nПри осуществлении организацией, являющейся официальной вещательной компанией в соответствии со статьей 31 указанного Федерального закона, деятельности в рамках договора, заключенного с Международным олимпийским комитетом или уполномоченной им организацией, через обособленное подразделение в течение периода, не превышающего двенадцати месяцев и включающего в себя период проведения XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, установленный частью 2 статьи 2 указанного Федерального закона, постановка на учет такой организации осуществляется на основании уведомления, направляемого данной организацией в налоговый орган.\n\nПри осуществлении организацией, являющейся иностранным организатором XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи в соответствии со статьей 3 указанного Федерального закона, деятельности в связи с организацией и проведением XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи в течение периода, не превышающего двенадцати месяцев и включающего в себя полностью или частично период проведения XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, установленный частью 2 статьи 2 указанного Федерального закона, постановка на учет такой организации осуществляется на основании уведомления, направляемого данной организацией в налоговый орган. (Дополнение абзацем - Федеральный закон от 23.07.2013 № 216-ФЗ)\n\nФорма уведомления, на основании которого происходит постановка на учет в налоговом органе организации, являющейся иностранным маркетинговым партнером Международного олимпийского комитета, официальной вещательной компанией и (или) иностранным организатором XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции Федерального закона от 23.07.2013 № 216-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 30.07.2010 № 242-ФЗ)\n\nФорма уведомления, на основании которого осуществляется постановка на учет в налоговом органе организаций, указанных в абзаце первом настоящего пункта, утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение пунктом - Федеральный закон от 07.06.2013 № 108-ФЗ)\n\nПостановка на учет организации в качестве участника договора инвестиционного товарищества - управляющего товарища, ответственного за ведение налогового учета, осуществляется налоговым органом по каждому договору инвестиционного товарищества отдельно.\n\n(Дополнение пунктом - Федеральный закон от 23.07.2013 № 248-ФЗ)\n\nПостановка на учет в налоговом органе иностранного лица, ранее снятого с учета в соответствии с пунктом 55 статьи 84 настоящего Кодекса, осуществляется налоговым органом на основании заявления о постановке на учет и документов, указанных в абзаце первом настоящего пункта.\n\n(Дополнение пунктом - Федеральный закон от 03.07.2016 № 244-ФЗ) (В редакции  Федерального закона от 29.05.2024 № 100-ФЗ)\n\nПри представлении в налоговый орган заявления о постановке на учет организацией, указанной в абзаце первом настоящего пункта, одновременно с указанным заявлением в налоговый орган представляются документы, необходимые для постановки на учет в налоговом органе, перечень которых утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nПри представлении российским банком в налоговый орган заявления о постановке на учет организации, указанной в абзаце первом настоящего пункта, в связи с открытием ей счета в указанном российском банке представление в налоговый орган с указанным заявлением документов, необходимых для постановки на учет такой организации, перечень которых утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, не требуется. (В редакции  федеральных законов от 01.05.2022 № 120-ФЗ, от 31.07.2023 № 389-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nПостановка на учет, снятие с учета организации или физического лица в налоговом органе по месту нахождения принадлежащих им недвижимого имущества и (или) транспортных средств осуществляются на основании сведений, сообщаемых органами и лицами, указанными в статье 85, пунктах 31 и 34 статьи 362, пункте 41 статьи 382, пункте 21 статьи 408 настоящего Кодекса, пункте 6 статьи 53 Земельного кодекса Российской Федерации. Организация подлежит постановке на учет в налоговых органах по месту нахождения недвижимого имущества, принадлежащего ей на праве собственности, праве постоянного (бессрочного) пользования, праве хозяйственного ведения или оперативного управления. (В редакции  федеральных законов от 23.12.2003 № 185-ФЗ, от 27.07.2010 № 229-ФЗ, от 23.11.2020 № 374-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nМестом нахождения имущества в целях настоящей статьи признается:\n\n1) для водных транспортных средств (за исключением маломерных судов) - место государственной регистрации транспортного средства; (В редакции федеральных законов от 09.07.1999 № 154-ФЗ, от 04.11.2014 № 347-ФЗ)\n\n11) для воздушных транспортных средств - место нахождения организации или место жительства (место пребывания) физического лица - собственника транспортного средства, а при отсутствии таковых - место государственной регистрации транспортного средства; (Дополнение подпунктом - Федеральный закон от 04.11.2014 № 347-ФЗ) (В редакции Федерального закона от 29.09.2019\n\n2) для транспортных средств, не указанных в подпунктах 1 и 11 настоящего пункта, - место нахождения организации (ее обособленного подразделения) или место жительства (место пребывания) физического лица, на которых в соответствии с законодательством Российской Федерации зарегистрировано транспортное средство;  (В редакции  федеральных законов от 09.07.1999 № 154-ФЗ, от 29.06.2004 № 58-ФЗ, от 23.07.2013 № 248-ФЗ, от 02.11.2013 № 306-ФЗ, от 04.11.2014 № 347-ФЗ, от 31.07.2023 № 389-ФЗ)\n\n3) для иного недвижимого имущества - место фактического нахождения имущества. (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\nПостановка на учет международной компании в налоговом органе по месту нахождения недвижимого имущества, принадлежавшего иностранной организации, получившей статус этой международной компании в порядке редомициляции, осуществляется на основании сведений о государственной регистрации международной компании, содержащихся в Едином государственном реестре юридических лиц. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 04.11.2014 № 347-ФЗ)\n\nПостановка на учет адвоката осуществляется налоговым органом по месту его жительства на основании сведений, сообщаемых адвокатской палатой субъекта Российской Федерации в соответствии со статьей 85 настоящего Кодекса. (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\nПостановка на учет арбитражного управляющего, занимающихся частной практикой оценщика и патентного поверенного осуществляется налоговым органом по месту их жительства на основании сведений, сообщаемых в соответствии со статьей 85 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 243-ФЗ) (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\nПостановка на учет медиатора осуществляется налоговым органом по месту жительства этого физического лица (месту его пребывания - при отсутствии у этого физического лица места жительства на территории Российской Федерации) на основании заявления этого физического лица, представляемого в любой налоговый орган по своему выбору. (Дополнение абзацем - Федеральный закон от 30.11.2016 № 401-ФЗ)\n\n(Пункт в редакции Федерального закона от 23.12.2003 № 185-ФЗ)\n\nПостановка на учет в налоговом органе физического лица, не являющегося индивидуальным предпринимателем и не имеющего на территории Российской Федерации места жительства (места пребывания), принадлежащих ему недвижимого имущества и (или) транспортных средств, осуществляется на основании заявления такого физического лица налоговым органом, в который по выбору физического лица представлено это заявление. (Дополнение абзацем - Федеральный закон от 29.07.2018 № 232-ФЗ)\n\n(Пункт в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nПри наличии нескольких организаций (индивидуальных предпринимателей), являющихся источниками выплаты доходов указанным иностранному гражданину, лицу без гражданства, такое физическое лицо подлежит постановке на учет в налоговом органе на основании первых сведений из представленных в соответствии с пунктом 4 статьи 2142 или пунктом 2 статьи 230 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 325-ФЗ) (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)","article_title":"Статья 83. Учет организаций и физических лиц","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6a63680cd37087d9b45cdd75482810d590008b06ec7c0ff408cbe07640fb8d31"},{"code_id":"NK_RF","article_number":"84","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 23.12.2003 № 185-ФЗ)\n\nПри постановке на учет физических лиц в состав сведений об указанных лицах включаются также их персональные данные:\n\nфамилия, имя, отчество;\n\nдата и место рождения;\n\nместо жительства;\n\nданные паспорта или иного документа, удостоверяющего личность налогоплательщика;\n\nданные о гражданстве.\n\n(Пункт в редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nНалоговый орган обязан осуществить постановку на учет российской организации по месту нахождения ее обособленного подразделения (за исключением филиала, представительства) в течение пяти дней со дня получения сообщения от этой организации в соответствии с пунктом 2 статьи 23 настоящего Кодекса, российской организации по месту нахождения ее филиала, представительства, иностранной некоммерческой неправительственной организации по месту осуществления ею деятельности на территории Российской Федерации через отделение на основании сведений, содержащихся в Едином государственном реестре юридических лиц, в течение пяти дней со дня внесения соответствующей записи в этот реестр, иностранной организации по месту осуществления ею деятельности на территории Российской Федерации через аккредитованные филиал, представительство на основании сведений, содержащихся в государственном реестре аккредитованных филиалов, представительств иностранных юридических лиц, в течение пяти дней со дня внесения соответствующей записи в этот реестр, через иное обособленное подразделение в течение пяти дней со дня получения от этой организации заявления о постановке на учет и всех необходимых документов и в тот же срок выдать (направить) российской организации, иностранной организации соответственно уведомление о постановке на учет в налоговом органе, свидетельство о постановке на учет в налоговом органе. (В редакции федеральных законов от 04.11.2014 № 347-ФЗ; от 03.07.2016 № 243-ФЗ)\n\nНалоговый орган обязан осуществить постановку на учет международной организации, иностранной некоммерческой неправительственной организации, иностранной религиозной организации по месту осуществления ими деятельности на территории Российской Федерации через филиалы, представительства в течение пяти дней со дня получения соответствующих сведений, сообщенных органом, указанным в пункте 9 статьи 85 настоящего Кодекса, и в тот же срок выдать (направить) такой организации свидетельство о постановке на учет в налоговом органе. (Дополнение абзацем - Федеральный закон от 29.07.2018 № 230-ФЗ)\n\nНалоговый орган, осуществивший постановку на учет вновь созданной российской организации или индивидуального предпринимателя, обязан выдать (направить) российской организации свидетельство о постановке на учет в налоговом органе, индивидуальному предпринимателю - свидетельство о постановке на учет в налоговом органе (если ранее указанное свидетельство не выдавалось или не направлялось) и уведомление о постановке на учет в налоговом органе, подтверждающее постановку на учет в налоговом органе физического лица в качестве индивидуального предпринимателя. (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nНалоговый орган обязан осуществить постановку на учет (снятие с учета) организации, физического лица по месту нахождения принадлежащих им недвижимого имущества и (или) транспортных средств, а также нотариуса, занимающегося частной практикой, адвоката, арбитражного управляющего, занимающихся частной практикой оценщика, патентного поверенного, медиатора по месту их жительства в течение пяти дней со дня получения соответствующих сведений, сообщенных органами и лицами, указанными в абзаце втором пункта 5 статьи 83 настоящего Кодекса, заявления о постановке на учет (снятии с учета) медиатора. Налоговый орган в тот же срок обязан выдать (направить): (В редакции  федеральных законов от 03.07.2016 № 243-ФЗ, от 30.11.2016 № 401-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nорганизации (физическому лицу) - уведомление о постановке на учет в налоговом органе, подтверждающее постановку на учет в налоговом органе по месту нахождения принадлежащих ей (ему) недвижимого имущества и (или) транспортных средств (уведомление о снятии с учета в налоговом органе);\n\nнотариусу, занимающемуся частной практикой (адвокату), - свидетельство о постановке на учет в налоговом органе (если ранее указанное свидетельство не выдавалось или не направлялось) и (или) уведомление о постановке на учет в налоговом органе, подтверждающее постановку на учет в налоговом органе физического лица в качестве нотариуса, занимающегося частной практикой (адвоката) (уведомление о снятии с учета в налоговом органе); (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nарбитражному управляющему, занимающимся частной практикой оценщику и патентному поверенному, медиатору - уведомление о постановке на учет в налоговом органе, подтверждающее постановку на учет в налоговом органе физического лица в качестве соответственно арбитражного управляющего, занимающихся частной практикой оценщика, патентного поверенного, медиатора (уведомление о снятии с учета в налоговом органе). (Дополнение абзацем - Федеральный закон от 03.07.2016 № 243-ФЗ) (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\nНалоговый орган обязан осуществить постановку на учет (снятие с учета) организации и физического лица по иным основаниям, предусмотренным настоящим Кодексом, в течение пяти дней со дня получения соответствующего заявления, или сведений о рождении (смерти), содержащихся в Едином государственном реестре записей актов гражданского состояния, или сведений, полученных в соответствии со статьей 85 настоящего Кодекса, если иное не предусмотрено абзацем десятым настоящего пункта, и в тот же срок выдать (направить) уведомление о постановке на учет (уведомление о снятии с учета) в налоговом органе, если иное не предусмотрено настоящим Кодексом. На основании сведений о смерти, содержащихся в Едином государственном реестре записей актов гражданского состояния, снятие физического лица с учета в налоговых органах осуществляется по всем основаниям, предусмотренным настоящим Кодексом. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nВ случае необходимости оформления иностранному гражданину или лицу без гражданства разрешения на работу в сокращенные сроки в соответствии с законодательством Российской Федерации налоговый орган обязан осуществить постановку на учет иностранного гражданина или лица без гражданства, в отношении которых приняты к рассмотрению документы для оформления разрешения на работу, по месту их пребывания в течение трех дней со дня получения соответствующих сведений от органа, осуществляющего выдачу иностранным гражданам и лицам без гражданства разрешений на работу, и в тот же срок направить сведения о постановке на учет в налоговом органе иностранного гражданина или лица без гражданства в орган, осуществляющий выдачу иностранным гражданам и лицам без гражданства разрешений на работу.\n\nНалоговый орган обязан осуществить постановку на учет иностранного лица, указанного в пунктах 46 и 410 статьи 83 настоящего Кодекса, в течение 30 дней со дня получения заявления о постановке на учет и иных необходимых документов и в тот же срок направить этому иностранному лицу уведомление о постановке на учет в налоговом органе по адресу электронной почты, указанному в заявлении о постановке на учет. В случае выявления налоговым органом недостоверных сведений, содержащихся в представленных иностранным лицом в налоговый орган заявлении о постановке на учет и (или) иных документах, постановка на учет в налоговом органе не осуществляется. При этом налоговый орган информирует такое лицо о данном факте. В этом случае постановка на учет иностранного лица осуществляется в течение 30 дней со дня получения налоговым органом заявления о постановке на учет и иных необходимых документов, содержащих достоверные сведения. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 244-ФЗ) (В редакции  Федерального закона от 29.05.2024 № 100-ФЗ)\n\nПри постановке на учет (снятии с учета) физического лица на основании пункта 73 статьи 83 настоящего Кодекса либо на основании сведений, содержащихся в Едином государственном реестре записей актов гражданского состояния, уведомление о постановке на учет (снятии с учета) в налоговом органе не выдается (не направляется). (Дополнение абзацем - Федеральный закон от 30.11.2016 № 401-ФЗ) (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nНалоговый орган обязан осуществить постановку на учет иностранной организации по основанию, предусмотренному пунктом 49 статьи 83 настоящего Кодекса, в течение пяти дней со дня получения от такой организации заявления о постановке на учет и документов, необходимых для постановки на учет в налоговом органе, или со дня получения от российского банка, в котором такой организации открывается счет, заявления о постановке на учет такой организации и в тот же срок выдать (направить) свидетельство о постановке на учет в налоговом органе такой организации или в электронной форме российскому банку, в котором такой организации открывается счет, для передачи такой организации. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ) (В редакции Федерального закона от 01.05.2022 № 120-ФЗ)\n\n(Пункт в редакции Федерального закона от 23.07.2013 № 248-ФЗ)\n\nаправить) указанной организации (индивидуальному предпринимателю) уведомление о постановке на учет в налоговом органе таких иностранного гражданина, лица без гражданства. (Дополнение пунктом - Федеральный закон от 29.09.2019 № 325-ФЗ) (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nИзменения в сведениях об обособленных подразделениях (за исключением филиалов и представительств) российских организаций подлежат учету налоговыми органами по месту нахождения таких обособленных подразделений на основании сообщений, представляемых (направляемых) российской организацией в соответствии с пунктом 2 статьи 23 настоящего Кодекса.\n\nИзменения в сведениях об иностранных организациях (в том числе об аккредитованных филиалах, представительствах, об иных обособленных подразделениях, за исключением указанных в абзацах первом и пятом настоящего пункта) подлежат учету налоговыми органами по месту нахождения указанных обособленных подразделений соответственно на основании сведений, содержащихся в государственном реестре аккредитованных филиалов, представительств иностранных юридических лиц, на основании заявления иностранной организации. Одновременно с подачей такого заявления иностранная организация представляет документы, подтверждающие изменения в этих сведениях.  (В редакции федеральных законов от 23.07.2013 № 248-ФЗ, от 04.11.2014 № 347-ФЗ, от 29.07.2018 № 230-ФЗ, от 29.09.2019 № 325-ФЗ)\n\nИзменения в сведениях об иностранном лице, состоящем на учете в налоговом органе в соответствии с пунктом 46 или 410 статьи 83 настоящего Кодекса, подлежат учету налоговым органом на основании заявления такого иностранного лица. Одновременно с подачей указанного заявления иностранное лицо представляет документы, подтверждающие изменения в этих сведениях. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 244-ФЗ) (В редакции  Федерального закона от 29.05.2024 № 100-ФЗ)\n\nИзменения в сведениях о международной организации, иностранной некоммерческой неправительственной организации, иностранной религиозной организации, осуществляющих деятельность на территории Российской Федерации, их филиалах, представительствах подлежат учету налоговыми органами по месту нахождения таких филиалов, представительств на основании сведений, сообщенных органом, указанным в пункте 9 статьи 85 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 29.07.2018 № 230-ФЗ)\n\nИзменения в сведениях о персональных данных индивидуальных предпринимателей, физических лиц, не являющихся индивидуальными предпринимателями, а также нотариусов, занимающихся частной практикой, адвокатов, арбитражных управляющих, занимающихся частной практикой оценщиков, патентных поверенных, медиаторов подлежат учету налоговым органом по месту их жительства на основании сведений, содержащихся в Едином государственном реестре записей актов гражданского состояния, и сведений, полученных в соответствии с пунктами 3 и 8 статьи 85 настоящего Кодекса. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nИзменения в сведениях об иностранной организации, состоящей на учете в налоговом органе в соответствии с пунктом 49 статьи 83 настоящего Кодекса, подлежат учету налоговым органом на основании заявления такой организации, представляемого в налоговый орган такой организацией или российским банком, в котором такой организации открыт счет. При представлении в налоговый орган такой организацией указанного заявления одновременно с ним в налоговый орган представляются документы, подтверждающие изменения в сведениях о такой иностранной организации. При представлении в налоговый орган указанного заявления российским банком, в котором иностранной организации открыт счет, представление иных документов, подтверждающих изменения в сведениях о такой организации не требуется. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ) (В редакции Федерального закона от 01.05.2022 № 120-ФЗ)\n\n(Пункт в редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nроссийской организации (в том числе в качестве ответственного участника консолидированной группы налогоплательщиков, в качестве участника договора инвестиционного товарищества - управляющего товарища, ответственного за ведение налогового учета) по месту ее нахождения, по месту нахождения ее филиала, представительства, воздушного транспортного средства, транспортного средства, указанного в подпункте 2 пункта 5 статьи 83 настоящего Кодекса, иностранной некоммерческой неправительственной организации по месту осуществления деятельности на территории Российской Федерации через отделение - в течение пяти дней со дня внесения соответствующих сведений в Единый государственный реестр юридических лиц; (В редакции федеральных законов от 23.07.2013 № 248-ФЗ; от 03.07.2016 № 243-ФЗ)\n\nроссийской организации по месту нахождения иного обособленного подразделения - в течение пяти дней со дня получения сообщения, представляемого (направляемого) российской организацией в соответствии с пунктом 2 статьи 23 настоящего Кодекса;\n\nиностранной организации по месту осуществления ею деятельности на территории Российской Федерации через аккредитованные филиал, представительство - в течение пяти дней со дня внесения соответствующих сведений, содержащихся в государственном реестре аккредитованных филиалов, представительств иностранных юридических лиц; (Дополнение абзацем - Федеральный закон от 04.11.2014 № 347-ФЗ)\n\nмеждународной организации, иностранной некоммерческой неправительственной организации, иностранной религиозной организации по месту осуществления ими деятельности на территории Российской Федерации через филиалы, представительства - в течение пяти дней со дня получения соответствующих сведений, сообщенных органом, указанным в пункте 9 статьи 85 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 29.07.2018 № 230-ФЗ)\n\nиностранной организации по месту осуществления деятельности на территории Российской Федерации через иное обособленное подразделение - в течение пяти дней со дня получения соответствующего заявления, если иное не предусмотрено настоящим пунктом; (В редакции Федерального закона от 04.11.2014 № 347-ФЗ)\n\nфизического лица (в том числе зарегистрированного в качестве индивидуального предпринимателя, нотариуса, занимающегося частной практикой, адвоката, арбитражного управляющего, занимающихся частной практикой оценщика, патентного поверенного, медиатора) по месту жительства, месту нахождения воздушного транспортного средства, месту нахождения транспортного средства, указанного в подпункте 2 пункта 5 статьи 83 настоящего Кодекса, - в течение пяти дней со дня получения сведений о факте регистрации, сообщаемых в соответствии со статьей 85 настоящего Кодекса органами, осуществляющими регистрацию физических лиц по месту их жительства. (В редакции федеральных законов от 03.07.2016 № 243-ФЗ; от 30.11.2016 № 401-ФЗ)\n\nПостановка на учет организации в налоговом органе по новому месту ее нахождения, месту нахождения обособленного подразделения организации осуществляется на основании документов, полученных от налогового органа соответственно по прежнему месту нахождения организации, месту нахождения обособленного подразделения организации. (В редакции Федерального закона от 04.11.2014 № 347-ФЗ)\n\nПостановка на учет физического лица в налоговом органе по новому месту его жительства осуществляется на основании сведений о факте регистрации, сообщаемых в соответствии со статьей 85 настоящего Кодекса органами, осуществляющими регистрацию физических лиц по месту их жительства. (Дополнение абзацем - Федеральный закон от 04.11.2014 № 347-ФЗ)\n\nСнятие с учета в налоговом органе физического лица может также осуществляться этим налоговым органом при получении им соответствующих сведений о постановке на учет этого физического лица в другом налоговом органе по месту его жительства.\n\n(Пункт в редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nВ случаях прекращения российской организацией деятельности через филиал или представительство (закрытия филиала или представительства), иностранной некоммерческой неправительственной организацией деятельности на территории Российской Федерации через отделение снятие с учета российской организации налоговым органом по месту нахождения этого филиала (представительства), иностранной организации налоговым органом по месту осуществления деятельности на территории Российской Федерации через это отделение осуществляется на основании сведений, содержащихся в Едином государственном реестре юридических лиц, но не ранее окончания выездной налоговой проверки в случае ее проведения.\n\nВ случаях прекращения иностранной организацией деятельности через аккредитованные филиал или представительство снятие с учета иностранной организации налоговым органом по месту осуществления деятельности на территории Российской Федерации осуществляется на основании сведений, содержащихся в государственном реестре аккредитованных филиалов, представительств иностранных юридических лиц, но не ранее окончания выездной налоговой проверки в случае ее проведения. (Дополнение абзацем - Федеральный закон от 04.11.2014 № 347-ФЗ) (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\nВ случае исключения филиала, представительства международной организации, иностранной некоммерческой неправительственной организации из реестра филиалов и представительств международных организаций и иностранных некоммерческих неправительственных организаций, исключения представительства иностранной религиозной организации из реестра представительств иностранных религиозных организаций, открытых в Российской Федерации, снятие с учета филиала, представительства международной организации, иностранной некоммерческой неправительственной организации, представительства иностранной религиозной организации осуществляется налоговым органом по месту нахождения такого филиала, представительства на основании сведений, сообщенных органом, указанным в пункте 9 статьи 85 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 29.07.2018 № 230-ФЗ)\n\nВ случае прекращения деятельности (закрытия) иного обособленного подразделения российской организации (иностранной организации) снятие с учета организации налоговым органом по месту нахождения этого обособленного подразделения осуществляется на основании полученного налоговым органом сообщения российской организации в соответствии с пунктом 2 статьи 23 настоящего Кодекса (заявления иностранной организации) в течение 10 дней со дня получения этого сообщения (заявления), но не ранее окончания выездной налоговой проверки организации в случае ее проведения.\n\nВ случае непредставления международной компанией сообщения, предусмотренного абзацем первым пункта 4 статьи 83 настоящего Кодекса, налоговый орган осуществляет снятие с учета иностранной организации, получившей статус международной компании, по месту нахождения ее обособленного подразделения по истечении 30 календарных дней со дня государственной регистрации международной компании. (Дополнение абзацем - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\nВ случаях освобождения от должности нотариуса, занимающегося частной практикой, прекращения статуса адвоката, прекращения членства арбитражного управляющего, оценщика, занимающегося частной практикой, в соответствующей саморегулируемой организации, исключения патентного поверенного, занимающегося частной практикой, из Реестра патентных поверенных Российской Федерации, прекращения занятия частной практикой оценщиком, патентным поверенным, прекращения деятельности медиатора снятие их с учета осуществляется налоговым органом на основании сведений, сообщаемых органами, указанными в статье 85 настоящего Кодекса, заявления о снятии с учета медиатора. (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\nВ случае закрытия счета в российском банке иностранной организации, состоящей на учете в налоговом органе по основанию, предусмотренному пунктом 49 статьи 83 настоящего Кодекса, снятие с учета такой организации осуществляется налоговым органом в течение пяти дней со дня получения в соответствии со статьей 86 настоящего Кодекса сообщения о закрытии такой организации последнего счета в российских банках. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ) (В редакции Федерального закона от 01.05.2022 № 120-ФЗ)\n\n(Пункт в редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nПри поступлении в налоговый орган заявления о постановке на учет (снятии с учета) в налоговом органе по основаниям, предусмотренным настоящим Кодексом, заявления иностранной организации, уведомления о выборе налогового органа для постановки на учет организации по месту нахождения одного из ее обособленных подразделений, сообщения, предусмотренного подпунктом 3 и (или) 31 пункта 2 статьи 23 настоящего Кодекса, по телекоммуникационным каналам связи или через личный кабинет налогоплательщика свидетельство о постановке на учет в налоговом органе и (или) уведомление о постановке на учет в налоговом органе (уведомление о снятии с учета в налоговом органе) направляются организации или физическому лицу, в том числе индивидуальному предпринимателю, в электронной форме по телекоммуникационным каналам связи или через личный кабинет налогоплательщика. При этом налоговый орган обязан представить предусмотренные настоящим пунктом документы в письменной форме на бумажном носителе по запросу организации или физического лица, в том числе индивидуального предпринимателя. (В редакции Федерального закона от 03.07.2016 № 244-ФЗ)\n\nФормы и форматы указанных в настоящей статье заявления о постановке на учет (снятии с учета) в налоговом органе по основаниям, предусмотренным настоящим Кодексом, заявления иностранной организации, уведомлений, предусмотренных статьей 83 настоящего Кодекса, запроса, документов, подтверждающих постановку на учет (снятие с учета) в налоговом органе, порядок заполнения форм заявления, уведомления, запроса и порядок представления заявления, уведомления, запроса в налоговый орган в электронной форме, а также порядок направления налоговым органом заявителю документов, подтверждающих постановку на учет (снятие с учета) в налоговом органе в электронной форме, утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции федеральных законов от 29.06.2012 № 97-ФЗ, от 30.11.2016 № 401-ФЗ, от 29.09.2019 № 325-ФЗ)\n\nЗаявление о постановке на учет (снятии с учета) в налоговом органе иностранного лица по основаниям, предусмотренным пунктами 46 и 410 статьи 83 настоящего Кодекса, и иные необходимые документы могут быть представлены в налоговый орган через представителя, по почте заказным письмом или в электронной форме через официальный сайт федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, в информационно-телекоммуникационной сети \"Интернет\" без применения усиленной квалифицированной электронной подписи.  (Дополнение абзацем - Федеральный закон от 03.07.2016 № 244-ФЗ) (В редакции федеральных законов от 31.07.2023 № 389-ФЗ, от 29.05.2024 № 100-ФЗ)\n\nПорядок направления о\n\nрганизации (индивидуальному предпринимателю), являющейся источником выплаты доходов иностранному гражданину, лицу без гражданства, поставленным на учет в налоговом органе в соответствии с пунктом 74 статьи 83 настоящего Кодекса, уведомления о постановке на учет в налоговом органе иностранного гражданина, лица без гражданства, предусмотренный настоящим пунктом, применяется также в случае поступления в налоговый орган сведений, указанных в пункте 74 статьи 83 настоящего Кодекса, по телекоммуникационным каналам связи. При этом налоговый орган по запросу иностранного гражданина, лица без гражданства, поставленных на учет в налоговом органе в соответствии с пунктом 74 статьи 83 настоящего Кодекса, обязан представить им указанное уведомление в письменной форме на бумажном носителе. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nЕсли заявление о постановке на учет в налоговом органе иностранной организации или заявление об изменении в сведениях о такой организации по основаниям, предусмотренным пунктом 49 статьи 83 и пунктом 3 статьи 84 настоящего Кодекса, представляется российским банком, в котором иностранной организации открывается счет, то такое заявление представляется в налоговый орган в электронной форме и должно быть заверено усиленной квалифицированной электронной подписью уполномоченного лица указанного российского банка. Порядок направления российскими банками в налоговые органы указанных заявлений утверждается Центральным банком Российской Федерации по согласованию с федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ) (В редакции Федерального закона от 01.05.2022 № 120-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 27.07.2010 № 229-ФЗ) (В редакции Федерального закона от 19.07.2011 № 245-ФЗ)\n\n1) выявление налоговым органом недостоверных сведений, содержащихся в представленных таким лицом в налоговый орган заявлении о постановке на учет и (или) иных документах, на основании которых оно было поставлено на учет в налоговом органе; (В редакции  Федерального закона от 29.05.2024 № 100-ФЗ)\n\n2) неисполнение таким лицом требования об уплате задолженности в течение 12 месяцев со дня истечения срока исполнения указанного требования. Положения настоящего подпункта не применяются, если таким лицом подано заявление о снятии с учета в налоговом органе в соответствии с пунктом 54 настоящей статьи; (В редакции  федеральных законов от 14.07.2022 № 263-ФЗ, от 29.05.2024 № 100-ФЗ)\n\n3) неисполнение таким лицом требования о представлении документов (информации), направленного налоговым органом в соответствии со статьей 93 настоящего Кодекса, в течение трех месяцев со дня истечения срока исполнения указанного требования; (В редакции  Федерального закона от 29.05.2024 № 100-ФЗ)\n\n4) непредставление таким лицом налоговой декларации по налогу на добавленную стоимость в налоговый орган в течение шести месяцев со дня истечения установленного срока ее представления при наличии у налогового органа информации, подтверждающей факт оказания в соответствующем налоговом периоде физическим лицам, не являющимся индивидуальными предпринимателями, услуг, указанных в пункте 1 статьи 1742 настоящего Кодекса, местом реализации которых признается территория Российской Федерации, а также факт реализации посредством электронной торговой площадки покупателям - физическим лицам товаров, местом реализации которых признается территория Российской Федерации согласно подпункту 4 пункта 1 статьи 147 настоящего Кодекса; (В редакции  федеральных законов от 27.11.2017 № 335-ФЗ, от 31.07.2023 № 389-ФЗ, от 29.05.2024 № 100-ФЗ)\n\n5) неуплата таким иностранным лицом в установленный срок сумм недоимки по налогу на добавленную стоимость, задолженности по пеням и штрафам, восстановленных в соответствии с пунктом 11 статьи 59 настоящего Кодекса. (В редакции  Федерального закона от 29.05.2024 № 100-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 03.07.2016 № 244-ФЗ)\n\nВ случае, указанном в настоящем пункте, уведомление о снятии с учета в налоговом органе иностранного гражданина, лица без гражданства организации (индивидуальному предпринимателю), являвшейся источником выплаты доходов этим иностранному гражданину, лицу без гражданства, не направляется.\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 325-ФЗ) (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nНалоговый орган вправе осуществить снятие с учета иностранной организации, состоящей на учете в соответствии с пунктом 410 статьи 83 настоящего Кодекса, без представления заявления о снятии с учета в случае непредставления такой иностранной организацией расчета сумм налога на доходы физических лиц, исчисленных и удержанных налоговым агентом, а также документа, содержащего сведения о доходах физических лиц за истекший налоговый период и суммах налога, исчисленных, удержанных и перечисленных в бюджетную систему Российской Федерации за этот налоговый период по каждому физическому лицу, подлежащих представлению в соответствии с пунктом 2 статьи 230 настоящего Кодекса, в течение трех календарных лет, следующих за годом, в котором такой расчет был представлен в последний раз.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nНалоговый орган указывает идентификационный номер налогоплательщика во всех направляемых ему уведомлениях.\n\nКаждый налогоплательщик указывает свой идентификационный номер в подаваемых в налоговый орган декларации, отчете, заявлении или ином документе, а также в иных случаях, предусмотренных законодательством, если иное не предусмотрено настоящей статьей. (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\nПорядок и условия присвоения, применения, а также изменения идентификационного номера налогоплательщика определяются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 29.06.2004 № 58-ФЗ; от 19.07.2011 № 245-ФЗ)\n\nФизические лица, не являющиеся индивидуальными предпринимателями, вправе не указывать идентификационные номера налогоплательщиков в представляемых в налоговые органы налоговых декларациях, заявлениях или иных документах, указывая при этом свои персональные данные, предусмотренные пунктом 1 статьи 84 настоящего Кодекса, или номер записи единого федерального информационного регистра, содержащего сведения о населении Российской Федерации, полученный в соответствии с Федеральным законом от 8 июня 2020 года № 168-ФЗ \"О едином федеральном информационном регистре, содержащем сведения о населении Российской Федерации\" (далее - федеральный регистр сведений о населении). (Дополнение абзацем - Федеральный закон от 27.07.2006 № 137-ФЗ) (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 23.07.2013 № 248-ФЗ)\n\n(Пункт в редакции Федерального закона от 19.07.2011 № 245-ФЗ)","article_title":"Статья 84. Порядок постановки на учет и снятия с учета организаций и физических лиц. Идентификационный номер налогоплательщика","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"15f0b9daba7ab3c78e2b39ecf8bdaa49cb0cb67405e693eee8654cbbb3bcbfb0"},{"code_id":"NK_RF","article_number":"85","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 23.12.2003 № 185-ФЗ; от 27.07.2010 № 229-ФЗ)\n\nОрганы, осуществляющие выдачу иностранным гражданам или лицам без гражданства разрешений на работу или патентов, обязаны сообщать сведения о постановке на миграционный учет по месту пребывания иностранных граждан или лиц без гражданства, которые не состоят на учете в налоговых органах и в отношении которых приняты к рассмотрению документы для оформления разрешения на работу или патента, в налоговые органы по месту своего нахождения не позднее дня, следующего за днем принятия указанных документов.\n\nАбзац. (Утратил силу - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n(Пункт в редакции Федерального закона от 23.07.2013 № 248-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 243-ФЗ) (Утратил силу - Федеральный закон от 30.11.2016 № 401-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 243-ФЗ) (Утратил силу - Федеральный закон от 30.11.2016 № 401-ФЗ)\n\nФедеральный орган исполнительной власти по интеллектуальной собственности обязан не позднее 10-го числа каждого месяца сообщать в налоговый орган по месту своего нахождения сведения за предшествующий месяц о занимающихся частной практикой патентных поверенных, зарегистрированных в Реестре патентных поверенных Российской Федерации, исключенных из указанного реестра, восстановленных в указанном реестре, о прекращении патентным поверенным занятия частной практикой.\n\n(Дополнение пунктом - Федеральный закон от 30.11.2016 № 401-ФЗ)\n\nо фактах первичной выдачи или замены документа, удостоверяющего личность гражданина Российской Федерации на территории Российской Федерации, и об изменениях персональных данных, содержащихся во вновь выданном документе, в течение пяти дней со дня выдачи нового документа; (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\nо фактах подачи гражданином в эти органы заявления об утрате документа, удостоверяющего личность гражданина Российской Федерации на территории Российской Федерации, в течение трех дней со дня его подачи.\n\n(Дополнение пунктом - Федеральный закон от 23.12.2003 № 185-ФЗ)\n\n1) о фактах первичной выдачи паспорта граж\n\nданина Российской Федерации, удостоверяющего личность гражданина Российской Федерации за пределами территории Российской Федерации, выдачи в дополнение к действующему или замены указанного паспорта и об изменениях персональных данных, содержащихся во вновь выданном паспорте, в течение пяти дней со дня выдачи нового паспорта;\n\n2) о фактах подачи гражданином в указанные органы заявления об объявлении паспорта гражданина Российской Федерации, удостоверяющего личность гражданина Российской Федерации за пределами территории Российской Федерации, недействительным в связи с его утратой в течение трех дней со дня подачи такого заявления.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nОрган, уполномоченный вести реестр филиалов и представительств международных организаций и иностранных некоммерческих неправительственных организаций, реестр представительств иностранных религиозных организаций, открытых в Российской Федерации, обязан сообщать в налоговый орган по месту своего нахождения о внесении сведений в соответствующий реестр (об изменениях, вносимых в реестр) в течение 10 дней со дня внесения указанных сведений (изменений). (Дополнение абзацем - Федеральный закон от 27.07.2010 № 229-ФЗ; в редакции Федерального закона от 29.07.2018 № 230-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\n1) о регистрации (снятии с регистрационного учета) застрахованных лиц в системе обязательного пенсионного страхования, а также об изменениях указанных сведений в течение 10 дней со дня соответствующей регистрации (снятия с регистрационного учета) или изменения указанных сведений;\n\n2) о лицах, в отношении которых органами Фонда пенсионного и социального страхования Российской Федерации приняты решения о назначении пенсии, прекращении выплаты пенсии, о лицах, соответствующих условиям, необходимым для назначения пенсии в соответствии с законодательством Российской Федерации, действовавшим на 31 декабря 2018 года, о лицах, сведения о которых размещены в государственной информационной системе \"Единая централизованная цифровая платформа в социальной сфере\", относящихся к инвалидам, включая детей-инвалидов, ветеранам боевых действий, ветеранам труда, лицам, имеющим право на получение социальной поддержки в соответствии с Законом Российской Федерации от 15 мая 1991 года № 1244-I \"О социальной защите граждан, подвергшихся воздействию радиации вследствие катастрофы на Чернобыльской АЭС\", в соответствии с Федеральным законом от 26 ноября 1998 года № 175-ФЗ \"О социальной защите граждан Российской Федерации, подвергшихся воздействию радиации вследствие аварии в 1957 году на производственном объединении \"Маяк\" и сбросов радиоактивных отходов в реку Теча\", в соответствии с Федеральным законом от 10 января 2002 года № 2-ФЗ \"О социальных гарантиях гражданам, подвергшимся радиационному воздействию вследствие ядерных испытаний на Семипалатинском полигоне\", а также о многодетных семьях, сведения о которых внесены в государственную информационную систему \"Единая централизованная цифровая платформа в социальной сфере\", ежегодно до 1 марта года, следующего за годом, за который представляются указанные сведения; (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n3) об опекунах и о попечителях, недееспособных и ограниченных в дееспособности гражданах, сведения о которых размещены органами опеки и попечительства в государственной информационной системе \"Единая централизованная цифровая платформа в социальной сфере\" и содержатся в банке данных о законных представителях лиц, имеющих право на получение мер социальной защиты (поддержки) (в том числе сведения о внесении исправлений или изменений в указанные сведения), в течение пяти дней со дня их размещения.\n\n(Дополнение пунктом - Федеральный закон от 03.07.2016 № 243-ФЗ) (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)","article_title":"Статья 85. Обязанности органов, учреждений, организаций и должностных лиц сообщать в налоговые органы сведения, связанные с учетом организаций и физических лиц","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"92c6fecc549c5d88505c5bd271a2016db945dd848542693cb7ff1c47ec503071"},{"code_id":"NK_RF","article_number":"85.1","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 02.04.2014 № 52-ФЗ)","article_title":"Статья 85.1. Обязанности органов, осуществляющих открытие и ведение лицевых счетов в соответствии с бюджетным законодательством Российской Федерации, связанные с учетом налогоплательщиков","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3ea8e11349fdb1756e9f6f814e85b6062d84a762d9095061b9e897fecab37611"},{"code_id":"NK_RF","article_number":"86","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 23.07.2013 № 248-ФЗ, от 19.12.2023 № 610-ФЗ)\n\n1) российским организациям, иностранным некоммерческим неправительственным организациям, осуществляющим деятельность на территории Российской Федерации через отделения, аккредитованным филиалам, представительствам иностранных организаций, индивидуальным предпринимателям - при наличии сведений о соответствующих идентификационном номере налогоплательщика, коде причины постановки на учет в налоговом органе, дате постановки на учет в налоговом органе, содержащихся соответственно в Едином государственном реестре юридических лиц, государственном реестре аккредитованных филиалов, представительств иностранных юридических лиц, Едином государственном реестре индивидуальных предпринимателей;\n\n2) нотариусам, занимающимся частной практикой, адвокатам, учредившим адвокатские кабинеты, - при наличии сведений об идентификационном номере налогоплательщика, иностранным организациям, не указанным в подпункте 1 настоящего пункта, - при наличии сведений об идентификационном номере налогоплательщика, коде причины постановки на учет в налоговом органе и дате постановки на учет в налоговом органе, содержащихся в Едином государственном реестре налогоплательщиков. (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n(Пункт в редакции Федерального закона от 03.07.2016 № 241-ФЗ)\n\nИнформация сообщается в электронной форме в течение трех дней со дня соответствующего события, если иное не предусмотрено настоящей статьей.\n\nПорядок сообщения банком, оператором платформы цифрового рубля об открытии или о закрытии счета, вклада (депозита), счета цифрового рубля, об изменении реквизитов счета, вклада (депозита), счета цифрового рубля организации, индивидуального предпринимателя, физического лица, не являющегося индивидуальным предпринимателем, о предоставлении права или прекращении права организации, индивидуального предпринимателя использовать корпоративные электронные средства платежа для переводов электронных денежных средств, о предоставлении права или прекращении права физического лица использовать персонифицированные электронные средства платежа для переводов электронных денежных средств, о предоставлении права или прекращении права физического лица, в отношении которого в соответствии с законодательством Российской Федерации о противодействии легализации (отмыванию) доходов, полученных преступным путем, и финансированию терроризма проведена упрощенная идентификация, использовать неперсонифицированные электронные средства платежа для переводов электронных денежных средств, а также об изменении реквизитов электронных средств платежа, перечисленных в настоящем пункте, в электронной форме устанавливается Центральным банком Российской Федерации по согласованию с федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nФормы и форматы сообщений банка, оператора платформы цифрового рубля налоговому органу об открытии или о закрытии счета, вклада (депозита), счета цифрового рубля организации, индивидуального предпринимателя, физического лица, не являющегося индивидуальным предпринимателем, об изменении реквизитов счета, вклада (депозита), счета цифрового рубля, о предоставлении права или прекращении права организации, индивидуального предпринимателя использовать корпоративные электронные средства платежа для переводов электронных денежных средств, о предоставлении права или прекращении права физического лица использовать персонифицированные электронные средства платежа для переводов электронных денежных средств, о предоставлении права или прекращении права физического лица, в отношении которого в соответствии с законодательством Российской Федерации о противодействии легализации (отмыванию) доходов, полученных преступным путем, и финансированию терроризма проведена упрощенная идентификация, использовать неперсонифицированные электронные средства платежа для переводов электронных денежных средств, а также об изменении реквизитов электронных средств платежа, перечисленных в настоящем пункте, устанавливаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, а в отношении счета цифрового рубля - указанным федеральным органом исполнительной власти по согласованию с Центральным банком Российской Федерации. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 03.07.2016 № 241-ФЗ) (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nСправки о наличии счетов, вкладов (депозитов), счетов цифрового рубля и (или) об остатках денежных средств (драгоценных металлов) на счетах, вкладах (депозитах), счетах цифрового рубля, выписки по операциям на счетах, по вкладам (депозитам) организаций, индивидуальных предпринимателей в банке, их счетам цифрового рубля, справки об остатках электронных денежных средств и о переводах электронных денежных средств могут быть запрошены налоговыми органами в случаях проведения налоговых проверок (налогового мониторинга) указанных лиц либо истребования у них документов (информации) в соответствии со статьей 931 настоящего Кодекса, а также в случаях неисполнения требования об уплате задолженности, вынесения решения о взыскании задолженности, принятия решений о приостановлении операций по счетам, счетам цифрового рубля организации, индивидуального предпринимателя, приостановлении переводов электронных денежных средств или об отмене приостановления операций по счетам, счетам цифрового рубля организации, индивидуального предпринимателя, отмене приостановления переводов электронных денежных средств. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nСправки о наличии счетов, вкладов (депозитов), счетов цифрового рубля и (или) об остатках денежных средств (драгоценных металлов) на счетах, вкладах (депозитах), счетах цифрового рубля, выписки по операциям на счетах, по вкладам (депозитам) физических лиц, не являющихся индивидуальными предпринимателями, в банке, их счетам цифрового рубля, справки об остатках электронных денежных средств и о переводах электронных денежных средств могут быть запрошены налоговыми органами в случаях вынесения решения о взыскании задолженности либо при наличии согласия руководителя вышестоящего налогового органа или руководителя (заместителя руководителя) федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, в случаях проведения налоговых проверок в отношении этих лиц либо истребования у них документов (информации) в соответствии с пунктом 1 статьи 931 настоящего Кодекса. (В редакции  федеральных законов от 19.12.2023 № 610-ФЗ, от 31.07.2025 № 287-ФЗ)\n\nНалоговыми органами могут быть запрошены справки о наличии счетов, вкладов (депозитов), счетов цифрового рубля и (или) об остатках денежных средств на счетах, вкладах (депозитах), счетах цифрового рубля, выписки по операциям на счетах, по вкладам (депозитам) организаций, индивидуальных предпринимателей и физических лиц, не являющихся индивидуальными предпринимателями, в банке, их счетам цифрового рубля, справки об остатках электронных денежных средств, цифровых рублей и о переводах электронных денежных средств индивидуальных предпринимателей и физических лиц, не являющихся индивидуальными предпринимателями, соответственно в банке, у оператора платформы цифрового рубля на основании запроса уполномоченного органа иностранного государства в случаях, предусмотренных международными договорами Российской Федерации. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nСправки о наличии счетов, вкладов (депозитов), счетов цифрового рубля и (или) об остатках денежных средств на счетах, вкладах (депозитах), счетах цифрового рубля, выписки по операциям на счетах, по вкладам (депозитам), счетам цифрового рубля иностранных организаций, реорганизованных или ликвидированных организаций могут быть запрошены налоговыми органами соответственно в банках, у оператора платформы цифрового рубля, если указанные организации являлись участниками сделки (операции) и (или) совокупности сделок (операций) с лицом, в отношении которого проводится налоговая проверка (налоговый мониторинг) либо у которого истребуются документы (информация) в соответствии со статьей 931 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 240-ФЗ) (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nСправки о наличии счетов организации, индивидуального предпринимат\n\nеля, физического лица, не являющегося индивидуальным предпринимателем, могут быть запрошены налоговыми органами в случае, если в заявлении о распоряжении путем возврата в соответствии с настоящим Кодексом денежных средств указан счет, сведения о котором не представлены в налоговый орган в соответствии с пунктом 11 настоящей статьи. (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 09.07.1999 № 154-ФЗ) (В редакции Федерального закона от 28.06.2013 № 134-ФЗ)\n\nКопии документов (информация), указанные в абзаце первом настоящего пункта, могут быть запрошены налоговыми органами:\n\nв отношении организации (индивидуального предпринимателя) - в случаях проведения налоговой проверки (налогового мониторинга) в отношении этого лица, истребования у него документов (информации) в соответствии со статьей 931 настоящего Кодекса, вынесения в отношении этого лица решения о взыскании задолженности и (или) принятия решения о приостановлении операций по счетам, счету цифрового рубля этого лица, решения о приостановлении переводов его электронных денежных средств, решения об отмене приостановления операций по счетам, счету цифрового рубля этого лица и (или) решения об отмене приостановления переводов электронных денежных средств этого лица; (В редакции  федеральных законов от 14.07.2022 № 263-ФЗ, от 19.12.2023 № 610-ФЗ, от 08.08.2024 № 259-ФЗ)\n\nв отношении физического лица, не являющегося индивидуальным предпринимателем, - при наличии согласия руководителя вышестоящего налогового органа или руководителя (заместителя руководителя) федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, в случаях проведения налоговой проверки в отношении этого лица либо истребования у него документов (информации) в соответствии с пунктом 1 статьи 931 настоящего Кодекса;\n\nв отношении организации (индивидуального предпринимателя, физического лица, не являющегося индивидуальным предпринимателем) - на основании запроса уполномоченного органа иностранного государства в случаях, предусмотренных международными договорами Российской Федерации.\n\nЕсли запрашиваемые документы (информация) не могут быть представлены в указанные в настоящем пункте сроки, налоговый орган при получении от банка уведомления о невозможности представления в установленные сроки документов (информации) и о сроках (при необходимости), в течение которых эти документы (информация) могут быть представлены, вправе продлить срок представления этих документов (информации). (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nВ течение двух дней со дня получения такого уведомления руководитель (заместитель руководителя) налогового органа вправе на основании этого уведомления продлить сроки представления документов или отказать в продлении сроков, о чем выносится отдельное решение. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nФорма, формат указанного уведомления и порядок его направления в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nФорма и порядок представления банками, оператором платформы цифрового рубля в электронной форме информации по запросам налоговых органов устанавливаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по согласованию с Центральным банком Российской Федерации. (В редакции  федеральных законов от 03.07.2016 № 240-ФЗ, от 19.12.2023 № 610-ФЗ)\n\nФорматы представления банками, оператором платформы цифрового рубля в электронной форме информации по запросам налоговых органов утверждаются Центральным банком Российской Федерации по согласованию с федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 229-ФЗ) (В редакции  федеральных законов от 29.06.2012 № 97-ФЗ, от 19.12.2023 № 610-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\nПравила, предусмотренные настоящей статьей, применяются также в отношении счетов инвестиционного товарищества, открываемых участником договора инвестиционного товарищества - управляющим товарищем, ответственным за ведение налогового учета, для осуществления операций, связанных с ведением общих дел товарищей по договору инвестиционного товарищества, и в отношении корпоративных электронных средств платежа, используемых для переводов электронных денежных средств по таким операциям, а также в отношении их счетов цифрового рубля. (Дополнение абзацем - Федеральный закон от 28.11.2011 № 336-ФЗ) (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 27.07.2006 № 137-ФЗ) (В редакции Федерального закона от 27.06.2011 № 162-ФЗ)\n\nОбязанности, предусмотренные пунктом 2 настоящей статьи, исполняются также кредитной организацией, у которой отозвана лицензия на осуществление банковских операций, до дня внесения в Единый государственный реестр юридических лиц записи о ликвидации такой организации в течение семи дней со дня получения мотивированного запроса налогового органа.\n\n(Дополнение пунктом - Федеральный закон от 30.11.2016 № 401-ФЗ) (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)","article_title":"Статья 86. Обязанности банков, оператора платформы цифрового рубля, связанные с осуществлением налогового контроля","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"099ce5ab641328037330076d68ac473718572b473619d516e50b44d9eaf76765"},{"code_id":"NK_RF","article_number":"86.1","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 09.07.1999 № 154-ФЗ) (Утратила силу - Федеральный закон от 07.07.2003 № 104-ФЗ)","article_title":"Статья 86.1. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"250b91848e696a7ad1d9f0b88aa62fbf1459f45f4420b8685db320c6e3ee176a"},{"code_id":"NK_RF","article_number":"86.2","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 09.07.1999 № 154-ФЗ) (Утратила силу - Федеральный закон от 07.07.2003 № 104-ФЗ)","article_title":"Статья 86.2. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"250b91848e696a7ad1d9f0b88aa62fbf1459f45f4420b8685db320c6e3ee176a"},{"code_id":"NK_RF","article_number":"86.3","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 09.07.1999 № 154-ФЗ) (Утратила силу - Федеральный закон от 07.07.2003 № 104-ФЗ)","article_title":"Статья 86.3. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"58ab009ca066017547e39ea5e140f03c4ee439d7aa0e6b40e2f620220c96bd67"},{"code_id":"NK_RF","article_number":"86.4","version_date":"2000-07-31","article_text":"1. Фонд пенсионного и социального страхования Российской Федерации обязан не позднее 10-го числа каждого месяца представлять в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, сведения за предшествующий месяц о лицах, распорядившихся средствами (частью средств) материнского (семейного) капитала в целях улучшения жилищных условий, и сумме перечисленных средств.\n\n2. Формы, форматы представляемых в электронной форме в налоговые органы сведений, предусмотренных настоящей статьей, и порядок заполнения форм утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение статьей - Федеральный закон от 31.07.2023 № 389-ФЗ)","article_title":"Статья 86.4. Обязанности органов, учреждений, организаций представлять в налоговые органы сведения, связанные с осуществлением налогового контроля","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cb54c390cce93d7e968c019423c6fcbbc637ed0629f4fc0e228dfb260a4d2911"},{"code_id":"NK_RF","article_number":"86.5","version_date":"2000-07-31","article_text":"1. Оператор майнинговой инфраструктуры обязан сообщать в налоговый орган по месту своего нахождения сведения, связанные с осуществлением майнинга цифровой валюты лицом, которому данный оператор оказывает услуги по предоставлению майнинговой инфраструктуры. Состав таких сведений определяется федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n2. Сведения, указанные в пункте 1 настоящей статьи, направляются в электронной форме по телекоммуникационным каналам связи не позднее 25-го числа месяца, следующего за истекшим кварталом, по формату, утвержденному федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение статьей - Федеральный закон от 29.11.2024 № 418-ФЗ)","article_title":"Статья 86.5. Обязанность оператора майнинговой инфраструктуры, связанная с осуществлением налогового контроля","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e36c6c0ca277de29789e7169e44dad6a3eae369818226b7950ae8be99725f9e3"},{"code_id":"NK_RF","article_number":"87","version_date":"2000-07-31","article_text":"1) камеральные налоговые проверки;\n\n2) выездные налоговые проверки.\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 87. Налоговые проверки","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cdd8abcac590c00ec8bb2a790973832a79fa4e0310a4f04069a983dce3722c22"},{"code_id":"NK_RF","article_number":"87.1","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 09.07.1999 № 154-ФЗ) (Утратила силу - Таможенный кодекс Российской Федерации от 28.05.2003 № 61-ФЗ)","article_title":"Статья 87.1. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"74dcb52b7d79192a049d0fab7e1c5f8904e1084a804608e6744cf40318a4d7a5"},{"code_id":"NK_RF","article_number":"88","version_date":"2000-07-31","article_text":"Камеральная налоговая проверка расчета финансового результата инвестиционного товарищества проводится налоговым органом по месту учета участника договора инвестиционного товарищества - управляющего товарища, ответственного за ведение налогового учета (далее в настоящей статье - управляющий товарищ, ответственный за ведение налогового учета). (Дополнение абзацем - Федеральный закон от 28.11.2011 № 336-ФЗ)\n\n12. В случае, если налоговая декларация по налогу на доходы физических лиц в отношении доходов, полученных налогоплательщиком от продажи либо в результате дарения недвижимого имущества, не представлена в налоговый орган в установленный срок в соответствии с подпунктом 2 пункта 1 и пунктом 3 статьи 228, пунктом 1 статьи 229 настоящего Кодекса, камеральная налоговая проверка проводится в соответствии с настоящей статьей на основе имеющихся у налоговых органов документов (информации) о таком налогоплательщике и об указанных доходах.\n\nПри наличии обстоятельств, указанных в абзаце первом настоящего пункта, камеральная налоговая проверка проводится в течение трех месяцев со дня, следующего за днем истечения установленного срока уплаты налога по соответствующим доходам.\n\nПри проведении в соответствии с абзацем первым настоящего пункта камеральной налоговой проверки налоговый орган вправе требовать у налогоплательщика представить в течение пяти дней необходимые пояснения.\n\nВ случае, если до окончания проведения в соответствии с абзацем первым настоящего пункта камеральной налоговой проверки налогоплательщиком (его представителем) представлена налоговая декларация, указанная в абзаце первом настоящего пункта, камеральная налоговая проверка прекращается и начинается новая камеральная налоговая проверка на основе представленной налоговой декларации. При этом документы (информация), полученные налоговым органом в рамках прекращенной камеральной налоговой проверки и иных мероприятий налогового контроля в отношении такого налогоплательщика, могут быть использованы при проведении камеральной налоговой проверки на основе представленной налоговой декларации.\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nВ случае, если налоговая декларация (расчет) не представлена налогоплательщиком - контролирующим лицом организации, признаваемым таковым в соответствии с главой 34 настоящего Кодекса, или иностранным лицом, подлежащим постановке на учет в налоговом органе в соответствии с пунктом 46 статьи 83 настоящего Кодекса, в налоговый орган в установленный срок, уполномоченные должностные лица налогового органа вправе провести камеральную налоговую проверку на основе имеющихся у них документов (информации) о налогоплательщике, а также данных об иных аналогичных налогоплательщиках в течение трех месяцев (в течение шести месяцев для иностранного лица, подлежащего постановке на учет в налоговом органе в соответствии с пунктом 46 статьи 83 настоящего Кодекса) со дня истечения срока представления такой налоговой декларации (расчета), установленного законодательством о налогах и сборах. (Дополнение абзацем - Федеральный закон от 24.11.2014 № 376-ФЗ) (В редакции  федеральных законов от 03.07.2016 № 244-ФЗ, от 29.05.2024 № 100-ФЗ)\n\nВ случае, если до окончания камеральной налоговой проверки имеющихся у налогового органа документов (информации) налогоплательщиком представлена налоговая декларация, камеральная налоговая проверка прекращается и начинается новая камеральная налоговая проверка на основе представленной налоговой декларации. Прекращение камеральной налоговой проверки означает прекращение всех действий налогового органа в отношении имеющихся у налогового органа документов (информации). При этом документы (информация), полученные налоговым органом в рамках прекращенной камеральной налоговой проверки, могут быть использованы при проведении мероприятий налогового контроля в отношении налогоплательщика. (Дополнение абзацем - Федеральный закон от 24.11.2014 № 376-ФЗ)\n\nКамеральная налоговая проверка на основе налоговой декларации по налогу на добавленную стоимость, документов, представленных в налоговый орган, а также других документов о деятельности налогоплательщика, имеющихся у налогового органа, проводится в течение двух месяцев со дня представления такой налоговой декларации (в течение шести месяцев со дня представления иностранным лицом, состоящим на учете в налоговом органе в соответствии с пунктом 46 статьи 83 настоящего Кодекса, налоговой декларации по налогу на добавленную стоимость). (Дополнение абзацем - Федеральный закон от 03.08.2018 № 302-ФЗ) (В редакции  Федерального закона от 29.05.2024 № 100-ФЗ)\n\nВ случае, если до окончания камеральной налоговой проверки налоговой декларации по налогу на добавленную стоимость налоговым органом установлены признаки, указывающие на возможное нарушение законодательства о налогах и сборах, руководитель (заместитель руководителя) налогового органа вправе принять решение о продлении срока проведения камеральной налоговой проверки. Срок камеральной налоговой проверки может быть продлен до трех месяцев со дня представления налоговой декларации по налогу на добавленную стоимость (за исключением камеральной налоговой проверки налоговой декларации по налогу на добавленную стоимость, представленной иностранным лицом, состоящим на учете в налоговом органе в соответствии с пунктом 46 статьи 83 настоящего Кодекса). (Дополнение абзацем - Федеральный закон от 03.08.2018 № 302-ФЗ) (В редакции  Федерального закона от 29.05.2024 № 100-ФЗ)\n\nКамеральная налоговая проверка на основе заявления, указанного в пункте 2 статьи 2211 настоящего Кодекса, проводится в течение 30 календарных дней со дня представления такого заявления, если иное не установлено настоящим Кодексом. (Дополнение абзацем - Федеральный закон от 20.04.2021 № 100-ФЗ)\n\nВ случае, если до окончания камеральной налоговой проверки на основе заявления, указанного в пункте 2 статьи 2211 настоящего Кодекса, налоговым органом установлены признаки, указывающие на возможное нарушение законодательства о налогах и сборах, руководитель (заместитель руководителя) налогового органа вправе принять решение о продлении срока проведен\n\nия камеральной налоговой проверки. Срок проведения камеральной налоговой проверки может быть продлен до трех месяцев со дня представления заявления, указанного в пункте 2 статьи 2211 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 20.04.2021 № 100-ФЗ)\n\nРешение о продлении срока проведения камеральной налоговой проверки направляется налогоплательщику через личный кабинет налогоплательщика (при прекращении у налогоплательщика доступа к личному кабинету налогоплательщика - по почте заказным письмом) в срок, не превышающий трех дней с даты принятия такого решения. (Дополнение абзацем - Федеральный закон от 20.04.2021 № 100-ФЗ)\n\nКамеральная налоговая проверка лиц, указанных в пункте 2 статьи 80 настоящего Кодекса, представивших единую (упрощенную) налоговую декларацию, проводится в течение трех месяцев на основе имеющихся у налоговых органов документов (информации) о налогоплательщике с учетом следующих особенностей: (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nкамеральная налоговая проверка проводится за налоговые периоды истекшего календарного года начиная с 1 февраля следующего календарного года; (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nв случае принятия решения о реорганизации или ликвидации организации камеральная налоговая проверка проводится за истекшие налоговые периоды текущего календарного года со дня, следующего за днем внесения в единый государственный реестр юридических лиц записи о том, что такая организация находится в процессе реорганизации или ликвидации. Ликвидация организации не может быть завершена ранее окончания камеральной налоговой проверки. (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n(Пункт в редакции Федерального закона от 26.11.2008 № 224-ФЗ)\n\nПри проведении камеральной налоговой проверки на основе уточненной налоговой декларации (расчета), в которой уменьшена сумма налога, подлежащая уплате в бюджетную систему Российской Федерации, по сравнению с ранее представленной налоговой декларацией (расчетом), налоговый орган вправе требовать у налогоплательщика представить в течение пяти дней необходимые пояснения, обосновывающие изменение соответствующих показателей налоговой декларации (расчета). (Дополнение абзацем - Федеральный закон от 28.06.2013 № 134-ФЗ) (В редакции Федерального закона от 04.11.2014 № 348-ФЗ)\n\nПри проведении камеральной налоговой проверки налоговой декларации (расчета), в которой заявлена сумма полученного в соответствующем отчетном (налоговом) периоде убытка, налоговый орган вправе требовать у налогоплательщика представить в течение пяти дней необходимые пояснения, обосновывающие размер полученного убытка. (Дополнение абзацем - Федеральный закон от 28.06.2013 № 134-ФЗ)\n\nНалогоплательщики, на которых настоящим Кодексом возложена обязанность представлять налоговую декларацию по налогу на добавленную стоимость в электронной форме, при проведении камеральной налоговой проверки такой налоговой декларации представляют пояснения, предусмотренные настоящим пунктом, в электронной форме по телекоммуникационным каналам связи через оператора электронного документооборота по формату, установленному федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. При представлении указанных пояснений не по формату, установленному федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, или на бумажном носителе такие пояснения не считаются представленными. (Дополнение абзацем - Федеральный закон от 01.05.2016 № 130-ФЗ) (В редакции Федерального закона от 09.11.2020 № 371-ФЗ)\n\nНалогоплательщик вправе в качестве пояснения представить в электронной форме реестр подтверждающих документов. Форма и порядок заполнения указанного реестра, а также формат и порядок представления такого реестра в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\n(Пункт в редакции Федерального закона от 01.05.2016 № 130-ФЗ)\n\nНалоговый орган вправе истребовать у налогоплательщика документы, подтверждающие в соответствии со статьей 172 настоящего Кодекса правомерность применения налоговых вычетов.\n\n1) подтверждающие, что местом оказания услуг, указанных в пункте 1 статьи 1742 настоящего Кодекса, признается территория Российской Федерации, а также иную информацию (сведения) относительно таких услуг;\n\n2) подтверждающие, что местом реализации товаров физическим лицам посредством электронной торговой площадки в соответствии со статьей 1743 настоящего Кодекса признается территория Российской Федерации, а также иную информацию (сведения) относительно таких товаров.\n\n(Дополнение пунктом - Федеральный закон от 03.07.2016 № 244-ФЗ) (В редакции  Федерального закона от 29.05.2024 № 100-ФЗ)\n\n1) между сведениями, содержащимися в налоговой декларации, представленной налогоплательщиком в соответствии с пунктом 2 статьи 80 и главами 261 и 262 настоящего Кодекса, и сведениями, содержащимися в отчете об операциях с товарами, подлежащими прослеживаемости, и (или) документах, содержащих реквизиты прослеживаемости, представленных в налоговый орган налогоплательщиком, осуществляющим операции с товарами, подлежащими прослеживаемости;\n\n2) между сведениями об операциях, содержащимися в налоговой декларации по налогу на добавленную стоимость, представленной налогоплательщиком, и сведениями об указанных операциях, содержащимися в отчете об операциях с товарами, подлежащими прослеживаемости, представленном в налоговый орган другим налогоплательщиком, осуществляющим операции с товарами, подлежащими прослеживаемости;\n\n3) между сведениями об операциях, содержащимися в отчете об операциях с товарами, подлежащими прослеживаемости, представленном налогоплательщиком, осуществляющим операции с товарами, подлежащими прослеживаемости, и сведениями об указанных операциях, содержащимися в отчете об операциях с товарами, подлежащими прослеживаемости, представленном в налоговый орган другим налогоплательщиком, осуществляющим операции с товарами, подлежащими прослеживаемости.\n\nПри этом налоговый орган не вправе истребовать у налогоплательщика счета-фактуры, первичные и иные документы, относящиеся к операциям с товарами, подлежащими прослеживаемости, при выявлении несоответствий, указанных в настоящем пункте, если такие документы ранее представлялись в налоговый орган в случаях и порядке, которые установлены Правительством Российской Федерации.\n\n(Дополнение пунктом - Федеральный закон от 09.11.2020 № 371-ФЗ)\n\nКамеральная налоговая проверка на основе налоговой декларации (расчета), по которой налоговым органом в соответствии с пунктом 42 статьи 80 настоящего Кодекса налогоплательщику направлено уведомление о признании налоговой декларации (расчета) непредставленной, прекращается в день направления указанного уведомления.\n\nЕсли указанная в абзаце втором настоящего пункта налоговая декларация (расчет) была уточненной, то по ранее представленной в налоговый орган налогоплательщиком налоговой декларации (расчету) камеральная налоговая проверка возобновляется. В этом случае в срок проведения камеральной налоговой проверки по ранее представленной налоговой декларации (расчету) не включается срок камеральной налоговой проверки, прекращенной в соответствии с абзацем вторым настоящего пункта.\n\nПрекращение камеральной налоговой проверки означает прекращение всех действий налогового органа в отношении ранее представленной налоговой декларации (расчета). При этом документы (сведения), полученные налоговым органом в рамках прекращенной камеральной налоговой проверки, могут быть использованы при проведении мероприятий налогового контроля в отношении налогоплательщика.\n\n(Дополнение пунктом - Федеральный закон от 26.11.2008 № 224-ФЗ) (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\n11. Ка\n\nмеральная налоговая проверка по консолидированной группе налогоплательщиков проводится в порядке, установленном настоящей статьей, на основе налоговых деклараций (расчетов) и документов, представленных ответственным участником этой группы, а также других документов о деятельности этой группы, имеющихся у налогового органа.\n\nПри проведении камеральной налоговой проверки по консолидированной группе налогоплательщиков налоговый орган вправе истребовать у ответственного участника этой группы копии документов, которые должны представляться с налоговой декларацией по налогу на прибыль организаций по консолидированной группе налогоплательщиков в соответствии с главой 25 настоящего Кодекса, в том числе относящиеся к деятельности иных участников проверяемой группы.\n\nНеобходимые пояснения и документы по консолидированной группе налогоплательщиков налоговому органу представляет ответственный участник этой группы.\n\n(Дополнение пунктом - Федеральный закон от 16.11.2011 № 321-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 88. Камеральная налоговая проверка","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"653c547fd894b01a6f91f7edfd6b5d4541e64f2aa952ce407d54c70198c54435"},{"code_id":"NK_RF","article_number":"89","version_date":"2000-07-31","article_text":"1. Выездная налоговая проверка проводится на территории (в помещении) налогоплательщика на основании решения руководителя (заместителя руководителя) налогового органа.\n\nВ случае, если у налогоплательщика отсутствует возможность предоставить помещение для проведения выездной налоговой проверки, выездная налоговая проверка может проводиться по месту нахождения налогового органа, а в случае проведения выездной налоговой проверки налогоплательщиков - иностранных организаций, признаваемых налоговыми резидентами Российской Федерации в порядке, установленном пунктом 8 статьи 2462 настоящего Кодекса, - по месту нахождения обособленного подразделения такой организации. (В редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\nРешение о проведении выездной налоговой проверки налогоплательщика, отнесенного в порядке, установленном статьей 83 настоящего Кодекса, к категории крупнейших налогоплательщиков, выносит налоговый орган, осуществивший постановку этого налогоплательщика на учет в качестве крупнейшего налогоплательщика. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nСамостоятельная выездная налоговая проверка филиала или представительства проводится на основании решения налогового органа по месту нахождения такого обособленного подразделения или налогового органа, уполномоченного на проведение выездных налоговых проверок на территории субъекта Российской Федерации филиалов и представительств, имеющих место нахождения на территории этого субъекта Российской Федерации. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nРешение о проведении выездной налоговой проверки должно содержать следующие сведения:\n\nполное и сокращенное наименования либо фамилия, имя, отчество налогоплательщика;\n\nпредмет проверки, то есть налоги, правильность исчисления и уплаты которых подлежит проверке;\n\nпериоды, за которые проводится проверка;\n\nдолжности, фамилии и инициалы сотрудников налогового органа, которым поручается проведение проверки.\n\nФорма решения руководителя (заместителя руководителя) налогового органа о проведении выездной налоговой проверки утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nРешение о проведении выездной налоговой проверки не может быть вынесено на основе специальной декларации, представленной в соответствии с Федеральным законом \"О добровольном декларировании физическими лицами активов и счетов (вкладов) в банках и о внесении изменений в отдельные законодательные акты Российской Федерации\", и (или) прилагаемых к ней документов и (или) сведений, а также сведений, содержащихся в указанной специальной декларации и (или) документах. (Дополнение абзацем - Федеральный закон от 08.06.2015 № 150-ФЗ)\n\n(Пункт в редакции Федерального закона от 28.09.2010 № 243-ФЗ)\n\nВ рамках выездной налоговой проверки может быть проверен период, не превышающий трех календарных лет, предшествующих году, в котором вынесено решение о проведении проверки, если иное не предусмотрено настоящим Кодексом. (В редакции федеральных законов от 27.07.2010 № 229-ФЗ; от 30.09.2013 № 267-ФЗ)\n\nВ случае представления налогоплательщиком уточненной налоговой декларации в рамках соответствующей выездной налоговой проверки проверяется период, за который представлена уточненная налоговая декларация. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 229-ФЗ)\n\nНалоговые органы не вправе проводить в отношении одного налогоплательщика более двух выездных налоговых проверок в течение календарного года, за исключением случаев принятия решения руководителем федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, о необходимости проведения выездной налоговой проверки налогоплательщика сверх указанного ограничения.\n\nПри определении количества выездных налоговых проверок налогоплательщика не учитывается количество проведенных самостоятельных выездных налоговых проверок его филиалов и представительств.\n\n1) проведение выездной налоговой проверки вышестоящим налоговым органом - в порядке контроля за деятельностью налогового органа, проводившего налоговый мониторинг;\n\n2) досрочное прекращение налогового мониторинга;\n\n3) невыполнение налогоплательщиком мотивированного мнения (мотивированных мнений) налогового органа в срок до 1 декабря года, следующего за периодом, за который проводился налоговый мониторинг, или в случае приостановления течения срока направления мотивированного мнения по запросу такого налогоплательщика для получения разъяснений в соответствии с пунктом 5 статьи 10530 настоящего Кодекса по вопросам применения законодательства о налогах и сборах в более поздний срок, равный периоду такого приостановления, исчисляемому со дня получения таким налогоплательщиком указанного мотивированного мнения. В этом случае решение о проведении выездной налоговой проверки выносится налоговым органом не позднее двух месяцев со дня истечения указанного срока. Предметом такой выездной налоговой проверки являются правильность исчисления и своевременность уплаты налогов (сборов, страховых взносов) в соответствии с невыполненным мотивированным мнением (невыполненными мотивированными мнениями); (В редакции  федеральных законов от 29.12.2020 № 470-ФЗ, от 08.08.2024 № 259-ФЗ)\n\n4) представление налогоплательщиком в календарном году, за который налоговый мониторинг не проводится, уточненной налоговой декларации (расчета) за период проведения налогового мониторинга, в которой по сравнению с ранее представленной налоговой декларацией (расчетом) уменьшена сумма налога (сбора, страховых взносов), подлежащая уплате в бюджетную систему Российской Федерации, увеличена заявленная к возмещению сумма налога на добавленную стоимость или акциза либо увеличена сумма полученного убытка. Предметом выездной налоговой проверки в указанном случае является правильность исчисления налога (сбора, страховых взносов) (определения суммы убытка) на основании измененных показателей уточненной налоговой декларации (расчета), повлекших уменьшение ранее исчисленной суммы налога (сбора, страховых взносов) (увеличение заявленной к возмещению суммы налога на добавленную стоимость или акциза либо увеличение суммы полученного убытка). (В редакции Федерального закона от 29.12.2020 № 470-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 04.11.2014 № 348-ФЗ)\n\nОснования и порядок продления срока проведения выездной налоговой проверки устанавливаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nНалоговый орган вправе проводить самостоятельную выездную налоговую проверку филиалов и представительств по вопросам правильности исчисления и своевременности уплаты региональных и (или) местных налогов.\n\nНалоговый орган, проводящий самостоятельную выездную проверку филиалов и представительств, не вправе проводить в отношении филиала или представительства две и более выездные налоговые проверки по одним и тем же налогам за один и тот же период.\n\nНалоговый орган не вправе проводить в отношении одного филиала или представительства налогоплательщика более двух выездных налоговых проверок в течение одного календарного года.\n\nПри проведении самостоятельной выездной налоговой проверки филиалов и представительств налогоплательщика срок проверки не может превышать один месяц.\n\nВ случае, если выездная налоговая проверка проводится в отношении налогоплательщика, не являющегося управляющим товарищем, ответственным за ведение налогового учета (далее в настоящей статье - управляющий товарищ), требование о представлении документов и (или) информации, связанных с его участием в договоре инвестиционного товарищества, направляется управляющему товарищу. Если управляющий товарищ не представил документы и (или) информацию в установленный срок, требование о представлении документов и (или) информации, связанных с участием проверяемого налогоплательщика в инвестиционном товариществе, может быть направлено другим участникам договора инвестиционного товарищества.\n\n(Дополнение пунктом - Федеральный закон от 28.11.2011 № 336-ФЗ)\n\n1) истребования документов (информации) в соответствии с пунктом 1 статьи 931 настоящего Кодекса;\n\n2) получения информации от иностранных государственных органов в рамках международных договоров Российской Федерации;\n\n3) проведения экспертиз;\n\n4) перевода на русский язык документов, представленных налогоплательщиком на иностранном языке.\n\nПриостановление проведения выездной налоговой проверки по основанию, указанному в подпункте 1 настоящего пункта, допускается не более одного раза по каждому лицу, у которого истребуются документы.\n\nПриостановление и возобновление проведения выездной налоговой проверки оформляются соответствующим решением руководителя (заместителя руководителя) налогового органа, проводящего указанную проверку.\n\nОбщий срок приостановления проведения выездной налоговой проверки не может превышать шесть месяцев. В случае, если проверка была приостановлена по основанию, указанному в подпункте 2 настоящего пункта, и в течение шести месяцев налоговый орган не смог получить запрашиваемую информацию от иностранных государственных органов в рамках международных договоров Российской Федерации, срок приостановления указанной проверки может быть увеличен на три месяца.\n\nНа период действия срока приостановления проведения выездной налоговой проверки приостанавливаются действия налогового органа по истребованию документов у налогоплательщика, которому в этом случае возвращаются все подлинники, истребованные при проведении проверки, за исключением документов, полученных в ходе проведения выемки, а также приостанавливаются действия налогового органа на территории (в помещении) налогоплательщика, связанные с указанной проверкой.\n\n10. Повторной выездной налоговой проверкой налогоплательщика признается выездная налоговая проверка, проводимая независимо от времени проведения предыдущей проверки по тем же налогам и за тот же период.\n\nПри назначении повторной выездной налоговой проверки ограничения, указанные в пункте 5 настоящей статьи, не действуют.\n\nПри проведении повторной выездной налоговой проверки может быть проверен период, не превышающий трех календарных лет, предшествующих году, в котором вынесено решение о проведении повторной выездной налоговой проверки.\n\nПовторная выездная налоговая проверка налогоплательщика может проводиться:\n\n1) вышестоящим налоговым органом - в порядке контроля за деятельностью налогового органа, проводившего проверку;\n\n2) налоговым органом, ранее проводившим проверку, на основании решения его руководителя (заместителя руководителя) - в случае представления налогоплательщиком уточненной налоговой декларации (расчета), в которой по сравнению с ранее представленной налоговой декларацией (расчетом) уменьшена сумма налога (сбора, страховых взносов), подлежащая уплате в бюджетную систему Российской Федерации, увеличена заявленная к возмещению сумма налога на добавленную стоимость или акциза либо увеличена сумма полученного убытка. Предметом повторной выездной налоговой проверки в указанном случае является правильность исчисления налога (сбора, страховых взносов) (определения суммы полученного убытка) на основании измененных показателей уточненной налоговой декларации (расчета), повлекших уменьшение ранее исчисленной суммы налога (сбора, страховых взносов) (увеличение заявленной к возмещению суммы налога на добавленную стоимость или акциза либо увеличение суммы полученного убытка). (В редакции Федерального закона от 29.12.2020 № 470-ФЗ)\n\nЕсли при проведении повторной выездной налоговой проверки выявлен факт совершения налогоплательщиком налогового правонарушения, которое не было выявлено при проведении первоначальной выездной налоговой проверки, к налогоплательщику не применяются налоговые санкции, за исключением случаев, когда невыявление факта налогового правонарушения при проведении первоначальной налоговой проверки явилось результатом сговора между налогоплательщиком и должностным лицом налогового органа.\n\n11. Выездная налоговая проверка, осуществляемая в связи с реорганизацией или ликвидацией организации-налогоплательщика, может проводиться независимо от времени проведения и предмета предыдущей проверки. При этом проверяется период, не превышающий трех календарных лет, предшествующих году, в котором вынесено решение о проведении проверки.\n\n12. Налогоплательщик обязан обеспечить возможность должностных лиц налоговых органов, проводящих выездную налоговую проверку, ознакомиться с документами, связанными с исчислением и уплатой налогов.\n\nПри проведении выездной налоговой проверки у налогоплательщика могут быть истребованы необходимые для проверки документы в порядке, установленном статьей 93 настоящего Кодекса.\n\nОзнакомление должностных лиц налоговых органов с подлинниками документов допускается только на территории налогоплательщика, за исключением случаев проведения выездной налоговой проверки по месту нахождения налогового органа, а также случаев, предусмотренных статьей 94 настоящего Кодекса.\n\n13. При необходимости уполномоченные должностные лица налоговых органов, осуществляющие выездную налоговую проверку, могут проводить инвентаризацию имущества налогоплательщика, а также производить осмотр производственных, складских, торговых и иных помещений и территорий, используемых налогоплательщиком для извлечения дохода либо связанных с содержанием объектов налогообложения, в порядке, установленном статьей 92 настоящего Кодекса.\n\n14. При наличии у осуществляющих выездную налоговую проверку должностных лиц достаточных оснований полагать, что документы, свидетельствующие о совершении правонарушений, могут быть уничтожены, сокрыты, изменены или заменены, производится выемка этих документов в порядке, предусмотренном статьей 94 настоящего Кодекса.\n\n15. В последний день проведения выездной налоговой проверки проверяющий обязан составить справку о проведенной проверке, в которой фиксируются предмет проверки и сроки ее проведения, и вручить ее налогоплательщику или его представителю.\n\nВ случае, если налогоплательщик (его представитель) уклоняется от получения справки о проведенной проверке, указанная справка направляется налогоплательщику заказным письмом по почте.\n\n16. Особенности проведения выездных налоговых проверок при выполнении соглашений о разделе продукции определяются главой 264 настоящего Кодекса.\n\nыездных налоговых проверок резидентов, исключенных из единого реестра резидентов Особой экономической зоны в Калининградской области, определяются статьями 2881 и 3851 настоящего Кодекса. (Дополнение пунктом - Федеральный закон от 17.05.2007 № 84-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 89. Выездная налоговая проверка","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8737fac2659088022c5394d59cda6accf583ffd882f3736211a13526a09d8495"},{"code_id":"NK_RF","article_number":"89.1","version_date":"2000-07-31","article_text":"1. Выездная налоговая проверка консолидированной группы налогоплательщиков проводится в отношении налога на прибыль организаций по консолидированной группе налогоплательщиков на территории (в помещении) ответственного участника этой группы и на территориях (в помещениях) иных участников этой группы на основании решения руководителя (заместителя руководителя) налогового органа.\n\nВ случае, если у участника консолидированной группы налогоплательщиков отсутствует возможность предоставить помещение для проведения выездной налоговой проверки, выездная налоговая проверка в отношении такого участника может проводиться по месту нахождения соответствующего налогового органа.\n\n2. Решение о проведении выездной налоговой проверки консолидированной группы налогоплательщиков выносит налоговый орган, осуществивший постановку на учет ответственного участника этой группы.\n\nСамостоятельная выездная налоговая проверка филиала или представительства участника консолидированной группы налогоплательщиков не проводится.\n\nВ решении о проведении выездной налоговой проверки консолидированной группы налогоплательщиков указываются:\n\nполное и сокращенное наименования ответственного участника, а также иных участников консолидированной группы налогоплательщиков (за исключением участников, в отношении которых за соответствующий период проводится (проведен) налоговый мониторинг, с учетом положений пункта 41 настоящей статьи); (В редакции Федерального закона от 03.07.2016 № 240-ФЗ)\n\nналоговые периоды, за которые проводится проверка;\n\nдолжности, фамилии и инициалы сотрудников налогового органа, которым поручается проведение проверки.\n\nДолжностные лица, указанные в решении о проведении выездной налоговой проверки консолидированной группы налогоплательщиков, могут принимать участие в проведении проверки по всем участникам консолидированной группы налогоплательщиков.\n\nФорма указанного решения утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n3. Проведение выездной налоговой проверки консолидированной группы налогоплательщиков в порядке, установленном статьей 89 настоящего Кодекса, не препятствует проведению самостоятельных выездных налоговых проверок участников этой группы по налогам, которые не подлежат исчислению и уплате указанной консолидированной группой налогоплательщиков, с отдельным оформлением результатов таких проверок.\n\n4. Предметом выездной налоговой проверки консолидированной группы налогоплательщиков является правильность исчисления и своевременность уплаты налога на прибыль организаций по этой группе.\n\n41. При проведении выездной налоговой проверки консолидированной группы налогоплательщиков налоговые органы не вправе проверять правильность определения полученных доходов и осуществленных расходов участником консолидированной группы налогоплательщиков за период, за который в отношении него проводится (проведен) налоговый мониторинг, за исключением следующих случаев:\n\n1) проведение выездной налоговой проверки вышестоящим налоговым органом в порядке контроля за деятельностью налогового органа, проводившего налоговый мониторинг;\n\n2) досрочное прекращение налогового мониторинга;\n\n3) невыполнение в срок до 1 декабря года, следующего за периодом, за который проводился налоговый мониторинг, мотивированного мнения (мотивированных мнений) налогового органа по вопросам правильности исчисления (удержания), полноты и своевременности уплаты (перечисления) налога на прибыль организаций, направленного участнику консолидированной группы налогоплательщиков, указанным участником консолидированной группы налогоплательщиков. В этом случае решение о проведении выездной налоговой проверки выносится налоговым органом не позднее двух месяцев со дня истечения указанного срока. Предметом такой выездной налоговой проверки является правильность исчисления налога на прибыль указанным участником консолидированной группы налогоплательщиков в соответствии с мотивированным мнением налогового органа; (В редакции Федерального закона от 29.12.2020 № 470-ФЗ)\n\n4) представление ответственным участником консолидированной группы налогоплательщиков в календарном году, за который налоговый мониторинг не проводится, уточненной налоговой декларации по налогу на прибыль организаций по консолидированной группе налогоплательщиков за период проведения налогового мониторинга, в которой уменьшена сумма налога, подлежащая уплате в бюджетную систему Российской Федерации, либо увеличена сумма полученного убытка по сравнению с ранее представленной налоговой декларацией в связи с уменьшением доходов (увеличением расходов) участником консолидированной группы налогоплательщиков, в отношении которого проводился налоговый мониторинг. Предметом выездной налоговой проверки в указанном случае является правильность исчисления налога (определения суммы полученного убытка) на основании измененных показателей уточненной налоговой декларации, повлекших уменьшение ранее исчисленной суммы налога (увеличение суммы полученного убытка). (В редакции Федерального закона от 29.12.2020 № 470-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 03.07.2016 № 240-ФЗ)\n\n5. Выездная налоговая проверка консолидированной группы налогоплательщиков не может продолжаться более двух месяцев. Указанный срок увеличивается на число месяцев, равное числу участников консолидированной группы налогоплательщиков (помимо ответственного участника этой группы), но не более чем до одного года.\n\n6. В случаях и порядке, которые предусмотрены пунктом 9 статьи 89 настоящего Кодекса, решение о приостановлении выездной налоговой проверки консолидированной группы налогоплательщиков выносит руководитель (заместитель руководителя) налогового органа, вынесшего решение о проведении такой проверки.\n\n7. Повторной выездной налоговой проверкой консолидированной группы налогоплательщиков признается выездная налоговая проверка, проводимая независимо от времени проведения предыдущей проверки этой группы за те же налоговые периоды.\n\n8. Справка о проведенной выездной налоговой проверке вручается представителю ответственного участника консолидированной группы налогоплательщиков в порядке, установленном пунктом 15 статьи 89 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 16.11.2011 № 321-ФЗ)","article_title":"Статья 89.1. Особенности проведения выездной налоговой проверки консолидированной группы налогоплательщиков","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1d32dc5e2842b1e1b623e916b5cb71ecafd29bd1f6400fb720e5c18cbe051e9c"},{"code_id":"NK_RF","article_number":"89.2","version_date":"2000-07-31","article_text":"Налогоплательщик - участник регионального инвестиционного проекта, применяющий налоговые ставки по налогу на прибыль организаций, установленные пунктами 1 и 15 статьи 284 настоящего Кодекса с учетом особенностей, предусмотренных подпунктом 2 пункта 2 и подпунктом 2 пункта 3 статьи 2843 настоящего Кодекса, обязан обеспечивать сохранность данных бухгалтерского и налогового учета и других документов, указанных в настоящем пункте, на протяжении всего срока применения таких налоговых ставок.\n\n(Пункт в редакции Федерального закона от 23.05.2016 № 144-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 30.09.2013 № 267-ФЗ)","article_title":"Статья 89.2. Особенности проведения выездной налоговой проверки налогоплательщика - участника регионального инвестиционного проекта","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a1451ab6716ed17edd398e0a6adc1426e73fd0bc407e3ad4f16b083dcf9c3d89"},{"code_id":"NK_RF","article_number":"9","version_date":"2000-07-31","article_text":"Участниками отношений, регулируемых законодательством о налогах и сборах, являются:\n\n1) организации и физические лица, признаваемые в соответствии с настоящим Кодексом налогоплательщиками, плательщиками сборов, плательщиками страховых взносов; (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n2) организации и физические лица, признаваемые в соответствии с настоящим Кодексом налоговыми агентами;\n\n3) налоговые органы (федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, и его территориальные органы); (В редакции Федерального закона от 29.06.2004 № 58-ФЗ)\n\n4) таможенные органы (федеральный орган исполнительной власти, уполномоченный в области таможенного дела, подчиненные ему таможенные органы Российской Федерации); (В редакции федеральных законов от 29.06.2004 № 58-ФЗ; от 29.07.2004 № 95-ФЗ; от 26.06.2008 № 103-ФЗ)\n\n5) (Пункт утратил силу - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\n6) (Пункт утратил силу - Федеральный закон от 29.06.2004 № 58-ФЗ)\n\n7) (Дополнение пунктом - Федеральный закон от 09.07.1999 № 154-ФЗ) (Утратил силу - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\n8) (Дополнение пунктом - Федеральный закон от 09.07.1999 № 154-ФЗ) (Утратил силу - Федеральный закон от 30.06.2003 № 86-ФЗ)","article_title":"Статья 9. Участники отношений, регулируемых законодательством о налогах и сборах","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"61c5ce796343f1b22f4c2913e7b64aeef1a687f2f1b896f91c9c5c9130e3292b"},{"code_id":"NK_RF","article_number":"90","version_date":"2000-07-31","article_text":"1. В качестве свидетеля для дачи показаний может быть вызвано любое физическое лицо, которому могут быть известны какие-либо обстоятельства, имеющие значение для осуществления налогового контроля. Показания свидетеля заносятся в протокол.\n\n2. Не могут допрашиваться в качестве свидетеля:\n\n1) лица, которые в силу малолетнего возраста, своих физических или психических недостатков не способны правильно воспринимать обстоятельства, имеющие значение для осуществления налогового контроля;\n\n2) лица, которые получили информацию, необходимую для проведения налогового контроля, в связи с исполнением ими своих профессиональных обязанностей, и подобные сведения относятся к профессиональной тайне этих лиц, в частности адвокат, аудитор.\n\n(Пункт в редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n3. Физическое лицо вправе отказаться от дачи показаний только по основаниям, предусмотренным законодательством Российской Федерации.\n\n4. Показания свидетеля могут быть получены по месту его пребывания, если он вследствие болезни, старости, инвалидности не в состоянии явиться в налоговый орган, а по усмотрению должностного лица налогового органа - и в других случаях.","article_title":"Статья 90. Участие свидетеля","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c2f5ef3931a51d522d37c739ac23eea4cdc64ffe5831af97da64f00047330392"},{"code_id":"NK_RF","article_number":"91","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 31.07.2023 № 389-ФЗ)\n\nНа основании такого акта налоговый орган по имеющимся у него данным о проверяемом лице (лице, в отношении которого проводится налоговый мониторинг) или по аналогии вправе самостоятельно определить сумму налога, подлежащую уплате. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nВ случае отказа проверяемого лица (лица, в отношении которого проводится налоговый мониторинг) подписать указанный акт в нем делается соответствующая запись. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n(Пункт в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 91. Доступ должностных лиц налоговых органов на территорию или в помещение для проведения налоговой проверки (налогового мониторинга)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2ba1b0269819e923f1b450edb07d967d641deabf2b3df4646b58a7947912f17b"},{"code_id":"NK_RF","article_number":"92","version_date":"2000-07-31","article_text":"1) при проведении выездной налоговой проверки; (Дополнение абзацем - Федеральный закон от 29.12.2020 № 470-ФЗ)\n\n2) при проведении камеральной налоговой проверки на основе налоговой декларации в случаях, предусмотренных пунктами 8, 81 и 89 статьи 88 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 29.12.2020 № 470-ФЗ)\n\n3) при проверке в рамках налогового мониторинга налоговой декларации по налогу на добавленную стоимость, в которой заявлена сумма налога к возмещению, или при выявлении противоречий или несоответствий, указанных в пунктах 81 и 89 статьи 88 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 29.12.2020 № 470-ФЗ)\n\nДолжностное лицо налогового органа, принявшего предусмотренное статьей 46 настоящего Кодекса решение о взыскании задолженности, размер которой превышает 1 миллион рублей, в отношении организации, при условии, что такое решение не исполнено в течение десяти дней с даты его принятия, вправе не более одного раза по одному решению о взыскании задолженности производить осмотр территорий, помещений, документов и предметов организации при наличии ее согласия. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nОсмотр территорий, помещений, документов и предметов производится на основании мотивированного постановления должностного лица налогового органа, производящего осмотр. Указанное постановление подлежит утверждению руководителем (заместителем руководителя) налогового органа. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n(Пункт в редакции Федерального закона от 28.06.2013 № 134-ФЗ)\n\nПри проведении осмотра вправе участвовать лицо, территории, помещения, документы и предметы которого подлежат осмотру должностным лицом налогового органа, или его представитель, а также специалисты. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)","article_title":"Статья 92. Осмотр","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"51fa0255943c79bd42341147bf9f0c05bc36cc37ee7705bb6a44ff315815e988"},{"code_id":"NK_RF","article_number":"93","version_date":"2000-07-31","article_text":"В случае нахождения должностного лица налогового органа, проводящего налоговую проверку, на территории проверяемого лица требование о представлении документов передается руководителю (законному или уполномоченному представителю) организации или физическому лицу (его законному или уполномоченному представителю) лично под расписку. (Дополнение абзацем - Федеральный закон от 23.07.2013 № 248-ФЗ) (В редакции Федерального закона от 01.05.2016 № 130-ФЗ)\n\nЕсли указанным способом требование о представлении документов передать невозможно, оно направляется в порядке, установленном пунктом 4 статьи 31 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 23.07.2013 № 248-ФЗ)\n\n(Пункт в редакции федеральных законов от 27.07.2010 № 229-ФЗ)\n\nПредставление документов на бумажном носителе производится в виде заверенных проверяемым лицом копий. Не допускается требование нотариального удостоверения копий документов, представляемых в налоговый орган (должностному лицу), если иное не предусмотрено законодательством Российской Федерации. Листы документов, представляемых на бумажном носителе, должны быть пронумерованы и прошиты в соответствии с требованиями, утверждаемыми федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nПредставление документов, составленных в электронной форме по форматам, установленным федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, осуществляется по телекоммуникационным каналам связи или через личный кабинет налогоплательщика.\n\nИстребуемые документы, составленные на бумажном носителе, могут быть представлены в налоговый орган в электронной форме в виде электронных образов документов (документов на бумажном носителе, преобразованных в электронную форму путем сканирования с сохранением их реквизитов) по форматам, установленным федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по телекоммуникационным каналам связи или через личный кабинет налогоплательщика.\n\nВ случае представления истребуемых документов в налоговый орган в электронной форме по телекоммуникационным каналам связи такие документы должны быть заверены усиленной квалифицированной электронной подписью проверяемого лица или усиленной квалифицированной электронной подписью его представителя.\n\nПорядок направления требования о представлении документов и порядок представления документов по требованию налогового органа в электронной форме по телекоммуникационным каналам связи или через личный кабинет налогоплательщика либо через информационные системы организации, к которым предоставлен доступ налоговому органу, утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nВ случае необходимости должностное лицо налогового органа вправе ознакомиться с подлинниками документов.\n\n(Пункт в редакции Федерального закона от 01.05.2016 № 130-ФЗ)\n\nВ случае, если проверяемое лицо не имеет возможности представить истребуемые документы в течение установленного настоящим пунктом срока, оно в течение дня, следующего за днем получения требования о представлении документов, письменно уведомляет проверяющих должностных лиц налогового органа о невозможности представления в указанные сроки документов с указанием причин, по которым истребуемые документы не могут быть представлены в установленные сроки, и о сроках, в течение которых проверяемое лицо может представить истребуемые документы. (В редакции Федерального закона от 16.11.2011 № 321-ФЗ)\n\nУказанное уведомление может быть представлено в налоговый орган проверяемым лицом лично или через представителя либо передано в электронной форме по телекоммуникационным каналам связи или через личный кабинет налогоплательщика. Лица, на которых в соответствии с пунктом 3 статьи 80 настоящего Кодекса не возложена обязанность по представлению налоговой декларации в электронной форме, вправе направить указанное уведомление по почте заказным письмом. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 240-ФЗ)\n\nФорма и формат указанного уведомления в электронной форме по телекоммуникационным каналам связи или через личный кабинет налогоплательщика утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 240-ФЗ)\n\nВ течение двух дней со дня получения такого уведомления руководитель (заместитель руководителя) налогового органа вправе на основании этого уведомления продлить сроки представления документов или отказать в продлении сроков, о чем выносится отдельное решение.\n\nПри проведении налоговой проверки консолидированной группы налогоплательщиков продление сроков осуществляется не менее чем на 10 дней. (Дополнение абзацем - Федеральный закон от 16.11.2011 № 321-ФЗ)\n\nВ случае такого отказа или непредставления указанных документов в установленные сроки должностное лицо налогового органа, проводящее налоговую проверку, производит выемку необходимых документов в порядке, предусмотренном статьей 94 настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 93. Истребование документов при проведении налоговой проверки","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"522ee84b65246ebbbe618a02eff35f5a80c3278bdf2e755baa4f7b0f6cf1bad4"},{"code_id":"NK_RF","article_number":"93.1","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nИстребование документов (информации), касающихся деятельности проверяемого налогоплательщика (плательщика сбора, плательщика страховых взносов, налогового агента), может проводиться также при рассмотрении материалов налоговой проверки на основании решения руководителя (заместителя руководителя) налогового органа о проведении дополнительных мероприятий налогового контроля.  (В редакции  федеральных законов от 23.07.2013 № 248-ФЗ, от 03.07.2016 № 243-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nДолжностное лицо налогового органа, проводящее налоговый мониторинг, вправе истребовать у контрагента или иных лиц, располагающих документами (информацией), касающимися деятельности организации, в отношении которой проводится налоговый мониторинг, эти документы (информацию). (Дополнение абзацем - Федеральный закон от 29.12.2020 № 470-ФЗ)\n\n11. При проведении камеральной налоговой проверки расчета финансового результата инвестиционного товарищества, налоговой декларации (расчета) по налогу на прибыль организаций, налогу на доходы физических лиц участника договора инвестиционного товарищества налоговый орган вправе истребовать у участника договора инвестиционного товарищества - управляющего товарища, ответственного за ведение налогового учета, следующие сведения за проверяемый период:\n\n1) состав участников договора инвестиционного товарищества, включая сведения об изменениях состава участников указанного договора;\n\n2) состав участников договора инвестиционного товарищества - управляющих товарищей, включая сведения об изменениях состава таких участников указанного договора;\n\n3) доля прибыли (расходов, убытков), приходящаяся на каждого из управляющих товарищей и товарищей;\n\n4) доля участия каждого из управляющих товарищей и товарищей в прибыли инвестиционного товарищества, установленная договором инвестиционного товарищества;\n\n5) доля каждого из управляющих товарищей и товарищей в общем имуществе товарищей;\n\n6) изменения в порядке определения участником договора инвестиционного товарищества - управляющим товарищем, ответственным за ведение налогового учета, расходов, произведенных в интересах всех товарищей для ведения общих дел товарищей, в случае, если такой порядок установлен договором инвестиционного товарищества.\n\n(Дополнение пунктом - Федеральный закон от 28.11.2011 № 336-ФЗ)\n\nПри проведении налоговой проверки в отношении иностранного лица, подлежащего постановке на учет в налоговом органе в соответствии с пунктом 46 статьи 83 настоящего Кодекса, налоговый орган вправе при наличии согласия руководителя (заместителя руководителя) федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, истребовать информацию в отношении операций по переводу денежных средств, осуществленных в адрес указанного иностранного лица, у организации национальной системы платежных карт, операторов по переводу денежных средств, операторов электронных денежных средств, оператора платформы цифрового рубля, операционных центров, платежных клиринговых центров, центральных платежных клиринговых контрагентов, расчетных центров и операторов связи. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 244-ФЗ) (В редакции  федеральных законов от 19.12.2023 № 610-ФЗ, от 29.05.2024 № 100-ФЗ)\n\nНалоговыми органами могут быть запрошены документы (информация), связанные с ведением реестра владельцев ценных бумаг, у лица, которое осуществляет (осуществляло) ведение этого реестра, в соответствии с запросом уполномоченного органа иностранного государства в случаях, предусмотренных международными договорами Российской Федерации. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n(Пункт в редакции Федерального закона от 28.06.2013 № 134-ФЗ)\n\nДолжностное лицо налогового органа, указанное в абзаце первом настоящего пункта, в случае непредставления в установленные сроки налогоплательщиком (плательщиком сбора, плательщиком страховых взносов, налоговым агентом) в налоговый орган документов, истребованных в соответствии с абзацем первым настоящего пункта, вправе истребовать у иных лиц, располагающих документами (информацией) об имуществе или имущественных правах налогоплательщика (плательщика сбора, плательщика страховых взносов, налогового агента), эти документы (информацию). (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nПри этом в поручении указывается, при проведении какого мероприятия налогового контроля либо что в связи с наличием задолженности возникла необходимость в представлении документов (информации), а при истребовании информации относительно конкретной сделки указываются также сведения, позволяющие идентифицировать эту сделку. (В редакции  федеральных законов от 29.09.2019 № 325-ФЗ, от 14.07.2022 № 263-ФЗ)\n\nЛицо, получившее требование о представлении документов (информации) в соответствии с пунктами 2 и 21 настоящей статьи, исполняет его в течение десяти дней со дня получения или в тот же срок уведомляет, что не располагает истребуемыми документами (информацией). (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nЕсли истребуемые документы (информация) не могут быть представлены в указанные в настоящем пункте сроки, налоговый орган при получении от лица, у которого истребованы документы (информация), уведомления о невозможности представления в установленные сроки документов (информации) и о сроках (при необходимости), в течение которых эти документы (информация) могут быть представлены, вправе продлить срок представления этих документов (информации).\n\nИстребуемые документы представляются с учетом положений, предусмотренных настоящим пунктом, пунктами 2 и 5 статьи 93, пунктом 6 статьи 10529 настоящего Кодекса. (В редакции  Федерального закона от 29.12.2020 № 470-ФЗ)\n\nУказанное в настоящем пункте уведомление представляется в порядке, предусмотренном пунктом 3 статьи 93 настоящего Кодекса, если иное не предусмотрено настоящим пунктом. (Дополнение абзацем - Федеральный закон от 29.12.2020 № 470-ФЗ)\n\nВ случае проведения налогового мониторинга указанные в настоящем пункте документы (информация) и уведомление заверяются усиленной квалифицированной электронной подписью проверяемого лица или его представителя и представляются в налоговый орган через информационные системы организации или по телекоммуникационным каналам связи в электронной форме по форматам, установленным федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 29.12.2020 № 470-ФЗ)\n\n(Пункт в редакции Федерального закона от 03.08.2018 № 302-ФЗ)\n\nНеправомерное несообщение (несвоевременное сообщение) истребуемой информации признается налоговым правонарушением и влечет ответственность, предусмотренную статьей 1291 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 23.07.2013 № 248-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 137-ФЗ)","article_title":"Статья 93.1. Истребование документов (информации) о налогоплательщике, плательщике сборов, плательщике страховых взносов и налоговом агенте или информации о конкретных сделках","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5076cf13a83088dc0a5b302a9dcf99ac154730896b0bdf39acbf5377ca1686a3"},{"code_id":"NK_RF","article_number":"93.2","version_date":"2000-07-31","article_text":"1. Должностное лицо налогового органа по месту учета аудиторской организации (индивидуального аудитора) вправе истребовать у аудиторской организации (индивидуального аудитора) полученные ею при осуществлении аудиторской деятельности и оказании прочих связанных с аудиторской деятельностью услуг, предусмотренных пунктами 1, 2, 4 и 5 части 7 статьи 1 Федерального закона от 30 декабря 2008 года № 307-ФЗ \"Об аудиторской деятельности\", документы (информацию) на основании решения руководителя (заместителя руководителя) федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, об истребовании документов (информации).\n\n2. У аудиторской организации (индивидуального аудитора) налоговым органом могут быть истребованы документы (информация), служащие основаниями для исчисления и уплаты (удержания, перечисления) налога (сбора, страховых взн\n\nосов), в случае, если такие документы (информация) были истребованы у налогоплательщика (плательщика сбора, плательщика страховых взносов, налогового агента) в соответствии с настоящим Кодексом и не были представлены в налоговый орган указанным лицом в установленном порядке при проведении в отношении его выездной налоговой проверки или проверки полноты исчисления и уплаты налогов в связи с совершением сделок между взаимозависимыми лицами. В этом случае указанное в пункте 1 настоящей статьи решение должно содержать следующие сведения:\n\nреквизиты решения о проведении выездной налоговой проверки или проверки полноты исчисления и уплаты налогов в связи с совершением сделок между взаимозависимыми лицами, в рамках которых возникла необходимость истребования документов (информации) у аудиторской организации (индивидуального аудитора), предмет проверки и период, за который она проводится;\n\nдата направления налогоплательщику (плательщику сбора, плательщику страховых взносов, налоговому агенту) требования о представлении документов (информации) и срок представления истребуемых документов (информации);\n\nсведения о факте непредставления в установленный срок документов (информации) проверяемым налогоплательщиком (плательщиком сбора, плательщиком страховых взносов, налоговым агентом), о получении от указанного лица уведомления о невозможности представления запрашиваемых документов (информации) или о его отказе от представления запрашиваемых документов (информации);\n\nсведения об аудиторской организации (индивидуальном аудиторе), проводившей аудит и (или) оказывавшей прочие связанные с аудиторской деятельностью услуги, указанные в пункте 1 настоящей статьи, за периоды, входящие в периоды проверки: наименование организации (фамилия, имя, отчество индивидуального аудитора), государственный регистрационный номер;\n\nреквизиты или иные сведения, позволяющие идентифицировать аудиторской организацией (индивидуальным аудитором) запрашиваемые документы (информацию).\n\nТребование о представлении документов (информации) с приложением копии указанного в настоящем пункте решения направляется налоговым органом аудиторской организации (индивидуальному аудитору) после истечения срока представления в установленном порядке документов (информации) налогоплательщиком (плательщиком сбора, плательщиком страховых взносов, налоговым агентом).\n\n3. У аудиторских организаций (индивидуальных аудиторов) налоговым органом могут быть истребованы документы (информация) также при поступлении в отношении аудируемого лица запроса компетентного органа иностранного государства (территории) в случаях, предусмотренных международными договорами Российской Федерации.\n\nВ случае поступления такого запроса указанное в пункте 1 настоящей статьи решение должно содержать следующие сведения:\n\nреквизиты запроса компетентного органа иностранного государства (территории);\n\nсведения о наличии в запросе компетентного органа иностранного государства (территории) запрета на информирование лица, в отношении которого получен запрос, о передаче касающейся его информации;\n\nсведения об аудиторской организации (индивидуальном аудиторе), проводившей аудит и (или) оказывавшей прочие связанные с аудиторской деятельностью услуги, указанные в пункте 1 настоящей статьи, за периоды, входящие в периоды проверки: наименование организации (фамилия, имя, отчество индивидуального аудитора), государственный регистрационный номер;\n\nреквизиты или иные сведения, позволяющие идентифицировать аудиторской организацией (индивидуальным аудитором) запрашиваемые документы (информацию).\n\nНалоговый орган по месту учета аудиторской организации (индивидуального аудитора) направляет указанному лицу требование о представлении документов (информации) с приложением копии соответствующего решения.\n\n4. Аудиторская организация (индивидуальный аудитор) вправе информировать лицо, в отношении которого получен запрос компетентного органа иностранного государства (территории), о получении соответствующего требования налогового органа и о передаче касающейся его информации только в случае, если запрос компетентного органа иностранного государства (территории) не содержит запрета на такое информирование.\n\n5. Истребуемые документы (информация) представляются аудиторской организацией (индивидуальным аудитором) налоговому органу в течение десяти дней со дня получения соответствующего требования с учетом положений, предусмотренных пунктами 2 и 3 статьи 93 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 29.07.2018 № 231-ФЗ)","article_title":"Статья 93.2. Истребование документов (информации) у аудиторских организаций (индивидуальных аудиторов)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5535b23741a34efe2accf48deded28ae3f676f40973c7cce83bde50ccf3c8a59"},{"code_id":"NK_RF","article_number":"94","version_date":"2000-07-31","article_text":"1. Выемка документов и предметов производится на основании мотивированного постановления должностного лица налогового органа, осуществляющего выездную налоговую проверку.\n\nУказанное постановление подлежит утверждению руководителем (его заместителем) налогового органа, вынесшего решение о проведении налоговой проверки. (В редакции Федерального закона от 16.11.2011 № 321-ФЗ)\n\n2. Не допускается производство выемки документов и предметов в ночное время.\n\n3. Выемка документов и предметов производится в присутствии понятых и лиц, у которых производится выемка документов и предметов. В необходимых случаях для участия в производстве выемки приглашается специалист.\n\nДо начала выемки должностное лицо налогового органа предъявляет постановление о производстве выемки и разъясняет присутствующим лицам их права и обязанности.\n\n4. Должностное лицо налогового органа предлагает лицу, у которого производится выемка документов и предметов, добровольно выдать их, а в случае отказа производит выемку принудительно.\n\nПри отказе лица, у которого производится выемка, вскрыть помещения или иные места, где могут находиться подлежащие выемке документы и предметы, должностное лицо налогового органа вправе сделать это самостоятельно, избегая причинения не вызываемых необходимостью повреждений запоров, дверей и других предметов.\n\n5. Не подлежат изъятию документы и предметы не имеющие отношения к предмету налоговой проверки.\n\n6. О производстве выемки, изъятия документов и предметов составляется протокол с соблюдением требований, предусмотренных статьей 99 настоящего Кодекса и настоящей статьей.\n\n7. Изъятые документы и предметы перечисляются и описываются в протоколе выемки либо в прилагаемых к нему описях с точным указанием наименования, количества и индивидуальных признаков предметов, а по возможности - стоимости предметов.\n\nПри изъятии таких документов с них изготавливают копии, которые заверяются должностным лицом налогового органа и передаются лицу, у которого они изымаются. При невозможности изготовить или передать изготовленные копии одновременно с изъятием документов, налоговый орган передает их лицу, у которого документы были изъяты, в течение пяти дней после изъятия.\n\nИзъятые документы должны быть пронумерованы, прошнурованы и скреплены печатью или подписью налогоплательщика (налогового агента, плательщика сбора, плательщика страховых взносов). В случае отказа налогоплательщика (налогового агента, плательщика сбора, плательщика страховых взносов) скрепить печатью или подписью изымаемые документы об этом в протоколе о выемке делается специальная отметка. (Дополнение абзацем - Федеральный закон от 27.07.2006 № 137-ФЗ) (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)","article_title":"Статья 94. Выемка документов и предметов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f5bf1aceb5a13a3a7ee596a700364234865bafb5fbb853b77c5afb9208007008"},{"code_id":"NK_RF","article_number":"95","version_date":"2000-07-31","article_text":"Экспертиза назначается в случае, если для разъяснения возникающих вопросов требуются специальные познания в науке, искусстве, технике или ремесле.\n\nВ постановлении указываются основания для назначения экспертизы, фамилия эксперта и наименование организации, в которой должна быть произведена экспертиза, вопросы, поставленные перед экспертом, и материалы, предоставляемые в распоряжение эксперта.\n\nПри проведении выездной налоговой проверки консолидированной группы налогоплательщиков ответственный участник этой группы подлежит ознакомлению с постановлением о назначении экспертизы. (Дополнение абзацем - Федеральный закон от 16.11.2011 № 321-ФЗ)\n\n1) заявить отвод эксперту;\n\n2) просить о назначении эксперта из числа указанных им лиц;\n\n3) представить дополнительные вопросы для получения по ним заключения эксперта;\n\n4) присутствовать с разрешения должностного лица налогового органа при производстве экспертизы и давать объяснения эксперту;\n\n5) знакомиться с заключением эксперта.\n\n10. Дополнительная экспертиза назначается в случае недостаточной ясности или полноты заключения и поручается тому же или другому эксперту.\n\nПовторная экспертиза назначается в случае необоснованности заключения эксперта или сомнений в его правильности и поручается другому эксперту.\n\nДополнительная и повторная экспертизы назначаются с соблюдением требований, предусмотренных настоящей статьей.","article_title":"Статья 95. Экспертиза","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"88eb47e24ff871c401db99640a52818717a5b149a84829f3418005faa205a760"},{"code_id":"NK_RF","article_number":"97","version_date":"2000-07-31","article_text":"Настоящее положение распространяется и на лицо, понимающее знаки немого или глухого физического лица.","article_title":"Статья 97. Участие переводчика","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"532d85f179a77b17b4ce671d4157d596141c7d9168951001fabdf5d98099ba30"},{"code_id":"NK_RF","article_number":"98","version_date":"2000-07-31","article_text":"1. При проведении действий по осуществлению налогового контроля в случаях, предусмотренных настоящим Кодексом, вызываются понятые.\n\n2. Понятые вызываются в количестве не менее двух человек.\n\n3. В качестве понятых могут быть вызваны любые не заинтересованные в исходе дела физические лица.\n\n4. Не допускается участие в качестве понятых должностных лиц налоговых органов.\n\n5. Понятые обязаны удостоверить в протоколе факт, содержание и результаты действий, производившихся в их присутствии. Они вправе делать по поводу произведенных действий замечания, которые подлежат внесению в протокол.\n\nВ случае необходимости понятые могут быть опрошены по указанным обстоятельствам.","article_title":"Статья 98. Участие понятых","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d3aade4a94e2f680811f1952d83dd159e1ca8b744ba626d6fde29a2a6d8fe916"},{"code_id":"NK_RF","article_number":"99","version_date":"2000-07-31","article_text":"1. В случаях, предусмотренных настоящим Кодексом, при проведении действий по осуществлению налогового контроля составляются протоколы. Протоколы составляются на русском языке.\n\n2. В протоколе указываются:\n\n1) его наименование;\n\n2) место и дата производства конкретного действия;\n\n3) время начала и окончания действия;\n\n4) должность, фамилия, имя, отчество лица, составившего протокол;\n\n5) фамилия, имя, отчество каждого лица, участвовавшего в действии или присутствовавшего при его проведении, а в необходимых случаях - его адрес, гражданство, сведения о том, владеет ли он русским языком;\n\n6) содержание действия, последовательность его проведения;\n\n7) выявленные при производстве действия существенные для дела факты и обстоятельства.\n\n3. Протокол прочитывается всеми лицами, участвовавшими в производстве действия или присутствовавшими при его проведении. Указанные лица вправе делать замечания, подлежащие внесению в протокол или приобщению к делу.\n\n4. Протокол подписывается составившим его должностным лицом налогового органа, а также всеми лицами, участвовавшими в производстве действия или присутствовавшими при его проведении.\n\n5. К протоколу прилагаются фотографические снимки и негативы, киноленты, видеозаписи и другие материалы, выполненные при производстве действия.","article_title":"Статья 99. Общие требования, предъявляемые к протоколу, составленному при производстве действий по осуществлению налогового контроля","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"743fb53cf4ddb34acdddecf3eb93fdcb75d5c6afc50a279d18f6316f44ae984d"},{"code_id":"NK_RF_2","article_number":"143","version_date":"2000-07-31","article_text":"организации;\n\nиндивидуальные предприниматели;\n\nлица, признаваемые налогоплательщиками налога на добавленную стоимость (далее в настоящей главе - налог) в связи с перемещением товаров через таможенную границу Таможенного союза, определяемые в соответствии с таможенным законодательством Таможенного союза и законодательством Российской Федерации о таможенном деле. (В редакции федеральных законов от 29.12.2000 № 166-ФЗ; от 27.11.2010 № 306-ФЗ)\n\nНе признаются налогоплательщиками организации, являющиеся официальными вещательными компаниям\n\nи в соответствии со статьей 31 Федерального закона от 1 декабря 2007 года № 310-ФЗ \"Об организации и о проведении XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, развитии города Сочи как горноклиматического курорта и внесении изменений в отдельные законодательные акты Российской Федерации\", в отношении операций по производству и распространению продукции средств массовой информации (в том числе по осуществлению официального теле- и радиовещания, включая цифровые и иные каналы связи), осуществляемых в соответствии с договором, заключенным с Международным олимпийским комитетом или уполномоченной им организацией, и совершаемых в течение периода проведения XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, установленного частью 2 статьи 2 указанного Федерального закона.\n\n(Дополнение пунктом - Федеральный закон от 01.12.2007 № 310-ФЗ) (В редакции Федерального закона от 30.07.2010 № 242-ФЗ)\n\nНе признаются налогоплательщиками конфедерации, национальные футбольные ассоциации, производители медиаинформации FIFA, поставщики товаров (работ, услуг) FIFA, определенные указанным Федеральным законом и являющиеся иностранными организациями, в части осуществления ими операций, связанных с осуществлением мероприятий, определенных указанным Федеральным законом.\n\n(Дополнение пунктом - Федеральный закон от 07.06.2013 № 108-ФЗ)","article_title":"Статья 143. Налогоплательщики","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"580bbb8664f82ff559f7b6c9372994611e597b03e41334ed612081d99fa73e17"},{"code_id":"NK_RF_2","article_number":"144","version_date":"2000-07-31","article_text":"(Статья утратила силу - Федеральный закон от 27.07.2010 № 229-ФЗ)","article_title":"Статья 144. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a63b4d25bb84290a5e35497b79db01d71b1135d6ac4ee2810b4bd9a8f1ccc81b"},{"code_id":"NK_RF_2","article_number":"145","version_date":"2000-07-31","article_text":"Организации и индивидуальные предприниматели, применяющие систему налогообложения для сельскохозяйственных товаропроизводителей (единый сельскохозяйственный налог), имеют право на освобождение от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога, при условии, что указанные лица переходят на уплату единого сельскохозяйственного налога и реализуют право, предусмотренное настоящим абзацем, в одном и том же календарном году либо при условии, что за предшествующий налоговый период по единому сельскохозяйственному налогу сумма дохода, полученного от реализации товаров (работ, услуг) при осуществлении видов предпринимательской деятельности, в отношении которых применяется указанная система налогообложения, без учета налога не превысила в совокупности: 100 миллионов рублей за 2018 год, 90 миллионов рублей за 2019 год, 80 миллионов рублей за 2020 год, 70 миллионов рублей за 2021 год, 60 миллионов рублей за 2022 год и последующие годы. (Дополнение абзацем - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\nОрганизации и индивидуальные предприниматели, применяющие упрощенную систему налогообложения, освобождаются от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога, при соблюдении одного из следующих условий: (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nза календарный год, предшествующий календарному году, начиная с которого организация или индивидуальный предприниматель переходит на упрощенную систему налогообложения, у указанных организации или индивидуального предпринимателя сумма доходов, определяемых в порядке, установленном главой 23, 25 или 261 настоящего Кодекса, а также в порядке, установленном Федеральным законом от 25 февраля 2022 года № 17-ФЗ \"О проведении эксперимента по установлению специального налогового режима \"Автоматизированная упрощенная система налогообложения\", не превысила в совокупности 60 миллионов рублей; (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nза предшествующий налоговый период по налогу, уплачиваемому в связи с применением упрощенной системы налогообложения, у указанных организации или индивидуального предпринимателя сумма доходов, определяемых в соответствии со статьей 34615 и подпунктами 1 и 3 пункта 1 статьи 34625 настоящего Кодекса, не превысила в совокупности 60 миллионов рублей. (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nВновь созданная организация и вновь зарегистрированный индивидуальный предприниматель, применяющие упрощенную систему налогообложения, освобождаются от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога, начиная с даты постановки их на учет в налоговом органе, указанной в свидетельстве о постановке на учет в налоговом органе. (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nПри определении величины доходов, указанной в абзацах четвертом и пятом настоящего пункта, не учитываются доходы в виде положительной курсовой разницы, предусмотренные пунктом 11 части второй статьи 250 настоящего Кодекса, и доходы в виде субсидий, признаваемые в порядке, установленном пунктом 41 статьи 271 настоящего Кодекса, при безвозмездной передаче в государственную и (или) муниципальную собственность имущества (имущественных прав). (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nВ случае, если индивидуальный предприниматель применял одновременно общий режим налогообложения и патентную систему налогообложения либо систему налогообложения для сельскохозяйственных товаропроизводителей (единый сельскохозяйственный налог) и патентную систему налогообложения, при определении величины доходов, указанной в абзацах четвертом и пятом настоящего пункта, учитываются доходы по обоим указанным налоговым режимам. (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nВ случае, если индивидуальный предприниматель применяет (применял) в календарном году упрощенную систему налогообложения, патентную систему налогообложения, специальный налоговый режим \"Автоматизированная упрощенная система налогообложения\", при определении величины доходов в соответствии с абзацами четвертым и пятым настоящего пункта учитываются доходы по всем указанным специальным налоговым режимам. (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nОрганизации и индивидуальные предприниматели, указанные в абзацах третьем - пятом пункта 1 настоящей статьи, применяют освобождение от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога, без учета особенностей, предусмотренных абзацем первым настоящего пункта.\n\n(Пункт в редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\nЛица, указанные в абзаце первом пункта 1 настоящей статьи, использующие право на освобождение, должны представить соответствующее уведомление и документы, указанные в пункте 6 настоящей статьи, которые подтверждают право на такое освобождение, в налоговый орган по месту своего учета. (В редакции  федеральных законов от 27.11.2017 № 335-ФЗ, от 12.07.2024 № 176-ФЗ)\n\nЛица, указанные в абзаце втором пункта 1 настоящей статьи, использующие право на освобождение, должны представить соответствующее уведомление в налоговый орган по месту своего учета. (Дополнение абзацем - Федеральный закон от 27.11.2017 № 335-ФЗ) (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\nУказанные документы и (или) уведомление представляются не позднее 20-го числа месяца, начиная с которого используется право на освобождение. (В редакции Федерального закона от 27.11.2017 № 335-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nОрганизации и индивидуальные предприниматели, применяющие систему налогообложения для сельскохозяйственных товаропроизводителей (единый сельскохозяйственный налог), воспользовавшиеся правом на освобождение, не вправе отказаться от права на освобождение в дальнейшем, за исключением случаев, если право на освобождение будет утрачено ими в соответствии с пунктом 5 настоящей статьи.\n\nПо истечении 12 календарных месяцев не позднее 20-го числа последующего месяца организации и индивидуальные предприниматели, которые использовали право на освобождение в соответствии с абзацем первым пункта 1 настоящей статьи, представляют в налоговые органы:\n\nдокументы, подтверждающие, что в течение указанного срока освобождения сумма выручки от реализации товаров (работ, услуг), исчисленная в соответствии с пунктом 1 настоящей статьи, без учета налога за каждые 3 последовательных календарных месяца в совокупности не превышала 2 миллиона рублей;\n\nуведомление о продлении использования права на освобождение в течение последующих 12 календарных месяцев или об отказе от использования данного права.\n\n(Пункт в редакции Федерального закона от 27.11.2017 № 335-ФЗ)\n\nЕсли в течение налогового периода по единому сельскохозяйственному налогу у организации или индивидуального предпринимателя, применяющих систему налогообложения для сельскохозяйственных товаропроизводителей (единый сельскохозяйственный налог) и использующих право на освобождение, сумма дохода, полученного от реализации товаров (работ, услуг) при осуществлении видов предпринимательской деятельности, в отношении которых применяется указанная система налогообложения, без учета налога превысила размер, установленный в абзаце втором пункта 1 настоящей статьи, такая организация или индивидуальный предприниматель начиная с 1-го числа месяца, в котором имело место такое превышение либо осуществлялась реализация подакцизных товаров, утрачивают право на освобождение. Организации и индивидуальные предприниматели, утратившие право на освобождение, не имеют права на повторное освобождение.\n\nЕсли в течение налогового периода по налогу, уплачиваемому в связи с применением упрощенной системы налогообложения, у организации или индивидуального предпринимателя, указанных в абзаце третьем пункта 1 настоящей статьи, сумма доходов, определяемых в соответствии со статьей 34615 и подпунктами 1 и 3 пункта 1 статьи 34625 настоящего Кодекса, превысила в совокупности 60 миллионов рублей, такие организация или индивидуальный предприниматель начиная с 1-го числа месяца, следующего за месяцем, в котором имело место такое превышение, начинает исполнять обязанности налогоплательщика. При определении величины доходов, указанной в настоящем абзаце, не учитываются доходы в виде положительной курсовой разницы, предусмотренные пунктом 11 части второй статьи 250 настоящего Кодекса, и доходы в виде субсидий, признаваемые в порядке, установленном пунктом 41 статьи 271 настоящего Кодекса, при безвозмездной передаче в государственную и (или) муниципальную собственность имущества (имущественных прав). В случае, если в течение налогового периода по налогу, уплачиваемому в связи с применением упрощенной системы налогообложения, индивидуальный предприниматель применяет одновременно упрощенную систему налогообложения и патентную систему налогообложения, при определении величины доходов, указанной в настоящем абзаце, учитываются доходы по обоим указанным специальным налоговым режимам. В случае, если в календарном году применения упрощенной системы налогообложения организации или индивидуальные предприниматели применяли специальный налоговый режим \"Автоматизированная упрощенная система налогообложения\", при определении величины доходов, указанной в настоящем абзаце, учитываются в том числе доходы, полученные в рамках применения специального налогового режима \"Автоматизированная упрощенная система налогообложения\". (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nСумма налога за месяц, в котором имело место превышение, предусмотренное абзацами первым и вторым настоящего пункта, либо осуществлялась реализация подакцизных товаров, подлежит восстановлению и уплате в бюджет в установленном порядке. (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\nВ случае, если налогоплательщик не представил документы, указанные в пункте 4 настоящей статьи (либо представил документы, содержащие недостоверные сведения), а также в случае, если налоговый орган установил, что налогоплательщик не соблюдает ограничения, установленные настоящим пунктом и пунктами 1 и 4 настоящей статьи, сумма налога подлежит восстановлению и уплате в бюджет в установленном порядке с взысканием с налогоплательщика соответствующих сумм налоговых санкций и пеней.\n\n(Пункт в редакции Федерального закона от 27.11.2017 № 335-ФЗ)\n\nвыписка из бухгалтерского баланса (представляют организации);\n\nвыписка из книги продаж;\n\nвыписка из книги учета доходов и расходов и хозяйственных операций (представляют индивидуальные предприниматели);\n\nабзац; (Утратил силу - Федеральный закон от 20.04.2014 № 81-ФЗ)\n\nДля организаций и индивидуальных предпринимателей, перешедших с упрощенной системы налогообложения на общий режим налогообложения, документом, подтверждающим право на освобождение, является выписка из книги учета доходов и расходов организаций и индивидуальных предпринимателей, применяющих упрощенную систему налогообложения. (Дополнение абзацем - Федеральный закон от 17.05.2007 № 85-ФЗ)\n\nДля индивидуальных предпринимателей, перешедших на общий режим налогообложения с системы налогообложения для сельскохозяйственных товаропроизводителей (единого сельскохозяйственного налога), документом, подтверждающим право на освобождение, является выписка из книги учета доходов и расходов индивидуальных предпринимателей, применяющих систему налогообложения для сельскохозяйственных товаропроизводителей (единый сельскохозяйственный налог). (Дополнение абзацем - Федеральный закон от 17.05.2007 № 85-ФЗ)\n\nФорма и формат уведомлений, предусмотренных настоящей статьей, утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Пункт в редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\nСуммы налога, уплаченные по товарам (работам, услугам), приобретенным налогоплательщиком, утратившим право на освобождение в соответствии с настоящей статьей, до утраты указанного права и использованным налогоплательщиком после утраты им этого права при осуществлении операций, признаваемых объектами налогообложения в соответствии с настоящей главой, принимаются к вычету в порядке, установленном статьями 171 и 172 настоящего Кодекса.\n\nПри переходе налогоплательщика на упрощенную систему налогообложения с применением освобождения от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога, предусмотренного настоящей статьей, суммы налога, принятые к вычету налогоплательщиком по товарам (работам, услугам), в том числе по основным средствам и нематериальным активам, имущественным правам в порядке, предусмотренном настоящей главой, подлежат восстановлению в налоговом периоде, предшествующем переходу на указанный режим. (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nСуммы налога, подлежащие восстановлению в соответствии с абзацем третьим н\n\nастоящего пункта, учитываются в составе прочих расходов в соответствии со статьей 264 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nОрганизации и индивидуальные предприниматели, применяющие упрощенную систему налогообложения и начавшие исполнять обязанности налогоплательщика, применяющего налоговые ставки, указанные в пункте 8 статьи 164 настоящего Кодекса, суммы налога по товарам (работам, услугам), в том числе основным средствам и нематериальным активам, имущественным правам, приобретенным ими в период освобождения от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога, к вычету не принимают в случае использования этих товаров (работ, услуг), в том числе основных средств и нематериальных активов, имущественных прав при осуществлении операций по реализации товаров (работ, услуг), имущественных прав, налогообложение которых производится по налоговым ставкам, указанным в подпунктах 1 - 12, 21 - 31, 7, 11 пункта 1 и пункте 8 статьи 164 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\n(Статья в редакции Федерального закона от 29.05.2002 № 57-ФЗ)","article_title":"Статья 145. Освобождение от исполнения обязанностей налогоплательщика","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"eec10242e2e82dff0b4fdf56fbaaa849e23cb61baa03e920f8923d3c89e8b715"},{"code_id":"NK_RF_2","article_number":"145.1","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 30.10.2018 № 373-ФЗ)\n\nПредусмотренное настоящей статьей освобождение не применяется в отношении обязанностей, возникающих в связи с ввозом на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, товаров, подлежащих налогообложению в соответствии с подпунктом 4 пункта 1 статьи 146 настоящего Кодекса. (В редакции Федерального закона от 27.11.2010 № 306-ФЗ)\n\nутрачен статус участника проекта, с момента утраты такого статуса;\n\nсовокупный размер прибыли участника проекта, рассчитанный в соответствии с главой 25 настоящего Кодекса нарастающим итогом начиная с 1-го числа года, в котором годовой объем выручки от реализации товаров (работ, услуг, имущественных прав), полученной этим участником проекта, превысил один миллиард рублей, превысил 300 миллионов рублей, с 1-го числа налогового периода, в котором произошло превышение указанного совокупного размера прибыли.\n\nСумма налога за налоговый период, в котором произошла утрата статуса участника проекта или имело место указанное превышение совокупного размера прибыли, подлежит восстановлению и уплате в бюджет в установленном порядке с взысканием с участника проекта соответствующих сумм пеней.\n\nутрачен статус участника проекта, с момента утраты такого статуса;\n\nсовокупный размер прибыли исследовательского корпоративного центра, рассчитанный в соответствии с главой 25 настоящего Кодекса нарастающим итогом начиная с 1-го числа года, в котором годовой объем выручки от реализации товаров (работ, услуг), передачи имущественных прав, полученной этим участником проекта, превысил один миллиард рублей, превысил один миллиард рублей, с 1-го числа налогового периода, в котором произошло превышение указанного совокупного размера прибыли;\n\nдоходы исследовательского корпоративного центра от реализации взаимозависимым лицам товаров (работ, услуг), передачи имущественных прав, определяемые в соответствии с главой 25 настоящего Кодекса, составили менее 50 процентов в общей сумме его доходов, с 1-го числа налогового периода, за который полученный исследовательским корпоративным центром доход от реализации взаимозависимым лицам товаров (работ, услуг), передачи имущественных прав составил менее 50 процентов в общей сумме его доходов.\n\nСумма налога за налоговый период, в котором произошла утрата статуса участника проекта, и (или) в котором имело место указанное превышение совокупного размера прибыли, и (или) в котором указанная доля дохода составила менее 50 процентов в общей сумме доходов, подлежит восстановлению и уплате в бюджет в установленном порядке с взысканием с исследовательского корпоративного центра соответствующих сумм пеней.\n\n(Дополнение пунктом - Федеральный закон от 28.12.2016 № 475-ФЗ)\n\nУчастник проекта, начавший использовать право на освобождение, должен направить в налоговый орган по месту своего учета письменное уведомление и документы, указанные в абзаце втором пункта 6 настоящей статьи, не позднее 20-го числа месяца, следующего за месяцем, с которого этот участник проекта начал использовать право на освобождение.\n\nАбзац. (Утратил силу - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\n(Пункт в редакции Федерального закона от 28.12.2010 № 395-ФЗ)\n\nТакой отказ возможен только в отношении всех осуществляемых участником проекта операций.\n\nНе допускается освобождение или отказ от него в зависимости от того, кто является покупателем (приобретателем) соответствующих товаров (работ, услуг).\n\nУчастнику проекта, отказавшемуся от освобождения, оно повторно не предоставляется.\n\nдокументы, указанные в пункте 6 настоящей статьи;\n\nуведомление о продлении использования права на освобождение в течение последующих 12 календарных месяцев или об отказе от освобождения.\n\nВ случае, если участником проекта не представлены документы, указанные в пункте 6 настоящей статьи, или представлены документы, содержащие недостоверные сведения, а также в случае наличия обстоятельств, указанных в пункте 2 или 21 настоящей статьи, сумма налога подлежит восстановлению и уплате в бюджет в установленном порядке с взысканием с участника проекта соответствующих сумм пеней. (В редакции Федерального закона от 28.12.2016 № 475-ФЗ)\n\nдокументы, подтверждающие статус участника проекта и предусмотренные Федеральным законом \"Об инновационном центре \"Сколково\" либо Федеральным законом от 29 июля 2017 года № 216-ФЗ \"Об инновационных научно-технологических центрах и о внесении изменений в отдельные законодательные акты Российской Федерации\"; (В редакции Федерального закона от 30.10.2018 № 373-ФЗ)\n\nвыписка из книги учета доходов и расходов или отчет о финансовых результатах участника проекта, подтверждающие годовой объем выручки от реализации товаров (работ, услуг, имущественных прав). (В редакции федеральных законов от 28.11.2011 № 339-ФЗ; от 29.06.2012 № 97-ФЗ)\n\nНачиная с года, следующего за годом, в котором годовой объем выручки от реализации товаров (работ, услуг, имущественных прав), полученной участником проекта, превысил один миллиард рублей, участник проекта также должен представлять в налоговый орган одновременно с документами, указанными в абзацах втором и третьем настоящего пункта, предусмотренный пунктом 18 статьи 274 настоящего Кодекса расчет совокупного размера прибыли, рассчитанного нарастающим итогом начиная с 1-го числа года, в котором годовой объем выручки, полученной этим участником проекта, превысил один миллиард рублей. (В редакции Федерального закона от 28.11.2011 № 339-ФЗ)\n\nФорма и формат уведомлений, предусмотренных настоящей статьей, утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Пункт в редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\nСуммы налога, уплаченные по товарам (работам, услугам), приобретенным участником проекта, утратившим право на освобождение в соответствии с настоящей статьей, до утраты указанного права и использованным им после утраты указанного права при осуществлении операций, признаваемых объектами налогообложения в соответствии с настоящей главой, принимаются к вычету в порядке, установленном статьями 171 и 172 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 28.09.2010 № 243-ФЗ)","article_title":"Статья 145.1. Освобождение от исполнения обязанностей налогоплательщика организации, получившей статус участника проекта по осуществлению исследовательской и научно-технологической деятельности","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e615c242f2c3a2f365d90dc15d39395110433d317a9b5781e614451c108a9c0f"},{"code_id":"NK_RF_2","article_number":"145.2","version_date":"2000-07-31","article_text":"1. Организация, получившая статус участника Военного инновационного технополиса \"Эра\" Министерства обороны Российской Федерации в соответствии с Федеральным законом от 14 июля 2022 года № 253-ФЗ \"О Военном инновационном технополисе \"Эра\" Министерства обороны Российской Федерации и о внесении изменений в отдельные законодательные акты Российской Федерации\" (далее также - участник Технополиса) и созданная начиная с 1 января календарного года, предшествующего календарному году, в котором этой организацией подана заявка на внесение сведений в реестр участников Технополиса, имеет право на освобождение от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога (далее в настоящей статье - освобождение), в порядке и на условиях, которые предусмотрены настоящей статьей.\n\nЕсли иное не установлено настоящей статьей, участник Технополиса имеет право на освобождение в течение десяти лет со дня получения статуса участника Технополиса.\n\nУчастник Технополиса имеет право на освобождение при условии, что он не применяет упрощенной системы налогообложения.\n\nПредусмотренное настоящей статьей освобождение не применяется в отношении обязанностей, возникающих в связи с ввозом на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, товаров, подлежащих налогообложению в соответствии с подпунктом 4 пункта 1 статьи 146 настоящего Кодекса.\n\n2. Участник Технополиса вправе использовать право на освобождение с 1-го числа месяца, следующего за месяцем, в котором был получен статус участника Технополиса, при условии представления в налоговый орган по месту своего учета не позднее 20-го числа месяца, следующего за месяцем, с которого участник Технополиса начал использовать право на освобождение, уведомления об использовании права на освобождение от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога (далее в настоящей статье - уведомление об использовании права на освобождение), в электронной форме по телекоммуникационным каналам связи или через личный кабинет налогоплательщика либо по почте заказным письмом.\n\n3. Участник Технополиса, использующий право на освобождение, вправе отказаться от освобождения, направив уведомление об отказе от освобождения от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога, в налоговый орган по месту своего учета в срок не позднее 1-го числа налогового периода, с которого участник Технополиса намерен отказаться от освобождения.\n\nТакой отказ возможен только в отношении всех осуществляемых участником Технополиса операций.\n\nУчастник Технополиса, отказавшийся от освобождения или утративший право на освобождение, теряет право на повторное использование права на освобождение.\n\n4. Участник Технополиса представляет в налоговый орган по месту своего учета не позднее 20 января года, следующего за истекшим календарным годом, в котором применялось освобождение, в электронной форме расчет совокупного размера полученной выручки, определенного нарастающим итогом начиная с 1-го числа года, в котором получен статус участника Технополиса.\n\nВ случае, если совокупный размер выручки, рассчитанный в соответствии с настоящим пунктом, превысил 1 миллиард рублей до истечения календарного года, последний расчет совокупного размера полученной выручки представляется не позднее 20-го числа месяца, следующего за налоговым периодом, в котором произошло указанное превышение совокупного размера полученной выручки.\n\n5. Участник Технополиса утрачивает право на освобождение в случае наступления хотя бы одного из следующих обстоятельств:\n\n1) утрачен статус участника Технополиса - со дня утраты такого статуса;\n\n2) совокупный размер полученной участником Технополиса выручки, рассчитанный в порядке, предусмотренном пунктом 4 настоящей статьи, превысил 1 миллиард рублей - с 1-го числа налогового периода, следующего за налоговым периодом, в котором произошло превышение указанного размера выручки;\n\n3) участником Технополиса не представлен в установленный срок расчет совокупного размера полученной выручки, предусмотренный пунктом 4 настоящей статьи, или представлен расчет, содержащий недостоверные сведения, - с 1-го числа календарного года, по истечении которого не представлен расчет совокупного размера полученной выручки в соответствии с пунктом 4 настоящей статьи или представлен расчет, содержащий недостоверные сведения.\n\n6. Суммы налога, принятые участником Технополиса к вычету в соответствии со статьями 171 и 172 настоящего Кодекса до использования им права на освобождение в соответствии с настоящей статьей, по товарам (работам, услугам), в том числе по основным средствам и нематериальным активам, имущественным правам, приобретенным для осуществления операций, признаваемых объектами налогообложения в соответствии с настоящей главой, но не использованным для указанных операций, после направления в налоговый орган участником Технополиса уведомления об использовании права на освобождение подлежат восстановлению в последнем налоговом периоде перед направлением в налоговый орган уведомления об использовании права на освобождение путем уменьшения налоговых вычетов.\n\nСуммы налога, уплаченные по товарам (работам, услугам), в том числе по основным средствам и нематериальным активам, имущественным правам, приобретенным участником Технополиса, утратившим право на освобождение в соответствии с настоящей статьей, до утраты указанного права и использованным им после утраты указанного права при осуществлении операций, признаваемых объектами налогообложения в соответствии с настоящей главой, принимаются к вычету в порядке, установленном статьями 171 и 172 настоящего Кодекса.\n\n7. Форма и формат уведомлений, предусмотренных настоящей статьей, форма и формат расчета совокупного размера выручки, порядок представления такого расчета в налоговый орган в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение статьей - Федеральный закон от 23.11.2024 № 399-ФЗ)","article_title":"Статья 145.2. Освобождение от исполнения обязанностей налогоплательщика организации, получившей статус участника Военного инновационного технополиса \"Эра\" Министерства обороны Российской Федерации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6ea5c8f4308f05792a2e890823c79829773d63056c6b3618f7924481299e5364"},{"code_id":"NK_RF_2","article_number":"146","version_date":"2000-07-31","article_text":"1. Объектом налогообложения признаются следующие операции:\n\n1) реализация товаров (работ, услуг) на территории Российской Федерации, в том числе реализация предметов залога и передача товаров (результатов выполненных работ, оказание услуг) по соглашению о предоставлении отступного или новации, а также передача имущественных прав. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nВ целях настоящей главы передача права собственности на товары, результатов выполненных работ, оказание услуг на безвозмездной основе признается реализацией товаров (работ, услуг);\n\n2) передача на территории Российской Федерации товаров (выполнение работ, оказание услуг) для собственных нужд, расходы на которые не принимаются к вычету (в том числе через амортизационные отчисления) при исчислении налога на прибыль организаций; (В редакции федеральных законов от 29.12.2000 № 166-ФЗ; от 06.08.2001 № 110-ФЗ)\n\n3) выполнение строительно-монтажных работ для собственного потребления;\n\n4) ввоз товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией. (В редакции Федерального закона от 27.11.2010 № 306-ФЗ)\n\n1) операции, указанные в пункте 3 статьи 39 настоящего Кодекса;\n\n2) передача на безвозмездной основе жилых домов, детских садов, клубов, санаториев и других объектов социально-культурного и жилищно-коммунального назначения, дорог, электрических сетей, подстанций, газовых сетей, водозаборных сооружений и других подобных объектов органам государственной власти, органам местного самоуправления и органам публичной власти федеральной территории \"Сириус\" (или по решению указанных органов, специализированным организациям, осуществляющим использование или эксплуатацию указанных объектов по их назначению), а также передача на безвозмездной основе объектов социально-культурного назначения в казну республики в составе Российской Федерации, казну края, области, города федерального значения, автономной области, автономного округа, в муниципальную казну соответствующего городского, сельского поселения или другого муниципального образования, в казну федеральной территории \"Сириус\"; (В редакции федеральных законов от 15.04.2019 № 63-ФЗ, от 11.06.2021 № 199-ФЗ)\n\n3) передача имущества государственных и муниципальных предприятий, выкупаемого в порядке приватизации;\n\n4) выполнение работ (оказание услуг) органами, входящими в систему органов государственной власти, органов местного самоуправления и органов публичной власти федеральной территории \"Сириус\", в рамках выполнения возложенных на них исключител\n\nьных полномочий в определенной сфере деятельности в случае, если обязательность выполнения указанных работ (оказания услуг) установлена законодательством Российской Федерации, законодательством субъектов Российской Федерации, актами органов местного самоуправления и нормативными правовыми актами федеральной территории \"Сириус\"; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ, от 11.06.2021 № 199-ФЗ)\n\n41) выполнение работ (оказание услуг) казенными учреждениями, а также бюджетными и автономными учреждениями в рамках государственного (муниципального) задания, источником финансового обеспечения которого является субсидия из соответствующего бюджета бюджетной системы Российской Федерации; (Дополнение подпунктом - Федеральный закон от 18.07.2011 № 239-ФЗ)\n\n42) оказание услуг по предоставлению права проезда транспортных средств по платным автомобильным дорогам общего пользования федерального значения (платным участкам таких автомобильных дорог), осуществляемых в соответствии с договором доверительного управления автомобильными дорогами, учредителем которого является Российская Федерация, за исключением услуг, плата за оказание которых остается в распоряжении концессионера в соответствии с концессионным соглашением; (Дополнение подпунктом - Федеральный закон от 28.11.2011 № 338-ФЗ)\n\n5) передача на безвозмездной основе, оказание услуг по передаче в безвозмездное пользование объектов основных средств органам государственной власти и управления, органам местного самоуправления и органам публичной власти федеральной территории \"Сириус\", а также государственным и муниципальным учреждениям, государственным и муниципальным унитарным предприятиям; (В редакции федеральных законов от 19.07.2011 № 245-ФЗ, от 11.06.2021 № 199-ФЗ)\n\n51) передача на безвозмездной основе имущества, предназначенного для использования в целях предупреждения и предотвращения распространения, а также диагностики и лечения новой коронавирусной инфекции, органам государственной власти и управления, органам местного самоуправления и (или) органам публичной власти федеральной территории \"Сириус\", государственным и муниципальным учреждениям, государственным и муниципальным унитарным предприятиям; (Дополнение подпунктом - Федеральный закон от 08.06.2020 № 172-ФЗ) (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\n6) операции по реализации земельных участков (долей в них); (Дополнение подпунктом - Федеральный закон от 20.08.2004 № 109-ФЗ)\n\n7) передача имущественных прав организации ее правопреемнику (правопреемникам); (Дополнение подпунктом - Федеральный закон от 22.07.2005 № 118-ФЗ)\n\n8) передача денежных средств или недвижимого имущества на формирование или пополнение целевого капитала некоммерческой организации в порядке, установленном Федеральным законом от 30 декабря 2006 года № 275-ФЗ \"О порядке формирования и использования целевого капитала некоммерческих организаций\"; (Дополнение подпунктом - Федеральный закон от 30.12.2006 № 276-ФЗ) (В редакции Федерального закона от 21.11.2011 № 328-ФЗ)\n\n81) передача недвижимого имущества в случае расформирования целевого капитала некоммерческой организации, отмены пожертвования или в ином случае, если возврат такого имущества, переданного на пополнение целевого капитала некоммерческой организации, предусмотрен договором пожертвования и (или) Федеральным законом от 30 декабря 2006 года № 275-ФЗ \"О порядке формирования и использования целевого капитала некоммерческих организаций\". Норма настоящего подпункта применяется при передаче такого имущества некоммерческой организацией - собственником целевого капитала жертвователю, его наследникам (правопреемникам) или другой некоммерческой организации в соответствии с Федеральным законом от 30 декабря 2006 года № 275-ФЗ \"О порядке формирования и использования целевого капитала некоммерческих организаций\"; (Дополнение подпунктом - Федеральный закон от 21.11.2011 № 328-ФЗ)\n\n9) операции по реализации налогоплательщиками, являющимися российскими организаторами Олимпийских игр и Паралимпийских игр в соответствии со статьей 3 Федерального закона \"Об организации и о проведении XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, развитии города Сочи как горноклиматического курорта и внесении изменений в отдельные законодательные акты Российской Федерации\", товаров (работ, услуг) и имущественных прав, осуществляемые по согласованию с лицами, являющимися иностранными организаторами Олимпийских игр и Паралимпийских игр в соответствии со статьей 3 Федерального закона \"Об организации и о проведении XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, развитии города Сочи как горноклиматического курорта и внесении изменений в отдельные законодательные акты Российской Федерации\", в рамках исполнения обязательств по соглашению, заключенному Международным олимпийским комитетом с Олимпийским комитетом России и городом Сочи на проведение XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи; (Дополнение подпунктом - Федеральный закон от 01.12.2007 № 310-ФЗ)\n\n91) оказание услуг по передаче в безвозмездное пользование автономной некоммерческой организации \"Организационный комитет XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в г. Сочи\", являющейся российским организатором XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи в соответствии со статьей 3 Федерального закона от 1 декабря 2007 года № 310-ФЗ \"Об организации и о проведении XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, развитии города Сочи как горноклиматического курорта и внесении изменений в отдельные законодательные акты Российской Федерации\", олимпийских объектов федерального значения, перечень которых в соответствии с частью 22 статьи 14 указанного Федерального закона определяется Правительством Российской Федерации; (Дополнение подпунктом - Федеральный закон от 23.07.2013 № 216-ФЗ)\n\n92) передача на безвозмездной основе олимпийских объектов федерального значения в государственную или муниципальную собственность, в собственность Государственной корпорации по строительству олимпийских объектов и развитию города Сочи как горноклиматического курорта; (Дополнение подпунктом - Федеральный закон от 23.07.2013 № 216-ФЗ)\n\n93) передача в собственность на безвозмездной основе образовательным и научным некоммерческим организациям на осуществление уставной деятельности государственного имущества, не закрепленного за государственными предприятиями и учреждениями, составляющего государственную казну Российской Федерации, казну республики в составе Российской Федерации, казну края, области, города федерального значения, автономной области, автономного округа, а также муниципального имущества, не закрепленного за муниципальными предприятиями и учреждениями, составляющего муниципальную казну соответствующего городского, сельского поселения или другого муниципального образования, и (или) государственного и муниципального имущества, не закрепленного за государственными и муниципальными предприятиями и учреждениями, составляющего казну федеральной территории \"Сириус\"; (Дополнение подпунктом - Федеральный закон от 29.12.2015 № 396-ФЗ) (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\n10) оказание услуг по передаче в безвозмездное пользование некоммерческим организациям на осуществление уставной деятельности государственного имущества, не закрепленного за государственными предприятиями и учреждениями, составляющего государственную казну Российской Федерации, казну республики в составе Российской Федерации, казну края, области, города федерального значения, автономной области, автономного округа, а также муниципального имущества, не закрепленного за муниципальными предприятиями и учреждениями, составляющего муниципальную казну соответствующего городского, сельского поселения или другого муниципального образования, и (или) государственного и муниципального имущества, не закрепленного за государственными и муниципальными предприятиями и учреждениями, составляющего казну федеральной территории \"Сириус\"; (Дополнение подпунктом - Федеральный закон от 25.11.2009 № 281-ФЗ) (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\n11) (Дополнение подпунктом - Федеральный закон от 05.04.2010 № 41-ФЗ) (Утратил силу  - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n12) операции по реализации (передаче) на территории Российской Федерации государственного или муниципального имущества, не закрепленного за государственными предприятиями и учреждениями и составляющего государственную казну Российской Федерации, казну республики в составе Российской Федерации, казну края, области, города федерального значения, автономной области, автономного округа, а также муниципального имущества, не закрепленного за муниципальными предприятиями и учреждениями и составляющего муниципальную казну соответствующего городского, сельского поселения или другого муниципального образования, государственного и муниципального имущества, не закрепленного за государственными и муниципальными предприятиями и учреждениями, составляющего казну федеральной территории \"Сириус\", выкупаемого в порядке, установленном Федеральным законом от 22 июля 2008 года № 159-ФЗ \"Об особенностях отчуждения недвижимого имущества, находящегося в государственной или в муниципальной собственности и арендуемого субъектами малого и среднего предпринимательства, и о внесении изменений в отдельные законодательные акты Российской Федерации\"; (Дополнение подпунктом - Федеральный закон от 28.12.2010 № 395-ФЗ) (В редакции федеральных законов от 27.11.2018 № 424-ФЗ, от 11.06.2021 № 199-ФЗ)\n\n13) связанные с осуществлением мероприятий, предусмотренных Федеральным законом \"О подготовке и проведении в Российской Федерации чемпионата мира по футболу FIFA 2018 года, Кубка конфедераций FIFA 2017 года, чемпионата Европы по футболу UEFA 2020 года и внесении изменений в отдельные законодательные акты Российской Федерации\", операции по реализации товаров (работ, услуг) и имущественных прав Организационным комитетом \"Россия-2018\", дочерними организациями Организационного комитета \"Россия-2018\", Российским футбольным союзом, производителями медиаинформации FIFA и поставщиками товаров (работ, услуг) FIFA, определенными указанным Федеральным законом и являющимися российскими организациями, а также связанные с осуществлением мероприятий по подготовке и проведению в Российской Федерации чемпионата Европы по футболу UEFA 2020 года, предусмотренных указанным Федеральным законом, операции по реализации товаров (работ, услуг) и имущественных прав Российским футбольным союзом и локальной организационной структурой, коммерческими партнерами UEFA, поставщиками товаров (работ, услуг) UEFA и вещателями UEFA, определенными указанным Федеральным законом, в период по 31 декабря 2021 года включительно; (Дополнение подпунктом - Федеральный закон от 07.06.2013 № 108-ФЗ) (В редакции федеральных законов от 30.11.2016 № 404-ФЗ, от 01.05.2019 № 101-ФЗ, от 20.04.2021 № 101-ФЗ)\n\n14) реализация автономной некоммерческой организацией, созданной в соответствии с Федеральным законом \"О защите интересов физических лиц, имеющих вклады в банках и обособленных структурных подразделениях банков, зарегистрированных и (или) действующих на территории Республики Крым и на территории города федерального значения Севастополя\", имущества и имущественных прав и оказание этой организацией услуг по представлению интересов вкладчиков; (Дополнение подпунктом - Федеральный закон от 20.04.2014 № 78-ФЗ)\n\n15) операции по реализации товаров (работ, услуг) и (или) имущественных прав должников, признанных в соответствии с законодательством Российской Федерации несостоятельными (банкротами), в том числе товаров (работ, услуг), изготовленных и (или) приобретенных (выполненных, оказанных) в процессе осуществления хозяйственной деятельности после признания должников в соответствии с законодательством Российской Федерации несостоятельными (банкротами); (Дополнение подпунктом - Федеральный закон от 24.11.2014 № 366-ФЗ) (В редакции Федерального закона от 15.10.2020 № 320-ФЗ)\n\n16) передача на безвозмездной основе органам государственной власти субъектов Российской Федерации и органам местного самоуправления имущества, в том числе объектов незавершенного строительства, акционерным обществом, которое создано в целях реализации соглашений о создании особых экономических зон и 100 процентов акций которого принадлежит Российской Федерации, и хозяйственными обществами, созданными с участием такого акционерного общества в указанных целях, являющимися управляющими компаниями особых экономических зон; (Дополнение подпунктом - Федеральный закон от 27.11.2017 № 351-ФЗ)\n\n17) передача на безвозмездной основе:\n\nв собственность некоммерческой организации, основными уставными целями которой являются популяризация и проведение чемпионата мира FIA \"Формула-1\", объекта недвижимого имущества для проведения шоссейно-кольцевых автомобильных гонок серии \"Формула-1\", а также одновременно с указанным объектом недвижимого имущества нематериальных активов и (или) необходимых для обеспечения функционирования указанного объекта недвижимого имущества объектов инфраструктуры, движимого имущества;\n\nв государственную или муниципальную собственность объекта недвижимого имущества, предназначенного для проведения спортивных мероприятий по конькобежному спорту, а также одновременно с указанным объектом недвижимого имущества необходимых для обеспечения функционирования указанного объекта недвижимого имущества объектов инфраструктуры, движимого имущества;\n\n(Дополнение подпунктом - Федеральный закон от 04.06.2018 № 143-ФЗ) (В редакции Федерального закона от 26.07.2019 № 211-ФЗ)\n\n18) передача на безвозмездной основе органам государственной власти, органам местного самоуправления и (или) органам публичной власти федеральной территории \"Сириус\" результатов работ по созданию и (или) реконструкции объектов теплоснабжения, централизованных систем горячего водоснабжения, холодного водоснабжения и (или) водоотведения, отдельных объектов таких систем, находящихся в государственной или муниципальной собственности и переданных во временное владение и пользование налогоплательщику в соответствии с договорами аренды, а также объектов теплоснабжения, централизованных систем горячего водоснабжения, холодного водоснабжения и (или) водоотведения, отдельных объектов таких систем, созданных налогоплательщиком в течение срока действия договоров аренды, в случае заключения этим налогоплательщиком в отношении данных объектов концессионных соглашений в соответствии с частью 1 статьи 51 Федерального закона от 21 июля 2005 года № 115-ФЗ \"О концессионных соглашениях\"; (Дополнение подпунктом - Федеральный закон от 12.11.2018 № 414-ФЗ) (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\n19) передача на безвозмездной основе в государственную казну Российской Федерации объектов недвижимого имущества; (Дополнение подпунктом - Федеральный закон от 15.04.2019 № 63-ФЗ)\n\n20) передача на безвозмездной основе имущества в собственность Российской Федерации для целей организации и (или) проведения научных исследований в Антарктике; (Дополнение подпунктом - Федеральный закон от 15.04.2019 № 63-ФЗ)\n\n21) выполнение работ (оказание услуг), передача имущественных прав на безвозмездной основе органами государственной власти, органами местного самоуправления, корпорацией развития малого и среднего предпринимательства и ее дочерними обществами, организациями, включенными в единый реестр организаций инфраструктуры поддержки в соответствии с Федеральным законом от 24 июля 2007 года № 209-ФЗ \"О развитии малого и среднего предпринимательства в Российской Федерации\", в рамках выполнения ими возложенных на них полномочий по поддержке субъектов малого и среднего предпринимательства в соответствии с Федеральным законом от 24 июля 2007 года № 209-ФЗ \"О развитии малого и среднего предпринимательства в Российской Федерации\", а также организациями, осуществляющими функции по поддержке экспорта в соответствии с Федеральным законом от 8 декабря 2003 года № 164-ФЗ \"Об основах государственного регулирования внешнеторговой деятельности\", в рамках выполнения ими возложенных на них полномочий по поддержке экспорта в соответствии с Федеральным законом от 8 декабря 2003 года № 164-ФЗ \"Об основах государственного регулирования внешнеторговой деятельности\" в случае, если выполнение работ (оказание услуг), передача имущественных прав осуществляются в соответствии с законодательством Российской Федерации, законодательством субъектов Российской Федерации, актами органов местного самоуправления; (Дополнение подпунктом - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\n22) оказание населению услуг по подключению (технологическому присоединению), в том числе фактическому присоединению, к газораспределительным сетям газоиспользующего оборудования, расположенного в домовладениях, принадлежащих физическим лицам на праве собственности или ином предусмотренном законом праве, намеревающимся использовать газ для удовлетворения личных, семейных, домашних и иных нужд, не связанных с осуществлением предпринимательской (профессиональной) деятельности, с учетом выполнения мероприятий в рамках такого подключения (технологического присоединения) до границ земельных участков, принадлежащих указанным физическим лицам на праве собственности или ином предусмотренном законом праве, при условии, что на основании актов Правительства Российской Федерации данные услуги оказываются без взимания платы с физических лиц; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n23) передача газа и (или) оказание услуг по его транспортировке по газораспределительным сетям на безвозмездной основе потребителям, использующим газ для обеспечения постоянного горения Вечного огня и периодического горения Огня памяти на воинских захоронениях и мемориальных сооружениях, находящихся вне воинских захоронений, в соответствии с Законом Российской Федерации от 14 января 1993 года № 4292-I \"Об увековечении памяти погибших при защите Отечества\" при условии, что на основании актов Правительства Российской Федерации передача газа и оказание услуг по его транспортировке по газораспределительным сетям осуществляются без взимания платы с потребителей; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n24) передача некоммерческой организацией, признаваемой в соответствии с законодательством Российской Федерации личным фондом или международным личным фондом (далее в целях настоящего Кодекса - личный фонд), в соответствии с утвержденными ее учредителем условиями управления имущества (имущественных прав) выгодоприобретателям - физическим лицам и (или) отдельным категориям лиц из неопределенного круга физических лиц; (Дополнение подпунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n25) передача на безвозмездной основе движимого имущества, оказание услуг по передаче в безвозмездное пользование недвижимого имущества некоммерческой организацией, признаваемой в соответствии с законодательством Российской Федерации благотворительным фондом или автономной некоммерческой организацией, образовательной некоммерческой организации, оказывающей не достигшим возраста 18 лет детям и детям-сиротам, и (или) детям-инвалидам, и (или) детям, оставшимся без попечения родителей, на безвозмездной основе услуги в сфере образования по реализации основных и (или) дополнительных образовательных программ, предусмотренных лицензией, при условии, что получаемые образовательной некоммерческой организацией доходы, подлежащие налогообложению налогом на прибыль организаций в соответствии с главой 25 настоящего Кодекса, не превышают 1 процента от суммы целевых поступлений на содержание этой образовательной некоммерческой организации и ведение ею уставной деятельности за налоговый период по налогу на прибыль организаций; (Дополнение под\n\nпунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n26) выполнение работ (оказание услуг) на безвозмездной основе автономной некоммерческой организацией по эксплуатации и ремонту движимого и недвижимого имущества, указанного в подпункте 25 настоящего пункта; (Дополнение подпунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n27) операции по осуществлению майнинга цифровой валюты; (Дополнение подпунктом - Федеральный закон от 29.11.2024 № 418-ФЗ)\n\n28) операции по реализации цифровой валюты; (Дополнение подпунктом - Федеральный закон от 29.11.2024 № 418-ФЗ)\n\n29) передача товаров (выполнение работ, оказание услуг) на безвозмездной основе являющимся казенными учреждениями воинским частям и организациям Вооруженных Сил Российской Федерации, войск национальной гвардии Российской Федерации, органов федеральной службы безопасности при условии, что данные товары (работы, услуги) передаются (выполняются, оказываются) в целях их использования указанными воинскими частями и организациями в ходе специальной военной операции. Факт получения указанными воинской частью или организацией данных товаров (работ, услуг) и цели их использования подтверждаются документом, подписанным командиром (руководителем) указанных воинской части или организации либо уполномоченным им лицом. (Дополнение подпунктом - Федеральный закон от 23.07.2025 № 227-ФЗ)","article_title":"Статья 146. Объект налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a007f208c1b920f357c80e5a3461537e1b40e2a9ef612e3a1e5dbec9c5affb8d"},{"code_id":"NK_RF_2","article_number":"147","version_date":"2000-07-31","article_text":"1. В целях настоящей главы местом реализации товаров признается территория Российской Федерации при наличии одного или нескольких следующих обстоятельств (с учетом особенностей, установленных пунктом 2 настоящей статьи):\n\n1) товар находится на территории Российской Федерации и иных территориях, находящихся под ее юрисдикцией, и не отгружается и не транспортируется;\n\n2) товар в момент начала отгрузки и транспортировки находится на территории Российской Федерации и иных территориях, находящихся под ее юрисдикцией. (В редакции  Федерального закона от 29.05.2024 № 100-ФЗ)\n\nПоложение настоящего подпункта не распространяется на товары Евразийского экономического союза, которые реализуются посредством электронной торговой площадки физическому лицу; (Дополнение абзацем - Федеральный закон от 29.05.2024 № 100-ФЗ)\n\n3) товар является товаром, указанным в подпункте 12 пункта 1 статьи 164 настоящего Кодекса, и реализуется физическим лицам на территории иностранного государства; (Дополнение подпунктом - Федеральный закон от 28.04.2023 № 173-ФЗ)\n\n4) товар Евразийского экономического союза, реализуемый посредством электронной торговой площадки продавцом государства - члена Евразийского экономического союза, в момент получения его покупателем - физическим лицом находится на территории Российской Федерации и иных территориях, находящихся под ее юрисдикцией.\n\nВ целях настоящей главы под электронной торговой площадкой понимается информационная система, функционирующая в информационно-телекоммуникационной сети \"Интернет\", на которой одновременно:\n\nдоступны сервисы, позволяющие покупателям заказать товар;\n\nразмещены условия оплаты и (или) организации оплаты товаров покупателем;\n\nразмещены условия доставки и (или) организации доставки товаров покупателю.\n\n(Дополнение подпунктом - Федеральный закон от 29.05.2024 № 100-ФЗ)\n\n2. В целях настоящей главы местом реализации товаров в виде углеводородного сырья, добытого на морском месторождении углеводородного сырья, а также продуктов его технологического передела (стабильного конденсата, сжиженного природного газа, широкой фракции легких углеводородов) признается территория Российской Федерации при наличии одного или нескольких обстоятельств, указанных в пункте 1 настоящей статьи, либо при наличии одного или нескольких следующих обстоятельств:\n\n1) товар находится на континентальном шельфе Российской Федерации и (или) в исключительной экономической зоне Российской Федерации либо в российской части (российском секторе) дна Каспийского моря и не отгружается и не транспортируется;\n\n2) товар в момент начала отгрузки и транспортировки находится на континентальном шельфе Российской Федерации и (или) в исключительной экономической зоне Российской Федерации либо в российской части (российском секторе) дна Каспийского моря.\n\n(Статья в редакции Федерального закона от 30.09.2013 № 268-ФЗ)","article_title":"Статья 147. Место реализации товаров","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"be839044ffe225a2b33282cf828fc6e30109b8fdefc6e8b70729eb60a6f25db5"},{"code_id":"NK_RF_2","article_number":"148","version_date":"2000-07-31","article_text":"1) работы (услуги) связаны непосредственно с недвижимым имуществом (за исключением воздушных, морских судов и судов внутреннего плавания, а также космических объектов), находящимся на территории Российской Федерации. К таким работам (услугам), в частности, относятся строительные, монтажные, строительно-монтажные, ремонтные, реставрационные работы, работы по озеленению, услуги по аренде; (В редакции Федерального закона от 22.07.2005 № 119-ФЗ)\n\n2) работы (услуги) связаны непосредственно с движимым имуществом, воздушными, морскими судами и судами внутреннего плавания, находящимися на территории Российской Федерации. К таким работам (услугам) относятся, в частности, монтаж, сборка, переработка, обработка, ремонт и техническое обслуживание; (В редакции Федерального закона от 22.07.2005 № 119-ФЗ)\n\n3) услуги фактически оказываются на территории Российской Федерации в сфере культуры, искусства, образования (обучения), физической культуры, туризма, отдыха и спорта; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 22.07.2005 № 119-ФЗ)\n\n4) покупатель работ (услуг) осуществляет деятельность на территории Российской Федерации. (В редакции Федерального закона от 29.12.2000 № 166-ФЗ)\n\nМестом осуществления деятельности покупателя считается территория Российской Федерации в случае фактического присутствия покупателя работ (услуг), указанных в настоящем подпункте, на территории Российской Федерации на основе государственной регистрации организации или индивидуального предпринимателя, а при ее отсутствии или в отношении филиалов и представительств указанной организации - на основании места, указанного в учредительных документах организации, места управления организации, места нахождения его постоянно действующего исполнительного органа, места нахождения постоянного представительства (если работы (услуги) приобретены через это постоянное представительство), места жительства физического лица, если иное не предусмотрено абзацами тринадцатым - семнадцатым настоящего подпункта. Положение настоящего подпункта применяется при: (В редакции федеральных законов от 29.12.2000 № 166-ФЗ; от 29.05.2002 № 57-ФЗ; от 21.07.2014 № 238-ФЗ; от 03.07.2016 № 244-ФЗ)\n\nпередаче, предоставлению патентов, лицензий, торговых марок, авторских прав или иных аналогичных прав, за исключением услуг, указанных в пункте 1 статьи 1742 настоящего Кодекса; (В редакции федеральных законов от 29.12.2000 № 166-ФЗ; от 29.05.2002 № 57-ФЗ; от 22.07.2005 № 119-ФЗ; от 03.07.2016 № 244-ФЗ)\n\nоказании услуг (выполнении работ) по разработке программ для ЭВМ и баз данных (программных средств и информационных продуктов вычислительной техники), их адаптации и модификации, за исключением услуг, указанных в пункте 1 статьи 1742 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 22.07.2005 № 119-ФЗ) (В редакции федеральных законов от 19.07.2011 № 245-ФЗ; от 03.07.2016 № 244-ФЗ)\n\nоказании консультационных, юридических, бухгалтерских, аудиторских, инжиниринговых, рекламных, маркетинговых услуг, услуг по обработке информации, за исключением услуг, указанных в пункте 1 статьи 1742 настоящего Кодекса, а также при проведении научно-исследовательских и опытно-конструкторских работ. К инжиниринговым услугам относятся инженерно-консультационные услуги по подготовке процесса производства и реализации продукции (работ, услуг), подготовке строительства и эксплуатации промышленных, инфраструктурных, сельскохозяйственных и других объектов, предпроектные и проектные услуги (подготовка технико-экономических обоснований, проектно-конструкторские разработки и другие подобные услуги). К услугам по обработке информации относятся услуги по осуществлению сбора и обобщению, систематизации информационных массивов и предоставлению в распоряжение пользователя результатов обработки этой информации; (В редакции федеральных законов от 29.12.2000 № 166-ФЗ; от 29.05.2002 № 57-ФЗ; от 22.07.2005 № 119-ФЗ; от 19.07.2011 № 245-ФЗ; от 03.07.2016 № 244-ФЗ)\n\nпредоставление труда работников (персонала) в случае, если работники работают в месте деятельности покупателя услуг; (В редакции Федерального закона от 05.05.2014 № 116-ФЗ)\n\nсдаче в аренду движимого имущества, за исключением сдачи в аренду авиационных двигателей и прочего авиационно-технического имущества, если в соответствии с законодательством иностранного государства местом реализации таких услуг признается территория такого иностранного государства, и сдачи в аренду наземных автотранспортных средств; (В редакции Федерального закона от 27.11.2017 № 335-ФЗ)\n\nоказании услуг агента, привлекающего от имени основного участника контракта лицо (организацию или физическое лицо) для оказания услуг, предусмотренных настоящим подпунктом; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 22.07.2005 № 119-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 22.07.2005 № 119-ФЗ)\n\nпередаче единиц сокращения выбросов (прав на единицы сокращения выбросов), полученных в рамках реализации проектов, направленных на сокращение антропогенных выбросов или на увеличение абсорбции поглотителями парниковых газов; (Дополнение абзацем - Федеральный закон от 19.07.2011 № 245-ФЗ) (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\nоказании услуг, указанных в пункте 1 статьи 1742 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 244-ФЗ)\n\nВ отношении физического лица, не являющегося индивидуальным предпринимателем, приобретающего услуги, указанные в пункте 1 статьи 1742 настоящего Кодекса, местом осуществления деятельности покупателя признается территория Российской Федерации в случае, если выполняется хотя бы одно из указанных ниже условий: (Дополнение абзацем - Федеральный закон от 03.07.2016 № 244-ФЗ)\n\nместом жительства покупателя является Российская Федерация; (Дополнение абзацем - Федеральный закон от 03.07.2016 № 244-ФЗ)\n\nместо нахождения банка, в котором открыт счет, используемый покупателем для оплаты услуг, или оператора электронных денежных средств, через которого осуществляется покупателем оплата услуг, - на территории Российской Федерации; (Дополнение абзацем - Федеральный закон от 03.07.2016 № 244-ФЗ)\n\nсетевой адрес покупателя, использованный при приобретении услуг, зарегистрирован в Российской Федерации; (Дополнение абзацем - Федеральный закон от 03.07.2016 № 244-ФЗ)\n\nмеждународный код страны телефонного номера, используемого для приобретения или оплаты услуг, присвоен Российской Федерации. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 244-ФЗ)\n\nЕсли при оказании физическим лицам, не являющимся индивидуальными предпринимателями, услуг, указанных в пункте 1 статьи 1742 настоящего Кодекса, местом осуществления деятельности покупателя признается территория Российской Федерации и при этом в соответствии с законодательством иностранного государства, в котором место оказания указанных услуг определяется по месту осуществления деятельности покупателя, местом осуществления деятельности указанного покупателя признается территория такого иностранного государства, продавец вправе определить место осуществления деятельности покупателя самостоятельно; (Дополнение абзацем - Федеральный закон от 03.07.2016 № 244-ФЗ)\n\n41) услуги по перевозке и (или) транспортировке, а также услуги (работы), непосредственно связанные с перевозкой и (или) транспортировкой (за исключением услуг (работ), непосредственно связанных с перевозкой и (или) транспортировкой товаров, помещенных под таможенную процедуру таможенного транзита при перевозке товаров от места прибытия на территорию Российской Федерации до места убытия с территории Российской Федерации, и услуг, указанных в подпункте 43 настоящего пункта), оказываются (выполняются) российскими организациями или индивидуальными предпринимателями в случае, если пункт отправления и (или) пункт назначения находятся на территории Российской Федерации, либо иностранными лицами, не состоящими на учете в налоговых органах в качестве налогоплательщиков, в случае, если пункты отправления и назначения находятся на территории Российской Федерации (за исключением услуг по перевозке пассажиров и багажа, оказываемых иностранными лицами не через постоянное представительство этого иностранного лица). (В редакции Федерального закона от 19.07.2011 № 245-ФЗ)\n\nМестом реализации услуг также признается территория Российской Федерации, если транспортные средства по договору фрахтования, предполагающему перевозку (транспортировку) на этих транспортных средствах, предоставляются российскими организациями и индивидуальными предпринимателями и пункт отправления и (или) пункт назначения находятся на территории Российской Федерации. При этом транспортными средствами признаются воздушные, морские суда и суда внутреннего плавания, используемые для перевозок товаров и (или) пассажиров водным (морским, речным), воздушным транспортом. (В редакции Федерального закона от 27.11.2017 № 335-ФЗ)\n\nМестом реализации услуг по транспортировке трубопроводным транспортом природного газа также признается территория Российской Федерации в случаях, предусмотренных международными договорами Российской Федерации; (Дополнение абзацем - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 22.07.2005 № 119-ФЗ)\n\n42) услуги (работы), непосредственно связанные с перевозкой и транспортировкой товаров, помещенных под таможенную процедуру таможенного транзита (за исключением услуг, указанных в подпункте 43 настоящего пункта) при перевозке товаров от места прибытия на территорию Российской Федерации до места убытия с территории Российской Федерации, оказываются (выполняются) организациями или индивидуальными предпринимателями, местом осуществления деятельности которых признается территория Российской Федерации; (Дополнение подпунктом - Федеральный закон от 22.07.2005 № 119-ФЗ) (В редакции Федерального закона от 19.07.2011 № 245-ФЗ)\n\n43) услуги по организации транспортировки трубопроводным транспортом природного газа по территории Российской Федерации оказываются российскими организациями; (Дополнение подпунктом - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\n44) услуги по перевозке товаров воздушными судами оказываются российскими авиаперевозчиками - организациями или индивидуальными предпринимателями и пункт отправления и пункт назначения находятся за пределами территории Российской Федерации в случае, если при перевозке на территории Российской Федерации совершается посадка эксплуатируемого указанными перевозчиками воздушного судна и место прибытия товаров на территорию Российской Федерации совпадает с местом убытия товаров с территории Российской Федерации; (Дополнение подпунктом - Федеральный закон от 29.11.2014 № 382-ФЗ)\n\n5) деятельность организации или индивидуального предпринимателя, которые выполняют работы (оказывают услуги), осуществляется на территории Российской Федерации (в части выполнения видов работ (оказания видов услуг), не предусмотренных подпунктами 1 - 41, 44 настоящего пункта). (В редакции федеральных законов от 29.12.2000 № 166-ФЗ; от 22.07.2005 № 119-ФЗ; от 19.07.2011 № 245-ФЗ; от 29.11.2014 № 382-ФЗ)\n\n1) работы (услуги) связаны непосредственно с недвижимым имуществом (за исключением воздушных, морских судов и судов внутреннего плавания, а также космических объектов), находящимся за пределами территории Российской Федерации. К таким работам (услугам), в частности, относятся строительные, монтажные, строительно-монтажные, ремонтные, реставрационные работы, работы по озеленению, услуги по аренде;\n\n2) работы (услуги) связаны непосредственно с находящимся за пределами территории Российской Федерации движимым имуществом, а также с находящимися за пределами территории Российской Федерации воздушными, морскими судами и судами внутреннего плавания. К таким работам (услугам) относятся, в частности, монтаж, сборка, переработка, обработка, ремонт, техническое обслуживание;\n\n3) услуги фактически оказываются за пределами территории Российской Федерации в сфере культуры, искусства, образования (обучения), физической культуры, туризма, отдыха и спорта;\n\n4) покупатель работ (услуг) не осуществляет деятельность на территории Российской Федерации. Положение настоящего подпункта применяется при выполнении тех видов работ и услуг, которые перечислены в подпункте 4 пункта 1 настоящей статьи;\n\n5) услуги по перевозке (транспортировке) и услуги (работы), непосредственно связанные с перевозкой, транспортировкой, фрахтованием, не перечислены в подпунктах 41 - 43 пункта 1 настоящей статьи. (В редакции Федерального закона от 19.07.2011 № 245-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 22.07.2005 № 119-ФЗ)\n\nВ целях настоящей главы местом осуществления деятельности организации или индивидуального предпринимателя, которые предоставляют в пользование воздушные суда, морские суда или суда внутреннего плавания по договору аренды (фрахтования на время) с экипажем, не признается территория Российской Федерации, если указанные суда используются за пределами территории Российской Федерации для добычи (вылова) водных биологических ресурсов и (или) научно-исследовательских целей либо перевозок между пунктами, находящимися за пределами территории Российской Федерации. (В редакции Федерального закона от 19.07.2011 № 245-ФЗ)\n\nльном шельфе и (или) в исключительной экономической зоне Российской Федерации. Положения настоящего пункта распространяются на следующие виды работ (услуг):\n\n1) работы (услуги), выполняемые (оказываемые) в границах континентального шельфа Российской Федерации и (или) в исключительной экономической зоне Российской Федерации либо в границах российской части (российского сектора) дна Каспийского моря, по региональному геологическому изучению, геологическому изучению и разведке морских месторождений углеводородного сырья (включая услуги по геологическому изучению недр и воспроизводству минерально-сырьевой базы, услуги по геофизическим исследованиям скважин, геолого-разведочные и сейсморазведочные работы, разведочные буровые работы, услуги по мониторингу состояния недр, услуги по аэрофотосъемке), созданию, доведению до состояния готовности к использованию (эксплуатации), техническому обслуживанию, ремонту, реконструкции, модернизации, техническому перевооружению, консервации, демонтажу, ликвидации (иные работы капитального характера) искусственных островов, установок и сооружений, а также иного имущества, расположенного на континентальном шельфе Российской Федерации и (или) в исключительной экономической зоне Российской Федерации либо в российской части (российском секторе) дна Каспийского моря, которое используется (создается для использования) в деятельности, связанной с добычей углеводородного сырья на морском месторождении углеводородного сырья; (В редакции Федерального закона от 30.09.2013 № 268-ФЗ)\n\n2) работы (услуги) по добыче углеводородного сырья, в том числе по строительству (бурению) скважин; (В редакции Федерального закона от 30.09.2013 № 268-ФЗ)\n\n3) работы (услуги) по подготовке (первичной обработке) углеводородного сырья;\n\n4) работы (услуги) по перевозке и (или) транспортировке углеводородного сырья из пунктов отправления, находящихся на континентальном шельфе Российской Федерации и (или) в исключительной экономической зоне Российской Федерации, а также работы (услуги), непосредственно связанные с такой перевозкой и (или) транспортировкой, выполняемые (оказываемые) российскими и (или) иностранными организациями.\n\n(Дополнение пунктом - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\n1) заключенного до 5 октября 2022 года включительно государственного (муниципального) контракта с государственным или муниципальным заказчиком Российской Федерации либо соглашения с государственным органом (государственным учреждением), трансграничным концерном, государственным концерном, государственным унитарным предприятием Донецкой Народной Республики, Луганской Народной Республики, Запорожской области или Херсонской области на выполнение работ (оказание услуг) на указанных в абзаце первом настоящего пункта территориях;\n\n2) заключенного до 5 октября 2022 года включительно договора с юридическим лицом, которому предоставлены средства из федерального бюджета или регионального бюджета на выполнение работ (оказание услуг) на указанных в абзаце первом настоящего пункта территориях;\n\n3) договора, по которому налогоплательщик является соисполнителем, субподрядчиком по контракту, соглашению и (или) договору, указанным в подпунктах 1 и 2 настоящего пункта (независимо от даты заключения такого договора);\n\n4) заключенного до 31 декабря 2022 года договора на выполнение работ (оказание услуг) на указанных в абзаце первом настоящего пункта территориях, не являющегося контрактом, соглашением или договором, указанными в подпунктах 1 - 3 настоящего пункта. Положения настоящего подпункта применяются в отношении работ (услуг), которые выполнены (оказаны) до 31 декабря 2022 года включительно и оплата полной стоимости которых поступила до 25 января 2023 года включительно на открытый в банке счет налогоплательщика.\n\nПоложения настоящего пункта применяются при условии документального подтверждения фактического выполнения (оказания) указанных в настоящем пункте работ (услуг), а также при наличии документа, подтверждающего получение оплаты стоимости выполненных работ (оказанных услуг) в случае, предусмотренном подпунктом 4 настоящего пункта. (В редакции  Федерального закона от 19.12.2022 № 549-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 21.11.2022 № 443-ФЗ)\n\n1) контракт, заключенный с иностранными или российскими лицами;\n\n2) документы, подтверждающие факт выполнения работ (оказания услуг).","article_title":"Статья 148. Место реализации работ (услуг)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c448cba78509e7847b3ca88a9e08b73bd5b95f66c1523f7822a4268cf3179c3e"},{"code_id":"NK_RF_2","article_number":"149","version_date":"2000-07-31","article_text":"Положения абзаца первого настоящего пункта применяются в случаях, если законодательством соответствующего иностранного государства установлен аналогичный порядок в отношении граждан Российской Федерации и российских организаций, аккредитованных в этом иностранном государстве, либо если такая норма предусмотрена международным договором (соглашением) Российской Федерации. Перечень иностранных государств, в отношении граждан и (или) организаций которых применяются нормы настоящего пункта, определяется федеральным органом исполнительной власти в сфере международных отношений совместно с Министерством финансов Российской Федерации. (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 29.06.2004 № 58-ФЗ; от 02.11.2004 № 127-ФЗ)\n\n1) следующих медицинских товаров отечественного и зарубежного производства по перечню, утверждаемому Правительством Российской Федерации:\n\nабзац; (Исключен - Федеральный закон от 28.12.2001 № 179-ФЗ)\n\nабзац; (Исключен - Федеральный закон от 28.12.2001 № 179-ФЗ)\n\nмедицинских изделий. Положения настоящего абзаца применяются при представлении в налоговый орган регистрационного удостоверения медицинского изделия, выданного в соответствии с правом Евразийского экономического союза, или регистрационного удостоверения на медицинское изделие (регистрационного удостоверения на изделие медицинского назначения (медицинскую технику), выданного в соответствии с законодательством Российской Федерации; (В редакции федеральных законов от 07.03.2017 № 25-ФЗ, от 29.11.2021 № 382-ФЗ)\n\nпротезно-ортопедических изделий, сырья и материалов для их изготовления и полуфабрикатов к ним; (В редакции Федерального закона от 29.12.2000 № 166-ФЗ)\n\nтехнических средств, включая автомототранспорт, материалы, которые могут быть использованы исключительно для профилактики инвалидности или реабилитации инвалидов;\n\nочков корригирующих (для коррекции зрения), линз для коррекции зрения, оправ для очков корригирующих (для коррекции зрения); (В редакции Федерального закона от 23.11.2015 № 318-ФЗ)\n\n2) медицинских услуг, оказываемых медицинскими организациями, индивидуальными предпринимателями, осуществляющими медицинскую деятельность, за исключением косметических и санитарно-эпидемиологических услуг. Ограничение, установленное настоящим подпунктом, не распространяется на санитарно-эпидемиологические услуги, финансируемые из бюджета. В целях настоящей главы к медицинским услугам относятся: (В редакции  федеральных законов от 29.12.2000 № 166-ФЗ, от 29.05.2002 № 57-ФЗ, от 22.07.2005 № 119-ФЗ, от 25.11.2013 № 317-ФЗ, от 29.11.2024 № 416-ФЗ)\n\nуслуги, определенные перечнем услуг, предоставляемых по обязательному медицинскому страхованию; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nуслуги, оказываемые населению, по диагностике, профилактике и лечению независимо от формы и источника их оплаты по перечню, утверждаемому Правительством Российской Федерации; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nуслуги по сбору у населения крови, оказываемые по договорам с медицинскими организациями, оказывающими медицинскую помощь в амбулаторных и стационарных условиях; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 25.11.2013 № 317-ФЗ)\n\nуслуги скорой медицинской помощи, оказываемые населению;\n\nабзац; (Исключен - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\nуслуги по дежурству медицинского персонала у постели больного;\n\nуслуги патолого-анатомические; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nуслуги, оказываемые беременным женщинам, новорожденным, инвалидам и наркологическим больным. (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 25.12.2018 № 493-ФЗ)\n\nАбзац. (Исключен - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\nПоложения настоящего подпункта распространяются также на иностранные юридические лица и иностранных индивидуальных предпринимателей, которые являются участниками проекта в соответствии с Федеральным законом от 29 июня 2015 года № 160-ФЗ \"О международном медицинском кластере и внесении изменений в отдельные законодательные акты Российской Федерации\"; (Дополнение абзацем - Федеральный закон от 25.12.2018 № 493-ФЗ)\n\n21) ветеринарных услуг; (Дополнение подпунктом - Федеральный закон от 29.11.2024 № 416-ФЗ)\n\n3) услуг по уходу за больными, инвалидами и престарелыми, необходимость ухода за которыми подтверждена соответствующими заключениями организаций здравоохранения, органов социальной защиты населения и (или) федеральных учреждений медико-социальной защиты; (В редакции Федерального закона от 18.07.2011 № 235-ФЗ)\n\n4) услуг по присмотру и уходу за детьми в организациях, осуществляющих образовательную деятельность по реализации образовательных программ дошкольного образования, услуг по проведению занятий с несовершеннолетними детьми в кружках, секциях (включая спортивные) и студиях; (В редакции федеральных законов от 18.07.2011 № 235-ФЗ; от 04.06.2014 № 153-ФЗ)\n\n5) продуктов питания, непосредственно произведенных столовыми образовательных и медицинских организаций и реализуемых ими в указанных организациях, а также продуктов питания, непосредственно произведенных организациями общественного питания и реализуемых ими указанным столовым или организациям; (В редакции Федерального закона от 18.07.2011 № 235-ФЗ)\n\n6) услуг по сохранению, комплектованию и использованию архивов, оказываемых архивными учреждениями и организациями;\n\n7) услуг по перевозке пассажиров:\n\nгородским пассажирским транспортом общего пользования (за исключением такси, в том числе маршрутного). В целях настоящей статьи к услугам по перевозке пассажиров городским пассажирским транспортом общего пользования относятся услуги по перевозке пассажиров по единым условиям перевозок пассажиров по единым тарифам за проезд, установленным органами местного самоуправления, в том числе с предоставлением всех льгот на проезд, утвержденных в установленном порядке; (В редакции Федерального закона от 29.12.2000 № 166-ФЗ)\n\nморским, речным, железнодорожным или автомобильным транспортом (за исключением такси, в том числе маршрутного) в пригородном сообщении при условии осуществления перевозок пассажиров по единым тарифам с предоставлением всех льгот на проезд, утвержденных в установленном порядке;\n\n71) работ, связанных с осуществлением регулярных перевозок пассажиров и багажа автомобильным транспортом и городским наземным электрическим транспортом по регулируемым тарифам на основании государственного или муниципального контракта; (Дополнение подпунктом - Федеральный закон от 30.10.2018 № 392-ФЗ)\n\n8) ритуальных услуг, работ (услуг) по изготовлению надгробных памятников и оформлению могил, а также реализация похоронных принадлежностей (по перечню, утверждаемому Правительством Российской Федерации); (В редакции Федерального закона от 29.12.2000 № 166-ФЗ)\n\n9) почтовых марок (за исключением коллекционных марок), маркированных открыток и маркированных конвертов, лотерейных билетов лотерей, проводимых по решению уполномоченного органа; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n10) услуг по предоставлению в пользование жилых помещений в жилищном фонде всех форм собственности;\n\n11) монет из драгоценных металлов, являющихся законным средством наличного платежа Российской Федерации или иностранного государства (группы государств); (В редакции Федерального закона от 28.12.2010 № 395-ФЗ)\n\n12) долей в уставном (складочном) капитале организаций, долей в праве собственности на общее имущество участников договора инвестиционного товарищества, паев в паевых фондах кооперативов и паевых инвестиционных фондах, ценных бумаг и производных финансовых инструментов, за исключением базисного актива производных финансовых инструментов, подлежащего налогообложению налогом на добавленную стоимость. (В редакции федеральных законов от 03.07.2016 № 242-ФЗ, от 23.11.2020 № 374-ФЗ)\n\nВ целях настоящей главы под реализацией производного финансового инструмента понимается реализация его базисного актива, а также уплата сумм премий по контракту, сумм вариационной маржи, иные периодические или разовые выплаты сторон производного финансового инструмента, которые не являются в соответствии с условиями производного финансового инструмента оплатой базисного актива. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nОпределение производных финансовых инструментов, а также их базисного актива осуществляется в соответствии с пунктом 1 статьи 301 настоящего Кодекса; (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n(Подпункт в редакции Федерального закона от 25.11.2009 № 281-ФЗ)\n\n121) депозитарных услуг, оказываемых депозитарием средств Международного валютного фонда, Международного банка реконструкции и развития и Международной ассоциации развития в рамках статей Соглашений Международного валютного фонда, Международного банка реконструкции и развития и Международной ассоциации развития; (Дополнение подпунктом - Федеральный закон от 03.11.2010 № 291-ФЗ)\n\n122) следующих услуг: (В редакции Федерального закона от 24.11.2014 № 366-ФЗ)\n\nуслуг, оказываемых регистраторами, депозитариями, включая специализированные депозитарии и центральный депозитарий, дилерами, брокерами, управляющими ценными бумагами, управляющими компаниями инвестиционных фондов, паевых инвестиционных фондов и негосударственных пенсионных фондов, клиринговыми организациями, организаторами торговли, репозитариями на основании лицензий на осуществление соответствующих видов деятельности; (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nуслуг, оказываемых указанными в абзаце втором настоящего подпункта организациями, непосредственно связанных с услугами, оказываемыми ими в рамках лицензируемой деятельности (по перечню, установленному Правительством Российской Федерации);\n\nуслуг по проведению, контролю и учету товарных поставок по обязательствам, допущенным к клирингу, оказываемых операторами товарных поставок, получившими аккредитацию в соответствии с Федеральным законом от 7 февраля 2011 года № 7-ФЗ \"О клиринге и клиринговой деятельности\";\n\nуслуг по принятию на себя обязательств, подлежащих включению в клиринговый пул, оказываемых центральными контрагентами на основании лицензии на осуществление клиринговой деятельности либо при условии получения ими аккредитации в соответствии с Федеральным законом от 7 февраля 2011 года № 7-ФЗ \"О клиринге и клиринговой деятельности\";\n\nуслуг по поддержанию цен, спроса, предложения и (или) объема организованных торгов, оказываемых маркет-мейкерами в соответствии с Федеральным законом от 21 ноября 2011 года № 325-ФЗ \"Об организованных торгах\";\n\nуслуг по обеспечению взаимодействия участников финансовой платформы посредством информационно-телекоммуникационной сети \"Интернет\", оказываемых оператором финансовой платформы в соответствии с Федеральным законом от 20 июля 2020 года № 211-ФЗ \"О совершении финансовых сделок с использованием финансовой платформы\" в целях обеспечения возможности совершения финансовых сделок с использованием финансовой платформы; (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nуслуг по идентификации участников финансовой платформы, оказываемых оператором финансовой платформы финансовым организациям в соответствии с Федеральным законом от 20 июля 2020 года № 211-ФЗ \"О совершении финансовых сделок с использованием финансовой платформы\"; (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nуслуг по информационному обеспечению взаимодействия в целях совершения финансовых сделок, оказываемых оператором финансовой платформы участникам финансовой платформы в соответствии с Федеральным законом от 20 июля 2020 года № 211-ФЗ \"О совершении финансовых сделок с использованием финансовой платформы\" в порядке, предусмотренном правилами финансовой платформы; (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nуслуг по размещению (выкупу) облигаций федерального займа для физических лиц, оказываемых уполномоченными организациями, в том числе с использованием финансовой платформы; (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nуслуг, оказываемых оператором финансовой платформы и непосредственно связанных с услугами, указанными в абзацах седьмом - десятом настоящего подпункта (по перечню, утверждаемому Правительством Российской Федерации); (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nуслуг по определению суммы денежных средств (количества иного имущества), подлежащих передаче по договору, являющемуся производным финансовым инструментом, и (или) по договору, заключенному в целях обеспечения исполнения обязательств из договора, являющегося производным финансовым инструментом, предъявлению требований, предусмотренных указанными договорами, совершению иных действий, необходимых для осуществления прав и исполнения обязанностей каждой из сторон по указанным договорам, оказываемых клиринговыми организациями, кредитными организациями, брокерами или депозитариями на основании генерального соглашения (единого договора), договора, являющегося производным финан\n\nсовым инструментом, или договора, заключенного в целях обеспечения исполнения обязательств из договора, являющегося производным финансовым инструментом; (Дополнение абзацем - Федеральный закон от 16.04.2022 № 96-ФЗ)\n\nуслуг операторов информационных систем, в которых осуществляется выпуск цифровых финансовых активов, операторов обмена цифровых финансовых активов и (или) операторов инвестиционных платформ, осуществляющих деятельность по организации привлечения инвестиций в соответствии с Федеральным законом от 2 августа 2019 года № 259-ФЗ \"О привлечении инвестиций с использованием инвестиционных платформ и о внесении изменений в отдельные законодательные акты Российской Федерации\": по оценке технической возможности допуска цифровых финансовых активов и (или) цифровых прав, включающих одновременно цифровые финансовые активы и утилитарные цифровые права, к обращению в информационных системах (инвестиционных платформах); по предоставлению пользователям доступа к своим информационным системам (инвестиционным платформам), в которых осуществляются выпуск, учет и (или) обращение цифровых финансовых активов и (или) цифровых прав, включающих одновременно цифровые финансовые активы и утилитарные цифровые права; по внесению записей и (или) изменению записей о цифровых финансовых активах и (или) цифровых правах, включающих одновременно цифровые финансовые активы и утилитарные цифровые права, в информационных системах (инвестиционных платформах), в том числе о совершении перехода прав, удостоверенных такими цифровыми финансовыми активами и (или) цифровыми правами, к новому обладателю; по осуществлению с использованием номинальных счетов, открытых указанным операторам, расчетов, связанных с выпуском цифровых финансовых активов и (или) цифровых прав, включающих одновременно цифровые финансовые активы и утилитарные цифровые права, периодическими выплатами по таким цифровым финансовым активам и (или) цифровым правам, выкупом таких цифровых финансовых активов и (или) цифровых прав, а также по сделкам с ними (включая операции, связанные с переводом денежных средств и осуществляемые по номинальному счету); по идентификации пользователей информационных систем по поручению иных операторов информационных систем, в которых осуществляется выпуск цифровых финансовых активов, а также операторов обмена цифровых финансовых активов. Положения настоящего абзаца не распространяются на реализацию консультационных услуг и услуг по предоставлению прав на использование программ для электронных вычислительных машин (если иное не предусмотрено подпунктом 26 настоящего пункта); (Дополнение абзацем - Федеральный закон от 14.07.2022 № 324-ФЗ)\n\nуслуг, не указанных в абзаце тринадцатом настоящего подпункта и оказываемых операторами информационных систем, в которых осуществляется выпуск цифровых финансовых активов, операторами обмена цифровых финансовых активов и (или) операторами инвестиционных платформ, при условии, что такие услуги непосредственно связаны с выпуском цифровых финансовых активов и (или) цифровых прав, включающих одновременно цифровые финансовые активы и утилитарные цифровые права, их учетом, обращением, а также с выкупом (по перечню услуг, утверждаемому Правительством Российской Федерации). (Дополнение абзацем - Федеральный закон от 14.07.2022 № 324-ФЗ)\n\nВ целях настоящего Кодекса под выкупом цифрового финансового актива и (или) цифрового права, включающего одновременно цифровой финансовый актив и утилитарное цифровое право, понимается операция по исполнению лицом, выпустившим эти цифровой финансовый актив и (или) цифровое право, своего обязательства, удостоверенного этими цифровым финансовым активом и (или) цифровым правом, в результате которой происходит погашение записи об этих цифровом финансовом активе и (или) цифровом праве в информационной системе, путем выплаты денежных средств либо передачи ценных бумаг, товаров, иного имущества (выполнения работ, оказания услуг, передачи исключительных прав на результаты интеллектуальной деятельности и (или) прав использования результатов интеллектуальной деятельности) в соответствии с условиями решения о выпуске этих цифрового финансового актива и (или) цифрового права; (Дополнение абзацем - Федеральный закон от 14.07.2022 № 324-ФЗ)\n\nуслуг, оказываемых оператором автоматизированной информационной системы страхования по представлению содержащейся в автоматизированной информационной системе страхования информации в соответствии с Законом Российской Федерации от 27 ноября 1992 года № 4015-I \"Об организации страхового дела в Российской Федерации\"; (Дополнение абзацем - Федеральный закон от 19.12.2023 № 611-ФЗ)\n\nуслуг по расчету размера дополнительных стимулирующих взносов по договорам долгосрочных сбережений, оказываемых администратором софинасирования в соответствии с Федеральным законом от 7 мая 1998 года № 75-ФЗ \"О негосударственных пенсионных фондах\"; (Дополнение абзацем - Федеральный закон от 23.07.2025 № 228-ФЗ)\n\nуслуг, оказываемых администратором софинасирования и непосредственно связанных с услугами, указанными в абзаце семнадцатом настоящего подпункта (по перечню, утверждаемому Правительством Российской Федерации); (Дополнение абзацем - Федеральный закон от 23.07.2025 № 228-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 28.07.2012 № 145-ФЗ)\n\n13) (Подпункт утратил силу - Федеральный закон от 27.11.2018 № 424-ФЗ)\n\n14) услуг в сфере образования, оказываемых организациями, осуществляющими образовательную деятельность, являющимися некоммерческими организациями, по реализации основных и (или) дополнительных образовательных программ, предусмотренных лицензией, за исключением консультационных услуг, а также услуг по сдаче в аренду помещений. (В редакции федеральных законов от 27.11.2017 № 346-ФЗ, от 29.11.2021 № 383-ФЗ)\n\nРеализация организациями, осуществляющими образовательную деятельность, являющимися некоммерческими организациями, товаров (работ, услуг) как собственного производства, так и приобретенных на стороне подлежит налогообложению вне зависимости от того, направляется ли доход от этой реализации в данную организацию или на непосредственные нужды обеспечения развития, совершенствования образовательного процесса, если иное не предусмотрено настоящим Кодексом; (В редакции Федерального закона от 27.11.2017 № 346-ФЗ)\n\n(Подпункт в редакции Федерального закона от 18.07.2011 № 235-ФЗ)\n\n141) услуг по социальному обслуживанию несовершеннолетних детей; услуг по поддержке и социальному обслуживанию граждан пожилого возраста, инвалидов, безнадзорных детей и иных граждан, которые признаны нуждающимися в социальном обслуживании и которым предоставляются социальные услуги в организациях социального обслуживания в соответствии с законодательством Российской Федерации о социальном обслуживании и (или) законодательством Российской Федерации о профилактике безнадзорности и правонарушений несовершеннолетних; (В редакции Федерального закона от 29.12.2014 № 464-ФЗ)\n\nуслуг по выявлению несовершеннолетних граждан, нуждающихся в установлении над ними опеки или попечительства, включая обследование условий жизни таких несовершеннолетних граждан и их семей;\n\nуслуг по выявлению совершеннолетних недееспособных или не полностью дееспособных граждан, нуждающихся в установлении над ними опеки или попечительства, включая обследование условий жизни таких граждан и их семей;\n\nуслуг по подбору и подготовке граждан, выразивших желание стать опекунами или попечителями несовершеннолетних граждан либо принять детей, оставшихся без попечения родителей, в семью на воспитание в иных установленных семейным законодательством Российской Федерации формах;\n\nуслуг по подбору и подготовке граждан, выразивших желание стать опекунами или попечителями совершеннолетних недееспособных или не полностью дееспособных граждан;\n\nуслуг населению по организации и проведению физкультурных, физкультурно-оздоровительных и спортивных мероприятий;\n\nуслуг по профессиональной подготовке, переподготовке и повышению квалификации, оказываемых по направлению органов службы занятости;\n\n(Дополнение подпунктом - Федеральный закон от 18.07.2011 № 235-ФЗ)\n\n15) работ (услуг) по сохранению объекта культурного наследия (памятника истории и культуры) народов Российской Федерации, включенного в единый государственный реестр объектов культурного наследия (памятников истории и культуры) народов Российской Федерации (далее в настоящей главе - объекты культурного наследия), выявленного объекта культурного наследия, проведенных в соответствии с требованиями Федерального закона от 25 июня 2002 года № 73-ФЗ \"Об объектах культурного наследия (памятниках истории и культуры) народов Российской Федерации\", культовых зданий и сооружений, находящихся в пользовании религиозных организаций, включающих в себя консервационные, противоаварийные, ремонтные, реставрационные работы, работы по приспособлению объекта культурного наследия, выявленного объекта культурного наследия для современного использования, спасательные археологические полевые работы, в том числе научно-исследовательские, изыскательские, проектные и производственные работы, научное руководство проведением работ по сохранению объекта культурного наследия, выявленного объекта культурного наследия, технический и авторский надзор за проведением этих работ на объектах культурного наследия, выявленных объектах культурного наследия.\n\nРеализация работ (услуг), указанных в настоящем подпункте, не подлежит налогообложению (освобождается от налогообложения) при представлении в налоговые органы следующих документов:\n\nсправки об отнесении объекта к объектам культурного наследия, включенным в единый государственный реестр объектов культурного наследия (памятников истории и культуры) народов Российской Федерации, или справки об отнесении объекта к выявленным объектам культурного наследия, выданной федеральным органом исполнительной власти, уполномоченным Правительством Российской Федерации в области сохранения, использования, популяризации и государственной охраны объектов культурного наследия, или органом исполнительной власти субъекта Российской Федерации, исполнительно-распорядительным органом федеральной территории \"Сириус\", уполномоченным в области сохранения, использования, популяризации и государственной охраны объектов культурного наследия, в соответствии с Федеральным законом от 25 июня 2002 года № 73-ФЗ \"Об объектах культурного наследия (памятниках истории и культуры) народов Российской Федерации\"; (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\nкопии договора на выполнение указанных в настоящем подпункте работ;\n\n(Подпункт в редакции Федерального закона от 19.07.2011 № 245-ФЗ)\n\n16) (Подпункт утратил силу - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n161) услуг, оказываемых в рамках арбитража (третейского разбирательства), администрируемого постоянно действующим арбитражным учреждением в соответствии с Федеральным законом от 29 декабря 2015 года № 382-ФЗ \"Об арбитраже (третейском разбирательстве) в Российской Федерации\" и Законом Российской Федерации от 7 июля 1993 года № 5338-I \"О международном коммерческом арбитраже\", оплата за которые (в том числе в составе арбитражного сбора) осуществляется через некоммерческую организацию, подразделением которой является это постоянно действующее арбитражное учреждение; (Дополнение подпунктом - Федеральный закон от 28.12.2016 № 463-ФЗ)\n\n17) услуг, оказываемых уполномоченными на то органами, за которые взимается государственная пошлина, все виды лицензионных, регистрационных и патентных пошлин и сборов, таможенных сборов за хранение, а также пошлины и сборы, взимаемые государственными органами, органами местного самоуправления, органами публичной власти федеральной территории \"Сириус\", иными уполномоченными органами и должностными лицами при предоставлении организациям и физическим лицам определенных прав (в том числе платежи в бюджеты за право пользования природными ресурсами); (В редакции федеральных законов от 29.12.2000 № 166-ФЗ, от 22.07.2005 № 119-ФЗ, от 04.12.2006 № 201-ФЗ, от 11.06.2021 № 199-ФЗ)\n\n171) услуг по аккредитации операторов технического осмотра, которые оказываются в соответствии с законодательством в области технического осмотра транспортных средств профессиональным объединением страховщиков, созданным в соответствии с Федеральным законом от 25 апреля 2002 года № 40-ФЗ \"Об обязательном страховании гражданской ответственности владельцев транспортных средств\", и за которые взимается плата за аккредитацию; (Дополнение подпунктом - Федеральный закон от 01.07.2011 № 170-ФЗ)\n\n172) (Дополнение подпунктом - Федеральный закон от 01.07.2011 № 170-ФЗ) (Утратил силу - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n18) товаров, помещенных под таможенную процедуру магазина беспошлинной торговли; (В редакции Федерального закона от 27.11.2010 № 306-ФЗ)\n\n19) товаров (работ, услуг), за исключением подакцизных товаров, реализуемых (выполненных, оказанных) в рамках оказания безвозмездной помощи (содействия) Российской Федерации в соответствии с Федеральным законом \"О безвозмездной помощи (содействии) Российской Федерации и внесении изменений и дополнений в отдельные законодательные акты Российской Федерации о налогах и об установлении льгот по платежам в государственные внебюджетные фонды в связи с осуществлением безвозмездной помощи (содействия) Российской Федерации\". (В редакции Федерального закона от 07.07.2003 № 117-ФЗ)\n\nРеализация товаров (работ, услуг), указанных в настоящем подпункте, не подлежит налогообложению (освобождается от налогообложения) при представлении в налоговые органы следующих документов:\n\nконтракта (копии контракта) налогоплательщика с донором (уполномоченной донором организацией) безвозмездной помощи (содействия) или с получателем безвозмездной помощи (содействия) на поставку товаров (выполнение работ, оказание услуг) в рамках оказания безвозмездной помощи (содействия) Российской Федерации. В случае, если получателем безвозмездной помощи (содействия) является федеральный орган исполнительной власти Российской Федерации, в налоговый орган представляется контракт (копия контракта) с уполномоченной этим федеральным органом исполнительной власти Российской Федерации организацией; (В редакции Федерального закона от 22.07.2005 № 119-ФЗ)\n\nудостоверения (нотариально заверенной копии удостоверения), выданного в установленном порядке и подтверждающего принадлежность поставляемых товаров (выполняемых работ, оказываемых услуг) к гуманитарной или технической помощи (содействию);\n\nабзац. (Утратил силу - Федеральный закон от 17.12.2009 № 318-ФЗ)\n\nАбзац; (Утратил силу - Федеральный закон от 17.12.2009 № 318-ФЗ)\n\n20) услуг, оказываемых организациями, осуществляющими деятельность в сфере культуры и искусства, к которым относятся: (В редакции Федерального закона от 21.11.2011 № 330-ФЗ)\n\nуслуги по предоставлению напрокат аудио-, видеоносителей из фондов организаций, осуществляющих деятельность в сфере культуры и искусства, звукотехнического оборудования, музыкальных инструментов, сценических постановочных средств, костюмов, обуви, театрального реквизита, бутафории, постижерских принадлежностей, культинвентаря, животных, экспонатов и книг; услуги по изготовлению копий в учебных целях и учебных пособий, фотокопированию, репродуцированию, ксерокопированию, микрокопированию с печатной продукции, музейных экспонатов и документов из фондов организаций, осуществляющих деятельность в сфере культуры и искусства; услуги по звукозаписи театрально-зрелищных, культурно-просветительных и зрелищно-развлекательных мероприятий, по изготовлению копий звукозаписей из фонотек организаций, осуществляющих деятельность в сфере культуры и искусства; услуги по доставке читателям и приему у читателей печатной продукции из фондов библиотек; услуги по составлению списков, справок и каталогов экспонатов, материалов и других предметов и коллекций, составляющих фонд организаций, осуществляющих деятельность в сфере культуры и искусства; услуги по предоставлению в аренду сценических и концертных площадок другим организациям, осуществляющим деятельность в сфере культуры и искусства; услуги по распространению билетов, указанные в абзаце третьем настоящего подпункта; услуги по предоставлению музейных предметов, музейных коллекций, по организации выставок экспонатов, по показу спектаклей, концертов и концертных программ, иных зрелищных программ вне места нахождения организации, осуществляющей деятельность в сфере культуры и искусства; (В редакции федеральных законов от 21.11.2011 № 330-ФЗ; от 23.07.2013 № 215-ФЗ)\n\nреализация входных билетов и абонементов на посещение театрально-зрелищных, культурно-просветительных и зрелищно-развлекательных мероприятий, аттракционов в зоопарках, океанариумах и парках культуры и отдыха, экскурсионных билетов и экскурсионных путевок, форма которых утверждена в установленном порядке как бланк строгой отчетности; (В редакции Федерального закона от 18.07.2017 № 161-ФЗ)\n\nреализация программ на спектакли и концерты, каталогов и буклетов.\n\nК организациям, осуществляющим деятельность в сфере культуры и искусства, в целях настоящего подпункта относятся театры, кинотеатры, концертные организации и коллективы, театральные и концертные кассы, цирки, библиотеки, музеи, выставки, дома и дворцы культуры, клубы, дома (в частности, кино, литератора, композитора), планетарии, парки культуры и отдыха, лектории и народные университеты, экскурсионные бюро (за исключением туристических экскурсионных бюро), заповедники, ботанические сады и зоопарки, океанариумы, национальные парки, природные парки и ландшафтные парки; (В редакции федеральных законов от 21.11.2011 № 330-ФЗ; от 18.07.2017 № 161-ФЗ)\n\n(Подпункт в редакции Федерального закона от 18.07.2011 № 235-ФЗ)\n\n21) работ (услуг) по производству кинопродукции, выполняемых (оказываемых) организациями кинематографии, прав на использование (включая прокат и показ) кинопродукции, получившей удостоверение национального фильма; (В редакции Федерального закона от 29.12.2000 № 166-ФЗ)\n\n211) прав на использование охраняемых результатов интеллектуальной деятельности, использованных и (или) возникших при создании кинопродукции, получившей удостоверение национального фильма, в том числе анимационных фильмов, в части предоставления лицензий на использование персонажей, музыкальных произведений, иных охраняемых объектов авторских прав и смежных прав, вошедших в состав кинопродукции, получившей удостоверение национального фильма; (Дополнение подпунктом - Федеральный закон от 23.04.2018 № 95-ФЗ)\n\n22) услуг по аэронавигационному обслуживанию полетов воздушных судов; (В редакции Федерального закона от 25.12.2018 № 493-ФЗ)\n\n23) работ (услуг, включая услуги по ремонту) по обслуживанию морских судов, судов внутреннего плавания и судов смешанного (река - море) плавания в период стоянки в портах (все виды портовых сборов, услуги судов портового флота), по лоцманской проводке, а также услуг по классификации и освидетельствованию судов; (В редакции Федерального закона от 07.11.2011 № 305-ФЗ)\n\n24) услуг аптечных организаций по изготовлению лекарственных препаратов для медицинского применения, а также по изготовлению или ремонту очковой оптики (за исключением солнцезащитной), по ремонту слуховых аппаратов и протезно-ортопедических изделий, перечисленных в подпункте 1 пункта 2 настоящей статьи, услуги по оказанию протезно-ортопедической помощи; (Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ) (В редакции Федерального закона от 25.11.2013 № 317-ФЗ)\n\n25) (Дополнение подпунктом - Федеральный закон от 17.05.2007 № 85-ФЗ) (Утратил силу - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\n26) исключительных прав на программы для электронных вычислительных машин и базы данных, включенные в единый реестр российских программ для электронных вычислительных машин и баз данных и (или) единый реестр результатов научно-исследовательских, опытно-конс\n\nтрукторских и технологических работ военного, специального или двойного назначения, прав на использование таких программ и баз данных (включая обновления к ним и дополнительные функциональные возможности), в том числе путем предоставления удаленного доступа к ним через информационно-телекоммуникационную сеть, в том числе через информационно-телекоммуникационную сеть \"Интернет\". (В редакции  федеральных законов от 14.07.2022 № 321-ФЗ, от 19.12.2022 № 520-ФЗ)\n\nПоложения настоящего подпункта не применяются, если передаваемые права состоят в получении возможности распространять рекламную информацию в информационно-телекоммуникационной сети, в том числе в информационно-телекоммуникационной сети \"Интернет\", и (или) получать доступ к такой информации, размещать предложения (объявления) о приобретении (реализации) товаров (работ, услуг), имущественных прав в информационно-телекоммуникационной сети, в том числе в информационно-телекоммуникационной сети \"Интернет\", осуществлять поиск информации о потенциальных покупателях (продавцах) и (или) заключать сделки; (В редакции  Федерального закона от 14.07.2022 № 321-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 19.07.2007 № 195-ФЗ) (В редакции Федерального закона от 31.07.2020 № 265-ФЗ)\n\n261) исключительных прав на изобретения, полезные модели, промышленные образцы, топологии интегральных микросхем, секреты производства (ноу-хау), а также прав на использование указанных результатов интеллектуальной деятельности на основании лицензионного договора; (Дополнение подпунктом - Федеральный закон от 31.07.2020 № 265-ФЗ)\n\n262) исключительных прав на изобретения, полезные модели, промышленные образцы, топологии интегральных микросхем, секреты производства (ноу-хау), а также прав на использование указанных результатов интеллектуальной деятельности на основании договора коммерческой концессии.\n\nПоложения настоящего подпункта применяются при условии выделения в цене договора коммерческой концессии вознаграждения за передачу исключительных прав на изобретения, полезные модели, промышленные образцы, топологии интегральных микросхем, секреты производства (ноу-хау), а также прав на использование указанных результатов интеллектуальной деятельности;\n\n(Дополнение подпунктом - Федеральный закон от 16.04.2022 № 97-ФЗ)\n\n27) товаров (работ, услуг) и имущественных прав налогоплательщиками, являющимися российскими маркетинговыми партнерами Международного олимпийского комитета в соответствии со статьей 31 Федерального закона от 1 декабря 2007 года № 310-ФЗ \"Об организации и о проведении XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, развитии города Сочи как горноклиматического курорта и внесении изменений в отдельные законодательные акты Российской Федерации\", за исключением филиалов, представительств в Российской Федерации организаций, являющихся иностранными маркетинговыми партнерами Международного олимпийского комитета в соответствии со статьей 31 указанного Федерального закона, в связи с исполнением этими организациями обязательств маркетингового партнера Международного олимпийского комитета в рамках организации и проведения XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи; (Дополнение подпунктом - Федеральный закон от 30.07.2010 № 242-ФЗ)\n\n28) услуг по организации и проведению азартных игр; (Дополнение подпунктом - Федеральный закон от 23.07.2013 № 198-ФЗ)\n\n29) услуг по доверительному управлению средствами пенсионных накоплений, средствами выплатного резерва и средствами пенсионных накоплений застрахованных лиц, которым установлена срочная пенсионная выплата, оказываемых в соответствии с законодательством Российской Федерации в сфере формирования и инвестирования средств пенсионных накоплений; (Дополнение подпунктом - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\n291) услуг по доверительному управлению имуществом, составляющим ипотечное покрытие, оказываемых государственной управляющей компанией в соответствии с Федеральным законом от 11 ноября 2003 года № 152-ФЗ \"Об ипотечных ценных бумагах\"; (Дополнение подпунктом - Федеральный закон от 04.11.2022 № 431-ФЗ)\n\n30) операции по уступке (переуступке) прав (требований) по обязательствам, возникающим на основании производных финансовых инструментов, реализация которых освобождается от налогообложения согласно подпункту 12 настоящего пункта; (Дополнение подпунктом - Федеральный закон от 28.12.2013 № 420-ФЗ) (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n31) макулатуры. В целях настоящего Кодекса под макулатурой понимаются бумажные и картонные отходы производства и потребления, отбракованные и вышедшие из употребления бумага, картон, типографские изделия, деловые бумаги, в том числе документы с истекшим сроком хранения; (Дополнение подпунктом - Федеральный закон от 02.06.2016 № 174-ФЗ)\n\n32) следующих услуг:\n\nуслуг по реализации иностранными лицами прав на проведение чемпионата мира FIA \"Формула-1\", включающих в себя право на популяризацию мероприятия и право называть мероприятие российского этапа указанного чемпионата \"Чемпионат мира FIA \"Формула-1\";\n\nрекламных услуг, реализуемых организацией, которая приобрела права, указанные в абзаце втором настоящего подпункта, на территории объекта \"Трасса для проведения шоссейно-кольцевых автомобильных гонок серии \"Формула-1\" в Имеретинской низменности и объекты инфраструктуры, обеспечивающие ее функционирование\" в городе Сочи;\n\n(Дополнение подпунктом - Федеральный закон от 30.11.2016 № 401-ФЗ)\n\n321) следующих услуг:\n\nуслуг по реализации иностранными лицами прав на проведение чемпионата мира FIA \"Формула-1\", включающих в себя право на популяризацию мероприятия и право называть мероприятие российского этапа указанного чемпионата \"Чемпионат мира FIA \"Формула-1\";\n\nрекламных услуг, реализуемых организацией, которая приобрела права, указанные в абзаце втором настоящего подпункта, на территории объекта спорта для проведения шоссейно-кольцевых автомобильных гонок серии \"Формула-1\" и объектов инфраструктуры, обеспечивающих функционирование указанного объекта спорта;\n\n(Дополнение подпунктом - Федеральный закон от 11.06.2021 № 196-ФЗ)\n\n322) рекламных услуг, реализуемых организаторами Международного мультиспортивного турнира \"Игры будущего\" в 2024 году в городе Казани спонсорам указанного спортивного соревнования в связи с организацией и проведением Международного мультиспортивного турнира \"Игры будущего\" в 2024 году в городе Казани; (Дополнение подпунктом - Федеральный закон от 19.12.2023 № 611-ФЗ)\n\n33) услуг по передаче медицинских изделий, указанных в абзаце четвертом подпункта 1 настоящего пункта, имеющих соответствующее регистрационное удостоверение, по договорам финансовой аренды (лизинга) с правом выкупа; (Дополнение подпунктом - Федеральный закон от 18.07.2017 № 161-ФЗ)\n\n331) услуг по предоставлению в аренду автомобилей скорой медицинской помощи с экипажем (водителем) медицинским организациям государственной и муниципальной системы здравоохранения в целях оказания указанными медицинскими организациями услуг скорой медицинской помощи населению; (Дополнение подпунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n332) услуг по перевозке автомобилями скорой медицинской помощи бригад скорой медицинской помощи, включая медицинскую эвакуацию граждан, по договорам с медицинскими организациями государственной и муниципальной системы здравоохранения в целях оказания указанными медицинскими организациями услуг скорой медицинской помощи населению; (Дополнение подпунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n34) материальных ценностей, выпускаемых из государственного материального резерва ответственным хранителям и заемщикам в связи с их освежением, заменой и в порядке заимствования в соответствии с Федеральным законом от 29 декабря 1994 года № 79-ФЗ \"О государственном материальном резерве\"; (Дополнение подпунктом - Федеральный закон от 14.11.2017 № 316-ФЗ)\n\n35) услуг по техническому управлению морскими судами и судами смешанного (река - море) плавания, оказываемых иностранным лицам, не состоящим на учете в налоговых органах в качестве налогоплательщиков и эксплуатирующим морские суда и суда смешанного (река - море) плавания, зарегистрированные в судовых реестрах иностранных государств. Перечень указанных услуг по техническому управлению морскими судами определяется Правительством Российской Федерации; (Дополнение подпунктом - Федеральный закон от 27.11.2018 № 424-ФЗ)\n\n36) услуг по обращению с твердыми коммунальными отходами, оказываемых региональными операторами по обращению с твердыми коммунальными отходами.\n\nВ целях настоящего подпункта к услугам по обращению с твердыми коммунальными отходами относятся услуги, в отношении которых органом исполнительной власти субъекта Российской Федерации, осуществляющим государственное регулирование тарифов, либо органом местного самоуправления, осуществляющим регулирование тарифов (в случае передачи ему соответствующих полномочий законом субъекта Российской Федерации) (далее в настоящем подпункте - орган регулирования тарифов), утвержден предельный единый тариф на услуги регионального оператора по обращению с твердыми коммунальными отходами без учета налога.\n\nПоложения настоящего подпункта подлежат применению налогоплательщиком в течение пяти последовательных календарных лет начиная с года, в котором введен в действие предельный единый тариф на услуги регионального оператора по обращению с твердыми коммунальными отходами без учета налога, вне зависимости от последующего установления органом регулирования тарифов предельного единого тарифа на услуги регионального оператора по обращению с твердыми коммунальными отходами с учетом налога в течение указанного периода;\n\n(Дополнение подпунктом - Федеральный закон от 26.07.2019 № 211-ФЗ)\n\n37) государственных (муниципальных) услуг в социальной сфере, оказываемых в соответствии с соглашениями, заключенными по результатам отбора исполнителей государственных (муниципальных) услуг в социальной сфере в соответствии с законодательством Российской Федерации о государственном (муниципальном) социальном заказе на оказание государственных (муниципальных) услуг в социальной сфере (за исключением соглашения о предоставлении субсидии на финансовое обеспечение выполнения государственного (муниципального) задания); (Дополнение подпунктом - Федеральный закон от 13.07.2020 № 191-ФЗ)\n\n38) цифровых финансовых активов; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 324-ФЗ)\n\n39) имущества (за исключением денежных средств) и (или) имущественных прав физическому лицу налогоплательщиком - иностранной организацией (иностранной структурой без образования юридического лица), доходы от получения которых данного физического лица подлежат освобождению от налогообложения налогом на доходы физических лиц в соответствии с пунктом 602 статьи 217 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n40) имущества физическому лицу, доходы от получения которого данного физического лица подлежат освобождению от налогообложения налогом на доходы физических лиц в соответствии с пунктом 93 статьи 217 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 21.11.2022 № 443-ФЗ)\n\n41) работ (услуг), имущественных прав, выполняемых (оказываемых), передаваемых некоммерческими организациями в рамках реализации ими федеральных проектов, источником финансового обеспечения которых является субсидия из федерального бюджета, предоставленная на основании федерального закона о федеральном бюджете на текущий финансовый год и плановый период указанным организациям, которые определены этим федеральным законом как получатели субсидии; (Дополнение подпунктом - Федеральный закон от 19.12.2022 № 523-ФЗ)\n\n42) лекарственных препаратов, ввезенных на территорию Российской Федерации и не зарегистрированных в Российской Федерации, некоммерческой организации, которая создана в соответствии с нормативным правовым актом Президента Российской Федерации в целях обеспечения оказания медицинской помощи детям с тяжелыми жизнеугрожающими и хроническими заболеваниями, в том числе редкими (орфанными) заболеваниями, а также безвозмездная передача указанных лекарственных препаратов медицинской организации и (или) фармацевтической организации государственной системы здравоохранения. Положения настоящего подпункта применяются в отношении реализации (передачи) лекарственных препаратов, предназначенных для оказания медицинской помощи детям с тяжелыми жизнеугрожающими и хроническими заболеваниями, в том числе редкими (орфанными) заболеваниями, и (или) для оказания медицинской помощи лицам, достигшим возраста 18 лет, в течение одного года после достижения ими указанного возраста в случае получения ими такой формы поддержки в рамках деятельности этой некоммерческой организации до достижения возраста 18 лет; (Дополнение подпунктом - Федеральный закон от 24.06.2023 № 262-ФЗ)\n\n43) услуг оператора по проведению операций в реестре углеродных единиц в соответствии с законодательством Российской Федерации в области ограничения выбросов парниковых газов и законодательством Российской Федерации, регламентирующим порядок проведения эксперимента по ограничению выбросов парниковых газов в отдельных субъектах Российской Федерации; (Дополнение подпунктом - Федеральный закон от 26.02.2024 № 37-ФЗ)\n\n44) услуг уполномоченной организации, обеспечивающей заключение сделок с цифровой валютой в рамках экспериментального правового режима, оказываемых в рамках экспериментального правового режима в сфере цифровых инноваций, установленного в соответствии со статьей 11 Федерального закона от 31 июля 2020 года № 259-ФЗ \"О цифровых финансовых активах, цифровой валюте и о внесении изменений в отдельные законодательные акты Российской Федерации\". (Дополнение подпунктом - Федеральный закон от 29.11.2024 № 418-ФЗ)\n\n1) реализация (передача для собственных нужд) предметов религиозного назначения и религиозной литературы (в соответствии с перечнем, утверждаемым Правительством Российской Федерации по представлению религиозных организаций (объединений), производимых религиозными организациями (объединениями) и организациями, единственными учредителями (участниками) которых являются религиозные организации (объединения), и реализуемых данными или иными религиозными организациями (объединениями) и организациями, единственными учредителями (участниками) которых являются религиозные организации (объединения), в рамках религиозной деятельности, за исключением подакцизных товаров и минерального сырья, а также организация и проведение указанными организациями религиозных обрядов, церемоний, молитвенных собраний или других культовых действий; (В редакции федеральных законов от 29.12.2000 № 166-ФЗ; от 29.05.2002 № 57-ФЗ; от 03.11.2006 № 176-ФЗ)\n\n2) реализация (в том числе передача, выполнение, оказание для собственных нужд) товаров (за исключением подакцизных, минерального сырья и полезных ископаемых, а также других товаров по перечню, утверждаемому Правительством Российской Федерации по представлению общероссийских общественных организаций инвалидов), работ, услуг (за исключением брокерских и иных посреднических услуг, не указанных в подпункте 122 пункта 2 настоящей статьи), производимых и реализуемых: (В редакции федеральных законов от 29.12.2000 № 166-ФЗ; от 28.07.2012 № 145-ФЗ)\n\nобщественными организациями инвалидов (в том числе созданными как союзы общественных организаций инвалидов), среди членов которых инвалиды и их законные представители составляют не менее 80 процентов;\n\nорганизациями, уставный капитал которых полностью состоит из вкладов указанных в абзаце втором настоящего подпункта общественных организаций инвалидов, если среднесписочная численность инвалидов среди их работников составляет не менее 50 процентов, а их доля в фонде оплаты труда - не менее 25 процентов;\n\nучреждениями, единственными собственниками имущества которых являются указанные в абзаце втором настоящего подпункта общественные организации инвалидов, созданными для достижения образовательных, культурных, лечебно-оздоровительных, физкультурно-спортивных, научных, информационных и иных социальных целей, а также для оказания правовой и иной помощи инвалидам, детям-инвалидам и их родителям;\n\nлечебно-производственными (трудовыми) мастерскими (отделениями) медицинских организаций, оказывающих психиатрическую помощь, наркологическую помощь и противотуберкулезную помощь, стационарных организаций социального обслуживания, предназначенных для лиц, страдающих психическими расстройствами, а также лечебно-производственными (трудовыми) мастерскими лечебных исправительных учреждений уголовно-исполнительной системы; (В редакции федеральных законов от 25.11.2013 № 317-ФЗ; от 24.11.2014 № 366-ФЗ)\n\nгосударственными и муниципальными унитарными предприятиями, если среднесписочная численность инвалидов среди их работников составляет не менее 50 процентов, а их доля в фонде оплаты труда не менее 25 процентов; (Дополнение абзацем - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\n3) осуществление банками и банком развития - государственной корпорацией банковских операций (за исключением инкассации), в том числе: (В редакции Федерального закона от 29.12.2017 № 466-ФЗ)\n\nпривлечение денежных средств организаций и физических лиц во вклады;\n\nразмещение привлеченных денежных средств организаций и физических лиц от имени банков и за их счет;\n\nоткрытие и ведение банковских счетов организаций и физических лиц, в том числе банковских счетов, служащих для расчетов по банковским картам, а также операции, связанные с обслуживанием банковских карт; (В редакции Федерального закона от 22.07.2005 № 119-ФЗ)\n\nосуществление переводов по поручению организаций и физических лиц, в том числе банков-корреспондентов, по их банковским счетам; (В редакции Федерального закона от 26.07.2019 № 212-ФЗ)\n\nкассовое обслуживание организаций и физических лиц;\n\nкупля-продажа иностранной валюты в наличной и безналичной формах (в том числе оказание посреднических услуг по операциям купли-продажи иностранной валюты);\n\nпривлечение драгоценных металлов физических и юридических лиц во вклады (до востребования и на определенный срок), за исключением монет из драгоценных металлов; (В редакции Федерального закона от 26.07.2019 № 212-ФЗ)\n\nразмещение указанных в абзаце восьмом настоящего подпункта привлеченных драгоценных металлов от своего имени и за свой счет; (В редакции Федерального закона от 26.07.2019 № 212-ФЗ)\n\nоткрытие и ведение банковских счетов физических и юридических лиц в драгоценных металлах, за исключением монет из драгоценных металлов; (В редакции Федерального закона от 26.07.2019 № 212-ФЗ)\n\nосуществление переводов по поручению физических и юридических лиц, в том числе банков-корреспондентов, по их банковским счетам в драгоценных металлах; (В редакции Федерального закона от 26.07.2019 № 212-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 28.02.2006 № 28-ФЗ) (Утратил силу - Федеральный закон от 26.07.2019 № 212-ФЗ)\n\n(Подпункт в редакции Федерального закона от 29.12.2000 № 166-ФЗ)\n\n31) услуг, связанных с обслуживанием банковских карт; (Дополнение подпунктом - Федеральный закон от 22.07.2005 № 119-ФЗ)\n\n32) осуществление банками и банком развития - государственной корпорацией следующих операций:\n\nисполнение банковских гарантий (выдача и аннулирование банковской гарантии, подтверждение и изменение условий указанной гарантии, платеж по указанной гарантии, оформление и проверка документов по этой гарантии);\n\nвыдача поручительств за третьих лиц, предусматривающих исполнение обязательств в денежной форме;\n\nоказание услуг, связанных с ус\n\nтановкой и эксплуатацией системы \"клиент-банк\", включая предоставление программного обеспечения и обучение обслуживающего указанную систему персонала;\n\nполучение от заемщиков сумм в счет компенсации страховых премий (страховых взносов), уплаченных банком по договорам страхования, в том числе по договорам страхования на случай смерти или наступления инвалидности указанных заемщиков, по договорам страхования имущества, являющегося обеспечением обязательств заемщика (залогом), и иным видам страхования, в которых банк является страхователем;\n\n(Дополнение подпунктом - Федеральный закон от 26.07.2019 № 212-ФЗ)\n\n33) осуществление оператором платформы цифрового рубля следующих операций:\n\nоткрытие и ведение счетов цифрового рубля организаций и физических лиц;\n\nосуществление переводов (перечислений) денежных средств с использованием платформы цифрового рубля;\n\n(Дополнение подпунктом - Федеральный закон от 19.12.2023 № 610-ФЗ)\n\n4) операции, осуществляемые организациями, обеспечивающими информационное и технологическое взаимодействие между участниками расчетов, включая оказание услуг по сбору, обработке и предоставлению участникам расчетов информации по операциям с банковскими картами; (В редакции Федерального закона от 11.07.2011 № 200-ФЗ)\n\n5) осуществление отдельных банковских операций организациями, которые в соответствии с законодательством Российской Федерации вправе их совершать без лицензии Центрального банка Российской Федерации;\n\n6) реализация изделий народных художественных промыслов признанного художественного достоинства (за исключением подакцизных товаров), образцы которых зарегистрированы в порядке, установленном уполномоченным Правительством Российской Федерации федеральным органом исполнительной власти; (В редакции Федерального закона от 23.07.2008 № 160-ФЗ)\n\n7) оказание услуг по страхованию, сострахованию и перестрахованию страховщиками, а также оказание услуг по негосударственному пенсионному обеспечению и (или) формированию долгосрочных сбережений негосударственными пенсионными фондами. (В редакции  федеральных законов от 30.12.2012 № 294-ФЗ, от 23.03.2024 № 58-ФЗ)\n\nВ целях настоящей статьи операциями по страхованию, сострахованию и перестрахованию признаются операции, в результате которых страховщик получает: (В редакции федеральных законов от 29.12.2000 № 166-ФЗ; от 30.12.2012 № 294-ФЗ)\n\nстраховые платежи (вознаграждения) по договорам страхования, сострахования и перестрахования, включая страховые взносы, выплачиваемую перестраховочную комиссию (в том числе тантьему); (В редакции Федерального закона от 29.12.2000 № 166-ФЗ)\n\nпроценты, начисленные на депо премии по договорам перестрахования и перечисленные перестрахователем перестраховщику;\n\nстраховые взносы, полученные уполномоченным страховщиком, заключившим в установленном порядке договор сострахования от имени и по поручению страховщиков; (В редакции Федерального закона от 30.12.2012 № 294-ФЗ)\n\nсредства, полученные страховщиком в порядке суброгации, от лица, ответственного за причиненный страхователю ущерб, в размере страхового возмещения, выплаченного страхователю; (В редакции Федерального закона от 29.12.2000 № 166-ФЗ)\n\nсредства, полученные страховщиком по заключенному в соответствии с законодательством Российской Федерации об обязательном страховании гражданской ответственности владельцев транспортных средств соглашению о прямом возмещении убытков от страховщика, который застраховал гражданскую ответственность лица, причинившего вред; (Дополнение абзацем - Федеральный закон от 25.12.2008 № 282-ФЗ)\n\nцелевые средства, получаемые страховыми медицинскими организациями - участниками обязательного медицинского страхования от территориального фонда обязательного медицинского страхования в соответствии с договором о финансовом обеспечении обязательного медицинского страхования; (Дополнение абзацем - Федеральный закон от 29.11.2010 № 313-ФЗ)\n\nсредства, получаемые страховыми медицинскими организациями - участниками обязательного медицинского страхования от территориального фонда обязательного медицинского страхования и предназначенные на расходы на ведение дела по обязательному медицинскому страхованию в соответствии с договором о финансовом обеспечении обязательного медицинского страхования (в пределах норматива, установленного законодательством Российской Федерации об обязательном медицинском страховании); (Дополнение абзацем - Федеральный закон от 29.11.2010 № 313-ФЗ)\n\nсредства, получаемые страховыми медицинскими организациями - участниками обязательного медицинского страхования от территориального фонда обязательного медицинского страхования, являющиеся вознаграждением за выполнение действий, предусмотренных договором о финансовом обеспечении обязательного медицинского страхования; (Дополнение абзацем - Федеральный закон от 29.11.2010 № 313-ФЗ)\n\n71) оказание услуг по страхованию и перестрахованию организацией, выполняющей функции по осуществлению страховой и гарантийной поддержки экспорта и импорта в соответствии с Федеральным законом от 8 декабря 2003 года № 164-ФЗ \"Об основах государственного регулирования внешнеторговой деятельности\"; (Дополнение подпунктом - Федеральный закон от 19.07.2011 № 245-ФЗ) (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n8) (Подпункт утратил силу - Федеральный закон от 23.07.2013 № 198-ФЗ)\n\n81) проведение лотерей, проводимых по решению уполномоченного органа исполнительной власти, включая оказание услуг по реализации лотерейных билетов; (Дополнение подпунктом - Федеральный закон от 22.07.2005 № 119-ФЗ)\n\n9) реализация руды, концентратов и других промышленных продуктов, содержащих драгоценные металлы, лома и отходов драгоценных металлов для производства драгоценных металлов и аффинажа; реализация драгоценных металлов налогоплательщиками (за исключением указанных в подпунктах 6 и 62 пункта 1 статьи 164 настоящего Кодекса) Государственному фонду драгоценных металлов и драгоценных камней Российской Федерации, фондам драгоценных металлов и драгоценных камней субъектов Российской Федерации, Центральному банку Российской Федерации, организации, изготавливающей банкноты и монету Банка России, и банкам; реализация драгоценных металлов из Государственного фонда драгоценных металлов и драгоценных камней Российской Федерации, из фондов драгоценных металлов и драгоценных камней субъектов Российской Федерации специализированным внешнеэкономическим организациям, Центральному банку Российской Федерации и банкам; реализация драгоценных металлов в слитках Центральным банком Российской Федерации и банками Центральному банку Российской Федерации, банкам и организации, изготавливающей банкноты и монету Банка России, в том числе по договорам поручения, комиссии либо агентским договорам с Центральным банком Российской Федерации и банками, независимо от помещения этих слитков в хранилище Центрального банка Российской Федерации или хранилища банков; реализация драгоценных металлов в слитках (за исключением серебра в слитках) банками, аффинажными организациями, имеющими право осуществлять аффинаж драгоценных металлов, организацией, изготавливающей банкноты и монету Банка России, физическим лицам независимо от помещения этих слитков в хранилища банков, а также реализация драгоценных металлов в слитках Центральным банком Российской Федерации и банками иным лицам при условии, что эти слитки остаются в одном из хранилищ (Государственном хранилище ценностей, хранилище Центрального банка Российской Федерации или хранилищах банков); (В редакции  федеральных законов от 29.12.2022 № 596-ФЗ, от 31.07.2023 № 389-ФЗ, от 23.03.2024 № 49-ФЗ)\n\n91) реализация драгоценных камней налогоплательщиками (за исключением указанных в подпункте 61 пункта 1 статьи 164 настоящего Кодекса) Государственному фонду драгоценных металлов и драгоценных камней Российской Федерации, фондам драгоценных металлов и драгоценных камней субъектов Российской Федерации, Центральному банку Российской Федерации и банкам; реализация необработанных драгоценных камней (за исключением необработанных природных алмазов) для обработки предприятиям независимо от форм собственности для последующей продажи на экспорт; реализация драгоценных камней в сырье и ограненных (за исключением указанных в подпункте 61 пункта 1 статьи 164 настоящего Кодекса) специализированным внешнеэкономическим организациям; реализация обработанных природных алмазов Центральным банком Российской Федерации и банками Центральному банку Российской Федерации и банкам, в том числе по договорам поручения, комиссии либо агентским договорам с Центральным банком Российской Федерации и банками, независимо от помещения этих обработанных природных алмазов в хранилище Центрального банка Российской Федерации или хранилища банков; реализация обработанных природных алмазов банками физическим лицам независимо от помещения этих обработанных природных алмазов в хранилища банков; реализация необработанных природных алмазов из Государственного фонда драгоценных металлов и драгоценных камней Российской Федерации, из фондов драгоценных металлов и драгоценных камней субъектов Российской Федерации обрабатывающим предприятиям всех форм собственности; (Дополнение подпунктом - Федеральный закон от 29.12.2022 № 596-ФЗ) (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n10) (Подпункт утратил силу - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n11) внутрисистемная реализация (передача, выполнение, оказание для собственных нужд) организациями и учреждениями уголовно-исполнительной системы произведенных ими товаров (выполненных работ, оказанных услуг);\n\n12) передача товаров (выполнение работ, оказание услуг), передача имущественных прав безвозмездно в рамках благотворительной деятельности в соответствии с Федеральным законом от 11 августа 1995 года № 135-ФЗ \"О благотворительной деятельности и добровольчестве (волонтерстве)\", за исключением подакцизных товаров. (В редакции федеральных законов от 18.07.2011 № 235-ФЗ, от 23.04.2018 № 98-ФЗ, от 26.07.2019 № 210-ФЗ)\n\nПри этом, если получателями товаров (работ, услуг), имущественных прав, указанных в абзаце первом настоящего подпункта, являются организация и (или) индивидуальный предприниматель, документами, подтверждающими право на освобождение от налогообложения в соответствии с настоящим подпунктом, являются: (Дополнение абзацем - Федеральный закон от 26.07.2019 № 210-ФЗ)\n\nдоговор или контракт о безвозмездной передаче налогоплательщиком товаров (работ, услуг), имущественных прав, указанных в абзаце первом настоящего подпункта; (Дополнение абзацем - Федеральный закон от 26.07.2019 № 210-ФЗ)\n\nакт приема-передачи товаров (работ, услуг), имущественных прав или иной документ, подтверждающий передачу налогоплательщиком товаров, имущественных прав (выполнение работ, оказание услуг); (Дополнение абзацем - Федеральный закон от 26.07.2019 № 210-ФЗ)\n\n13) реализация входных билетов и абонементов, форма которых утверждена в установленном порядке как бланк строгой отчетности, организациями физической культуры и спорта на проводимые ими спортивно-зрелищные мероприятия; оказание услуг по предоставлению в аренду спортивных сооружений для подготовки и проведения указанных мероприятий; (В редакции федеральных законов от 19.07.2011 № 245-ФЗ; от 29.12.2014 № 479-ФЗ)\n\n14) оказание услуг коллегиями адвокатов, адвокатскими бюро, адвокатскими палатами субъектов Российской Федерации или Федеральной палатой адвокатов своим членам в связи с осуществлением ими профессиональной деятельности; (В редакции федеральных законов от 31.12.2002 № 187-ФЗ; от 27.07.2006 № 137-ФЗ)\n\n15) операции займа в денежной форме и ценными бумагами, включая проценты по ним, операции финансирования участия в кредите (займе) в денежной форме, включая проценты по ним,  операции по предоставлению обеспечительного платежа в денежной форме или ценными бумагами, включая денежные суммы, подлежащие уплате за предоставление обеспечительного платежа, осуществляемые в соответствии с Федеральным законом \"О рынке ценных бумаг\" по договорам репо, договорам, являющимся производными финансовыми инструментами, и (или) договорам иного вида, объектом которых являются ценные бумаги и (или) иностранная валюта, в том числе по указанным договорам, заключаемым на условиях, определенных генеральным соглашением (единым договором), а также операции РЕПО, включая денежные суммы, подлежащие уплате за предоставление ценных бумаг по операциям РЕПО. (В редакции  федеральных законов от 16.04.2022 № 96-ФЗ, от 14.07.2022 № 323-ФЗ)\n\nВ целях настоящей главы операцией РЕПО признается договор, отвечающий требованиям, предъявляемым к договорам репо Федеральным законом \"О рынке ценных бумаг\". (В редакции  Федерального закона от 14.07.2022 № 323-ФЗ)\n\nВ целях настоящего Кодекса операцией финансирования участия в кредите (займе) признается соглашение, заключаемое в соответствии с Федеральным законом от 31 декабря 2017 года № 486-ФЗ \"О синдицированном кредите (займе) и внесении изменений в отдельные законодательные акты Российской Федерации\" или применимым законодательством иностранных государств; (Дополнение абзацем - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n(Подпункт в редакции Федерального закона от 25.11.2009 № 281-ФЗ)\n\n151) (Дополнение подпунктом - Федеральный закон от 22.07.2005 № 119-ФЗ) (Утратил силу - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\n152) операции, осуществляемые в рамках клиринговой деятельности:\n\nпередача (возврат) имущества, предназначенного для коллективного клирингового обеспечения и (или) индивидуального клирингового обеспечения, а также передача (возврат) имущества в имущественный пул клиринговой организации (из имущественного пула клиринговой организации); (В редакции Федерального закона от 28.11.2015 № 326-ФЗ)\n\nвыплата процентов, начисленных на средства гарантийного фонда, формируемого за счет имущества, являющегося предметом коллективного клирингового обеспечения и (или) индивидуального клирингового обеспечения, подлежащих уплате клиринговой организацией участникам клиринга и иным лицам в соответствии с правилами клиринга такой клиринговой организации на основании Федерального закона от 7 февраля 2011 года № 7-ФЗ \"О клиринге и клиринговой деятельности\";\n\n(Дополнение подпунктом - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\n153) операции по выдаче поручительств (гарантий) налогоплательщиком, не являющимся банком; (Дополнение подпунктом - Федеральный закон от 30.11.2016 № 401-ФЗ)\n\n154) передача денежных средств на финансирование участия управляющего товарища в соглашении о сервисных рисках в качестве оператора, осуществляемое по соглашению об управлении финансированием, а также передача денежных средств управляющим товарищем в результате распределения денежных средств по соглашению об управлении финансированием; (Дополнение подпунктом - Федеральный закон от 17.02.2023 № 22-ФЗ)\n\n16) выполнение научно-исследовательских и опытно-конструкторских работ за счет средств бюджетов бюджетной системы Российской Федерации, средств Российского фонда фундаментальных исследований, Российского фонда технологического развития и фондов поддержки научной, научно-технической, инновационной деятельности, созданных для этих целей в соответствии с Федеральным законом от 23 августа 1996 года № 127-ФЗ \"О науке и государственной научно-технической политике\"; выполнение научно-исследовательских и опытно-конструкторских работ организациями, осуществляющими образовательную деятельность, и научными организациями на основе хозяйственных договоров; (В редакции федеральных законов от 23.07.2013 № 215-ФЗ; от 27.11.2017 № 346-ФЗ)\n\n161) выполнение организациями научно-исследовательских, опытно-конструкторских и технологических работ, относящихся к созданию новых продукции и технологий или к усовершенствованию производимой продукции и технологий, если в состав научно-исследовательских, опытно-конструкторских и технологических работ включаются следующие виды деятельности:\n\nразработка конструкции инженерного объекта или технической системы;\n\nразработка новых технологий, то есть способов объединения физических, химических, технологических и других процессов с трудовыми процессами в целостную систему, производящую новую продукцию (товары, работы, услуги);\n\nсоздание опытных, то есть не имеющих сертификата соответствия, образцов машин, оборудования, материалов, обладающих характерными для нововведений принципиальными особенностями и не предназначенных для реализации третьим лицам, их испытание в течение времени, необходимого для получения данных, накопления опыта и отражения их в технической документации;\n\n(Дополнение подпунктом - Федеральный закон от 19.07.2007 № 195-ФЗ)\n\n17) (Подпункт утратил силу - Федеральный закон от 05.08.2000 № 118-ФЗ)\n\n18) услуги санаторно-курортных, оздоровительных организаций и организаций отдыха, организаций отдыха и оздоровления детей, в том числе детских оздоровительных лагерей, расположенных на территории Российской Федерации, оформленные путевками или курсовками, являющимися бланками строгой отчетности; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 22.07.2005 № 119-ФЗ)\n\n19) проведение работ (оказание услуг) по тушению лесных пожаров;\n\n20) реализация продукции собственного производства организаций, занимающихся производством сельскохозяйственной продукции, удельный вес доходов от реализации которой в общей сумме их доходов составляет не менее 70 процентов, в счет натуральной оплаты труда, натуральных выдач для оплаты труда, а также для общественного питания работников, привлекаемых на сельскохозяйственные работы; (В редакции Федерального закона от 29.12.2000 № 166-ФЗ)\n\n21) (Подпункт утратил силу - Федеральный закон от 05.08.2000 № 118-ФЗ)\n\n22) реализация жилых домов, жилых помещений, а также долей в них; (Дополнение подпунктом - Федеральный закон от 20.08.2004 № 109-ФЗ)\n\n23) передача доли в праве на общее имущество в многоквартирном доме при реализации квартир; (Дополнение подпунктом - Федеральный закон от 20.08.2004 № 109-ФЗ)\n\n231) услуги застройщика, оказываемые на основании договора участия в долевом строительстве, заключенного в соответствии с Федеральным законом от 30 декабря 2004 года № 214-ФЗ \"Об участии в долевом строительстве многоквартирных домов и иных объектов недвижимости и о внесении изменений в некоторые законодательные акты Российской Федерации\", согласно которому объектами долевого строительства являются жилые дома либо входящие в состав многоквартирных домов жилые и (или) нежилые помещения, машино-места. Положения настоящего подпункта не применяются в отношении услуг застройщика, оказываемых при строительстве помещений, предназначенных для временного проживания (без права на постоянную регистрацию); (Дополнение подпунктом - Федеральный закон от 17.06.2010 № 119-ФЗ) (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n232) работы подрядчика, выполняемые на основании договора строительного подряда, заключенного с физическим лицом в соответствии с Федеральным законом от 22 июля 2024 года № 186-ФЗ \"О строительстве жилых домов по договорам строительного подряда с использованием счетов эскроу\"; (Дополнение подпунктом - Федеральный закон от 08.08.2024 № 283-ФЗ)\n\n24) (Дополнение подпунктом - Федеральный закон от 22.07.2005 № 119-ФЗ) (Утратил силу - Федеральный закон от 17.05.2007 № 85-ФЗ)\n\n25) передача в рекламных целях товаров (работ, услуг), расходы на приобретение (создание) единицы которых не превышают 300 рублей; (Дополнение подпунктом - Федеральный закон от 22.07.2005 № 119-ФЗ) (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n26) операции по уступке (переуступке, приобретению) прав (требований) кредитора по обязательствам, вытекающим из договоров по предоставлению займов в денежной форме и (или) кредитных договоров, соглашений о финансировании участия в кредите (займе) в денежной форме, а также по исполнению заемщиком обязательств перед каждым новы\n\nм кредитором по первоначальному договору, лежащему в основе договора уступки; (Дополнение подпунктом - Федеральный закон от 19.07.2007 № 195-ФЗ) (В редакции  федеральных законов от 25.11.2009 № 281-ФЗ, от 14.07.2022 № 323-ФЗ)\n\n261) операции по уступке (переуступке) денежного требования кредитора по обязательствам, возникшим в связи с привлечением к ответственности в соответствии с законодательством Российской Федерации о несостоятельности (банкротстве) лиц, контролировавших кредитную организацию, лиц, контролирующих (контролировавших) должников кредитной организации, а также по исполнению указанными лицами обязательств перед каждым новым кредитором, получившим денежное требование на основании договора уступки; (Дополнение подпунктом - Федеральный закон от 21.11.2022 № 443-ФЗ)\n\n27) проведение работ (оказание услуг) резидентами портовой особой экономической зоны в портовой особой экономической зоне; (Дополнение подпунктом - Федеральный закон от 30.10.2007 № 240-ФЗ)\n\n28) безвозмездное оказание услуг по предоставлению эфирного времени и (или) печатной площади в соответствии с законодательством Российской Федерации о выборах и референдумах; (Дополнение подпунктом - Федеральный закон от 17.07.2009 № 161-ФЗ)\n\n281) безвозмездное оказание услуг по предоставлению эфирного времени и (или) печатной площади в соответствии с Законом Российской Федерации о поправке к Конституции Российской Федерации от 14 марта 2020 года № 1-ФКЗ \"О совершенствовании регулирования отдельных вопросов организации и функционирования публичной власти\"; (Дополнение подпунктом - Федеральный закон от 26.03.2020 № 68-ФЗ)\n\n29) реализация коммунальных услуг (за исключением услуг по обращению с твердыми коммунальными отходами), предоставляемых управляющими организациями, товариществами собственников жилья, жилищно-строительными, жилищными или иными специализированными потребительскими кооперативами, созданными в целях удовлетворения потребностей граждан в жилье и отвечающими за обслуживание внутридомовых инженерных систем, с использованием которых предоставляются коммунальные услуги, при условии приобретения коммунальных услуг указанными налогоплательщиками у организаций коммунального комплекса, поставщиков электрической энергии и газоснабжающих организаций, организаций, осуществляющих горячее водоснабжение, холодное водоснабжение и (или) водоотведение; (Дополнение подпунктом - Федеральный закон от 28.11.2009 № 287-ФЗ) (В редакции  федеральных законов от 07.12.2011 № 417-ФЗ, от 26.07.2019 № 211-ФЗ, от 08.08.2024 № 259-ФЗ)\n\n291) реализация услуг по обращению с твердыми коммунальными отходами, предоставляемых управляющими организациями, товариществами собственников жилья, жилищно-строительными, жилищными или иными специализированными потребительскими кооперативами, созданными в целях удовлетворения потребностей граждан в жилье и отвечающими за обслуживание внутридомовых инженерных систем, с использованием которых предоставляются коммунальные услуги, при условии приобретения услуг по обращению с твердыми коммунальными отходами указанными налогоплательщиками у региональных операторов по обращению с твердыми коммунальными отходами; (Дополнение подпунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n30) реализация работ (услуг) по содержанию и ремонту общего имущества в многоквартирном доме, выполняемых (оказываемых) управляющими организациями, товариществами собственников жилья, жилищно-строительными, жилищными или иными специализированными потребительскими кооперативами, созданными в целях удовлетворения потребностей граждан в жилье и отвечающими за обслуживание внутридомовых инженерных систем, с использованием которых предоставляются коммунальные услуги, при условии приобретения работ (услуг) по содержанию и ремонту общего имущества в многоквартирном доме указанными налогоплательщиками у организаций и индивидуальных предпринимателей, непосредственно выполняющих (оказывающих) данные работы (услуги), реализация работ (услуг) по выполнению функций технического заказчика работ по капитальному ремонту общего имущества в многоквартирных домах, выполняемых (оказываемых) специализированными некоммерческими организациями, которые осуществляют деятельность, направленную на обеспечение проведения капитального ремонта общего имущества в многоквартирных домах, и созданы в соответствии с Жилищным кодексом Российской Федерации, а также органами местного самоуправления и (или) муниципальными бюджетными учреждениями в случаях, предусмотренных Жилищным кодексом Российской Федерации; (Дополнение подпунктом - Федеральный закон от 28.11.2009 № 287-ФЗ) (В редакции Федерального закона от 25.12.2012 № 271-ФЗ)\n\n31) передача имущественных прав (в том числе предоставление права использования результатов интеллектуальной деятельности и (или) средств индивидуализации) общероссийским общественным объединением, осуществляющим свою деятельность в соответствии с законодательством Российской Федерации об общественных объединениях, Олимпийской хартией Международного олимпийского комитета и на основе признания Международным олимпийским комитетом, и общероссийским общественным объединением, осуществляющим свою деятельность в соответствии с законодательством Российской Федерации об общественных объединениях, Конституцией Международного паралимпийского комитета и на основе признания Международным паралимпийским комитетом, в рамках исполнения обязательств по соглашениям, заключенным с российскими и иностранными организаторами XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи в соответствии со статьей 3 Федерального закона от 1 декабря 2007 года № 310-ФЗ \"Об организации и о проведении XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, развитии города Сочи как горноклиматического курорта и внесении изменений в отдельные законодательные акты Российской Федерации\"; (Дополнение подпунктом - Федеральный закон от 27.12.2009 № 379-ФЗ)\n\n32) безвозмездное оказание услуг по производству и (или) распространению социальной рекламы в соответствии с законодательством Российской Федерации о рекламе.\n\nУказанные в настоящем подпункте операции не подлежат налогообложению при соблюдении одного из следующих требований к социальной рекламе:\n\nв социальной рекламе, распространяемой в радиопрограммах, продолжительность упоминания о спонсорах составляет не более трех секунд;\n\nв социальной рекламе, распространяемой в телепрограммах, при кино- и видеообслуживании, продолжительность упоминания о спонсорах составляет не более трех секунд и такому упоминанию отведено не более 7 процентов площади кадра;\n\nв социальной рекламе, распространяемой другими способами, на упоминание о спонсорах отведено не более 5 процентов рекламной площади (пространства).\n\nУстановленные настоящим подпунктом требования к упоминаниям о спонсорах не распространяются на упоминания в социальной рекламе об органах государственной власти, иных государственных органах и органах местного самоуправления, о муниципальных органах, которые не входят в структуру органов местного самоуправления, о социально ориентированных некоммерческих организациях, а также о физических лицах, оказавшихся в трудной жизненной ситуации или нуждающихся в лечении, в целях оказания им благотворительной помощи;\n\n(Дополнение подпунктом - Федеральный закон от 18.07.2011 № 235-ФЗ)\n\n33) услуги участников договора инвестиционного товарищества - управляющих товарищей по ведению общих дел товарищей; (Дополнение подпунктом - Федеральный закон от 28.11.2011 № 336-ФЗ)\n\n34) передача имущественных прав в виде вклада по договору инвестиционного товарищества, а также передача имущественных прав участнику договора инвестиционного товарищества в случае выдела его доли из имущества, находящегося в общей собственности участников указанного договора, или раздела такого имущества - в пределах суммы оплаченного вклада данного участника; (Дополнение подпунктом - Федеральный закон от 28.11.2011 № 336-ФЗ)\n\n35) реализация (передача для собственных нужд) племенного крупного рогатого скота, племенных свиней, племенных овец, племенных коз, племенных лошадей, племенной птицы (племенного яйца), племенных рыб; семени (спермы), полученного от племенных быков, племенных свиней, племенных баранов, племенных козлов, племенных жеребцов; эмбрионов, полученных от племенного крупного рогатого скота, племенных свиней, племенных овец, племенных коз, племенных лошадей; эмбрионов, молоди, полученных от племенных рыб, по перечню кодов видов продукции в соответствии с Общероссийским классификатором продукции по видам экономической деятельности, утверждаемому Правительством Российской Федерации. (В редакции федеральных законов от 30.11.2016 № 401-ФЗ, от 02.07.2021 № 308-ФЗ)\n\nПоложения настоящего подпункта применяются при наличии у налогоплательщика племенного свидетельства (паспорта), выданного в соответствии с Федеральным законом от 3 августа 1995 года № 123-ФЗ \"О племенном животноводстве\"; (В редакции  Федерального закона от 30.11.2024 № 430-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 23.06.2016 № 187-ФЗ)\n\n36) оказание услуг по выполнению функций агента Российской Федерации, предусмотренных Федеральным законом от 24 июля 2008 года № 161-ФЗ \"О содействии развитию жилищного строительства\", при реализации, сдаче в аренду государственного имущества, не закрепленного за государственными предприятиями и учреждениями, составляющего государственную казну Российской Федерации; (Дополнение подпунктом - Федеральный закон от 04.06.2018 № 143-ФЗ)\n\n37) услуги по осуществлению ремонта и технического обслуживания товаров (в том числе медицинских товаров), включая стоимость запасных частей для них и деталей к ним, оказываемые в период гарантийного срока их эксплуатации в целях исполнения обязательств по гарантийному ремонту таких товаров, при условии невзимания дополнительной платы за такие услуги; (Дополнение подпунктом - Федеральный закон от 27.11.2018 № 424-ФЗ)\n\n38) оказание услуг общественного питания через объекты общественного питания (рестораны, кафе, бары, предприятия быстрого обслуживания, буфеты, кафетерии, столовые, закусочные, отделы кулинарии при указанных объектах и иные аналогичные объекты общественного питания), а также услуг общественного питания вне объектов общественного питания по месту, выбранному заказчиком (выездное обслуживание).\n\nУслугами общественного питания в целях настоящего подпункта не признается реализация:\n\nпродукции общественного питания отделами кулинарии организаций и индивидуальных предпринимателей розничной торговли;\n\nпродукции общественного питания организациями и индивидуальными предпринимателями, осуществляющими заготовочную и иную аналогичную деятельность, организациям и индивидуальным предпринимателям, оказывающим услуги общественного питания, предусмотренные настоящим подпунктом, либо занимающимся розничной торговлей.\n\nЕсли иное не предусмотрено настоящим подпунктом, организации и индивидуальные предприниматели, оказывающие услуги общественного питания, имеют право на освобождение, предусмотренное настоящим подпунктом, при одновременном выполнении следующих условий:\n\nесли за календарный год, предшествующий году, в котором применяется освобождение, сумма доходов организации или индивидуального предпринимателя, определяемых в порядке, установленном главой 23, 25 или 262 настоящего Кодекса, не превысила в совокупности три миллиарда рублей; (В редакции  Федерального закона от 23.07.2025 № 227-ФЗ)\n\nесли за календарный год, предшествующий году, в котором применяется освобождение, удельный вес доходов от реализации услуг общественного питания в общей сумме доходов организации или индивидуального предпринимателя составил не менее 70 процентов. При этом доходы определяются в порядке, установленном главой 23, 25 или 262 настоящего Кодекса;\n\nесли за календарный год, предшествующий году, в котором применяется освобождение, среднемесячный размер выплат и иных вознаграждений, начисленных организацией или индивидуальным предпринимателем в пользу физических лиц, определяемый исходя из данных расчетов по страховым взносам, не ниже размера среднемесячной начисленной заработной платы за календарный год, предшествующий году, в котором применяется освобождение, в каждом субъекте Российской Федерации, в налоговый орган которого представлен расчет по страховым взносам за календарный год, предшествующий году, в котором применяется освобождение, по виду экономической деятельности, определяемому по классу 56 \"Деятельность по предоставлению продуктов питания и напитков\" раздела I \"Деятельность гостиниц и предприятий общественного питания\" в соответствии с Общероссийским классификатором видов экономической деятельности. Информация о размере среднемесячной начисленной заработной платы в субъекте Российской Федерации по указанному виду экономической деятельности размещается федеральным органом исполнительной власти, уполномоченным в области статистики, в единой межведомственной информационно-статистической системе, доступ к которой осуществляется через информационно-телекоммуникационную сеть \"Интернет\". При отсутствии на начало налогового периода указанной информации в единой межведомственной информационно-статистической системе за календарный год, предшествующий году, в котором применяется освобождение, до истечения указанного налогового периода используется аналогичная информация за первые девять месяцев указанного календарного года. В этом случае для целей применения освобождения в указанном налоговом периоде учитывается наибольшее из значений среднемесячного размера выплат и иных вознаграждений, начисленных организацией или индивидуальным предпринимателем в пользу физических лиц: за календарный год, предшествующий году, в котором применяется освобождение, либо за первые девять месяцев календарного года, предшествующего году, в котором применяется освобождение.\n\nВ целях применения абзаца восьмого настоящего подпункта среднемесячный размер выплат и иных вознаграждений, начисленных организацией или индивидуальным предпринимателем в пользу физических лиц, за календарный год, предшествующий году, в котором применяется освобождение (за первые девять месяцев календарного года, предшествующего году, в котором применяется освобождение), определяется путем деления средней суммы начисленных выплат и иных вознаграждений за указанный период на количество месяцев указанного периода, за которые начислялись выплаты и вознаграждения в пользу физических лиц по трудовым договорам.\n\nВеличина средней суммы начисленных выплат и иных вознаграждений определяется путем деления суммы выплат и иных вознаграждений по трудовым договорам, определяемой исходя из данных расчетов по страховым взносам за календарный год, предшествующий году, в котором применяется освобождение (за первые девять месяцев календарного года, предшествующего году, в котором применяется освобождение), на показатель среднесписочной численности работников.\n\nПри создании организации (государственной регистрации физического лица в качестве индивидуального предпринимателя) указанная организация (индивидуальный предприниматель) вправе применить предусмотренное настоящим подпунктом освобождение в налоговых периодах календарного года, в котором создана указанная организация (осуществлена государственная регистрация физического лица в качестве индивидуального предпринимателя), без ограничений, предусмотренных настоящим пунктом;\n\n(Дополнение подпунктом - Федеральный закон от 02.07.2021 № 305-ФЗ) (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\n39) реализация организацией, осуществляющей туроператорскую деятельность, туристского продукта в сфере внутреннего туризма и (или) въездного туризма; (Дополнение подпунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n40) передача международными холдинговыми компаниями субъекту Российской Федерации либо муниципальному образованию результатов работ и (или) имущества в соответствии с абзацами вторым - четвертым пункта 4 статьи 28410 настоящего Кодекса. (Дополнение подпунктом - Федеральный закон от 19.12.2023 № 595-ФЗ)\n\nТакой отказ или приостановление возможен только в отношении всех осуществляемых налогоплательщиком операций, предусмотренных одним или несколькими подпунктами пункта 3 настоящей статьи. Не допускается, чтобы подобные операции освобождались или не освобождались от налогообложения в зависимости от того, кто является покупателем (приобретателем) соответствующих товаров (работ, услуг). (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nНе допускается отказ или приостановление от освобождения от налогообложения операций на срок менее одного года. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nОперации по реализации услуг, указанных в подпункте 2 пункта 2 настоящей статьи, иностранными юридическими лицами и индивидуальными предпринимателями, являющимися участниками проекта в соответствии с Федеральным законом от 29 июня 2015 года № 160-ФЗ \"О международном медицинском кластере и внесении изменений в отдельные законодательные акты Российской Федерации\", не подлежат налогообложению (освобождаются от налогообложения) при наличии разрешительной документации, выданной в установленном порядке уполномоченными органами и организациями иностранного государства - члена Организации экономического сотрудничества и развития и подтверждающей право на оказание таких услуг. (Дополнение абзацем - Федеральный закон от 25.12.2018 № 493-ФЗ)","article_title":"Статья 149. Операции, не подлежащие налогообложению (освобождаемые от налогообложения)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"908d1384be614a39cc4a1a0ee305dd7c320d29ae8fe84fc4d3242a7f3cf6bc72"},{"code_id":"NK_RF_2","article_number":"150","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 27.11.2010 № 306-ФЗ)\n\nНе подлежит налогообложению (освобождается от налогообложения) ввоз на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией: (В редакции Таможенного код\n\nекса Российской Федерации от 28.05.2003 № 61-ФЗ; Федерального закона от 27.11.2010 № 306-ФЗ)\n\n1) товаров (за исключением подакцизных товаров), ввозимых в качестве безвозмездной помощи (содействия) Российской Федерации, в порядке, устанавливаемом Правительством Российской Федерации в соответствии с Федеральным законом \"О безвозмездной помощи (содействии) Российской Федерации и внесении изменений и дополнений в отдельные законодательные акты Российской Федерации о налогах и об установлении льгот по платежам в государственные внебюджетные фонды в связи с осуществлением безвозмездной помощи (содействия) Российской Федерации\"; (В редакции федеральных законов от 29.12.2000 № 166-ФЗ; от 07.07.2003 № 117-ФЗ)\n\n2) следующих товаров:\n\nтоваров, указанных в подпункте 1 пункта 2 статьи 149 настоящего Кодекса;\n\nсырья и комплектующих изделий, которые предназначены для производства товаров, указанных в абзаце втором настоящего подпункта, и аналоги которых не производятся в Российской Федерации.\n\nПоложения абзаца третьего настоящего подпункта применяются при условии представления в таможенные органы документа, подтверждающего целевое назначение таких сырья и комплектующих изделий и отсутствие их аналогов, которые производятся в Российской Федерации, выданного федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере промышленного и оборонно-промышленного комплексов, в установленном указанным федеральным органом исполнительной власти порядке.\n\nВ случае ввоза таких сырья и комплектующих изделий с территории государства - члена Евразийского экономического союза данный документ представляется в налоговый орган;\n\n(Подпункт в редакции Федерального закона от 30.06.2016 № 225-ФЗ)\n\n3) (Подпункт утратил силу - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n4) культурных ценностей, приобретенных государственными или муниципальными учреждениями, культурных ценностей, полученных в дар государственными и муниципальными учреждениями культуры, государственными и муниципальными архивами, а также культурных ценностей, передаваемых в качестве дара учреждениям, отнесенным в соответствии с законодательством Российской Федерации к особо ценным объектам культурного и национального наследия народов Российской Федерации. (В редакции Федерального закона от 03.12.2012 № 245-ФЗ)\n\nПоложения настоящего подпункта применяются при условии представления в таможенные органы подтверждения федерального органа исполнительной власти, осуществляющего функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере культуры, искусства, культурного наследия (в том числе археологического наследия), кинематографии, либо в случае, если приобретенные, полученные в дар культурные ценности являются документами Архивного фонда Российской Федерации или другими архивными документами, подтверждения федерального органа исполнительной власти, осуществляющего функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере архивного дела и делопроизводства, о соблюдении условий, установленных абзацем первым настоящего подпункта; (Дополнение абзацем - Федеральный закон от 03.12.2012 № 245-ФЗ) (В редакции Федерального закона от 18.06.2017 № 121-ФЗ)\n\n(Подпункт в редакции Федерального закона от 25.11.2009 № 281-ФЗ)\n\n41) культурных ценностей, не указанных в подпункте 4 настоящей статьи, при условии их отнесения к таковым в соответствии с законодательством Российской Федерации о вывозе и ввозе культурных ценностей.\n\nПоложения настоящего подпункта применяются при условии представления в таможенные органы экспертного заключения, оформленного в соответствии с законодательством Российской Федерации о вывозе и ввозе культурных ценностей, содержащего вывод об отнесении исследуемого движимого предмета к культурным ценностям;\n\n(Дополнение подпунктом - Федеральный закон от 28.12.2017 № 430-ФЗ)\n\n5) всех видов печатных изданий, получаемых государственными и муниципальными библиотеками и музеями по международному книгообмену, а также произведений кинематографии, ввозимых специализированными государственными организациями в целях осуществления международных некоммерческих обменов;\n\n6) товаров, произведенных в результате хозяйственной деятельности российских организаций на земельных участках, являющихся территорией иностранного государства с правом землепользования Российской Федерации на основании международного договора; (В редакции Федерального закона от 22.07.2005 № 119-ФЗ)\n\n7) технологического оборудования (в том числе комплектующих и запасных частей к нему), аналоги которого не производятся в Российской Федерации, по перечню, утверждаемому Правительством Российской Федерации; (В редакции Федерального закона от 26.11.2008 № 224-ФЗ)\n\n8) необработанных природных алмазов;\n\n9) товаров, предназначенных для официального пользования иностранных дипломатических и приравненных к ним представительств, а также для личного пользования дипломатического и административно-технического персонала этих представительств, включая членов их семей, проживающих вместе с ними;\n\n10) валюты Российской Федерации и иностранной валюты, банкнот, являющихся законными средствами платежа (за исключением предназначенных для коллекционирования), а также ценных бумаг - акций, облигаций, сертификатов, векселей; (В редакции Федерального закона от 29.12.2000 № 166-ФЗ)\n\n11) продукции морского промысла, выловленной и (или) переработанной рыбопромышленными предприятиями (организациями) Российской Федерации; (В редакции Федерального закона от 29.12.2000 № 166-ФЗ)\n\n12) судов, подлежащих регистрации в Российском международном реестре судов, а также судов, подлежащих регистрации в Российском открытом реестре судов лицами, получившими статус участника специального административного района в соответствии с Федеральным законом от 3 августа 2018 года № 291-ФЗ \"О специальных административных районах на территориях Калининградской области и Приморского края\"; (Дополнение подпунктом - Федеральный закон от 20.12.2005 № 168-ФЗ) (В редакции Федерального закона от 29.09.2019 № 324-ФЗ)\n\n13) товаров, за исключением подакцизных, по перечню, утверждаемому Правительством Российской Федерации, перемещаемых в рамках международного сотрудничества Российской Федерации в области исследования и использования космического пространства, а также соглашений об услугах по запуску космических аппаратов; (Дополнение подпунктом - Федеральный закон от 10.11.2006 № 191-ФЗ) (В редакции Федерального закона от 27.11.2010 № 306-ФЗ)\n\n14) (Дополнение подпунктом - Федеральный закон от 01.12.2007 № 310-ФЗ) (Утратил силу - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\n15) российских судов рыбопромыслового флота, в отношении которых за пределами таможенной территории Российской Федерации были выполнены работы по капитальному ремонту и (или) модернизации; (Дополнение подпунктом - Федеральный закон от 30.12.2008 № 314-ФЗ)\n\n16) незарегистрированных лекарственных средств, предназначенных для оказания медицинской помощи по жизненным показаниям конкретных пациентов, и гемопоэтических стволовых клеток и костного мозга для проведения неродственной трансплантации.\n\nПоложения настоящего подпункта применяются при условии представления в таможенные органы соответствующего разрешения, выданного федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере здравоохранения, обращения лекарственных средств для медицинского применения; (В редакции Федерального закона от 25.11.2013 № 317-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 18.07.2011 № 235-ФЗ)\n\n17) расходных материалов для научных исследований, аналоги которых не производятся в Российской Федерации, по перечню и в порядке, которые утверждаются Правительством Российской Федерации.\n\nК расходным материалам в целях настоящего подпункта относятся товары, срок полезного использования которых не превышает одного года и которые предназначены для осуществления научно-исследовательской и научно-технической деятельности, а также экспериментальных разработок;\n\n(Дополнение подпунктом - Федеральный закон от 04.06.2014 № 151-ФЗ)\n\n18) десантно-вертолетных кораблей-доков; (Дополнение подпунктом - Федеральный закон от 21.07.2014 № 239-ФЗ)\n\n19) племенного крупного рогатого скота, племенных свиней, племенных овец, племенных коз, племенных лошадей, племенной птицы (племенного яйца); семени (спермы), полученного от племенных быков, племенных свиней, племенных баранов, племенных козлов, племенных жеребцов; эмбрионов, полученных от племенного крупного рогатого скота, племенных свиней, племенных овец, племенных коз, племенных лошадей, по перечню кодов видов продукции в соответствии с единой Товарной номенклатурой внешнеэкономической деятельности Евразийского экономического союза, утверждаемому Правительством Российской Федерации.\n\nПри ввозе товаров, указанных в настоящем подпункте, из стран, не являющихся государствами - членами Евразийского экономического союза, положения настоящего подпункта применяются при условии представления в таможенный орган заключения об отнесении сельскохозяйственных животных и полученных от них семени и эмбрионов к племенной продукции (материалу), выданного в соответствии с Федеральным законом от 3 августа 1995 года № 123-ФЗ \"О племенном животноводстве\". (В редакции  Федерального закона от 30.11.2024 № 430-ФЗ)\n\nПри ввозе товаров, указанных в настоящем подпункте, из государств - членов Евразийского экономического союза положения настоящего подпункта применяются при условии представления в налоговый орган племенного свидетельства (паспорта) на ввозимую племенную продукцию (материал), выданного уполномоченным органом страны-экспортера; (Дополнение абзацем - Федеральный закон от 30.11.2024 № 430-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 23.06.2016 № 187-ФЗ)\n\n20) гражданских воздушных судов при условии представления в таможенный орган копии свидетельства о государственной регистрации гражданского воздушного судна в Государственном реестре гражданских воздушных судов Российской Федерации.\n\nВ случае непредставления документа, указанного в абзаце первом настоящего подпункта, предусмотренный настоящим подпунктом ввоз гражданских воздушных судов освобождается от налогообложения при представлении в таможенный орган обязательства налогоплательщика по форме, утвержденной федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области таможенного дела, представить в течение 90 календарных дней с даты регистрации таможенной декларации в таможенный орган документ, указанный в абзаце первом настоящего подпункта.\n\nВ случае, если по истечении срока, установленного абзацем вторым настоящего подпункта, налогоплательщик, представивший в таможенный орган обязательство налогоплательщика, указанное в абзаце втором настоящего подпункта, не представил в таможенный орган копию свидетельства о государственной регистрации гражданского воздушного судна в Государственном реестре гражданских воздушных судов Российской Федерации, сумма налога, исчисленная при таможенном декларировании гражданского воздушного судна, уплачивается этим налогоплательщиком не позднее дня, следующего за днем истечения срока, установленного абзацем вторым настоящего подпункта.\n\nПри исключении данных о гражданском воздушном судне из Государственного реестра гражданских воздушных судов Российской Федерации сумма налога, исчисленная при таможенном декларировании гражданского воздушного судна, освобождение от уплаты которой при ввозе гражданского воздушного судна предусмотрено настоящим подпунктом, подлежит уплате налогоплательщиком, представившим в таможенный орган копию свидетельства о государственной регистрации гражданского воздушного судна в Государственном реестре гражданских воздушных судов Российской Федерации, указанного в абзаце первом настоящего подпункта, в день исключения данных из Государственного реестра гражданских воздушных судов Российской Федерации. Положения настоящего абзаца не распространяются на исключение данных о гражданском воздушном судне из Государственного реестра гражданских воздушных судов Российской Федерации в следующих случаях:\n\nсписание гражданского воздушного судна или снятие его с эксплуатации в связи с невозможностью использования данного судна по назначению (в качестве транспортного средства);\n\nреализация гражданского воздушного судна или переход на иных законных основаниях права собственности на него иностранному государству, а также иностранному гражданину, лицу без гражданства или иностранной организации при условии вывоза гражданского воздушного судна за пределы территории Российской Федерации.\n\nВ целях контроля за соблюдением требований, установленных настоящим подпунктом, для применения освобождения от уплаты налога при ввозе гражданских воздушных судов на территорию Российской Федерации федеральный орган исполнительной власти, осуществляющий функции по оказанию государственных услуг и управлению государственным имуществом в сфере воздушного транспорта (гражданской авиации), а также государственной регистрации прав на воздушные суда и сделок с ними, направляет с использованием единой системы межведомственного электронного взаимодействия в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области таможенного дела, сведения о включении данных о гражданских воздушных судах в Государственный реестр гражданских воздушных судов Российской Федерации, а также сведения об исключении данных о гражданских воздушных судах и о причинах исключения этих данных из Государственного реестра гражданских воздушных судов Российской Федерации в порядке, утверждаемом федеральным органом исполнительной власти, осуществляющим функции по оказанию государственных услуг и управлению государственным имуществом в сфере воздушного транспорта (гражданской авиации), а также государственной регистрации прав на воздушные суда и сделок с ними, по согласованию с федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области таможенного дела;\n\n(Дополнение подпунктом - Федеральный закон от 29.09.2019 № 324-ФЗ)\n\n21) гражданских воздушных судов, зарегистрированных в государственном реестре гражданских воздушных судов иностранного государства, при условии представления в таможенный орган копии свидетельства (сертификата) о регистрации гражданского воздушного судна в государственном реестре гражданских воздушных судов иностранного государства, которым в соответствии с международным договором Российской Федерации переданы Российской Федерации полностью или частично функции и обязанности государства регистрации.\n\nПри исключении данных о гражданском воздушном судне из реестра гражданских воздушных судов иностранного государства, которым в соответствии с международным договором Российской Федерации переданы Российской Федерации полностью или частично функции и обязанности государства регистрации, сумма налога, исчисленная при таможенном декларировании гражданского воздушного судна, освобождение от уплаты которой при ввозе гражданского воздушного судна предусмотрено настоящим подпунктом, подлежит уплате налогоплательщиком, представившим в таможенный орган копию свидетельства (сертификата) о регистрации гражданского воздушного судна в государственном реестре гражданских воздушных судов иностранного государства, которым в соответствии с международным договором Российской Федерации переданы Российской Федерации полностью или частично функции и обязанности государства регистрации, указанного в абзаце первом настоящего подпункта, в день исключения данных из реестра гражданских воздушных судов иностранного государства, которым в соответствии с международным договором Российской Федерации переданы Российской Федерации полностью или частично функции и обязанности государства регистрации. Положения настоящего абзаца не распространяются на исключение данных о гражданском воздушном судне из реестра гражданских воздушных судов иностранного государства, которым в соответствии с международным договором Российской Федерации переданы Российской Федерации полностью или частично функции и обязанности государства регистрации, в следующих случаях:\n\nпредставление в таможенный орган свидетельства о государственной регистрации гражданского воздушного судна в Государственном реестре гражданских воздушных судов Российской Федерации;\n\nсписание гражданского воздушного судна или снятие его с эксплуатации в связи с невозможностью использования данного судна по назначению (в качестве транспортного средства).\n\nВ целях контроля за соблюдением требований, установленных настоящим подпунктом, для применения освобождения от уплаты налога при ввозе гражданских воздушных судов на территорию Российской Федерации федеральный орган исполнительной власти, осуществляющий функции по оказанию государственных услуг и управлению государственным имуществом в сфере воздушного транспорта (гражданской авиации), а также государственной регистрации прав на воздушные суда и сделок с ними, направляет с использованием единой системы межведомственного электронного взаимодействия в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области таможенного дела, сведения о включении данных о гражданских воздушных судах в федеральную государственную информационную систему \"Реестр эксплуатантов и воздушных судов\", а также сведения об изменении (исключении) данных о гражданских воздушных судах и о причинах изменения (исключения) этих данных в федеральной государственной информационной системе \"Реестр эксплуатантов и воздушных судов\" в порядке, утверждаемом федеральным органом исполнительной власти, осуществляющим функции по оказанию государственных услуг и управлению государственным имуществом в сфере воздушного транспорта (гражданской авиации), а также государственной регистрации прав на воздушные суда и сделок с ними, по согласованию с федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области таможенного дела;\n\n(Дополнение подпунктом - Федеральный закон от 29.09.2019 № 324-ФЗ)\n\n22) авиационных двигателей, запасных частей и комплектующих изделий, предназначенных для строительства, ремонта и (или) модернизации на территории Российской Федерации гражданских воздушных судов (за исключением сверхлегких пилотируемых воздушных судов с массой конструкции 115 килограммов и менее), а также печатных изданий, опытных образцов и (или) их составных частей, необходимых для разработки, создания и (или) испытания гражданских воздушных судов и (или) авиационных двигателей. (В редакции  Федерального закона от 14.11.2023 № 538-ФЗ)\n\nПоложения настоящего подпункта применяются при условии представления в таможенный орган документа, подтверждающего целевое назначение ввозимого товара, выданного федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере промышленного и оборонно-промышленного комплексов, по форме и в порядке, которые установлены указанным федеральным органом исполнительной власти;\n\n(Дополнение подпунктом - Федеральный закон от 29.09.2019 № 324-ФЗ)\n\n23) двигателей, запасных частей и комплектующих изделий, предназначенных для строительства, ремонта и (или) модернизации на территории Российской Федерации беспилотных гражданских воздушных судов с максимальной взлетной массой от 0,15 килограмма до 30 килограммов, а также печатных изданий, опытных образцов и (или) их составных частей, необходимых для разработки, создания и (или) испытания указанных в настоящем подпункте беспилотных гражданских воздушных судов и (или) двигателей.\n\nПоложения настоящего подпункта применяются при условии представления в таможенный о\n\nрган документа, подтверждающего целевое назначение ввозимого товара, выданного федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере промышленного и оборонно-промышленного комплексов, по форме и в порядке, которые установлены указанным федеральным органом исполнительной власти.\n\n(Дополнение подпунктом - Федеральный закон от 31.07.2025 № 297-ФЗ)","article_title":"Статья 150. Ввоз товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, не подлежащий налогообложению (освобождаемый от налогообложения)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7ad779f3b4080248304c978343a88338b7302671b32cf79c1dc81f6f4c5b3b64"},{"code_id":"NK_RF_2","article_number":"151","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 27.11.2010 № 306-ФЗ)\n\n1) при помещении товаров под таможенную процедуру выпуска для внутреннего потребления налог уплачивается в полном объеме, если иное не предусмотрено подпунктом 11 настоящего пункта; (В редакции федеральных законов от 27.11.2010 № 306-ФЗ; от 30.03.2016 № 72-ФЗ)\n\n11) при выпуске товаров в соответствии с таможенной процедурой выпуска для внутреннего потребления при завершении действия таможенной процедуры свободной таможенной зоны на территории Особой экономической зоны в Калининградской области суммы исчисленного налога налогоплательщиками не уплачиваются при условии, что эти налогоплательщики на дату выпуска товаров в соответствии с указанной таможенной процедурой не применяют специальные налоговые режимы либо применяют упрощенную систему налогообложения, исполняя обязанности налогоплательщика, применяющего налоговые ставки, предусмотренные пунктами 2 и 3 статьи 164 настоящего Кодекса, не используют право на освобождение, предусмотренное статьей 145 настоящего Кодекса, и за налоговый период, предшествующий дате выпуска товаров в соответствии с указанной таможенной процедурой, не осуществляли операции по реализации товаров, не подлежащие налогообложению в соответствии со статьей 149 настоящего Кодекса, за исключением операций по передаче товаров, предусмотренных подпунктом 12 пункта 3 статьи 149 настоящего Кодекса, если иной порядок уплаты налога не предусмотрен абзацем третьим настоящего подпункта. (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\nПорядок налогообложения, предусмотренный абзацем первым настоящего подпункта, вправе применять налогоплательщики, которые на дату выпуска товаров в соответствии с таможенной процедурой выпуска для внутреннего потребления при завершении действия таможенной процедуры свободной таможенной зоны на территории Особой экономической зоны в Калининградской области являются резидентами, включенными в единый реестр резидентов Особой экономической зоны в Калининградской области, либо лицами, государственная регистрация которых осуществлена в Калининградской области и которые по состоянию на 1 апреля 2006 года осуществляли деятельность на основании Федерального закона от 22 января 1996 года № 13-ФЗ \"Об Особой экономической зоне в Калининградской области\", состоящие на учете в налоговых органах Калининградской области по месту нахождения организации (месту жительства физического лица - индивидуального предпринимателя).\n\nСуммы налога, исчисленные при таможенном декларировании, которые не были уплачены в соответствии с положениями абзаца первого настоящего подпункта, подлежат уплате в бюджет соответствующими налогоплательщиками в порядке, предусмотренном абзацем первым пункта 1 статьи 174 настоящего Кодекса, по итогам налогового периода, в котором истекают 180 календарных дней с даты выпуска товаров в соответствии с таможенной процедурой выпуска для внутреннего потребления при завершении действия таможенной процедуры свободной таможенной зоны на территории Особой экономической зоны в Калининградской области, если до истечения указанного срока эти товары не были использованы указанными налогоплательщиками для осуществления операций, признаваемых объектами налогообложения в соответствии с настоящей главой, без применения освобождения от налога, установленного настоящей главой. Документы, в частности копии договоров на поставку товаров, подтверждающие использование этих товаров при осуществлении указанных операций, представляются одновременно с налоговой декларацией, в которой отражены соответствующие операции.\n\nПодтверждение выполнения условий, указанных в абзаце первом настоящего подпункта, осуществляется путем представления в таможенный орган налоговыми органами необходимых для такого подтверждения сведений о налогоплательщике. Сведения о сумме исчисленного налога, не уплаченного налогоплательщиком на основании абзаца первого настоящего подпункта, и другие сведения, необходимые для контроля за правильностью исчисления и уплаты налога, представляются таможенным органом в налоговые органы. Состав и порядок представления сведений, указанных в настоящем абзаце, утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, и федеральным органом исполнительной власти, уполномоченным в области таможенного дела;\n\n(Дополнение подпунктом - Федеральный закон от 30.03.2016 № 72-ФЗ) (В редакции Федерального закона от 30.06.2016 № 225-ФЗ)\n\n2) при помещении товаров под таможенную процедуру реимпорта налогоплательщиком уплачиваются суммы налога, от уплаты которых он был освобожден, либо суммы, которые были ему возвращены в связи с экспортом товаров в соответствии с настоящим Кодексом, в порядке, предусмотренном таможенным законодательством Таможенного союза и законодательством Российской Федерации о таможенном деле; (В редакции Федерального закона от 27.11.2010 № 306-ФЗ)\n\n3) при помещении товаров под таможенные процедуры транзита, таможенного склада, реэкспорта, беспошлинной торговли, свободной таможенной зоны, свободного склада, уничтожения, отказа в пользу государства и специальную таможенную процедуру, а также при таможенном декларировании припасов налог не уплачивается; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ; Таможенного кодекса от 28.05.2003 № 61-ФЗ; федеральных законов от 27.11.2010 № 306-ФЗ; от 19.07.2011 № 245-ФЗ)\n\n4) при помещении товаров под таможенную процедуру переработки на таможенной территории налог не уплачивается при условии вывоза продуктов переработки с таможенной территории Таможенного союза в определенный срок; (В редакции Таможенного кодекса Российской Федерации от 28.05.2003 № 61-ФЗ; Федерального закона от 27.11.2010 № 306-ФЗ)\n\n5) при помещении товаров под таможенную процедуру временного ввоза применяется полное или частичное освобождение от уплаты налога в порядке, предусмотренном таможенным законодательством Таможенного союза и законодательством Российской Федерации о таможенном деле; (В редакции Федерального закона от 27.11.2010 № 306-ФЗ)\n\n6) при ввозе продуктов переработки товаров, помещенных под таможенную процедуру переработки вне таможенной территории, применяется полное или частичное освобождение от уплаты налога в порядке, предусмотренном таможенным законодательством Таможенного союза и законодательством Российской Федерации о таможенном деле; (В редакции Федерального закона от 27.11.2010 № 306-ФЗ)\n\n7) при помещении товаров под таможенную процедуру переработки для внутреннего потребления налог уплачивается в полном объеме. (В редакции Таможенного кодекса Российской Федерации от 28.05.2003 № 61-ФЗ; Федерального закона от 27.11.2010 № 306-ФЗ)\n\n1) при вывозе товаров с территории Российской Федерации в таможенной процедуре экспорта налог не уплачивается. (В редакции Федерального закона от 27.11.2010 № 306-ФЗ)\n\nУказанный в настоящем подпункте порядок налогообложения применяется также при помещении товаров под таможенную процедуру таможенного склада в целях последующего вывоза этих товаров в соответствии с таможенной процедурой экспорта, а также при помещении товаров под таможенную процедуру свободной таможенной зоны; (В редакции федеральных законов от 22.07.2005 № 117-ФЗ; от 27.11.2010 № 306-ФЗ)\n\n2) при вывозе товаров за пределы территории Российской Федерации и иных территорий, находящихся под ее юрисдикцией, в таможенной процедуре реэкспорта налог не уплачивается, а уплаченные при ввозе на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, суммы налога возвращаются налогоплательщику в порядке, предусмотренном таможенным законодательством Таможенного союза и законодательством Российской Федерации о таможенном деле; (В редакции Федерального закона от 07.11.2011 № 305-ФЗ)\n\n3) при вывозе с территории Российской Федерации припасов, а также товаров в целях завершения специальной таможенной процедуры налог не уплачивается; (Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ) (В редакции Федерального закона от 19.07.2011 № 245-ФЗ)\n\n4) при вывозе товаров с территории Российской Федерации и иных территорий, находящихся под ее юрисдикцией, в соответствии с иными по сравнению с указанными в подпунктах 1 - 3 настоящего пункта таможенными процедурами освобождение от уплаты налога и (или) возврат уплаченных сумм налога не производится, если иное не предусмотрено таможенным законодательством Таможенного союза и законодательством Российской Федерации о таможенном деле. (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 27.11.2010 № 306-ФЗ)\n\nПоложения абзаца первого настоящего пункта не применяются в отношении организаций (индивидуальных предпринимателей) - поверенных, комиссионеров, агентов, которые признаются налоговыми агентами в соответствии с пунктом 1 статьи 1743 настоящего Кодекса, а также поверенных, комиссионеров, агентов, с которыми заключены договоры, предусматривающие реализацию товаров доверителя, комитента, принципала организациям или индивидуальным предпринимателям. (Дополнение абзацем - Федеральный закон от 29.05.2024 № 100-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)","article_title":"Статья 151. Особенности налогообложения при ввозе товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, и вывозе товаров с территории Российской Федерации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3b0b196cf45fb4c9f58144f9630889e23ec48b478e28a49198855a9ba1b7228c"},{"code_id":"NK_RF_2","article_number":"152","version_date":"2000-07-31","article_text":"(Статья утратила силу - Федеральный закон от 27.11.2010 № 306-ФЗ)","article_title":"Статья 152. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"10c022c07b89cdf203a713b30ea73d70468ed3a9241dcb301046cc770ea41755"},{"code_id":"NK_RF_2","article_number":"153","version_date":"2000-07-31","article_text":"1. Налоговая база при реализации товаров (работ, услуг) определяется налогоплательщиком в соответствии с настоящей главой в зависимости от особенностей реализации произведенных им или приобретенных на стороне товаров (работ, услуг).\n\nПри передаче товаров (выполнении работ, оказании услуг) для собственных нужд, признаваемых объектом налогообложения в соответствии со статьей 146 настоящего Кодекса, налоговая база определяется налогоплательщиком в соответствии с настоящей главой.\n\nПри ввозе товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, налоговая база определяется налогоплательщиком в соответствии с настоящей главой и таможенным законодательством Таможенного союза и законодательством Российской Федерации о таможенном деле. (В редакции Федерального закона от 27.11.2010 № 306-ФЗ)\n\nПри применении налогоплательщиками при реализации (передаче, выполнении, оказании для собственных нужд) товаров (работ, услуг) различных налоговых ставок налоговая база определяется отдельно по каждому виду товаров (работ, услуг), облагаемых по разным ставкам. При применении одинаковых ставок налога налоговая база определяется суммарно по всем видам операций, облагаемых по этой ставке. (В редакции Федерального закона от 29.12.2000 № 166-ФЗ)\n\nПри передаче имущественных прав налоговая база определяется с учетом особенностей, установленных настоящей главой. (Дополнение абзацем - Федеральный закон от 22.07.2005 № 119-ФЗ)\n\nУказанные в настоящем пункте доходы учитываются в случае возможности их оценки и в той мере, в какой их можно оценить.","article_title":"Статья 153. Налоговая база","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"865c88744afb8a0bdcdde0a3e050800178bb62b06661f591245a80b866fbc505"},{"code_id":"NK_RF_2","article_number":"154","version_date":"2000-07-31","article_text":"1. Налоговая база при реализации налогоплательщиком товаров (работ, услуг), если иное не предусмотрено настоящей статьей, определяется как стоимость этих товаров (работ, услуг), исчисленная исходя из цен, определяемых в соответствии со статьей 1053 настоящего Кодекса, с учетом акцизов (для подакцизных товаров) и без включения суммы налога.\n\nПри получении налогоплательщиком оплаты, частичной оплаты в счет предстоящих поставок товаров (выполнения работ, оказания услуг) налоговая база определяется исходя из суммы полученной оплаты с учетом суммы налога.\n\nПри получении налогоплательщиком оплаты, частичной оплаты в связи с выпуском таким налогоплательщиком цифрового права, включающего одновременно цифровой финансовый актив и утилитарное цифровое право, данные суммы в целях настоящего Кодекса приравниваются к получению налогоплательщиком оплаты, частичной оплаты в счет предстоящих поставок товаров (выполнения работ, оказания услуг), предстоящей передачи имущественных прав, право требования передачи (выполнения, оказания) которых удостоверено этим цифровым правом.\n\nВ налоговую базу не включаются оплата, частичная оплата, полученные налогоплательщиком в счет предстоящей передачи цифровых финансовых активов, а также оплата, частичная оплата, полученные налогоплательщиком в счет предстоящих поставок товаров (выполнения работ, оказания услуг):\n\nдлительность производственного цикла изготовления которых составляет свыше шести месяцев, при определении налогоплательщиком налоговой базы по мере отгрузки (передачи) таких товаров (выполнения работ, оказания услуг) в соответствии с положениями пункта 13 статьи 167 настоящего Кодекса;\n\nкоторые облагаются по налоговой ставке 0 процентов в соответствии с пунктом 1 статьи 164 настоящего Кодекса;\n\nкоторые не подлежат налогообложению (освобождаются от налогообложения).\n\nНалоговая база при отгрузке (передаче) товаров (выполнении работ, оказании услуг) в счет ранее полученной оплаты, частичной оплаты, включенных ранее в налоговую базу, определяется налогоплательщиком в порядке, установленном абзацем первым настоящего пункта, если иное не предусмотрено пунктом 61 настоящей статьи.\n\nПри получении налогоплательщиком оплаты, частичной оплаты в счет предстоящей передачи имущественных прав, в том числе цифрового права, включающего одновременно цифровой финансовый актив и утилитарное цифровое право, в случаях, предусмотренных абзацем вторым пункта 1 и пунктами 2 - 4 и 6 статьи 155 настоящего Кодекса, налоговая база определяется как разница между суммой оплаты, частичной оплаты, полученных налогоплательщиком в счет предстоящей передачи имущественных прав, в том числе цифрового права, включающего одновременно цифровой финансовый актив и утилитарное цифровое право, и суммой расходов на приобретение указанного права (размера денежного требования, в том числе будущего требования), определяемой исходя из доли оплаты, частичной оплаты в стоимости, по которой передаются имущественные права, в том числе указанное цифровое право.\n\n(Пункт в редакции  Федерального закона от 14.07.2022 № 324-ФЗ)\n\nПри реализации товаров (работ, услуг) с учетом субсидий, предоставляемых бюджетами бюджетной системы Российской Федерации в связи с применением налогоплательщиком государственных регулируемых цен, или с учетом льгот (в том числе скидок на цену товаров (работ, услуг) без учета налога), предоставляемых отдельным потребителям в соответствии с законодательством, налоговая база определяется как стоимость реализованных товаров (работ, услуг), исчисленная исходя из фактических цен\n\nих реализации. (Дополнение абзацем - Федеральный закон от 29.12.2000 № 166-ФЗ) (В редакции федеральных законов от 22.07.2005 № 119-ФЗ; от 29.11.2007 № 284-ФЗ; от 03.08.2018 № 303-ФЗ)\n\nСуммы субсидий, предоставляемых бюджетами бюджетной системы Российской Федерации в связи с применением налогоплательщиком государственных регулируемых цен, или льгот (в том числе скидок на цену товаров (работ, услуг) без учета налога), предоставляемых отдельным потребителям в соответствии с законодательством, при определении налоговой базы не учитываются. (Дополнение абзацем - Федеральный закон от 22.07.2005 № 119-ФЗ) (В редакции федеральных законов от 29.11.2007 № 284-ФЗ; от 03.08.2018 № 303-ФЗ)\n\n1) на дату приобретения налогоплательщиком автомобиля и (или) мотоцикла их продавец применяет общий режим налогообложения;\n\n2) последним собственником автомобиля или мотоцикла, на которого было зарегистрировано в соответствии с законодательством Российской Федерации реализуемое налогоплательщиком транспортное средство, являлось физическое лицо;\n\n3) при приобретении автомобиля и (или) мотоцикла налогоплательщиком получен от продавца счет-фактура с суммой налога, определенной в соответствии с настоящим пунктом или пунктом 51 настоящей статьи.\n\nПоложения настоящего пункта не применяются в отношении указанных в пункте 51 настоящей статьи операций налогоплательщика по реализации автомобилей и мотоциклов.\n\n(Дополнение пунктом - Федеральный закон от 19.12.2023 № 612-ФЗ)\n\nПри реализации базисного актива производных финансовых инструментов, обращающихся на организованном рынке и предполагающих поставку базисного актива (за исключением реализации базисного актива опционных договоров (контрактов), налоговая база определяется как стоимость, по которой должна быть осуществлена реализация базисного актива и которая определена в соответствии с условиями утвержденной биржей спецификации производного финансового инструмента. Определение налоговой базы при реализации такого базисного актива осуществляется на дату, соответствующую моменту определения налоговой базы, установленному статьей 167 настоящего Кодекса, с учетом акцизов (для подакцизных товаров) и без включения в них налога. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nПри реализации базисного актива опционных договоров (контрактов), обращающихся на организованном рынке и предполагающих поставку базисного актива, налоговая база определяется как стоимость, по которой должна быть осуществлена реализация базисного актива и которая определена в соответствии с условиями утвержденной биржей спецификации производного финансового инструмента, но не ниже стоимости, исчисленной исходя из цен, определяемых в порядке, предусмотренном статьей 1053 настоящего Кодекса, действующих на дату, соответствующую моменту определения налоговой базы, установленному статьей 167 настоящего Кодекса, с учетом акцизов (для подакцизных товаров) и без включения в них налога. (В редакции федеральных законов от 18.07.2011 № 227-ФЗ; от 03.07.2016 № 242-ФЗ)\n\nВ целях настоящей главы под спецификацией производного финансового инструмента понимается документ биржи, определяющий условия производного финансового инструмента. (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n(Пункт в редакции Федерального закона от 25.11.2009 № 281-ФЗ)\n\nПри отгрузке (передаче) товаров, операции по реализации которых подлежат налогообложению по налоговой ставке, предусмотренной пунктом 3 статьи 164 настоящего Кодекса, в счет оплаты, частичной оплаты, полученных налогоплательщиком в связи с выпуском цифрового права, включающего одновременно цифровой финансовый актив и утилитарное цифровое право, если при получении данных оплаты, частичной оплаты налогоплательщиком была применена налоговая ставка, предусмотренная пунктом 1 статьи 164 настоящего Кодекса, налоговая база определяется как стоимость указанного цифрового права, исчисленная исходя из цены цифрового права, установленной решением о выпуске указанного цифрового права, но не ниже стоимости этих товаров, исчисленной исходя из цен, определяемых в порядке, предусмотренном статьей 1053 настоящего Кодекса, и действующих по состоянию на дату выпуска указанного цифрового права. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 14.07.2022 № 324-ФЗ)\n\nИзменение в сторону увеличения стоимости (с учетом налога) отгруженных товаров, указанных в абзаце первом пункта 8 статьи 161 настоящего Кодекса, в том числе в случае увеличения цены и (или) увеличения количества (объема) отгруженных товаров, учитывается налоговым агентом, указанным в пункте 8 статьи 161 настоящего Кодекса, при определении налоговой базы за налоговый период, в котором были составлены документы, являющиеся основанием для составления корректировочных счетов-фактур в соответствии с пунктом 10 статьи 172 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 19.07.2011 № 245-ФЗ) (В редакции Федерального закона от 05.04.2013 № 39-ФЗ)","article_title":"Статья 154. Порядок определения налоговой базы при реализации товаров (работ, услуг)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e1ff50925386a3dc4004c4412195022dfdcf9e7f2289c41e00afa018426b665c"},{"code_id":"NK_RF_2","article_number":"155","version_date":"2000-07-31","article_text":"Налоговая база при уступке первоначальным кредитором денежного требования, вытекающего из договора реализации товаров (работ, услуг), или при переходе указанного требования к другому лицу на основании закона определяется как сумма превышения суммы дохода, полученного первоначальным кредитором при уступке права требования, над размером денежного требования, права по которому уступлены. (Дополнение абзацем - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\n(Статья в редакции Федерального закона от 22.07.2005 № 119-ФЗ)","article_title":"Статья 155. Особенности определения налоговой базы при передаче имущественных прав","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"114882744593460d5ca101a025bb7fe420d2a8a77faf092faf532dfc4367e37f"},{"code_id":"NK_RF_2","article_number":"156","version_date":"2000-07-31","article_text":"1. Налогоплательщики при осуществлении предпринимательской деятельности в интересах другого лица на основе договоров поручения, договоров комиссии либо агентских договоров определяют налоговую базу как сумму дохода, полученную ими в виде вознаграждений (любых иных доходов) при исполнении любого из указанных договоров.\n\nВ аналогичном порядке определяется налоговая база при реализации залогодержателем в установленном законодательством Российской Федерации порядке предмета невостребованного залога, принадлежащего залогодателю. (Дополнение абзацем - Федеральный закон от 22.07.2005 № 119-ФЗ)","article_title":"Статья 156. Особенности определения налоговой базы налогоплательщиками, получающими доход на основе договоров поручения, договоров комиссии или агентских договоров","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e84d8286781209efeb9763e9cdba9acef827f927fa9790da3d4a5fc88b3b4754"},{"code_id":"NK_RF_2","article_number":"158","version_date":"2000-07-31","article_text":"В случае, если цена, по которой предприятие продано выше балансовой стоимости реализованного имущества, для целей налогообложения применяется поправочный коэффициент, рассчитанный как отношение цены реализации предприятия, уменьшенной на балансовую стоимость дебиторской задолженности (и на стоимость ценных бумаг, если не принято решение об их переоценке), к балансовой стоимости реализованного имущества, уменьшенной на балансовую стоимость дебиторской задолженности (и на стоимость ценных бумаг, если не принято решение об их переоценке). В этом случае поправочный коэффициент к сумме дебиторской задолженности\n\n(и стоимости ценных бумаг) не применяется. (В редакции Федерального закона от 29.12.2000 № 166-ФЗ)\n\nВ сводном счете-фактуре цена каждого вида имущества принимается равной произведению его балансовой стоимости на поправочный коэффициент.\n\nПо каждому виду имущества, реализация которого облагается налогом, в графах \"Ставка НДС\" и \"Сумма НДС\" указываются соответственно расчетная налоговая ставка в размере 16,67 процента и сумма налога, определенная как соответствующая расчетной налоговой ставке в размере 16,67 процента процентная доля налоговой базы. (В редакции федеральных законов от 07.07.2003 № 117-ФЗ; от 03.08.2018 № 303-ФЗ)","article_title":"Статья 158. Особенности определения налоговой базы при реализации предприятия в целом как имущественного комплекса","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"451ac995dc117846c9c1cff90bf4a369ee97557e0c4911c6ae5474e7973295e8"},{"code_id":"NK_RF_2","article_number":"160","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 27.11.2010 № 306-ФЗ)\n\n1) таможенной стоимости этих товаров; (В редакции федеральных законов от 29.12.2000 № 166-ФЗ; от 29.05.2002 № 57-ФЗ)\n\n2) подлежащей уплате таможенной пошлины;\n\n3) подлежащих уплате акцизов (по подакцизным товарам). (В редакции федеральных законов от 29.12.2000 № 166-ФЗ; от 07.07.2003 № 117-ФЗ)\n\n(Пункт 2 исключен - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\nЕсли в составе одной партии ввозимых на таможенную территорию Российской Федерации товаров присутствуют как подакцизные товары, так и неподакцизные товары, налоговая база определяется отдельно в отношении каждой группы указанных товаров. Налоговая база определяется в аналогичном порядке в случае, если в составе партии ввозимых на таможенную территорию Российской Федерации товаров присутствуют продукты переработки товаров, ранее вывезенных с территории Российской Федерации в соответствии с таможенной процедурой переработки вне таможенной территории. (В редакции федеральных законов от 29.12.2000 № 166-ФЗ; от 29.05.2002 № 57-ФЗ; от 07.07.2003 № 117-ФЗ; от 27.11.2010 № 306-ФЗ)","article_title":"Статья 160. Порядок определения налоговой базы при ввозе товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"78e8681a08d8d599b256e0ee40e3fbf88ec3b80450750924336cc73ed1bb9eae"},{"code_id":"NK_RF_2","article_number":"161","version_date":"2000-07-31","article_text":"1. При реализации товаров (работ, услуг), местом реализации которых является территория Российской Федерации, налоговая база определяется налоговыми агентами в случае реализации этих товаров (работ, услуг) налогоплательщиками - иностранными лицами:\n\nне состоящими на учете в налоговых органах либо состоящими на учете в налоговых органах только в связи с нахождением на территории Российской Федерации принадлежащих им недвижимого имущества и (или) транспортных средств либо в связи с открытием счета в банке;\n\nсостоящими на учете в налоговых органах по месту нахождения их обособленных подразделений на территории Российской Федерации (за исключением осуществления реализации указанных в абзаце первом настоящего пункта товаров (работ, услуг) через обособленное подразделение иностранной организации, расположенное на территории Российской Федерации).\n\nНалоговая база определяется налоговыми агентами отдельно при совершении каждой операции по реализации товаров (работ, услуг) на территории Российской Федерации с учетом настоящей главы как сумма дохода от реализации этих товаров (работ, услуг) с учетом налога.\n\n(Пункт в редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\nПри предоставлении на территории Российской Федерации органами государственной власти и управления, органами местного самоуправления, органами публичной власти федеральной территории \"Сириус\" права ограниченного пользования земельным участком (сервитута) в отношении земельных участков, находящихся в федеральной собственности, собственности субъектов Российской Федерации и муниципальной собственности, земельных участков, находящихся в собственности федеральной территории \"Сириус\", налоговая база определяется как сумма оплаты, перечисленной за установленный сервитут с учетом налога. При этом налоговая база определяется налоговым агентом отдельно по каждому земельному участку, в отношении которого установлен сервитут. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nВ случае, указанном в абзаце втором настоящего пункта, налоговыми агентами признаются организации и индивидуальные предприниматели, в интересах которых установлен сервитут. Указанные налоговые агенты обязаны исчислить, удержать и перечислить в бюджет соответствующую сумму налога вне зависимости от того, исполняют ли они обязанности налогоплательщика, связанные с исчислением и уплатой налога, и иные обязанности, установленные настоящей главой. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nПри реализации (передаче) на территории Российской Федерации государственного имущества, не закрепленного за государственными предприятиями и учреждениями, составляющего государственную казну Российской Федерации, казну республики в составе Российской Федерации, казну края, области, города федерального значения, автономной области, автономного округа, а также муниципального имущества, не закрепленного за муниципальными предприятиями и учреждениями, составляющего муниципальную казну соответствующего городского, сельского поселения или другого муниципального образования, государственного и муниципального имущества, не закрепленного за государственными и муниципальными предприятиями и учреждениями, составляющего казну федеральной территории \"Сириус\", налоговая база определяется как сумма дохода от реализации (передачи) этого имущества с учетом налога. При этом налоговая база определяется отдельно при совершении каждой операции по реализации (передаче) указанного имущества. В этом случае налоговыми агентами признаются покупатели (получатели) указанного имущества, за исключением физических лиц, не являющихся индивидуальными предпринимателями. Указанные лица обязаны исчислить расчетным методом, удержать из выплачиваемых доходов и уплатить в бюджет соответствующую сумму налога. (Дополнение абзацем - Федеральный закон от 26.11.2008 № 224-ФЗ) (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\nВ этом случае налоговая база определяется налоговым агентом как сумма оплаты, перечисленной налоговым агентом иностранному лицу в связи с выпуском цифровых прав, включающих одновременно цифровые финансовые активы и утилитарные цифровые права, с учетом налога.\n\nУказанные налоговые агенты обязаны исчислить, удержать и перечислить в бюджет соответствующую сумму налога вне зависимости от того, исполняют ли они обязанности налогоплательщика, связанные с исчислением и уплатой налога, и иные обязанности, установленные настоящей главой.\n\n(Дополнение пунктом - Федеральный закон от 14.07.2022 № 324-ФЗ)\n\nДля целей настоящего пункта налоговыми агентами признаются организации (за исключением банков), приобретающие у физических лиц или банков цифровые права, указанные в абзаце первом настоящего пункта.\n\nНалоговые агенты обязаны исчислить сумму налога по налоговой ставке, предусмотренной пунктом 3 статьи 164 настоящего Кодекса, и уплатить ее в бюджет вне зависимости от того, исполняют ли они обязанности налогоплательщика, связанные с исчислением и уплатой налога, и иные обязанности, установленные настоящей главой.\n\nИсполнение налоговым агентом обязанности по исчислению налога согласно настоящему пункту не освобождает налогоплательщика, выпустившего указанные в абзаце первом настоящего пункта цифровые права, от обязанности исчислить налог при отгрузке (передаче) товаров организациям в счет выкупа цифровых прав, включающих одновременно цифровые финансовые активы и утилитарные цифровые права, если указанные цифровые права удостоверяют право на получение товаров, предусмотренных подпунктом 62 пункта 1 статьи 164 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nНалоговым агентом является лицо, в собственности которого находится судно (гражданское воздушное судно) по истечении 90 календарных дней со дня передачи судна (гражданского воздушного судна) налогоплательщиком покупателю (заказчику). (В редакции Федерального закона от 29.09.2019 № 324-ФЗ)\n\nНалоговый агент обязан исчислить по налоговой ставке, предусмотренной пунктом 3 статьи 164 настоящего Кодекса, соответствующую сумму налога и перечислить ее в бюджет.\n\nВ целях осуществления контроля за правильностью исчисления и уплаты налога федеральный орган исполнительной власти, осуществляющий функции по оказанию государственных услуг и управлению государственным имуществом в сфере воздушного транспорта (гражданской авиации), а также государственной регистрации прав на воздушные суда и сделок с ними, ежемесячно не позднее 10-го числа месяца, следующего за отчетным месяцем, направляет в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, сведения о включении данных о гражданских воздушных судах в Государственный реестр гражданских воздушных судов Российской Федерации, а также сведения об исключении данных о гражданских воздушных судах из Государственного реестра гражданских воздушных судов Российской Федерации и о причинах исключения этих данных. Состав и порядок направления таких сведений утверждаются федеральным органом исполнительной власти, осуществляющим функции по оказанию государственных услуг и управлению государственным имуществом в сфере воздушного транспорта (гражданской авиации), а также государственной регистрации прав на воздушные суда и сделок с ними, по согласованию с федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 324-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 20.12.2005 № 168-ФЗ) (В редакции Федерального закона от 07.11.2011 № 305-ФЗ)\n\nРоссийской Федерации не осуществлена, налоговая база по услугам по передаче гражданских воздушных судов определяется налоговым агентом как стоимость этих услуг по договору аренды (лизинга).\n\nДля целей применения настоящего пункта налоговым агентом является арендатор (лизингополучатель), получивший от арендодателя (лизингодателя) гражданское воздушное судно по договору аренды (лизинга), по истечении 90 календарных дней со дня передачи гражданского воздушного судна.\n\nНалоговый агент обязан исчислить по налоговой ставке, предусмотренной пунктом 3 статьи 164 настоящего Кодекса, соответствующую сумму налога и перечислить ее в бюджет.\n\nПоложения настоящего пункта не распространяются на правоотношения, предусмотренные подпунктом 20 статьи 150 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 324-ФЗ)\n\nДля целей применения настоящего пункта налоговым агентом является лицо, в собственности которого находится гражданское воздушное судно на дату исключения из Государственного реестра гражданских воздушных судов Российской Федерации.\n\nНалоговый агент обязан исчислить по налоговой ставке, предусмотренной пунктом 3 статьи 164 настоящего Кодекса, соответствующую сумму налога и перечислить ее в бюджет.\n\nПоложения настоящего пункта не распространяются на следующие случаи исключения данных о гражданском воздушном судне из Государственного реестра гражданских воздушных судов Российской Федерации:\n\nсписание гражданского воздушного судна или снятие его с эксплуатации в связи с невозможностью использования данного судна по назначению (в качестве транспортного средства);\n\nреализация гражданского воздушного судна или переход на иных законных основаниях права собственности на него иностранному государству, а также иностранному гражданину, лицу без гражданства или иностранной организации при условии вывоза гражданского воздушного судна за пределы территории Российской Федерации.\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 324-ФЗ)\n\nВ целях настоящего Кодекса:\n\nмедными полуфабрикатами признаются любые товары, содержащие медь и используемые для производства кабельно-проводниковой продукции (в том числе после дополнительной обработки, переработки или иной трансформации), за исключением лома и отходов цветных металлов;\n\nсырыми шкурами животных признаются необработанные (невыделанные) шкуры, снятые с туш животных, парные или законсервированные в целях предотвращения их порчи и разложения (мокросоленые или сушеные), но не подвергнутые никакой дальнейшей обработке;\n\nалюминием вторичным и его сплавами признаются алюминий вторичный и его сплавы, классифицируемые в соответствии с Общероссийским классификатором продукции по видам экономической деятельности;\n\nмакулатурой признаются бумажные и картонные отходы производства и потребления, отбракованные и вышедшие из употребления бумага, картон, типографские изделия, деловые бумаги, в том числе документы с истекшим сроком хранения.\n\nНалоговая база, указанная в абзаце первом настоящего пункта, определяется налоговыми агентами, если иное не установлено настоящим пунктом. Налоговыми агентами признаются покупатели (получатели) товаров, указанных в абзаце первом настоящего пункта, за исключением физических лиц, не являющихся индивидуальными предпринимателями. Указанные налоговые агенты обязаны исчислить расчетным методом и уплатить в бюджет соответствующую сумму налога вне зависимости от того, исполняют они обязанности налогоплательщика, связанные с исчислением и уплатой налога, и иные обязанности, установленные настоящей главой, или нет.\n\nПри реализации товаров, указанных в абзаце первом настоящего пункта, налогоплательщики-продавцы, освобожденные от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога, и лица, не являющиеся налогоплательщиками, в договоре, первичном учетном документе делают соответствующую запись или проставляют отметку \"Без налога (НДС)\".\n\nВ случае установления факта недостоверного проставления налогоплательщиком - продавцом товаров, указанных в абзаце первом настоящего пункта, в договоре, первичном учетном документе отметки \"Без налога (НДС)\" обязанность по исчислению и уплате налога возлагается на такого налогоплательщика - продавца товаров.\n\nНалогоплательщики-продавцы, освобожденные от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога, и лица, не являющиеся налогоплательщиками, при утрате права на освобождение от исполнения обязанностей налогоплательщика либо на применение патентной системы налогообложения исчисляют и уплачивают налог по операциям реализации товаров, указанных в абзаце первом настоящего пункта, начиная с периода, в котором указанные лица перешли на общий режим налогообложения, до дня наступления обстоятельств, являющихся основанием для утраты права на освобождение от исполнения обязанностей налогоплательщика либо на применение патентной системы налогообложения.\n\nНалогоплательщики-продавцы, применяющие при реализации товаров, указанных в абзаце первом настоящего пункта, налоговые ставки, указанные в пункте 8 статьи 164 настоящего Кодекса, в договоре, первичном учетном документе указывают налоговую ставку 5 либо 7 процентов.\n\nВ отношении медных полуфабрикатов положения настоящего пункта применяются в случае их реализации организациями (индивидуальными предпринимателями), не включенными в перечень производителей кабельно-проводниковой продукции либо в перечень производителей медных полуфабрикатов, организациям (индивидуальным предпринимателям), включенным в перечень производителей кабельно-проводниковой продукции. Указанные в настоящем абзаце перечни определяются федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере промышленного и оборонно-промышленного комплексов, совместно с федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, в порядке, установленном Правительством Российской Федерации.\n\nУказанные в абзаце двенадцатом настоящего пункта перечни подлежат размещению федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере промышленного и оборонно-промышленного комплексов, на своем официальном сайте в информационно-телекоммуникационной сети \"Интернет\".\n\nВ перечень производителей медных полуфабрикатов наряду с организациями (индивидуальными предпринимателями), осуществляющими производство медных полуфабрикатов, включаются следующие лица в случае осуществления ими операций по реализации медных полуфабрикатов:\n\nорганизации (индивидуальные предприниматели), осуществляющие добычу минерального сырья, содержащего медь;\n\nорганизации (индивидуальные предприниматели), входящие в соответствии с антимонопольным законодательством Российской Федерации в одну группу лиц с организациями (индивидуальными предпринимателями), осуществляющими производство медных полуфабрикатов, и (или) организациями (индивидуальными предпринимателями), осуществляющими добычу минерального сырья, содержащего медь;\n\nорганизации (индивидуальные предприниматели), обязанность которых по уплате налога обеспечена поручительством организаций (индивидуальных предпринимателей), осуществляющих производство медных полуфабрикатов, и (или) организаций (индивидуальных предпринимателей), осуществляющих добычу минерального сырья, содержащего медь, оформленным в порядке, предусмотренном статьей 74 настоящего Кодекса, и предусматривающим обязанность поручителя на основании требования налогового органа уплатить в бюджет за налогоплательщика суммы налога, отраженные в налоговых декларациях налогоплательщика либо в решениях по результатам налоговых проверок в отношении налогоплательщика и не уплаченные налогоплательщиком в сроки, установленные настоящим Кодексом.\n\nПравительством Российской Федерации могут быть определены дополнительные требования к организациям (индивидуальным предпринимателям), включаемым в перечни, указанные в абзаце двенадцатом настоящего пункта, а также к поручителям и договору поручительства.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2017 № 335-ФЗ) (В редакции  Федерального закона от 30.11.2024 № 431-ФЗ)","article_title":"Статья 161. Особенности определения налоговой базы налоговыми агентами","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6a033b3a5008467b6def26421bb8ac37bd8fecc5ad2c41964b4088c54536676b"},{"code_id":"NK_RF_2","article_number":"162","version_date":"2000-07-31","article_text":"1) (Подпункт утратил силу - Федеральный закон от 22.07.2005 № 119-ФЗ)\n\n2) полученных за реализованные товары (работы, услуги) в виде финансовой помощи, на пополнение фондов специального назначения, в счет увеличения доходов либо иначе связанных с оплатой реализованных товаров (работ, услуг);\n\n3) полученных в виде процента (дисконта) по полученным в счет оплаты за реализованные товары (работы, услуги) облигациям и векселям, процента по товарному кредиту в части, превышающей размер процента, рассчитанного в соответствии со ставками рефинансирования Центрального банка Российской Федерации, действовавшими в периодах, за которые производится расчет процента; (В редакции Федерального закона от 29.12.2000 № 166-ФЗ)\n\n4) полученных страховых выплат по договорам страхования риска неисполнения договорных обязательств контрагентом страхователя-кредитора, если страхуемые договорные обязательства предусматривают поставку страхователем, применяющим положения пункта 5 статьи 170 настоящего Кодекса, товаров (работ, услуг), реализация которых признается объектом налогообложения в соответствии со статьей 146 настоящего Кодекса, за исключением реализации товаров (работ, услуг), указанных в пункте 1 статьи 164 настоящего Кодекса; (В редакции федеральных законов от 19.07.2011 № 245-ФЗ; от 07.06.2013 № 131-ФЗ; от 05.04.2016 № 97-ФЗ)\n\n5) (Подпункт исключен - Федеральный закон от 29.12.2000 № 166-ФЗ)\n\n1) денежные средства, полученные управляющими организациями, товариществами собственников жилья, жилищно-строительными, жилищными или иными специализированными потребительскими кооперативами, созданными в целях удовлетворения потребностей граждан в жилье и отвечающими за обслуживание внутридомовых инженерных систем, с использованием которых предоставляются коммунальные услуги, на формирование резерва на проведение текущего и капитального ремонта общего имущества в многоквартирных домах, в том числе на формирование фондов капитального ремонта общего имущества в многоквартирных домах;\n\n2) денежные средства, полученные специализированными некоммерческими организациями, которые осуществляют деятельность, направленную на обеспечение проведения капитального ремонта общего имущества в многоквартирных домах, и созданы в соответствии с Жилищным кодексом Российской Федерации, на формирование фондов капитального ремонта общего имущества в многоквартирных домах;\n\n3) денежные средства, полученные энергосбытовой организацией, уполномоченной Правительством Российской Федерации на осуществление купли-продажи электрической энергии (мощности) для целей поставки электрической энергии (мощности) на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области и Херсонской области, на возмещение недополученных доходов в размере, определенном на основании актов Правительства Российской Федерации либо федерального органа исполнительной власти, осуществляющего функции по принятию нормативных правовых актов и контролю за соблюдением антимонопольного законодательства, законодательства в сфере государственного регулирования цен (тарифов) на товары (услуги). (Дополнение подпунктом - Федеральный закон от 23.07.2025 № 229-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 28.11.2009 № 287-ФЗ) (В редакции Федерального закона от 25.12.2012 № 271-ФЗ)","article_title":"Статья 162. Особенности определения налоговой базы с учетом сумм, связанных с расчетами по оплате товаров (работ, услуг)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8b72ec120e65a500c885986b4da8cdce0f8cc8e063a9ea1334f38ec5b781fe82"},{"code_id":"NK_RF_2","article_number":"162.1","version_date":"2000-07-31","article_text":"1. При реорганизации организации в форме выделения вычетам у реорганизованной (реорганизуемой) организации подлежат суммы налога, исчисленные и уплаченные ею с сумм авансовых или иных платежей в счет предстоящих поставок товаров (выполнения работ, оказания услуг), реализуемых на территории Российской Федерации, в случае перевода долга при реорганизации на правопреемника (правопреемников) по обязательствам, связанным с реализацией товаров (работ, услуг) или передачей имущественных прав.\n\nВычеты сумм налога, указанных в настоящем пункте, производятся в полном объеме после перевода долга на правопреемника (правопреемников) по обязательствам, связанным с реализацией товаров (работ, услуг) или передачей имущественных прав.\n\n2. При реорганизации организации в форме выделения налоговая база правопреемника (правопреемников) увеличивается на суммы авансовых или иных платежей в счет предстоящих поставок товаров (выполнения работ, оказания услуг), полученных в порядке правопреемства от реорганизованной (реорганизуемой) организации и подлежащих учету у правопреемника (правопреемников).\n\n3. В случае реорганизации в форме слияния, присоединения, разделения, преобразования вычетам у правопреемника (правопреемников) подлежат суммы налога, исчисленные и уплаченные реорганизованной организацией с сумм авансовых или иных платежей, полученных в счет предстоящих поставок товаров (выполнения работ, оказания услуг).\n\n4. Вычеты суммы налога, исчисленной и уплаченной с сумм авансовых или иных платежей, предусмотренных пунктом 2 настоящей статьи, а также сумм налога, указанных в пункте 3 настоящей статьи, производятся правопреемником (правопреемниками) после даты реализации соответствующих товаров (работ, услуг) или после отражения в учете у правопреемника (правопреемников) операций в случаях расторжения или изменения условий соответствующего договора и возврата соответствующих сумм авансовых платежей, но не позднее одного года с момента такого возврата.\n\n5. В случае реорганизации организации независимо от формы реорганизации подлежащие учету у правопреемника (правопреемников) суммы налога, предъявленные реорганизованной (реорганизуемой) организации и (или) уплаченные этой организацией при приобретении (ввозе) товаров (работ, услуг), но не предъявленные ею к вычету, подлежат вычету правопреемником (правопреемниками) этой организации в порядке, предусмотренном настоящей главой.\n\nВычеты сумм налога, указанных в абзаце первом настоящего пункта, производятся правопреемником (правопреемниками) реорганизованной (реорганизуемой) организации на основании счетов-фактур (копий счетов-фактур), выставленных реорганизованной (реорганизуемой) организации, или счетов-фактур, выставленных правопреемнику (правопреемникам) продавцами при приобретении товаров (работ, услуг), а также на основании копий документов, подтверждающих фактическую уплату реорганизованной (реорганизуемой) организацией сумм налога продавцам при приобретении товаров (работ, услуг), и (или) документов, подтверждающих фактическую уплату сумм налога продавцам при приобретении товаров (работ, услуг) правопреемником (правопреемниками) этой организации.\n\n6. В целях настоящей главы не признается оплатой товаров (работ, услуг) передача налогоплательщиком права требования правопреемнику (правопреемникам) при реорганизации организации. При переходе права требования от реорганизованной (реорганизуемой) организации к правопреемнику (правопреемникам) налоговая база определяется правопреемником (правопреемниками), получающим (получающими) право требования, в момент определения налоговой базы в соответствии с порядком, установленным статьей 167 настоящего Кодекса, с учетом положений, предусмотренных подпунктами 2 - 4 пункта 1 и пунктом 2 статьи 162 настоящего Кодекса.\n\n7. В случае реорганизации организации положения, предусмотренные подпунктами 2 и 3 пункта 5 статьи 169 настоящего Кодекса для принятия сумм налога к вычету или возмещению правопреемником (правопреемниками) реорганизованной (реорганизуемой) организации, считаются выполненными при наличии в счете-фактуре реквизитов реорганизованной (реорганизуемой) организации.\n\n8. При передаче правопреемнику (правопреемникам) товаров (работ, услуг, имущественных прав), в том числе основных средств и нематериальных активов, при приобретении (ввозе) которых суммы налога были приняты реорганизованной (реорганизуемой) организацией к вычету в порядке, предусмотренном настоящей главой, соответствующие суммы налога не подлежат восстановлению и уплате в бюджет реорганизованной (реорганизуемой) организацией.\n\nей определяется на основании передаточного акта или разделительного баланса.\n\n(Дополнение статьей - Федеральный закон от 22.07.2005 № 118-ФЗ)","article_title":"Статья 162.1. Особенности налогообложения при реорганизации организаций","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"96e32f1a1c52763967ac09eb96c25a7b75624aaf3496527ed86b485d7883abfd"},{"code_id":"NK_RF_2","article_number":"162.2","version_date":"2000-07-31","article_text":"1. В случае приобретения товаров (услуг) лицами, сведения о которых внесены в единый государственный реестр юридических лиц или единый государственный реестр индивидуальных предпринимателей (далее в настоящем пункте - покупатели), у продавцов - юридических лиц, которые имели в соответствии с учредительными документами место нахождения постоянно действующего исполнительного органа либо в случае отсутствия постоянно действующего исполнительного органа - иного органа или лица, имеющих право действовать от имени юридического лица без доверенности, на территории Республики Крым или территории города федерального значения Севастополя на день принятия в Российскую Федерацию Республики Крым и образования в составе Российской Федерации новых субъектов, сведения о которых не внесены в единый государственный реестр юридических лиц, либо физических лиц, являющихся предпринимателями, сведения о которых не внесены в единый государственный реестр индивидуальных предпринимателей (далее в настоящем пункте - продавцы), определение налоговой базы производится с учетом следующих особенностей:\n\n1) суммы налога на добавленную стоимость, предъявленные продавцами по товарам (услугам), отгруженным (оказанным) по 31 декабря 2014 года, не принятые к вычету в течение 2014 года, принимаются к вычету покупателем при определении налоговой базы по налогу до 1 июля 2015 года при наличии налоговых накладных, выставленных продавцами при отгрузке товаров (оказании услуг) или при получении оплаты (частичной оплаты) в счет предстоящих поставок товаров (оказания услуг), документов, подтверждающих фактическое перечисление сумм оплаты (частичной оплаты) в счет предстоящих поставок товаров (оказания услуг), договора, предусматривающего перечисление указанных сумм;\n\n2) суммы налога на добавленную стоимость, принятые к вычету покупателем на основании налоговых накладных, выставленных продавцами при получении оплаты (частичной оплаты) в счет предстоящих поставок товаров (оказания услуг), не подлежат восстановлению, за исключением случаев расторжения или изменения условий договора и возврата (включая зачет встречных требований) соответствующих сумм оплаты (частичной оплаты) покупателю. При этом восстановление сумм налога на добавленную стоимость производится покупателем в налоговом периоде, в котором произошли расторжение или изменение условий договора и возврат (включая зачет встречных требований) соответствующих сумм оплаты (частичной оплаты) покупателю.\n\n2. В случае, если покупателем товаров (услуг), являющимся юридическим лицом, которое имело в соответствии с учредительными документами место нахождения постоянно действующего исполнительного органа либо в случае отсутствия постоянно действующего исполнительного органа - иного органа или лица, имеющих право действовать от имени юридического лица без доверенности, на территории Республики Крым или территории города федерального значения Севастополя на день принятия в Российскую Федерацию Республики Крым и образования в составе Российской Федерации новых субъектов, сведения о котором не внесены в единый государственный реестр юридических лиц, либо физическим лицом, являющимся предпринимателем, сведения о котором не внесены в единый государственный реестр индивидуальных предпринимателей (далее в настоящем пункте - покупатель), перечислена оплата (частичная оплата) в счет предстоящих поставок товаров (оказания услуг) продавцу, являющемуся юридическим лицом, которое имело в соответствии с учредительными документами место нахождения постоянно действующего исполнительного органа либо в случае отсутствия постоянно действующего исполнительного органа - иного органа или лица, имеющих право действовать от имени юридического лица без доверенности, на территории Республики Крым или территории города федерального значения Севастополя на день принятия в Российскую Федерацию Республики Крым и образования в составе Российской Федерации новых субъектов, сведения о котором не внесены в единый государственный реестр юридических лиц, либо физическим лицом, являющимся предпринимателем, сведения о котором не внесены в единый государственный реестр индивидуальных предпринимателей (далее в настоящем пункте - продавец), а отгрузка указанных товаров (оказание указанных услуг) произведена (произведено) с 1 января 2015 года, определение налоговой базы производится с учетом следующих особенностей:\n\n1) если поставка товаров (оказание услуг) в счет поступившей ранее оплаты (частичной оплаты) произведена (произведено) продавцом, налоговая база по налогу определяется на дату отгрузки указанных товаров (оказания указанных услуг);\n\n2) суммы налога на добавленную стоимость, предъявленные продавцом покупателю по товарам (услугам), отгруженным (оказанным) в счет поступившей ранее оплаты (частичной оплаты) указанных товаров (услуг), подлежат вычету у покупателя на основании счета-фактуры при выполнении одного из следующих условий:\n\nсуммы налога на добавленную стоимость, отнесенные в соответствии с нормативными правовыми актами Республики Крым и города федерального значения Севастополя к налоговому кредиту при перечислении оплаты (частичной оплаты) в счет предстоящих поставок товаров (оказания услуг), подлежат восстановлению покупателем в налоговом периоде, в котором суммы налога на добавленную стоимость, предъявленные продавцом по товарам (услугам), подлежат вычету покупателем;\n\nсуммы налога на добавленную стоимость, отнесенные покупателем в расходы по налогам с доходов, исчисленным до дня внесения сведений о нем в единый государственный реестр юридических лиц или единый государственный реестр индивидуальных предпринимателей, подлежат включению в состав доходов, подлежащих налогообложению в периоде применения покупателем вычетов в соответствии с настоящим пунктом.\n\n(Дополнение статьей - Федеральный закон от 29.11.2014 № 379-ФЗ)","article_title":"Статья 162.2. Особенности определения налоговой базы на территориях Республики Крым и города федерального значения Севастополя","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"042a2b45cfeeff1701be8f50d926d0df5949925b7f903b669a6a24073aa65255"},{"code_id":"NK_RF_2","article_number":"162.3","version_date":"2000-07-31","article_text":"Налогоплательщики, которые на день принятия в Российскую Федерацию Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и образования в составе Российской Федерации новых субъектов имели в соответствии с учредительными документами место нахождения постоянно действующего исполнительного органа либо в случае отсутствия постоянно действующего исполнительного органа иного органа или лица, имеющих право действовать от имени юридического лица без доверенности, либо имели место жительства на территории Донецкой Народной Республики, Луганской Народной Республики, Запорожской области или Херсонской области, использующие при производстве и (или) реализации товаров товары, приобретенные до начала применения такими налогоплательщиками законодательства Российской Федерации о налогах и сборах и учтенные при инвентаризации, произведенной в соответствии с частями двенадцатой - семнадцатой статьи 313 настоящего Кодекса, определяют налоговую базу по налогу на добавленную стоимость как разницу между стоимостью реализованных товаров, определяемую в соответствии со статьей 154 настоящего Кодекса, с учетом налога и стоимостью приобретения указанных товаров с учетом налога (за исключением амортизируемого имущества). При этом исчисление налога на добавленную стоимость производится расчетным методом с применением расчетных налоговых ставок в размере 9,09 процента и (или) 16,67 процента либо налоговой ставки в размере 0 процентов в случаях, предусмотренных статьей 164 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 21.11.2022 № 443-ФЗ)","article_title":"Статья 162.3. Особенности определения налоговой базы и исчисления налога на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cc9e2bbcb888d51b47bbe8bf73b3451b97b47654ddf94a94d4e788a6c03c379c"},{"code_id":"NK_RF_2","article_number":"163","version_date":"2000-07-31","article_text":"Налоговый период (в том числе для налогоплательщиков, исполняющих обязанности налоговых агентов, далее - налоговые агенты) устанавливается как квартал.\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 163. Налоговый период","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"125d6033ca94b4b3b4e29f27dd8347d6ba947787115e798f89fc5260307f5309"},{"code_id":"NK_RF_2","article_number":"164","version_date":"2000-07-31","article_text":"1. Налогообложение производится по налоговой ставке 0 процентов при реализации:\n\n1) следующих товаров:\n\nвывезенных в таможенной процедуре экспорта;\n\nпомещенных под таможенную процедуру свободной таможенной зоны;\n\nвывезенных в таможенной процедуре реэкспорта товаров, ранее помещенных под таможенную процедуру переработки на таможенной территории, и (или) товаров (продуктов переработки, отходов и (или) остатков), полученных (образовавшихся) в результате переработки товаров, помещенных под таможенную процедуру переработки на таможенной территории;\n\nвывезенных в таможенной процедуре реэкспорта товаров, ранее помещенных под таможенные процедуры свободной таможенной зоны, свободного склада, и (или) товаров, изготовленных (полученных) из товаров, помещенных под таможенные процедуры свободной таможенной зоны, свободного склада.\n\nПоложения настоящего подпункта применяются при условии представления в налоговые органы документов, предусмотренных статьей 165 настоящего Кодекса;\n\n(Подпункт в редакции Федерального закона от 27.11.2017 № 350-ФЗ)\n\n11) товаров, вывезенных с территории Российской Федерации на территорию государства - члена Евразийского экономического союза, в случаях, предусмотренных Договором о Евразийском экономическом союзе от 29 мая 2014 года; (Дополнение подпунктом - Федеральный закон от 03.08.2018 № 302-ФЗ)\n\n12) российскими организациями или индивидуальными предпринимателями физическим лицам товаров, ранее вывезенных в таможенной процедуре экспорта с территории Российской Федерации такими российскими организациями или индивидуальными предпринимателями на территорию иностранного государства, отгружаемых со склада (из помещения), находящегося на территории этого иностранного государства.\n\nПоложения настоящего подпункта применяются при условии, что товар, реализованный физическому лицу, доставляется по адресу на территории иностранного государства, не являющегося государством - членом Евразийского экономического союза;\n\n(Дополнение подпунктом - Федеральный закон от 28.04.2023 № 173-ФЗ)\n\n2) (Подпункт утратил силу - Федеральный закон от 27.11.2010 № 309-ФЗ)\n\n21) услуг по международной перевозке товаров.\n\nВ целях настоящей статьи под международными перевозками товаров понимаются перевозки товаров морскими, речными судами, судами смешанного (река - море) плавания, воздушными судами, железнодорожным транспортом и автотранспортными средствами, при которых пункт отправления или пункт назначения товаров расположен за пределами территории Российской Федерации.\n\nПоложения настоящего подпункта распространяются также на следующие услуги, оказываемые российскими организациями или индивидуальными предпринимателями:\n\nуслуги по предоставлению железнодорожного подвижного состава и (или) контейнеров для осуществления международных перевозок; (В редакции Федерального закона от 27.11.2017 № 350-ФЗ)\n\nтранспортно-экспедиционные услуги, оказываемые на основании договора транспортной экспедиции при организации международной перевозки. В целях настоящей статьи к транспортно-экспедиционным услугам относятся участие в переговорах по заключению контрактов купли-продажи товаров, оформление документов, прием и выдача грузов, разработка документов для проектных перевозок, организация и выполнение перевозки грузов, завоз-вывоз грузов, погрузочно-разгрузочные и складские услуги, информационные услуги, подготовка и дополнительное оборудование транспортных средств, услуги по организации страхования грузов, платежно-финансовых услуг, услуги по таможенному оформлению грузов и транспортных средств, экспедиторское сопровождение, а также разработка и согласование технических условий погрузки и крепления грузов, розыск груза после истечения срока доставки, контроль за соблюдением комплектной отгрузки оборудования, перемаркировка грузов, обслуживание и ремонт универсальных контейнеров грузоотправителей, обслуживание рефрижераторных контейнеров и хранение грузов в складских помещениях и на открытых площадках экспедитора. (В редакции федеральных законов от 19.07.2011 № 245-ФЗ, от 09.11.2020 № 368-ФЗ)\n\nПоложения настоящего подпункта не распространяются на услуги организаций (индивидуальных предпринимателей) по перевозке вывозимого (ввозимого) с территории Российской Федерации (на территорию Российской Федерации) товара, а также на транспортно-экспедиционные услуги организаций (индивидуальных предпринимателей) при организации такой перевозки, если одновременно выполняются следующие условия: (Дополнение абзацем - Федеральный закон от 22.04.2024 № 92-ФЗ)\n\nуказанные организации (индивидуальные предприниматели) осуществляют перевозку только между пунктами, находящимися на территории Российской Федерации; (Дополнение абзацем - Федеральный закон от 22.04.2024 № 92-ФЗ)\n\nуказанные организации (индивидуальные предприниматели) не указаны в транспортных, товаросопроводительных и (или) иных документах, подтверждающих вывоз товаров за пределы территории Российской Федерации (ввоз товаров на территорию Российской Федерации), в качестве одного из перевозчиков. (Дополнение абзацем - Федеральный закон от 22.04.2024 № 92-ФЗ)\n\nПоложения настоящего подпункта не распространяются на услуги указанных в подпункте 9 настоящего пункта российских перевозчиков на железнодорожном транспорте.\n\nПоложения настоящего подпункта распространяются также и на услуги, указанные в абзацах четвертом и пятом настоящего подпункта, оказываемые при организации и осуществлении перевозок железнодорожным транспортом от места прибытия товаров на территорию Российской Федерации (от портов или пограничных станций, расположенных на территории Российской Федерации) до станции назначения товаров, расположенной на территории Российской Федерации. (Дополнение абзацем - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\nВ целях настоящей статьи к международным перевозкам приравниваются работы (услуги) по перевозке и (или) транспортировке углеводородного сырья из пункта отправления, находящегося на континентальном шельфе Российской Федерации и (или) в исключительной экономической зоне Российской Федерации либо в российской части (российском секторе) дна Каспийского моря, в пункт назначения, находящийся за пределами территории Российской Федерации и иных территорий, находящихся под ее юрисдикцией; (Дополнение абзацем - Федеральный закон от 30.09.2013 № 268-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 27.11.2010 № 309-ФЗ)\n\n22) работ (услуг), выполняемых (оказываемых) организациями трубопроводного транспорта нефти и нефтепродуктов, по:\n\nтранспортировке нефти, нефтепродуктов вне зависимости от даты их помещения под соответствующую таможенную процедуру из пункта отправления, расположенного на территории Российской Федерации, до границы Российской Федерации для последующего вывоза трубопроводным транспортом за пределы территории Российской Федерации, либо до морских портов Российской Федерации для последующего вывоза за пределы территории Российской Федерации морским транспортом, либо до пункта перевалки (перегрузки, слива, налива) на иные виды транспорта, в том числе на трубопроводный, расположенный на территории Российской Федерации, для последующего вывоза за пределы территории Российской Федерации иными видами транспорта, в том числе трубопроводным;\n\nперевалке и (или) перегрузке нефти и нефтепродуктов, вывозимых за пределы территории Российской Федерации, в том числе в морских, речных портах, вне зависимости от даты их помещения под соответствующую таможенную процедуру.\n\nПод перевалкой в целях настоящей статьи понимаются погрузка, выгрузка, слив, налив, маркировка, сортировка, упаковка, перемещение в границах морского, речного порта, технологическое накопление грузов, приведение грузов в транспортабельное состояние, их крепление и сепарация.\n\nДля целей настоящей главы к организациям трубопроводного транспорта нефти и нефтепродуктов относятся российские организации, осуществляющие деятельность в сфере транспортировки нефти и нефтепродуктов по магистральным трубопроводам. (В редакции Федерального закона от 21.11.2011 № 330-ФЗ)\n\nНастоящий подпункт распространяется на работы (услуги), выполняемые (оказываемые) на основании договора (контракта) с:\n\nиностранным или российским лицом, которое заключило внешнеэкономическую сделку по реализации нефти и (или) нефтепродуктов, транспортируемых за пределы территории Российской Федерации, или является лицом, от имени либо по поручению которого была заключена указанная внешнеэкономическая сделка;\n\nагентом (комиссионером) иностранного или российского лица, которое заключило внешнеэкономическую сделку по реализации нефти и (или) нефтепродуктов, транспортируемых за пределы территории Российской Федерации, или является лицом, от имени либо по поручению которого была заключена указанная внешнеэкономическая сделка.\n\nПоложения настоящего подпункта распространяются также и на работы (услуги), выполняемые (оказываемые) организациями трубопроводного транспорта нефти и нефтепродуктов, по транспортировке, перевалке и (или) перегрузке нефти и нефтепродуктов, помещенных под таможенную процедуру таможенного транзита, а также вывозимых с территории Российской Федерации на территорию государства - члена Таможенного союза, с учетом особенностей, изложенных в настоящем подпункте. (Дополнение абзацем - Федеральный закон от 21.11.2011 № 330-ФЗ)\n\nНастоящий подпункт не распространяется на работы (услуги), выполняемые (оказываемые) на основании договоров, сторонами которых являются только организации трубопроводного транспорта нефти и нефтепродуктов;\n\n(Дополнение подпунктом - Федеральный закон от 27.11.2010 № 309-ФЗ)\n\n23) услуг по организации транспортировки трубопроводным транспортом природного газа, вывозимого за пределы территории Российской Федерации (ввозимого на территорию Российской Федерации), в том числе помещенного под таможенную процедуру таможенного транзита, а также услуг по транспортировке (организации транспортировки) трубопроводным транспортом природного газа, ввозимого на территорию Российской Федерации для переработки на территории Российской Федерации. (В редакции Федерального закона от 19.07.2011 № 245-ФЗ)\n\nВ целях настоящей главы под организацией транспортировки природного газа трубопроводным транспортом понимаются услуги, оказываемые собственником магистральных газопроводов на основании отдельного договора, предусматривающего организацию транспортировки природного газа; (В редакции Федерального закона от 19.07.2011 № 245-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 27.11.2010 № 309-ФЗ)\n\n23-1) услуг по транспортировке природного газа трубопроводным транспортом в случаях, предусмотренных международными договорами Российской Федерации; (Дополнение подпунктом - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\n24) услуг, оказываемых организацией по управлению единой национальной (общероссийской) электрической сетью по передаче по единой национальной (общероссийской) электрической сети электрической энергии, поставка которой осуществляется из электроэнергетической системы Российской Федерации в электроэнергетические системы иностранных государств; (Дополнение подпунктом - Федеральный закон от 27.11.2010 № 309-ФЗ)\n\n25) работ (услуг), выполняемых (оказываемых) российскими организациями (за исключением организаций трубопроводного транспорта) в морских, речных портах по перевалке и хранению тов\n\nаров, перемещаемых через границу Российской Федерации, в товаросопроводительных документах которых указан пункт отправления и (или) пункт назначения, находящийся за пределами территории Российской Федерации; (Дополнение подпунктом - Федеральный закон от 27.11.2010 № 309-ФЗ)\n\n26) работ (услуг) по переработке товаров, помещенных под таможенную процедуру переработки на таможенной территории; (Дополнение подпунктом - Федеральный закон от 27.11.2010 № 309-ФЗ)\n\n27) транспортно-экспедиционных услуг, а также услуг по предоставлению железнодорожного подвижного состава и (или) контейнеров, оказываемых российскими организациями или индивидуальными предпринимателями, для осуществления перевозки или транспортировки железнодорожным транспортом экспортируемых (реэкспортируемых) товаров, указанных в подпункте 1 настоящего пункта, при условии, что пункт отправления и пункт назначения находятся на территории Российской Федерации. (В редакции Федерального закона от 27.11.2017 № 350-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 22.04.2024 № 92-ФЗ)\n\nПоложения настоящего подпункта не распространяются на услуги указанных в подпункте 9 настоящего пункта российских перевозчиков на железнодорожном транспорте и услуги, указанные в подпункте 21 настоящего пункта;\n\n(Дополнение подпунктом - Федеральный закон от 27.11.2010 № 309-ФЗ)\n\n28) работ (услуг), выполняемых (оказываемых) организациями внутреннего водного транспорта, в отношении товаров, вывозимых в таможенной процедуре экспорта (реэкспорта) при перевозке (транспортировке) товаров в пределах территории Российской Федерации из пункта отправления до пункта выгрузки или перегрузки (перевалки) на морские суда, суда смешанного (река - море) плавания или иные виды транспорта. (В редакции Федерального закона от 27.11.2017 № 350-ФЗ)\n\nВ целях настоящей статьи к организациям внутреннего водного транспорта относятся российские организации, осуществляющие судоходство на внутренних водных путях Российской Федерации и иную связанную с судоходством деятельность на внутренних водных путях Российской Федерации, а также с входом во внутренние воды и выходом в территориальное море Российской Федерации;\n\n(Дополнение подпунктом - Федеральный закон от 27.11.2010 № 309-ФЗ)\n\n28-1) работ (услуг) по перевозке (транспортировке) товаров морскими судами из пункта отправления на территории Российской Федерации до пункта выгрузки или перегрузки (перевалки) на территории Российской Федерации на морские суда в целях дальнейшего вывоза указанных товаров из Российской Федерации; (Дополнение подпунктом - Федеральный закон от 13.07.2020 № 195-ФЗ)\n\n29) углеводородного сырья, добытого на морском месторождении углеводородного сырья, а также продуктов его технологического передела (стабильного конденсата, сжиженного природного газа, широкой фракции легких углеводородов), вывезенных из пункта отправления, находящегося на континентальном шельфе Российской Федерации и (или) в исключительной экономической зоне Российской Федерации либо в российской части (российском секторе) дна Каспийского моря, в пункт назначения, находящийся за пределами территории Российской Федерации и иных территорий, находящихся под ее юрисдикцией, при условии представления документов, предусмотренных статьей 165 настоящего Кодекса, за исключением случаев, если такие товары вывозятся в таможенной процедуре экспорта; (Дополнение подпунктом - Федеральный закон от 30.09.2013 № 268-ФЗ)\n\n210) услуг по перевозке товаров воздушными судами, оказываемых российскими организациями или индивидуальными предпринимателями, при которой пункт отправления и пункт назначения находятся за пределами территории Российской Федерации, в случае, если на территории Российской Федерации совершается посадка воздушного судна, при условии, что место прибытия товаров на территорию Российской Федерации и место убытия товаров с территории Российской Федерации совпадают; (Дополнение подпунктом - Федеральный закон от 29.11.2014 № 382-ФЗ)\n\n211) услуг по компенсации суммы налога физическим лицам - гражданам иностранных государств, имеющим право на такую компенсацию на основании статьи 1691 настоящего Кодекса.\n\nНалогообложение производится по налоговой ставке 0 процентов при оказании услуг, указанных в абзаце первом настоящего подпункта, налогоплательщиками - организациями, осуществляющими розничную торговлю, включенными в перечень организаций розничной торговли в соответствии с пунктом 5 статьи 1691 настоящего Кодекса (далее в настоящей главе - организации розничной торговли), либо иными налогоплательщиками, действующими на основании соглашений с организациями розничной торговли;\n\n(Дополнение подпунктом - Федеральный закон от 27.11.2017 № 341-ФЗ)\n\n212) услуг, оказываемых при международных воздушных перевозках непосредственно в международных аэропортах Российской Федерации, по перечню, утверждаемому Правительством Российской Федерации; (Дополнение подпунктом - Федеральный закон от 25.12.2018 № 493-ФЗ)\n\n213) услуг по ледокольной проводке морских судов:\n\nосуществляющих перевозку товаров, вывозимых из Российской Федерации, в том числе до пункта выгрузки или перегрузки (перевалки) указанных товаров на территории Российской Федерации в целях их дальнейшего вывоза из Российской Федерации;\n\nследующих в пункт отправления на территории Российской Федерации для погрузки товаров в целях их дальнейшего вывоза из Российской Федерации, в том числе перевозки (транспортировки) погруженных товаров до пункта выгрузки или перегрузки (перевалки) на морские суда на территории Российской Федерации в целях дальнейшего вывоза из Российской Федерации.\n\nДля целей настоящего подпункта работы (услуги) по ледокольной проводке морских судов включают в себя обеспечение безопасности плавания судов в акватории Северного морского пути, а именно ледовую разведку ледоколом, прокладку ледоколом каналов во льду, формирование группы судов и расстановку судов для следования за ледоколом (ледоколами), обеспечение плавания судна в проложенном во льду канале за ледоколом на буксире, без буксира в одиночном плавании или в составе группы судов;\n\n(Дополнение подпунктом - Федеральный закон от 13.07.2020 № 195-ФЗ)\n\n3) работ (услуг), непосредственно связанных с перевозкой или транспортировкой товаров, помещенных под таможенную процедуру таможенного транзита при перевозке иностранных товаров от таможенного органа в месте прибытия на территорию Российской Федерации до таможенного органа в месте убытия с территории Российской Федерации; (В редакции федеральных законов от 22.07.2005 № 119-ФЗ; от 27.11.2010 № 309-ФЗ)\n\n31) оказываемых организациями или индивидуальными предпринимателями:\n\nуслуг по предоставлению железнодорожного подвижного состава и (или) контейнеров для осуществления услуг по перевозке или транспортировке железнодорожным транспортом товаров, перемещаемых через территорию Российской Федерации с территории иностранного государства, не являющегося членом Евразийского экономического союза, в том числе через территорию государства - члена Евразийского экономического союза, или с территории государства - члена Евразийского экономического союза на территорию другого иностранного государства, в том числе являющегося членом Евразийского экономического союза; (В редакции федеральных законов от 27.11.2017 № 350-ФЗ, от 29.09.2019 № 322-ФЗ)\n\nтранспортно-экспедиционных услуг, оказываемых на основе договора транспортной экспедиции при организации услуг по перевозке или транспортировке железнодорожным транспортом товаров, порожнего железнодорожного подвижного состава или контейнеров, перемещаемых через территорию Российской Федерации с территории иностранного государства, не являющегося членом Евразийского экономического союза, в том числе через территорию государства - члена Евразийского экономического союза, или с территории государства - члена Евразийского экономического союза на территорию другого иностранного государства, в том числе являющегося членом Евразийского экономического союза. (В редакции Федерального закона от 29.09.2019 № 322-ФЗ)\n\nПоложения настоящего подпункта не распространяются на услуги, оказываемые российскими перевозчиками на железнодорожном транспорте;\n\n(Дополнение подпунктом - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\n4) услуг по перевозке пассажиров и багажа при условии, что пункт отправления или пункт назначения пассажиров и багажа расположены за пределами территории Российской Федерации, при оформлении перевозок на основании единых международных перевозочных документов; (В редакции Федерального закона от 29.12.2000 № 166-ФЗ)\n\n41) услуг по внутренним воздушным перевозкам пассажиров и багажа при условии, что пункт отправления или пункт назначения пассажиров и багажа расположен на территории Республики Крым или на территории города федерального значения Севастополя; (Дополнение подпунктом - Федеральный закон от 04.06.2014 № 151-ФЗ)\n\n42) услуг по внутренним воздушным перевозкам пассажиров и багажа при условии, что пункт отправления или пункт назначения пассажиров и багажа расположен на территории Калининградской области, или при условии, что пункт отправления и (или) пункт назначения пассажиров и багажа расположены на территории Дальневосточного федерального округа; (Дополнение подпунктом - Федеральный закон от 27.11.2017 № 353-ФЗ) (В редакции Федерального закона от 03.08.2018 № 303-ФЗ)\n\n43) услуг по внутренним воздушным перевозкам пассажиров и багажа при условии, что пункт отправления, пункт назначения пассажиров и багажа, а также все промежуточные пункты маршрута перевозки в случае их наличия расположены вне территории Московской области и территории города федерального значения Москвы; (Дополнение подпунктом - Федеральный закон от 06.06.2019 № 123-ФЗ)\n\n5) товаров (работ, услуг) в области космической деятельности.\n\nПоложения настоящего подпункта распространяются на космическую технику, космические объекты, объекты космической инфраструктуры, подлежащие обязательной сертификации в соответствии с законодательством Российской Федерации в области космической деятельности, а также на космическую технику, космические объекты, объекты космической инфраструктуры военного и двойного назначения, на работы (услуги), выполняемые (оказываемые) с использованием техники, находящейся непосредственно в космическом пространстве, в том числе управляемой с поверхности и (или) из атмосферы Земли; работы (услуги) по исследованию космического пространства, по наблюдению за объектами и явлениями в космическом пространстве, в том числе с поверхности и (или) из атмосферы Земли; подготовительные и (или) вспомогательные (сопутствующие) наземные работы (услуги), технологически обусловленные (необходимые) и неразрывно связанные с выполнением работ (оказанием услуг) по исследованию космического пространства и (или) с выполнением работ (оказанием услуг) с использованием техники, находящейся непосредственно в космическом пространстве;\n\n(Подпункт в редакции Федерального закона от 25.11.2009 № 281-ФЗ)\n\n6) драгоценных металлов Государственному фонду драгоценных металлов и драгоценных камней Российской Федерации, фондам драгоценных металлов и драгоценных камней субъектов Российской Федерации, Центральному банку Российской Федерации, банкам налогоплательщиками, осуществляющими добычу или производство драгоценных металлов из лома и отходов, содержащих драгоценные металлы, а также налогоплательщиками, осуществляющими без лицензии на пользование недрами производство драгоценных металлов из лома и отходов, содержащих драгоценные металлы; (В редакции Федерального закона от 27.06.2018 № 159-ФЗ)\n\n61) необработанных природных алмазов Государственному фонду драгоценных металлов и драгоценных камней Российской Федерации, фондам драгоценных металлов и драгоценных камней субъектов Российской Федерации, Центральному банку Российской Федерации, банкам, иным организациям налогоплательщиками, осуществляющими добычу драгоценных камней;\n\nобработанных природных алмазов Государственному фонду драгоценных металлов и драгоценных камней Российской Федерации, фондам драгоценных металлов и драгоценных камней субъектов Российской Федерации, Центральному банку Российской Федерации и банкам налогоплательщиками, осуществляющими добычу драгоценных камней;\n\n(Дополнение подпунктом - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n62) драгоценных металлов в слитках (за исключением серебра в слитках) физическим лицам налогоплательщиками, осуществляющими их добычу. Положения настоящего подпункта применяются в отношении драгоценных металлов, аффинаж которых осуществлен на территории Российской Федерации и которые реализуются физическим лицам в счет выкупа цифровых прав, включающих одновременно цифровые финансовые активы и утилитарные цифровые права, в случае, если решением о выпуске указанных цифровых прав определены срок их выкупа и место отгрузки товаров, указанных в настоящем подпункте, на территории Российской Федерации; (Дополнение подпунктом - Федеральный закон от 31.07.2023 № 389-ФЗ) (В редакции  Федерального закона от 23.03.2024 № 49-ФЗ)\n\n7) товаров (работ, услуг) для официального пользования иностранными дипломатическими и приравненными к ним представительствами или для личного пользования дипломатического или административно-технического персонала этих представительств, включая проживающих вместе с ними членов их семей.\n\nРеализация товаров (выполнение работ, оказание услуг), указанных в настоящем подпункте, подлежит налогообложению по ставке 0 процентов в случаях, если законодательством соответствующего иностранного государства установлен аналогичный порядок в отношении дипломатических и приравненных к ним представительств Российской Федерации, дипломатического и административно-технического персонала этих представительств (включая проживающих вместе с ними членов их семей), либо если такая норма предусмотрена в международном договоре Российской Федерации. Перечень иностранных государств, в отношении представительств которых применяются нормы настоящего подпункта, определяется федеральным органом исполнительной власти в сфере международных отношений совместно с Министерством финансов Российской Федерации. (В редакции федеральных законов от 29.06.2004 № 58-ФЗ; от 02.11.2004 № 127-ФЗ)\n\nПорядок применения настоящего подпункта устанавливается Правительством Российской Федерации;\n\n8) припасов, вывезенных с территории Российской Федерации. В целях настоящей статьи припасами признаются топливо и горюче-смазочные материалы, которые необходимы для обеспечения нормальной эксплуатации воздушных и морских судов, судов смешанного (река - море) плавания; (Дополнение подпунктом - Федеральный закон от 29.05.2002 № 57-ФЗ) (В редакции Федерального закона от 27.11.2010 № 309-ФЗ)\n\n9) выполняемых российскими перевозчиками на железнодорожном транспорте:\n\nуслуг по перевозке или транспортировке экспортируемых (реэкспортируемых) товаров, указанных в подпункте 1 настоящего пункта; (В редакции Федерального закона от 27.11.2017 № 350-ФЗ)\n\nработ (услуг), связанных с указанной в абзаце втором настоящего подпункта перевозкой или транспортировкой, стоимость которых указана в перевозочных документах на перевозку экспортируемых (реэкспортируемых) товаров. (В редакции Федерального закона от 27.11.2017 № 350-ФЗ)\n\nПоложения настоящего подпункта применяются при условии, что указанные в настоящем подпункте работы (услуги) выполняются (оказываются) в отношении товаров, помещенных под таможенную процедуру экспорта, реэкспорта; (В редакции  Федерального закона от 19.12.2022 № 549-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 22.07.2005 № 119-ФЗ) (В редакции Федерального закона от 05.04.2010 № 50-ФЗ)\n\n91) выполняемых (оказываемых) российскими перевозчиками на железнодорожном транспорте:\n\nработ (услуг) по перевозке или транспортировке товаров, вывозимых с территории Российской Федерации на территорию государства - члена Евразийского экономического союза, и работ (услуг), непосредственно связанных с перевозкой или транспортировкой указанных товаров, стоимость которых указана в перевозочных документах на перевозку товаров; (В редакции Федерального закона от 29.09.2019 № 322-ФЗ)\n\nработ (услуг) по перевозке или транспортировке товаров, порожнего железнодорожного подвижного состава или контейнеров, перемещаемых через территорию Российской Федерации с территории иностранного государства, не являющегося членом Евразийского экономического союза, в том числе через территорию государства - члена Евразийского экономического союза, или с территории государства - члена Евразийского экономического союза на территорию другого иностранного государства, в том числе являющегося членом Евразийского экономического союза, и работ (услуг), непосредственно связанных с указанной перевозкой или транспортировкой, стоимость которых указана в перевозочных документах на перевозку товаров, порожнего железнодорожного подвижного состава или контейнеров; (В редакции Федерального закона от 29.09.2019 № 322-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\n92) услуг по перевозке пассажиров железнодорожным транспортом в пригородном сообщении; (Дополнение подпунктом - Федеральный закон от 06.04.2015 № 83-ФЗ)\n\n93) услуг по перевозке пассажиров и багажа железнодорожным транспортом общего пользования в дальнем сообщении (за исключением услуг, указанных в подпункте 4 настоящего пункта); (Дополнение подпунктом - Федеральный закон от 30.11.2016 № 401-ФЗ)\n\n94) услуг по перевозке пассажиров и багажа высокоскоростным железнодорожным транспортом по высокоскоростной железнодорожной магистрали Москва - Санкт-Петербург (далее в настоящем подпункте - высокоскоростная железнодорожная магистраль), оказываемых в соответствии с концессионным соглашением о финансировании, создании, эксплуатации инфраструктуры высокоскоростного железнодорожного транспорта общего пользования, а также услуг по организации таких перевозок пассажиров и багажа (далее в настоящем подпункте - услуги по организации перевозок).\n\nВ целях настоящего подпункта к услугам по организации перевозок относятся услуги по заключению и исполнению договоров перевозки пассажиров и багажа высокоскоростным железнодорожным транспортом по высокоскоростной железнодорожной магистрали, по организации распространения проездных документов (билетов) для проезда по высокоскоростной железнодорожной магистрали, по осуществлению сбора и перечисления заказчику по договору на оказание услуг по организации перевозок денежных средств, поступивших в качестве оплаты проездных документов (билетов) для проезда по высокоскоростной железнодорожной магистрали, по проверке наличия и действительности проездных документов (билетов) для проезда по высокоскоростной железнодорожной магистрали и по пресечению случаев безбилетного проезда, по эксплуатации, обслуживанию и ремонту высокоскоростного железнодорожного подвижного состава, пассажирской инфраструктуры высокоскоростного железнодорожного транспорта, по допуску высокоскоростного железнодорожного подвижного состава к эксплуатации на инфраструктуре высокоскоростного железнодорожного транспорта, по проверке работоспособности систем и иных параметров высокоскоростного железнодорожного подвижного состава, по управлению высокоскоростным железнодорожным подвижным составом при осуществлении перевозок по высокоскоростной железнодорожной магистрали, по подготовке графика движения поездов, по обслуживанию пассажиров, по размещению, трансляции информации, в том числе навигационного характера, на объектах пассажирской инфраструктуры высокоскоростного железнодорожного транспорта, а также по обеспечению соблюдения требований транспортной безопасности при эксплуатации высокоскоростного железнодорожного подвижного состава, на объектах пассажирской инфраструктуры высокоскоростного железнодорожного транспорта и объектах иной инфраструктуры, необходимой для содержания, обслуживания и ремонта высокоскоростного железнодорожно\n\nго подвижного состава.\n\nК услугам по организации перевозок не относятся не указанные в настоящем подпункте услуги по организации рекламной, торговой и иной коммерческой деятельности в высокоскоростном железнодорожном подвижном составе и на объектах пассажирской инфраструктуры высокоскоростного железнодорожного транспорта;\n\n(Дополнение подпунктом - Федеральный закон от 23.07.2025 № 227-ФЗ)\n\n10) построенных судов, подлежащих регистрации в Российском международном реестре судов, а также в 2022 и 2023 годах судов, принадлежащих на праве собственности российской лизинговой компании и зарегистрированных в Российском международном реестре судов, при условии представления в налоговые органы документов, предусмотренных статьей 165 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 20.12.2005 № 168-ФЗ) (В редакции  федеральных законов от 14.07.2022 № 323-ФЗ, от 21.11.2022 № 443-ФЗ)\n\n11) товаров (работ, услуг) для официального использования международными организациями и их представительствами, осуществляющими деятельность на территории Российской Федерации. Перечень международных организаций, в отношении которых применяются нормы настоящего подпункта, определяется федеральным органом исполнительной власти в сфере международных отношений совместно с Министерством финансов Российской Федерации.\n\nНалоговая ставка 0 процентов применяется в отношении товаров (работ, услуг), реализуемых для официального использования международными организациями и их представительствами, осуществляющими деятельность на территории Российской Федерации на основании положений международных договоров Российской Федерации, предусматривающих освобождение от налога;\n\n(Дополнение подпунктом - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\n12) услуг по предоставлению морских судов, судов смешанного (река - море) плавания и услуг членов экипажей таких судов в пользование на определенный срок на основании договоров фрахтования судна на время (тайм-чартер) для целей перевозки (транспортировки) вывозимых за пределы территории Российской Федерации или ввозимых на территорию Российской Федерации товаров; (Дополнение подпунктом - Федеральный закон от 07.11.2011 № 305-ФЗ) (В редакции Федерального закона от 03.08.2018 № 302-ФЗ)\n\n13) товаров (работ, услуг) и имущественных прав при реализации FIFA (Federation Internationale de Football Association), дочерним организациям FIFA, товаров (работ, услуг) и имущественных прав в связи с осуществлением мероприятий конфедерациям, Организационному комитету \"Россия-2018\", дочерним организациям Организационного комитета \"Россия-2018\", национальным футбольным ассоциациям, Российскому футбольному союзу, производителям медиаинформации FIFA, поставщикам товаров (работ, услуг) FIFA, определенным Федеральным законом \"О подготовке и проведении в Российской Федерации чемпионата мира по футболу FIFA 2018 года, Кубка конфедераций FIFA 2017 года, чемпионата Европы по футболу UEFA 2020 года и внесении изменений в отдельные законодательные акты Российской Федерации\", а также товаров (работ, услуг) и имущественных прав в связи с осуществлением мероприятий по подготовке и проведению в Российской Федерации чемпионата Европы по футболу UEFA 2020 года при реализации UEFA (Union of European Football Associations), дочерним организациям UEFA, коммерческим партнерам UEFA, поставщикам товаров (работ, услуг) UEFA и вещателям UEFA, Российскому футбольному союзу, локальной организационной структуре, определенным указанным Федеральным законом. Порядок применения положений настоящего подпункта устанавливается Правительством Российской Федерации; (Дополнение подпунктом - Федеральный закон от 07.06.2013 № 108-ФЗ) (В редакции Федерального закона от 01.05.2019 № 101-ФЗ)\n\n14) товаров (работ, услуг), имущественных прав, приобретаемых для целей организации и проведения XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи организациями, являющимися иностранными организаторами XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи в соответствии со статьей 3 Федерального закона от 1 декабря 2007 года № 310-ФЗ \"Об организации и о проведении XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, развитии города Сочи как горноклиматического курорта и внесении изменений в отдельные законодательные акты Российской Федерации\", иностранными маркетинговыми партнерами Международного олимпийского комитета, в том числе официальными вещательными компаниями, в соответствии со статьей 31 указанного Федерального закона, и филиалами, представительствами в Российской Федерации иностранных организаций, являющихся маркетинговыми партнерами Международного олимпийского комитета, в том числе официальными вещательными компаниями, в соответствии со статьей 31 указанного Федерального закона. Порядок применения положений настоящего подпункта устанавливается Правительством Российской Федерации; (Дополнение подпунктом - Федеральный закон от 23.07.2013 № 216-ФЗ)\n\n15) гражданских воздушных судов, зарегистрированных (подлежащих регистрации) в Государственном реестре гражданских воздушных судов Российской Федерации, а также работ (услуг) по строительству гражданских воздушных судов при условии представления в налоговые органы документов, предусмотренных пунктом 151 статьи 165 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 29.09.2019 № 324-ФЗ) (В редакции  Федерального закона от 31.07.2025 № 297-ФЗ)\n\n151) собранных (произведенных) на территории Евразийского экономического союза беспилотных гражданских воздушных судов с максимальной взлетной массой от 0,15 килограмма до 30 килограммов при условии представления в налоговые органы документов, предусмотренных пунктом 157 статьи 165 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 31.07.2025 № 297-ФЗ)\n\n16) авиационных двигателей, запасных частей и комплектующих изделий, предназначенных для строительства, ремонта и (или) модернизации на территории Российской Федерации гражданских воздушных судов (за исключением сверхлегких пилотируемых воздушных судов с массой конструкции 115 килограммов и менее), при условии представления в налоговые органы документов, предусмотренных пунктом 152 статьи 165 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 29.09.2019 № 324-ФЗ) (В редакции Федерального закона от 14.11.2023 № 538-ФЗ)\n\n161) неисправных (исправных) авиационных двигателей, запасных частей и комплектующих изделий, предназначенных для гражданских воздушных судов и передаваемых в обмен на аналогичные исправные (неисправные) авиационные двигатели, запасные части и комплектующие изделия, при условии представления в налоговый орган документов, предусмотренных пунктом 156 статьи 165 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 14.11.2023 № 538-ФЗ)\n\n162) двигателей, запасных частей и комплектующих изделий, предназначенных для строительства, ремонта и (или) модернизации на территории Российской Федерации беспилотных гражданских воздушных судов с максимальной взлетной массой от 0,15 килограмма до 30 килограммов при условии представления в налоговые органы документов, предусмотренных пунктом 158 статьи 165 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 31.07.2025 № 297-ФЗ)\n\n17) услуг по передаче гражданских воздушных судов, зарегистрированных (подлежащих регистрации) в Государственном реестре гражданских воздушных судов Российской Федерации, по договорам аренды (лизинга) при условии представления в налоговые органы документов, предусмотренных статьей 165 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 29.09.2019 № 324-ФЗ)\n\n18) услуг по предоставлению в аренду или пользование на ином праве объектов туристской индустрии, введенных в эксплуатацию (в том числе после реконструкции) после 1 января 2022 года и включенных в реестр объектов туристской индустрии. Порядок ведения реестра объектов туристской индустрии утверждается Правительством Российской Федерации.\n\nНалогоплательщики, оказывающие услуги, указанные в абзаце первом настоящего подпункта, вправе применять налоговую ставку 0 процентов до истечения двадцати последовательных налоговых периодов, следующих за налоговым периодом, в котором соответствующий объект туристской индустрии был введен в эксплуатацию (в том числе после реконструкции);\n\n(Дополнение подпунктом - Федеральный закон от 26.03.2022 № 67-ФЗ)\n\n19) услуг по предоставлению мест для временного проживания в гостиницах и иных средствах размещения.\n\nПоложения настоящего подпункта применяются по 31 декабря 2030 года включительно, если иное не установлено настоящим подпунктом.\n\nНалогоплательщики, оказывающие услуги по предоставлению мест для временного проживания в гостиницах и иных средствах размещения, которые являются объектами туристской индустрии, указанными в абзаце первом подпункта 18 настоящего пункта, вправе в отношении указанных услуг применять налоговую ставку 0 процентов до наступления наиболее поздней из следующих дат:\n\n31 декабря 2030 года включительно;\n\nпоследний день налогового периода (включительно), в котором истекают двадцать последовательных налоговых периодов, следующих за налоговым периодом, в котором соответствующий объект туристской индустрии был введен в эксплуатацию (в том числе после реконструкции);\n\n(Дополнение подпунктом - Федеральный закон от 26.03.2022 № 67-ФЗ) (В редакции  Федерального закона от 23.07.2025 № 227-ФЗ)\n\n20) налогоплательщиком, сведения о котором включены в единый государственный реестр юридических лиц или единый государственный реестр индивидуальных предпринимателей до 5 октября 2022 года включительно, который заключил до 5 октября 2022 года включительно государственный (муниципальный) контракт с государственным или муниципальным заказчиком Российской Федерации либо соглашение с государственным органом (государственным учреждением), трансграничным концерном, государственным концерном, государственным унитарным предприятием Донецкой Народной Республики, Луганской Народной Республики, Запорожской области или Херсонской области на поставку товаров в пункт назначения, находящийся на территории Донецкой Народной Республики, Луганской Народной Республики, Запорожской области или Херсонской области, либо заключил до 31 декабря 2022 года договор, не являющийся указанными государственным (муниципальным) контрактом либо соглашением, на поставку товаров на эти территории с юридическим лицом, созданным на территории Донецкой Народной Республики, Луганской Народной Республики, Запорожской области или Херсонской области до дня принятия указанных территорий в Российскую Федерацию и образования в составе Российской Федерации новых субъектов (индивидуальным предпринимателем, зарегистрированным на одной из указанных территорий до дня принятия указанных территорий в Российскую Федерацию и образования в составе Российской Федерации новых субъектов), либо с иностранным лицом, товаров, предусмотренных указанными государственным (муниципальным) контрактом, соглашением, договором.\n\nВ случае реализации товаров по договору, не являющемуся государственным (муниципальным) контрактом либо соглашением, указанными в абзаце первом настоящего подпункта, указанная в абзаце первом настоящего пункта ставка налога применяется при условии отгрузки таких товаров до 31 декабря 2022 года включительно и получения полной оплаты таких товаров на открытый в банке счет налогоплательщика до 25 января 2023 года включительно;\n\n(Дополнение подпунктом - Федеральный закон от 21.11.2022 № 443-ФЗ)\n\n21) услуг по перевозке товаров автотранспортными средствами (за исключением услуг, указанных в подпункте 21 настоящего пункта), при которой пункт отправления или пункт назначения товаров расположен на территории Донецкой Народной Республики, Луганской Народной Республики, Запорожской области или Херсонской области, при условии заключения договора на перевозку товаров до 31 декабря 2022 года включительно, оказания услуг по перевозке товаров до указанной даты и получения полной оплаты на открытый в банке счет налогоплательщика (на счет налогоплательщика, открытый в организации, зарегистрированной на территории Донецкой Народной Республики, Луганской Народной Республики, Запорожской области или Херсонской области и обладающей в соответствии с законодательством Донецкой Народной Республики или Луганской Народной Республики, с нормативными правовыми актами Запорожской области или Херсонской области правом на осуществление банковских операций) в счет оказания таких услуг на указанных территориях до 25 января 2023 года включительно; (Дополнение подпунктом - Федеральный закон от 21.11.2022 № 443-ФЗ)\n\n22) работ (услуг) российскими судоремонтными предприятиями (организациями) по ремонту морских судов, судов внутреннего плавания, судов смешанного (река - море) плавания и судов рыбопромыслового флота при условии заключения инвестиционного соглашения о развитии и модернизации собственных производственных мощностей (далее в настоящей главе - инвестиционное соглашение).\n\nИнвестиционное соглашение заключается российским судоремонтным предприятием (организацией) с федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере промышленного и оборонно-промышленного комплексов, и Министерством финансов Российской Федерации.\n\nИнвестиционное соглашение должно содержать перечень мероприятий по развитию и модернизации собственных производственных мощностей и обязательство по направлению средств на реализацию данных мероприятий ежегодно в течение семи последовательных календарных лет начиная с 1 января года подписания инвестиционного соглашения. Размер таких средств должен составлять не менее 20 процентов определяемой по итогам предыдущего календарного года суммарной стоимости реализованных работ (услуг) российскими судоремонтными предприятиями (организациями) по ремонту морских судов, судов внутреннего плавания, судов смешанного (река - море) плавания и судов рыбопромыслового флота. Средства в указанном размере должны ежегодно направляться на финансирование расходов на приобретение, сооружение, изготовление, доставку объектов основных средств, используемых для выполнения работ (оказания услуг), указанных в настоящем подпункте, и доведение таких объектов до состояния, в котором они пригодны для использования. При этом под основными средствами понимается часть имущества в значении, предусмотренном статьей 257 настоящего Кодекса.\n\nИнвестиционное соглашение заключается до 31 декабря 2024 года включительно. С 1 января 2025 года заключение инвестиционных соглашений не допускается.\n\nИнвестиционное соглашение действует до 31 декабря включительно года, в котором истекает семь последовательных календарных лет, исчисляемых с 1 января года, в котором было заключено инвестиционное соглашение.\n\nИнвестиционное соглашение может быть расторгнуто в одностороннем порядке путем направления уведомления о его расторжении российским судоремонтным предприятием (организацией), заключившим инвестиционное соглашение, или федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере промышленного и оборонно-промышленного комплексов, по согласованию с Министерством финансов Российской Федерации в случае нарушения российским судоремонтным предприятием (организацией) обязательства, указанного в настоящем подпункте.\n\nФорма инвестиционного соглашения, порядок заключения (расторжения) инвестиционного соглашения, форма уведомления о расторжении инвестиционного соглашения, форма уведомления о внесении изменений в инвестиционное соглашение и порядок проведения мониторинга выполнения условий инвестиционного соглашения утверждаются федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере промышленного и оборонно-промышленного комплексов, по согласованию с Министерством финансов Российской Федерации.\n\n(Дополнение подпунктом - Федеральный закон от 24.06.2023 № 261-ФЗ)\n\n2. Налогообложение производится по налоговой ставке 10 процентов при реализации:\n\n1) следующих продовольственных товаров:\n\nскота и птицы в живом весе;\n\nмяса и мясопродуктов (за исключением деликатесных: вырезки, телятины, языков, колбасных изделий - сырокопченых в/с, сырокопченых полусухих в/с, сыровяленых, фаршированных в/с; копченостей из свинины, баранины, говядины, телятины, мяса птицы - балыка, карбонада, шейки, окорока, пастромы, филея; свинины и говядины запеченных; консервов - ветчины, бекона, карбонада и языка заливного);\n\nмолока и молокопродуктов (включая мороженое, произведенное на их основе, за исключением мороженого, выработанного на плодово-ягодной основе, фруктового и пищевого льда);\n\nяйца и яйцепродуктов;\n\nмасла растительного (за исключением масла пальмового); (В редакции Федерального закона от 02.08.2019 № 268-ФЗ)\n\nмаргарина, жиров специального назначения, в том числе жиров кулинарных, кондитерских, хлебопекарных, заменителей молочного жира, эквивалентов, улучшителей и заменителей масла какао, спредов, смесей топленых; (В редакции Федерального закона от 29.11.2012 № 206-ФЗ)\n\nсахара, включая сахар-сырец;\n\nзерна, комбикормов, кормовых смесей, зерновых отходов;\n\nмаслосемян и продуктов их переработки (шротов(а), жмыхов);\n\nхлеба и хлебобулочных изделий (включая сдобные, сухарные и бараночные изделия);\n\nмакаронных изделий;\n\nрыбы живой (за исключением ценных пород: белорыбицы, лосося балтийского и дальневосточного, осетровых (белуги, бестера, осетра, севрюги, стерляди), семги, нельмы, кеты, чавычи, кижуча, муксуна, омуля, сига сибирского и амурского, чира); (В редакции Федерального закона от 02.07.2021 № 308-ФЗ)\n\nморе- и рыбопродуктов, в том числе рыбы охлажденной, мороженой и других видов обработки, сельди, консервов и пресервов (за исключением деликатесных: икры осетровых и лососевых рыб; белорыбицы, лосося балтийского, осетровых рыб - белуги, бестера, осетра, севрюги, стерляди; семги; спинки и теши нельмы х/к; кеты и чавычи слабосоленых, среднесоленых и семужного посола; спинки кеты, чавычи и кижуча х/к, теши кеты и боковника чавычи х/к; спинки муксуна, омуля, сига сибирского и амурского, чира х/к; пресервов филе - ломтиков лосося балтийского и лосося дальневосточного; мяса крабов и наборов отдельных конечностей крабов варено-мороженых; лангустов);\n\nпродуктов детского и диабетического питания;\n\nовощей (включая картофель);\n\nфруктов и ягод (включая виноград); (Дополнение абзацем - Федеральный закон от 02.08.2019 № 268-ФЗ)\n\n11) обработанных протравителями (протравленных) семян сельскохозяйственных культур; (Дополнение подпунктом - Федеральный закон от 19.12.2023 № 611-ФЗ) (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n12) племенного крупного рогатого скота;\n\nплеменных свиней;\n\nплеменных овец;\n\nплеменных коз;\n\nплеменных лошадей;\n\nплеменной птицы (племенного яйца);\n\nплеменных рыб;\n\nсемени (спермы), полученного от племенных быков, племенных свиней, племенных баранов, племенных козлов, племенных жеребцов;\n\nэмбрионов, полученных от племенного крупного рогатого скота, племенных свиней, племенных овец, племенных коз, племенных лошадей;\n\nэмбрионов, молоди, полученных от племенных рыб.\n\nПоложения настоящего подпункта применяются при наличии у налогоплательщика племенного свидетельства (паспорта), выданного в соответствии с Федеральным законом от 3 августа 1995 года № 123-ФЗ \"О племенном животноводстве\";\n\n(Дополнение подпунктом - Федеральный закон от 29.10.2024 № 362-ФЗ)\n\n2) следующих товаров для детей:\n\nтрикотажных изделий для новорожденных и детей ясельной, дошкольной, младшей и старшей школьных возрастных групп: верхних\n\nтрикотажных изделий, бельевых трикотажных изделий, чулочно-носочных изделий, прочих трикотажных изделий: перчаток, варежек, головных уборов;\n\nшвейных изделий, в том числе изделий из натуральных овчины и кролика (включая изделия из натуральных овчины и кролика с кожаными вставками) для новорожденных и детей ясельной, дошкольной, младшей и старшей школьных возрастных групп, верхней одежды (в том числе плательной и костюмной группы), нательного белья, головных уборов, одежды и изделий для новорожденных и детей ясельной группы. Положения настоящего абзаца не распространяются на швейные изделия из натуральной кожи и натурального меха, за исключением натуральных овчины и кролика;\n\nобуви (за исключением спортивной): пинеток, гусариковой, дошкольной, школьной; валяной и резиновой: малодетской, детской, школьной;\n\nдетской мебели: кроватей, матрацев, стульев, стульчиков для кормления, манежей;\n\nвелосипедов;\n\nдетских удерживающих устройств, предназначенных для использования в механических транспортных средствах;\n\nшкольно-письменных принадлежностей: тетрадей школьных, тетрадей для рисования, папок для тетрадей, обложек для учебников, обложек для дневников, обложек для тетрадей, альбомов для рисования, альбомов для черчения, дневников школьных, пеналов, счетных палочек, касс цифр и букв, счетов школьных, пластилина;\n\nизделий, предназначенных для ухода за детьми: бутылочек, сосок (включая пустышки), горшков, ванночек, горок для купания новорожденных;\n\nподгузников и пеленок;\n\n(Подпункт в редакции  Федерального закона от 19.10.2023 № 504-ФЗ)\n\n3) периодических печатных изданий, за исключением периодических печатных изданий рекламного или эротического характера;\n\nкнижной продукции, связанной с образованием, наукой и культурой, за исключением книжной продукции рекламного и эротического характера. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 28.12.2001 № 179-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 28.12.2001 № 179-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 28.12.2001 № 179-ФЗ)\n\nабзац. (Утратил силу - Федеральный закон от 28.12.2001 № 179-ФЗ)\n\nВ целях настоящего подпункта под периодическим печатным изданием понимается газета, журнал, альманах, бюллетень, иное издание, имеющее постоянное название, текущий номер и выходящее в свет не реже одного раза в год.\n\nВ целях настоящего подпункта к периодическим печатным изданиям рекламного характера относятся периодические печатные издания, в которых реклама превышает 45 процентов объема одного номера периодического печатного издания; (В редакции Федерального закона от 30.11.2016 № 408-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 28.12.2001 № 179-ФЗ)\n\n4) следующих медицинских товаров отечественного и зарубежного производства:\n\nлекарственных средств, включая фармацевтические субстанции, лекарственные средства, предназначенные для проведения клинических исследований лекарственных препаратов, и лекарственные препараты, изготовленные аптечными организациями; (В редакции Федерального закона от 25.11.2013 № 317-ФЗ)\n\nмедицинских изделий, за исключением медицинских изделий, операции по реализации которых освобождаются от налогообложения в соответствии с подпунктом 1 пункта 2 статьи 149 настоящего Кодекса. Положения настоящего абзаца применяются при представлении в налоговый орган регистрационного удостоверения медицинского изделия, выданного в соответствии с правом Евразийского экономического союза, или регистрационного удостоверения на медицинское изделие (регистрационного удостоверения на изделие медицинского назначения (медицинскую технику), выданного в соответствии с законодательством Российской Федерации; (В редакции федеральных законов от 07.03.2017 № 25-ФЗ, от 29.11.2021 № 382-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 28.12.2001 № 179-ФЗ)\n\n5) (Дополнение подпунктом - Федеральный закон от 02.10.2012 № 161-ФЗ) (Утратил силу - Федеральный закон от 23.06.2016 № 187-ФЗ)\n\n6) услуг по внутренним воздушным перевозкам пассажиров и багажа (за исключением услуг, указанных в подпунктах 41, 42 и 43 пункта 1 настоящей статьи). (Дополнение подпунктом - Федеральный закон от 06.04.2015 № 83-ФЗ) (В редакции федеральных законов от 03.08.2018 № 303-ФЗ; от 06.06.2019 № 123-ФЗ)\n\n7) (Дополнение подпунктом - Федеральный закон от 29.12.2015 № 386-ФЗ) (Утратил силу - Федеральный закон от 30.11.2016 № 401-ФЗ)\n\nКоды видов продукции, перечисленных в настоящем пункте, в соответствии с Общероссийским классификатором продукции по видам экономической деятельности, а также Товарной номенклатурой внешнеэкономической деятельности определяются Правительством Российской Федерации. (В редакции федеральных законов от 29.12.2000 № 166-ФЗ; от 03.07.2016 № 248-ФЗ)\n\n(Пункт 5 исключен - Федеральный закон  от 29.12.2000 № 166-ФЗ)\n\nНалогоплательщик вправе не применять налоговую ставку, указанную в пункте 1 настоящей статьи, только в отношении всех осуществляемых налогоплательщиком операций, предусмотренных абзацем первым настоящего пункта.\n\nНе допускается применение разных налоговых ставок в зависимости от того, кто является покупателем (приобретателем) соответствующих товаров (работ, услуг).\n\n(Дополнение пунктом - Федеральный закон от 27.11.2017 № 350-ФЗ)\n\n1) 5 процентов - в случае выполнения одного из следующих условий:\n\nза календарный год, предшествующий календарному году, начиная с которого организация или индивидуальный предприниматель переходит на упрощенную систему налогообложения, у указанных организации или индивидуального предпринимателя сумма доходов, определяемых в порядке, установленном главой 23, 25 или 261 настоящего Кодекса, а также в порядке, установленном Федеральным законом от 25 февраля 2022 года № 17-ФЗ \"О проведении эксперимента по установлению специального налогового режима \"Автоматизированная упрощенная система налогообложения\", не превысила в совокупности 250 миллионов рублей, и такие организация или индивидуальный предприниматель не имеет оснований для освобождения от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога;\n\nза предшествующий налоговый период по налогу, уплачиваемому в связи с применением упрощенной системы налогообложения, у организации или индивидуального предпринимателя сумма доходов, определяемых в соответствии со статьей 34615 и подпунктами 1 и 3 пункта 1 статьи 34625 настоящего Кодекса, не превысила в совокупности 250 миллионов рублей, и такие организация или индивидуальный предприниматель не имеет оснований для освобождения от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога;\n\nв течение налогового периода по налогу, уплачиваемому в связи с применением упрощенной системы налогообложения, организация или индивидуальный предприниматель начинает исполнять обязанности налогоплательщика, связанные с исчислением и уплатой налога.\n\nЕсли в течение налогового периода по налогу, уплачиваемому в связи с применением упрощенной системы налогообложения, у организации или индивидуального предпринимателя сумма доходов, определяемых в соответствии со статьей 34615 и подпунктами 1 и 3 пункта 1 статьи 34625 настоящего Кодекса, превысила в совокупности 250 миллионов рублей, такие организация или индивидуальный предприниматель начиная с 1-го числа месяца, следующего за месяцем, в котором имело место указанное превышение, утрачивает право на применение налоговой ставки 5 процентов. При этом в целях определения указанной величины доходов учитываются в том числе полученные в календарном году применения упрощенной системы налогообложения доходы в рамках применения специального налогового режима \"Автоматизированная упрощенная система налогообложения\";\n\n2) 7 процентов - в случае выполнения одного из следующих условий:\n\nза календарный год, предшествующий календарному году, начиная с которого организация или индивидуальный предприниматель переходит на упрощенную систему налогообложения, у указанных организации или индивидуального предпринимателя сумма доходов, определяемых в порядке, установленном главой 23, 25 или 261 настоящего Кодекса, а также в порядке, установленном Федеральным законом от 25 февраля 2022 года № 17-ФЗ \"О проведении эксперимента по установлению специального налогового режима \"Автоматизированная упрощенная система налогообложения\", не превысила в совокупности 450 миллионов рублей, и такие организация или индивидуальный предприниматель не имеет оснований для освобождения от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога;\n\nза предшествующий налоговый период по налогу, уплачиваемому в связи с применением упрощенной системы налогообложения, у организации или индивидуального предпринимателя сумма доходов, определяемых в соответствии со статьей 34615 и подпунктами 1 и 3 пункта 1 статьи 34625 настоящего Кодекса, не превысила в совокупности 450 миллионов рублей, и такие организация или индивидуальный предприниматель не имеет оснований для освобождения от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога;\n\nв течение налогового периода по налогу, уплачиваемому в связи с применением упрощенной системы налогообложения, организация или индивидуальный предприниматель начинает исполнять обязанности налогоплательщика, связанные с исчислением и уплатой налога, либо утрачивает право на применение налоговой ставки в размере 5 процентов.\n\nЕсли в течение налогового периода по налогу, уплачиваемому в связи с применением упрощенной системы налогообложения, у организации или индивидуального предпринимателя сумма доходов, определяемых в соответствии со статьей 34615 и подпунктами 1 и 3 пункта 1 статьи 34625 настоящего Кодекса, превысила в совокупности 450 миллионов рублей, такие организация или индивидуальный предприниматель начиная с 1-го числа месяца, в котором имело место указанное превышение, утрачивает право на применение налоговых ставок в размере 5 процентов и 7 процентов. При этом в целях определения указанной величины доходов учитываются в том числе полученные в календарном году применения упрощенной системы налогообложения доходы в рамках применения специального налогового режима \"Автоматизированная упрощенная система налогообложения\".\n\n(Дополнение пунктом - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nОрганизации и индивидуальные предприниматели, применяющие налоговые ставки, установленные пунктом 8 настоящей статьи, не применяют налоговые ставки, установленные пунктом 1 (за исключением случаев налогообложения по данной ставке операций, указанных в подпунктах 1 - 12, 21 - 31, 7 и 11 пункта 1), пунктами 2 и 3 настоящей статьи.\n\nНалоговые ставки, установленные пунктом 8 настоящей статьи, не применяются при ввозе товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, а также при осуществлении операций, указанных в пунктах 1, 3 - 6 статьи 161 настоящего Кодекса.\n\nПри определении величин размера доходов, предусмотренных пунктом 8 настоящей статьи, не учитываются доходы в виде положительной курсовой разницы, предусмотренные пунктом 11 части второй статьи 250 настоящего Кодекса, и доходы в виде субсидий, признаваемые в порядке, установленном пунктом 41 статьи 271 настоящего Кодекса, при безвозмездной передаче в государственную и (или) муниципальную собственность имущества (имущественных прав).\n\nВ случае, если индивидуальный предприниматель применял одновременно общий режим налогообложения и патентную систему налогообложения либо систему налогообложения для сельскохозяйственных товаропроизводителей (единый сельскохозяйственный налог) и патентную систему налогообложения, при определении величин размера доходов, указанных в пункте 8 настоящей статьи, учитываются доходы по обоим указанным налоговым режимам.\n\nВ случае, если индивидуальный предприниматель применяет (применял) в календарном году упрощенную систему налогообложения, патентную систему налогообложения, специальный налоговый режим \"Автоматизированная упрощенная система налогообложения\", при определении величины доходов, указанных в пункте 8 настоящей статьи, учитываются доходы по всем указанным специальным налоговым режимам.\n\nУказанные в пункте 8 настоящей статьи величины размера доходов подлежат индексации в порядке, предусмотренном пунктом 2 статьи 34612 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 12.07.2024 № 176-ФЗ)","article_title":"Статья 164. Налоговые ставки","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"16cedd345fd3dfd3aea8f0fa29e8811278d03d8fe37ba2f41a0d19a3b0d477f0"},{"code_id":"NK_RF_2","article_number":"165","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.08.2018 № 302-ФЗ)\n\n1) в случае вывоза в таможенной процедуре экспорта товаров, указанных в абзаце втором подпункта 1 пункта 1 статьи 164 настоящего Кодекса, в налоговые органы представляется реестр в электронной форме, содержащий сведения из декларации на товары, по которой осуществлен выпуск товаров в таможенной процедуре экспорта и товары были вывезены за пределы таможенной территории Евразийского экономического союза, в том числе через территорию государства - члена Евразийского экономического союза, а также сведения из контракта налогоплательщика с иностранным лицом на реализацию товаров, вывозимых за пределы таможенной территории Евразийского экономического союза, либо сведения из контракта налогоплательщика с российской организацией на поставку товаров ее филиалу, представительству, отделению, бюро, конторе, агентству или другому обособленному подразделению, находящемуся за пределами таможенной территории Евразийского экономического союза, с учетом следующих особенностей:\n\nпри вывозе товаров трубопроводным транспортом или по линиям электропередачи в указанном в абзаце первом настоящего подпункта реестре указываются сведения из полной декларации на товары, по которой осуществлен выпуск товаров в таможенной процедуре экспорта;\n\nпри вывозе реализуемых товаров в пункт назначения, находящийся на континентальном шельфе Российской Федерации и (или) в исключительной экономической зоне Российской Федерации либо в российской части (российском секторе) дна Каспийского моря, в целях использования их в деятельности, связанной с добычей углеводородного сырья на морском месторождении углеводородного сырья, в указанном в абзаце первом настоящего подпункта реестре указываются сведения из контракта налогоплательщика с налогоплательщиком, осуществляющим деятельность по поиску, оценке, разведке и (или) разработке указанного месторождения, на поставку (реализацию) товаров за пределы таможенной территории Евразийского экономического союза;\n\n2) при вывозе из Российской Федерации припасов в налоговые органы представляются:\n\nреестр в электронной форме, содержащий сведения из декларации на товары, используемой при таможенном декларировании припасов, вывезенных с территории российского порта (аэропорта), открытого для международного сообщения, за пределы таможенной территории Евразийского экономического союза, а также сведения из контракта налогоплательщика с иностранным лицом на поставку таких припасов за пределы таможенной территории Евразийского экономического союза, - при вывозе припасов з\n\nа пределы таможенной территории Евразийского экономического союза;\n\nреестр в электронной форме, содержащий сведения из транспортных, товаросопроводительных и (или) иных документов, включающих в том числе сведения о количестве припасов, подтверждающих вывоз припасов из Российской Федерации воздушными и морскими судами, судами смешанного (река - море) плавания, а также сведения из контракта налогоплательщика с иностранным лицом на поставку припасов за пределы территории Российской Федерации, - при вывозе припасов в государство - член Евразийского экономического союза;\n\nреестр в электронной форме, содержащий сведения из контракта налогоплательщика с налогоплательщиком, осуществляющим деятельность по поиску, оценке, разведке и (или) разработке указанного месторождения, на поставку припасов за пределы таможенной территории Евразийского экономического союза, сведения из транспортных, товаросопроводительных и (или) иных документов, подтверждающих вывоз припасов в пункт назначения, находящийся на континентальном шельфе Российской Федерации и (или) в исключительной экономической зоне Российской Федерации либо в российской части (российском секторе) дна Каспийского моря, а также сведения из декларации на товары, используемой при таможенном декларировании припасов, - при вывозе реализуемых припасов в целях использования их в деятельности, связанной с добычей углеводородного сырья на морском месторождении углеводородного сырья;\n\n3) в случае, если товары помещены под таможенную процедуру свободной таможенной зоны, в налоговые органы представляются:\n\nконтракт (копия контракта), заключенный с резидентом особой экономической зоны, территории опережающего развития, свободного порта Владивосток, Арктической зоны Российской Федерации или с участником свободной экономической зоны;\n\nкопия свидетельства о регистрации лица в качестве резидента особой экономической зоны, выданного федеральным органом исполнительной власти, уполномоченным осуществлять функции по управлению особыми экономическими зонами, или копия свидетельства о регистрации лица в качестве резидента территории опережающего развития, выданного управляющей компанией, определенной Правительством Российской Федерации в целях осуществления функций по управлению территориями опережающего развития, или копия свидетельства о регистрации лица в качестве резидента свободного порта Владивосток, выданного уполномоченным федеральным органом исполнительной власти, осуществляющим на территории Дальневосточного федерального округа функции по координации деятельности по реализации государственных программ и федеральных целевых программ, или копия свидетельства о регистрации лица в качестве резидента Арктической зоны Российской Федерации, выданного управляющей компанией, определенной Правительством Российской Федерации в целях осуществления функций по управлению Арктической зоной Российской Федерации, или копия свидетельства о включении участника в реестр участников свободной экономической зоны, выданного уполномоченным Правительством Российской Федерации федеральным органом исполнительной власти;\n\nдекларация на товары (ее копия) с отметками таможенного органа о выпуске товаров в соответствии с таможенной процедурой свободной таможенной зоны;\n\n4) в случае вывоза в таможенной процедуре реэкспорта товаров, указанных в абзацах четвертом и пятом подпункта 1 пункта 1 статьи 164 настоящего Кодекса, в налоговые органы представляется реестр в электронной форме, содержащий сведения из деклараций на товары, свидетельствующих о помещении товаров, ранее ввезенных в Российскую Федерацию, под таможенные процедуры свободной таможенной зоны, свободного склада или переработки на таможенной территории, и сведения из деклараций на товары, свидетельствующих о помещении под таможенную процедуру реэкспорта указанных товаров и (или) товаров, которые изготовлены (получены) из товаров, помещенных под таможенные процедуры свободной таможенной зоны, свободного склада, или которые являются продуктами переработки, отходами и (или) остатками, полученными (образовавшимися) в результате переработки товаров, помещенных под таможенную процедуру переработки на таможенной территории, а также сведения из контракта на реализацию товаров для вывоза за пределы таможенной территории Евразийского экономического союза;\n\n5) в случае, если товары пересылаются в международных почтовых отправлениях, в налоговые органы представляется реестр в электронной форме, содержащий сведения из деклараций на товары либо из таможенных деклараций CN 23;\n\n6) в случае, если товары, при таможенном декларировании которых используется декларация на товары для экспресс-грузов, доставляются перевозчиком в качестве экспресс-груза, в налоговые органы представляется реестр в электронной форме, содержащий сведения из декларации на товары для экспресс-грузов;\n\n7) при реализации товаров, предусмотренных подпунктом 12 пункта 1 статьи 164 настоящего Кодекса, для подтверждения обоснованности применения налоговой ставки 0 процентов в налоговые органы представляются реестр в электронной форме, содержащий сведения из декларации на товары, поданной в российский таможенный орган, по которой ранее товары были вывезены в таможенной процедуре экспорта с территории Российской Федерации на территорию иностранного государства, сведения из документа (счета) на оплату товаров, содержащего в том числе сведения о количестве товаров и об их стоимости, сведения из договора аренды склада (помещения) или иного документа, подтверждающего право пользования налогоплательщиком на территории иностранного государства складом (помещением), с которого отгружаются товары, предусмотренные подпунктом 12 пункта 1 статьи 164 настоящего Кодекса, а также сведения об адресе доставки таких товаров покупателю - физическому лицу. (Дополнение подпунктом - Федеральный закон от 28.04.2023 № 173-ФЗ)\n\n(Пункт в редакции  Федерального закона от 19.12.2022 № 549-ФЗ)\n\n11. При реализации товаров, указанных в подпункте 29 пункта 1 статьи 164 настоящего Кодекса, для подтверждения обоснованности применения налоговой ставки 0 процентов и налоговых вычетов в налоговые органы представляются следующие документы:\n\n1) контракт (копия контракта) налогоплательщика на поставку товаров в пункт назначения, находящийся за пределами территории Российской Федерации и иных территорий, находящихся под ее юрисдикцией. Если контракт содержит сведения, составляющие государственную тайну, вместо копии полного текста контракта представляется выписка из него, содержащая информацию, необходимую для проведения налогового контроля (в частности, информацию об условиях поставки, о сроках, цене, виде продукции);\n\n2) копии транспортных, товаросопроводительных или иных документов, подтверждающих вывоз товаров в пункт назначения, находящийся за пределами территории Российской Федерации и иных территорий, находящихся под ее юрисдикцией.\n\n(Дополнение пунктом - Федеральный закон от 30.09.2013 № 268-ФЗ)\n\nПри вывозе товаров в таможенной процедуре экспорта (реэкспорта) судами через морские порты, в том числе в случае, если погрузка товаров и их таможенное оформление осуществляются вне региона деятельности пограничного таможенного органа, для подтверждения вывоза товаров за пределы таможенной территории Евразийского экономического союза налогоплательщиком в налоговые органы представляются следующие документы:\n\nкопия поручения на отгрузку грузов с указанием порта разгрузки. В случае вывоза уловов водных биологических ресурсов и произведенной из них рыбной и иной продукции, доставленных на территорию Российской Федерации в соответствии с законодательством о рыболовстве и сохранении водных биологических ресурсов без выгрузки на сухопутную территорию Российской Федерации, такая копия поручения налогоплательщиком в налоговые органы не представляется;\n\nкопия коносамента, морской накладной или любого иного подтверждающего факт приема к перевозке товара документа, в котором в графе \"Порт разгрузки\" указано место, находящееся за пределами таможенной территории Евразийского экономического союза.\n\nПри вывозе товаров в таможенной процедуре экспорта (реэкспорта) воздушным транспортом для подтверждения вывоза товаров за пределы таможенной территории Евразийского экономического союза в налоговые органы налогоплательщиком представляется копия международной авиационной грузовой накладной с указанием аэропорта разгрузки, находящегося за пределами таможенной территории Евразийского экономического союза.\n\nПри вывозе товаров в таможенной процедуре экспорта (реэкспорта) железнодорожным транспортом истребуемые транспортные документы могут представляться налогоплательщиком в налоговый орган в электронной форме по формату, утвержденному совместно федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, и федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области таможенного дела. Указанные документы представляются в налоговый орган в электронной форме по телекоммуникационным каналам связи через оператора электронного документооборота, являющегося российской организацией и соответствующего требованиям, утвержденным федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nПри вывозе реализуемых товаров в целях использования их в деятельности, связанной с добычей углеводородного сырья на морском месторождении углеводородного сырья, в налоговые органы налогоплательщиком представляются копии транспортных, товаросопроводительных и (или) иных документов, подтверждающих вывоз товаров в пункт назначения, находящийся на континентальном шельфе Российской Федерации и (или) в исключительной экономической зоне Российской Федерации либо в российской части (российском секторе) дна Каспийского моря. (Дополнение абзацем - Федеральный закон от 19.12.2022 № 549-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 03.08.2018 № 302-ФЗ)\n\nТранспортные (товаросопроводительные) и (или) иные документы, подтверждающие перемещение товаров с территории Российской Федерации на территорию государства - члена Евразийского экономического союза, а также договоры (контракты), заключенные с налогоплательщиком другого государства - члена Евразийского экономического союза или с налогоплательщиком государства, не являющегося членом Евразийского экономического союза, на основании которых осуществляется экспорт товаров, могут не представляться одновременно с налоговой декларацией в случае представления налогоплательщиком в налоговый орган в электронной форме перечня заявлений о ввозе товаров и уплате косвенных налогов, составленных по форме, предусмотренной международным межведомственным договором (далее в настоящем Кодексе - заявление о ввозе товаров и уплате косвенных налогов). (В редакции  Федерального закона от 19.12.2022 № 549-ФЗ)\n\nНалоговый орган, проводящий камеральную налоговую проверку (налоговый мониторинг), вправе выборочно истребовать у налогоплательщика документы, предусмотренные абзацем вторым настоящего пункта, сведения из которых включены в перечень заявлений о ввозе товаров и уплате косвенных налогов, реквизиты которого указаны в представленном в электронной форме перечне заявлений о ввозе товаров и уплате косвенных налогов. Истребуемые документы (их копии) представляются налогоплательщиком в течение 30 календарных дней с даты получения соответствующего требования налогового органа. (В редакции Федерального закона от 29.12.2020 № 470-ФЗ)\n\nВ случае, если по требованию налогового органа налогоплательщиком не представлены документы, указанные в абзаце втором настоящего пункта, сведения из которых включены в заявление о ввозе товаров и уплате косвенных налогов, реквизиты которого указаны в представленном в электронной форме перечне заявлений о ввозе товаров и уплате косвенных налогов, обоснованность применения налоговой ставки 0 процентов в соответствующей части считается неподтвержденной.\n\n(Дополнение пунктом - Федеральный закон от 03.08.2018 № 302-ФЗ)\n\n1) договор комиссии, договор поручения либо агентский договор (копии договоров) налогоплательщика с комиссионером, поверенным или агентом;\n\n2) документы, предусмотренные подпунктом 3 пункта 1 настоящей статьи.\n\n(Дополнение пунктом - Федеральный закон от 19.12.2022 № 549-ФЗ)\n\n1) копия соглашения между Правительством Российской Федерации и правительством соответствующего иностранного государства об урегулировании задолженности бывшего СССР (Российской Федерации) или в счет предоставления государственных кредитов иностранным государствам; (В редакции Федерального закона от 29.12.2000 № 166-ФЗ)\n\n2) копия соглашения между Министерством финансов Российской Федерации и налогоплательщиком о финансировании поставок товаров в счет погашения государственной задолженности или в счет предоставления государственных кредитов иностранным государствам; (В редакции Федерального закона от 29.12.2000 № 166-ФЗ)\n\n3) (Подпункт утратил силу - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\n4) декларация на товары (ее копия) с отметками российского таможенного органа, осуществившего выпуск товаров в таможенной процедуре экспорта, и российского таможенного органа места убытия, через который товар был вывезен с территории Российской Федерации и иных территорий, находящихся под ее юрисдикцией (далее в настоящей статье - российский таможенный орган места убытия), с учетом следующих особенностей:\n\nпри вывозе товаров в таможенной процедуре экспорта трубопроводным транспортом или по линиям электропередачи представляется полная декларация на товары (ее копия) с отметками российского таможенного органа, подтверждающими факт помещения товаров под таможенную процедуру экспорта;\n\nпри вывозе товаров в таможенной процедуре экспорта через границу Российской Федерации с государством - членом Евразийского экономического союза, на которой таможенное оформление отменено, в третьи страны представляется декларация на товары (ее копия) с отметками таможенного органа Российской Федерации, производившего таможенное оформление указанного вывоза товаров.\n\n(Подпункт в редакции  Федерального закона от 19.12.2022 № 549-ФЗ)\n\nекса, для подтверждения обоснованности применения налоговой ставки 0 процентов налогоплательщиками представляются в налоговые органы следующие документы:\n\n1) контракт (копия контракта) налогоплательщика с иностранным или российским лицом на оказание указанных услуг. В случае вывоза товаров с территории Российской Федерации на территорию государства - члена Евразийского экономического союза или ввоза товаров на территорию Российской Федерации с территории государства - члена Евразийского экономического союза и заключения налогоплательщиком контракта на оказание указанных услуг с лицом, не осуществляющим внешнеэкономическую сделку с перевозимыми товарами, помимо указанного контракта (копии контракта) представляется копия контракта этого лица с лицом, осуществляющим внешнеэкономическую сделку с перевозимыми товарами;\n\n2) копии транспортных, товаросопроводительных и (или) иных документов, подтверждающих вывоз товаров за пределы территории Российской Федерации (ввоз товаров на территорию Российской Федерации), если иное не предусмотрено подпунктом 3 настоящего пункта.\n\nПри вывозе товаров за пределы таможенной территории Евразийского экономического союза, в том числе через территорию государства - члена Евразийского экономического союза, морским или речным судном, судном смешанного (река - море) плавания в налоговые органы представляются:\n\nкопия поручения на отгрузку товаров с указанием порта разгрузки;\n\nкопия коносамента, морской накладной или любого иного подтверждающего факт приема товара к перевозке документа, в котором в графе \"Порт разгрузки\" указано место, находящееся за пределами таможенной территории Евразийского экономического союза.\n\nВ случае, если погрузка товаров и их таможенное оформление при вывозе товаров морским судном или речным судном, судном смешанного (река - море) плавания осуществляются вне региона деятельности российского таможенного органа места убытия, в налоговые органы представляются:\n\nкопия поручения на отгрузку товаров с указанием порта разгрузки, находящегося за пределами территории Российской Федерации;\n\nкопия коносамента, морской накладной или любого иного подтверждающего факт приема товара к перевозке документа, в котором в графе \"Порт разгрузки\" указано место, находящееся за пределами таможенной территории Евразийского экономического союза.\n\nПри ввозе товаров морским, речным судном, судном смешанного (река - море) плавания с территории иностранного государства, не являющегося членом Евразийского экономического союза, в том числе через территорию государства - члена Евразийского экономического союза, в налоговые органы представляется копия коносамента, морской накладной или любого иного документа, подтверждающего факт приема товара к перевозке, в котором в графе \"Порт погрузки\" указано место, находящееся за пределами таможенной территории Евразийского экономического союза.\n\nПри вывозе товаров за пределы территории Евразийского экономического союза, в том числе через территорию государства - члена Евразийского экономического союза, воздушным транспортом в налоговые органы представляется копия грузовой накладной с указанием аэропорта разгрузки (перегрузки), находящегося за пределами таможенной территории Евразийского экономического союза.\n\nПри ввозе товаров воздушным транспортом с территории иностранного государства, не являющегося членом Евразийского экономического союза, в том числе через территорию государства - члена Евразийского экономического союза, в налоговые органы представляется копия грузовой накладной с указанием аэропорта погрузки (перегрузки), находящегося за пределами таможенной территории Евразийского экономического союза.\n\nПри вывозе товаров автомобильным транспортом за пределы таможенной территории Евразийского экономического союза, в том числе через территорию государства - члена Евразийского экономического союза, в налоговые органы представляется копия транспортного, товаросопроводительного и (или) иного документа, на основании которого товар был вывезен за пределы территории Российской Федерации.\n\nПри ввозе товаров автомобильным транспортом с территории иностранного государства, не являющегося членом Евразийского экономического союза, в том числе через территорию государства - члена Евразийского экономического союза, в налоговые органы представляется копия транспортного, товаросопроводительного и (или) иного документа, на основании которого товар был ввезен на территорию Российской Федерации.\n\nВ случае вывоза товаров с территории Российской Федерации на территорию государства - члена Евразийского экономического союза или ввоза товаров на территорию Российской Федерации с территории государства - члена Евразийского экономического союза морскими, речными судами, судами смешанного (река - море) плавания, воздушными судами, железнодорожным транспортом и автотранспортными средствами в налоговые органы представляются копии транспортных, товаросопроводительных и (или) иных документов с указанием места разгрузки или места погрузки (станции назначения или станции отправления), находящихся на территории другого государства - члена Евразийского экономического союза.\n\nПри выполнении работ (оказании услуг) по перевозке и (или) транспортировке углеводородного сырья из пункта отправления, находящегося на континентальном шельфе Российской Федерации и (или) в исключительной экономической зоне Российской Федерации либо в российской части (российском секторе) дна Каспийского моря, в пункт назначения, находящийся за пределами территории Российской Федерации и иных территорий, находящихся под ее юрисдикцией, в налоговые органы представляются копии транспортных, товаросопроводительных или иных документов, подтверждающих факт вывоза углеводородного сырья из пункта отправления, находящегося на континентальном шельфе Российской Федерации и (или) в исключительной экономической зоне Российской Федерации либо в российской части (российском секторе) дна Каспийского моря, в пункт назначения, находящийся за пределами территории Российской Федерации и иных территорий, находящихся под ее юрисдикцией;\n\n3) при вывозе товаров железнодорожным транспортом за пределы таможенной территории Евразийского экономического союза, в том числе через территорию государства - члена Евразийского экономического союза, в налоговые органы представляется реестр в электронной форме, содержащий сведения о регистрационном номере декларации на товары и сведения из перевозочного документа, на основании которого товары были вывезены за пределы таможенной территории Евразийского экономического союза.\n\nПри ввозе товаров железнодорожным транспортом с территории иностранного государства, не являющегося государством - членом Евразийского экономического союза, в том числе через территорию государства - члена Евразийского экономического союза, в налоговые органы представляется реестр в электронной форме, содержащий сведения о регистрационном номере транзитной декларации либо декларации на товары (если товары при ввозе на таможенную территорию Евразийского экономического союза не помещались под таможенную процедуру таможенного транзита), а также сведения из перевозочного документа, на основании которого товары были ввезены на территорию Российской Федерации.\n\nПри организации и осуществлении перевозки товаров железнодорожным транспортом от места их прибытия на территорию Российской Федерации (от портов или пограничных станций, расположенных на территории Российской Федерации) до станции назначения, расположенной на территории Российской Федерации, в налоговый орган представляются:\n\nреестр в электронной форме, содержащий сведения из транспортных, товаросопроводительных и (или) иных документов, указанных в подпункте 2 настоящего пункта, на основании которых товары прибыли в порт, а также сведения из перевозочного документа, на основании которого товары были перевезены от порта до станции назначения;\n\nреестр в электронной форме, содержащий сведения из перевозочного документа, на основании которого товары прибыли на пограничную станцию и были перевезены до станции назначения, а также сведения о регистрационном номере транзитной декларации либо декларации на товары (если товары при ввозе на таможенную территорию Евразийского экономического союза не помещались под таможенную процедуру таможенного транзита).\n\n(Дополнение пунктом - Федеральный закон от 27.11.2010 № 309-ФЗ) (В редакции  Федерального закона от 22.04.2024 № 92-ФЗ)\n\n1) контракт (копия контракта) налогоплательщика на выполнение указанных работ (оказание указанных услуг) с лицом, указанным в абзацах шестом - восьмом подпункта 22 пункта 1 статьи 164 настоящего Кодекса;\n\n2) (Подпункт утратил силу - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\n3) полная таможенная декларация (ее копия) с отметками российского таможенного органа (если российский таможенный орган регистрирует таможенную декларацию) или таможенного органа государства - члена Таможенного союза (если таможенная декларация регистрируется указанным таможенным органом), осуществившего выпуск товара (нефти, нефтепродуктов), либо документы (их копии), подтверждающие факт оказания услуг по транспортировке нефти и нефтепродуктов трубопроводным транспортом (в случае, если таможенное декларирование не предусмотрено таможенным законодательством Таможенного союза); (В редакции Федерального закона от 21.11.2011 № 330-ФЗ)\n\n4) копии транспортных, товаросопроводительных и (или) иных документов, подтверждающих вывоз товаров за пределы территории Российской Федерации. Положения настоящего подпункта применяются с учетом особенностей, предусмотренных подпунктом 3 пункта 31 настоящей статьи. (В редакции Федерального закона от 03.08.2018 № 302-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 27.11.2010 № 309-ФЗ)\n\n1) контракт (копия контракта) налогоплательщика с иностранным или российским лицом на оказание указанных услуг;\n\n2) (Подпункт утратил силу - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\n3) полная таможенная декларация (ее копия) с отметками российского таможенного органа о совершенных таможенных операциях (в случае, если таможенное декларирование производится) либо документы (их копии), подтверждающие факт оказания услуг по организации транспортировки (услуг по транспортировке в случае ввоза на территорию Российской Федерации) природного газа трубопроводным транспортом (в случае, если таможенное декларирование не производится).\n\n(Дополнение пунктом - Федеральный закон от 27.11.2010 № 309-ФЗ)\n\n33-1. При реализации услуг, предусмотренных подпунктом 23-1 пункта 1 статьи 164 настоящего Кодекса, для подтверждения обоснованности применения налоговой ставки 0 процентов налогоплательщиками представляются в налоговые органы следующие документы:\n\n1) контракт (копия контракта) налогоплательщика с иностранным или российским лицом на оказание указанных услуг;\n\n2) полная таможенная декларация (ее копия) с отметками российского таможенного органа о совершенных таможенных операциях либо документы (их копии), подтверждающие факт оказания услуг, указанных в подпункте 23-1 пункта 1 статьи 164 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\n1) контракт (копия контракта) налогоплательщика с российским лицом на оказание указанных услуг;\n\n2) копии актов об оказании услуг по передаче электрической энергии и (или) иных документов, подтверждающих передачу электрической энергии, поставка которой осуществляется из электроэнергетической системы Российской Федерации в электроэнергетические системы иностранных государств;\n\n3) (Подпункт утратил силу - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 27.11.2010 № 309-ФЗ)\n\n1) контракт (копия контракта) налогоплательщика с иностранным или российским лицом на выполнение указанных работ (оказание указанных услуг);\n\n2) (Подпункт утратил силу - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\n3) копии транспортных, товаросопроводительных и (или) иных документов, подтверждающих вывоз товаров за пределы территории Российской Федерации и иных территорий, находящихся под ее юрисдикцией (ввоз товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией), с учетом следующих особенностей.\n\nПри вывозе товаров морским или речным судном, судном смешанного (река - море) плавания в налоговые органы представляются:\n\nкопия поручения на отгрузку товаров с указанием порта разгрузки, находящегося за пределами территории Российской Федерации; (В редакции  Федерального закона от 19.12.2022 № 549-ФЗ)\n\nкопия коносамента, морской накладной или любого иного подтверждающего факт приема к перевозке товара документа, в котором в графе \"Порт разгрузки\" указано место, находящееся за пределами территории Российской Федерации.\n\nПри ввозе товаров морским или речным судном, судном смешанного (река - море) плавания налогоплательщиком представляется в налоговые органы копия коносамента, морской накладной или любого иного подтверждающего факт перевозки товара документа, в котором в графе \"Порт погрузки\" указано место, находящееся за пределами территории Российской Федерации, с отметкой таможенного органа, действующего в пункте пропуска.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2010 № 309-ФЗ)\n\n1) контракт (копия контракта) налогоплательщика с иностранным или российским лицом на выполнение работ (оказание услуг);\n\n2) (Подпункт утратил силу - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\n3) копии таможенных деклараций, свидетельствующих о помещении иностранных товаров, ввозимых на территорию Российской Федерации, под таможенную процедуру переработки на таможенной территории, а также копии таможенных деклараций, свидетельствующих о помещении продуктов переработки, вывезенных с территории Российской Федерации за пределы таможенной территории Таможенного союза, под таможенную процедуру реэкспорта, завершающую действие таможенной процедуры переработки на таможенной территории; (В редакции Федерального закона от 29.12.2014 № 452-ФЗ)\n\n4) копии транспортных, товаросопроводительных и (или) иных документов, подтверждающих ввоз иностранных товаров на территорию Российской Федерации для совершения операций по их переработке и вывоз продуктов переработки с территории Российской Федерации за пределы таможенной территории Таможенного союза с учетом особенностей, предусмотренных подпунктом 3 пункта 31 настоящей статьи. (В редакции Федерального закона от 29.12.2014 № 452-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 27.11.2010 № 309-ФЗ)\n\n1) контракт (копия контракта) налогоплательщика на оказание услуг;\n\n2) реестр в электронной форме, содержащий сведения о регистрационном номере декларации на товары (в отношении товаров, помещенных под таможенную процедуру экспорта или реэкспорта), а также сведения из перевозочного документа, на основании которого товары, помещенные под таможенную процедуру экспорта или реэкспорта, перевозились железнодорожным транспортом из пункта отправления в пункт назначения, находящиеся на территории Российской Федерации.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2010 № 309-ФЗ) (В редакции  Федерального закона от 22.04.2024 № 92-ФЗ)\n\n1) контракт (копия контракта) налогоплательщика с иностранным или российским лицом на выполнение указанных работ (оказание указанных услуг);\n\n2) (Подпункт утратил силу - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\n3) копии транспортных, товаросопроводительных или иных документов, подтверждающих вывоз товаров за пределы территории Российской Федерации, с учетом следующих особенностей.\n\nВ случае осуществления перевозки (транспортировки) товаров, вывозимых в таможенной процедуре экспорта (реэкспорта), организациями внутреннего водного транспорта в пределах территории Российской Федерации из пункта отправления до пункта выгрузки или перегрузки (перевалки) на морские суда, суда смешанного (река - море) плавания или иные виды транспорта в налоговые органы представляются: (В редакции Федерального закона от 27.11.2017 № 350-ФЗ)\n\nкопия поручения на отгрузку товаров на речное судно (в случае, если таможенное оформление груза осуществляется в порту выгрузки или перевалки, данный документ не представляется); (В редакции  Федерального закона от 19.12.2022 № 549-ФЗ)\n\nкопия коносамента, морской накладной или любого иного документа речного судна, подтверждающего факт приема товара к перевозке, в котором в графе \"Порт разгрузки\" указано место перевалки (выгрузки), находящееся на территории Российской Федерации;\n\nкопия поручения на отгрузку товаров на морское судно, в которое производилась перевалка (погрузка) груза, с указанием порта разгрузки, находящегося за пределами территории Российской Федерации, и с приложением перечня транспортных средств (речных судов), доставивших груз; (В редакции  федеральных законов от 27.11.2017 № 350-ФЗ, от 19.12.2022 № 549-ФЗ, от 22.04.2024 № 92-ФЗ)\n\nкопия коносамента, морской накладной или любого иного документа морского судна, подтверждающего факт приема товара к перевозке, в котором в графе \"Порт разгрузки\" указано место, находящееся за пределами территории Российской Федерации.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2010 № 309-ФЗ)\n\n38-1. При реализации работ (услуг), предусмотренных подпунктом 28-1 пункта 1 статьи 164 настоящего Кодекса, для подтверждения обоснованности применения налоговой ставки 0 процентов налогоплательщиком в налоговый орган представляются следующие документы:\n\n1) контракт (копия контракта) налогоплательщика на выполнение указанных работ (оказание указанных услуг);\n\n2) копия поручения на отгрузку товаров на морское судно, на котором товар перевозился в место назначения, находящееся за пределами территории Российской Федерации, с приложением перечня транспортных средств (морских судов), доставивших груз; (В редакции  Федерального закона от 19.12.2022 № 549-ФЗ)\n\n3) копия коносамента, морской накладной или любого иного документа, подтверждающего факт приема товаров к перевозке, в котором в графе \"Порт разгрузки\" указано место выгрузки или перегрузки (перевалки), находящееся на территории Росси\n\nйской Федерации;\n\n4) копия коносамента, морской накладной или любого иного документа, подтверждающего факт приема товаров к дальнейшей перевозке, в котором в графе \"Порт разгрузки\" указано место, находящееся за пределами территории Российской Федерации.\n\n(Дополнение пунктом - Федеральный закон от 13.07.2020 № 195-ФЗ)\n\nуказание маршрута перевозки;\n\nподтверждение таможенных органов о том, что место прибытия товаров на территорию Российской Федерации и место убытия товаров с территории Российской Федерации совпадают.\n\nВ случае выборочного истребования налоговым органом отдельных документов, включенных в реестр, копии указанных документов представляются налогоплательщиками в течение 30 календарных дней с даты получения соответствующего требования налогового органа.\n\n(Дополнение пунктом - Федеральный закон от 29.11.2014 № 382-ФЗ)\n\nПеречень сведений, которые указываются в реестре, форма и порядок его заполнения, а также формат и порядок представления реестра в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nВ состав сведений, которые указываются в реестре, включается информация о размере налоговой базы, к которой налогоплательщиком применяется налоговая ставка 0 процентов.\n\nРеестр представляется в налоговый орган в электронной форме по телекоммуникационным каналам связи через оператора электронного документооборота, являющегося российской организацией и соответствующего требованиям, утвержденным федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nНалоговый орган, проводящий камеральную налоговую проверку (налоговый мониторинг), в случае выявления несоответствия сведений, указанных в реестре, сведениям, имеющимся у налогового органа, вправе истребовать у налогоплательщика документы, подтверждающие сведения, по которым выявлены несоответствия. (В редакции Федерального закона от 29.12.2020 № 470-ФЗ)\n\nВ случае истребования налоговым органом документов, сведения из которых включены в реестр, копии указанных документов представляются налогоплательщиком в течение 20 календарных дней с даты получения соответствующего требования налогового органа.\n\nВ случае, если по требованию налогового органа налогоплательщиком не представлены копии документов, сведения из которых включены в реестр, обоснованность применения налоговой ставки 0 процентов в соответствующей части считается неподтвержденной.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2017 № 341-ФЗ)\n\n1) контракт (копия контракта) налогоплательщика на оказание указанных услуг;\n\n2) копия коносамента, морской накладной и (или) любого иного документа, подтверждающего факт приема товара к перевозке, в котором в графе \"Порт разгрузки\" указано место, находящееся за пределами территории Российской Федерации;\n\n3) копия коносамента, морской накладной и (или) любого иного документа, подтверждающего факт приема товаров к перевозке, в котором в графе \"Порт разгрузки\" указано место выгрузки или перегрузки (перевалки), находящееся на территории Российской Федерации (в случае перевозки товаров до пункта выгрузки или перегрузки (перевалки) на территории Российской Федерации в целях их дальнейшего вывоза из Российской Федерации);\n\n4) копия поручения на отгрузку товаров на морское судно, на котором товар перевозился в место назначения, находящееся за пределами территории Российской Федерации, с приложением перечня транспортных средств (морских судов), доставивших груз. (В редакции  Федерального закона от 19.12.2022 № 549-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 13.07.2020 № 195-ФЗ)\n\n1) контракт (копия контракта) налогоплательщика с иностранным или российским лицом на выполнение указанных работ (оказание указанных услуг);\n\n2) (Подпункт утратил силу - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\n3) таможенная декларация (ее копия) с отметками российских таможенных органов места прибытия и места убытия товара, через которые товар был ввезен на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, и вывезен за пределы территории Российской Федерации и иных территорий, находящихся под ее юрисдикцией, с учетом особенностей, предусмотренных подпунктом 3 пункта 1 настоящей статьи; (В редакции Федерального закона от 19.07.2011 № 245-ФЗ)\n\n4) копии транспортных, товаросопроводительных и (или) иных документов, подтверждающих ввоз товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, и вывоз товаров за пределы территории Российской Федерации и иных территорий, находящихся под ее юрисдикцией, в соответствии с подпунктом 3 пункта 1 статьи 164 настоящего Кодекса. Положения настоящего подпункта применяются с учетом особенностей, предусмотренных подпунктом 3 пункта 31 настоящей статьи. (В редакции федеральных законов от 19.07.2011 № 245-ФЗ; от 03.08.2018 № 302-ФЗ)\n\nконтракт (копия контракта) налогоплательщика с иностранным или российским лицом на оказание указанных услуг;\n\nкопии перевозочных документов, оформленных при перевозках с участием железнодорожного транспорта, с указанием наименований или кодов станций отправления, наименований или кодов входных и выходных российских пограничных и (или) припортовых железнодорожных станций, наименований или кодов станций назначения. (В редакции Федерального закона от 29.09.2019 № 322-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\nреестр перевозочных документов, оформляемых при перевозках товаров в международном сообщении, с указанием в нем номеров перевозочных документов, наименований или кодов входных и выходных пограничных и (или) припортовых железнодорожных станций, стоимости работ (услуг), а также номеров деклараций на товары, по которым такие товары помещались под таможенную процедуру экспорта, реэкспорта или таможенного транзита. (В редакции  Федерального закона от 19.12.2022 № 549-ФЗ)\n\nВ случае выборочного истребования налоговым органом отдельных перевозочных документов, включенных в реестры, копии указанных документов представляются указанными в абзаце первом настоящего пункта перевозчиками в течение 30 календарных дней с даты получения соответствующего требования налогового органа. Перевозочные документы, включенные в реестр, должны свидетельствовать о перевозке товаров, помещенных под таможенную процедуру экспорта, реэкспорта или таможенного транзита. (В редакции  федеральных законов от 28.02.2006 № 28-ФЗ, от 27.07.2006 № 137-ФЗ, от 27.11.2010 № 309-ФЗ, от 29.12.2014 № 452-ФЗ, от 27.11.2017 № 350-ФЗ, от 19.12.2022 № 549-ФЗ)\n\nПри реализации указанными в абзаце первом настоящего пункта перевозчиками услуг, предусмотренных подпунктом 4 пункта 1 статьи 164 настоящего Кодекса, для подтверждения обоснованности применения налоговой ставки 0 процентов (или особенностей налогообложения) и налоговых вычетов в налоговые органы представляются реестры единых перевозочных документов, оформляемых при перевозках пассажиров и багажа в прямом международном сообщении, определяющих путь следования с указанием в них номеров перевозочных документов, пунктов отправления и назначения, даты оказания услуг, стоимости услуг по перевозке пассажиров и багажа, или иные документы, предусмотренные договорами, заключенными указанными в абзаце первом настоящего пункта перевозчиками с железными дорогами иностранных государств, или международными договорами Российской Федерации. (В редакции Федерального закона от 29.12.2014 № 452-ФЗ)\n\n(Пункт в редакции Федерального закона от 22.07.2005 № 119-ФЗ)\n\nВ случае выборочного истребования налоговым органом отдельных перевозочных документов, включенных в реестр, копии указанных документов представляются в течение 30 календарных дней с даты получения соответствующего требования налогового органа;\n\n(Дополнение пунктом - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\n1) документ (его копия), подтверждающий ввод объекта туристской индустрии в эксплуатацию (в том числе после реконструкции);\n\n2) договор (копия договора) на оказание услуг по предоставлению в аренду или пользование на ином праве объекта туристской индустрии.\n\n(Дополнение пунктом - Федеральный закон от 26.03.2022 № 67-ФЗ)\n\nПри реализации услуг, указанных в абзаце третьем подпункта 19 пункта 1 статьи 164 настоящего Кодекса, для подтверждения обоснованности применения налоговой ставки 0 процентов и налоговых вычетов в налоговые органы также представляется документ (его копия), подтверждающий ввод объекта туристской индустрии в эксплуатацию (в том числе после реконструкции).\n\n(Дополнение пунктом - Федеральный закон от 26.03.2022 № 67-ФЗ)\n\nПри реализации услуг по перевозке пассажиров и багажа, предусмотренных подпунктом 94 пункта 1 статьи 164 настоящего Кодекса, через комиссионера, поверенного либо агента по договору комиссии, договору поручения либо агентскому договору для подтверждения обоснованности применения налоговой ставки 0 процентов и налоговых вычетов в налоговые органы наряду с реестром перевозочных (проездных) документов по перевозке пассажиров и багажа, указанным в абзаце первом настоящего пункта, представляется договор комиссии, договор поручения либо агентский договор (копия договора) налогоплательщика с комиссионером, поверенным либо агентом.\n\nПри реализации услуг по организации перевозок пассажиров и багажа, предусмотренных подпунктом 94 пункта 1 статьи 164 настоящего Кодекса, для подтверждения обоснованности применения налоговой ставки 0 процентов и налоговых вычетов в налоговые органы представляются:\n\nдоговор или контракт (копия договора или контракта) налогоплательщика на оказание услуг по организации перевозок пассажиров и багажа;\n\nакт или иные документы (их копии), подтверждающие оказание услуг по организации перевозок пассажиров и багажа.\n\n(Дополнение пунктом - Федеральный закон от 23.07.2025 № 227-ФЗ)\n\n1) (Подпункт утратил силу - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\n2) реестр единых международных перевозочных документов по перевозке пассажиров и багажа, определяющих маршрут перевозки с указанием в нем номеров перевозочных документов, пунктов отправления и назначения, даты оказания услуг, стоимости услуг по перевозке пассажиров и багажа. (В редакции федеральных законов от 29.12.2000 № 166-ФЗ; от 29.12.2014 № 452-ФЗ)\n\nВ случае выборочного истребования налоговым органом отдельных перевозочных документов, включенных в реестр, копии указанных документов представляются в течение 30 календарных дней с даты получения соответствующего требования налогового органа.\n\n(Дополнение пунктом - Федеральный закон от 04.06.2014 № 151-ФЗ)\n\nВ случае выборочного истребования налоговым органом отдельных перевозочных документов, включенных в реестр, копии указанных документов представляются в течение 30 календарных дней с даты получения соответствующего требования налогового органа.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2017 № 353-ФЗ)\n\n1) договор или контракт (копия договора или контракта) налогоплательщика с иностранным или российским лицом на оказание услуг;\n\n2) акт или иные документы (их копии), подтверждающие оказание услуг и содержащие указание на маршрут перевозки с указанием пунктов отправления и назначения.\n\n(Дополнение пунктом - Федеральный закон от 25.12.2018 № 493-ФЗ)\n\nснованности применения налоговой ставки 0 процентов и налоговых вычетов в налоговые органы представляются следующие документы:\n\n1) договор или контракт (копия договора или контракта) налогоплательщика с иностранными или российскими лицами на реализацию (поставку) товаров, выполнение работ, оказание услуг;\n\n2) (Подпункт утратил силу - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\n3) акт или иные документы (их копии), подтверждающие реализацию (поставку) товаров, выполнение работ, оказание услуг;\n\n4) сертификат (его копия), выданный (выданная) в соответствии с законодательством Российской Федерации на реализуемую космическую технику, включая космические объекты, объекты космической инфраструктуры (товары), а в случае реализации космической техники, включая космические объекты, объекты космической инфраструктуры (товары) военного и двойного назначения, - удостоверение (его копия), выданное (выданная) военным представительством Министерства обороны Российской Федерации. (В редакции Федерального закона от 25.11.2009 № 281-ФЗ)\n\n(Пункт в редакции Федерального закона от 04.11.2007 № 255-ФЗ)\n\n1) инвестиционное соглашение (его копия);\n\n2) контракт (его копия) налогоплательщика на выполнение работ (оказание услуг), заключенный после заключения инвестиционного соглашения, указанного в подпункте 22 пункта 1 статьи 164 настоящего Кодекса;\n\n3) акт или иные документы (их копии), подтверждающие выполнение работ (оказание услуг).\n\n(Дополнение пунктом - Федеральный закон от 24.06.2023 № 261-ФЗ)\n\n1) контракт (копия контракта) на реализацию драгоценных металлов; (В редакции федеральных законов от 29.12.2000 № 166-ФЗ; от 27.06.2018 № 159-ФЗ)\n\n2) документы (их копии), подтверждающие передачу драгоценных металлов Государственному фонду драгоценных металлов и драгоценных камней Российской Федерации, фондам драгоценных металлов и драгоценных камней субъектов Российской Федерации, Центральному банку Российской Федерации, банкам. (В редакции федеральных законов от 29.12.2000 № 166-ФЗ; от 29.05.2002 № 57-ФЗ; от 27.06.2018 № 159-ФЗ)\n\n1) контракт (копия контракта) на реализацию необработанных природных алмазов и (или) обработанных природных алмазов;\n\n2) документы (их копии), подтверждающие передачу необработанных природных алмазов Государственному фонду драгоценных металлов и драгоценных камней Российской Федерации, фондам драгоценных металлов и драгоценных камней субъектов Российской Федерации, Центральному банку Российской Федерации, банкам, иным организациям и (или) передачу обработанных природных алмазов Государственному фонду драгоценных металлов и драгоценных камней Российской Федерации, фондам драгоценных металлов и драгоценных камней субъектов Российской Федерации, Центральному банку Российской Федерации, банкам.\n\n(Дополнение пунктом - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n1) документы (их копии), подтверждающие передачу драгоценных металлов физическим лицам;\n\n2) решение (его копия) о выпуске цифровых прав, включающих одновременно цифровые финансовые активы и утилитарные цифровые права, удостоверяющих право требовать передачи драгоценных металлов в слитках;\n\n3) отчет (его копия) оператора информационной системы, содержащий сведения о погашении записей о цифровых правах, указанных в подпункте 2 настоящего пункта, в информационной системе такого оператора в результате их выкупа путем передачи драгоценных металлов в слитках.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nЕсли по истечении 180 календарных дней налогоплательщик не представил указанные в абзаце первом настоящего пункта документы (их копии) либо реестры, операции по реализации товаров, предусмотренные подпунктами 1 и 8 пункта 1 статьи 164 настоящего Кодекса, подлежат налогообложению по налоговым ставкам, предусмотренным пунктами 2 и 3 статьи 164 настоящего Кодекса. Если впоследствии налогоплательщик представляет в налоговые органы документы (их копии) либо реестры, обосновывающие применение налоговой ставки в размере 0 процентов, уплаченные суммы налога подлежат вычету в порядке и на условиях, которые предусмотрены статьями 171 и 172 настоящего Кодекса.\n\nДокументы, указанные в пункте 5 настоящей статьи, представляются налогоплательщиками для подтверждения обоснованности применения налоговой ставки 0 процентов при выполнении работ (оказании услуг), предусмотренных подпунктами 3 и 9 пункта 1 статьи 164 настоящего Кодекса, в срок не позднее 180 календарных дней с даты помещения товаров под таможенную процедуру экспорта, реэкспорта или таможенного транзита. Если по истечении 180 календарных дней налогоплательщик не представил документы, указанные в пункте 5 настоящей статьи, операции по реализации работ (услуг) подлежат налогообложению по налоговой ставке 20 процентов. Если впоследствии налогоплательщик представляет в налоговые органы документы, обосновывающие применение налоговой ставки 0 процентов, уплаченные суммы налога подлежат вычету в порядке и на условиях, которые предусмотрены статьями 171 и 172 настоящего Кодекса.\n\nПоложения настоящего пункта не распространяются на налогоплательщиков, освобожденных от исполнения обязанностей налогоплательщика в соответствии со статьей 145 настоящего Кодекса.\n\nДокументы (их копии) либо реестры, указанные в пунктах 31 - 39, 4 и 14 настоящей статьи, представляются налогоплательщиками для подтверждения обоснованности применения налоговой ставки 0 процентов в следующем порядке:\n\nдокументы, указанные в пункте 31 настоящей статьи, представляются в налоговый орган в срок не позднее 180 календарных дней с даты оформления поручения на отгрузку товаров, предусмотренного абзацами третьим и шестым подпункта 2 пункта 31 настоящей статьи, либо с даты оформления документов, предусмотренных абзацами восьмым - десятым, тринадцатым и четырнадцатым подпункта 2 пункта 31 настоящей статьи, либо с даты составления документов, предусмотренных абзацами одиннадцатым и двенадцатым подпункта 2 пункта 31 настоящей статьи;\n\nреестр, указанный в абзаце первом подпункта 3 пункта 31 настоящей статьи, и контракт (копия контракта), предусмотренный подпунктом 1 пункта 31 настоящей статьи, представляются в налоговый орган в срок не позднее 180 календарных дней с даты оформления транспортных, товаросопроводительных и (или) иных документов, на основании которых товары были вывезены за пределы таможенной территории Евразийского экономического союза;\n\nреестр, указанный в абзаце втором подпункта 3 пункта 31 настоящей статьи, и контракт (копия контракта), предусмотренный подпунктом 1 пункта 31 настоящей статьи, представляются в налоговый орган в срок не позднее 180 календарных дней с даты помещения товаров под таможенную процедуру при ввозе на таможенную территорию Евразийского экономического союза;\n\nреестр, указанный в абзаце четвертом подпункта 3 пункта 31 настоящей статьи, и контракт (копия контракта), предусмотренный подпунктом 1 пункта 31 настоящей статьи, представляются в налоговый орган в срок не позднее 180 календарных дней с даты оформления перевозочного документа, на основании которого товары были перевезены от порта, расположенного на территории Российской Федерации, до станции назначения, расположенной на территории Российской Федерации;\n\nреестр, указанный в абзаце пятом подпункта 3 пункта 31 настоящей статьи, и контракт (копия контракта), предусмотренный подпунктом 1 пункта 31 настоящей статьи, представляются в налоговый орган в срок не позднее 180 календарных дней с даты оформления перевозочного документа, на основании которого товары были перевезены от места прибытия на территорию Российской Федерации до станции назначения, расположенной на территории Российской Федерации;\n\nдокументы, указанные в пункте 32 настоящей статьи, представляются в налоговый орган в срок не позднее 180 календарных дней с даты выпуска товаров по таможенной декларации, указанной в подпункте 3 пункта 32 настоящей статьи, либо с даты составления документа, подтверждающего факт оказания услуг по транспортировке нефти и нефтепродуктов трубопроводным транспортом (в случае, если таможенное декларирование не предусмотрено правом Евразийского экономического союза);\n\nдокументы, указанные в пункте 33 настоящей статьи, представляются в налоговый орган в срок не позднее 180 календарных дней с даты выпуска товаров по полной таможенной декларации (в случае, если таможенное декларирование производится) либо с даты оформления документов, подтверждающих факт оказания услуг по организации транспортировки (услуг по транспортировке в случае ввоза на территорию Российской Федерации) природного газа трубопроводным транспортом (в случае, если таможенное декларирование не производится);\n\nдокументы, указанные в пункте 34 настоящей статьи, представляются в налоговый орган в срок не позднее 180 календарных дней с даты составления актов, указанных в подпункте 2 пункта 34 настоящей статьи;\n\nдокументы, указанные в пункте 35 настоящей статьи, представляются в налоговый орган в срок не позднее 180 календарных дней с даты оформления поручения на отгрузку товаров, предусмотренного абзацем третьим подпункта 3 пункта 35 настоящей статьи, либо с даты отметки, проставленной таможенными органами на документах, предусмотренных абзацем пятым подпункта 3 пункта 35 настоящей статьи;\n\nдокументы, указанные в пункте 36 настоящей статьи, представляются в налоговый орган в срок не позднее 180 календарных дней с даты выпуска продуктов переработки, вывозимых за пределы территории Российской Федерации на основании таможенных деклараций, предусмотренных подпунктом 3 пункта 36 настоящей статьи;\n\nдокументы и реестры, указанные в пункте 37 настоящей статьи, представляются в налоговый орган в срок не позднее 180 календарных дней с даты помещения товаров под таможенную процедуру экспорта или реэкспорта;\n\nдокументы, указанные в пунктах 38 и 38-1 настоящей статьи, представляются в налоговый орган в срок не позднее 180 календарных дней с даты оформления поручения на отгрузку товаров на морское судно, предусмотренного абзацем пятым подпункта 3 пункта 38 или подпунктом 2 пункта 38-1 настоящей статьи;\n\nдокументы, указанные в пункте 39 настоящей статьи, представляются в налоговый орган в срок не позднее 180 календарных дней с даты отметки таможенного органа, подтверждающей убытие товаров с территории Российской Федерации;\n\nдокументы, указанные в пункте 4 настоящей статьи, представляются в налоговый орган в срок не позднее 180 календарных дней с даты отметки, проставленной таможенными органами на таможенной декларации, предусмотренной подпунктом 3 пункта 4 настоящей статьи, подтверждающей вывоз товаров за пределы территории Российской Федерации;\n\nдокументы, указанные в пункте 14 настоящей статьи, представляются в налоговый орган в срок не позднее 180 календарных дней с даты составления документов, указанных в подпункте 2 пункта 14 настоящей статьи.\n\nЕсли по истечении 180 календарных дней налогоплательщик не представил указанные в абзацах шестом - двадцатом настоящего пункта документы и (или) реестры, операции по реализации работ (услуг), предусмотренных подпунктами 21 - 28-1, 210, 3 и 12 пункта 1 статьи 164 настоящего Кодекса, подлежат налогообложению по ставке, предусмотренной пунктом 3 статьи 164 настоящего Кодекса.\n\nЕсли впоследствии налогоплательщик представляет в налоговый орган документы и (или) реестры, обосновывающие применение налоговой ставки 0 процентов, уплаченные суммы налога подлежат вычету в порядке и на условиях, которые предусмотрены статьями 171 и 172 настоящего Кодекса.\n\nДокументы, указанные в пунктах 41 и 51 настоящей статьи, представляются в налоговый орган в срок не позднее 180 календарных дней с даты проставления на перевозочном документе календарного штемпеля пограничной железнодорожной станции (при перемещении товаров, порожнего железнодорожного подвижного состава или контейнеров с территории Российской Федерации через выходные железнодорожные пограничные станции) или календарного штемпеля станции назначения (при перемещении товаров, порожнего железнодорожного подвижного состава или контейнеров с территории Российской Федерации через выходные припортовые железнодорожные станции) при выполнении работ (оказании услуг), указанных в подпункте 31 и абзаце третьем подпункта 91 пункта 1 статьи 164 настоящего Кодекса, либо с даты проставления календарного штемпеля станции отправления при выполнении работ (оказании услуг), указанных в абзаце втором подпункта 91 пункта 1 статьи 164 настоящего Кодекса. Если по истечении 180 календарных дней налогоплательщик не представил указанные документы, операции по реализации работ (услуг), предусмотренных подпунктами 31 и 91 пункта 1 статьи 164 настоящего Кодекса, подлежат налогообложению по ставке, предусмотренной пунктом 3 статьи 164 настоящего Кодекса.\n\nЕсли впоследствии налогоплательщик представляет в налоговый орган документы, обосновывающие применение налоговой ставки 0 процентов, уплаченные суммы налога подлежат вычету в порядке и на условиях, которые предусмотрены статьями 171 и 172 настоящего Кодекса.\n\nДокументы, указанные в пункте 11 настоящей статьи, представляются в налоговый орган в срок не позднее 180 календарных дней с даты оформления транспортных, товаросопроводительных и (или) иных документов с указанием пункта назначения, находящегося за пределами территории Российской Федерации и иных территорий, находящихся под ее юрисдикцией. Если по истечении 180 календарных дней налогоплательщик не представил указанные документы, операции по реализации товаров, предусмотренные подпунктом 29 пункта 1 статьи 164 настоящего Кодекса, подлежат налогообложению по ставке, предусмотренной пунктом 3 статьи 164 настоящего Кодекса.\n\nЕсли впоследствии налогоплательщик представит в налоговый орган документы, обосновывающие применение налоговой ставки 0 процентов, уплаченные суммы налога подлежат вычету в порядке и на условиях, которые предусмотрены статьями 171 и 172 настоящего Кодекса.\n\nДокументы, указанные в пункте 311 настоящей статьи, представляются в налоговый орган в срок не позднее 180 календарных дней с даты оформления поручения на отгрузку товаров. Если по истечении 180 календарных дней налогоплательщик не представил указанные документы, операции по реализации работ (услуг), предусмотренных подпунктом 213 пункта 1 статьи 164 настоящего Кодекса, подлежат налогообложению по ставке, предусмотренной пунктом 3 статьи 164 настоящего Кодекса.\n\nЕсли впоследствии налогоплательщик представляет в налоговый орган документы, обосновывающие применение налоговой ставки 0 процентов, уплаченные суммы налога подлежат вычету в порядке и на условиях, которые предусмотрены статьями 171 и 172 настоящего Кодекса.\n\n(Пункт в редакции  Федерального закона от 22.04.2024 № 92-ФЗ)\n\nЕсли разрешение на погрузку товаров и (или) вывоз товаров морским или речным судном, судном смешанного (река - море) плавания за пределы территории Евразийского экономического союза не подтверждаются сведениями (информацией), полученными (полученной) по запросу налогового органа от федерального органа исполнительной власти, уполномоченного по контролю и надзору в области таможенного дела, обоснованность применения налоговой ставки 0 процентов в отношении операций по реализации работ (услуг) в соответствующей части считается неподтвержденной.\n\n(Дополнение пунктом - Федеральный закон от 19.12.2022 № 549-ФЗ)\n\n10. Документы (в том числе реестры и перечень заявлений о ввозе товаров и уплате косвенных налогов), указанные в настоящей статье, представляются налогоплательщиками для обоснования применения налоговой ставки 0 процентов одновременно с представлением налоговой декларации, если и\n\nное не предусмотрено настоящей статьей. (В редакции Федерального закона от 03.08.2018 № 302-ФЗ)\n\nВ случае, если контракты (договоры), в том числе истребованные налоговым органом, ранее были представлены налогоплательщиком в налоговый орган для обоснования применения налоговой ставки 0 процентов в соответствии с настоящей статьей за предыдущие налоговые периоды или обоснования освобождения от уплаты акциза (возмещения сумм акциза) в соответствии с пунктом 7 статьи 198 настоящего Кодекса, их повторное представление не требуется. Вместо представления указанных в настоящем абзаце документов налогоплательщик представляет в налоговые органы уведомление с указанием реквизитов документа, которым (приложением к которому) были представлены указанные документы, и наименования налогового органа, в который они были представлены. (Дополнение абзацем - Федеральный закон от 03.08.2018 № 302-ФЗ) (В редакции  Федерального закона от 19.12.2022 № 549-ФЗ)\n\nПорядок определения суммы налога, относящейся к товарам (работам, услугам), имущественным правам, приобретенным для производства и (или) реализации товаров (работ, услуг), операции по реализации которых облагаются по налоговой ставке 0 процентов, устанавливается принятой налогоплательщиком учетной политикой для целей налогообложения. Положения настоящего абзаца не распространяются на операции по реализации товаров, указанных в подпункте 1 (за исключением сырьевых товаров), подпунктах 12 и 6 пункта 1 статьи 164 настоящего Кодекса. (В редакции  Федерального закона от 28.04.2023 № 173-ФЗ)\n\nВ целях настоящей главы к сырьевым товарам относятся минеральные продукты, продукция химической промышленности и связанных с ней других отраслей промышленности, древесина и изделия из нее, древесный уголь, жемчуг, драгоценные и полудрагоценные камни, драгоценные металлы, недрагоценные металлы и изделия из них. Коды видов товаров, перечисленных в настоящем абзаце, в соответствии с единой Товарной номенклатурой внешнеэкономической деятельности Евразийского экономического союза определяются Правительством Российской Федерации.\n\n(Пункт в редакции Федерального закона от 30.05.2016 № 150-ФЗ)\n\n13. При реализации товаров, предусмотренных подпунктом 10 пункта 1 статьи 164 настоящего Кодекса, для подтверждения обоснованности применения налоговой ставки 0 процентов и налоговых вычетов в налоговые органы представляются следующие документы:\n\n1) контракт (копия контракта) на реализацию судна, заключенный налогоплательщиком с заказчиком и содержащий условие об обязательной регистрации построенного судна в Российском международном реестре судов в течение 90 календарных дней с момента перехода права собственности на судно от налогоплательщика к заказчику, либо иной договор (копия договора) на реализацию судна, заключенный в 2022 году налогоплательщиком-продавцом, являющимся российской лизинговой компанией, с контрагентом; (В редакции  федеральных законов от 27.07.2006 № 137-ФЗ, от 29.09.2019 № 324-ФЗ, от 14.07.2022 № 323-ФЗ)\n\n2) выписка из реестра строящихся судов с указанием, что по окончании строительства судно подлежит регистрации в Российском международном реестре судов (не представляется при реализации судна российской лизинговой компанией); (В редакции  Федерального закона от 14.07.2022 № 323-ФЗ)\n\n3) документы, подтверждающие факт перехода права собственности на судно от налогоплательщика к заказчику или от российской лизинговой компании контрагенту; (В редакции  Федерального закона от 14.07.2022 № 323-ФЗ)\n\n4) (Подпункт утратил силу - Федеральный закон от 07.11.2011 № 305-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 20.12.2005 № 168-ФЗ)\n\n14. При реализации работ (услуг), предусмотренных подпунктом 12 пункта 1 статьи 164 настоящего Кодекса, для подтверждения обоснованности применения налоговой ставки 0 процентов и налоговых вычетов в налоговые органы представляются следующие документы:\n\n1) контракт (копия контракта) налогоплательщика с иностранным или российским лицом на оказание указанных услуг;\n\n2) копии транспортных, товаросопроводительных и (или) иных документов, подтверждающих вывоз товаров за пределы территории Российской Федерации или ввоз товаров на территорию Российской Федерации, с учетом следующих особенностей:\n\nпри вывозе товаров за пределы территории Российской Федерации морским судном или судном смешанного (река - море) плавания в налоговые органы представляется копия коносамента, морской накладной или любого иного подтверждающего факт приема товаров к перевозке документа, в котором в графе \"Порт выгрузки\" указано место выгрузки, расположенное за пределами территории Российской Федерации;\n\nпри ввозе товаров морским судном или судном смешанного (река - море) плавания с территории иностранного государства на территорию Российской Федерации в налоговые органы представляется копия коносамента, морской накладной или любого иного подтверждающего факт приема товаров к перевозке документа, в котором в графе \"Порт погрузки\" указано место погрузки, расположенное за пределами территории Российской Федерации, а в графе \"Порт выгрузки\" указано место выгрузки, расположенное на территории Российской Федерации.\n\n(Дополнение пунктом - Федеральный закон от 07.11.2011 № 305-ФЗ)\n\nреестры деклараций на товары (полных деклараций на товары), предусмотренных абзацем четвертым подпункта 3 пункта 1, подпунктом 4 пункта 3, подпунктом 3 пункта 32, подпунктом 3 пункта 33, подпунктом 3 пункта 36, подпунктом 3 пункта 4 настоящей статьи, с указанием в них регистрационных номеров соответствующих деклараций вместо копий указанных деклараций;\n\nреестры документов, подтверждающих факт оказания услуг по транспортировке нефти и нефтепродуктов трубопроводным транспортом, предусмотренных подпунктом 3 пункта 32 настоящей статьи, документов, подтверждающих факт оказания услуг по организации транспортировки (услуг по транспортировке в случае ввоза в Российскую Федерацию) природного газа трубопроводным транспортом, предусмотренных подпунктом 3 пункта 33 настоящей статьи (в случае, если таможенное декларирование не предусмотрено правом Евразийского экономического союза или не производится), вместо копий указанных документов;\n\nреестр полных деклараций на товары либо документов, подтверждающих факт оказания услуг по транспортировке нефти и нефтепродуктов трубопроводным транспортом, а также транспортных, товаросопроводительных и (или) иных документов, предусмотренных подпунктами 3 и 4 пункта 32 настоящей статьи, вместо копий указанных документов;\n\nреестры деклараций на товары (полных деклараций на товары), а также транспортных, товаросопроводительных и (или) иных документов, предусмотренных подпунктами 3 и 4 пункта 36, подпунктами 3 и 4 пункта 4 настоящей статьи, вместо копий указанных документов;\n\nреестры транспортных, товаросопроводительных и (или) иных документов, предусмотренных подпунктом 2 пункта 31, подпунктом 3 пункта 35, подпунктом 3 пункта 38, подпунктами 2 - 4 пункта 38-1, подпунктами 2 - 4 пункта 311, подпунктом 2 пункта 14 настоящей статьи, вместо копий указанных документов; (В редакции  Федерального закона от 23.07.2025 № 227-ФЗ)\n\nреестр перевозочных документов, предусмотренных пунктом 41 настоящей статьи, вместо копий указанных документов;\n\nреестр перевозочных, товаросопроводительных или иных документов, предусмотренных пунктом 39 настоящей статьи, в электронной форме вместо реестра указанных документов на бумажном носителе;\n\nреестры перевозочных документов, предусмотренные пунктами 5, 51, 53, 56, 6, 61, 62, 64 настоящей статьи, в электронной форме вместо реестров указанных документов на бумажном носителе. (В редакции  Федерального закона от 23.07.2025 № 227-ФЗ)\n\nРеестры, предусмотренные абзацами вторым - девятым настоящего пункта, подпунктами 1, 2, 4 - 7 пункта 1, пунктами 2, 21, подпунктом 3 пункта 31, подпунктом 2 пункта 37 настоящей статьи, представляются в налоговый орган по установленному формату в электронной форме по телекоммуникационным каналам связи, в том числе через оператора электронного документооборота, являющегося российской организацией и соответствующего требованиям, утвержденным федеральным органом исполнительной власти, уполномоченным по контролю и надзору в сфере налогов и сборов.\n\nНалоговый орган, проводящий камеральную налоговую проверку (налоговый мониторинг), вправе:\n\nвыборочно истребовать у налогоплательщика документы, сведения из которых включены в предусмотренные абзацем девятым настоящего пункта реестры (за исключением реестра перевозочных документов, предусмотренного абзацем третьим пункта 5 настоящей статьи);\n\nистребовать у налогоплательщика документы, сведения из которых включены в реестры, предусмотренные абзацами вторым - восьмым настоящего пункта, подпунктами 1, 2, 4 - 7 пункта 1, пунктами 2, 21, подпунктом 3 пункта 31, подпунктом 2 пункта 37 настоящей статьи, в электронной форме, в реестр перевозочных документов, предусмотренный абзацем третьим пункта 5 настоящей статьи, которые содержат сведения, не включенные в указанный в пункте 18 настоящей статьи перечень сведений, передаваемых федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области таможенного дела;\n\nистребовать у налогоплательщика документы, подтверждающие сведения, по которым выявлены несоответствия, в случае выявления несоответствия сведений, полученных налоговым органом в соответствии с пунктом 17 настоящей статьи, сведениям, содержащимся в реестрах, предусмотренных абзацами вторым - восьмым настоящего пункта, подпунктами 1, 2, 4 - 7 пункта 1, пунктами 2, 21, подпунктом 3 пункта 31, подпунктом 2 пункта 37 настоящей статьи, в представленном налогоплательщиком в электронной форме реестре перевозочных документов, предусмотренном абзацем третьим пункта 5 настоящей статьи.\n\nВ случае истребования налоговым органом документов, сведения из которых включены в реестры, предусмотренные абзацами вторым - девятым настоящего пункта, подпунктами 1, 2, 4 - 7 пункта 1, пунктами 2, 21, подпунктом 3 пункта 31, подпунктом 2 пункта 37 настоящей статьи, копии указанных документов представляются налогоплательщиком в течение 30 календарных дней с даты получения соответствующего требования налогового органа. Представленные документы должны соответствовать требованиям, указанным в настоящей статье, если иное не предусмотрено настоящим пунктом.\n\nВ случае, если истребуемый контракт, сведения о котором указаны в реестре, предусмотренном подпунктом 1, 2 или 4 пункта 1 либо пунктом 2 или 21 настоящей статьи, содержит сведения, составляющие государственную тайну, вместо копии полного текста контракта представляется выписка из него, содержащая информацию, необходимую для проведения мероприятий налогового контроля (в частности, информацию об условиях поставки, о сроках, цене, виде продукции).\n\nВ случае, если по требованию налогового органа налогоплательщиком не представлены указанные в настоящей статье документы, сведения из которых включены в реестры, предусмотренные абзацами вторым - девятым настоящего пункта, подпунктами 1, 2, 4 - 7 пункта 1, пунктами 2, 21, подпунктом 3 пункта 31, подпунктом 2 пункта 37 настоящей статьи, обоснованность применения налоговой ставки 0 процентов в соответствующей части считается неподтвержденной.\n\nПри реализации товаров, вывезенных в таможенной процедуре экспорта (реэкспорта) за пределы таможенной территории Евразийского экономического союза, копии истребуемых деклараций на товары, сведения из которых включены в представленные в электронной форме в налоговый орган соответствующие реестры, могут представляться в налоговый орган без соответствующих отметок российских таможенных органов места убытия.\n\nПри реализации услуг, предусмотренных абзацами четвертым, пятым, десятым подпункта 21 пункта 1 статьи 164 настоящего Кодекса, оказываемых при организации перевозок товаров железнодорожным транспортом и (или) для осуществления таких перевозок, копии истребуемых документов, сведения из которых включены в представленные в электронной форме в налоговый орган соответствующие реестры, могут представляться в налоговый орган без соответствующих отметок российских таможенных органов.\n\nВ случае, если вывоз товаров в соответствии с таможенной процедурой экспорта (реэкспорта) за пределы таможенной территории Евразийского экономического союза по документам, представленным налогоплательщиком, не подтверждается сведениями, полученными в соответствии с пунктом 17 настоящей статьи от федерального органа исполнительной власти, уполномоченного по контролю и надзору в области таможенного дела, об этом сообщается налогоплательщику. Налогоплательщик вправе в течение 15 календарных дней со дня получения сообщения налогового органа представить необходимые пояснения и любые имеющиеся у налогоплательщика документы, подтверждающие вывоз указанных товаров.\n\nЕсли вывоз товаров в соответствии с таможенной процедурой экспорта (реэкспорта) за пределы таможенной территории Евразийского экономического союза не подтверждается сведениями (информацией), полученными от федерального органа исполнительной власти, уполномоченного по контролю и надзору в области таможенного дела, по запросу федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, обоснованность применения налоговой ставки 0 процентов в отношении операций по реализации товаров в соответствующей части считается неподтвержденной. Запрос федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области таможенного дела, должен содержать пояснения и документы, если они были представлены налогоплательщиком в налоговый орган в соответствии с абзацем двадцатым настоящего пункта.\n\n(Дополнение пунктом - Федеральный закон от 29.12.2014 № 452-ФЗ) (В редакции  Федерального закона от 22.04.2024 № 92-ФЗ)\n\n1) контракт (копия контракта) на реализацию гражданского воздушного судна либо на выполнение работ (оказание услуг) по строительству гражданского воздушного судна, подлежащего государственной регистрации (зарегистрированного) в Государственном реестре гражданских воздушных судов Российской Федерации, заключенный налогоплательщиком, реализующим это гражданское воздушное судно, с покупателем или заключенный налогоплательщиком, выполняющим работы (оказывающим услуги) по строительству гражданского воздушного судна и передающим его заказчику;\n\n2) документы (копии документов), подтверждающие передачу гражданского воздушного судна, подлежащего государственной регистрации (зарегистрированного) в Государственном реестре гражданских воздушных судов Российской Федерации, налогоплательщиком покупателю (заказчику).\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 324-ФЗ)\n\n1) контракт (копия контракта) на реализацию авиационных двигателей, запасных частей и комплектующих изделий, предназначенных для строительства, ремонта и (или) модернизации гражданских воздушных судов;\n\n2) документы (копии документов), подтверждающие целевое назначение товаров, выданные федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере промышленного и оборонно-промышленного комплексов, по форме и в порядке, которые установлены указанным федеральным органом исполнительной власти; (В редакции  Федерального закона от 14.11.2023 № 538-ФЗ)\n\n3) документы (копии документов), подтверждающие передачу авиационных двигателей, запасных частей и комплектующих изделий, предназначенных для строительства, ремонта и (или) модернизации гражданских воздушных судов, налогоплательщиком покупателю.\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 324-ФЗ)\n\n1) договор аренды либо договор лизинга гражданского воздушного судна, подлежащего государственной регистрации (зарегистрированного) в Государственном реестре гражданских воздушных судов Российской Федерации, заключенный арендодателем (лизингодателем) с арендатором (лизингополучателем);\n\n2) документ (копия документа), подтверждающий передачу арендодателем (лизингодателем) арендатору (лизингополучателю) гражданского воздушного судна, подлежащего государственной регистрации (зарегистрированного) в Государственном реестре гражданских воздушных судов Российской Федерации.\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 324-ФЗ)\n\n1) государственный (муниципальный) контракт налогоплательщика с государственным или муниципальным заказчиком Российской Федерации либо соглашение с государственным органом (государственным учреждением), трансграничным концерном, государственным концерном, государственным унитарным предприятием Донецкой Народной Республики, Луганской Народной Республики, Запорожской области или Херсонской области (копия государственного (муниципального) контракта либо указанного соглашения) на поставку товаров, заключенные до 5 октября 2022 года включительно, либо договор (копия договора), не являющийся указанными государственным (муниципальным) контрактом или соглашением, налогоплательщика на поставку товаров, заключенный до 31 декабря 2022 года включительно с юридическим лицом, созданным на территории Донецкой Народной Республики, Луганской Народной Республики, Запорожской области или Херсонской области до дня принятия указанных территорий в Российскую Федерацию и образования в составе Российской Федерации новых субъектов (индивидуальным предпринимателем, зарегистрированным на одной из указанных территорий до дня принятия в Российскую Федерацию указанных территорий и образования в составе Российской Федерации новых субъектов), либо с иностранным лицом;\n\n2) копии транспортных, товаросопроводительных и (или) иных документов, подтверждающих перевозку (доставку) товаров в пункт назначения, находящийся на территории Донецкой Народной Республики, Луганской Народной Республики, Запорожской области или Херсонской области;\n\n3) документы, подтверждающие поступление на открытый в банке счет налогоплательщика денежных средств за\n\nтовары по договору, указанному в подпункте 1 настоящего пункта, в полном объеме.\n\n(Дополнение пунктом - Федеральный закон от 21.11.2022 № 443-ФЗ)\n\n1) договор (копия договора) на оказание услуг по перевозке товаров;\n\n2) копии транспортных, товаросопроводительных и (или) иных документов, подтверждающих перевозку товаров с территории (на территорию) Донецкой Народной Республики, Луганской Народной Республики, Запорожской области или Херсонской области;\n\n3) документы, подтверждающие поступление на открытый в банке счет налогоплательщика (на счет налогоплательщика, открытый в организации, зарегистрированной на территории Донецкой Народной Республики, Луганской Народной Республики, Запорожской области или Херсонской области и обладающей в соответствии с законодательством Донецкой Народной Республики или Луганской Народной Республики, с нормативными правовыми актами Запорожской области или Херсонской области правом на осуществление банковских операций) денежных средств в полном объеме в счет оплаты оказанных услуг по перевозке товаров.\n\n(Дополнение пунктом - Федеральный закон от 21.11.2022 № 443-ФЗ)\n\n1) контракт (копия контракта) на реализацию беспилотных гражданских воздушных судов с максимальной взлетной массой от 0,15 килограмма до 30 килограммов, заключенный налогоплательщиком, реализующим эти беспилотные гражданские воздушные суда, с покупателем;\n\n2) выписка из реестра российской промышленной продукции, подтверждающая включение сведений о реализуемых беспилотных гражданских воздушных судах с максимальной взлетной массой от 0,15 килограмма до 30 килограммов в указанный реестр;\n\n3) документы (копии документов), подтверждающие передачу беспилотных гражданских воздушных судов с максимальной взлетной массой от 0,15 килограмма до 30 килограммов налогоплательщиком покупателю.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2025 № 297-ФЗ)\n\n1) контракт (копия контракта) на реализацию двигателей, запасных частей и комплектующих изделий, предназначенных для строительства, ремонта и (или) модернизации беспилотных гражданских воздушных судов с максимальной взлетной массой от 0,15 килограмма до 30 килограммов;\n\n2) документы (копии документов), подтверждающие целевое назначение товаров, выданные федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере промышленного и оборонно-промышленного комплексов, по форме и в порядке, которые установлены указанным федеральным органом исполнительной власти;\n\n3) документы (копии документов), подтверждающие передачу двигателей, запасных частей и комплектующих изделий, предназначенных для строительства, ремонта и (или) модернизации беспилотных гражданских воздушных судов с максимальной взлетной массой от 0,15 килограмма до 30 килограммов, налогоплательщиком покупателю.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2025 № 297-ФЗ)\n\nВ состав сведений, которые указываются в реестрах, предусмотренных настоящей статьей, включается информация о размере налоговой базы, к которой налогоплательщиком применяется налоговая ставка 0 процентов. (В редакции  Федерального закона от 19.12.2022 № 549-ФЗ)\n\nВ состав сведений, которые указываются в реестре, предусмотренном подпунктом 6 пункта 1 настоящей статьи, включаются также сведения из индивидуальной накладной и документа, составленного налогоплательщиком для иностранного физического лица и содержащего сведения о стоимости реализованного товара. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ) (В редакции  Федерального закона от 19.12.2022 № 549-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.12.2014 № 452-ФЗ)\n\nОрганизация почтовой связи передает федеральному органу исполнительной власти, уполномоченному по контролю и надзору в области таможенного дела, сведения о факте вывоза товаров в случае, если товары пересылаются в международных почтовых отправлениях. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.12.2014 № 452-ФЗ)\n\nПеречень сведений, форматы и порядок их передачи в электронной форме организацией почтовой связи в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области таможенного дела, в целях подтверждения фактического вывоза товаров, пересылаемых в международных почтовых отправлениях, утверждаются совместно федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области таможенного дела, и организацией почтовой связи. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.12.2014 № 452-ФЗ)\n\nвместо копий истребованных документов, сведения из которых включены в реестр, предусмотренный абзацем первым подпункта 3 пункта 31 настоящей статьи, - при реализации услуг, указанных в подпункте 21 пункта 1 статьи 164 настоящего Кодекса и оказанных в отношении товаров, вывозимых железнодорожным транспортом в соответствии с таможенной процедурой экспорта; (В редакции  Федерального закона от 22.04.2024 № 92-ФЗ)\n\nвместо копий истребованных документов, сведения из которых включены в реестр, предусмотренный подпунктом 2 пункта 37 настоящей статьи, - при реализации услуг, указанных в подпункте 27 пункта 1 статьи 164 настоящего Кодекса, для перевозки или транспортировки железнодорожным транспортом экспортируемых товаров; (В редакции  Федерального закона от 22.04.2024 № 92-ФЗ)\n\nвместо копий документов, предусмотренных абзацем четвертым пункта 5 настоящей статьи, - при реализации работ (услуг), указанных в подпункте 9 пункта 1 статьи 164 настоящего Кодекса и оказанных российскими перевозчиками на железнодорожном транспорте в отношении экспортируемых товаров.\n\nУказанные в настоящем пункте документы представляются в налоговый орган в электронной форме по телекоммуникационным каналам связи через оператора электронного документооборота, являющегося российской организацией и соответствующего требованиям, утвержденным федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nПредставленные документы должны соответствовать требованиям, предусмотренным настоящей статьей.\n\n(Дополнение пунктом - Федеральный закон от 03.08.2018 № 302-ФЗ)","article_title":"Статья 165. Порядок подтверждения права на применение налоговой ставки 0 процентов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1efa19b6e0d33d67f1cc33fa092f55a7c0b3f3f007bfb080ab5cfa6b5b6c6410"},{"code_id":"NK_RF_2","article_number":"166","version_date":"2000-07-31","article_text":"1. Сумма налога при определении налоговой базы в соответствии со статьями 154 - 159 и 162 настоящего Кодекса исчисляется как соответствующая налоговой ставке процентная доля налоговой базы, а при раздельном учете - как сумма налога, полученная в результате сложения сумм налогов, исчисляемых отдельно как соответствующие налоговым ставкам процентные доли соответствующих налоговых баз.\n\n2. Общая сумма налога при реализации товаров (работ, услуг) представляет собой сумму, полученную в результате сложения сумм налога, исчисленных в соответствии с порядком, установленным пунктом 1 настоящей статьи.\n\n31. При реализации товаров, указанных в абзаце первом пункта 8 статьи 161 настоящего Кодекса, сумма налога налогоплательщиками-продавцами не исчисляется, за исключением случаев, предусмотренных абзацами седьмым и восьмым пункта 8 статьи 161, подпунктом 1 пункта 1 статьи 164 настоящего Кодекса, а также при реализации указанных товаров физическим лицам, не являющимся индивидуальными предпринимателями.\n\nПри реализации товаров, указанных в абзаце первом пункта 8 статьи 161 настоящего Кодекса, сумма налога исчисляется налоговыми агентами, указанными в пункте 8 статьи 161 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\nЕсли в соответствии с требованиями, установленными пунктом 3 статьи 160 настоящего Кодекса, налоговая база определяется отдельно по каждой группе ввозимых товаров, по каждой из указанных налоговых баз сумма налога исчисляется отдельно в соответствии с порядком, установленным абзацем первым настоящего пункта. При этом общая сумма налога исчисляется как сумма, полученная в результате сложения сумм налогов, исчисленных отдельно по каждой из таких налоговых баз. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)","article_title":"Статья 166. Порядок исчисления налога","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"df9ea851d2c840a309b3eb451e67f07bf4d8b4fb1d7f2f062d96bd62954e2b78"},{"code_id":"NK_RF_2","article_number":"167","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 22.07.2005 № 119-ФЗ)\n\n1. В целях настоящей главы моментом определения налоговой базы, если иное не предусмотрено пунктами 3, 7 - 11, 13 - 15 настоящей статьи, является наиболее ранняя из следующих дат:\n\n1) день отгрузки (передачи) товаров (работ, услуг), имущественных прав;\n\n2) день оплаты, частичной оплаты в счет предстоящих поставок товаров (выполнения работ, оказания услуг), передачи имущественных прав.\n\n(Пункт в редакции Федерального закона от 22.07.2005 № 119-ФЗ)\n\nВ случае, если документы (их копии), предусмотренные статьей 165 настоящего Кодекса, не собраны в течение сроков, указанных в пункте 9 статьи 165 настоящего Кодекса, моментом определения налоговой базы по указанным товарам (работам, услугам) является последнее число квартала, на который приходится истечение соответствующего срока, указанного в пункте 9 статьи 165 настоящего Кодекса, если иное не предусмотрено настоящим пунктом.\n\nВ случае реорганизации организации, если 181-й календарный день совпадает с датой завершения реорганизации или наступает после указанной даты, момент определения налоговой базы определяется правопреемником (правопреемниками) как дата завершения реорганизации (дата государственной регистрации каждой вновь возникшей организации, а в случае реорганизации в форме присоединения - дата внесения в единый государственный реестр юридических лиц записи о прекращении деятельности каждой присоединяемой организации).\n\n(Пункт в редакции  Федерального закона от 19.12.2022 № 549-ФЗ)\n\n11. В целях настоящей главы момент определения налоговой базы при передаче товаров (выполнении работ, оказании услуг) для собственных нужд, призн\n\nаваемой объектом налогообложения в соответствии с настоящей главой, определяется как день совершения указанной передачи товаров (выполнения работ, оказания услуг). (В редакции Федерального закона от 22.07.2005 № 119-ФЗ)\n\n12. Принятая организацией учетная политика для целей налогообложения утверждается соответствующими приказами, распоряжениями руководителя организации.\n\nУчетная политика для целей налогообложения применяется с 1 января года, следующего за годом утверждения ее соответствующим приказом, распоряжением руководителя организации.\n\nУчетная политика для целей налогообложения, принятая организацией, является обязательной для всех обособленных подразделений организации.\n\nУчетная политика для целей налогообложения, принятая вновь созданной организацией, утверждается не позднее окончания первого налогового периода. Учетная политика для целей налогообложения, принятая вновь созданной организацией, считается применяемой со дня создания организации.\n\nАбзац. (Дополнение абзацем - Федеральный закон от 29.12.2000 № 166-ФЗ) (Утратил силу - Федеральный закон от 22.07.2005 № 119-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 29.05.2002 № 57-ФЗ) (Утратил силу - Федеральный закон от 22.07.2005 № 119-ФЗ)\n\n13. В случае получения налогоплательщиком - изготовителем товаров (работ, услуг) оплаты, частичной оплаты в счет предстоящих поставок товаров (выполнения работ, оказания услуг), длительность производственного цикла изготовления которых составляет свыше шести месяцев (по перечню, определяемому Правительством Российской Федерации), налогоплательщик - изготовитель указанных товаров (работ, услуг) вправе определять момент определения налоговой базы как день отгрузки (передачи) указанных товаров (выполнения работ, оказания услуг) при наличии раздельного учета осуществляемых операций и сумм налога по приобретаемым товарам (работам, услугам), в том числе по основным средствам и нематериальным активам, имущественным правам, используемым для осуществления операций по производству товаров (работ, услуг) длительного производственного цикла и других операций.\n\nПри получении оплаты, частичной оплаты налогоплательщиком - изготовителем товаров (работ, услуг) в налоговые органы одновременно с налоговой декларацией представляется контракт с покупателем (копия такого контракта, заверенная подписью руководителя и главного бухгалтера), а также документ, подтверждающий длительность производственного цикла товаров (работ, услуг), с указанием их наименования, срока изготовления, наименования организации-изготовителя, выданный указанному налогоплательщику-изготовителю федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере промышленного, оборонно-промышленного и топливно-энергетического комплексов, подписанный уполномоченным лицом и заверенный печатью этого органа.\n\n(Дополнение пунктом - Федеральный закон от 22.07.2005 № 119-ФЗ)","article_title":"Статья 167. Момент определения налоговой базы","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ed167ccc878f8bc066adf27bc575313226d30ba97784c477e6a7c1c104c0b418"},{"code_id":"NK_RF_2","article_number":"168","version_date":"2000-07-31","article_text":"В случае получения налогоплательщиком (налоговыми агентами, указанными в пунктах 4, 5 и 51 статьи 161 настоящего Кодекса) сумм оплаты, частичной оплаты в счет предстоящих поставок товаров (выполнения работ, оказания услуг), передачи имущественных прав, реализуемых на территории Российской Федерации, налогоплательщик (налоговые агенты, указанные в пунктах 4, 5 и 51 статьи 161 настоящего Кодекса) обязан предъявить покупателю этих товаров (работ, услуг), имущественных прав сумму налога, исчисленную в порядке, установленном пунктом 4 статьи 164 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 26.11.2008 № 224-ФЗ) (В редакции Федерального закона от 03.08.2018 № 302-ФЗ)\n\nПоложения настоящего пункта не применяются при реализации товаров, указанных в абзаце первом пункта 8 статьи 161 настоящего Кодекса, за исключением случаев, предусмотренных подпунктом 1 пункта 1 статьи 164 настоящего Кодекса, а также при реализации указанных товаров физическим лицам, не являющимся индивидуальными предпринимателями. (Дополнение абзацем - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\nСумма налога, исчисленная налогоплательщиком при отгрузке (передаче) товаров, предусмотренных подпунктом 62 пункта 1 статьи 164 настоящего Кодекса, организациям в счет выкупа цифровых прав, включающих одновременно цифровые финансовые активы и утилитарные цифровые права, в случае, если указанные цифровые права удостоверяют право на получение таких товаров и при оплате, частичной оплате указанных цифровых прав налогоплательщиком была применена налоговая ставка, предусмотренная пунктом 1 статьи 164 настоящего Кодекса, предъявляется к оплате данным организациям. В этом случае организации обязаны перечислить соответствующую сумму налога налогоплательщику после предъявления указанных цифровых прав к выкупу и до момента отгрузки (передачи) таких товаров. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nПри исчислении суммы налога в соответствии с пунктами 1 - 3 статьи 161 настоящего Кодекса налоговыми агентами, указанными в пунктах 2 и 3 статьи 161 настоящего Кодекса, составляются счета-фактуры в порядке, установленном пунктами 5 и 6 статьи 169 настоящего Кодекса.\n\nПри исчислении суммы налога налоговыми агентами, указанными в пункте 10 статьи 1742 настоящего Кодекса, счета-фактуры выставляются в срок не позднее пяти календарных дней месяца, следующего за истекшим кварталом, в котором получена оплата, частичная оплата в счет оказания иностранными организациями услуг в электронной форме, указанных в пункте 1 статьи 1742 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\nПри изменении стоимости отгруженных товаров (выполненных работ, оказанных услуг), переданных имущественных прав, в том числе в случае изменения цены (тарифа) и (или) уточнения количества (объема) отгруженных товаров (выполненных работ, оказанных услуг), переданных имущественных прав, продавец выставляет покупателю корректировочный счет-фактуру не позднее пяти календарных дней считая со дня составления документов, указанных в пункте 10 статьи 172 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\n(Пункт в редакции Федерального закона от 26.11.2008 № 224-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 22.07.2005 № 119-ФЗ) (Утратил силу - Федеральный закон от 26.11.2008 № 224-ФЗ)\n\nПри реализации товаров (работ, услуг) налогоплательщиками, применяющими систему налогообложения для сельскохозяйственных товаропроизводителей (единый сельскохозяйственный налог) или упрощенную систему налогообложения и при этом освобожденными от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога, счета-фактуры не составляются.\n\nПри реализации налогоплательщиками товаров, указанных в абзаце первом пункта 8 статьи 161 настоящего Кодекса, а также при получении оплаты, частичной оплаты в счет предстоящих поставок таких товаров налогоплательщик составляет счета-фактуры, корректировочные счета-фактуры без учета сумм налога. При этом в указанных счетах-фактурах, корректировочных счетах-фактурах делается соответствующая надпись или ставится штамп \"НДС исчисляется налоговым агентом\".\n\n(Пункт в редакции  Федерального закона от 29.10.2024 № 362-ФЗ)","article_title":"Статья 168. Сумма налога, предъявляемая продавцом покупателю","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e67de81ce2f263453e0b0957b08b814b6f7eaac7871a2c7cb77d83fddba70935"},{"code_id":"NK_RF_2","article_number":"169","version_date":"2000-07-31","article_text":"Счет-фактура может быть составлен и выставлен на бумажном носителе и (или) в электронной форме. Счета-фактуры составляются в электронной форме по взаимному согласию сторон сделки и при наличии у указанных сторон совместимых технических средств и возможностей для приема и обработки этих счетов-фактур, если иное не предусмотрено настоящей статьей, в соответствии с установленными форматами и порядком. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 229-ФЗ) (В редакции федеральных законов от 29.06.2012 № 97-ФЗ, от 09.11.2020 № 371-ФЗ)\n\nКорректировочный счет-фактура, выставленный продавцом покупателю товаров (работ, услуг), имущественных прав при изменении стоимости отгруженных товаров (выполненных работ, оказанных услуг), переданных имущественных прав в сторону уменьшения, в том числе в случае уменьшения цены (тарифа) и (или) уменьшения количества (объема) отгруженных товаров (выполненных работ, оказанных услуг), переданных имущественных прав, является документом, служащим основанием для принятия продавцом товаров (работ, услуг), имущественных прав сумм налога к вычету в порядке, предусмотренном настоящей главой. (Дополнение абзацем - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\nСчет-фактура является документом, служащим основанием для принятия покупателем, исполняющим обязанности налогового агента в соответствии с пунктом 8 статьи 161 настоящего Кодекса, исчисленных сумм налога к вычету в порядке, предусмотренном настоящей главой. (Дополнение абзацем - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\nКорректировочный счет-фактура, составленный при изменении стоимости отгруженных товаров, указанных в абзаце первом пункта 8 статьи 161 настоящего Кодекса, в том числе в случае изменения цены и (или) изменения количества (объема) отгруженных товаров, является документом, служащим основанием для принятия покупателем, исполняющим обязанности налогового агента в соответствии с пунктом 8 статьи 161 настоящего Кодекса, сумм налога к вычету в порядке, предусмотренном настоящей главой. (Дополнение абзацем - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\n1) реализации, передачи в составе выполненных работ товаров, подлежащих прослеживаемости, физическим лицам для личных, семейных, домашних и иных не связанных с предпринимательской деятельностью нужд, а также налогоплательщикам налога на профессиональный доход; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n2) реализации и перемещения товаров, подлежащих прослеживаемости, с территории Российской Федерации в соответствии с таможенной процедурой экспорта (реэкспорта);\n\n3) реализации и перемещения товаров, подлежащих прослеживаемости, с территории Российской Федерации на территорию другого государства - члена Евразийского экономического союза.\n\n(Дополнение пунктом - Федеральный закон от 09.11.2020 № 371-ФЗ)\n\nОшибки в счетах-фактурах и корректировочных счетах-фактурах, не препятствующие налоговым органам при проведении налоговой проверки идентифицировать продавца, покупателя товаров (работ, услуг), имущественных прав, наименование товаров (работ, услуг), имущественных прав, их стоимость, налоговую ставку и сумму налога, предъявленную покупателю, а также неуказание (неверное указание) в счете-фактуре сведений, установленных подпунктами 16 - 18 пункта 5 настоящей статьи, не являются основанием для отказа в принятии к вычету сумм налога. (В редакции федеральных законов от 19.07.2011 № 245-ФЗ, от 09.11.2020 № 371-ФЗ)\n\nНевыполнение требований к счету-фактуре, не предусмотренных пунктами 5 и 6 настоящей статьи, не может являться основанием для отказа принять к вычету суммы налога, предъявленные продавцом. Невыполнение не предусмотренных пунктами 52 и 6 настоящей статьи требований к корректировочному счету-фактуре, выставленному продавцом покупателю товаров (работ, услуг), имущественных прав при изменении стоимости отгруженных товаров (выполненных работ, оказанных услуг), переданных имущественных прав в сторону уменьшения, в том числе в случае уменьшения цены (тарифа) и (или) уменьшения количества (объема) отгруженных товаров (выполненных работ, оказанных услуг), переданных имущественных прав, не может являться основанием для отказа в принятии к вычету продавцом суммы налога. (В редакции Федерального закона от 19.07.2011 № 245-ФЗ)\n\nПоложения настоящего пункта применяются также к счетам-фактурам, корректировочным счетам-фактурам, выставляемым налогоплательщиком покупателю, исполняющему обязанности налогового агента в соответствии с пунктом 8 статьи 161 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\n(Пункт в редакции Федерального закона от 17.12.2009 № 318-ФЗ)\n\n1) при совершении операций, признаваемых объектом налогообложения в соответствии с настоящей главой (за исключением операций, не подлежащих налогообложению (освобождаемых от налогообложения) в соответствии со статьей 149 настоящего Кодекса, если иное не предусмотрено подпунктом 11 настоящего пункта). При совершении операций по реализации товаров (работ, услуг), имущественных прав, за исключением операций по реализации товаров, подлежащих прослеживаемости, лицам, не являющимся налогоплательщиками налога на добавленную стоимость, и налогоплательщикам, освобожденным от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога, по письменному согласию сторон сделки счета-фактуры не составляются; (В редакции федеральных законов от 21.07.2014 № 238-ФЗ, от 29.11.2014 № 382-ФЗ, от 30.05.2016 № 150-ФЗ, от 09.11.2020 № 371-ФЗ)\n\n11) при совершении операций по реализации товаров, не подлежащих налогообложению (освобождаемых от налогообложения) в соответствии со статьей 149 настоящего Кодекса, вывезенных за пределы территории Российской Федерации на территорию государства - члена Евразийского экономического союза; (Дополнение подпунктом - Федеральный закон от 30.05.2016 № 150-ФЗ)\n\n2) в иных случаях, определенных в установленном порядке.\n\n(Пункт в редакции Федерального закона от 28.12.2013 № 420-ФЗ)\n\nлогоплательщики, в том числе освобожденные от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога, лица, не являющиеся налогоплательщиками, в случае выставления и (или) получения ими счетов-фактур при осуществлении предпринимательской деятельности в интересах другого лица на основе договоров комиссии, агентских договоров, предусматривающих реализацию и (или) приобретение товаров (работ, услуг), имущественных прав от имени комиссионера (агента), или на основе договоров транспортной экспедиции, а также при выполнении функций застройщика обязаны вести журнал учета полученных и выставленных счетов-фактур в отношении указанной деятельности.\n\nДля налогоплательщиков, осуществляющих предпринимательскую деятельность на основе договоров транспортной экспедиции, положения абзаца первого настоящего пункта применяются в случае определения ими налоговой базы как суммы дохода, полученной в виде вознаграждения при исполнении данных договоров.\n\nДля лиц, осуществляющих предпринимательскую деятельность на основе договоров транспортной экспедиции, не являющихся налогоплательщиками налога на добавленную стоимость либо являющихся налогоплательщиками, освобожденными от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога, положения абзаца первого настоящего пункта применяются в случае, если при определении ими налоговой базы в порядке, установленном главами 23, 25, 261 и 262 настоящего Кодекса, в составе доходов учитываются доходы в виде вознаграждения при исполнении данных договоров.\n\nВ журнале учета полученных и выставленных счетов-фактур не подлежат регистрации счета-фактуры, выставленные на сумму дохода в виде вознаграждения при исполнении указанных в настоящем пункте договоров.\n\nПоложения настоящего пункта не распространяются на налоговых агентов, указанных в пунктах 4, 5 и 51 статьи 161 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 03.08.2018 № 302-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 28.06.2013 № 134-ФЗ) (В редакции Федерального закона от 21.07.2014 № 238-ФЗ)\n\n1) порядковый номер и дата составления счета-фактуры; (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\n2) наименование, адрес и идентификационные номера налогоплательщика (налогового агента) и покупателя; (В редакции Федерального закона от 03.08.2018 № 302-ФЗ)\n\n3) наименование и адрес грузоотправителя и грузополучателя;\n\n4) номер платежно-расчетного документа в случае получения оплаты, частичной оплаты или иных платежей в счет предстоящих поставок товаров (выполнения работ, оказания услуг), передачи имущественных прав, реквизиты, позволяющие идентифицировать документ об отгрузке товаров (о выполнении работ, об оказании услуг), о передаче имущественных прав; (В редакции Федерального закона от 09.11.2020 № 371-ФЗ)\n\n5) порядковый номер записи поставляемых (отгруженных) товаров (выполненных работ, оказанных услуг), переданных имущественных прав, наименование поставляемых (отгруженных) товаров (описание выполненных работ, оказанных услуг), переданных имущественных прав и единица измерения (при возможности ее указания); (В редакции Федерального закона от 09.11.2020 № 371-ФЗ)\n\n6) количество (объем) поставляемых (отгруженных) по счету-фактуре товаров (работ, услуг) исходя из принятых по нему единиц измерения (при возможности их указания); (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n61) наименование валюты; (Дополнение подпунктом - Федеральный закон от 27.07.2010 № 229-ФЗ)\n\n62) идентификатор государственного контракта, договора (соглашения) (при наличии); (Дополнение подпунктом - Федеральный закон от 03.04.2017 № 56-ФЗ)\n\n7) цена (тариф) за единицу измерения (при возможности ее указания) по договору (контракту) без учета налога, а в случае применения государственных регулируемых цен (тарифов), включающих в себя налог, с учетом суммы налога; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n8) стоимость товаров (работ, услуг), имущественных прав за все количество поставляемых (отгруженных) по счету-фактуре товаров (выполненных работ, оказанных услуг), переданных имущественных прав без налога; (В редакции Федерального закона от 22.07.2005 № 119-ФЗ)\n\n9) сумма акциза по подакцизным товарам;\n\n10) налоговая ставка;\n\n11) сумма налога, предъявляемая покупателю товаров (работ, услуг), имущественных прав, определяемая исходя из применяемых налоговых ставок; (В редакции Федерального закона от 22.07.2005 № 119-ФЗ)\n\n12) стоимость всего количества поставляемых (отгруженных) по счету-фактуре товаров (выполненных работ, оказанных услуг), переданных имущественных прав с учетом суммы налога; (В редакции Федерального закона от 22.07.2005 № 119-ФЗ)\n\n13) страна происхождения товара; (В редакции Федерального закона от 29.12.2000 № 166-ФЗ)\n\n14) регистрационный номер декларации на товары; (В редакции Федерального закона от 09.11.2020 № 371-ФЗ)\n\n15) код вида товара в соответствии с единой Товарной номенклатурой внешнеэкономической деятельности Евразийского экономического союза. Сведения, предусмотренные настоящим подпунктом, указываются в отношении товаров, вывезенных за пределы территории Российской Федерации на территорию государства - члена Евразийского экономического союза; (Дополнение подпунктом - Федеральный закон от 30.05.2016 № 150-ФЗ)\n\n16) регистрационный номер партии товара, подлежащего прослеживаемости; (Дополнение подпунктом - Федеральный закон от 09.11.2020 № 371-ФЗ)\n\n17) количественная единица измерения товара, используемая в целях осуществления прослеживаемости; (Дополнение подпунктом - Федеральный закон от 09.11.2020 № 371-ФЗ)\n\n18) количество товара, подлежащего прослеживаемости, в количественной единице измерения товара, используемой в целях осуществления прослеживаемости; (Дополнение подпунктом - Федеральный закон от 09.11.2020 № 371-ФЗ)\n\n19) стоимость товара, подлежащего прослеживаемости. (Дополнение подпунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nСведения, предусмотренные подпунктом 13 настоящего пункта, указываются в отношении товаров, страной происхождения которых не является Российская Федерация. Сведения, предусмотренные подпунктом 14 настоящего пункта, указываются в отношении товаров, страной происхождения которых не являются государства - члены Евразийского экономического союза. Налогоплательщик, реализующий указанные товары, несет ответственность только за соответствие указанных сведений в предъявляемых им счетах-фактурах сведениям, содержащимся в полученных им счетах-фактурах и товаросопроводительных документах. (В редакции федеральных законов от 29.12.2000 № 166-ФЗ, от 09.11.2020 № 371-ФЗ)\n\nСведения, предусмотренные подпунктами 16 - 19 настоящего пункта, указываются при реализации товаров (в том числе в составе комплектов (наборов), подлежащих прослеживаемости, а также при передаче товаров, подлежащих прослеживаемости, в составе выполненных работ. (Дополнение абзацем - Федеральный закон от 09.11.2020 № 371-ФЗ) (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n1) порядковый номер и дата составления счета-фактуры; (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\n2) наименование, адрес и идентификационные номера налогоплательщика (налогового агента) и покупателя; (В редакции Федерального закона от 03.08.2018 № 302-ФЗ)\n\n3) номер платежно-расчетного документа;\n\n4) наименование поставляемых товаров (описание работ, услуг), имущественных прав;\n\n41) наименование валюты; (Дополнение подпунктом - Федеральный закон от 27.07.2010 № 229-ФЗ)\n\n42) идентификатор государственного контракта, договора (соглашения) (при наличии); (Дополнение подпунктом - Федеральный закон от 03.04.2017 № 56-ФЗ)\n\n5) сумма оплаты, частичной оплаты в счет предстоящих поставок товаров (выполнения работ, оказания услуг), передачи имущественных прав;\n\n6) налоговая ставка;\n\n7) сумма налога, предъявляемая покупателю товаров (работ, услуг), имущественных прав, определяемая исходя из применяемых налоговых ставок.\n\n(Дополнение пунктом - Федеральный закон от 26.11.2008 № 224-ФЗ)\n\n1) наименование \"корректировочный счет-фактура\", порядковый номер и дата составления корректировочного счета-фактуры;\n\n2) порядковый номер и дата составления счета-фактуры (счетов-фактур), по которому (которым) осуществляется изменение стоимости отгруженных товаров (выполненных работ, оказанных услуг), переданных имущественных прав, в том числе в случае изменения цены (тарифа) и (или) уточнения количества (объема) поставленных (отгруженных) товаров (выполненных работ, оказанных услуг), переданных имущественных прав; (В редакции Федерального закона от 05.04.2013 № 39-ФЗ)\n\n3) наименования, адреса и идентификационные номера налогоплательщика (налогового агента) и покупателя; (В редакции Федерального закона от 03.08.2018 № 302-ФЗ)\n\n4) порядковый номер записи поставляемых (отгруженных) товаров (выполненных работ, оказанных услуг), переданных имущественных прав, наименование поставляемых (отгруженных) товаров (описание выполненных работ, оказанных услуг), переданных имущественных прав и единица измерения (при возможности ее указания), по которым осуществляются изменение цены (тарифа) и (или) уточнение количества (объема); (В редакции Федерального закона от 09.11.2020 № 371-ФЗ)\n\n5) количество (объем) товаров (работ, услуг) по счету-фактуре (счетам-фактурам) исходя из принятых по нему единиц измерения (при возможности их указания) до и после уточнения количества (объема) поставленных (отгруженных) товаров (выполненных работ, оказанных услуг), переданных имущественных прав; (В редакции Федерального закона от 05.04.2013 № 39-ФЗ)\n\n6) наименование валюты;\n\n61) идентификатор государственного контракта, договора (соглашения) (при наличии); (Дополнение подпунктом - Федеральный закон от 03.04.2017 № 56-ФЗ)\n\n7) цена (тариф) за единицу измерения (при возможности ее указания) без учета налога, а в случае применения государственных регулируемых цен (тарифов), включающих в себя налог, с учетом суммы налога до и после изменения цены (тарифа);\n\n8) стоимость всего количества товаров (работ, услуг), имущественных прав по счету-фактуре (счетам-фактурам) без налога до и после внесенных изменений; (В редакции Федерального закона от 05.04.2013 № 39-ФЗ)\n\n9) сумма акциза по подакцизным товарам;\n\n10) налоговая ставка;\n\n11) сумма налога, определяемая исходя из применяемых налоговых ставок до и после изменения стоимости отгруженных товаров (выполненных работ, оказанных услуг), переданных имущественных прав, в том числе в случае изменения цены (тарифа) и (или) уточнения количества (объема) поставленных (отгруженных) товаров (выполненных работ, оказанных услуг), переданных имущественных прав;\n\n12) стоимость всего количества товаров (работ, услуг), имущественных прав по счету-фактуре (счетам-фактурам) с учетом суммы налога до и после изменения стоимости отгруженных товаров (выполненных работ, оказанных услуг), переданных имущественных прав, в том числе в случае изменения цены (тарифа) и (или) уточнения количества (объема) поставленных (отгруженных) товаров (выполненных работ, оказанных услуг), переданных имущественных прав; (В редакции Федерального закона от 05.04.2013 № 39-ФЗ)\n\n13) разница между показателями счета-фактуры (счетов-фактур), по которому (которым) осуществляется изменение стоимости отгруженных товаров (выполненных работ, оказанных услуг), переданных имущественных прав, в том числе в случае изменения цены (тарифа) и (или) уточнения количества (объема) поставленных (отгруженных) товаров (выполненных работ, оказанных услуг), переданных имущественных прав, и показателями, исчисленными после изменения стоимости отгруженных товаров (выполненных работ, оказанных услуг), переданных имущественных прав, в том числе в случае изменения цены (тарифа) и (или) уточнения количества (объема) поставленных (отгруженных) товаров (выполненных работ, оказанных услуг), переданных имущественных прав. (В редакции Федерального закона от 05.04.2013 № 39-ФЗ)\n\nНалогоплательщик вправе составить единый корректировочный счет-фактуру на изменение стоимости отгруженных товаров (выполненных работ, оказанных услуг), переданных имущественных прав, указанных в двух и более счетах-фактурах, составленных этим налогоплательщиком ранее; (В редакции Федерального закона от 05.04.2013 № 39-ФЗ)\n\n14) страна происхождения товара; (Дополнение подпунктом - Федеральный закон от 09.11.2020 № 371-ФЗ)\n\n15) регистрационный номер декларации на товары; (Дополнение подпунктом - Федеральный закон от 09.11.2020 № 371-ФЗ)\n\n16) регистрационный номер партии товара, подлежащего прослеживаемости; (Дополнение подпунктом - Федеральный закон от 09.11.2020 № 371-ФЗ)\n\n17) количественная единица измерения товара, используемая в целях осуществления прослеживаемости; (Дополнение подпунктом - Федеральный закон от 09.11.2020 № 371-ФЗ)\n\n18) количество товара, подлежащего прослеживаемости, в количественной единице измерения товара, используемой в целях осуществления прослеживаемости; (Дополнение подпунктом - Федеральный закон от 09.11.2020 № 371-ФЗ)\n\n19) стоимость товара, подлежащего прослеживаемости. (Дополнение подпунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\nСчет-фактура, составленный в электронной форме, подписывается усиленной квалифицированной электронной подписью руководителя организации либо иных лиц, уполномоченных на это приказом (иным распорядительным документом) по организации или доверенностью от имени организации, индивидуального предпринимателя в соответствии с законодательством Российской Федерации. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 229-ФЗ) (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\nФорматы счета-фактуры, журнала учета полученных и выставленных счетов-фактур, книг покупок и книг продаж в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 27.07.2010 № 229-ФЗ)","article_title":"Статья 169. Счет-фактура","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"329af912708992a5abb9185289e75a3e0fced686888d98f92f509a4baa4f653e"},{"code_id":"NK_RF_2","article_number":"169.1","version_date":"2000-07-31","article_text":"1. Физические лица - граждане иностранных государств при вывозе товаров, которые приобретены ими у налогоплательщиков - организаций розничной торговли и при реализации которых был исчислен налог, имеют право на компенсацию суммы налога, уплаченной такими физическими лицами в составе цены товара организациям розничной торговли (в том числе при осуществлении ими деятельности через обособленное подразделение), в виде выплаты денежных средств таким физическим лицам в порядке и на условиях, которые установлены настоящей статьей (далее в настоящей главе - компенсация суммы налога).\n\nФизическое лицо - гражданин иностранного государства имеет право на компенсацию суммы налога при предъявлении паспорта, который выдан уполномоченным органом иностранного государства, не являющегося государством - членом Евразийского экономического союза, и по которому указанное физическое лицо въехало на территорию Российской Федерации, и при условии вывоза этим физическим лицом приобретенных им товаров за пределы таможенной территории Евразийского экономического союза (за исключением вывоза товаров через территории государств - членов Евразийского экономического союза) через пункты пропуска через Государственную границу Российской Федерации, перечень которых определяется Правительством Российской Федерации.\n\n2. Компенсация суммы налога не производится при приобретении физическими лицами - гражданами иностранных государств товаров, признаваемых подакцизными в соответствии со статьей 181 настоящего Кодекса. Правительство Российской Федерации вправе определить перечень иных товаров, при приобретении которых физическими лицами - гражданами иностранных государств на основании настоящей статьи не производится компенсация суммы налога.\n\n3. Сумма налога, компенсируемая физическому лицу - гражданину иностранного государства на основании настоящей статьи, определяется как сумма налога, исчисленная организацией розничной торговли при реализации товаров этому физическому лицу, уменьшенная на стоимость услуги по компенсации суммы налога.\n\n4. Документами, подтверждающими право физического лица - гражданина иностранного государства на компенсацию суммы налога, признаются паспорт, который выдан уполномоченным органом иностранного государства, не являющегося государством - членом Евразийского экономического союза, и по которому указанное физическое лицо въехало на территорию Российской Федерации, и документ (чек) для компенсации суммы налога, оформляемый физическому лицу налогоплательщиком - организацией розничной торговли в порядке и на условиях, которые предусмотрены настоящей статьей, с отметкой таможенного органа Российской Федерации, подтверждающей факт вывоза товаров с территории Российской Федерации за пределы таможенной террит\n\nории Евразийского экономического союза (за исключением вывоза товаров через территории государств - членов Евразийского экономического союза) через пункты пропуска через Государственную границу Российской Федерации в срок, предусмотренный для вывоза товаров в соответствии с пунктом 9 настоящей статьи. (В редакции Федерального закона от 20.07.2020 № 220-ФЗ)\n\nПорядок проставления отметки, предусмотренной настоящим пунктом, на документах (чеках) для компенсации суммы налога на бумажном носителе и в электронной форме утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области таможенного дела. (В редакции Федерального закона от 20.07.2020 № 220-ФЗ)\n\n5. Документ (чек) для компенсации суммы налога при реализации товаров физическому лицу - гражданину иностранного государства, имеющему право на компенсацию суммы налога, оформляется такому физическому лицу налогоплательщиком - организацией розничной торговли, включенной в перечень организаций розничной торговли, утверждаемый федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в области развития внешней и внутренней торговли.\n\nФорма заявления о включении в перечень организаций розничной торговли, указанный в абзаце первом настоящего пункта, порядок рассмотрения заявления о включении организации розничной торговли в указанный перечень и порядок исключения организации розничной торговли из указанного перечня утверждаются федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в области развития внешней и внутренней торговли.\n\nДля включения в перечень организаций розничной торговли, указанный в абзаце первом настоящего пункта, организация розничной торговли или ее обособленное подразделение должны размещаться в местах размещения, перечень которых утверждается Правительством Российской Федерации.\n\nОрганизация розничной торговли должна соответствовать критериям отбора организаций розничной торговли, определяемым Правительством Российской Федерации.\n\n6. Документ (чек) для компенсации суммы налога оформляется по требованию физического лица - гражданина иностранного государства при реализации ему организацией розничной торговли в течение одного календарного дня товаров на сумму не менее 10 тысяч рублей с учетом налога.\n\nДокумент (чек) для компенсации суммы налога может оформляться организациями розничной торговли в электронной форме (далее в настоящей статье - электронный документ (чек). Формат электронного документа (чека) утверждается совместно федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области таможенного дела, и федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nДокумент (чек) для компенсации суммы налога оформляется на основании одного или нескольких кассовых чеков, отпечатанных в течение одного календарного дня с применением контрольно-кассовой техники, адрес установки (применения) которой соответствует месту размещения организации розничной торговли или ее обособленного подразделения, предусмотренному перечнем, указанным в абзаце третьем пункта 5 настоящей статьи.\n\n(Пункт в редакции Федерального закона от 20.07.2020 № 220-ФЗ)\n\n7. Документ (чек) для компенсации суммы налога составляется в произвольной форме и содержит следующие сведения:\n\n1) порядковый номер и дата составления документа (чека) для компенсации суммы налога;\n\n2) порядковый номер и дата кассового чека, выданного организацией розничной торговли физическому лицу, указанному в пункте 1 настоящей статьи;\n\n3) наименование, идентификационный номер налогоплательщика организации розничной торговли, адрес этой организации или ее обособленного подразделения (в случае осуществления организацией розничной торговли деятельности через обособленное подразделение);\n\n4) фамилия, имя, отчество (при его наличии) физического лица, указанного в пункте 1 настоящей статьи, написанные буквами латинского алфавита (в соответствии с паспортными данными);\n\n5) номер паспорта физического лица, указанного в пункте 1 настоящей статьи;\n\n6) наименование иностранного государства, уполномоченным органом которого выдан паспорт физическому лицу, указанному в пункте 1 настоящей статьи, написанное буквами латинского алфавита (в соответствии с паспортными данными);\n\n7) наименование реализованных товаров и единица измерения;\n\n8) номера (артикулы) товаров (при их наличии) (по каждому наименованию товара);\n\n9) количество (объем) реализованных товаров (по каждому наименованию товара);\n\n10) сумма налога, исчисленная организацией розничной торговли по реализованным товарам (по каждому наименованию товара);\n\n11) стоимость реализованных товаров с учетом суммы налога (по каждому наименованию товара);\n\n12) штриховой код, позволяющий с применением считывающих устройств осуществлять идентификацию номера документа (чека) для компенсации суммы налога.\n\n8. Организации розничной торговли, не оказывающие услуг, предусмотренных подпунктом 211 пункта 1 статьи 164 настоящего Кодекса, передают в электронной форме лицам, оказывающим такие услуги на основании соглашений с указанными организациями розничной торговли, сведения из документов (чеков) для компенсации суммы налога, электронные документы (чеки). Состав, формат, порядок передачи в электронной форме указанных сведений и порядок передачи электронных документов (чеков) утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области таможенного дела.\n\nЛица, оказывающие услуги, предусмотренные подпунктом 211 пункта 1 статьи 164 настоящего Кодекса, передают в электронной форме в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области таможенного дела, сведения из документов (чеков) для компенсации суммы налога, электронные документы (чеки). Состав, формат, порядок передачи в электронной форме указанных сведений и порядок передачи электронных документов (чеков) утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области таможенного дела.\n\nФедеральный орган исполнительной власти, уполномоченный по контролю и надзору в области таможенного дела, передает в электронной форме в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, сведения из документов (чеков) для компенсации суммы налога, в том числе из электронных документов (чеков), и сведения о проставленных на таких документах таможенными органами Российской Федерации отметках, указанных в пункте 4 настоящей статьи. Состав, формат и порядок передачи в электронной форме указанных сведений утверждаются совместно федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, и федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области таможенного дела.\n\nФедеральный орган исполнительной власти, уполномоченный по контролю и надзору в области таможенного дела, передает в электронной форме лицам, оказывающим услуги, предусмотренные подпунктом 211 пункта 1 статьи 164 настоящего Кодекса, сведения из документов (чеков) для компенсации суммы налога, сведения о проставленных на них таможенными органами Российской Федерации отметках, указанных в пункте 4 настоящей статьи, электронные документы (чеки) с проставленными таможенными органами Российской Федерации отметками, указанными в пункте 4 настоящей статьи. Состав, формат, порядок передачи в электронной форме указанных сведений и порядок передачи электронных документов (чеков) утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области таможенного дела.\n\n(Пункт в редакции Федерального закона от 20.07.2020 № 220-ФЗ)\n\n81. Лица, оказывающие услуги, предусмотренные подпунктом 211 пункта 1 статьи 164 настоящего Кодекса, на основании соглашений с организациями розничной торговли, после выплаты физическим лицам - гражданам иностранных государств компенсации сумм налога направляют организациям розничной торговли, оформившим документы (чеки) для компенсации суммы налога:\n\nдокументы (чеки) для компенсации суммы налога с отметками, указанными в пункте 4 настоящей статьи;\n\nсведения, полученные от федерального органа исполнительной власти, уполномоченного по контролю и надзору в области таможенного дела, в соответствии с абзацем четвертым пункта 8 настоящей статьи, - в электронной форме;\n\nсведения о компенсированных физическим лицам - гражданам иностранных государств суммах налога - в электронной форме.\n\nФормат, порядок направления в электронной форме указанных сведений и порядок передачи электронных документов (чеков) утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение пунктом - Федеральный закон от 20.07.2020 № 220-ФЗ)\n\n9. Физические лица - граждане иностранных государств, имеющие право на компенсацию суммы налога, вправе обратиться за компенсацией суммы налога в течение одного года со дня приобретения товаров в организациях розничной торговли при условии вывоза товаров в течение трех месяцев со дня их приобретения за пределы таможенной территории Евразийского экономического союза (за исключением вывоза товаров через территории государств - членов Евразийского экономического союза) через пункты пропуска через Государственную границу Российской Федерации.\n\n(Дополнение статьей - Федеральный закон от 27.11.2017 № 341-ФЗ)","article_title":"Статья 169.1. Компенсация суммы налога физическим лицам - гражданам иностранных государств при вывозе товаров за пределы таможенной территории Евразийского экономического союза. Порядок и условия осуществления такой компенсации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"45723dd44811ea9167c5fdc7449aabb2741865b2c608f7f629eec61e17da9521"},{"code_id":"NK_RF_2","article_number":"170","version_date":"2000-07-31","article_text":"1) приобретения (ввоза) товаров (работ, услуг), в том числе основных средств и нематериальных активов, используемых для операций по производству и (или) реализации (а также передаче, выполнению, оказанию для собственных нужд) товаров (работ, услуг), не подлежащих налогообложению (освобожденных от налогообложения);\n\n2) приобретения (ввоза) товаров (работ, услуг), в том числе основных средств и нематериальных активов, используемых для операций по производству и (или) реализации товаров, местом реализации которых не признается территория Российской Федерации, за исключением операций по реализации товаров посредством электронных торговых площадок покупателю - физическому лицу, получающему товар в другом государстве - члене Евразийского экономического союза; (В редакции  федеральных законов от 15.04.2019 № 63-ФЗ, от 29.05.2024 № 100-ФЗ)\n\n21) приобретения (ввоза) товаров (работ, услуг), в том числе основных средств и нематериальных активов, используемых для операций по реализации работ (услуг), предусмотренных статьей 149 настоящего Кодекса, местом реализации которых не признается территория Российской Федерации. Положения настоящего подпункта не применяются в случае приобретения рекламных и маркетинговых услуг, используемых для передачи прав, указанных в подпункте 26 пункта 2 статьи 149 настоящего Кодекса, местом реализации которых не признается территория Российской Федерации; (Дополнение подпунктом - Федеральный закон от 15.04.2019 № 63-ФЗ) (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\n3) приобретения (ввоза) товаров (работ, услуг), в том числе основных средств и нематериальных активов, лицами, не являющимися налогоплательщиками налога на добавленную стоимость либо освобожденными от исполнения обязанностей налогоплательщика по исчислению и уплате налога; (В редакции Федерального закона от 22.07.2005 № 119-ФЗ)\n\n4) приобретения (ввоза) товаров (работ, услуг), в том числе основных средств и нематериальных активов, имущественных прав, для производства и (или) реализации (передачи) товаров (работ, услуг), операции по реализации (передаче) которых не признаются реализацией товаров (работ, услуг) в соответствии с пунктом 2 статьи 146 настоящего Кодекса, если иное не установлено настоящей главой; (В редакции Федерального закона от 22.07.2005 № 119-ФЗ)\n\n5) приобретения банками, применяющими порядок учета налога, предусмотренный пунктом 5 настоящей статьи, товаров, в том числе основных средств и нематериальных активов, имущественных прав, которые в дальнейшем реализуются банками до начала использования для осуществления банковских операций, для сдачи в аренду или до введения в эксплуатацию; (Дополнение подпунктом - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\n6) приобретения имущественных прав, предусмотренных абзацем вторым пункта 1, пунктами 2 - 4 и 6 статьи 155 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 324-ФЗ)\n\n7) приобретения автомобилей и мотоциклов, налоговая база по операциям реализации которых определяется в соответствии с пунктом 52 статьи 154 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 19.12.2023 № 612-ФЗ)\n\n8) приобретения (ввоза) товаров (работ, услуг), в том числе основных средств и нематериальных активов, имущественных прав налогоплательщиками, применяющими упрощенную систему налогообложения и исполняющими обязанности налогоплательщика, применяющего налоговые ставки, указанные в пункте 8 статьи 164 настоящего Кодекса, в случае использования этих товаров (работ, услуг), в том числе основных средств и нематериальных активов, имущественных прав при осуществлении операций по реализации товаров (работ, услуг), имущественных прав, налогообложение которых производится по налоговым ставкам, указанным в подпунктах 1 - 12, 21 - 31, 7, 11 пункта 1 и пункте 8 статьи 164 настоящего Кодекса. (Дополнение подпунктом - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\n(Пункт в редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nВ случае приобретения товаров (работ, услуг), в том числе основных средств, нематериальных активов, имущественных прав частично за счет субсидий и (или) бюджетных инвестиций, полученных налогоплательщиком из бюджетов бюджетной системы Российской Федерации, суммы налога, предъявленные налогоплательщику и (или) фактически уплаченные им при ввозе товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, вычету не подлежат в соответствующей доле.\n\nУказанная доля определяется как отношение суммы субсидий и (или) бюджетных инвестиций, израсходованных на приобретение товаров (работ, услуг), в том числе основных средств, нематериальных активов, имущественных прав, к общей стоимости указанных товаров (работ, услуг), в том числе основных средств, нематериальных активов, имущественных прав с учетом предъявленных налогоплательщику и фактически уплаченных им при ввозе таких товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, сумм налога.\n\nВ случае предоставления субсидии на уплату сумм налога при ввозе товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, уплаченная за счет таких субсидий и (или) бюджетных инвестиций сумма налога вычету не подлежит.\n\nСуммы налога, не подлежащие вычету в соответствии с настоящим пунктом, не включаются в стоимость указанных товаров (работ, услуг), в том числе основных средств, нематериальных активов, имущественных прав, а учитываются единовременно в составе прочих расходов в соответствии со статьей 264 настоящего Кодекса.\n\nВ случае, если при предоставлении субсидий и (или) бюджетных инвестиций не определены конкретные товары (работы, услуги), в том числе основные средства, нематериальные активы, имущественные права, на приобретение которых предоставляются указанные субсидии и (или) бюджетные инвестиции, налогоплательщик обязан вести раздельный учет затрат, осуществляемых за счет субсидий и (или) бюджетных инвестиций, и затрат, осуществляемых за счет других источников.\n\nПоложения настоящего пункта применяются также при проведении капитального строительства и (или) приобретении недвижимого имущества за счет субсидий и (или) бюджетных инвестиций, полученных налогоплательщиком из бюджетов бюджетной системы Российской Федерации, с последующим увеличением уставного фонда государственных (муниципальных) унитарных предприятий или возникновением права государственной (муниципальной) собственности на эквивалентную часть в уставном (складочном) капитале юридических лиц.\n\nПоложения настоящего пункта не применяются в случае, если документами о предоставлении субсидий и (или) бюджетных инвестиций предусмотрено финансирование затрат на оплату приобретаемых товаров (работ, услуг), в том числе основных средств, нематериальных активов, имущественных прав без включения в состав таких затрат предъявленных сумм налога и (или) сумм налога, уплаченных при ввозе товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2017 № 335-ФЗ) (В редакции Федерального закона от 27.11.2018 № 424-ФЗ)\n\n1) передачи имущества, нематериальных активов, имущественных прав в качестве вклада в уставный (складочный) капитал хозяйственных обществ и товариществ, вклада по договору инвестиционного товарищества или паевых взносов в паевые фонды кооперативов, передачи управляющей компании паевого инвестиционного фонда имущества в доверительное управление, а также передачи недвижимого имущества на пополнение целевого капитала некоммерческой организации в порядке, установленном Федеральным законом от 30 декабря 2006 года № 275-ФЗ \"О порядке формирования и использования целевого капитала некоммерческих организаций\". (В редакции федеральных законов от 21.11.2011 № 328-ФЗ, от 28.11.2011 № 336-ФЗ, от 02.07.2021 № 305-ФЗ)\n\nВосстановлению подлежат суммы налога в размере, ранее принятом к вычету, а в отношении основных средств и нематериальных а\n\nктивов - в размере суммы, пропорциональной остаточной (балансовой) стоимости без учета переоценки.\n\nСуммы налога, подлежащие восстановлению в соответствии с настоящим подпунктом, не включаются в стоимость имущества, нематериальных активов и имущественных прав и подлежат налоговому вычету у принимающей организации (в том числе участника договора инвестиционного товарищества - управляющего товарища) в порядке, установленном настоящей главой. При этом сумма восстановленного налога указывается в документах, которыми оформляется передача указанных имущества, нематериальных активов и имущественных прав. (В редакции федеральных законов от 28.11.2011 № 336-ФЗ; от 27.11.2017 № 351-ФЗ)\n\nПоложения настоящего подпункта не применяются в отношении передачи имущества, нематериальных активов, имущественных прав акционерным обществом, которое создано в целях реализации соглашений о создании особых экономических зон и 100 процентов акций которого принадлежит Российской Федерации, в уставный капитал хозяйственных обществ, созданных с участием такого акционерного общества в указанных целях, являющихся управляющими компаниями особых экономических зон; (Дополнение абзацем - Федеральный закон от 27.11.2017 № 351-ФЗ)\n\n2) дальнейшего использования таких товаров (работ, услуг), в том числе основных средств и нематериальных активов, и имущественных прав для осуществления операций, указанных в пункте 2 настоящей статьи, за исключением: операций, предусмотренных подпунктами 16 - 18, 22, 23, 25, 26, 29  пункта 2 статьи 146 настоящего Кодекса; операции, предусмотренной подпунктом 1 настоящего пункта; выполнения работ (оказания услуг) за пределами территории Российской Федерации российскими авиационными предприятиями в рамках миротворческой деятельности и осуществления международного сотрудничества в разрешении международных проблем гуманитарного характера в рамках Организации Объединенных Наций (в отношении воздушных судов, двигателей и запасных частей к ним); передачи основных средств, нематериальных активов и (или) иного имущества, имущественных прав правопреемнику (правопреемникам) при реорганизации юридических лиц; передачи имущества участнику договора простого товарищества (договора о совместной деятельности), договора инвестиционного товарищества или его правопреемнику в случае выдела его доли из имущества, находящегося в общей собственности участников договора, или раздела такого имущества; операций по передаче на безвозмездной основе медицинским организациям, являющимся некоммерческими организациями, органам государственной власти и управления и (или) органам местного самоуправления, органам публичной власти федеральной территории \"Сириус\", государственным и муниципальным учреждениям, государственным и муниципальным унитарным предприятиям имущества, предназначенного для использования в целях предупреждения и предотвращения распространения, а также диагностики и лечения новой коронавирусной инфекции; операций по передаче на безвозмездной основе в государственную казну Российской Федерации объектов недвижимого имущества. (В редакции  федеральных законов от 27.07.2010 № 217-ФЗ, от 28.11.2011 № 336-ФЗ, от 23.07.2013 № 216-ФЗ, от 28.12.2016 № 463-ФЗ, от 27.11.2017 № 351-ФЗ, от 04.06.2018 № 143-ФЗ, от 12.11.2018 № 414-ФЗ, от 08.06.2020 № 172-ФЗ, от 11.06.2021 № 199-ФЗ, от 29.11.2021 № 382-ФЗ, от 14.07.2022 № 323-ФЗ, от 08.08.2024 № 259-ФЗ, от 23.07.2025 № 227-ФЗ)\n\nВосстановлению подлежат суммы налога в размере, ранее принятом к вычету, а в отношении основных средств и нематериальных активов - в размере суммы, пропорциональной остаточной (балансовой) стоимости без учета переоценки.\n\nСуммы налога, подлежащие восстановлению в соответствии с настоящим подпунктом, не включаются в стоимость указанных товаров (работ, услуг), в том числе основных средств и нематериальных активов, имущественных прав, а учитываются в составе прочих расходов в соответствии со статьей 264 настоящего Кодекса.\n\nВосстановление сумм налога производится в том налоговом периоде, в котором товары (работы, услуги), в том числе основные средства и нематериальные активы, и имущественные права были переданы или начинают использоваться налогоплательщиком для осуществления операций, указанных в пункте 2 настоящей статьи.\n\nПри переходе налогоплательщика на упрощенную систему налогообложения с исполнением обязанностей налогоплательщика, применяющего налоговые ставки, указанные в пункте 8 статьи 164 настоящего Кодекса, суммы налога, принятые к вычету налогоплательщиком по товарам (работам, услугам), в том числе основным средствам и нематериальным активам, имущественным правам в порядке, предусмотренном настоящей главой, подлежат восстановлению в первом налоговом периоде, начиная с которого осуществляемые им операции по реализации товаров (работ, услуг), имущественных прав подлежат налогообложению. (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ) (Утратил силу - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\n3) в случае перечисления покупателем сумм оплаты, частичной оплаты в счет предстоящих поставок товаров (выполнения работ, оказания услуг), передачи имущественных прав.\n\nВосстановление сумм налога производится покупателем в том налоговом периоде, в котором суммы налога по приобретенным товарам (работам, услугам), имущественным правам подлежат вычету в порядке, установленном настоящим Кодексом, или в том налоговом периоде, в котором произошло изменение условий либо расторжение соответствующего договора и возврат соответствующих сумм оплаты, частичной оплаты, полученных налогоплательщиком в счет предстоящих поставок товаров (выполнения работ, оказания услуг), передачи имущественных прав.\n\nСуммы налога, принятые к вычету в отношении оплаты, частичной оплаты в счет предстоящих поставок товаров (выполнения работ, оказания услуг), передачи имущественных прав, подлежат восстановлению в размере налога, принятого налогоплательщиком к вычету по приобретенным им товарам (выполненным работам, оказанным услугам), переданным имущественным правам, в оплату которых подлежат зачету суммы ранее перечисленной оплаты, частичной оплаты согласно условиям договора (при наличии таких условий). (В редакции Федерального закона от 21.07.2014 № 238-ФЗ)\n\nПоложения настоящего подпункта распространяются на налоговых агентов, указанных в пункте 8 статьи 161 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 26.11.2008 № 224-ФЗ)\n\n4) изменения стоимости отгруженных товаров (выполненных работ, оказанных услуг), переданных имущественных прав в сторону уменьшения, в том числе в случае уменьшения цены (тарифа) и (или) уменьшения количества (объема) отгруженных товаров (выполненных работ, оказанных услуг), переданных имущественных прав.\n\nВосстановлению подлежат суммы налога в размере разницы между суммами налога, исчисленными исходя из стоимости отгруженных товаров (выполненных работ, оказанных услуг), переданных имущественных прав до и после такого уменьшения.\n\nВосстановление сумм налога производится покупателем в налоговом периоде, на который приходится наиболее ранняя из следующих дат:\n\nдата получения покупателем первичных документов на изменение в сторону уменьшения стоимости приобретенных товаров (выполненных работ, оказанных услуг), полученных имущественных прав;\n\nдата получения покупателем корректировочного счета-фактуры, выставленного продавцом при изменении в сторону уменьшения стоимости отгруженных товаров (выполненных работ, оказанных услуг), переданных имущественных прав. (В редакции Федерального закона от 27.11.2017 № 335-ФЗ)\n\nПоложения настоящего подпункта распространяются на налоговых агентов, указанных в пункте 8 статьи 161 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 19.07.2011 № 245-ФЗ)\n\n5) (Дополнение подпунктом - Федеральный закон от 19.07.2011 № 245-ФЗ) (Утратил силу - Федеральный закон от 24.11.2014 № 366-ФЗ)\n\n6) получения налогоплательщиком в соответствии с законодательством Российской Федерации из бюджетов бюджетной системы Российской Федерации субсидий и (или) бюджетных инвестиций на возмещение ранее понесенных затрат на приобретение товаров (работ, услуг), в том числе основных средств, нематериальных активов, имущественных прав и (или) на возмещение затрат по уплате налога при ввозе товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией.\n\nВосстановлению подлежат суммы налога в размере, ранее принятом к вычету, если иное не предусмотрено настоящим подпунктом.\n\nВ случае получения налогоплательщиком субсидий и (или) бюджетных инвестиций на возмещение части ранее понесенных затрат на приобретение товаров (работ, услуг), в том числе основных средств, нематериальных активов, имущественных прав восстановлению подлежат сумма налога, принятая к вычету по указанным товарам (работам, услугам), в том числе основным средствам, нематериальным активам, имущественным правам, и (или) сумма налога, уплаченного при ввозе товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, в соответствующей доле.\n\nУказанная доля определяется как отношение суммы субсидий и (или) бюджетных инвестиций, за счет которых были возмещены затраты на приобретение товаров (работ, услуг), в том числе основных средств, нематериальных активов, имущественных прав, к общей стоимости указанных товаров (работ, услуг), в том числе основных средств, нематериальных активов, имущественных прав с учетом предъявленных налогоплательщику и фактически уплаченных им при ввозе таких товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, сумм налога.\n\nВ случае получения субсидии на возмещение затрат по уплате сумм налога при ввозе товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, восстановлению подлежит сумма налога, ранее принятая к вычету, в размере полученной субсидии.\n\nВ случае, если при предоставлении субсидий и (или) бюджетных инвестиций на возмещение ранее понесенных затрат не определены конкретные товары (работы, услуги), в том числе основные средства, нематериальные активы, имущественные права, затраты на приобретение которых подлежат возмещению, восстановлению подлежит сумма налога по приобретенным товарам (работам, услугам), в том числе основным средствам, нематериальным активам, имущественным правам, принятая к вычету в течение календарного года, предшествовавшего году получения указанных субсидий и (или) бюджетных инвестиций, в соответствующей доле.\n\nДоля, указанная в абзаце шестом настоящего подпункта, определяется исходя из суммы субсидий и (или) бюджетных инвестиций, полученных на возмещение затрат, в общей величине совокупных расходов (с учетом предъявленных налогоплательщику и фактически уплаченных при ввозе товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, сумм налога) на приобретение, производство и (или) реализацию товаров (работ, услуг), имущественных прав, осуществленных в течение календарного года, предшествовавшего году получения указанных субсидий и (или) бюджетных инвестиций.\n\nСуммы налога, подлежащие восстановлению в соответствии с настоящим подпунктом, не включаются в стоимость товаров (работ, услуг), в том числе основных средств, нематериальных активов, имущественных прав, а учитываются единовременно в составе прочих расходов в соответствии со статьей 264 настоящего Кодекса.\n\nВосстановление сумм налога производится в том налоговом периоде, в котором получены суммы субсидий и (или) бюджетных инвестиций.\n\nПоложения настоящего подпункта не применяются в случае, если документами о предоставлении субсидий и (или) бюджетных инвестиций предусмотрено возмещение затрат на приобретение товаров (работ, услуг), в том числе основных средств, нематериальных активов, имущественных прав без включения в состав таких затрат предъявленных сумм налога и (или) сумм налога, уплаченных при ввозе товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией;\n\n(Дополнение подпунктом - Федеральный закон от 19.07.2011 № 245-ФЗ) (В редакции Федерального закона от 27.11.2018 № 424-ФЗ)\n\n7) отсутствия у налогоплательщика раздельного учета затрат, указанного в абзаце шестом пункта 21 настоящей статьи.\n\nСуммы налога по товарам (работам, услугам), в том числе по основным средствам, нематериальным активам, имущественным правам, принятые к вычету в календарном году за налоговые периоды начиная с налогового периода, в котором получены субсидии и (или) бюджетные инвестиции, подлежат восстановлению в последнем налоговом периоде указанного календарного года в соответствующей доле.\n\nУказанная доля определяется как отношение суммы субсидий и (или) бюджетных инвестиций с учетом положений абзаца четвертого настоящего подпункта к общей величине совокупных расходов (с учетом предъявленных налогоплательщику и фактически уплаченных им при ввозе товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, сумм налога) на приобретение, производство и (или) реализацию товаров (работ, услуг), в том числе основных средств, нематериальных активов, имущественных прав, осуществленных в течение налоговых периодов, указанных в абзаце втором настоящего подпункта.\n\nПоложительная разница между суммой субсидий и (или) бюджетных инвестиций и суммой расходов при расчете доли в текущем календарном году не учитывается и прибавляется к сумме субсидий и (или) бюджетных инвестиций для целей расчета доли в следующем календарном году.\n\nСуммы налога, подлежащие восстановлению в соответствии с настоящим подпунктом, не включаются в стоимость товаров (работ, услуг), в том числе основных средств, нематериальных активов, имущественных прав, а учитываются единовременно в составе прочих расходов в соответствии со статьей 264 настоящего Кодекса.\n\n(Дополнение подпунктом - Федеральный закон от 27.11.2018 № 424-ФЗ)\n\n(Пункт в редакции Федерального закона от 22.07.2005 № 119-ФЗ\n\nабзац; (Утратил силу - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nабзац. (Утратил силу - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nВосстановление сумм налога правопреемником организации производится на основании счетов-фактур (копий счетов-фактур), выставленных такой организации и прилагаемых к передаточному акту или разделительному балансу, исходя из стоимости указанных в них переданных товаров (работ, услуг), имущественных прав, а в отношении переданных основных средств и нематериальных активов - в размере суммы, пропорциональной остаточной (балансовой) стоимости без учета переоценки. При отсутствии у правопреемника счетов-фактур такой организации восстановление сумм налога производится правопреемником на основании бухгалтерской справки-расчета с применением налоговых ставок, предусмотренных пунктом 2, 3 или 8 статьи 164 настоящего Кодекса (действовавших на момент приобретения товаров (работ, услуг), имущественных прав, основных средств указанной организацией), к стоимости товаров (работ, услуг), имущественных прав, а в отношении основных средств и нематериальных активов - в размере суммы, пропорциональной остаточной (балансовой) стоимости без учета переоценки, указанной в передаточном акте или разделительном балансе. (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 325-ФЗ\n\nучитываются в стоимости таких товаров (работ, услуг), имущественных прав в соответствии с пунктом 2 настоящей статьи - по товарам (работам, услугам), в том числе основным средствам и нематериальным активам, имущественным правам, используемым для осуществления операций, не облагаемых налогом на добавленную стоимость;\n\nпринимаются к вычету в соответствии со статьей 172 настоящего Кодекса - по товарам (работам, услугам), в том числе основным средствам и нематериальным активам, имущественным правам, используемым для осуществления операций, облагаемых налогом на добавленную стоимость;\n\nпринимаются к вычету либо учитываются в их стоимости в той пропорции, в которой они используются для производства и (или) реализации товаров (работ, услуг), имущественных прав, операции по реализации которых подлежат налогообложению (освобождены от налогообложения), - по товарам (работам, услугам), в том числе основным средствам и нематериальным активам, имущественным правам, используемым для осуществления как облагаемых налогом, так и не подлежащих налогообложению (освобожденных от налогообложения) операций, в порядке, установленном принятой налогоплательщиком учетной политикой для целей налогообложения, и с учетом особенностей, установленных пунктом 41 настоящей статьи.\n\nПри этом налогоплательщик обязан вести раздельный учет сумм налога по приобретенным товарам (работам, услугам), в том числе основным средствам и нематериальным активам, имущественным правам, используемым для осуществления как облагаемых налогом, так и не подлежащих налогообложению (освобожденных от налогообложения) операций. (В редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\nПри отсутствии у налогоплательщика раздельного учета сумма налога по приобретенным товарам (работам, услугам), в том числе основным средствам и нематериальным активам, имущественным правам, вычету не подлежит и в расходы, принимаемые к вычету при исчислении налога на прибыль организаций (налога на доходы физических лиц), не включается.\n\nНалогоплательщик вправе не применять положения абзаца четвертого настоящего пункта к тем налоговым периодам, в которых доля совокупных расходов на приобретение, производство и (или) реализацию товаров (работ, услуг), имущественных прав, операции по реализации которых не подлежат налогообложению, не превышает 5 процентов общей величины совокупных расходов на приобретение, производство и (или) реализацию товаров (работ, услуг), имущественных прав. При этом указанные в абзаце четвертом настоящего пункта суммы налога, предъявленные таким налогоплательщикам продавцами товаров (работ, услуг), имущественных прав в указанном налоговом периоде, подлежат вычету в соответствии с порядком, предусмотренным статьей 172 настоящего Кодекса. (В редакции Федерального закона от 27.11.2017 № 335-ФЗ)\n\nПри расчете пропорции, указанной в абзаце четвертом настоящего пункта, эмитенты российских депозитарных расписок не учитывают сделки по размещению и (или) погашению российских депозитарных расписок, а также сделки по приобретению и реализации представляемых ценных бумаг, которые связаны с размещением и (или) погашением российских депозитарных расписок.\n\nДля целей настоящего пункта, а также пункта 41 настоящей статьи к операциям, подлежащим налогообложению, относятся также операции по реализации работ (услуг), местом реализации которых в соответствии со статьей\n\n148 настоящего Кодекса не признается территория Российской Федерации (за исключением операций, предусмотренных статьей 149 настоящего Кодекса). (Дополнение абзацем - Федеральный закон от 15.04.2019 № 63-ФЗ)\n\n(Пункт в редакции Федерального закона от 28.12.2013 № 420-ФЗ)\n\n1) по основным средствам и нематериальным активам, принимаемым к учету в первом или во втором месяце квартала, налогоплательщик вправе определять пропорцию исходя из стоимости отгруженных в соответствующем месяце товаров (выполненных работ, оказанных услуг), переданных имущественных прав, операции по реализации которых подлежат налогообложению (освобождены от налогообложения), в общей стоимости отгруженных за месяц товаров (выполненных работ, оказанных услуг), переданных имущественных прав;\n\n2) в целях расчета пропорции в отношении производных финансовых инструментов в качестве стоимости отгруженных товаров (выполненных работ, оказанных услуг), переданных имущественных прав за налоговый период: (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nстоимость производных финансовых инструментов, предполагающих поставку базисного актива, определяемая по правилам, установленным статьей 154 настоящего Кодекса, при условии отгрузки (передачи) базисного актива соответствующих производных финансовых инструментов в налоговом периоде (месяце); (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nсумма чистого дохода, полученного налогоплательщиком в текущем налоговом периоде (месяце) по производным финансовым инструментам в результате исполнения (прекращения) обязательств, не связанных с реализацией базисного актива (в том числе полученные суммы вариационной маржи и премий по контракту), включая суммы денежных средств, которые должны быть получены по таким обязательствам в будущих налоговых периодах, если дата определения (возникновения) соответствующего права требования по производным финансовым инструментам имела место в текущем налоговом периоде (месяце). (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nПри этом суммой чистого дохода признается разница между всеми полученными доходами, не связанными с реализацией базисного актива (в том числе полученные суммы вариационной маржи и премий по контракту), по всем производным финансовым инструментам и всеми произведенными расходами, не связанными с реализацией базисного актива (в том числе уплаченные суммы вариационной маржи и премий по контракту), по всем производным финансовым инструментам при условии, что такая разница является положительной. Если такая разница является отрицательной, то она не учитывается при расчете пропорции в соответствии с настоящим абзацем; (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n3) клиринговая организация при расчете пропорции не учитывает сделки с ценными бумагами, производными финансовыми инструментами, иные сделки, по которым такая клиринговая организация является стороной в целях осуществления их клиринга, а также сделки, совершаемые клиринговой организацией в целях обеспечения исполнения обязательств участников клиринга; (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n4) при определении стоимости услуг по предоставлению займа денежными средствами или ценными бумагами, по сделкам РЕПО и по операциям финансирования участия в кредите (займе), операции по реализации которых освобождаются от налогообложения, учитывается сумма доходов в виде процентов, начисленных налогоплательщиком в текущем налоговом периоде (месяце); (В редакции  Федерального закона от 14.07.2022 № 323-ФЗ)\n\n41) участник соглашения об управлении финансированием при расчете пропорции учитывает денежные средства, полученные от управляющего товарища в размере соответствующей доходной части в результате распределения денежных средств по соглашению об управлении финансированием; (Дополнение подпунктом - Федеральный закон от 17.02.2023 № 22-ФЗ)\n\n5) при определении стоимости ценных бумаг, операции по реализации которых освобождаются от налогообложения:\n\nучитывается сумма дохода от такой реализации, определяемая как совокупная разница между ценой реализованных ценных бумаг, определяемой с учетом положений статьи 280 настоящего Кодекса, и расходами на приобретение и (или) реализацию этих ценных бумаг, определяемыми с учетом положений статьи 280 настоящего Кодекса, при условии, что такая разница является положительной. Если указанная разница является отрицательной, то она не учитывается при определении суммы чистого дохода;\n\nне учитываются операции по погашению депозитарных расписок при получении представляемых ценных бумаг и операции по передаче представляемых ценных бумаг при размещении депозитарных расписок, удостоверяющих права на представляемые ценные бумаги;\n\nне учитываются операции по выдаче и погашению клиринговых сертификатов участия; (Дополнение абзацем - Федеральный закон от 28.11.2015 № 326-ФЗ)\n\n6) при определении стоимости цифровых финансовых активов учитывается сумма дохода от реализации цифровых финансовых активов, определяемая как совокупная разница между ценой реализованных цифровых финансовых активов и расходами на приобретение и (или) реализацию этих цифровых финансовых активов, определяемыми в соответствии с главой 25 настоящего Кодекса, при условии, что такая разница является положительной. Если указанная разница является отрицательной, она не учитывается при определении суммы чистого дохода. (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 324-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\nУчастник договора инвестиционного товарищества - управляющий товарищ, ответственный за ведение налогового учета, вправе включать в затраты, принимаемые к вычету при определении за отчетный (налоговый) период прибыли (убытка) от деятельности в рамках инвестиционного товарищества в соответствии со статьей 2782 настоящего Кодекса, суммы налога, уплаченные поставщикам по приобретаемым товарам (работам, услугам). При этом вся сумма налога, полученная инвестиционным товариществом по операциям, подлежащим налогообложению, подлежит уплате в бюджет. (Дополнение абзацем - Федеральный закон от 28.11.2011 № 336-ФЗ)\n\n1) клиринговые организации вправе принимать к вычету в порядке, установленном статьей 172 настоящего Кодекса:\n\nсуммы налога, предъявленные продавцами товаров (в том числе являющихся базисным активом производных финансовых инструментов), приобретаемых клиринговыми организациями в целях осуществления функций центрального контрагента, а также для исполнения и (или) обеспечения исполнения допущенных к клирингу обязательств; (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\nсуммы налога, предъявленные продавцами услуг, приобретаемых клиринговыми организациями в целях осуществления функций оператора товарных поставок;\n\n2) вычеты сумм налога, указанных в подпункте 1 настоящего пункта, производятся в случае приобретения товаров (услуг) указанными клиринговыми организациями только для осуществления операций по реализации товаров (услуг), подлежащих налогообложению;\n\n3) момент определения налоговой базы при реализации товаров (в том числе являющихся базисным активом производных финансовых инструментов) и (или) услуг, указанных в подпункте 1 настоящего пункта, определяется клиринговыми организациями, воспользовавшимися правом, предусмотренным подпунктом 1 настоящего пункта, в порядке, предусмотренном пунктом 1 статьи 167 настоящего Кодекса; (В редакции Федерального закона от 03.07.2016 № 242-ФЗ)\n\n4) суммы налога, уплаченные продавцам иных товаров (работ, услуг), не указанных в подпункте 1 настоящего пункта, включаются в затраты, принимаемые к вычету при исчислении налога на прибыль организаций. При этом вся сумма налога, полученная по операциям, не связанным с осуществлением клиринговой организацией деятельности по реализации товаров (работ, услуг), указанных в подпункте 1 настоящего пункта, подлежит уплате в бюджет;\n\n5) клиринговые организации, воспользовавшиеся правом, предусмотренным подпунктом 1 настоящего пункта, обязаны вести раздельный учет:\n\nсумм налога, указанных в абзаце втором подпункта 1 настоящего пункта;\n\nсумм налога, указанных в абзаце третьем подпункта 1 настоящего пункта;\n\nсумм налога, предъявленных продавцами иных товаров (работ, услуг), приобретаемых клиринговыми организациями;\n\nсумм налога, предъявленных клиринговыми организациями при реализации товаров, указанных в абзаце втором подпункта 1 настоящего пункта;\n\nсумм налога, предъявленных клиринговыми организациями при реализации услуг, указанных в абзаце третьем подпункта 1 настоящего пункта;\n\nсумм налога, предъявленных клиринговыми организациями при реализации иных товаров (работ, услуг);\n\n6) клиринговые организации, принявшие решение воспользоваться правом, предусмотренным подпунктом 1 настоящего пункта, отражают это решение в учетной политике организации для целей налогообложения, утверждаемой в соответствии с пунктом 12 статьи 167 настоящего Кодекса, и не вправе отказаться от использования этого права в течение четырех налоговых периодов, считая с налогового периода начала использования этого права;\n\n7) положения пунктов 4, 41 и 5 настоящей статьи не применяются в отношении клиринговых организаций, воспользовавшихся правом, предусмотренным подпунктом 1 настоящего пункта.\n\n(Дополнение пунктом - Федеральный закон от 28.11.2015 № 326-ФЗ)","article_title":"Статья 170. Порядок отнесения сумм налога на затраты по производству и реализации товаров (работ, услуг)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"321701f3e5197ab56e590a11093cca3ed6745df0123b4ef69a3a1192c2ee3ae4"},{"code_id":"NK_RF_2","article_number":"171","version_date":"2000-07-31","article_text":"1. Налогоплательщик имеет право уменьшить общую сумму налога, исчисленную в соответствии со статьей 166 настоящего Кодекса, на установленные настоящей статьей налоговые вычеты.\n\n1) товаров (работ, услуг), а также имущественных прав, приобретаемых для осуществления операций, признаваемых объектами налогообложения в соответствии с настоящей главой, за исключением товаров, предусмотренных пунктом 2 статьи 170 настоящего Кодекса; (В редакции федеральных законов от 29.12.2000 № 166-ФЗ; от 29.05.2002 № 57-ФЗ; от 22.07.2005 № 119-ФЗ)\n\n2) (Подпункт утратил силу - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n3) товаров (работ, услуг), а также имущественных прав, приобретаемых для осуществления операций по реализации работ (услуг), местом реализации которых в соответствии со статьей 148 настоящего Кодекса не признается территория Российской Федерации, за исключением операций, предусмотренных статьей 149 настоящего Кодекса, если иное не предусмотрено подпунктом 4 настоящего пункта. (В редакции  федеральных законов от 23.11.2020 № 374-ФЗ, от 12.07.2024 № 176-ФЗ)\n\nПоложения настоящего подпункта не применяются налогоплательщиками, применяющими налоговые ставки, указанные в пункте 8 статьи 164 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 15.04.2019 № 63-ФЗ)\n\n4) рекламных и маркетинговых услуг, приобретаемых для передачи прав, указанных в подпункте 26 пункта 2 статьи 149 настоящего Кодекса, местом реализации которых в соответствии со статьей 148 настоящего Кодекса не признается территория Российской Федерации. (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\nПоложения настоящего подпункта не применяются налогоплательщиками, применяющими налоговые ставки, указанные в пункте 8 статьи 164 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\n5) товаров (работ, услуг), а также имущественных прав, приобретаемых для осуществления операций по реализации товаров посредством электронных торговых площадок покупателю - физическому лицу, получающему товары в другом государстве - члене Евразийского экономического союза. (Дополнение подпунктом - Федеральный закон от 29.05.2024 № 100-ФЗ)\n\nАбзац. (Исключен - Федеральный закон от 29.12.2000 № 166-ФЗ)\n\nПраво на указанные налоговые вычеты имеют покупатели - налоговые агенты, состоящие на учете в налоговых органах и исполняющие обязанности налогоплательщика в соответствии с настоящей главой. Налоговые агенты, осуществляющие операции,\n\nуказанные в пунктах 4, 5, 51 и 52 статьи 161 настоящего Кодекса, не имеют права на включение в налоговые вычеты сумм налога, исчисленных по этим операциям. (В редакции  федеральных законов от 29.12.2000 № 166-ФЗ, от 29.05.2002 № 57-ФЗ, от 22.07.2005 № 119-ФЗ, от 03.08.2018 № 302-ФЗ, от 28.12.2022 № 565-ФЗ)\n\nПоложения настоящего пункта применяются при условии, что товары (работы, услуги), имущественные права были приобретены налогоплательщиком, являющимся налоговым агентом, для целей, указанных в пункте 2 настоящей статьи, и при их приобретении он исчислил налог в соответствии со статьей 161 настоящего Кодекса. (В редакции  федеральных законов от 29.12.2000 № 166-ФЗ, от 26.11.2008 № 224-ФЗ, от 27.11.2017 № 335-ФЗ, от 28.12.2022 № 565-ФЗ)\n\nСуммы налога, исчисленные налоговым агентом в соответствии с пунктом 53 статьи 161 настоящего Кодекса, принимаются к вычету при условии принятия на учет таким налоговым агентом товаров, полученных налогоплательщиком, являющимся налоговым агентом, в результате выкупа соответствующих цифровых прав для целей, указанных в пункте 2 настоящей статьи, а также в случае, предусмотренном абзацем третьим пункта 5 настоящей статьи. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nУказанные суммы налога подлежат вычету или возврату налогоплательщику - иностранному лицу после уплаты налоговым агентом налога, удержанного из доходов этого налогоплательщика, и только в той части, в которой приобретенные или ввезенные товары (работы, услуги), имущественные права использованы при производстве товаров (выполнении работ, оказании услуг), реализованных удержавшему налог налоговому агенту. Указанные суммы налога подлежат вычету или возврату при условии постановки налогоплательщика - иностранного лица на учет в налоговых органах Российской Федерации. (В редакции федеральных законов от 29.12.2000 № 166-ФЗ; от 22.07.2005 № 119-ФЗ)\n\nВычетам подлежат суммы налога, исчисленные продавцами и уплаченные ими в бюджет с сумм оплаты, частичной оплаты в счет предстоящих поставок товаров (выполнения работ, оказания услуг), реализуемых на территории Российской Федерации, в случае изменения условий либо расторжения соответствующего договора и возврата соответствующих сумм авансовых платежей. (В редакции Федерального закона от 22.07.2005 № 119-ФЗ)\n\nВычету подлежат суммы налога, исчисленные налогоплательщиками и уплаченные ими в бюджет при получении оплаты, частичной оплаты в связи с выпуском такими налогоплательщиками цифровых прав, включающих одновременно цифровые финансовые активы и утилитарные цифровые права, суммы налога, исчисленные налоговыми агентами в соответствии с пунктом 53 статьи 161 настоящего Кодекса, в случае, если выкуп указанных цифровых прав производится денежными средствами или путем передачи товаров (работ, услуг), имущественных прав, операции по реализации которых не подлежат налогообложению (освобождаются от налогообложения) либо подлежат налогообложению по налоговой ставке, предусмотренной пунктом 1 статьи 164 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 14.07.2022 № 324-ФЗ) (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nПоложения настоящего пункта распространяются на покупателей-налогоплательщиков, исполняющих обязанности налогового агента в соответствии с пунктами 2, 3 и 8 статьи 161 настоящего Кодекса, а также на налоговых агентов, указанных в пунктах 4, 5 и 51 статьи 161 и подпункте 3 пункта 1 статьи 1743 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 17.05.2007 № 85-ФЗ) (В редакции  федеральных законов от 27.11.2017 № 335-ФЗ, от 03.08.2018 № 302-ФЗ, от 29.05.2024 № 100-ФЗ)\n\nВ случае реорганизации вычетам у правопреемника (правопреемников) подлежат суммы налога, предъявленные реорганизованной (реорганизуемой) организации по товарам (работам, услугам), имущественным правам, приобретенным реорганизованной (реорганизуемой) организацией для выполнения строительно-монтажных работ для собственного потребления, создания нематериальных активов, принимаемые к вычету, но не принятые реорганизованной (реорганизуемой) организацией к вычету на момент завершения реорганизации. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nВычетам подлежат суммы налога, исчисленные налогоплательщиками в соответствии с пунктом 1 статьи 166 настоящего Кодекса при выполнении строительно-монтажных работ для собственного потребления, связанных с имуществом, предназначенным для осуществления операций, облагаемых налогом в соответствии с настоящей главой, стоимость которого подлежит включению в расходы (в том числе через амортизационные отчисления) при исчислении налога на прибыль организаций.\n\nСуммы налога, принятые налогоплательщиком к вычету в отношении приобретенных или построенных объектов основных средств в порядке, предусмотренном настоящей главой, подлежат восстановлению в случаях и порядке, предусмотренных статьей 1711 настоящего Кодекса. (В редакции Федерального закона от 24.11.2014 № 366-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 24.11.2014 № 366-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 19.07.2011 № 245-ФЗ) (Утратил силу - Федеральный закон от 24.11.2014 № 366-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 19.07.2011 № 245-ФЗ) (Утратил силу - Федеральный закон от 24.11.2014 № 366-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 19.07.2011 № 245-ФЗ) (Утратил силу - Федеральный закон от 24.11.2014 № 366-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 23.07.2013 № 216-ФЗ) (Утратил силу - Федеральный закон от 24.11.2014 № 366-ФЗ)\n\n(Пункт в редакции Федерального закона от 22.07.2005 № 119-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 24.11.2014 № 366-ФЗ)\n\nВычетам подлежат суммы налога, исчисленные налоговым агентом, указанным в пункте 8 статьи 161 настоящего Кодекса, с сумм оплаты, частичной оплаты, перечисленных в счет предстоящего приобретения товаров, указанных в пункте 8 статьи 161 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\nСуммы налога, предъявленные налогоплательщику, перечислившему суммы оплаты, частичной оплаты в связи с выпуском цифровых прав, включающих одновременно цифровые финансовые активы и утилитарные цифровые права, вычету не подлежат. (Дополнение абзацем - Федеральный закон от 14.07.2022 № 324-ФЗ)\n\nСуммы налога, предъявленные налогоплательщику, перечислившему суммы оплаты, частичной оплаты в счет предстоящей передачи имущественных прав, предусмотренных абзацем вторым пункта 1, пунктами 2 - 4 и 6 статьи 155 настоящего Кодекса, вычету не подлежат. (Дополнение абзацем - Федеральный закон от 14.07.2022 № 324-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 26.11.2008 № 224-ФЗ)\n\nПри изменении в сторону увеличения стоимости отгруженных товаров (выполненных работ, оказанных услуг), переданных имущественных прав, в том числе в случае увеличения цены (тарифа) и (или) увеличения количества (объема) отгруженных товаров (выполненных работ, оказанных услуг), переданных имущественных прав, разница между суммами налога, исчисленными исходя из стоимости отгруженных товаров (выполненных работ, оказанных услуг), переданных имущественных прав до и после такого увеличения, подлежит вычету у покупателя этих товаров (работ, услуг), имущественных прав.\n\n(Дополнение пунктом - Федеральный закон от 19.07.2011 № 245-ФЗ)","article_title":"Статья 171. Налоговые вычеты","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c4e231915d65ab9f3d08c5c8a1d1d41ab4325eda2b89ed1b5a542641b2740f8e"},{"code_id":"NK_RF_2","article_number":"171.1","version_date":"2000-07-31","article_text":"1. Суммы налога, принятые налогоплательщиком к вычету в отношении приобретенных или построенных объектов основных средств в порядке, предусмотренном настоящей главой, подлежат восстановлению в порядке, предусмотренном настоящей статьей.\n\n2. Положения настоящей статьи в отношении восстановления сумм налога применяются к суммам налога, предъявленным налогоплательщику (либо уплаченным или исчисленным налогоплательщиком) и принятым им к вычету при осуществлении следующих операций:\n\n1) при проведении подрядчиками капитального строительства объектов недвижимости, учитываемых как объекты основных средств;\n\n2) при приобретении недвижимого имущества (за исключением космических объектов);\n\n3) при приобретении на территории Российской Федерации или при ввозе на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, морских судов, судов внутреннего плавания, судов смешанного (река - море) плавания, воздушных судов и двигателей к ним;\n\n4) при приобретении товаров (работ, услуг) для выполнения строительно-монтажных работ;\n\n5) при выполнении налогоплательщиком строительно-монтажных работ для собственного потребления.\n\n3. Восстановление сумм налога, принятых налогоплательщиком к вычету в отношении приобретенных или построенных объектов основных средств, в соответствии с настоящей статьей производится в случае, если такие объекты основных средств в дальнейшем используются этим налогоплательщиком для осуществления операций, указанных в пункте 2 статьи 170 настоящего Кодекса, за исключением объектов основных средств, которые полностью самортизированы или с момента ввода которых в эксплуатацию у такого налогоплательщика прошло не менее 15 лет.\n\n4. Налогоплательщик обязан отражать восстановленную сумму налога в налоговой декларации, представляемой в налоговые органы по месту своего учета за последний налоговый период каждого календарного года из десяти лет начиная с года, в котором наступил момент, указанный в пункте 4 статьи 259 настоящего Кодекса.\n\n5. Расчет суммы налога, подлежащей восстановлению и уплате в бюджет в соответствии с пунктом 4 настоящей статьи, производится исходя из одной десятой суммы налога, принятой к вычету, в соответствующей доле.\n\nУказанная доля определяется исходя из стоимости отгруженных товаров (выполненных работ, оказанных услуг), переданных имущественных прав, не облагаемых налогом и указанных в пункте 2 статьи 170 настоящего Кодекса, в общей стоимости товаров (работ, услуг), имущественных прав, отгруженных (переданных) за соответствующий календарный год. При этом сумма налога, подлежащая восстановлению, в стоимость данного имущества не включается, а учитывается в составе прочих расходов в соответствии со статьей 264 настоящего Кодекса.\n\n6. В случае, если проведена модернизация (реконструкция) объектов основных средств (в том числе после истечения срока, указанного в пункте 3 настоящей статьи), приводящая к изменению их первоначальной стоимости, суммы налога по строительно-монтажным работам, а также по товарам (работам, услугам), приобретенным для выполнения строительно-монтажных работ при проведении модернизации (реконструкции), принятые налогоплательщиком к вычету в порядке, предусмотренном настоящей главой, подлежат восстановлению в случае, если указанные объекты основных средств в дальнейшем используются для осуществления операций, указанных в пункте 2 статьи 170 настоящего Кодекса.\n\nВ случае, указанном в настоящем пункте, налогоплательщик обязан отражать восстановленную сумму налога по окончании каждого календарного года в течение десяти лет начиная с года, в котором на основании пункта 4 статьи 259 настоящего Кодекса производится начисление амортизации с измененной первоначальной стоимости объекта основных средств, в налоговой декларации, представляемой в налоговые органы по месту своего учета за последний налоговый период каждого календарного года из десяти лет.\n\n7. Расчет суммы налога, подлежащей восстановлению и уплате в бюджет в соответствии с пунктом 6 настоящей статьи, производится исходя из одной десятой суммы налога, принятой к вычету по строительно-монтажным работам, а также по товарам (работам, услугам), приобретенным для выполнения строительно-монтажных работ при проведении модернизации (реконструкции), в соответствующей доле.\n\nУказанная доля определяется исходя из стоимости отгруженных товаров (выполненных работ, оказанных услуг), переданных имущественных прав, не облагаемых налогом и указанных в пункте 2 статьи 170 настоящего Кодекса, в общей стоимости товаров (работ, услуг), имущественных прав, отгруженных (переданных) за календарный год. При этом сумма налога, подлежащая восстановлению, в стоимость данного имущества не включается, а учитывается в составе прочих расходов в соответствии со статьей 264 настоящего Кодекса.\n\n8. В случае, если до истечения срока, указанного в пункте 3 настоящей статьи, модернизируемый (реконструируемый) объект основных средств исключается из состава амортизируемого имущества и не используется в деятельности налогоплательщика один год или несколько полных календарных лет, за эти годы восстановление сумм налога, принятых к вычету, не производится.\n\nПри этом начиная с года, в котором на основании пункта 4 статьи 259 настоящего Кодекса производится начисление амортизации с измененной первоначальной стоимости объекта основных средств, налогоплательщик обязан отражать восстановленную сумму налога в налоговой декларации, представляемой в налоговые органы по месту своего учета за последний налоговый период каждого календарного года из оставшихся до окончания десятилетнего срока, указанного в пункте 4 настоящей статьи.\n\n9. Расчет суммы налога, подлежащей восстановлению и уплате в бюджет в соответствии с пунктом 8 настоящей статьи, производится исходя из суммы налога, исчисленной как поделенная на количество лет, оставшихся до окончания десятилетнего срока, указанного в пункте 4 настоящей статьи, разница между суммой налога, указанной в пункте 2 настоящей статьи, принятой налогоплательщиком к вычету, и суммой налога, полученной в результате сложения одной десятой суммы на\n\nлога, указанной в пункте 5 настоящей статьи, за годы, предшествующие полному календарному году, в котором по модернизируемому (реконструируемому) объекту основных средств начисление амортизации не производится и объект основных средств не используется в деятельности налогоплательщика, в соответствующей доле.\n\nУказанная доля определяется исходя из стоимости отгруженных товаров (выполненных работ, оказанных услуг), переданных имущественных прав, не облагаемых налогом и указанных в пункте 2 статьи 170 настоящего Кодекса, в общей стоимости товаров (работ, услуг), имущественных прав, отгруженных (переданных) за календарный год. При этом сумма налога, подлежащая восстановлению, в стоимость этого имущества не включается, а учитывается в составе прочих расходов в соответствии со статьей 264 настоящего Кодекса.\n\nПри этом расчет суммы налога, подлежащей восстановлению по строительно-монтажным работам, а также по товарам (работам, услугам), приобретенным для выполнения строительно-монтажных работ при проведении модернизации (реконструкции), осуществляется в порядке, установленном пунктами 6 и 7 настоящей статьи.\n\n(Дополнение статьей - Федеральный закон от 24.11.2014 № 366-ФЗ)","article_title":"Статья 171.1. Восстановление сумм налога, принятых к вычету в отношении приобретенных или построенных объектов основных средств","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4f428b3ec3b6a8f17f849ed69d924505ac8ccd8c98cfad7e749572c060ca58f6"},{"code_id":"NK_RF_2","article_number":"172","version_date":"2000-07-31","article_text":"Вычетам подлежат, если иное не установлено настоящей статьей, только суммы налога, предъявленные налогоплательщику при приобретении товаров (работ, услуг), имущественных прав на территории Российской Федерации, либо фактически уплаченные ими при ввозе товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, после принятия на учет указанных товаров (работ, услуг), имущественных прав с учетом особенностей, предусмотренных настоящей статьей и при наличии соответствующих первичных документов. (В редакции федеральных законов от 29.12.2000 № 166-ФЗ; от 22.07.2005 № 119-ФЗ; от 27.11.2010 № 306-ФЗ)\n\nВычеты сумм налога, предъявленных продавцами налогоплательщику при приобретении либо уплаченных при ввозе на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, основных средств, оборудования к установке, и (или) нематериальных активов, указанных в пунктах 2 и 4 статьи 171 настоящего Кодекса, производятся в полном объеме после принятия на учет данных основных средств, оборудования к установке, и (или) нематериальных активов. В случае создания налогоплательщиком нематериальных активов (собственными силами и (или) с привлечением третьих лиц) вычеты сумм налога, предъявленных налогоплательщику при приобретении товаров (работ, услуг), имущественных прав на территории Российской Федерации либо фактически уплаченных им при ввозе товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, для создания таких нематериальных активов, в том числе сумм налога, предъявленных налогоплательщику по договорам на создание нематериальных активов, производятся после принятия на учет указанных товаров (работ, услуг), имущественных прав. (В редакции федеральных законов от 22.07.2005 № 119-ФЗ, от 28.02.2006 № 28-ФЗ, от 27.11.2010 № 306-ФЗ, от 29.09.2019 № 325-ФЗ)\n\nПри приобретении за иностранную валюту товаров (работ, услуг), имущественных прав иностранная валюта пересчитывается в рубли по курсу Центрального банка Российской Федерации на дату принятия на учет товаров (работ, услуг), имущественных прав. (Дополнение абзацем - Федеральный закон от 22.07.2005 № 119-ФЗ)\n\nПри приобретении товаров (работ, услуг), имущественных прав по договорам, обязательство об оплате которых предусмотрено в рублях в сумме, эквивалентной определенной сумме в иностранной валюте, или в условных денежных единицах, налоговые вычеты, произведенные в порядке, предусмотренном настоящей главой, при последующей оплате указанных товаров (работ, услуг), имущественных прав не корректируются. Разницы в сумме налога, возникающие у покупателя при последующей оплате, учитываются в составе внереализационных доходов в соответствии со статьей 250 настоящего Кодекса или в составе внереализационных расходов в соответствии со статьей 265 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 19.07.2011 № 245-ФЗ) (В редакции Федерального закона от 20.04.2014 № 81-ФЗ)\n\n11. Налоговые вычеты, предусмотренные пунктом 2 статьи 171 настоящего Кодекса, могут быть заявлены в налоговых периодах в пределах трех лет после принятия на учет приобретенных налогоплательщиком на территории Российской Федерации товаров (работ, услуг), имущественных прав или товаров, ввезенных им на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией.\n\nПри получении счета-фактуры покупателем от продавца товаров (работ, услуг), имущественных прав после завершения налогового периода, в котором эти товары (работы, услуги), имущественные права приняты на учет, но до установленного статьей 174 настоящего Кодекса срока представления налоговой декларации за указанный налоговый период покупатель вправе принять к вычету сумму налога в отношении таких товаров (работ, услуг), имущественных прав с того налогового периода, в котором указанные товары (работы, услуги), имущественные права были приняты на учет, с учетом особенностей, предусмотренных настоящей статьей.\n\n(Дополнение пунктом - Федеральный закон от 29.11.2014 № 382-ФЗ)\n\nВычеты сумм налога, указанных в пункте 10 статьи 171 настоящего Кодекса, производятся на дату, соответствующую моменту последующего исчисления налога по налоговой ставке 0 процентов в отношении операций по реализации товаров (работ, услуг), предусмотренных пунктом 1 статьи 164 настоящего Кодекса, при наличии на этот момент документов, предусмотренных статьей 165 настоящего Кодекса.\n\nПоложения настоящего пункта не распространяются на налогоплательщиков, отказавшихся от применения налоговой ставки, указанной в пункте 1 статьи 164 настоящего Кодекса, в порядке, установленном пунктом 7 статьи 164 настоящего Кодекса, а также на операции по реализации товаров, указанных в подпункте 1 (за исключением сырьевых товаров), подпунктах 12 и 6 пункта 1 статьи 164 настоящего Кодекса, и работ (услуг), указанных в подпункте 22 пункта 1 статьи 164 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 30.05.2016 № 150-ФЗ) (В редакции  федеральных законов от 27.11.2017 № 350-ФЗ, от 28.04.2023 № 173-ФЗ, от 24.06.2023 № 261-ФЗ)\n\n(Пункт в редакции Федерального закона от 22.07.2005 № 119-ФЗ)\n\nВычеты сумм налога, указанных в абзаце третьем пункта 5 статьи 171 настоящего Кодекса, производятся после выкупа налогоплательщиком цифровых прав, включающих одновременно цифровые финансовые активы и утилитарные цифровые права.\n\n(Пункт в редакции  Федерального закона от 14.07.2022 № 324-ФЗ)\n\nВычеты сумм налога, указанных в абзаце третьем пункта 6 статьи 171 настоящего Кодекса, производятся на момент определения налоговой базы, установленный пунктом 10 статьи 167 настоящего Кодекса. (В редакции Федерального закона от 26.11.2008 № 224-ФЗ)\n\nВ случае реорганизации организации вычет указанных в абзаце третьем пункта 6 статьи 171 настоящего Кодекса сумм налога, которые не были приняты реорганизованной (реорганизуемой) организацией к вычету до момента завершения реорганизации, производится правопреемником (правопреемниками) по мере уплаты в бюджет налога, исчисленного реорганизованной (реорганизуемой) организацией при выполнении строительно-монтажных работ для собственного потребления в соответствии со статьей 173 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 22.07.2005 № 118-ФЗ)\n\n(Пункт в редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nВычеты сумм налога, исчисленных исходя из оплаты, частичной оплаты в счет предстоящей передачи имущественных прав, в том числе цифровых прав, включающих одновременно цифровые финансовые активы и утилитарные цифровые права, в случаях, предусмотренных абзацем вторым пункта 1 и пунктами 2 - 4 и 6 статьи 155 настоящего Кодекса, производятся с даты передачи имущественных прав, в том числе указанных цифровых прав, в размере налога, исчисленного в соответствии с абзацем девятым пункта 1 статьи 154 настоящего Кодекса.\n\n(Пункт в редакции  Федерального закона от 14.07.2022 № 324-ФЗ)\n\nПри полном или частичном неподтверждении таможенным органом Российской Федерации факта вывоза товаров физическим лицом - гражданином иностранного государства, указанным в пункте 1 статьи 1691 настоящего Кодекса, за пределы таможенной территории Евразийского экономического союза (за исключением вывоза товаров через территории государств - членов Евразийского экономического союза) через пункты пропуска через Государственную границу Российской Федерации вычеты сумм налога производятся только в отношении товаров, фактический вывоз которых подтвержден таможенным органом Российской Федерации.\n\nВычеты сумм налога производятся в пределах одного года с даты компенсации суммы налога физическому лицу - гражданину иностранного государства, указанному в пункте 1 статьи 1691 настоящего Кодекса.\n\nОшибки в документах (чеках) для компенсации суммы налога, не препятствующие налоговым органам при проведении налоговой проверки идентифицировать налогоплательщика - организацию розничной торговли, иностранное государство, уполномоченным органом которого выдан паспорт физическому лицу - гражданину иностранного государства, указанному в пункте 1 статьи 1691 настоящего Кодекса, наименование реализованных товаров, а также сумму налога, исчисленную организацией розничной торговли по реализованным товарам, не являются основанием для отказа в принятии к вычету суммы налога.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2017 № 341-ФЗ)","article_title":"Статья 172. Порядок применения налоговых вычетов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bd52ee49ac476a9e1e72c55b23c01e255daf55e2b44d4dbc8357e23387a83b85"},{"code_id":"NK_RF_2","article_number":"173","version_date":"2000-07-31","article_text":"Абзац. (Утратил силу - Федеральный закон от 22.07.2005 № 119-ФЗ)\n\nАбзац. (Исключен - Федеральный закон от 29.05.2002 № 57-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 22.07.2005 № 119-ФЗ)\n\n1) лицами, не являющимися налогоплательщиками, или налогоплательщиками, освобожденными от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога; (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\n2) налогоплательщиками при реализации товаров (работ, услуг), операции по реализации которых не подлежат налогообложению. (В редакции Федерального закона от 29.05.2002 № 57-ФЗ)\n\nПри этом сумма налога, подлежащая уплате в бюджет, определяется как сумма налога, указанная в соответствующем счете-фактуре, переданном покупателю товаров (работ, услуг).\n\nстатьи 170 настоящего Кодекса, определяется в порядке, предусмотренном абзацем шестым пункта 31 статьи 170 настоящего Кодекса. (Дополнение пунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)","article_title":"Статья 173. Сумма налога, подлежащая уплате в бюджет","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f3c86666d9ccb25f9a65f9bc3204e817420e3cf5149de2e13dd4975620ae6675"},{"code_id":"NK_RF_2","article_number":"174","version_date":"2000-07-31","article_text":"Если иное не предусмотрено подпунктом 11 пункта 1 статьи 151 настоящего Кодекса, при ввозе товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, сумма налога, подлежащая уплате в бюджет, уплачивается в соответствии с таможенным законодательством Таможенного союза и законодательством Российской Федерации о таможенном деле. (В редакции федеральных законов от 27.11.2010 № 306-ФЗ; от 30.03.2016 № 72-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 08.12.2003 № 163-ФЗ) (Утратил силу  - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 08.12.2003 № 163-ФЗ) (Утратил силу  - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\nУплата налога правопреемниками, указанными в абзацах четвертом и пятом пункта 31 статьи 170 настоящего Кодекса, производится не позднее 28-го числа месяца, следующего за налоговым периодом, в котором сумма налога подлежит восстановлению в соответствии с настоящей главой. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nНалоговые агенты, не являющиеся налогоплательщиками или являющиеся налогоплательщиками, освобожденными от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога, а также правопреемники, указанные в абзацах четвертом и пятом пункта 31 статьи 170 настоящего Кодекса, обязаны представить в налоговые органы по месту своего учета соответствующую налоговую декларацию в срок не позднее 25-го числа месяца, следующего за истекшим налоговым периодом. (В редакции федеральных законов от 29.11.2014 № 382-ФЗ, от 29.09.2019 № 325-ФЗ)\n\nУказанные в абзаце втором настоящего пункта лица в случае выставления и (или) получения ими счетов-фактур при осуществлении предпринимательской деятельности в интересах другого лица на основе договоров комиссии, агентских договоров, предусматривающих реализацию и (или) приобретение товаров (работ, услуг), имущественных прав от имени комиссионера (агента), или на основе договоров транспортной экспедиции (если при определении налоговой базы в порядке, установленном главами 23, 25, 261 и 262 настоящего Кодекса, в составе доходов учитываются доходы в виде вознаграждения при исполнении договоров транспортной экспедиции), а также при выполнении функций застройщика обязаны представить в налоговые органы по месту своего учета не позднее 25-го числа месяца, следующего за истекшим налоговым периодом, соответствующую налоговую декларацию по установленному формату в электронной форме по телекоммуникационным каналам связи через оператора электронного документооборота. (В редакции Федерального закона от 29.11.2014 № 382-ФЗ)\n\nПри представлении налоговой декларации на бумажном носителе в случае, если настоящим пунктом предусмотрена обязанность представления налоговой декларации (расчета) в электронной форме, такая декларация не считается представленной. (Дополнение абзацем - Федеральный закон от 04.11.2014 № 347-ФЗ)\n\n(Пункт в редакции Федерального закона от 28.06.2013 № 134-ФЗ)\n\nВ случае выставления и (или) получения счетов-фактур при осуществлении налогоплательщиком (налоговым агентом) предпринимательской деятельности в интересах другого лица на основе договоров комиссии, агентских договоров, предусматривающих реализацию и (или) приобретение товаров (работ, услуг), имущественных прав от имени комиссионера (агента), или на основе договоров транспортной экспедиции, а также при выполнении функций застройщика в налоговую декларацию включаются сведения, указанные в журнале учета полученных и выставленных счетов-фактур в отношении указанной деятельности.\n\nЛица, указанные в пункте 5 статьи 173 настоящего Кодекса, включают в налоговую декларацию сведения, указанные в выставленных счетах-фактурах.\n\nСостав сведений, указанных в книге покупок и книге продаж, в журнале учета полученных и выставленных счетов-фактур, в выставленных счетах-фактурах, включаемых в налоговую декларацию, определяется федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение пунктом - Федеральный закон от 28.06.2013 № 134-ФЗ)\n\nПеречень контрольных соотношений, указанных в настоящем пункте, утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение пунктом - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nВ случае представления налогоплательщиком (налоговым агентом, лицом, указанным в пункте 5 статьи 173 настоящего Кодекса) в срок, установленный настоящим пунктом, налоговой декларации, в которой устранены несоответствия контрольным соотношениям, указанным в пункте 53 настоящей статьи, датой представления указанной налоговой декларации считается дата представления налоговой декларации, которая в соответствии с пунктом 53 настоящей статьи была признана непредставленной.\n\n(Дополнение пунктом - Федеральный закон от 23.11.2020 № 374-ФЗ)","article_title":"Статья 174. Порядок и сроки уплаты налога в бюджет","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"36a77ca496d78a98a0ca9f18a4e29a22552a2bc4597e6247c8ee33b90426c50b"},{"code_id":"NK_RF_2","article_number":"174.1","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 30.06.2008 № 108-ФЗ; от 28.11.2011 № 336-ФЗ)\n\n1. В целях настоящей главы ведение общего учета операций, подлежащих налогообложению в соответствии со статьей 146 настоящего Кодекса, возлагается на участника товарищества, которым являются российская организация либо индивидуальный предприниматель (далее в настоящей статье - участник товарищества).\n\nПри совершении операций в соответствии с договором простого товарищества (договором о совместной деятельности), договором инвестиционного товарищества, концессионным соглашением или договором доверительного управления имуществом на участника товарищества, концессионера или доверительного управляющего возлагаются обязанности налогоплательщика, установленные настоящей главой. (В редакции  федеральных законов от 30.06.2008 № 108-ФЗ, от 28.11.2011 № 336-ФЗ, от 02.07.2021 № 307-ФЗ, от 12.07.2024 № 176-ФЗ)\n\nПри осуществлении участником товарищества, ведущим общий учет операций в целях налогообложения, концессионером или доверительным управляющим иной деятельности право на вычет сумм налога возникает при наличии раздельного учета товаров (работ, услуг), в том числе основных средств и нематериальных активов, и имущественных прав, используемых при осуществлении операций в соответствии с договором простого товарищества (договором о совместной деятельности), договором инвестиционного товарищества, концессионным соглашением или договором доверительного управления имуществом и используемых им при осуществлении иной деятельности. (В редакции федеральных законов от 30.06.2008 № 108-ФЗ; от 28.11.2011 № 336-ФЗ)\n\nУчастник договора инвестиционного товарищества - управляющий товарищ, ответственный за ведение налогового учета, в срок, предусмотренный пунктом 5 статьи 174 настоящего Кодекса, представляет в налоговый орган по месту своего учета отдельную налоговую декларацию по каждому договору инвестиционного товарищества.\n\n(Дополнение пунктом - Федеральный закон от 23.07.2013 № 248-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 22.07.2005 № 119-ФЗ)","article_title":"Статья 174.1. Особенности исчисления и уплаты в бюджет налога при осуществлении операций в соответствии с договором простого товарищества (договором о совместной деятельности), договором инвестиционного товарищества, договором доверительного управления имуществом или концессионным соглашением на территории Российской Федерации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6e09753523df3d854cab9537955a8f670178c412a2c3b8bb5746fc952763b787"},{"code_id":"NK_RF_2","article_number":"174.2","version_date":"2000-07-31","article_text":"1. В целях настоящей главы оказанием услуг в электронной форме признается оказание услуг через информационно-телекоммуникационную сеть, в том числе через информационно-телекоммуникационную сеть \"Интернет\" (далее в настоящей статье - сеть \"Интернет\"), автоматизированно с использованием информационных технологий. К таким услугам относятся:\n\nпредоставление прав на использование программ для электронных вычислительных машин (включая компьютерные игры), баз данных через сеть \"Интернет\", в том числе путем предоставления удаленного доступа к ним, включая обновления к ним и дополнительные функциональные возможности;\n\nоказание рекламных услуг в сети \"Интернет\", в том числе с использованием программ для электронных вычислительных машин и баз данных, функционирующих в сети \"Интернет\", а также предоставление рекламной площади (пространства) в сети \"Интернет\";\n\nоказание услуг по размещению предложений о приобретении (реализации) товаров (работ, услуг), имущественных прав в сети \"Интернет\";\n\nоказание через сеть \"Интернет\" услуг по предоставлению технических, организационных, информационных и иных возможностей, осуществляемых с использованием информационных технологий и систем, для установления контактов и заключения сделок между продавцами и покупателями (включая предоставление торговой площадки, функционирующей в сети \"Интернет\" в режиме реального времени, на которой потенциальные покупатели предлагают свою цену посредством автоматизированной процедуры и стороны извещаются о продаже путем отправляемого автоматически создаваемого сообщения);\n\nобеспечение и (или) поддержание коммерческого или личного присутствия в сети \"Интернет\", поддержка электронных ресурсов пользователей (сайтов и (или) страниц сайтов в сети \"Интернет\"), обеспечение доступа к ним других пользователей сети, предоставление пользователям возможности их модификации;\n\nхранение и обработка информации при условии, что лицо, представившее эту информацию, имеет к ней доступ через сеть \"Интернет\";\n\nпредоставление в режиме реального времени вычислительной мощности для размещения информации в информационной системе;\n\nпредоставление доменных имен, оказание услуг хостинга;\n\nоказание услуг по администрированию информационных систем, сайтов в сети \"Интернет\";\n\nоказание услуг, осуществляемых автоматическим способом через сеть \"Интернет\" при вводе данных покупателем услуги, автоматизированных услуг по поиску данных, их отбору и сортировке по запросам, предоставлению указанных данных пользователям через информационно-телекоммуникационные сети (в частности, сводки фондовой биржи в режиме реального времени, осуществление в режиме реального времени автоматизированного перевода);\n\nпредоставление прав на использование электронных книг (изданий) и других электронных публикаций, информационных, образовательных материалов, графических изображений, музыкальных произведений с текстом или без текста, аудиовизуальных произведений через сеть \"Интернет\", в том числе путем предоставления удаленного доступа к ним для просмотра или прослушивания через сеть \"Интернет\";\n\nоказание услуг по поиску и (или) представлению заказчику информации о потенциальных покупателях;\n\nпредоставление доступа к поисковым системам в сети \"Интернет\";\n\nведение статистики на сайтах в сети \"Интернет\".\n\nВ целях настоящей главы к услугам в электронной форме, указанным в абзаце первом настоящего пункта, не относятся, в частности, следующие операции:\n\nреализация товаров (работ, услуг), если при заказе через сеть \"Интернет\" поставка товаров (выполнение работ, оказание услуг) осуществляется без использования сети \"Интернет\";\n\nреализация (передача прав на использование) программ для электронных вычислительных машин (включая компьютерные игры), баз данных на материальных носителях;\n\nоказание консультационных услуг по электронной почте;\n\nоказание услуг по предоставлению доступа к сети \"Интернет\".\n\nПри оказании иностранными организациями физическим лицам услуг в электронной форме, указанных в пункте 1 настоящей статьи\n\n, местом реализации которых признается территория Российской Федерации, иностранные организации - посредники, осуществляющие предпринимательскую деятельность с участием в расчетах непосредственно с физическими лицами - потребителями услуг на основании договоров поручения, договоров комиссии, агентских договоров или иных аналогичных договоров с иностранными организациями, оказывающими такие услуги, признаются в целях настоящей главы налоговыми агентами. В случае оказания таких услуг с участием в расчетах нескольких организаций-посредников налоговым агентом признается иностранная организация - посредник, осуществляющая предпринимательскую деятельность с участием в расчетах непосредственно с физическими лицами - потребителями услуг независимо от наличия у нее договора с иностранной организацией, оказывающей услуги. Налоговый агент обязан исчислить и уплатить соответствующую сумму налога.\n\n(Пункт в редакции  Федерального закона от 14.07.2022 № 323-ФЗ)\n\nПри определении налоговой базы в соответствии с настоящей статьей стоимость указанных в абзаце первом настоящего пункта услуг в иностранной валюте пересчитывается в рубли по курсу Центрального банка Российской Федерации, установленному на последний день налогового периода, в котором поступила оплата (частичная оплата) таких услуг.\n\n(Пункт в редакции Федерального закона от 27.11.2017 № 335-ФЗ)\n\nВ случае, если исчисление и уплата (перечисление) налога в соответствии с настоящей статьей производятся налоговым агентом, налоговая декларация представляется в налоговый орган таким налоговым агентом. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n10. При оказании иностранными организациями услуг в электронной форме, указанных в пункте 1 настоящей статьи, местом реализации которых признается территория Российской Федерации (за исключением оказания услуг через обособленное подразделение иностранной организации, расположенное на территории Российской Федерации), налоговыми агентами признаются российские организации, индивидуальные предприниматели или обособленные подразделения иностранных организаций, расположенные на территории Российской Федерации, - посредники, состоящие на учете в налоговых органах и осуществляющие предпринимательскую деятельность с участием в расчетах непосредственно с покупателем на основании договоров поручения, комиссии, агентских или иных аналогичных договоров с иностранными организациями, оказывающими такие услуги. В случае оказания таких услуг с участием в расчетах нескольких посредников налоговым агентом признается российская организация, индивидуальный предприниматель или обособленное подразделение иностранной организации, расположенное на территории Российской Федерации, - посредники, состоящие на учете в налоговых органах и осуществляющие расчеты непосредственно с покупателем независимо от наличия у них договора с иностранной организацией, оказывающей такие услуги.\n\nУказанные налоговые агенты производят исчисление и уплату налога в порядке, предусмотренном пунктом 5 статьи 161 настоящего Кодекса, с учетом особенностей, предусмотренных пунктом 4 настоящей статьи.\n\nВ целях настоящего пункта не признаются посредниками организации, являющиеся субъектами национальной платежной системы, а также операторы связи, указанные в Федеральном законе от 27 июня 2011 года № 161-ФЗ \"О национальной платежной системе\", в рамках осуществления переводов денежных средств за услуги, предусмотренные в пункте 1 настоящей статьи. (Дополнение абзацем - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\n11. Уплата сумм недоимки по налогу, задолженности по пеням и штрафам, восстановленных в соответствии с пунктом 11 статьи 59 настоящего Кодекса, производится указанными иностранными организациями в течение одного месяца начиная со дня постановки на учет в налоговом органе в соответствии с пунктом 46 статьи 83 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 03.07.2016 № 244-ФЗ)","article_title":"Статья 174.2. Особенности исчисления и уплаты налога при оказании иностранными организациями услуг в электронной форме","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c5856370b59bf2a89bcbd9b76d1fc328f2eed3d7653ecc2ab7d608e5b1237283"},{"code_id":"NK_RF_2","article_number":"174.3","version_date":"2000-07-31","article_text":"1. При реализации физическим лицам посредством электронных торговых площадок товаров, местом реализации которых согласно подпункту 4 пункта 1 статьи 147 настоящего Кодекса признается территория Российской Федерации, исчисление и уплата налога производятся:\n\n1) организациями, созданными в соответствии с законодательством государств - членов Евразийского экономического союза (кроме Российской Федерации), и физическими лицами, зарегистрированными в качестве индивидуальных предпринимателей в соответствии с законодательством государств - членов Евразийского экономического союза (кроме Российской Федерации), осуществляющими реализацию товаров (за исключением реализации товаров через обособленные подразделения организаций, созданных в соответствии с законодательством государств - членов Евразийского экономического союза (кроме Российской Федерации), расположенных на территории Российской Федерации) посредством принадлежащих им электронных торговых площадок (далее в настоящей статье - иностранные продавцы);\n\n2) налоговыми агентами, которыми в целях настоящей главы признаются организации, созданные в соответствии с законодательством государств - членов Евразийского экономического союза (кроме Российской Федерации), и физические лица, зарегистрированные в качестве индивидуальных предпринимателей в соответствии с законодательством государств - членов Евразийского экономического союза (кроме Российской Федерации), посредством электронных торговых площадок которых на основании договоров комиссии, агентских договоров, договоров поручения или иных аналогичных договоров реализуются товары организаций, созданных в соответствии с законодательством государств - членов Евразийского экономического союза, и физических лиц, зарегистрированных в качестве индивидуальных предпринимателей в соответствии с законодательством государств - членов Евразийского экономического союза (далее в настоящей статье - иностранные посредники);\n\n3) налоговыми агентами, которыми в целях настоящей главы признаются российские организации и индивидуальные предприниматели, посредством электронных торговых площадок которых на основании договоров комиссии, агентских договоров, договоров поручения реализуются товары организаций, созданных в соответствии с законодательством государств - членов Евразийского экономического союза (кроме Российской Федерации), и физических лиц, зарегистрированных в качестве индивидуальных предпринимателей в соответствии с законодательством государств - членов Евразийского экономического союза (кроме Российской Федерации) (далее в настоящей статье - российские посредники).\n\n2. При реализации иностранными продавцами, иностранными и российскими посредниками покупателям - физическим лицам товаров, местом реализации которых признается территория Российской Федерации на основании подпункта 4 пункта 1 статьи 147 настоящего Кодекса, моментом определения налоговой базы является последний день налогового периода, в котором поступила оплата (частичная оплата) реализованных товаров. При этом налоговая база определяется как стоимость указанных товаров с учетом суммы налога, исчисленная исходя из фактических цен их реализации.\n\nПри определении налоговой базы в соответствии с настоящей статьей стоимость товара в иностранной валюте пересчитывается в рубли по курсу Центрального банка Российской Федерации, установленному на последний день налогового периода, в котором поступила оплата (частичная оплата) такого товара.\n\nПри возврате ранее реализованного товара либо при отказе покупателя - физического лица от поставки оплаченного товара сумма налога, исчисленная иностранным продавцом или иностранным посредником по такому товару, может быть использована ими для уменьшения исчисленной суммы налога, подлежащей уплате за налоговый период, в котором полностью или частично осуществлен возврат стоимости такого товара покупателю - физическому лицу. В случае превышения суммы налога, исчисленной по такому товару, над суммой налога, подлежащей уплате за налоговый период, в котором полностью или частично осуществлен возврат стоимости такого товара покупателю - физическому лицу, на положительную разницу между указанными суммами налога может быть уменьшена сумма налога, подлежащая уплате иностранным продавцом или иностранным посредником в последующих налоговых периодах, но не позднее трех лет с даты окончания налогового периода, в котором произведен возврат товара.\n\n3. Сумма налога исчисляется иностранными продавцами, иностранными посредниками и российскими посредниками, указанными в пункте 1 настоящей статьи, и определяется как соответствующая расчетной налоговой ставке в размере 16,67 процента или 9,09 процента (в случаях, предусмотренных пунктом 2 статьи 164 настоящего Кодекса) процентная доля налоговой базы.\n\n4. Уплата налога иностранными продавцами и иностранными посредниками, указанными в пункте 1 настоящей статьи, производится не позднее 28-го числа месяца, следующего за истекшим налоговым периодом.\n\n5. Суммы налога, предъявленные иностранным продавцам, иностранным посредникам, подлежащим постановке на учет в налоговых органах в соответствии с пунктом 46 статьи 83 настоящего Кодекса (за исключением сумм налога, предъявленных их обособленным подразделениям, расположенным на территории Российской Федерации), при приобретении товаров (работ, услуг), в том числе основных средств и нематериальных активов, на территории Российской Федерации либо фактически уплаченные при ввозе товаров, в том числе основных средств и нематериальных активов, на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, вычету не подлежат.\n\n6. Иностранные продавцы, иностранные посредники, подлежащие постановке на учет в соответствии с пунктом 46 статьи 83 настоящего Кодекса, представляют в налоговый орган налоговую декларацию в электронной форме через личный кабинет налогоплательщика по формату, предусмотренному пунктом 8 статьи 1742 настоящего Кодекса, а в период, когда личный кабинет налогоплательщика не может использоваться такими иностранными продавцами, иностранными посредниками для представления в налоговый орган документов (информации), сведений в соответствии с абзацем третьим пункта 3 статьи 112 настоящего Кодекса, - по телекоммуникационным каналам связи через оператора электронного документооборота не позднее 25-го числа месяца, следующего за истекшим налоговым периодом.\n\nРоссийские посредники, указанные в подпункте 3 пункта 1 настоящей статьи, производят уплату налога и представляют в налоговый орган налоговую декларацию, предусмотренную статьей 174 настоящего Кодекса, в порядке и сроки, которые предусмотрены статьей 174 настоящего Кодекса.\n\n7. Уплата суммы задолженности, восстановленной в соответствии с пунктом 11 статьи 59 настоящего Кодекса, производится иностранными продавцами и иностранными посредниками, указанными в настоящей статье, в течение одного месяца начиная со дня постановки на учет в налоговом органе в соответствии с пунктом 46 статьи 83 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 29.05.2024 № 100-ФЗ)","article_title":"Статья 174.3. Особенности исчисления и уплаты налога при реализации товаров Евразийского экономического союза физическим лицам посредством электронных торговых площадок","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"478d9934a334cc9e8da5dbe03593c6b8274944acbfa7a10460b90fe170943a6e"},{"code_id":"NK_RF_2","article_number":"175","version_date":"2000-07-31","article_text":"(Статья исключена - Федеральный закон от 29.05.2002 № 57-ФЗ)","article_title":"Статья 175. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"486a7cbf6b68b0e602fd136af1b46bc117a914c97a86781ad35851a76cacef35"},{"code_id":"NK_RF_2","article_number":"176","version_date":"2000-07-31","article_text":"1. В случае, если по итогам налогового периода сумма налоговых вычетов превышает общую сумму налога, исчисленную по операциям, признаваемым объектом налогообложения в соответствии с подпунктами 1 - 3 пункта 1 статьи 146 настоящего Кодекса, полученная разница подлежит возмещению налогоплательщику в соответствии с положениями настоящей статьи.\n\nПосле представления налогоплательщиком налоговой декларации налоговый орган проверяет обоснованность суммы налога, заявленной к возмещению, при проведении камеральной налоговой проверки в порядке, установленном статьей 88 настоящего Кодекса, если иное не предусмотрено настоящим пунктом.\n\nНалогоплательщики, указанные в подпункте 6 пункта 2 статьи 1761 настоящего Кодекса, реализуют право на возмещение суммы налога, указанной в абзаце первом настоящего пункта, в порядке, установленном статьей 1761 настоящего Кодекса.\n\n2. По окончании проверки в течение семи дней налоговый орган обязан принять решение о возмещении соответствующих сумм, если при проведении камеральной налоговой проверки не были выявлены нарушения законодательства о налогах и сборах.\n\n3. В случае выявления нарушений законодательства о налогах и сборах в ходе проведения камеральной налоговой проверки уполномоченными должностными лицами налоговых органов должен быть составлен акт налоговой проверки в соответствии со статьей 100 настоящего Кодекса.\n\nАкт и другие материалы камеральной налоговой проверки, в ходе которой были выявлены нарушения законодательства о налогах и сборах, а также представленные налогоплательщиком (его представителем) возражения должны быть рассмотрены руководителем (заместителем руководителя) налогового органа, проводившего налоговую проверку, и решение по ним должно быть принято в соответствии со статьей 101 настоящего Кодекса.\n\nПо результатам рассмотрения материалов камеральной налоговой проверки руководитель (заместитель руководителя) налогового органа выносит решение о привлечении налогоплательщика к ответственности за совершение налогового правонарушения либо об отказе в привлечении налогоплательщика к ответственности за совершение налогового правонарушения.\n\nОдновременно с этим решением принимаются:\n\nрешение о возмещении полностью суммы налога, заявленной к возмещению;\n\nрешение об отказе в возмещении полностью суммы налога, заявленной к возмещению;\n\nрешение о возмещении частично суммы налога, заявленной к возмещению, и решение об отказе в возмещении частично суммы налога, заявленной к возмещению.\n\n4. Налоговый орган обязан сообщить в письменной форме налогоплательщику о принятом решении о возмещении (полностью или частично) или об отказе в возмещении в течение пяти дней со дня принятия соответствующего решения.\n\nУказанное сообщение может быть передано руководителю организации, индивидуальному предпринимателю, их представителям лично под расписку или иным способом, подтверждающим факт и дату его получения.\n\n5. В случаях и порядке, которые предусмотрены статьей 1761 настоящего Кодекса, налогоплательщики вправе воспользоваться заявительным порядком возмещения налога.\n\n(Статья в редакции Федерального закона от 14.07.2022 № 263-ФЗ)","article_title":"Статья 176. Порядок возмещения налога","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"538723a20fb7e1acc9134fb774224fdb0955cb0711784dee361c72ee2f431960"},{"code_id":"NK_RF_2","article_number":"176.1","version_date":"2000-07-31","article_text":"Для налогоплательщиков, указанных в подпункте 6 пункта 2 настоящей статьи, заявительный порядок возмещения налога представляет собой осуществление в порядке, предусмотренном настоящей статьей, возмещения суммы налога, заявленной к возмещению в налоговой декларации, за налоговый период года, за который проводится (проведен) налоговый мониторинг, в порядке, установленном настоящей статьей. (Дополнение абзацем - Федеральный закон от 29.12.2020 № 470-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n1) налогоплательщики-организации, у которых совокупная сумма налога на добавленную стоимость, акцизов, налога на прибыль организаций и налога на добычу полезных ископаемых, уплаченная за три календарных года, предшествующие году, в котором подается заявление о применении заявительного порядка возмещения налога, без учета сумм налогов, уплаченных в связи с перемещением товаров через границу Российской Федерации и в качестве налогового агента, составляет не менее 2 миллиардов рублей. Указанные налогоплательщики вправе применить заявительный порядок возмещения налога, если со дня создания соответствующей организации до дня подачи налоговой декларации прошло не менее трех лет и если на дату подачи заявления о применении заявительного порядка возмещения налога в отношении указанных налогоплател\n\nьщиков не возбуждено производство по делу о несостоятельности (банкротстве) в соответствии с законодательством Российской Федерации о несостоятельности (банкротстве); (В редакции  федеральных законов от 27.11.2010 № 306-ФЗ, от 29.12.2015 № 397-ФЗ, от 03.08.2018 № 302-ФЗ, от 31.07.2023 № 389-ФЗ)\n\n2) налогоплательщики, представившие в налоговый орган налоговую декларацию, в которой заявлено право на возмещение налога, в случае, если исполнение обязательства по возврату суммы налога, заявленной к возмещению, в бюджет в полном объеме обеспечивается действующей банковской гарантией (банковскими гарантиями), представленной (представленными) гарантом (гарантами) в порядке, предусмотренном статьей 741 настоящего Кодекса.\n\nБанковская гарантия подлежит направлению в налоговый орган гарантом не позднее дня, следующего за днем выдачи банковской гарантии.\n\nБанковская гарантия (банковские гарантии) должна (должны) предусматривать обязательство гаранта (гарантов) на основании требования налогового органа уплатить в бюджет за налогоплательщика сумму налога, излишне полученную им в результате возмещения налога в заявительном порядке, если решение о возмещении суммы налога, заявленной к возмещению в заявительном порядке, будет отменено полностью или частично в случаях, предусмотренных настоящей статьей;\n\n(Подпункт в редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n3) (Дополнение подпунктом - Федеральный закон от 29.11.2014 № 380-ФЗ) (Утратил силу  - Федеральный закон от 19.12.2023 № 611-ФЗ)\n\n4) (Дополнение подпунктом - Федеральный закон от 13.07.2015 № 214-ФЗ) (Утратил силу - Федеральный закон от 19.12.2023 № 611-ФЗ)\n\n5) налогоплательщики, обязанность которых по уплате налога обеспечена поручительством в соответствии со статьей 74 настоящего Кодекса, предусматривающим обязательство поручителя (поручителей) на основании требования налогового органа уплатить в бюджет за налогоплательщика сумму налога, излишне полученную им в результате возмещения налога в заявительном порядке, если решение о возмещении суммы налога, заявленной к возмещению в заявительном порядке, будет отменено полностью или частично в случаях, предусмотренных настоящей статьей; (Дополнение подпунктом - Федеральный закон от 30.11.2016 № 401-ФЗ) (В редакции  федеральных законов от 14.07.2022 № 263-ФЗ, от 31.07.2023 № 389-ФЗ)\n\n6) налогоплательщики, в отношении которых проводится налоговый мониторинг на дату представления налоговой декларации, указанной в пункте 1 настоящей статьи; (Дополнение подпунктом - Федеральный закон от 29.12.2020 № 470-ФЗ)\n\n7) налогоплательщики-организации, которые осуществляют производство вакцины для профилактики новой коронавирусной инфекции и информация о которых содержится в регистрационном удостоверении такой вакцины; (Дополнение подпунктом - Федеральный закон от 02.07.2021 № 306-ФЗ)\n\n8) налогоплательщики, в отношении которых на дату представления заявления о применении заявительного порядка возмещения налога одновременно соблюдаются следующие требования:\n\nналогоплательщик не находится в процессе реорганизации или ликвидации;\n\nв отношении налогоплательщика не возбуждено производство по делу о несостоятельности (банкротстве) в соответствии с законодательством Российской Федерации о несостоятельности (банкротстве).\n\nУказанные в настоящем подпункте налогоплательщики имеют право на применение заявительного порядка возмещения налога за налоговые периоды 2022 - 2025 годов. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nПоложения настоящего подпункта применяются с учетом особенностей, установленных пунктом 22 настоящей статьи.\n\n(Дополнение подпунктом - Федеральный закон от 26.03.2022 № 67-ФЗ)\n\n1) являться российской организацией;\n\n2) совокупная сумма налога на добавленную стоимость, акцизов, налога на прибыль организаций и налога на добычу полезных ископаемых, уплаченная поручителем в течение трех лет, предшествующих году, в котором представлено заявление о заключении договора поручительства, без учета сумм налогов, уплаченных в связи с перемещением товаров через границу Российской Федерации и в качестве налогового агента, составляет не менее 2 миллиардов рублей; (В редакции Федерального закона от 03.08.2018 № 302-ФЗ)\n\n3) сумма обязательств поручителя по действующим договорам поручительства (включая договор поручительства, указанный в подпункте 5 пункта 2 настоящей статьи, в отношении налогоплательщика), заключенным в соответствии с настоящим Кодексом, на дату представления заявления о заключении договора поручительства, указанного в подпункте 5 пункта 2 настоящей статьи, не превышает 50 процентов стоимости чистых активов поручителя, определенной по состоянию на 31 декабря календарного года, предшествующего году, в котором представлено заявление о заключении договора поручительства, указанного в подпункте 5 пункта 2 настоящей статьи; (В редакции Федерального закона от 03.08.2018 № 302-ФЗ)\n\n4) поручитель на дату представления заявления о заключении договора поручительства, указанного в подпункте 5 пункта 2 настоящей статьи, не находится в процессе реорганизации или ликвидации;\n\n5) в отношении поручителя на дату представления заявления о заключении договора поручительства, указанного в подпункте 5 пункта 2 настоящей статьи, не возбуждено производство по делу о несостоятельности (банкротстве) в соответствии с законодательством Российской Федерации о несостоятельности (банкротстве);\n\n6) поручитель на дату представления заявления о заключении договора поручительства, указанного в подпункте 5 пункта 2 настоящей статьи, имеет положительное либо нулевое сальдо единого налогового счета. (В редакции  федеральных законов от 03.08.2018 № 302-ФЗ, от 14.07.2022 № 263-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 30.11.2016 № 401-ФЗ)\n\nВ случае превышения заявленной к возмещению за налоговый период суммы налога над совокупной суммой налогов и страховых взносов, указанной в абзаце первом настоящего пункта, налогоплательщики, указанные в подпункте 8 пункта 2 настоящей статьи, имеют право на применение заявительного порядка возмещения в части такого превышения при представлении действующей банковской гарантии или поручительства, предусмотренных подпунктами 2 и 5 пункта 2 настоящей статьи.\n\n(Дополнение пунктом - Федеральный закон от 26.03.2022 № 67-ФЗ)\n\n1) срок действия банковской гарантии должен истекать не ранее чем через 10 месяцев со дня подачи налоговой декларации (уточненной налоговой декларации), в которой заявлена сумма налога к возмещению;\n\n2) сумма, на которую выдана (выданы) банковская гарантия (банковские гарантии), должна обеспечивать исполнение обязательств по возврату в бюджет в полном объеме суммы налога, заявляемой к возмещению в заявительном порядке.\n\n(Пункт в редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n1) срок действия договора поручительства должен истекать не ранее чем через 10 месяцев со дня подачи налоговой декларации, в которой заявлена сумма налога к возмещению, и должен быть не более одного года со дня заключения договора поручительства; (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\n2) сумма, указанная в договоре поручительства (договорах поручительства), должна обеспечивать исполнение обязательств по возврату в бюджет в полном объеме суммы налога, заявляемой к возмещению в заявительном порядке. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.11.2014 № 380-ФЗ)\n\nВ случае, предусмотренном подпунктом 5 пункта 2 настоящей статьи, договор поручительства (договоры поручительства) должен (должны) быть заключен (заключены) с налоговым органом не позднее срока, предусмотренного пунктом 7 настоящей статьи для подачи заявления о применении заявительного порядка возмещения налога (заявления о замене договора поручительства).\n\n(Дополнение пунктом - Федеральный закон от 19.07.2011 № 245-ФЗ) (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nНалогоплательщики, указанные в подпункте 6 пункта 2 настоящей статьи, реализуют свое право на применение заявительного порядка возмещения налога путем подачи в налоговый орган в электронной форме по телекоммуникационным каналам связи либо через информационные системы организации, к которым предоставлен доступ налоговому органу, в ходе проведения налогового мониторинга заявления о применении заявительного порядка возмещения налога, в котором налогоплательщик вправе указать для возврата денежных средств реквизиты открытого им счета в банке. (Дополнение абзацем - Федеральный закон от 29.12.2020 № 470-ФЗ) (В редакции  федеральных законов от 28.12.2022 № 565-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nВ указанных заявлениях налогоплательщики принимают на себя обязательство вернуть в бюджет излишне полученные ими в заявительном порядке суммы (включая проценты, предусмотренные пунктом 9 статьи 79 настоящего Кодекса (в случае их уплаты), а также уплатить начисленные на указанные суммы проценты в порядке, установленном пунктом 17 настоящей статьи, в случае, если решение о возмещении суммы налога, заявленной к возмещению, в заявительном порядке будет отменено полностью или частично в случаях, предусмотренных настоящей статьей. (В редакции  федеральных законов от 29.12.2020 № 470-ФЗ, от 14.07.2022 № 263-ФЗ, от 28.12.2022 № 565-ФЗ)\n\nВ срок не позднее пяти дней со дня представления налоговой декларации (уточненной налоговой декларации) налогоплательщик вправе подать заявление о замене банковской гарантии (банковских гарантий), представленной (представленных) гарантом (гарантами) в отношении представленной налогоплательщиком налоговой декларации (в том числе ранее представленной налоговой декларации, по которой вынесено решение о возмещении суммы налога, заявленной к возмещению в заявительном порядке), на новую банковскую гарантию (новые банковские гарантии). (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nВ срок не позднее пяти дней со дня представления налоговой декларации (уточненной налоговой декларации) налогоплательщик вправе подать заявление о замене договора поручительства (договоров поручительства), заключенного (заключенных) в отношении представленной налоговой декларации (в том числе ранее представленной налоговой декларации, по которой вынесено решение о возмещении суммы налога, заявленной к возмещению в заявительном порядке), на новый договор поручительства (новые договоры поручительства). (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nВ случае, если сумма налога, заявленная к возмещению в уточненной налоговой декларации, превышает сумму налога, возмещенную налогоплательщику при применении заявительного порядка в отношении ранее представленной налоговой декларации, налогоплательщик вправе подать заявление о применении заявительного порядка возмещения налога в пределах суммы налога, составляющей такое превышение. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nо возмещении суммы налога, заявленной к возмещению в заявительном порядке;\n\nоб отказе в возмещении суммы налога, заявленной к возмещению в заявительном порядке.\n\nВ случае применения налогоплательщиками заявительного порядка возмещения налога в соответствии с подпунктом 2 или 5 пункта 2 настоящей статьи решения, указанные в абзацах втором и третьем настоящего пункта, выносятся в течение пяти дней со дня представления заявления о применении заявительного порядка возмещения налога и банковской гарантии (банковских гарантий) (договора поручительства (договоров поручительства) при условии соблюдения сроков для представления указанных документов.\n\nВ течение пяти дней со дня подачи налогоплательщиком заявления о замене банковской гарантии (банковских гарантий) (договора поручительства (договоров поручительства) налоговый орган проверяет соблюдение требований, предусмотренных пунктами 2, 4, 41, 61 и 7 настоящей статьи, и принимает одно из следующих решений:\n\nо замене банковской гарантии (банковских гарантий) (договора поручительства (договоров поручительства) в отношении ранее представленной налоговой декларации, по которой вынесено решение о возмещении суммы налога, заявленной к возмещению в заявительном порядке;\n\nоб отказе в замене банковской гарантии (банковских гарантий) (договора поручительства (договоров поручительства) в отношении ранее представленной налоговой декларации, по которой вынесено решение о возмещении суммы налога, заявленной к возмещению в заявительном порядке.\n\nУказанные в настоящем пункте решения в течение пяти дней со дня их вынесения должны быть вручены налогоплательщику, в отношении которого они были вынесены, либо его представителю под расписку или переданы иным способом, свидетельствующим о дате получения указанных решений этим налогоплательщиком (его представителем). В случае, если указанные решения невозможно вручить или передать иным способом, свидетельствующим о дате их получения, они направляются по почте заказным письмом по месту нахождения налогоплательщика, месту жительства физического лица.\n\nПринятие решения об отказе в возмещении суммы налога, заявленной к возмещению в заявительном порядке, и (или) решения об отказе в замене банковской гарантии (банковских гарантий) (договора поручительства (договоров поручительства) в отношении ранее представленной налоговой декларации, по которой вынесено решение о возмещении суммы налога, заявленной к возмещению в заявительном порядке, не изменяет порядок и сроки проведения камеральной налоговой проверки представленной налоговой декларации.\n\nВ случае вынесения решения об отказе в возмещении суммы налога, заявленной к возмещению в заявительном порядке, возмещение суммы налога осуществляется в порядке и сроки, которые предусмотрены статьей 176 настоящего Кодекса.\n\nНе позднее дня, следующего за днем вынесения одного из решений, указанных в настоящем пункте, налоговый орган в соответствии со статьями 74 и 741 настоящего Кодекса уведомляет гаранта (гарантов), выдавшего (выдавших) банковскую гарантию (банковские гарантии), об его освобождении от обязательств по этой банковской гарантии (этим банковским гарантиям), а поручителя об освобождении от обязательств по договору поручительства.\n\n(Пункт в редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nВ отношении налогоплательщиков, указанных в подпункте 6 пункта 2 настоящей статьи, обоснованность суммы налога, заявленной к возмещению в налоговой декларации, проверяется налоговым органом в течение срока проведения налогового мониторинга, предусмотренного пунктом 5 статьи 10526 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 29.12.2020 № 470-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 19.07.2011 № 245-ФЗ) (Утратил силу - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 29.11.2014 № 380-ФЗ) (Утратил силу - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nНе позднее дня, следующего за днем направления налогоплательщику сообщения об отсутствии выявленных нарушений законодательства о налогах и сборах, налоговый орган в соответствии со статьями 74 и 741 настоящего Кодекса уведомляет гаранта (гарантов), выдавшего (выдавших) банковскую гарантию (банковские гарантии), об освобождении гаранта (гарантов) от обязательств по этой банковской гарантии (этим банковским гарантиям), а поручителя об освобождении от обязательств по договору поручительства. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nЕсли в отношении налогоплательщиков, указанных в подпункте 6 пункта 2 н\n\nастоящей статьи, сумма налога, возмещенная в порядке, предусмотренном настоящей статьей, превышает сумму налога, подлежащую возмещению в соответствии с составленным налоговым органом мотивированным мнением, налоговый орган одновременно с составлением мотивированного мнения принимает решение об отмене (полностью или частично) решения о возмещении суммы налога, заявленной к возмещению. (Дополнение абзацем - Федеральный закон от 29.12.2020 № 470-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nРешение об отмене (полностью или частично) решения о возмещении суммы налога, заявленной к возмещению, в заявительном порядке должно содержать сведения: (Дополнение абзацем - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\nо сумме налога, подлежащей возмещению по результатам камеральной налоговой проверки или в связи с составлением налоговым органом мотивированного мнения; (Дополнение абзацем - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\nо суммах налога, излишне полученных налогоплательщиком в заявительном порядке, подлежащих возврату в бюджетную систему Российской Федерации; (Дополнение абзацем - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\nо сумме процентов, предусмотренных пунктом 9 статьи 79 настоящего Кодекса, подлежащих возврату в бюджетную систему Российской Федерации; (Дополнение абзацем - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\nо сумме процентов, начисленных в соответствии с пунктом 17 настоящей статьи до дня принятия решения об отмене (полностью или частично) решения о возмещении суммы налога, заявленной к возмещению, в заявительном порядке; (Дополнение абзацем - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\nо сроке вступления в силу и исполнения решения об отмене (полностью или частично) решения о возмещении суммы налога, заявленной к возмещению, в заявительном порядке. (Дополнение абзацем - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\nНачиная со дня, следующего за днем принятия решения налогового органа об отмене (полностью или частично) решения о возмещении суммы налога, заявленной к возмещению в заявительном порядке, на сумму излишне полученных налогоплательщиком в заявительном порядке сумм начисляются пени в соответствии со статьей 75 настоящего Кодекса.\n\n(Пункт в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nЕсли уточненная налоговая декларация подана налогоплательщиком до принятия решения, предусмотренного абзацем вторым или третьим пункта 8 настоящей статьи, то такое решение по ранее поданной налоговой декларации не принимается. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nЕсли уточненная налоговая декларация подана налогоплательщиком после принятия налоговым органом решения о возмещении суммы налога, заявленной к возмещению, в заявительном порядке, но до завершения камеральной налоговой проверки (до окончания срока проведения налогового мониторинга, но не позднее дня составления мотивированного мнения, если уточненная налоговая декларация подана налогоплательщиком, указанным в подпункте 6 пункта 2 настоящей статьи), то указанное решение по ранее поданной налоговой декларации отменяется (полностью или частично) не позднее десяти дней со дня представления уточненной налоговой декларации, если иное не установлено настоящим пунктом. Не позднее дня, следующего за днем принятия решения об отмене (полностью или частично) решения о возмещении суммы налога, заявленной к возмещению, в заявительном порядке, налоговый орган уведомляет налогоплательщика о принятии данного решения. Суммы, излишне полученные налогоплательщиком в заявительном порядке, должны быть возвращены им с учетом процентов, предусмотренных пунктом 17 настоящей статьи. (В редакции  федеральных законов от 29.12.2020 № 470-ФЗ, от 28.12.2022 № 565-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nРешение о возмещении суммы налога, заявленной к возмещению в заявительном порядке, не подлежит отмене в случае, если на дату представления уточненной налоговой декларации, представленной до завершения камеральной налоговой проверки налоговой декларации, по которой вынесено указанное решение (до окончания срока проведения налогового мониторинга, но не позднее дня составления мотивированного мнения, если уточненная налоговая декларация представлена налогоплательщиком, указанным в подпункте 6 пункта 2 настоящей статьи), сумма налога, возмещенная налогоплательщику в заявительном порядке, равна сумме налога, заявленной к возмещению в заявительном порядке по уточненной налоговой декларации, или меньше указанной суммы. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nРешение о возмещении суммы налога, заявленной к возмещению в заявительном порядке, в случае превышения суммы налога, возмещенной в заявительном порядке, над суммой налога, заявленной к возмещению в заявительном порядке по уточненной налоговой декларации, представленной до завершения камеральной налоговой проверки налоговой декларации, по которой вынесено указанное решение (до окончания срока проведения налогового мониторинга, но не позднее дня составления мотивированного мнения, если уточненная налоговая декларация представлена налогоплательщиком, указанным в подпункте 6 пункта 2 настоящей статьи), не подлежит отмене в части суммы налога, заявленной к возмещению в заявительном порядке по уточненной налоговой декларации. При этом в указанном случае налоговый орган в срок не позднее десяти дней со дня представления уточненной налоговой декларации принимает решение об отмене решения о возмещении суммы налога, заявленной к возмещению в заявительном порядке, в части превышения суммы налога, возмещенной в заявительном порядке, над суммой налога, заявленной к возмещению в заявительном порядке по уточненной налоговой декларации. Суммы налога, излишне полученные налогоплательщиком в заявительном порядке, должны быть возвращены им с учетом процентов, предусмотренных пунктом 17 настоящей статьи. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nПоложения абзацев четвертого и пятого настоящего пункта не применяются, если: (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nранее представленная (представленные) банковская гарантия (банковские гарантии) или банковская гарантия (банковские гарантии), представленная (представленные) взамен указанной банковской гарантии (указанных банковских гарантий), не соответствует (не соответствуют) требованиям, установленным пунктами 2 и 4 настоящей статьи; (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nнарушены сроки, предусмотренные пунктом 7 настоящей статьи, для представления заявления о замене банковской гарантии на новую банковскую гарантию (новые банковские гарантии) взамен ранее представленной банковской гарантии (ранее представленных банковских гарантий); (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nранее заключенный договор поручительства (договоры поручительства) или новый договор поручительства (договоры поручительства), представленный (представленные) взамен ранее заключенного (заключенных) договора поручительства (договоров поручительства), не соответствует (не соответствуют) требованиям, установленным пунктами 2 и 41 настоящей статьи; (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nнарушен срок, предусмотренный пунктом 7 настоящей статьи, для представления заявления о замене договора поручительства (договоров поручительства), заключенного (заключенных) в отношении ранее представленной налоговой декларации (ранее представленных налоговых деклараций), на новый договор поручительства (новые договоры поручительства) взамен ранее заключенного договора поручительства (ранее заключенных договоров поручительства). (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nВ срок не позднее пяти дней со дня истечения срока, установленного пунктом 8 настоящей статьи для проверки налоговым органом соблюдения требований, предусмотренных пунктами 2, 4, 41, 61 и 7 настоящей статьи, налоговый орган: (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nуведомляет в соответствии со статьей 741 настоящего Кодекса гаранта об освобождении от обязательств по банковской гарантии, представленной гарантом по ранее представленной налогоплательщиком налоговой декларации, при условии принятия налоговым органом решения о замене банковской гарантии в целях обеспечения обязанности по уплате суммы налога, возмещенного налогоплательщику по решению налогового органа при применении заявительного порядка возмещения налога в отношении ранее представленной налоговой декларации; (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nуведомляет в соответствии со статьей 74 настоящего Кодекса поручителя об освобождении от обязательств по договору поручительства в отношении ранее представленной налогоплательщиком налоговой декларации при условии принятия налоговым органом решения о замене договора поручительства в целях обеспечения обязанности по уплате налога, возмещенного налогоплательщику по решению налогового органа при применении заявительного порядка возмещения налога в отношении ранее представленной налоговой декларации. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 17.12.2009 № 318-ФЗ)","article_title":"Статья 176.1. Заявительный порядок возмещения налога","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f23e23ef9376c0a6bd7c199061f48f559ae36152fe48560f3a95679ffeca6817"},{"code_id":"NK_RF_2","article_number":"177","version_date":"2000-07-31","article_text":"Сроки и порядок уплаты налога при ввозе товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, устанавливаются настоящей главой с учетом положений таможенного законодательства Таможенного союза и законодательства Российской Федерации о таможенном деле.\n\n(Статья в редакции Федерального закона от 27.11.2010 № 306-ФЗ)","article_title":"Статья 177. Сроки и порядок уплаты налога при ввозе товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"36b0934ca877095db7c4e2fd42d66e37fe78d79bf86bde5a18ad94223b24942c"},{"code_id":"NK_RF_2","article_number":"178","version_date":"2000-07-31","article_text":"(Статья утратила силу - Федеральный закон от 06.06.2003 № 65-ФЗ)\n\nГЛАВА 22. АКЦИЗЫ","article_title":"Статья 178. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"962162280989dfaf2dc794d921e476919bc97225ff5e1ca60a04d9453b12e6c8"},{"code_id":"NK_RF_2","article_number":"179","version_date":"2000-07-31","article_text":"1) организации;\n\n2) индивидуальные предприниматели;\n\n3) лица, признаваемые налогоплательщиками в связи с перемещением товаров через таможенную границу Евразийского экономического союза, определяемые в соответствии с правом Евразийского экономического союза и законодательством Российской Федерации о таможенном деле. (В редакции Федерального закона от 23.11.2015 № 323-ФЗ)","article_title":"Статья 179. Налогоплательщики","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"90e626038fa8c37328878cc566b03d3d1f493a830f0dcd7f4aa5998d30ec918f"},{"code_id":"NK_RF_2","article_number":"179.1","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 24.07.2002 № 110-ФЗ) (Утратила силу - Федеральный закон от 26.07.2006 № 134-ФЗ)","article_title":"Статья 179.1. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b2acb7bc1f3fa81bf0275c8a34bc6858079e7a1cd5116aa2a168fa32f3743424"},{"code_id":"NK_RF_2","article_number":"179.2","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 29.09.2019 № 326-ФЗ)\n\n1. Свидетельства о регистрации организации, совершающей операции с этиловым спиртом (далее в настоящей статье - свидетельство), выдаются организациям, осуществляющим следующие виды деятельности:\n\n1) производство неспиртосодержащей продукции, в качестве сырья для производства которой (в процессе производства которой) используется денатурированный этиловый спирт, - свидетельство на производство неспиртосодержащей продукции;\n\n2) производство спиртосодержащей парфюмерно-косметической продукции в металлической аэрозольной упаковке, в качестве сырья для производства которой используется этиловый спирт, - свидетельство на производство спиртосодержащей парфюмерно-косметической продукции в металлической аэрозольной упаковке;\n\n3) производство спиртосодержащей парфюмерно-косметической продукции в малой емкости (спиртосодержащей парфюмерно-косметической продукции с объемной долей этилового спирта до 80 процентов включительно, разливаемой в емкости не более 100 мл, или спиртосодержащей парфюмерно-косметической продукции с объемной долей этилового спирта до 90 процентов включительно при наличии на флаконе пульверизатора, разливаемой в емкости не более 100 мл, или спиртосодержащей парфюмерно-косметической продукции с объемной долей этилового спирта до 90 процентов включительно, разливаемой в емкости не более 3 мл), в качестве сырья для производства которой используется этиловый спирт, - свидетельство на производство спиртосодержащей парфюмерно-косметической продукции в малой емкости;\n\n4) производство спиртосодержащей продукции бытовой химии в металлической аэрозольной упаковке - свидетельство на производство спиртосодержащей продукции бытовой химии в металлической аэрозольной упаковке;\n\n5) производство прошедших регистрацию в соответствии с правом Евразийского экономического союза и (или) законодательством Российской Федерации лекарственных средств, и (или) лекарственных препаратов, и (или) медицинских изделий, предусмотренных перечнями, утвержденными федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере здравоохранения, в соответствии с критериями и в порядке, которые установлены Правительством Российской Федерации (далее в настоящей главе - перечни фармацевтической продукции), в качестве сырья для производства которых (в процессе производства которых) используется фармацевтическая субстанция спирта этилового (этанол) (далее в настоящей главе - фармацевтическая субстанция спирта этилового), - свидетельство на производство фармацевтической продукции; (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\n6) производство спиртосодержащей непищевой продукции в виде геля, крема на гелевой основе (крем-геля), в качестве сырья для производства которой (в процессе производства которой) используется этиловый спирт, - свидетельство на производство спиртосодержащей непищевой продукции; (Дополнение подпунктом - Федеральный закон от 15.10.2020 № 321-ФЗ)\n\n7) производство спиртосодержащих полиграфических красок, в качестве сырья для производства которых используется денатурированный этиловый спирт, - свидетельство на производство спиртосодержащих полиграфических красок. (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 267-ФЗ)\n\n(Пункт в редакции Федерального закона от 29.09.2019 № 326-ФЗ)\n\n2. В свидетельстве указываются:\n\n1) наименование налогового органа, выдавшего свидетельство;\n\n2) полное и сокращенное наименования организации, местонахождение организации и адрес (место фактической деятельности) осуществления организацией вида деятельности, указанного в пункте 1 настоящей статьи;\n\n3) идентификационный номер налогоплательщика (ИНН);\n\n4) вид деятельности;\n\n5) реквизиты документов, подтверждающих право собственности (право хозяйственного ведения или оперативного управления) на производственные мощности, и местонахождение указанных мощностей. В целях настоящей главы под производственными мощностями понимаются сооружения, технологические установки и оборудование; (В редакции федеральных законов от 29.09.2019 № 326-ФЗ, от 15.10.2020 № 321-ФЗ)\n\n6) реквизиты документов, подтверждающих право собственности (право хозяйственного ведения или оперативного управления) на мощности по хранению этилового спирта, и местонахождение указанных мощностей при условии, что требование о наличии указанных мощностей у организации предусмотрено пунктом 4 настоящей статьи; (В редакции Федерального закона от 29.09.2019 № 326-ФЗ)\n\n7) (Подпункт утратил силу - Федеральный закон от 29.09.2019 № 326-ФЗ)\n\n8) виды товаров, для производства которых (в процессе производства которых) используется этиловый спирт; (В редакции Федерального закона от 29.09.2019 № 326-ФЗ)\n\n9) регистрационный номер свидетельства и дата его выдачи.\n\n3. Форма свидетельства, выдаваемого на каждый вид деятельности, предусмотренный пунктом 1 настоящей статьи, форма заявления о выдаче свидетельства, представляемого налогоплательщиком, формы решений налогового органа о выдаче (об отказе в выдаче), приостановлении (возобновлении) действия свидетельства, об аннулировании свидетельства и административный регламент по предоставлению государственной услуги по выдаче свидетельства утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции Федерального закона от 30.09.2013 № 269\n\n4. Свидетельства выдаются организациям при соблюдении следующих требований:\n\n1) свидетельство на производство неспиртосодержащей продукции - при наличии в собственности (на праве хозяйственного ведения или оперативного управления) организации мощностей по производству, хранению и отпуску неспиртосодержащей продукции, в качестве сырья для производства которой (в процессе производства которой) используется денатурированный этиловый спирт;\n\n2) свидетельство на производство спиртосодержащей парфюмерно-косметической продукции в металлической аэрозольной упаковке - при наличии в собственности (на праве хозяйственного ведения или оперативного управления) организации мощностей по хранению этилового спирта, по производству, хранению и отпуску спиртосодержащей парфюмерно-косметической продукции в металлической аэрозольной упаковке, в качестве сырья для производства которой используется этиловый спирт;\n\n3) свидетельство на производство спиртосодержащей парфюмерно-косметической продукции в малой емкости - при наличии в собственности (на праве хозяйственного ведения или оперативного управления) организации мощностей по хранению этилового спирта, по производству, хранению и отпуску спиртосодержащей парфюмерно-косметической продукции в малой емкости при условии, что в качестве сырья для производства указанной продукции используется этиловый спирт;\n\n4) свидетельство на производство спиртосодержащей продукции бытовой химии в металлической аэрозольной упаковке - при наличии в собственности (на праве хозяйственного ведения или оперативного управления) организации мощностей по хранению этилового спирта, по производству, хранению и отпуску спиртосодержащей продукции бытовой химии в металлической аэрозольной упаковке, в качестве сырья для производства которой используется этиловый спирт;\n\n5) свидетельство на производство фармацевтической продукции - при наличии в собственности (на праве хозяйственного ведения или оперативного управления) организации мощностей по производству, хранению и отпуску лекарственных средств, и (или) лекарственных препаратов, и (или) медицинских изделий, предусмотренных перечнями фармацевтической продукции, в качестве сырья для производства которых (в процессе производства которых) используется фармацевтическая субстанция спирта этилового, и при наличии лицензии на производство лекарственных средств, и (или) лекарственных препаратов, и (или) медицинских изделий, действие которой не прекращено и не приостановлено, в случае, если в соответствии с законодательством Российской Федерации наличие такой лицензии обязательно для производства лекарственных средств, и (или) лекарственных препаратов, и (или) медицинских изделий.\n\nВ целях настоящей главы лекарственные средства и (или) лекарственные препараты, в составе которых не содержится этиловый спирт или объемная доля этилового спирта составляет не более 20 процентов, а также медицинские изделия считаются предусмотренными соответствующими перечнями фармацевтической продукции без необходимости их дополнительного указания в таких перечнях;\n\n(Подпункт в редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\n6) свидетельство на производство спиртосодержащей непищевой продукции - при наличии у организации на праве собственности (на праве хозяйственного ведения или оперативного управления) мощностей по хранению этилового спирта, по производству, хранению и отпуску спиртосодержащей непищевой продукции в виде геля, крема на гелевой основе (крем-геля), в качестве сырья для производства которой (в процессе производства которой) используется этиловый спирт; (Дополнение подпунктом - Федеральный закон от 15.10.2020 № 321-ФЗ)\n\n7) свидетельство на производство спиртосодержащих полиграфических красок - при наличии у организации на праве собственности (на праве хозяйственного ведения или оперативного управления) мощностей по хранению денатурированного этилового спирта, по производству и хранению спиртосодержащих полиграфических красок, в качестве сырья для производства которых используется денатурированный этиловый спирт. (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 267-ФЗ)\n\n(Пункт в редакции Федерального закона от 29.09.2019 № 326-ФЗ)\n\n41. Для получения свидетельства организация представляет в налоговый орган:\n\n1) заявление о выдаче свидетельства;\n\n2) копии документов, подтверждающих право собственности (право хозяйственного ведения или оперативного управления) на необходимые для осуществления заявленного вида деятельности мощности, указанные в пункте 4 настоящей статьи;\n\n3) копию лицензии на осуществление соответствующего вида деятельности, указанного в пункте 1 настоящей статьи (в случае, если в соответствии с действующим законодательством наличие лицензии обязательно для осуществления такого вида деятельности), либо сведения о дате предоставления лицензии на осуществление соответствующего вида деятельности, указанного в пункте 1 настоящей статьи, и ее регистрационном номере (в случае, если наличие лицензии подтверждается записью в реестре лицензий или государственном сводном реестре выданных, приостановленных и аннулированных лицензий на производство и оборот этилового спирта, алкогольной и спиртосодержащей продукции); (В редакции Федерального закона от 29.11.2021 № 383-ФЗ)\n\n4) перечень видов производимой продукции с указанием номера свидетельства о государственной регистрации (его регистрационного номера) - в случае, если в соответствии с законодательством Российской Федерации и (или) правом Евразийского экономического союза предусмотрена обязательная государственная регистрация такой продукции, либо в случае, если обязательная государственная регистрация не предусмотрена, - копии документов, в соответствии с которыми производится данный вид продукции (технические условия, регламент, сведения о составе компонентов продукции с указанием норм использования этилового спирта в качестве сырья (вспомогательного материала).\n\nНалоговый орган при проведении камеральной налоговой проверки (налогового мониторинга) вправе истребовать у налогоплательщика документы, содержащие информацию об использовании этилового спирта в качестве сырья (вспомогательного материала) при производстве продукции.\n\n(Дополнение подпунктом - Федеральный закон от 15.10.2020 № 321-ФЗ) (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 326-ФЗ)\n\n44. Налоговый орган отказывает в выдаче свидетельства в следующих случаях:\n\n1) представленное заявление о выдаче свидетельства не соответствует установленной форме;\n\n2) организацией-заявителем не представлены или представлены не в полном объеме необходимые для получения свидетельства копии документов;\n\n3) в представленных организацией-заявителем документах (копиях документов) содержится недостоверная информация.\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 326-ФЗ)\n\n45. Организация, получившая свидетельство, одновременно с налоговой декларацией по акцизам представляет в налоговый орган копии документов, подтверждающих возникновение в налоговом периоде, за который представляется налоговая декларация, следующих обстоятельств:\n\n1) прекращение права собственности (права хозяйственного ведения или оперативного управления) в отношении объектов имущества, указанных в пункте 4 настоящей статьи, и (или) прекращение действия лицензии на производство лекарственных средств, и (или) лекарственных препаратов, и (или) медицинских изделий в случае, если в соответствии с действующим законодательством наличие такой лицензии обязательно для производства лекарственных средств, и (или) лекарственных препаратов, и (или) медицинских изделий;\n\n2) возникновение у организации права собственности (права хозяйственного ведения или оперативного управления) в отношении объектов имущества, указанных в пункте 4 настоящей статьи;\n\n3) изменение реквизитов документов, предусмотренных пунктом 41 настоящей статьи, и (или) документов, подтверждающих право, предусмотренное подпунктом 2 настоящего пункта;\n\n4) изменение видов товаров, для производства которых (в процессе производства которых) организацией используется этиловый спирт, и (или) изменение документов, в соответствии с которыми они изготавливаются. (В редакции Федерального закона от 15.10.2020 № 321-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 326-ФЗ)\n\n5. Налоговый орган приостанавливает действие свидетельства с 1-го числа налогового периода, в котором им установлен факт наступления хотя бы одного из следующих случаев:\n\n1) невыполнение организацией положений законодательства о налогах и сборах в части исчисления и уплаты акцизов;\n\n2) приостановление (прекращение) действия лицензии на осуществление соответствующего вида деятельности, указанного в пункте 1 настоящей статьи (в случае, если в соответствии с действующим законодательством Российской Федерации наличие лицензии обязательно для осуществления такого вида деятельности);\n\n3) непредставление организацией документов, указанных в пункте 45 настоящей статьи.\n\n(Пункт в редакции Федерального закона от 29.09.2019 № 326-ФЗ)\n\n51. В случае приостановления действия свидетельства налоговый орган в своем решении обязан установить срок для устранения обстоятельств, являющихся основанием приостановления действия свидетельства. Указанный срок не может превышать шесть месяцев с даты вступления в силу указанного решения.\n\nОрганизация, действие свидетельства которой приостановлено, обязана уведомить в письменной форме налоговый орган, выдавший свидетельство, об устранении обстоятельств, явившихся основанием приостановления действия свидетельства. Налоговый орган в течение десяти рабочих дней с даты получения такого уведомления принимает решение о возобновлении действия свидетельства или об аннулировании свидетельства и сообщает об этом в письменной форме организации.\n\nРешение о возобновлении действия свидетельства вступает в силу с даты его принятия налоговым органом, выдавшим свидетельство.\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 326-ФЗ)\n\n52. Налоговый орган аннулирует свидетельство в следующих случаях:\n\n1) представление организацией заявления об аннулировании свидетельства, составленного в произвольной форме;\n\n2) истечение срока для устранения обстоятельств, установленного налоговым органом, если организация, действие свидетельства которой приостановлено, не устранила в установленный срок все обстоятельства, явившиеся основанием приостановления действия свидетельства;\n\n3) изменение наименования организации;\n\n4) изменение местонахождения организации;\n\n5) изменение местонахождения производственных мощностей, мощностей по хранению этилового спирта, указанных в свидетельстве (в документах, представленных организацией в соответствии с пунктом 45 настоящей статьи);\n\n6) прекращение права собственности (права хозяйственного ведения или оперативного управления) на все мощности по хранению этилового спирта, указанные в свидетельстве (в документах, представленных организацией в соответствии с пунктом 45 настоящей статьи);\n\n7) прекращение права собственности (права хозяйственного ведения или оперативного управления) на все производственные мощности, указанные в свидетельстве (в документах, представленных организацией в соответствии с пунктом 45 настоящей статьи), и (или) прекращение действия лицензии на производство лекарственных средств, и (или) лекарственных препаратов, и (или) медицинских изделий в случае, если в соответствии с действующим законодательством наличие такой лицензии обязательно для производства лекарственных средств, и (или) лекарственных препаратов, и (или) медицинских изделий;\n\n8) производство товаров, для производства которых (в процессе производства которых) используется этиловый спирт, виды которых не указаны в свидетельстве (в документах, представленных организацией в соответствии с пунктом 45 настоящей статьи), за исключением лекарственных средств, медицинских изделий и лекарственных препаратов, относящихся в целях настоящей главы к подакцизным товарам; (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\n9) передача организацией свидетельства другому лицу.\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 326-ФЗ)\n\n53. Решение налогового органа об аннулировании свидетельства вступает в силу со дня его принятия и действует с учетом следующих особенностей:\n\n1) при наступлении случая, указанного в подпункте 1 пункта 52 настоящей статьи, свидетельство аннулируется со дня, указанного в заявлении;\n\n2) при наступлении случаев, указанных в подпунктах 2 - 7 пункта 52 настоящей статьи, свидетельство аннулируется со дня наступления соответствующих обстоятельств;\n\n21) при наступлении случая, указанного в подпункте 8 пункта 52 настоящей статьи, свидетельство аннулируется со дня вынесения решения налогового органа об аннулировании свидетельства; (Дополнение подпунктом - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\n3) при наступлении случая, указанного в подпункте 9 пункта 52 настоящей статьи, свидетельство аннулируется с 1-го числа налогового периода, в котором возникли соответствующие обстоятельства. (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 326-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 21.07.2005 № 107-ФЗ)","article_title":"Статья 179.2. Свидетельства о регистрации организации, совершающей операции с этиловым спиртом","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9a54cf10a421dcd736ec8202fb87f2e421aabe40c68fbd6cd7859a4db26d93bb"},{"code_id":"NK_RF_2","article_number":"179.3","version_date":"2000-07-31","article_text":"1. Свидетельства о регистрации лица, совершающего операции с прямогонным бензином (далее в настоящей статье - свидетельство), выдаются организациям и индивидуальным предпринимателям, осуществляющим следующие виды деятельности:\n\nпроизводство прямогонного бензина, в том числе из давальческого сырья (материалов), - свидетельство на производство прямогонного бензина;\n\nпроизводство продукции нефтехимии, при котором в качестве сырья используется прямогонный бензин, в том числе из давальческого сырья (материалов), - свидетельство на переработку прямогонного бензина.\n\nВ целях настоящей главы продукцией нефтехимии признается следующая продукция (за исключением подакцизных товаров, перечисленных в пункте 1 статьи 181 настоящего Кодекса):\n\nполучаемая в результате переработки (химических превращений), в том числе с использованием вспомогательных веществ, фракций (компонентов) углеводородного сырья (нефти, газового конденсата, попутного нефтяного газа, этана, сжиженного углеводородного газа (далее также в настоящей главе - СУГ) и (или) природного газа), в том числе прямогонного бензина, в органические вещества, которые являются конечными продуктами и (или) используются в дальнейшем для выпуска на их основе других продуктов и (или) используются для технологических потребностей (в том числе в виде топлива), а также побочная продукция и отходы, получаемые в результате указанной переработки; (В редакции Федерального закона от 15.10.2020 № 321-ФЗ)\n\nполучаемая в результате переработки (химических превращений), в том числе с использованием вспомогательных веществ, бензола, параксилола или ортоксилола в органические вещества, которые являются конечными продуктами и (или) используются в дальнейшем для выпуска на их основе других продуктов и (или) используются для технологических потребностей (в том числе в виде топлива), а также побочная продукция и отходы, получаемые в результате указанной переработки.\n\n(Пункт в редакции Федерального закона от 27.11.2017 № 335-ФЗ)\n\n2. В свидетельстве указываются:\n\n1) наименование налогового органа, выдавшего свидетельство;\n\n2) полное и сокращенное наименования организации (фамилия, имя, отчество индивидуального предпринимателя), место нахождения организации (место жительства индивидуального предпринимателя) и адрес (место фактической деятельности) осуществления организацией (индивидуальным предпринимателем) видов деятельности, указанных в пункте 1 настоящей статьи;\n\n3) идентификационный номер налогоплательщика (ИНН);\n\n4) вид деятельности;\n\n5) реквизиты документов, подтверждающих право собственности (право владения или пользования на других законных основаниях при условии, что уставный (складочный) капитал (фонд) организации-заявителя состоит на 100 процентов из вклада (доли) организации - собственника производственных мощностей) на производственные мощности, и место нахождения указанных мощностей;\n\n6) реквизиты договора на оказание налогоплательщиком услуг по переработке нефти, газового конденсата, попутного нефтяного газа, природного газа, горючих сланцев, угля и другого сырья, а также продуктов их переработки в целях получения прямогонного бензина (при наличии указанного договора);\n\n7) реквизиты договора на оказание услуг по переработке прямогонного бензина с организацией, осуществляющей производство продукции нефтехимии (при наличии указанного договора);\n\n8) регистрационный номер свидетельства и дата его выдачи.\n\nсвидетельство на производство прямогонного бензина - при наличии в собственности (на праве владения или пользования на других законных основаниях при условии, что уставный (складочный) капитал (фонд) организации-заявителя на 100 процентов состоит из вклада (доли) органи\n\nзации - собственника производственных мощностей) организации или индивидуального предпринимателя (организации, в которой организация-заявитель владеет более чем 50 процентами уставного (складочного) капитала (фонда) общества с ограниченной ответственностью либо голосующих акций акционерного общества) мощностей по производству прямогонного бензина и (или) при наличии договора об оказании услуг по переработке налогоплательщиком сырой нефти, газового конденсата, попутного нефтяного газа, природного газа, горючих сланцев, угля и другого сырья, а также продуктов их переработки, в результате которой осуществляется производство прямогонного бензина;\n\nсвидетельство на переработку прямогонного бензина - при наличии в собственности (на праве владения или пользования на других законных основаниях при условии, что уставный (складочный) капитал (фонд) организации-заявителя на 100 процентов состоит из вклада (доли) организации - собственника производственных мощностей) организации или индивидуального предпринимателя (организации, в которой организация-заявитель владеет более чем 50 процентами уставного (складочного) капитала (фонда) общества с ограниченной ответственностью либо голосующих акций акционерного общества) мощностей по производству продукции нефтехимии и (или) при наличии договора об оказании услуг по переработке принадлежащего данному налогоплательщику прямогонного бензина, заключенного с организацией, осуществляющей производство продукции нефтехимии.\n\nНалоговый орган обязан выдать свидетельство (уведомить заявителя об отказе в выдаче свидетельства) не позднее 30 календарных дней с момента представления налогоплательщиком заявления о выдаче свидетельства и представления копий предусмотренных настоящей статьей документов. Уведомление направляется налогоплательщику в письменной форме с указанием причин отказа. Для получения свидетельства налогоплательщик (если иное не установлено настоящей статьей) представляет в налоговый орган заявление о выдаче свидетельства, сведения о наличии у него необходимых для осуществления заявленного вида деятельности производственных мощностей, копии документов, подтверждающих право собственности налогоплательщика на указанные мощности (копии документов, подтверждающих право хозяйственного ведения и (или) оперативного управления закрепленным за ним имуществом).\n\nДля получения свидетельства на производство прямогонного бензина организация или индивидуальный предприниматель - переработчик сырой нефти, газового конденсата, попутного нефтяного газа, природного газа, горючих сланцев, угля и другого сырья, а также продуктов их переработки вместо документов, подтверждающих право собственности (право хозяйственного ведения и (или) оперативного управления) на мощности по производству прямогонного бензина, могут представить в налоговый орган заверенную копию договора об оказании услуг по переработке нефти, газового конденсата, попутного нефтяного газа, природного газа, горючих сланцев, угля и другого сырья, а также продуктов их переработки с отметкой налогового органа по месту нахождения организации, осуществляющей переработку нефти, газового конденсата, попутного нефтяного газа, природного газа, горючих сланцев, угля и другого сырья, а также продуктов их переработки. Указанная отметка проставляется при представлении в налоговый орган по месту нахождения этой организации или месту жительства индивидуального предпринимателя копии договора об оказании услуг по переработке нефти, газового конденсата, попутного нефтяного газа, природного газа, горючих сланцев, угля и другого сырья, а также продуктов их переработки.\n\nДля получения свидетельства на переработку прямогонного бензина организация или индивидуальный предприниматель - собственник сырья вместо документов, подтверждающих право собственности (право владения или пользования на других законных основаниях при условии, что уставный (складочный) капитал (фонд) организации-заявителя на 100 процентов состоит из вклада (доли) организации - собственника производственных мощностей) на мощности по производству, хранению и отпуску продукции нефтехимии, могут представить в налоговые органы заверенную копию договора об оказании услуг по переработке прямогонного бензина, заключенного с организацией, осуществляющей производство продукции нефтехимии, с отметкой налогового органа по месту нахождения организации, осуществляющей производство продукции нефтехимии. Указанная отметка проставляется при представлении в налоговый орган по месту нахождения организации или месту жительства индивидуального предпринимателя, осуществляющих производство продукции нефтехимии, копии договора об оказании услуг по переработке прямогонного бензина.\n\nСвидетельства, предусмотренные настоящей статьей, выдаются также организации или индивидуальному предпринимателю, обратившимся с заявлением о выдаче соответствующего свидетельства, при наличии производственных мощностей, необходимых для получения свидетельств, в собственности организации, в которой организация или индивидуальный предприниматель, обратившиеся с заявлением о выдаче свидетельства, владеют более чем 50 процентами уставного (складочного) капитала (фонда) общества с ограниченной ответственностью либо голосующих акций акционерного общества. В этом случае организация или индивидуальный предприниматель, обратившиеся с заявлением о выдаче свидетельства, представляют в налоговый орган документы, подтверждающие права организации на владение, пользование и распоряжение указанным имуществом, и документы, подтверждающие владение указанной долей (соответствующим количеством голосующих акций) в уставном (складочном) капитале (фонде) организации.\n\nДействие свидетельства начинается с 1-го дня налогового периода, в котором налогоплательщиком представлены заявление и копии предусмотренных настоящей статьей документов, на основании которых выдано указанное свидетельство. (Дополнение абзацем - Федеральный закон от 24.11.2014 № 366-ФЗ)\n\nневыполнения организацией или индивидуальным предпринимателем положений законодательства о налогах и сборах в части исчисления и уплаты акцизов;\n\nнепредставления организацией или индивидуальным предпринимателем - покупателем (получателем) прямогонного бензина в течение трех последовательных налоговых периодов реестров счетов-фактур, представляемых в налоговые органы в соответствии со статьей 201 настоящего Кодекса. В указанном случае приостанавливается действие свидетельства организации или индивидуального предпринимателя - покупателя (получателя) прямогонного бензина;\n\nиспользования технологического оборудования по производству, хранению и реализации прямогонного бензина, не оснащенного контрольными приборами учета их объемов, а также оснащенного вышедшим из строя контрольным и учетно-измерительным оборудованием, нарушения работы и условий эксплуатации контрольного и учетно-измерительного оборудования, установленного на указанном технологическом оборудовании.\n\nВ случае приостановления действия свидетельства налоговый орган обязан установить срок устранения нарушений, повлекших за собой приостановление действия свидетельства. Указанный срок не может превышать шесть месяцев. В случае, если в установленный срок нарушения не были устранены, свидетельство аннулируется.\n\nОрганизация или индивидуальный предприниматель, имеющие свидетельство, обязаны уведомить в письменной форме налоговый орган, выдавший свидетельство, об устранении ими нарушений, повлекших за собой приостановление действия свидетельства. Налоговый орган, выдавший свидетельство, принимает решение о возобновлении или об отказе от возобновления его действия и сообщает об этом в письменной форме организации или индивидуальному предпринимателю, имеющим свидетельство, в течение трех дней с даты получения уведомления об устранении нарушений, повлекших за собой приостановление действия свидетельства.\n\nСрок действия свидетельства на время приостановления его действия не продлевается.\n\nНалоговые органы аннулируют свидетельство в случае:\n\nпредставления организацией или индивидуальным предпринимателем соответствующего заявления;\n\nпередачи организацией или индивидуальным предпринимателем выданного в порядке, установленном в соответствии с пунктом 3 настоящей статьи, свидетельства иному лицу;\n\nзавершения реорганизации организации, если в результате реорганизации данная организация утратила право собственности на производственные мощности, заявленные при получении свидетельства, или прекращения действия договоров, предусмотренных абзацами вторым и третьим пункта 4 настоящей статьи;\n\nизменения наименования организации (изменения фамилии, имени, отчества индивидуального предпринимателя);\n\nизменения места нахождения организации (места жительства индивидуального предпринимателя);\n\nпрекращения права собственности или владения (пользования) на других законных основаниях (при условии, что уставный (складочный) капитал (фонд) организации-заявителя на 100 процентов состоит из вклада (доли) организации - собственника производственных мощностей) на весь объем мощностей, указанных в свидетельстве, или прекращения действия договоров, предусмотренных абзацами вторым и третьим пункта 4 настоящей статьи.\n\n(Дополнение статьей - Федеральный закон от 26.07.2006 № 134-ФЗ)","article_title":"Статья 179.3. Свидетельства о регистрации лица, совершающего операции с прямогонным бензином","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"848862ea3f79b3d788f35c6f304780431325e512fb8525457b6d2b8352b34c87"},{"code_id":"NK_RF_2","article_number":"179.4","version_date":"2000-07-31","article_text":"1. Свидетельство о регистрации лица, совершающего операции с бензолом, параксилолом или ортоксилолом (далее в настоящей статье - свидетельство), выдается организациям и индивидуальным предпринимателям, осуществляющим производство продукции нефтехимии (в том числе на основе договора об оказании указанным лицам услуг по производству продукции нефтехимии), при котором в качестве сырья (в том числе на промежуточной стадии непрерывного технологического процесса производства продукции нефтехимии) используется бензол, параксилол или ортоксилол, принадлежащие указанным лицам на праве собственности.\n\n2. В свидетельстве указываются:\n\n1) наименование налогового органа, выдавшего свидетельство;\n\n2) полное и сокращенное наименования организации (фамилия, имя, отчество индивидуального предпринимателя), место нахождения организации (место жительства индивидуального предпринимателя) и адрес (место фактической деятельности) осуществления организацией (индивидуальным предпринимателем) деятельности, указанной в пункте 1 настоящей статьи;\n\n3) идентификационный номер налогоплательщика (ИНН);\n\n4) реквизиты документов, подтверждающих право собственности (право владения и (или) пользования) на производственные мощности, и место нахождения указанных мощностей;\n\n5) реквизиты договора об оказании налогоплательщику услуг по производству продукции нефтехимии;\n\n6) регистрационный номер свидетельства и дата его выдачи.\n\n3. Форма свидетельства, форма заявления о выдаче свидетельства, представляемого налогоплательщиком, формы решений налогового органа о выдаче (об отказе в выдаче), приостановлении (возобновлении) действия свидетельства, об аннулировании свидетельства и административный регламент по предоставлению государственной услуги по выдаче свидетельства утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n4. Свидетельство выдается организациям и индивидуальным предпринимателям при наличии в собственности (на праве владения и (или) пользования) организации или индивидуального предпринимателя (организации, в которой организация-заявитель владеет более чем 50 процентами уставного (складочного) капитала (фонда) общества с ограниченной ответственностью либо голосующих акций акционерного общества) мощностей по производству продукции нефтехимии, при котором в качестве сырья используется бензол, параксилол или ортоксилол (в том числе на промежуточной стадии непрерывного технологического процесса производства продукции нефтехимии), и (или) при наличии договора об оказании налогоплательщику услуг по производству продукции нефтехимии, при котором в качестве сырья используется бензол, параксилол или ортоксилол (в том числе на промежуточной стадии непрерывного технологического процесса производства продукции нефтехимии), заключенного с организацией, непосредственно осуществляющей указанное производство.\n\nНалоговый орган обязан выдать свидетельство или направить налогоплательщику уведомление об отказе в выдаче свидетельства с указанием причины отказа в срок не позднее 30 календарных дней с момента представления налогоплательщиком заявления о выдаче свидетельства и представления копий предусмотренных настоящей статьей документов. Уведомление направляется налогоплательщику в письменной форме.\n\nДля получения свидетельства налогоплательщик представляет в налоговый орган заявление о выдаче свидетельства, а также один из следующих документов:\n\nперечень производственных мощностей, находящихся у налогоплательщика, необходимых для осуществления производства продукции нефтехимии, с приложением копий документов, подтверждающих право собственности (право владения и (или) пользования) налогоплательщика на указанные мощности;\n\nзаверенную копию договора об оказании налогоплательщику услуг по производству продукции нефтехимии, заключенного с организацией, непосредственно осуществляющей указанное производство, с отметкой налогового органа по месту нахождения данной организации. Указанная отметка проставляется при представлении в налоговый орган по месту нахождения указанной организации, осуществляющей производство, копии договора об оказании услуг по переработке бензола, параксилола или ортоксилола.\n\nСвидетельство, предусмотренное настоящей статьей, выдается также организации или индивидуальному предпринимателю, обратившимся с заявлением о выдаче свидетельства, если производственные мощности, необходимые для получения свидетельства, принадлежат на праве собственности (праве владения и (или) пользования) организации, в которой организация или индивидуальный предприниматель, обратившиеся с заявлением о выдаче свидетельства, владеют более чем 50 процентами уставного (складочного) капитала (фонда) общества с ограниченной ответственностью либо голосующих акций акционерного общества. В этом случае организация или индивидуальный предприниматель, обратившиеся с заявлением о выдаче свидетельства, представляют в налоговый орган документы, подтверждающие право собственности (право владения и (или) пользования) на производственные мощности, и документы, подтверждающие право владения указанной долей (соответствующим количеством голосующих акций) в уставном (складочном) капитале (фонде) организации.\n\nДействие свидетельства начинается с 1-го дня налогового периода, в котором налогоплательщиком представлены заявление и копии предусмотренных настоящей статьей документов, на основании которых выдано указанное свидетельство.\n\n5. Налоговые органы приостанавливают действие свидетельства в случае:\n\nневыполнения организацией или индивидуальным предпринимателем положений законодательства о налогах и сборах в части исчисления и уплаты акцизов;\n\nотсутствия средств измерений, методик измерений для измерения количества бензола, параксилола или ортоксилола, направленных на производство продукции нефтехимии. (В редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\nПод средствами измерений для целей настоящей главы понимаются технические средства, предназначенные для соответствующих измерений, отвечающие метрологическим и техническим требованиям, установленным законодательством Российской Федерации об обеспечении единства измерений. (Дополнение абзацем - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\nВ случае приостановления действия свидетельства налоговый орган обязан установить срок устранения нарушений, повлекших за собой приостановление действия свидетельства. Указанный срок не может превышать шесть месяцев. В случае, если в установленный срок нарушения не были устранены, свидетельство аннулируется.\n\nОрганизация или индивидуальный предприниматель, действие свидетельства которых приостановлено, обязаны уведомить в письменной форме налоговый орган, выдавший свидетельство, об устранении нарушений, повлекших за собой приостановление действия свидетельства. Налоговый орган, выдавший свидетельство, принимает решение о возобновлении или об аннулировании свидетельства и сообщает об этом в письменной форме организации или индивидуальному предпринимателю в течение трех дней с даты получения уведомления об устранении нарушений, повлекших за собой приостановление действия свидетельства.\n\n6. Налоговые органы аннулируют свидетельство в случае:\n\n1) представления организацией или индивидуальным предпринимателем соответствующего заявления;\n\n2) истечения срока для устранения нарушений, установленного налоговым органом, если лицо, действие свидетельства которого приостановлено, не устранило в указанный срок нарушения, повлекшие за собой приостановление действия свидетельства;\n\n3) изменения наименования организации (фамилии, имени, отчества индивидуального предпринимателя);\n\n4) изменения места нахождения организации (места жительства индивидуального предпринимателя);\n\n5) прекращения права собственности (права владения и (или) пользования) на весь объем мощностей, указанных в свидетельстве, или прекращения действия договора об оказании услуг по производству продукции нефтехимии.\n\n7. В случаях аннулирования свидетельства, предусмотренных пунктом 6 настоящей статьи, а также в случае утраты организацией или индивидуальным предпринимателем свидетельства организация или индивидуальный предприниматель вправе подать заявление о получении нового свидетельства.\n\n8. Налоговый орган, выдавший свидетельство, обязан уведомить в письменной форме организацию или индивидуального предпринимателя о приостановлении действия или об аннулировании свидетельства в трехдневный срок со дня принятия соответствующего решения.\n\n(Дополнение статьей - Федеральный закон от 24.11.2014 № 366-ФЗ)","article_title":"Статья 179.4. Свидетельство о регистрации лица, совершающего операции с бензолом, параксилолом или ортоксилолом","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9e9e25fe15a480120b6abfdcff58d1f329a9d5c34c643af70f820d855fedcfc8"},{"code_id":"NK_RF_2","article_number":"179.5","version_date":"2000-07-31","article_text":"1. Свидетельство о регистрации организации, совершающей операции со средними дистиллятами (далее в настоящей статье - свидетельство), выдается российским организациям, которым принадлежат на праве собственности или ином законном основании объекты, относящиеся к одному из следующих видов имущества:\n\n1) морские суда, суда внутреннего плавания и (или) суда смешанного (река - море) плавания, используемые в целях судоходства или торгового мореплавания (далее в настоящей главе - водные суда), имеющие право плавания под Государственным флагом Российской Федерации; (В редакции Федерального закона от 05.04.2016 № 101-ФЗ)\n\n2) установки и (или) сооружения в виде гибко или стационарно закрепленных в соответствии с проектной документацией на их создание по месту расположения во внутренних морских водах, в территориальном море Российской Федерации, на континентальном шельфе Российской Федерации, в исключительной экономической зоне Российской Федерации либо в российской части (российском секторе) дна Каспийского моря стационарных и плавучих (подвижных) буровых установок (платформ), морских плавучих (передвижных) платформ, морских стационарных платформ и других объектов, а также подводных со\n\nоружений (включая скважины);\n\n3) объекты имущества, которые непосредственно используются для производства электрической и (или) тепловой энергии путем преобразования тепловой энергии, образующейся в результате сгорания средних дистиллятов, в электрическую и (или) использования такой тепловой энергии для изменения термодинамических параметров теплоносителя. (Дополнение подпунктом - Федеральный закон от 30.07.2019 № 255-ФЗ)\n\n2. В свидетельстве указываются:\n\n1) наименование налогового органа, выдавшего свидетельство;\n\n2) полное и сокращенное наименование организации, место нахождения организации и ее адрес (место фактической деятельности);\n\n3) идентификационный номер налогоплательщика (ИНН);\n\n4) регистрационный номер свидетельства и дата его выдачи.\n\n3. Форма свидетельства, форма заявления о выдаче свидетельства, представляемого налогоплательщиком, формы решений налогового органа о выдаче (об отказе в выдаче), приостановлении (возобновлении) действия свидетельства, об аннулировании свидетельства и административный регламент по предоставлению государственной услуги по выдаче свидетельства утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n4. Для получения свидетельства налогоплательщик представляет в налоговый орган заявление о выдаче свидетельства, а также следующие документы:\n\n1) в отношении водных судов:\n\nкопии документов, подтверждающих право собственности (право владения, и (или) пользования, и (или) распоряжения) на судно;\n\nкопию свидетельства (временного свидетельства) о праве плавания под Государственным флагом Российской Федерации (за исключением маломерных судов); (В редакции Федерального закона от 15.10.2020 № 321-ФЗ)\n\nкопию судового билета, подтверждающего право плавания под Государственным флагом Российской Федерации, - в отношении маломерных судов; (Дополнение абзацем - Федеральный закон от 15.10.2020 № 321-ФЗ)\n\n2) в отношении установок и сооружений, указанных в подпункте 2 пункта 1 настоящей статьи, - копии документов, подтверждающих право собственности (право владения, и (или) пользования, и (или) распоряжения) на указанные установки и сооружения;\n\n3) в отношении объектов имущества, указанных в подпункте 3 пункта 1 настоящей статьи, - копии документов, подтверждающих право собственности (право оперативного управления) на указанные объекты имущества, их ввод в эксплуатацию. (Дополнение подпунктом - Федеральный закон от 30.07.2019 № 255-ФЗ)\n\n5. Действие свидетельства начинается с 1-го дня налогового периода, в котором налогоплательщиком представлены заявление и документы, на основании которых выдано указанное свидетельство.\n\n6. Налоговый орган обязан выдать свидетельство или направить налогоплательщику письменное уведомление об отказе в выдаче свидетельства с указанием причины отказа в срок не позднее 30 календарных дней с даты представления налогоплательщиком заявления о выдаче свидетельства и документов, предусмотренных настоящей статьей.\n\n7. Организация, получившая свидетельство, одновременно с налоговой декларацией по акцизам представляет в налоговый орган копии документов, подтверждающих возникновение в налоговом периоде, за который представляется налоговая декларация, следующих обстоятельств:\n\n1) прекращение права собственности (права владения, и (или) пользования, и (или) распоряжения) в отношении объектов имущества, указанных в пункте 1 настоящей статьи;\n\n2) возникновение у организации права собственности (права владения, и (или) пользования, и (или) распоряжения) в отношении объектов имущества, указанных в пункте 1 настоящей статьи;\n\n3) изменение реквизитов документов, предусмотренных пунктом 4 настоящей статьи, и (или) документов, подтверждающих право, предусмотренное подпунктом 2 настоящего пункта.\n\n8. Налоговый орган, выдавший свидетельство, приостанавливает его действие в случае невыполнения организацией положений законодательства Российской Федерации о налогах и сборах в части исчисления и уплаты акцизов.\n\nВ случае принятия налоговым органом решения о приостановлении действия свидетельства этот налоговый орган устанавливает срок устранения нарушений, повлекших за собой приостановление действия свидетельства, а также в трехдневный срок с даты принятия такого решения направляет его организации, которой выдано свидетельство. При этом срок устранения нарушений не может превышать шесть месяцев.\n\nОрганизация, действие свидетельства которой приостановлено, обязана уведомить в письменной форме налоговый орган, выдавший свидетельство, об устранении нарушений, повлекших за собой приостановление действия свидетельства. При получении такого уведомления налоговый орган, выдавший свидетельство, принимает решение о возобновлении или об аннулировании свидетельства и сообщает об этом в письменной форме организации в трехдневный срок с даты получения уведомления об устранении указанных нарушений.\n\n9. Решение об аннулировании свидетельства принимается налоговым органом, выдавшим это свидетельство, в случае:\n\n1) представления организацией заявления об аннулировании свидетельства - с даты, указанной в таком заявлении;\n\n2) неустранения нарушений в установленный налоговым органом срок - с даты принятия соответствующего решения;\n\n3) прекращения права собственности (права оперативного управления), вывод из эксплуатации объектов имущества, указанных в подпункте 3 пункта 1 настоящей статьи, в отношении которых в налоговый орган представлены копии документов, подтверждающих право собственности (право оперативного управления) на указанные объекты имущества, в соответствии с пунктами 4 и (или) 7 настоящей статьи, - с даты прекращения права собственности (права оперативного управления), вывода из эксплуатации последнего из указанных объектов. (Дополнение подпунктом - Федеральный закон от 30.07.2019 № 255-ФЗ)\n\n10. Решение об аннулировании свидетельства передается налогоплательщику в трехдневный срок со дня принятия этого решения под расписку или иным способом, свидетельствующим о дате его получения налогоплательщиком.\n\n11. Действие свидетельства прекращается в случае его утраты организацией.\n\n12. В случае принятия решения об аннулировании свидетельства в соответствии с настоящей статьей и (или) в случае утраты организацией свидетельства такая организация вправе представить в налоговый орган заявление о получении нового свидетельства в порядке, установленном настоящей статьей.\n\n(Дополнение статьей - Федеральный закон от 23.11.2015 № 323-ФЗ)","article_title":"Статья 179.5. Свидетельство о регистрации организации, совершающей операции со средними дистиллятами","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"53a073ad5c61b8971485c1e7415e0e0ca5d5afe6cb5c85e879f5cbb94d80436e"},{"code_id":"NK_RF_2","article_number":"179.6","version_date":"2000-07-31","article_text":"1. Свидетельство о регистрации лица, совершающего операции по переработке средних дистиллятов (далее в настоящей статье - свидетельство), выдается организации, осуществляющей переработку средних дистиллятов (в том числе на основе договора об оказании такой организации услуг по переработке средних дистиллятов).\n\n2. Свидетельство выдается организации-заявителю при наличии у нее на праве собственности (на праве владения (пользования) на других законных основаниях) производственных мощностей, необходимых для осуществления технологических процессов (хотя бы одного вида) по переработке средних дистиллятов, указанных в пункте 8 настоящей статьи, средств измерений для определения количества средних дистиллятов, направленных на переработку, или при наличии договора об оказании ей услуг по переработке средних дистиллятов, заключенного с организацией, непосредственно осуществляющей указанную переработку и имеющей на праве собственности (на праве владения (пользования) на других законных основаниях) производственные мощности, необходимые для осуществления технологических процессов (хотя бы одного вида) по переработке средних дистиллятов, указанных в пункте 8 настоящей статьи, средств измерений для определения количества средних дистиллятов, направленных на переработку.\n\nНалоговый орган обязан выдать свидетельство или направить организации-заявителю уведомление об отказе в выдаче свидетельства с указанием причины отказа в срок не позднее 15 дней со дня получения им заявления о выдаче свидетельства и предусмотренных настоящей статьей документов.\n\n3. Для получения свидетельства организация-заявитель представляет в налоговый орган заявление о выдаче свидетельства, а также один из следующих комплектов документов:\n\n1) перечень производственных мощностей, необходимых для осуществления технологических процессов (хотя бы одного вида) по переработке средних дистиллятов, указанных в пункте 8 настоящей статьи, с приложением копий документов, подтверждающих право собственности (право владения (пользования) на других законных основаниях) на указанные мощности, а также перечень средств измерений (с указанием мест их размещения) для определения количества средних дистиллятов, направленных на переработку;\n\n2) заверенная копия договора об оказании услуг по переработке средних дистиллятов, заключенного с организацией, непосредственно осуществляющей переработку средних дистиллятов и имеющей свидетельство, с отметкой налогового органа по месту нахождения указанной организации. Такая отметка проставляется уполномоченным лицом налогового органа при представлении в налоговый орган по месту нахождения организации, непосредственно осуществляющей переработку средних дистиллятов, копии указанного договора при условии наличия у этой организации свидетельства и производственных мощностей, необходимых для осуществления технологических процессов (хотя бы одного вида) по переработке средних дистиллятов, указанных в пункте 8 настоящей статьи, средств измерений для определения количества средних дистиллятов.\n\n4. Действие свидетельства начинается с 1-го дня налогового периода, в котором организацией-заявителем представлены заявление и предусмотренные настоящей статьей документы, на основании которых выдано свидетельство.\n\n5. Налоговый орган отказывает в выдаче свидетельства в следующих случаях:\n\n1) заявление о выдаче свидетельства представлено не в соответствии с формой;\n\n2) организацией-заявителем не представлены или представлены не в полном объеме необходимые для получения свидетельства документы;\n\n3) в представленных организацией-заявителем документах содержится недостоверная информация.\n\n6. В свидетельстве указываются:\n\n1) наименование налогового органа, выдавшего свидетельство;\n\n2) полное и сокращенное наименования организации, место нахождения организации и адрес осуществления организацией деятельности (место фактической деятельности), указанной в пункте 1 настоящей статьи;\n\n3) идентификационный номер налогоплательщика (ИНН);\n\n4) реквизиты документов (при наличии), подтверждающих право собственности организации-заявителя (право владения (пользования) на других законных основаниях) на производственные мощности, необходимые для осуществления технологических процессов (хотя бы одного вида) по переработке средних дистиллятов, указанных в пункте 8 настоящей статьи;\n\n5) реквизиты договора об оказании организации-заявителю услуг по переработке средних дистиллятов (при наличии);\n\n6) регистрационный номер свидетельства и дата его выдачи.\n\n7. Форма свидетельства, форма заявления о выдаче свидетельства, формы решений налогового органа о выдаче (об отказе в выдаче), приостановлении (возобновлении) действия свидетельства, о неполном устранении нарушений, повлекших за собой приостановление действия свидетельства, об аннулировании свидетельства и административный регламент предоставления государственной услуги по выдаче свидетельства утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n8. В целях настоящей главы к технологическим процессам по переработке средних дистиллятов относятся следующие процессы:\n\n1) первичная переработка нефти;\n\n2) гидроочистка углеводородных фракций;\n\n3) каталитический крекинг;\n\n4) гидрокрекинг;\n\n5) каталитический риформинг;\n\n6) деасфальтизация гудрона пропаном;\n\n7) селективная очистка масел фенолом;\n\n8) селективная очистка масел N-метилпирролидоном;\n\n9) депарафинизация рафинатов;\n\n10) производство масел 3 группы;\n\n11) гидроизодепарафинизация;\n\n12) гидроочистка масел и парафинов;\n\n13) замедленное коксование; (Дополнение подпунктом - Федеральный закон от 30.07.2019 № 255-ФЗ)\n\n14) гидроконверсия тяжелых остатков; (Дополнение подпунктом - Федеральный закон от 30.07.2019 № 255-ФЗ)\n\n15) получение технического углерода путем термического или термоокислительного разложения средних дистиллятов; (Дополнение подпунктом - Федеральный закон от 30.07.2019 № 255-ФЗ)\n\n16) производство битума путем окисления гудрона. (Дополнение подпунктом - Федеральный закон от 30.07.2019 № 255-ФЗ)\n\n9. Налоговые органы приостанавливают действие свидетельства в следующих случаях:\n\n1) невыполнения организацией положений законодательства о налогах и сборах в части исчисления и уплаты акцизов;\n\n2) приостановления действия свидетельства у организации, с которой заключен договор об оказании услуг по переработке средних дистиллятов;\n\n3) отсутствия или нахождения в нерабочем состоянии средств измерений для определения количества средних дистиллятов, направляемых на переработку.\n\n10. В случае приостановления действия свидетельства налоговый орган обязан установить срок для устранения нарушений, повлекших за собой приостановление действия свидетельства. Указанный срок не может превышать шесть месяцев.\n\nОрганизация, действие свидетельства которой приостановлено, обязана уведомить в письменной форме налоговый орган, выдавший свидетельство, об устранении нарушений, повлекших за собой приостановление действия свидетельства. Налоговый орган, выдавший свидетельство, в течение десяти рабочих дней со дня получения такого уведомления принимает решение о возобновлении действия свидетельства или о неполном устранении нарушений, повлекших за собой приостановление действия свидетельства.\n\n11. Налоговые органы аннулируют свидетельство в следующих случаях:\n\n1) представление организацией соответствующего заявления в произвольной форме;\n\n2) истечение срока для устранения нарушений, установленного налоговым органом, если лицо, действие свидетельства которого приостановлено, не устранило в указанный срок все нарушения, повлекшие за собой приостановление действия свидетельства;\n\n3) изменение наименования организации;\n\n4) изменение места нахождения организации;\n\n5) прекращение права собственности (права владения (пользования) на других законных основаниях) на все производственные мощности, указанные в свидетельстве, либо прекращение действия договора об оказании услуг по переработке средних дистиллятов или аннулирование свидетельства у организации, с которой заключен договор об оказании услуг по переработке средних дистиллятов.\n\n12. В случаях аннулирования свидетельства организация вправе подать заявление о получении нового свидетельства.\n\nВ случае утраты организацией свидетельства такая организация вправе обратиться в налоговый орган за выдачей дубликата. В случае повторной утраты свидетельства организация вправе подать заявление о получении нового свидетельства.\n\n13. Налоговый орган, выдавший (выдающий) свидетельство, обязан уведомить в письменной форме организацию об отказе в выдаче свидетельства, о приостановлении действия свидетельства, о неполном устранении нарушений, повлекших за собой приостановление действия свидетельства, о возобновлении действия свидетельства или об аннулировании свидетельства в трехдневный срок со дня принятия соответствующего решения.\n\n(Дополнение статьей - Федеральный закон от 27.11.2017 № 335-ФЗ)","article_title":"Статья 179.6. Свидетельство о регистрации лица, совершающего операции по переработке средних дистиллятов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2564de1eabee7701201d7f2f36d937ce39e939e13e8fb64d7b9369d7965d0311"},{"code_id":"NK_RF_2","article_number":"179.7","version_date":"2000-07-31","article_text":"1. Свидетельство о регистрации лица, совершающего операции по переработке нефтяного сырья (далее в настоящей статье - свидетельство), выдается российской организации, осуществляющей переработку нефтяного сырья (в том числе на основе договора об оказании такой организации услуг по переработке нефтяного сырья) в целях получения товаров в виде продуктов, выработанных из нефтяного сырья (прямогонный бензин, автомобильный бензин, авиационный керосин, дизельное топливо, средние дистилляты, высоковязкие продукты), одного или нескольких видов.\n\n2. Если иное не установлено пунктом 3 настоящей статьи, свидетельство выдается российской организации-заявителю на основании заявления, представленного в налоговый орган, при наличии у нее на праве собственности и (или) ином законном основании производственных мощностей, необходимых для осуществления технологических процессов (хотя бы одного вида) по переработке нефтяного сырья, указанных в пункте 11 настоящей статьи, средств измерений для определения количества нефтяного сырья, направленного на переработку, и при выполнении хотя бы одного из следующих условий:\n\n1) организация-заявитель и (или) российские организации, которые прямо и (или) косвенно участвуют в организации-заявителе и совокупная доля участия которых в организации-заявителе составляла по состоянию на 1 января 2018 года не менее 50 процентов, по состоянию на указанную дату подпадали под действие введенных иностранными государствами, международными организациями, экономическими, политическими, военными или иными объединениями государств в отношении Российской Федерации, российских организаций, граждан Российской Федерации запретительных, ограничительных и (или) иных аналогичных мер, заключающихся в том числе в установлении запретов и (или) ограничений каким-либо лицам на проведение расчетов и (или) осуществление финансовых операций с такими российскими организациями, запретов или ограничений каким-либо лицам на предоставление заемного финансирования или проведение операций с такими российскими организациями, связанных с предоставлением заемного финансирования и (или) приобретением либо отчуждением ценных бумаг (долей в уставных капиталах), и (или) запретов или ограничений, связанных с поставками оборудования, услуг и (или) технологий;\n\n2) в течение хотя бы одного из трех налоговых периодов, предшествующих налоговому периоду, в котором было представлено заявление о выдаче свидетельства, организация-заявитель осуществляла реализацию (в случае производства из давальческого нефтяного сырья - передачу собственнику и (или) по его поручению третьим лицам) на территории Российской Федерации произведенного ею из нефтяного сырья (в том числе из давальческого нефтяного сырья) автомобильного бензина класса 5 и (или) реализацию (в случае производства из давальческого нефтяного сырья - передачу собственнику сырья и (или) по его поручению третьим лицам) на территории Российской Федерации произведенного ею из нефтяного сырья (в том числе из давальческого нефтяного сырья) прямогонного бензина на переработку в продукцию нефтехимии, прямогонный бензин, бензол, параксилол, ортоксилол лицам, имеющим свидетельство на переработку прямогонного бензина и (или) свидетельство о регистрации лица, совершающего операции с бензолом, параксилолом или ортоксилолом, и (или) передачу в структуре организации-заявителя, имеющей свидетельство на переработку прямогонного бензина и (или) свидетельство на совершение операций с бензолом, параксилолом или ортоксилолом, произведенного ею из нефтяного сырья (в том числе из давальческого нефтяного сырья) прямогонного бензина на переработку в продукцию нефтехимии, прямогонный бензин, бензол, параксилол, ортоксилол при условии, что объем реализации (в случае производства из давальческого нефтяного сырья - передачи собственнику давальческого нефтяного сырья или по его поручению третьим лицам) и (или) передачи в структуре организации-заявителя таких продуктов за указанные три налоговых периода в совокупности превысил 5 тысяч тонн и соотношение объем\n\nа производства указанных продуктов переработки нефтяного сырья к объему нефтяного сырья, направленного на переработку, в совокупности за указанный период составило значение 0,1 и более; (В редакции Федерального закона от 27.11.2018 № 424-ФЗ)\n\n3) организацией-заявителем до 1 июня 2019 года заключено с федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса, соглашение о модернизации нефтеперерабатывающих мощностей или организация-заявитель является третьей стороной соглашения о замене стороны в соглашении о модернизации нефтеперерабатывающих мощностей, заключенном до 1 июня 2019 года. (В редакции Федерального закона от 15.10.2020 № 321-ФЗ)\n\n3. Вне зависимости от выполнения условий, установленных в пункте 2 настоящей статьи, свидетельство также выдается организации-заявителю при наличии у нее договора об оказании ей услуг по переработке нефтяного сырья, заключенного с организацией, непосредственно осуществляющей указанную переработку, имеющей на праве собственности и (или) ином законном основании производственные мощности, необходимые для осуществления технологических процессов (хотя бы одного вида) по переработке нефтяного сырья, указанных в пункте 11 настоящей статьи, средства измерений для определения количества нефтяного сырья, направленного на переработку, при условии, что в отношении организации, которая непосредственно осуществляет переработку нефтяного сырья, выполняется хотя бы одно из условий, указанных в подпунктах 1 и 2 пункта 2 настоящей статьи.\n\nВне зависимости от выполнения условий, установленных пунктом 2 настоящей статьи, свидетельство также выдается организации-заявителю при наличии у нее договора об оказании ей услуг по переработке нефтяного сырья, заключенного с организацией, непосредственно осуществляющей указанную переработку, имеющей на праве собственности и (или) ином законном основании производственные мощности, необходимые для осуществления технологических процессов (хотя бы одного вида) по переработке нефтяного сырья, указанных в пункте 11 настоящей статьи, средства измерений для определения количества нефтяного сырья, направленного на переработку, при условии, что в отношении организации, которая непосредственно осуществляет переработку нефтяного сырья, выполняется условие, указанное в подпункте 3 пункта 2 настоящей статьи, и совокупная первоначальная стоимость объектов основных средств, включенных в соглашение о модернизации нефтеперерабатывающих мощностей и вводимых в эксплуатацию в период с 1 июля 2014 года по 1 января 2026 года, составляет не менее 60 миллиардов рублей. Положения настоящего абзаца применяются при условии, что доля прямого участия организации-заявителя в организации, с которой у нее заключен договор об оказании ей услуг по переработке нефтяного сырья и которая непосредственно осуществляет указанную переработку, составляет более 50 процентов. (Дополнение абзацем - Федеральный закон от 27.11.2018 № 424-ФЗ) (В редакции  федеральных законов от 15.10.2020 № 321-ФЗ, от 14.07.2022 № 323-ФЗ)\n\n4. Налоговый орган обязан выдать свидетельство или направить организации-заявителю уведомление об отказе в выдаче свидетельства с указанием причины отказа в срок не позднее 15 дней со дня получения им заявления о выдаче свидетельства и предусмотренных настоящей статьей документов и сведений.\n\n5. Соглашение о модернизации нефтеперерабатывающих мощностей вправе заключить российская организация, направившая на переработку в 2017 году нефтяное сырье в объеме более 600 тысяч тонн, при наличии у нее на праве собственности и (или) ином законном основании производственных мощностей, необходимых для осуществления технологических процессов (хотя бы одного вида) по переработке нефтяного сырья, указанных в пункте 11 настоящей статьи, средств измерений для определения количества нефтяного сырья, направленного на переработку, в случае, если такая организация удовлетворяет хотя бы одному из следующих условий:\n\n1) после завершения мероприятий, предусмотренных соглашением о модернизации нефтеперерабатывающих мощностей, отношение объема производства автомобильного бензина класса 5, производимого из нефтяного сырья, направленного такой организацией на переработку, к объему нефтяного сырья, направленного на переработку, по итогам каждого года будет составлять не менее 0,1;\n\n2) совокупная первоначальная стоимость объектов основных средств, предусмотренных для включения в соглашение о модернизации нефтеперерабатывающих мощностей и вводимых в эксплуатацию в период с 1 июля 2014 года по 1 января 2026 года, составляет не менее 60 миллиардов рублей. (В редакции  Федерального закона от 14.07.2022 № 323-ФЗ)\n\n(Пункт в редакции Федерального закона от 15.10.2020 № 321-ФЗ)\n\n51. В соглашении о модернизации нефтеперерабатывающих мощностей указываются мероприятия, связанные с проектированием, строительством, вводом в эксплуатацию установок вторичной переработки нефти, а также сроки реализации указанных мероприятий.\n\nДля целей заключения соглашений о модернизации нефтеперерабатывающих мощностей Правительством Российской Федерации утверждается перечень установок вторичной переработки нефти, которые могут являться предметом таких соглашений.\n\nФорма соглашения о модернизации нефтеперерабатывающих мощностей, порядок заключения (расторжения) соглашения о модернизации нефтеперерабатывающих мощностей, порядок внесения изменений в соглашение о модернизации нефтеперерабатывающих мощностей, порядок контроля за исполнением соглашения о модернизации нефтеперерабатывающих мощностей устанавливаются Правительством Российской Федерации.\n\nВ период с 1 января 2022 года по 31 декабря 2023 года включительно, а также после 1 июля 2024 года (после 1 июля 2025 года для соглашений о модернизации нефтеперерабатывающих мощностей, заключенных по основанию, указанному в подпункте 1 пункта 5 настоящей статьи) не допускается внесение изменений в соглашение о модернизации нефтеперерабатывающих мощностей, за исключением изменения сроков реализации мероприятий, указанных в соглашении о модернизации нефтеперерабатывающих мощностей, но не более чем на шесть месяцев по сравнению со сроками реализации данных мероприятий, зафиксированными в указанном соглашении по состоянию на 1 января 2021 года (на 1 июля 2024 года для соглашений о модернизации нефтеперерабатывающих мощностей, в которые вносились изменения в период с 1 января по 30 июня 2024 года включительно, или на 1 июля 2025 года для соглашений о модернизации нефтеперерабатывающих мощностей, заключенных по основанию, указанному в подпункте 1 пункта 5 настоящей статьи, в которые вносились изменения в период с 1 января по 30 июня 2025 года включительно), а также за исключением замены стороны в соглашении о модернизации нефтеперерабатывающих мощностей, предусмотренной пунктом 55 настоящей статьи. (В редакции  Федерального закона от 29.11.2024 № 416-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 15.10.2020 № 321-ФЗ)\n\n52. Федеральный орган исполнительной власти, осуществляющий функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса, ежегодно до 1 июля текущего года осуществляет проверку выполнения мероприятий, указанных в соглашении о модернизации нефтеперерабатывающих мощностей, в предыдущем календарном году.\n\nФедеральный орган исполнительной власти, осуществляющий функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса, расторгает соглашение о модернизации нефтеперерабатывающих мощностей в одностороннем порядке в случае нарушения сроков реализации хотя бы одного из мероприятий, предусмотренных таким соглашением, за исключением:\n\nнарушения сроков реализации и финансирования мероприятий, указанных в таком соглашении, приходящихся на период 2022 и 2023 годов, при условии их выполнения по 31 декабря 2023 года включительно;\n\nнарушения сроков реализации и финансирования мероприятий, указанных в таком соглашении, заключенном по основанию, указанному в подпункте 2 пункта 5 настоящей статьи, приходящихся на период 2023 года, при условии их выполнения по 31 декабря 2025 года включительно;\n\nнарушения сроков реализации и финансирования мероприятий, указанных в таком соглашении, приходящихся на период 2024 года, при условии внесения изменений в указанное соглашение в отношении таких мероприятий в порядке, предусмотренном пунктом 51 настоящей статьи.\n\nФедеральный орган исполнительной власти, осуществляющий функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса, уведомляет организацию, являющуюся стороной соглашения о модернизации нефтеперерабатывающих мощностей, о расторжении соглашения о модернизации нефтеперерабатывающих мощностей в течение пятнадцати рабочих дней со дня расторжения указанного соглашения.\n\n(Дополнение пунктом - Федеральный закон от 15.10.2020 № 321-ФЗ) (В редакции  Федерального закона от 23.07.2025 № 227-ФЗ)\n\n53. Соглашение о модернизации нефтеперерабатывающих мощностей считается неисполненным при наступлении хотя бы одного из следующих обстоятельств:\n\n1) соглашение о модернизации нефтеперерабатывающих мощностей расторгнуто по основанию, указанному в пункте 52 настоящей статьи;\n\n2) принято решение о реорганизации организации, заключившей соглашение о модернизации нефтеперерабатывающих мощностей, или решение о ликвидации указанной организации в период с 1 января 2021 года до 1-го числа месяца, в котором налогоплательщиком от федерального органа исполнительной власти, осуществляющего функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса, получено подтверждение полного выполнения указанного соглашения о модернизации нефтеперерабатывающих мощностей, но не позднее 1 января 2025 года - если иное не установлено пунктом 55 настоящей статьи;\n\n3) для организации, заключившей соглашение о модернизации нефтеперерабатывающих мощностей по основанию, указанному в подпункте 1 пункта 5 настоящей статьи:\n\nесли по истечении первого квартала, или шести месяцев, или девяти месяцев, или двенадцати месяцев 2029 года, или 2030 года, или 2031 года отношение объема высокооктанового (по исследовательскому методу 92 и более) автомобильного бензина класса 5, который был произведен из нефтяного сырья, направленного на переработку и принадлежащего организации на праве собственности, и был реализован ею на территории Российской Федерации в соответствующем периоде, к объему нефтяного сырья, направленного в соответствующем периоде на переработку и принадлежащего организации на праве собственности, оказалось менее 0,1; (В редакции  федеральных законов от 27.11.2023 № 539-ФЗ, от 29.11.2024 № 416-ФЗ)\n\nесли в вынесенном (вынесенных) налоговым органом решении (решениях) о привлечении к ответственности за совершение налогового правонарушения и (или) решении (решениях) об отказе в привлечении к ответственности за совершение налогового правонарушения по результатам налоговых проверок организации за налоговые периоды, дата начала которых приходится на период с 1 января 2019 года по 31 декабря 2022 года включительно, не исполненных по состоянию на любую дату начиная с 1 января 2026 года, указаны суммы акцизов, подлежащие уплате, в совокупном размере более 300 миллионов рублей; (Дополнение абзацем - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\nесли в случае завершения до 1 января 2024 года полностью или частично мероприятий, предусмотренных соглашением о модернизации нефтеперерабатывающих мощностей, в результате которых отношение, указанное в подпункте 1 пункта 5 настоящей статьи, по итогам квартала, следующего за кварталом завершения указанных мероприятий, составило не менее 0,1, отношение, указанное в абзаце втором настоящего подпункта, оказалось менее 0,1. Для целей настоящего абзаца отношение, указанное в абзаце втором настоящего подпункта, определяется по истечении первого квартала, шести месяцев, девяти месяцев и двенадцати месяцев в каждом году начиная с года, в котором были завершены указанные мероприятия, до 2025 года включительно, если иное не установлено настоящим абзацем. Для года, в котором были завершены указанные мероприятия, такое отношение определяется начиная с квартала, следующего за кварталом завершения указанных мероприятий, за каждые следующие за таким кварталом три месяца, шесть и девять месяцев этого календарного года;\n\n(Подпункт в редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\n4) для организации, заключившей соглашение о модернизации нефтеперерабатывающих мощностей по основанию, указанному в подпункте 2 пункта 5 настоящей статьи, - если совокупная первоначальная стоимость объектов основных средств, включенных в соглашение о модернизации нефтеперерабатывающих мощностей и введенных в эксплуатацию в период с 1 июля 2014 года по 1 января 2026 года, оказалась менее 60 миллиардов рублей. (В редакции  Федерального закона от 14.07.2022 № 323-ФЗ)\n\nДля целей настоящего подпункта первоначальная стоимость основного средства определяется в порядке, установленном пунктом 1 статьи 257 настоящего Кодекса. В случае, если в сделках, учитываемых при формировании первоначальной стоимости основного средства, применялись цены, не признаваемые рыночными, первоначальная стоимость такого основного средства для целей настоящего подпункта определяется с использованием цен указанных сделок, принимаемых для целей налогообложения, в порядке и с применением методов, которые установлены главой 143 настоящего Кодекса. В целях настоящего абзаца рыночная цена определяется с учетом положений статьи 1053 настоящего Кодекса;\n\n5) в период с 1 января 2021 года и до 1-го числа месяца, в котором налогоплательщиком от федерального органа исполнительной власти, осуществляющего функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса, получено подтверждение полного выполнения соглашения о модернизации нефтеперерабатывающих мощностей, но не позднее 1 января 2025 года прекращено право собственности организации (за исключением случая гибели или уничтожения имущества) в отношении объектов основных средств, предусмотренных соглашением о модернизации нефтеперерабатывающих мощностей, - если иное не установлено пунктом 55 настоящей статьи.\n\n(Дополнение пунктом - Федеральный закон от 15.10.2020 № 321-ФЗ)\n\n54. Организация, заключившая соглашение о модернизации нефтеперерабатывающих мощностей (далее в настоящем пункте - организация-заявитель), обращается в федеральный орган исполнительной власти, осуществляющий функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса, с запросом о подтверждении полного (частичного) выполнения указанной организацией соглашения о модернизации нефтеперерабатывающих мощностей (далее также - запрос).\n\nПо запросу организации-заявителя федеральный орган исполнительной власти, осуществляющий функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса, до истечения тридцати дней с даты получения запроса направляет указанной организации в письменной форме подтверждение полного (частичного) выполнения соглашения о модернизации нефтеперерабатывающих мощностей или отказ в таком подтверждении.\n\nФедеральный орган исполнительной власти, осуществляющий функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса, направляет организации-заявителю подтверждение полного (частичного) выполнения соглашения о модернизации нефтеперерабатывающих мощностей при условии, что сумма фактически оплаченных и документально подтвержденных затрат, непосредственно связанных с созданием объектов основных средств, включенных в соглашение о модернизации нефтеперерабатывающих мощностей, по состоянию на 1-е число месяца получения запроса превысила 60 миллиардов рублей (40 миллиардов рублей - для случая частичного выполнения соглашения о модернизации нефтеперерабатывающих мощностей). При этом организация-заявитель обязана приложить к запросу копии документов, подтверждающих фактическую оплату затрат, указанных в настоящем абзаце, виды которых соответствуют перечню видов подтверждающих документов, утверждаемому федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса (далее в настоящем пункте - перечень).\n\nФедеральный орган исполнительной власти, осуществляющий функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса, направляет организации-заявителю отказ в подтверждении полного (частичного) выполнения соглашения о модернизации нефтеперерабатывающих мощностей в следующих случаях:\n\nсоглашение о модернизации нефтеперерабатывающих мощностей расторгнуто;\n\nв представленных организацией-заявителем документах содержится недостоверная информация;\n\nнепредставление (в том числе неполное представление) организацией-заявителем копий документов, подтверждающих фактическую оплату затрат, непосредственно связанных с созданием объектов основных средств, включенных в соглашение о модернизации нефтеперерабатывающих мощностей, в размере 60 миллиардов рублей и более (40 миллиардов рублей и более - для случая частичного выполнения соглашения о модернизации нефтеперерабатывающих мощностей);\n\nвиды представленных подтверждающих документов не соответствуют перечню.\n\nФорма запроса, форма подтверждения (отказа в подтверждении) полного (частичного) выполнения соглашения о модернизации нефтеперерабатывающих мощностей устанавливаются федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса.\n\nВ случае направления организацией-заявителем в федеральный орган исполнительной власти, осуществляющий функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса, запроса не допускается внесение изменений в соглашение о модернизации нефтеперерабатывающих мощностей начиная с даты получения такого запроса федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса.\n\n(Дополнение пунктом - Федеральный закон от 15.10.2020 № 321-ФЗ)\n\n55. При выполнении условий, установленных настоящим пунктом, допускается замена стороны в соглашении о модернизации нефтеперерабатывающих мощностей, в том числе при реорганизации организации.\n\nЗамена стороны в соглашении о модернизации нефтеперерабатывающих мощностей допускается при условии перехода к организации - третьему лицу прав собственности на все объекты основных средств (в том числе создаваемые), предусмотренные соглашением о модернизации нефтеперерабатывающих мощностей.\n\nВ этом случае может быть заключено соглашение о замене стороны в соглашении о модернизации нефтеперерабатывающих мощностей до истечения тридцати дней с момента перехода прав собственности на все указанные объекты основных средств.\n\nСоглашение о замене стороны в соглашении о модернизации нефтеперерабатывающих мощностей заключается между федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса, организацией\n\n, заключившей соглашение о модернизации нефтеперерабатывающих мощностей, а также организацией, к которой перешли права собственности на объекты основных средств (в том числе создаваемые), предусмотренные соглашением о модернизации нефтеперерабатывающих мощностей.\n\nЗамена стороны в соглашении о модернизации нефтеперерабатывающих мощностей допускается как в течение всего срока действия соглашения, так и после прекращения его действия со дня получения организацией-заявителем подтверждения от федерального органа исполнительной власти, осуществляющего функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса, о полном выполнении организацией-заявителем указанного соглашения о модернизации нефтеперерабатывающих мощностей.\n\nВ соглашении о замене стороны в соглашении о модернизации нефтеперерабатывающих мощностей третья сторона (организация, к которой перешли права собственности на объекты основных средств) принимает на себя все обязательства, предусмотренные соглашением о модернизации нефтеперерабатывающих мощностей.\n\nФорма соглашения о замене стороны в соглашении о модернизации нефтеперерабатывающих мощностей и порядок заключения такого соглашения устанавливаются федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса.\n\n(Дополнение пунктом - Федеральный закон от 15.10.2020 № 321-ФЗ)\n\n6. Для получения свидетельства организация-заявитель представляет в налоговый орган заявление о выдаче свидетельства, а также один из следующих комплектов документов:\n\n1) перечень производственных мощностей, необходимых для осуществления технологических процессов (хотя бы одного вида) по переработке нефтяного сырья, указанных в пункте 11 настоящей статьи, с приложением копий документов, подтверждающих право собственности и (или) право пользования в отношении указанных мощностей, перечень средств измерений (с указанием мест их размещения) для определения количества нефтяного сырья, направленного на переработку, а также документы и сведения, подтверждающие выполнение в отношении организации-заявителя хотя бы одного из условий, указанных в подпунктах 1 - 3 пункта 2 настоящей статьи;\n\n2) заверенная копия договора об оказании услуг по переработке нефтяного сырья, заключенного с организацией, непосредственно осуществляющей переработку нефтяного сырья и имеющей свидетельство, с отметкой налогового органа по месту нахождения указанной организации. Отметка на договоре об оказании услуг по переработке нефтяного сырья проставляется уполномоченным лицом налогового органа при представлении в налоговый орган по месту нахождения организации, непосредственно осуществляющей переработку нефтяного сырья и имеющей свидетельство, копии указанного договора при условии наличия у этой организации производственных мощностей, необходимых для осуществления технологических процессов (хотя бы одного вида) по переработке нефтяного сырья, указанных в пункте 11 настоящей статьи, средств измерений для определения количества нефтяного сырья.\n\nВ случае, если организация-заявитель осуществляет переработку нефтяного сырья как на принадлежащих ей на праве собственности и (или) ином законном основании производственных мощностях, так и на основании договора об оказании ей услуг по переработке нефтяного сырья, в налоговый орган представляются комплекты документов в соответствии с подпунктами 1 и 2 настоящего пункта. При этом в свидетельстве указываются все места размещения средств измерений для определения количества нефтяного сырья, направленного на переработку, отраженные в указанных комплектах документов. (В редакции Федерального закона от 27.11.2018 № 424-ФЗ)\n\nПри подаче заявления о выдаче свидетельства организация-заявитель вправе не представлять документы, ранее представленные в налоговый орган в соответствии с положениями настоящей статьи. (Дополнение абзацем - Федеральный закон от 30.07.2019 № 255-ФЗ)\n\n7. Действие свидетельства начинается с 1-го дня налогового периода, в котором организацией-заявителем представлены заявление и предусмотренные настоящей статьей документы, на основании которых выдано свидетельство.\n\n8. Налоговый орган отказывает в выдаче свидетельства в следующих случаях:\n\n1) заявление о выдаче свидетельства представлено не в соответствии с установленной формой;\n\n2) организацией-заявителем не представлены или представлены не в полном объеме необходимые для получения свидетельства документы;\n\n3) в представленных организацией-заявителем документах содержится недостоверная информация;\n\n4) для организации-заявителя, обратившейся за получением свидетельства по основанию, указанному в абзаце втором пункта 3 настоящей статьи, - если на дату представления в налоговый орган заявления доля участия организации-заявителя в организации, с которой у нее заключен договор, указанный в подпункте 2 пункта 6 настоящей статьи, составляет менее 50 процентов; (Дополнение подпунктом - Федеральный закон от 15.10.2020 № 321-ФЗ)\n\n5) организация-заявитель ранее получала свидетельство, которое было аннулировано в период с 1 марта 2020 года по 31 декабря 2021 года включительно, и (или) к организации-заявителю перешли права пользования и (или) распоряжения производственными мощностями, указанными в свидетельстве организации, свидетельство которой было аннулировано в указанный период (за исключением случая, указанного в пункте 55 настоящей статьи), и (или) организация-заявитель заключила договор об оказании ей услуг по переработке нефтяного сырья с организацией, непосредственно осуществляющей указанную переработку, и с такой организацией ранее был заключен договор об оказании услуг по переработке нефтяного сырья другой организацией и у этой другой организации было аннулировано свидетельство в период с 1 марта 2020 года по 31 декабря 2021 года включительно. Положения настоящего подпункта не применяются в случае, если аннулирование свидетельства производится по заявлению налогоплательщика при получении им по тем же основаниям нового свидетельства, действующего с налогового периода, в котором было аннулировано ранее полученное свидетельство. (Дополнение подпунктом - Федеральный закон от 15.10.2020 № 321-ФЗ)\n\n9. В свидетельстве указываются:\n\n1) наименование налогового органа, выдавшего свидетельство;\n\n2) полное и сокращенное наименования организации-заявителя, место нахождения организации-заявителя и адрес осуществления организацией-заявителем деятельности (место фактической деятельности), указанной в пункте 1 настоящей статьи;\n\n3) идентификационный номер налогоплательщика (ИНН);\n\n4) реквизиты документов (при наличии), подтверждающих право собственности и (или) иное законное основание организации-заявителя в отношении производственных мощностей, необходимых для осуществления технологических процессов (хотя бы одного вида) по переработке нефтяного сырья, указанных в пункте 11 настоящей статьи;\n\n5) реквизиты договора об оказании организации-заявителю услуг по переработке нефтяного сырья (при наличии);\n\n6) регистрационный номер свидетельства и дата его выдачи;\n\n7) места размещения средств измерений для определения количества нефтяного сырья, направленного на переработку. (Дополнение подпунктом - Федеральный закон от 27.11.2018 № 424-ФЗ)\n\n10. Форма свидетельства, форма заявления о выдаче свидетельства, формы решений налогового органа о выдаче (об отказе в выдаче), приостановлении (возобновлении) действия свидетельства, о неполном устранении нарушений, повлекших за собой приостановление действия свидетельства, об аннулировании свидетельства и административный регламент предоставления государственной услуги по выдаче свидетельства утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n11. В целях настоящей главы к технологическим процессам по переработке нефтяного сырья относятся следующие процессы (их совокупность):\n\n1) первичная переработка нефти и (или) конденсата газового стабильного;\n\n2) каталитический риформинг бензина;\n\n3) каталитический крекинг;\n\n4) гидрокрекинг;\n\n5) гидроконверсия тяжелых остатков;\n\n6) замедленное коксование;\n\n7) селективная очистка, депарафинизация и гидроизодепарафинизация.\n\n12. Налоговые органы приостанавливают действие свидетельства в следующих случаях:\n\n1) невыполнение организацией положений законодательства о налогах и сборах в части исчисления и уплаты акцизов;\n\n2) приостановление действия свидетельства у организации, с которой заключен договор об оказании услуг по переработке нефтяного сырья. В случае наличия у налогоплательщика нескольких свидетельств, полученных в соответствии с пунктом 3 настоящей статьи, налоговые органы приостанавливают действие только свидетельства, полученного в связи с наличием у налогоплательщика договора об оказании ему услуг по переработке нефтяного сырья, заключенного с организацией, непосредственно осуществляющей указанную переработку, действие свидетельства которой было приостановлено; (В редакции Федерального закона от 30.07.2019 № 255-ФЗ)\n\n3) отсутствие средств измерений для определения количества нефтяного сырья, направляемого на переработку, или нахождение таких средств измерений в состоянии, препятствующем определению количества нефтяного сырья, направляемого на переработку.\n\n13. Действие свидетельства приостанавливается по решению налогового органа со дня установления факта наступления хотя бы одного случая, предусмотренного подпунктами 1 - 3 пункта 12 настоящей статьи.\n\n14. В случае приостановления действия свидетельства налоговый орган в своем решении обязан установить срок для устранения нарушений, повлекших за собой приостановление действия свидетельства. Указанный срок не может превышать шесть месяцев с даты вступления в силу указанного решения.\n\nОрганизация, действие свидетельства которой приостановлено, обязана уведомить в письменной форме налоговый орган, выдавший свидетельство, об устранении нарушений, повлекших за собой приостановление действия свидетельства. Налоговый орган, выдавший свидетельство, в течение десяти рабочих дней со дня получения такого уведомления принимает решение о возобновлении действия свидетельства или о неполном устранении нарушений, повлекших за собой приостановление действия свидетельства.\n\n15. Налоговые органы аннулируют свидетельство в следующих случаях:\n\n1) представление организацией заявления об аннулировании свидетельства, составленного в произвольной форме;\n\n2) истечение срока для устранения нарушений, установленного налоговым органом, если организация, действие свидетельства которой приостановлено, не устранила в указанный срок все нарушения, повлекшие за собой приостановление действия свидетельства;\n\n3) (Пункт утратил силу - Федеральный закон от 15.10.2020 № 321-ФЗ)\n\n4) изменение адреса осуществления деятельности (места фактической деятельности), указанной в пункте 1 настоящей статьи; (В редакции Федерального закона от 15.10.2020 № 321-ФЗ)\n\n5) прекращение права собственности (права пользования на иных законных основаниях) на все производственные мощности, указанные в свидетельстве, либо прекращение действия договора об оказании услуг по переработке нефтяного сырья (за исключением обстоятельства, указанного в абзаце пятом пункта 20 настоящей статьи) или аннулирование свидетельства у организации, с которой заключен договор об оказании услуг по переработке нефтяного сырья; (В редакции Федерального закона от 15.10.2020 № 321-ФЗ)\n\n6) если по истечении первого квартала, или шести месяцев, или девяти месяцев, или двенадцати месяцев календарного года соотношение суммы объема высокооктанового (по исследовательскому методу 92 и более) автомобильного бензина класса 5, произведенного из нефтяного сырья, направленного на переработку и принадлежащего организации на праве собственности (для организации, непосредственно осуществляющей переработку нефтяного сырья, в части полученного ею давальческого нефтяного сырья - на любых иных законных основаниях), реализованного ею (для организации, непосредственно осуществляющей переработку нефтяного сырья, в отношении объема высокооктанового (по исследовательскому методу 92 и более) автомобильного бензина класса 5, произведенного такой организацией из давальческого нефтяного сырья, - переданного ею собственнику давальческого нефтяного сырья и (или) по его поручению третьим лицам) на территории Российской Федерации в соответствующем периоде, объема прямогонного бензина, произведенного из нефтяного сырья, направленного на переработку и принадлежащего организации на праве собственности (для организации, непосредственно осуществляющей переработку нефтяного сырья, в части полученного ею давальческого нефтяного сырья - на любых иных законных основаниях), реализованного ею (в случае производства из давальческого нефтяного сырья - переданного ею собственнику давальческого нефтяного сырья и (или) по его поручению третьим лицам) в соответствующем периоде на переработку в продукцию нефтехимии, прямогонный бензин, бензол, параксилол, ортоксилол лицам, имеющим свидетельство на переработку прямогонного бензина и (или) свидетельство о регистрации лица, совершающего операции с бензолом, параксилолом или ортоксилолом, и объема прямогонного бензина, произведенного из нефтяного сырья, направленного на переработку, переданного в структуре организации-заявителя, имеющей свидетельство на переработку прямогонного бензина и (или) свидетельство на совершение операций с бензолом, параксилолом или ортоксилолом, на переработку в продукцию нефтехимии, прямогонный бензин, бензол, параксилол, ортоксилол, к объему нефтяного сырья, принадлежащего организации на праве собственности (для организации, непосредственно осуществляющей переработку нефтяного сырья, в части полученного ею давальческого нефтяного сырья - на любых иных законных основаниях), направленного в соответствующем периоде на переработку, оказалось менее 0,1; (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\n7) наступление обстоятельства, при котором соглашение о модернизации нефтеперерабатывающих мощностей считается неисполненным; (В редакции Федерального закона от 15.10.2020 № 321-ФЗ)\n\n8) в отношении организации, получившей свидетельство по основанию, указанному в абзаце втором пункта 3 настоящей статьи, - если доля участия указанной организации в организации, непосредственно осуществляющей переработку нефтяного сырья, с которой заключен договор, указанный в подпункте 2 пункта 6 настоящей статьи, оказалась менее 50 процентов. (Дополнение подпунктом - Федеральный закон от 15.10.2020 № 321-ФЗ)\n\n16. Аннулирование свидетельства налоговым органом по основаниям, предусмотренным пунктом 15 настоящей статьи, осуществляется с учетом следующих особенностей:\n\n1) если иное не установлено подпунктом 7 настоящего пункта, при наступлении случая, указанного в подпункте 1 пункта 15 настоящей статьи, действие свидетельства аннулируется со дня, указанного в заявлении;\n\n2) если иное не установлено подпунктом 7 настоящего пункта, при наступлении случаев, указанных в подпунктах 2, 4 и 5 пункта 15 настоящей статьи, действие свидетельства аннулируется по решению налогового органа со дня наступления соответствующих обстоятельств;\n\n3) если иное не установлено подпунктом 7 настоящего пункта, действие свидетельства аннулируется по решению налогового органа с 1 января года, для которого установлено невыполнение соотношения, указанного в подпункте 6 пункта 15 настоящей статьи;\n\n4) положения подпункта 6 пункта 15 настоящей статьи не применяются в отношении следующих организаций:\n\nполучивших свидетельство по основаниям, указанным в подпункте 1 пункта 2 настоящей статьи;\n\nполучивших свидетельство по основаниям, указанным в подпункте 3 пункта 2 настоящей статьи, и являющихся стороной соглашения о модернизации нефтеперерабатывающих мощностей, заключенного по основанию, указанному в подпункте 2 пункта 5 настоящей статьи;\n\nполучивших свидетельство по основаниям, указанным в пункте 3 настоящей статьи, и имеющих договор на оказание услуг по переработке нефтяного сырья, заключенный с организацией, непосредственно осуществляющей переработку нефтяного сырья и получившей свидетельство по основаниям, указанным в подпункте 1 пункта 2 настоящей статьи;\n\nполучивших свидетельство по основаниям, указанным в абзаце втором пункта 3 настоящей статьи, и имеющих договор на оказание услуг по переработке нефтяного сырья, заключенный с организацией, непосредственно осуществляющей переработку нефтяного сырья, получившей свидетельство по основаниям, указанным в подпункте 3 пункта 2 настоящей статьи, и являющейся стороной соглашения о модернизации нефтеперерабатывающих мощностей, заключенного по основанию, указанному в подпункте 2 пункта 5 настоящей статьи;\n\nполучивших свидетельство по основаниям, указанным в подпункте 3 пункта 2 настоящей статьи, и являющихся стороной соглашения о модернизации нефтеперерабатывающих мощностей, заключенного по основанию, указанному в подпункте 1 пункта 5 настоящей статьи. В отношении таких организаций положения подпункта 6 пункта 15 настоящей статьи не применяются до 1 января 2029 года; (В редакции  федеральных законов от 27.11.2023 № 539-ФЗ, от 29.11.2024 № 416-ФЗ)\n\n5) при наступлении случая, указанного в подпункте 7 пункта 15 настоящей статьи, действие свидетельства аннулируется по решению налогового органа с даты начала действия такого свидетельства. При этом суммы акциза, исчисленные с даты начала действия аннулированного свидетельства организацией, заключившей соглашение о модернизации нефтеперерабатывающих мощностей, которое признано неисполненным, и (или) организацией (организациями), получившей свидетельство по основанию, указанному в абзаце втором пункта 3 настоящей статьи, имевшей (имеющей) договор, указанный в подпункте 2 пункта 6 настоящей статьи, с указанной организацией, заключившей соглашение о модернизации нефтеперерабатывающих мощностей, которое признано неисполненным, при совершении операций, указанных в подпункте 34 пункта 1 статьи 182 настоящего Кодекса, и не уплаченные в связи с применением налоговых вычетов, указанных в пункте 27 статьи 200 настоящего Кодекса, а также суммы, возмещенные указанным организациям в связи с применением таких вычетов, подлежат уплате в бюджет указанной организацией, заключившей соглашение о модернизации нефтеперерабатывающих мощностей, которое признано неисполненным, до истечения месяца, следующего за месяцем, в котором наступило обстоятельство, влекущее признание такого соглашения о модернизации нефтеперерабатывающих мощностей неисполненным;\n\n6) если иное не установлено подпунктом 7 настоящего пункта, при наступлении случая, указанного в подпункте 8 пункта 15 настоящей статьи, действие свидетельства аннулируется по решению налогового органа с 1-го числа месяца, на который приходится первая дата, по состоянию на которую соответствующая доля участия оказалась ниже 50 процентов;\n\n7) при наступлении до 1-го числа месяца, в котором налогоплательщиком получено от федерального органа исполнительной власти, осуществляющего функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса, подтверждение полного выполнения этим налогоплательщиком соглашения о модернизации нефтеперерабатывающих мощностей, но не позднее 1 января 2025 года случая, указанного в подпунктах 1, 2, 4, 5 и 8 пункта 15 настоящей статьи, в отношении организации, имеющей свидетельство по основанию, указанному в подпункте 3 пункта 2 или в абзаце втором пункта 3 настоящей статьи, действие свидетельства аннулируется по решению налогового органа с даты начала действия такого свидетельства. При этом суммы акциза, исчисленные с даты начала действия аннулированного свидетельства орга\n\nнизацией, заключившей соглашение о модернизации нефтеперерабатывающих мощностей, или организацией, получившей свидетельство по основанию, указанному в абзаце втором пункта 3 настоящей статьи, и имеющей договор, указанный в подпункте 2 пункта 6 настоящей статьи, с организацией, заключившей соглашение о модернизации нефтеперерабатывающих мощностей, при совершении операций, указанных в подпункте 34 пункта 1 статьи 182 настоящего Кодекса, и не уплаченные в связи с применением налоговых вычетов, указанных в пункте 27 статьи 200 настоящего Кодекса, а также суммы, возмещенные указанным организациям в связи с применением таких вычетов, подлежат уплате в бюджет соответствующей организацией, заключившей соглашение о модернизации нефтеперерабатывающих мощностей, до истечения месяца, следующего за месяцем, в котором наступил случай, явившийся основанием для аннулирования свидетельства. Положения настоящего подпункта не применяются в случае, если аннулирование свидетельства необходимо для осуществления действий по замене стороны в соглашении о модернизации нефтеперерабатывающих мощностей, осуществляемой в соответствии с пунктом 55 настоящей статьи, или в случае, если аннулирование свидетельства производится по заявлению налогоплательщика при получении им выданного по тем же основаниям нового свидетельства, действующего с налогового периода, в котором было аннулировано ранее полученное свидетельство.\n\n(Пункт в редакции Федерального закона от 15.10.2020 № 321-ФЗ)\n\n17. В случаях аннулирования свидетельства организация вправе подать заявление о получении нового свидетельства.\n\nВ случае утраты организацией свидетельства такая организация вправе обратиться в налоговый орган за выдачей дубликата. (В редакции Федерального закона от 15.10.2020 № 321-ФЗ)\n\n18. Налоговый орган, выдавший (выдающий) свидетельство, обязан уведомить в письменной форме организацию об отказе в его выдаче, о приостановлении действия, неполном устранении нарушений, повлекших за собой приостановление действия свидетельства, о возобновлении действия или об аннулировании свидетельства в трехдневный срок со дня принятия соответствующего решения.\n\n19. Федеральный орган исполнительной власти, осуществляющий функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса, направляет в налоговые органы следующие сведения:\n\n1) о заключенных (расторгнутых) соглашениях о модернизации нефтеперерабатывающих мощностей, о внесении изменений в заключенные соглашения о модернизации нефтеперерабатывающих мощностей, о заключенных соглашениях о замене стороны в соглашении о модернизации нефтеперерабатывающих мощностей - до истечения тридцати дней с момента заключения (расторжения) соглашений о модернизации нефтеперерабатывающих мощностей (соглашений о замене стороны в соглашении о модернизации нефтеперерабатывающих мощностей), о внесении изменений в такие соглашения;\n\n2) об организациях, которым направлено подтверждение полного (частичного) выполнения соглашения о модернизации нефтеперерабатывающих мощностей, - до истечения тридцати дней с момента направления такого подтверждения;\n\n3) об организациях, которые полностью или частично завершили до 1 января 2024 года мероприятия, предусмотренные соглашением о модернизации нефтеперерабатывающих мощностей, заключенным по основанию, указанному в подпункте 1 пункта 5 настоящей статьи, в результате которых отношение объема производства автомобильного бензина класса 5, производимого из нефтяного сырья, направленного такой организацией на переработку, к объему нефтяного сырья, направленного на переработку, по итогам квартала, следующего за кварталом завершения указанных мероприятий, составило не менее 0,1, - до истечения тридцати дней, следующих за кварталом, в котором выполнено указанное условие. (Дополнение подпунктом - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\n(Пункт в редакции Федерального закона от 15.10.2020 № 321-ФЗ)\n\n20. Получившая свидетельство организация одновременно с налоговой декларацией по акцизам в сроки, предусмотренные для представления налоговой декларации за налоговый период в налоговые органы, обязана направить в налоговый орган уведомление о наступлении в течение налогового периода, за который представляется указанная налоговая декларация, следующих обстоятельств, влекущих изменение сведений, указанных в свидетельстве такой организации:\n\nдля организации, непосредственно осуществляющей переработку нефтяного сырья, - замена средств измерений для определения количества нефтяного сырья, направленного на переработку, и (или) изменение мест их размещения, и (или) установка новых средств измерений;\n\nизменение наименования организации;\n\nизменение места нахождения организации;\n\nдля организации, осуществляющей переработку нефтяного сырья на основе договора об оказании ей услуг по переработке нефтяного сырья, - реквизиты нового договора об оказании такой организации услуг по переработке нефтяного сырья в случае прекращения действия договора по переработке нефтяного сырья в течение налогового периода или предыдущего налогового периода и начала действия в течение налогового периода указанного нового договора об оказании услуг по переработке нефтяного сырья при условии, что оба указанных договора об оказании услуг по переработке нефтяного сырья заключены с одной организацией, непосредственно осуществляющей переработку нефтяного сырья и имеющей свидетельство;\n\nпрекращение права собственности (права пользования на иных законных основаниях) на производственные мощности, указанные в свидетельстве;\n\nвозникновение права собственности (права пользования на иных законных основаниях) на производственные мощности, на которых будет осуществляться переработка нефтяного сырья и которые необходимы для осуществления технологических процессов (хотя бы одного вида) по переработке нефтяного сырья, указанных в пункте 11 настоящей статьи.\n\nК указанному в настоящем пункте уведомлению должны быть приложены копии документов, подтверждающих наступление соответствующего обстоятельства.\n\nФорма уведомления и перечень видов подтверждающих документов, необходимых для подтверждения наступления соответствующих обстоятельств, утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nДля организаций, оказывающих услуги по переработке нефтяного сырья и не являющихся плательщиками акциза на нефтяное сырье, представление уведомлений о наступлении обстоятельств, перечисленных в настоящем пункте, осуществляется в течение пятнадцати дней после окончания налогового периода, в котором наступили указанные обстоятельства.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2018 № 424-ФЗ) (В редакции Федерального закона от 15.10.2020 № 321-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 03.08.2018 № 301-ФЗ)","article_title":"Статья 179.7. Свидетельство о регистрации лица, совершающего операции по переработке нефтяного сырья","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"212743a9ebec11e76df329c95ad3b71b9ecfb16f69f7085adf28c36a1c217c9e"},{"code_id":"NK_RF_2","article_number":"179.8","version_date":"2000-07-31","article_text":"1. Свидетельство о регистрации лица, совершающего операции по переработке этана (далее в настоящей статье - свидетельство), выдается организации, осуществляющей переработку этана (в том числе на основе договора об оказании такой организации услуг по переработке этана) в целях получения товаров, являющихся продукцией нефтехимии.\n\n2. Если иное не установлено пунктом 3 настоящей статьи, свидетельство выдается российской организации-заявителю на основании заявления, представленного в налоговый орган, при наличии у нее на праве собственности и (или) ином законном основании производственных мощностей, необходимых для переработки этана в товары, являющиеся продукцией нефтехимии, средств измерений для определения количества этана, направленного на переработку, и при выполнении хотя бы одного из следующих условий:\n\n1) в период с 1 января 2022 года организацией-заявителем введены в эксплуатацию новые производственные мощности по переработке этана в товары, являющиеся продукцией нефтехимии, проектной мощностью по сырью не менее 300 тысяч тонн этана в год либо не менее 600 тысяч тонн этана и СУГ в совокупности в год; (В редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\n2) организацией-заявителем до 1 января 2023 года заключено с федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса, соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии.\n\n3. Вне зависимости от выполнения условий, установленных пунктом 2 настоящей статьи, свидетельство выдается также организации-заявителю при выполнении хотя бы одного из следующих требований:\n\n1) организацией-заявителем заключен договор об оказании ей услуг по переработке этана в товары, являющиеся продукцией нефтехимии, с организацией, непосредственно осуществляющей указанную переработку, имеющей на праве собственности и (или) ином законном основании производственные мощности, необходимые для переработки этана в товары, являющиеся продукцией нефтехимии, средства измерений для определения количества этана, направленного на переработку, при выполнении в отношении такой организации условия, указанного в подпункте 1 пункта 2 настоящей статьи;\n\n2) организацией-заявителем заключен договор об оказании ей услуг по переработке этана в товары, являющиеся продукцией нефтехимии, с организацией, непосредственно осуществляющей указанную переработку, имеющей на праве собственности и (или) ином законном основании производственные мощности, необходимые для переработки этана в товары, являющиеся продукцией нефтехимии, средства измерений для определения количества этана, направленного на переработку, при выполнении в отношении такой организации условия, указанного в подпункте 2 пункта 2 настоящей статьи, а также при условии, что доля прямого участия организации-заявителя в организации, с которой у нее заключен договор об оказании ей услуг по переработке этана в товары, являющиеся продукцией нефтехимии, и которая непосредственно осуществляет указанную переработку, составляет 50 процентов или более.\n\n4. Налоговый орган обязан выдать свидетельство или направить организации-заявителю уведомление об отказе в выдаче свидетельства с указанием причины отказа в срок не позднее пятнадцати дней со дня получения им заявления о выдаче свидетельства и предусмотренных настоящей статьей документов и сведений.\n\nДля целей настоящей главы в совокупной первоначальной стоимости объектов основных средств, предусмотренных организацией-заявителем для включения в соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, и вводимых в эксплуатацию в период с 1 января 2022 года по 31 декабря 2028 года включительно, учитывается также изменение первоначальной стоимости объектов основных средств в результате модернизации (реконструкции), осуществленное в период с 1 января 2022 года по 31 декабря 2028 года включительно. (Дополнение абзацем - Федеральный закон от 29.11.2024 № 416-ФЗ)\n\nДля целей заключения соглашений о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, Правительством Российской Федерации утверждается перечень установок, которые связаны с производством товаров, являющихся продукцией нефтехимии, и могут являться предметом таких соглашений.\n\nНе допускается включение в соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, объектов основных средств, указанных в ранее заключенных соглашениях о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, а также объектов основных средств, не включенных в перечень установок, которые связаны с производством товаров, являющихся продукцией нефтехимии, и могут являться предметом соглашений о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии.\n\nФорма соглашения о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, порядок заключения соглашения о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, порядок внесения изменений в соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, порядок осуществления контроля за исполнением соглашения о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, устанавливаются Правительством Российской Федерации.\n\nДля целей настоящей статьи после 1 января 2026 года не допускается внесение изменений в соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, за исключением изменения сроков реализации отдельных мероприятий, указанных в соглашении, но не более чем на шесть месяцев по сравнению со сроками реализации данных мероприятий, зафиксированными в соглашении о модернизации (реконструкции) мощностей по переработке этана в товары, являющиеся продукцией нефтехимии, по состоянию на 1 января 2026 года. (В редакции  Федерального закона от 29.11.2024 № 416-ФЗ)\n\nДо 1 января 2026 года организация, заключившая соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, имеет право вносить изменения в указанное соглашение, в том числе в отношении корректировки (добавления, замены или исключения) сведений об установках, которые связаны с производством товаров, являющихся продукцией нефтехимии, и могут являться предметом такого соглашения. (Дополнение абзацем - Федеральный закон от 02.07.2021 № 305-ФЗ) (В редакции  Федерального закона от 29.11.2024 № 416-ФЗ)\n\nФедеральный орган исполнительной власти, осуществляющий функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса, расторгает соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, в одностороннем порядке в случае нарушения сроков реализации хотя бы одного из мероприятий, предусмотренных указанным соглашением.\n\nФедеральный орган исполнительной власти, осуществляющий функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса, уведомляет организацию, являющуюся стороной соглашения о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, о расторжении указанного соглашения в течение пятнадцати рабочих дней со дня расторжения указанного соглашения.\n\n1) соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, расторгнуто по основанию, указанному в пункте 7 настоящей статьи;\n\n2) принято решение о реорганизации организации, заключившей соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии (за исключением реорганизации в форме присоединения к такой организации других юридических лиц или в форме выделения из такой организации юридических лиц без передачи им мощностей по производству товаров, являющихся продукцией нефтехимии), или решение о ликвидации такой организации в период с 1 января 2022 года по 31 декабря 2028 года включительно; (В редакции  Федерального закона от 29.11.2024 № 416-ФЗ)\n\n3) совокупная первоначальная стоимость объектов основных средств, включенных в соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, и введенных в эксплуатацию в период с 1 января 2022 года по 31 декабря 2028 года включительно, оказалась менее 65 миллиардов рублей. (В редакции  Федерального закона от 29.11.2024 № 416-ФЗ)\n\nДля целей настоящего подпункта первоначальная стоимость (увеличение первоначальной стоимости) основного средства определяется в порядке, установленном пунктами 1 и 2 статьи 257 настоящего Кодекса. В случае, если в сделках, учитываемых при формировании первоначальной стоимости основного средства, применялись цены, не признаваемые рыночными, первоначальная стоимость такого основного средства для целей настоящего подпункта определяется с использованием цен указанных сделок, принимаемых для целей налогообложения, в порядке и с применением методов, которые установлены главой 143 настоящего Кодекса. Для целей настоящего абзаца рыночная цена определяется с учетом положений статьи 1053 настоящего Кодекса; (В редакции  Федерального закона от 29.11.2024 № 416-ФЗ)\n\n4) в период с 1 января 2022 года по 31 декабря 2028 года включительно прекращено право собственности организации (за исключением гибели или уничтожения имущества) в отношении объектов основных средств, предусмотренных соглашением о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии; (В редакции  Федерального закона от 29.11.2024 № 416-ФЗ)\n\n5) соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, явилось основанием для выдачи свидетельства о регистрации лица, совершающего операции по переработке сжиженных углеводородных газов, в соответствии с подпунктом 3 пункта 2 статьи 1799 настоящего Кодекса при условии, что организация, заключившая такое соглашение, имеет свидетельство о регистрации лица, совершающего\n\nоперации по переработке этана, и свидетельство о регистрации лица, совершающего операции по переработке сжиженных углеводородных газов. (Дополнение подпунктом - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\n1) перечень производственных мощностей по переработке этана в товары, являющиеся продукцией нефтехимии, с приложением копий документов, подтверждающих право собственности на указанные мощности и (или) право владения (пользования) ими на ином законном основании, перечень средств измерений (с указанием мест их размещения) для определения количества этана, направленного на переработку, а также документы и сведения, подтверждающие выполнение в отношении организации-заявителя хотя бы одного из условий, указанных в подпунктах 1 и 2 пункта 2 настоящей статьи;\n\n2) заверенная организацией-заявителем копия договора об оказании услуг по переработке этана в товары, являющиеся продукцией нефтехимии, заключенного с организацией, непосредственно осуществляющей переработку этана в товары, являющиеся продукцией нефтехимии, и имеющей свидетельство, с отметкой налогового органа по месту нахождения этой организации. Отметка на договоре об оказании услуг по переработке этана в товары, являющиеся продукцией нефтехимии, проставляется уполномоченным лицом налогового органа при представлении в налоговый орган по месту нахождения организации, непосредственно осуществляющей переработку этана в товары, являющиеся продукцией нефтехимии, и имеющей соответствующее свидетельство, копии указанного договора при условии наличия у этой организации производственных мощностей по переработке этана в товары, являющиеся продукцией нефтехимии, средств измерений для определения количества этана, направленного на переработку.\n\n1) заявление о выдаче свидетельства представлено не в соответствии с установленной формой;\n\n2) организацией-заявителем не представлены или представлены не в полном объеме необходимые для получения свидетельства документы;\n\n3) в представленных организацией-заявителем документах содержится недостоверная информация;\n\n4) в отношении организации-заявителя, подавшей заявление о выдаче свидетельства по основанию, указанному в подпункте 2 пункта 3 настоящей статьи, по состоянию на дату подачи заявления доля прямого участия организации-заявителя в организации, с которой у нее заключен договор об оказании ей услуг по переработке этана в товары, являющиеся продукцией нефтехимии, и которая непосредственно осуществляет указанную переработку, составляет менее 50 процентов.\n\n1) наименование налогового органа, выдавшего свидетельство;\n\n2) полное и сокращенное наименования организации-заявителя, место нахождения организации-заявителя и адрес осуществления организацией-заявителем деятельности (место фактической деятельности), указанной в пункте 1 настоящей статьи;\n\n3) идентификационный номер налогоплательщика (ИНН);\n\n4) реквизиты документов (при наличии), подтверждающих право собственности организации-заявителя на производственные мощности по переработке этана в товары, являющиеся продукцией нефтехимии, и (или) право владения (пользования) ими на ином законном основании;\n\n5) реквизиты договора об оказании организации-заявителю услуг по переработке этана в товары, являющиеся продукцией нефтехимии (при наличии);\n\n6) регистрационный номер свидетельства и дата его выдачи;\n\n7) места размещения средств измерений для определения количества этана, направленного на переработку в товары, являющиеся продукцией нефтехимии.\n\n1) невыполнение организацией положений законодательства о налогах и сборах в части исчисления и уплаты акцизов;\n\n2) приостановление действия свидетельства организации, с которой заключен договор об оказании услуг по переработке этана в товары, являющиеся продукцией нефтехимии. В случае наличия у налогоплательщика нескольких свидетельств, полученных в соответствии с пунктом 3 настоящей статьи, налоговые органы приостанавливают действие свидетельства, полученного в связи с наличием у налогоплательщика договора об оказании ему услуг по переработке этана в товары, являющиеся продукцией нефтехимии, и заключенного с непосредственно осуществляющей указанную переработку организацией, действие свидетельства которой было приостановлено;\n\n3) отсутствие средств измерений для определения количества этана, направленного на переработку, или нахождение таких средств измерений в состоянии, препятствующем определению количества этана, направляемого на переработку.\n\nОрганизация, действие свидетельства которой приостановлено, обязана уведомить в письменной форме налоговый орган, выдавший свидетельство, об устранении нарушений, повлекших за собой приостановление действия свидетельства. Налоговый орган, выдавший свидетельство, в течение десяти рабочих дней со дня получения такого уведомления принимает решение о возобновлении действия свидетельства или о неполном устранении нарушений, повлекших за собой приостановление действия свидетельства.\n\n1) представление организацией заявления об аннулировании свидетельства, составленного в произвольной форме;\n\n2) истечение срока для устранения нарушений, установленного налоговым органом, если организация, действие свидетельства которой приостановлено, не устранила в указанный срок все нарушения, повлекшие за собой приостановление действия свидетельства;\n\n3) изменение адреса осуществления деятельности (места фактической деятельности), указанной в пункте 1 настоящей статьи;\n\n4) прекращение права собственности на все производственные мощности, указанные в свидетельстве, или права владения (пользования) ими на ином законном основании либо прекращение действия договора об оказании услуг по переработке этана в товары, являющиеся продукцией нефтехимии, или аннулирование свидетельства организации, с которой заключен договор об оказании услуг по переработке этана в товары, являющиеся продукцией нефтехимии;\n\n5) наступление обстоятельства, при котором соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, считается неисполненным;\n\n6) для организации, получившей свидетельство по основанию, указанному в подпункте 2 пункта 3 настоящей статьи, - если доля прямого участия указанной организации в организации, с которой у нее заключен договор об оказании ей услуг по переработке этана в товары, являющиеся продукцией нефтехимии, и которая непосредственно осуществляет указанную переработку, оказалась менее 50 процентов.\n\n1) если иное не установлено подпунктом 5 настоящего пункта, при наступлении случая, указанного в подпункте 1 пункта 18 настоящей статьи, действие свидетельства аннулируется со дня, указанного в заявлении;\n\n2) если иное не установлено подпунктом 5 настоящего пункта, при наступлении случаев, указанных в подпунктах 2 - 4 пункта 18 настоящей статьи, действие свидетельства аннулируется по решению налогового органа со дня наступления соответствующих обстоятельств;\n\n3) при наступлении случая, указанного в подпункте 5 пункта 18 настоящей статьи, действие свидетельства аннулируется по решению налогового органа с даты начала действия свидетельства. При этом суммы акциза, исчисленные с даты начала действия аннулированного свидетельства организацией, заключившей соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, которое признано неисполненным, и (или) организацией (организациями), получившей свидетельство по основанию, указанному в подпункте 2 пункта 3 настоящей статьи, и заключившей договор об оказании услуг по переработке этана в товары, являющиеся продукцией нефтехимии, с указанной организацией, заключившей соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, которое признано неисполненным, при совершении операций, указанных в подпункте 39 пункта 1 статьи 182 настоящего Кодекса, и не уплаченные в связи с применением налоговых вычетов, указанных в пункте 32 статьи 200 настоящего Кодекса, а также суммы, возмещенные указанным организациям в связи с применением таких вычетов, подлежат уплате в бюджет указанной организацией, заключившей соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, которое признано неисполненным, до истечения месяца, следующего за месяцем, в котором наступило обстоятельство, влекущее признание соглашения о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, неисполненным;\n\n4) если иное не установлено подпунктом 5 настоящего пункта, при наступлении случая, указанного в подпункте 6 пункта 18 настоящей статьи, действие свидетельства аннулируется по решению налогового органа с 1-го числа месяца, на который приходится первая дата, по состоянию на которую соответствующая доля участия оказалась ниже 50 процентов;\n\n5) при наступлении по 31 декабря 2028 года включительно хотя бы одного случая, указанного в подпунктах 1 - 4 и 6 пункта 18 настоящей статьи, в отношении организации, имеющей свидетельство по основанию, указанному в подпункте 2 пункта 2 или подпункте 2 пункта 3 настоящей статьи, действие свидетельства аннулируется по решению налогового органа с даты начала действия такого свидетельства. При этом суммы акциза, исчисленные с даты начала действия аннулированного свидетельства организацией, заключившей соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, или организацией, получившей свидетельство по основанию, указанному в подпункте 2 пункта 3 настоящей статьи, и заключившей договор об оказании услуг по переработке этана в товары, являющиеся продукцией нефтехимии, с организацией, заключившей соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, при совершении операций, указанных в подпункте 39 пункта 1 статьи 182 настоящего Кодекса, и не уплаченные в связи с применением налоговых вычетов, указанных в пункте 32 статьи 200 настоящего Кодекса, а также суммы, возмещенные указанным организациям в связи с применением таких вычетов, подлежат уплате в бюджет соответствующей организацией, заключившей соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, до истечения месяца, следующего за месяцем, в котором наступил случай, явившийся основанием для аннулирования свидетельства. (В редакции  Федерального закона от 29.11.2024 № 416-ФЗ)\n\nВ случае утраты организацией свидетельства такая организация вправе обратиться в налоговый орган за выдачей дубликата.\n\nСостав и порядок представления сведений, указанных в настоящем пункте, утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, и федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса.\n\nдля организации, непосредственно осуществляющей переработку этана в товары, являющиеся продукцией нефтехимии, - замена средств измерений для определения количества этана, направленного на переработку, и (или) изменение мест их размещения, и (или) установка новых средств измерений;\n\nизменение наименования организации;\n\nизменение места нахождения организации;\n\nпрекращение права собственности на производственные мощности, указанные в свидетельстве, или права владения (пользования) ими на иных законных основаниях;\n\nвозникновение права собственности на производственные мощности, на которых будет осуществляться переработка этана в товары, являющиеся продукцией нефтехимии, или права владения (пользования) ими на иных законных основаниях.\n\nК указанному в настоящем пункте уведомлению должны быть приложены копии документов, подтверждающих наступление соответствующего обстоятельства.\n\nФорма уведомления и перечень видов документов, необходимых для подтверждения наступления соответствующих обстоятельств, утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение статьей - Федеральный закон от 15.10.2020 № 321-ФЗ)","article_title":"Статья 179.8. Свидетельство о регистрации лица, совершающего операции по переработке этана","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"04ef197fc8dc596d6648f7b9de108e5fa5fd9542afa1ca5443d4cd11bb64f7d9"},{"code_id":"NK_RF_2","article_number":"179.9","version_date":"2000-07-31","article_text":"1. Свидетельство о регистрации лица, совершающего операции по переработке сжиженных углеводородных газов (далее в настоящей статье - свидетельство), выдается организации, осуществляющей переработку СУГ, в том числе на основании договора об оказании такой организации услуг по переработке СУГ, в целях получения товаров, являющихся продукцией нефтехимии.\n\n2. Если иное не установлено пунктом 3 настоящей статьи, свидетельство выдается российской организации-заявителю на основании заявления, представленного в налоговый орган, при наличии у нее на праве собственности и (или) ином законном основании производственных мощностей, необходимых для переработки СУГ в товары, являющиеся продукцией нефтехимии, средств измерений для определения количества СУГ, направленного на переработку, и при выполнении хотя бы одного из следующих условий:\n\n1) в период с 1 января 2022 года организацией-заявителем введены в эксплуатацию новые производственные мощности по переработке СУГ в товары, являющиеся продукцией нефтехимии, проектной мощностью по сырью не менее 300 тысяч тонн СУГ в год либо не менее 600 тысяч тонн этана и СУГ в совокупности в год; (В редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\n2) организацией-заявителем до 1 января 2023 года заключено с федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса, соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии;\n\n3) при наличии у организации-заявителя взаимозависимого лица, осуществляющего деятельность, указанную в пункте 1 настоящей статьи, в субъекте Российской Федерации, где осуществляет такую деятельность организация-заявитель, и при наличии у такого взаимозависимого лица заключенного в соответствии с подпунктом 2 настоящего пункта соглашения о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, которым предусмотрен в период с 1 января 2022 года по 31 января 2027 года ввод в эксплуатацию объектов основных средств совокупной первоначальной стоимостью более 220 миллиардов рублей. (Дополнение подпунктом - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\n3. Вне зависимости от выполнения условий, установленных пунктом 2 настоящей статьи, свидетельство выдается также организации-заявителю при выполнении хотя бы одного из следующих требований:\n\n1) при наличии у организации-заявителя договора об оказании ей услуг по переработке СУГ в товары, являющиеся продукцией нефтехимии, заключенного с организацией, непосредственно осуществляющей указанную переработку\n\nи имеющей на праве собственности и (или) ином законном основании производственные мощности, необходимые для переработки СУГ в товары, являющиеся продукцией нефтехимии, средств измерений для определения количества СУГ, направленного на переработку, и при выполнении в отношении такой организации условия, указанного в подпункте 1 пункта 2 настоящей статьи;\n\n2) при наличии у организации-заявителя договора об оказании ей услуг по переработке СУГ в товары, являющиеся продукцией нефтехимии, заключенного с организацией, непосредственно осуществляющей указанную переработку и имеющей на праве собственности и (или) ином законном основании производственные мощности, необходимые для переработки СУГ в товары, являющиеся продукцией нефтехимии, средств измерений для определения количества СУГ, направленного на переработку, и при выполнении в отношении такой организации условия, указанного в подпункте 2 пункта 2 настоящей статьи, а также при условии, что доля прямого участия организации-заявителя в организации, с которой у нее заключен договор об оказании ей услуг по переработке СУГ в товары, являющиеся продукцией нефтехимии, и которая непосредственно осуществляет указанную переработку, составляет 50 процентов или более.\n\n4. Налоговый орган обязан выдать свидетельство или направить организации-заявителю уведомление об отказе в выдаче свидетельства с указанием причины отказа в срок не позднее пятнадцати дней со дня получения им заявления о выдаче свидетельства и предусмотренных настоящей статьей документов и сведений.\n\n5. Соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, заключается при условии, что совокупная первоначальная стоимость объектов основных средств, предусмотренных организацией-заявителем для включения в указанное соглашение и вводимых в эксплуатацию в период с 1 января 2022 года по 31 декабря 2027 года включительно, составляет не менее 65 миллиардов рублей (110 миллиардов рублей для организаций-заявителей, которые намереваются осуществлять налогообложение СУГ в порядке, установленном абзацем вторым пункта 12 статьи 193 настоящего Кодекса).\n\n6. К соглашениям о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, заключаемым в целях настоящей статьи, применяются требования, предусмотренные для соответствующих соглашений, заключаемых для целей статьи 1798 настоящего Кодекса.\n\nДля целей настоящей статьи после 1 января 2026 года не допускается внесение изменений в соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, за исключением изменения сроков реализации отдельных мероприятий, указанных в соглашении, но не более чем на шесть месяцев по сравнению со сроками реализации таких мероприятий, зафиксированными в соглашении о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, по состоянию на 1 января 2026 года. (В редакции  Федерального закона от 29.11.2024 № 416-ФЗ)\n\n7. Для целей настоящей статьи федеральный орган исполнительной власти, осуществляющий функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса, заключает (расторгает) соглашения о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, вносит изменения в указанные соглашения, осуществляет проверку их выполнения в порядке, установленном статьей 1798 настоящего Кодекса.\n\n8. Соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, считается неисполненным при наступлении хотя бы одного из следующих обстоятельств:\n\n1) соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, расторгнуто по основанию, указанному в пункте 7 статьи 1798 настоящего Кодекса;\n\n2) принято решение о реорганизации организации, заключившей соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии (за исключением реорганизации в форме присоединения к такой организации других юридических лиц или в форме выделения из такой организации юридических лиц без передачи им мощностей по производству товаров, являющихся продукцией нефтехимии), или решение о ликвидации такой организации в период с 1 января 2022 года по 31 декабря 2027 года включительно;\n\n3) совокупная первоначальная стоимость объектов основных средств, включенных в соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, и введенных в эксплуатацию в период с 1 января 2022 года по 31 декабря 2027 года включительно, оказалась менее 65 миллиардов рублей (110 миллиардов рублей для организации, которая осуществляет налогообложение СУГ в порядке, установленном абзацем вторым пункта 12 статьи 193 настоящего Кодекса, или 220 миллиардов рублей для организации, заключившей соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, при условии, что такое соглашение служило основанием для получения свидетельства лицом, являющимся взаимозависимым по отношению к такой организации, в соответствии с подпунктом 3 пункта 2 настоящей статьи). (В редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\nДля целей настоящего подпункта первоначальная стоимость (увеличение первоначальной стоимости) основного средства определяется в порядке, установленном пунктами 1 и 2 статьи 257 настоящего Кодекса. В случае, если в сделках, учитываемых при формировании первоначальной стоимости основного средства, применялись цены, не признаваемые рыночными, первоначальная стоимость такого основного средства для целей настоящего подпункта определяется с использованием цен указанных сделок, принимаемых для целей налогообложения, в порядке и с применением методов, которые установлены главой 143 настоящего Кодекса. В целях настоящего абзаца рыночная цена определяется с учетом положений статьи 1053 настоящего Кодекса; (В редакции  Федерального закона от 29.11.2024 № 416-ФЗ)\n\n4) в период с 1 января 2022 года по 31 декабря 2027 года включительно прекращено право собственности организации (за исключением гибели или уничтожения имущества) в отношении объектов основных средств, предусмотренных соглашением о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии;\n\n5) соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, явилось основанием для выдачи свидетельства о регистрации лица, совершающего операции по переработке сжиженных углеводородных газов, в соответствии с подпунктом 3 пункта 2 настоящей статьи при условии, что организация, заключившая такое соглашение, имеет свидетельство о регистрации лица, совершающего операции по переработке этана, и свидетельство о регистрации лица, совершающего операции по переработке сжиженных углеводородных газов. (Дополнение подпунктом - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\n9. Для получения свидетельства организация-заявитель представляет в налоговый орган заявление о выдаче свидетельства, а также один из следующих комплектов документов:\n\n1) перечень производственных мощностей по переработке СУГ в товары, являющиеся продукцией нефтехимии, с приложением копий документов, подтверждающих право собственности на указанные мощности и (или) право владения (пользования) ими на ином законном основании, перечень средств измерений (с указанием мест их размещения) для определения количества СУГ, направленного на переработку, а также документы и сведения, подтверждающие выполнение в отношении организации-заявителя хотя бы одного из условий, указанных в подпунктах 1 - 3 пункта 2 настоящей статьи; (В редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\n2) заверенная организацией-заявителем копия договора об оказании услуг по переработке СУГ в товары, являющиеся продукцией нефтехимии, заключенного с организацией, непосредственно осуществляющей переработку СУГ в товары, являющиеся продукцией нефтехимии, и имеющей свидетельство, с отметкой налогового органа по месту нахождения указанной организации. Отметка на договоре об оказании услуг по переработке СУГ в товары, являющиеся продукцией нефтехимии, проставляется уполномоченным лицом налогового органа при представлении в налоговый орган по месту нахождения организации, непосредственно осуществляющей переработку СУГ в товары, являющиеся продукцией нефтехимии, и имеющей соответствующее свидетельство, копии указанного договора при условии наличия у этой организации производственных мощностей по переработке СУГ в товары, являющиеся продукцией нефтехимии, средств измерений для определения количества СУГ, направленного на переработку.\n\n10. При подаче заявления о выдаче свидетельства организация-заявитель вправе не представлять документы, ранее представленные в налоговый орган в соответствии с положениями настоящей статьи.\n\n11. Действие свидетельства начинается с первого дня налогового периода, в котором организацией-заявителем представлены заявление и предусмотренные настоящей статьей документы, на основании которых выдано свидетельство.\n\n12. Налоговый орган отказывает в выдаче свидетельства в следующих случаях:\n\n1) заявление о выдаче свидетельства представлено не в соответствии с установленной формой;\n\n2) организацией-заявителем не представлены или представлены не в полном объеме необходимые для получения свидетельства документы;\n\n3) в представленных организацией-заявителем документах содержится недостоверная информация;\n\n4) в отношении организации-заявителя, получающей свидетельство по основанию, указанному в подпункте 2 пункта 3 настоящей статьи, по состоянию на дату подачи заявления доля прямого участия организации-заявителя в организации, с которой у нее заключен договор об оказании ей услуг по переработке СУГ в товары, являющиеся продукцией нефтехимии, и которая непосредственно осуществляет указанную переработку, составляет менее 50 процентов.\n\n13. В свидетельстве указываются:\n\n1) наименование налогового органа, выдавшего свидетельство;\n\n2) полное и сокращенное наименования организации-заявителя, место нахождения организации-заявителя и адрес осуществления организацией-заявителем деятельности (место фактической деятельности), указанной в пункте 1 настоящей статьи;\n\n3) идентификационный номер налогоплательщика (ИНН);\n\n4) реквизиты документов (при наличии), подтверждающих право собственности организации-заявителя на производственные мощности по переработке СУГ в товары, являющиеся продукцией нефтехимии, (или) право владения (пользования) ими на ином законном основании;\n\n5) реквизиты договора об оказании организации-заявителю услуг по переработке СУГ в товары, являющиеся продукцией нефтехимии (при наличии);\n\n51) реквизиты соглашения о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, заключенного лицом, являющимся взаимозависимым по отношению к организации-заявителю (в случае, если свидетельство выдается на основании подпункта 3 пункта 2 настоящей статьи); (Дополнение подпунктом - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\n6) регистрационный номер свидетельства и дата его выдачи;\n\n7) места размещения средств измерений для определения количества СУГ, направленного на переработку в товары, являющиеся продукцией нефтехимии.\n\n14. Форма свидетельства, форма заявления о выдаче свидетельства, формы решений налогового органа о выдаче (об отказе в выдаче) свидетельства, о приостановлении (возобновлении) его действия, о неполном устранении нарушений, повлекших за собой приостановление действия свидетельства, об аннулировании свидетельства и административный регламент предоставления государственной услуги по выдаче свидетельства утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n15. Налоговые органы приостанавливают действие свидетельства в следующих случаях:\n\n1) невыполнение организацией положений законодательства о налогах и сборах в части исчисления и уплаты акцизов;\n\n2) приостановление действия свидетельства организации, с которой заключен договор об оказании услуг по переработке СУГ в товары, являющиеся продукцией нефтехимии. В случае наличия у налогоплательщика нескольких свидетельств, полученных в соответствии с пунктом 3 настоящей статьи, налоговые органы приостанавливают действие свидетельства, полученного в связи с наличием у налогоплательщика договора об оказании ему услуг по переработке СУГ в товары, являющиеся продукцией нефтехимии, заключенного с непосредственно осуществляющей указанную переработку организацией, действие свидетельства которой было приостановлено;\n\n3) отсутствие средств измерений для определения количества СУГ, направленного на переработку, или нахождение таких средств измерений в состоянии, препятствующем определению количества СУГ, направляемого на переработку.\n\n16. Действие свидетельства приостанавливается по решению налогового органа со дня установления факта наступления хотя бы одного случая, предусмотренного подпунктами 1 - 3 пункта 15 настоящей статьи.\n\n17. В случае приостановления действия свидетельства налоговый орган в своем решении обязан установить срок для устранения нарушений, повлекших за собой приостановление действия свидетельства. Указанный срок не может превышать шесть месяцев с даты вступления в силу решения налогового органа.\n\nОрганизация, действие свидетельства которой приостановлено, обязана уведомить в письменной форме налоговый орган, выдавший свидетельство, об устранении нарушений, повлекших за собой приостановление действия свидетельства. Налоговый орган, выдавший свидетельство, в течение десяти рабочих дней со дня получения такого уведомления принимает решение о возобновлении действия свидетельства или о неполном устранении нарушений, повлекших за собой приостановление действия свидетельства.\n\n18. Налоговые органы аннулируют свидетельство в следующих случаях:\n\n1) представление организацией заявления об аннулировании свидетельства, составленного в произвольной форме;\n\n2) истечение срока для устранения нарушений, установленного налоговым органом, если организация, действие свидетельства которой приостановлено, не устранила в указанный срок все нарушения, повлекшие за собой приостановление действия свидетельства;\n\n3) изменение адреса осуществления деятельности (места фактической деятельности), указанной в пункте 1 настоящей статьи;\n\n4) прекращение права собственности на все производственные мощности, указанные в свидетельстве, или права владения (пользования) ими на ином законном основании либо прекращение действия договора об оказании услуг по переработке СУГ в товары, являющиеся продукцией нефтехимии, или аннулирование свидетельства организации, с которой заключен договор об оказании услуг по переработке СУГ в товары, являющиеся продукцией нефтехимии;\n\n5) наступление обстоятельства, при котором соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, считается неисполненным (в том числе при наступлении указанного обстоятельства для лица, являющегося взаимозависимым по отношению к организации, свидетельство которой аннулируется, в случае, если такое свидетельство получено на основании подпункта 3 пункта 2 настоящей статьи); (В редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\n6) для организации, получившей свидетельство по основанию, указанному в подпункте 2 пункта 3 настоящей статьи, - если доля прямого участия такой организации в организации, с которой такой организацией заключен договор об оказании ей услуг по переработке СУГ в товары, являющиеся продукцией нефтехимии, и которая непосредственно осуществляет указанную переработку, оказалась менее 50 процентов.\n\n19. Аннулирование свидетельства налоговыми органами по основаниям, предусмотренным пунктом 18 настоящей статьи, осуществляется с учетом следующих особенностей:\n\n1) если иное не установлено подпунктом 5 настоящего пункта, при наступлении случая, указанного в подпункте 1 пункта 18 настоящей статьи, действие свидетельства аннулируется со дня, указанного в заявлении;\n\n2) если иное не установлено подпунктом 5 настоящего пункта, при наступлении случаев, указанных в подпунктах 2 - 4 пункта 18 настоящей статьи, действие свидетельства аннулируется по решению налогового органа со дня наступления соответствующих обстоятельств;\n\n3) при наступлении случая, указанного в подпункте 5 пункта 18 настоящей статьи, действие свидетельства аннулируется по решению налогового органа с даты начала действия свидетельства. При этом суммы акциза, исчисленные с даты начала действия аннулированного свидетельства организацией, заключившей соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, которое признано неисполненным, и (или) организацией (организациями), получившей свидетельство по основанию, указанному в подпункте 2 пункта 3 настоящей статьи, и заключившей договор об оказании услуг по переработке СУГ в товары, являющиеся продукцией нефтехимии, с организацией, заключившей соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, которое признано неисполненным, при совершении операций, указанных в подпункте 40 пункта 1 статьи 182 настоящего Кодекса, и не уплаченные в связи с применением налоговых вычетов, указанных в пункте 33 статьи 200 настоящего Кодекса, а также суммы, возмещенные указанным организациям в связи с применением таких вычетов, подлежат уплате в бюджет организацией, заключившей соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, которое признано неисполненным, до истечения месяца, следующего за месяцем, в котором наступило обстоятельство, влекущее признание неисполненным соглашения о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии;\n\n4) если иное не установлено подпунктом 5 настоящего пункта, при наступлении случая, указанного в подпункте 6 пункта 18 настоящей статьи, действие свидетельства аннулируется по решению налогового органа с 1-го числа месяца, на который приходится первая дата, по состоянию на которую соответствующая доля участия оказалась ниже 50 процентов;\n\n5) при наступлении по 31 декабря 2027 года включительно хотя бы одного случая, указанного в подпунктах 1 - 4 и 6 пункта 18 настоящей статьи, в отношении организации, имеющей свидетельство по основанию, указанному в подпункте 2 пункта 2 или подпункте 2 пункта 3 настоящей статьи, действие свидетельства аннулируется по решению налогового органа с даты начала действия такого свидетельства. При этом суммы акциза, исчисленные с даты начала действия аннулированного свидетельства организацией, заключившей соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией не\n\nфтехимии, или организацией, получившей свидетельство по основанию, указанному в подпункте 2 пункта 3 настоящей статьи, и заключившей договор об оказании услуг по переработке СУГ в товары, являющиеся продукцией нефтехимии, с организацией, заключившей соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, при совершении операций, указанных в подпункте 40 пункта 1 статьи 182 настоящего Кодекса, и не уплаченные в связи с применением налоговых вычетов, указанных в пункте 33 статьи 200 настоящего Кодекса, а также суммы, возмещенные указанным организациям в связи с применением таких вычетов, подлежат уплате в бюджет соответствующей организацией, заключившей соглашение о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, до истечения месяца, следующего за месяцем, в котором наступил случай, явившийся основанием для аннулирования свидетельства.\n\n20. В случае аннулирования свидетельства организация вправе подать заявление о получении нового свидетельства.\n\nВ случае утраты организацией свидетельства такая организация вправе обратиться в налоговый орган за выдачей дубликата.\n\n21. Налоговый орган, выдавший (выдающий) свидетельство, обязан уведомить в письменной форме организацию об отказе в выдаче свидетельства, о приостановлении его действия, о неполном устранении нарушений, повлекших за собой приостановление действия свидетельства, о возобновлении действия свидетельства или об аннулировании свидетельства в трехдневный срок со дня принятия соответствующего решения.\n\n22. Федеральный орган исполнительной власти, осуществляющий функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса, направляет в налоговые органы информацию о соглашениях о создании новых мощностей и (или) модернизации (реконструкции) действующих мощностей по производству товаров, являющихся продукцией нефтехимии, по перечню, в составе и порядке, которые предусмотрены пунктом 22 статьи 1798 настоящего Кодекса.\n\n23. Организация, получившая свидетельство, одновременно с налоговой декларацией по акцизам (в сроки, предусмотренные для представления в налоговые органы налоговой декларации за налоговый период) обязана направить в налоговый орган уведомление о наступлении в течение налогового периода, за который представляется указанная налоговая декларация, следующих обстоятельств, влекущих изменение сведений, указанных в свидетельстве такой организации:\n\nдля организации, непосредственно осуществляющей переработку СУГ в товары, являющиеся продукцией нефтехимии, - замена средств измерений для определения количества СУГ, направленного на переработку, и (или) изменение мест их размещения, и (или) установка новых средств измерений;\n\nизменение наименования организации;\n\nизменение места нахождения организации;\n\nпрекращение права собственности на производственные мощности, указанные в свидетельстве (права владения (пользования) ими на иных законных основаниях);\n\nвозникновение права собственности на производственные мощности, на которых будет осуществляться переработка СУГ в товары, являющиеся продукцией нефтехимии (права владения (пользования) ими на иных законных основаниях).\n\nК указанному в настоящем пункте уведомлению должны быть приложены копии документов, подтверждающие наступление соответствующих обстоятельств.\n\nФорма уведомления и перечень видов документов, необходимых для подтверждения наступления соответствующих обстоятельств, утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение статьей - Федеральный закон от 15.10.2020 № 321-ФЗ)","article_title":"Статья 179.9. Свидетельство о регистрации лица, совершающего операции по переработке сжиженных углеводородных газов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ca5bbbec172d76389e05b1258aabce8ac626b495c2ddad2de8a7558c2d71d621"},{"code_id":"NK_RF_2","article_number":"180","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 29.12.2000 № 166-ФЗ)\n\nУказанное лицо имеет все права и исполняет обязанности налогоплательщика, предусмотренные настоящим Кодексом, в отношении указанной суммы акциза. (В редакции Федерального закона от 29.12.2000 № 166-ФЗ)\n\nУказанное лицо обязано не позднее дня осуществления первой операции, признаваемой объектом налогообложения в соответствии с настоящей главой, известить налоговый орган об исполнении им обязанностей налогоплательщика в рамках договора простого товарищества (договора о совместной деятельности). (В редакции Федерального закона от 29.12.2000 № 166-ФЗ)","article_title":"Статья 180. Особенности исполнения обязанностей налогоплательщика в рамках договора простого товарищества (договора о совместной деятельности)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"59e5a266a2f0ce57c55cecad4889ae9c0d20d355d72c9795528b9f04fa03c982"}]$law7v024$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text)) insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at) select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
    commit;
